import{n as e}from"./rolldown-runtime-hePW80VL.js";var t=e({kernel:()=>ne,scenes:()=>re}),n=e=>Array.isArray(e)?e.join(` `):e,r=(e,t)=>({da:n(e),en:n(t)}),ee=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),i=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},te=(e,t,n)=>({when:e,event:t,sign:n}),a=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),ne={id:`hunt-the-wrong-beast`,titles:[r(`Det forkerte uhyre`,`The Wrong Beast`),r(`Nordenvind over {place}`,`North Wind over {place}`),r(`Hornknappen i den dødes hånd`,`The Horn Button in the Dead Man’s Hand`)],missions:[`monster-hunt`,`wilderness`],foes:`beasts`,roles:{npc1:r(`et barn af den døde fårebonde, der nu ejer den sidste gård ved drivvejen`,`a child of the dead sheep farmer, now the owner of the last farm on the drove road`),npc2:r(`en fårehyrde, der har vogtet får for alle gårdene ved drivvejen og nu kun arbejder for {villain}`,`a shepherd who has tended the sheep of every farm on the drove road and now works only for {villain}`),npc3:r(`en graver, der så liget, før kisten blev lukket`,`a gravedigger who saw the body before the coffin was closed`),villain:r(`en velhavende fåreavler, der har købt gård efter gård ved drivvejen`,`a wealthy sheep farmer who has bought farm after farm along the drove road`)},hook:r(`{npc1} kommer hen til heltene ved graven med dusøropslaget i hånden og beder dem gå ind i {place} og dræbe {boss}, før flere dør ved drivvejen; {npc1} lægger selv faderens sølvspænde oven i dusøren.`,`{npc1} comes to the heroes at the graveside with the bounty notice in hand and asks them to go into {place} and kill {boss} before anyone else on the drove road dies; {npc1} will add their father’s silver buckle to the bounty.`),people:{npc1:{wants:r(`Vil have {boss} dræbt og vil aldrig sælge faderens gård, uanset hvad {villain} byder.`,`Wants {boss} killed and will never sell their father’s farm, whatever {villain} offers.`),secret:r(`Skændtes med faderen den aften, han døde, fordi {npc1} ville sælge til {villain}, og har ikke fortalt det til nogen.`,`Quarrelled with their father on the evening he died, because {npc1} wanted to sell to {villain}, and has told no one.`)},npc2:{wants:r(`Vil blive ved med at arbejde for {villain} og slippe for galgen.`,`Wants to keep working for {villain} and stay off the gallows.`),secret:r(`Har slået naboernes får ihjel om natten efter {villain}s ordre og slæbt dem ud i kanten af {place}, men havde intet at gøre med {npc1}s fars død.`,`Has killed the neighbours’ sheep by night on {villain}’s orders and dragged them to the edge of {place}, but had nothing to do with the death of {npc1}’s father.`)},npc3:{wants:r(`Vil have sandheden frem uden at skulle stå alene med den.`,`Wants the truth to come out without having to carry it alone.`),secret:r(`Har gemt knappen fra den dødes hånd i tre dage og tiet, fordi {villain} har betalt både kisten og gravøllet.`,`Has kept the button from the dead man’s hand for three days and said nothing, because {villain} paid for both the coffin and the funeral feast.`)}},premise:r([`I årevis har {boss} og nogle {foe} holdt til dybt inde i {place}, og så længe ingen fra {town} gik derind, kom de aldrig ud.`,`For en måned siden satte {villain}, egnens rigeste fåreavler, ild til deres gamle hule, så de blev set ved gårdene langs drivvejen om natten; siden er naboernes får fundet døde i kanten af {place}, og den ene bonde efter den anden har solgt sin gård billigt til {villain}.`,`Da {npc1}s far nægtede at sælge og fulgte {villain}s vogn op til det gamle stenbrud, slog {villain} ham ned bagfra og lod ham ligge i kanten af {place}, og nu giver hele {town} {boss} skylden.`,`I aften, når vinden vender mod nord, vil {villain} sætte ild til risbunkerne ved {boss}s nye hule i stenbruddet oppe i {place} og drive {boss} og de andre ned ad drivvejen mod {npc1}s gård, den sidste, der ikke er solgt.`],[`For years {boss} and some {foe} have kept to the depths of {place}, and as long as no one from {town} went in, they never came out.`,`A month ago {villain}, the richest sheep farmer in the district, set fire to their old den so that they were seen at night near the farms along the drove road. Since then the neighbours’ sheep have been found dead at the edge of {place}, and one farmer after another has sold out cheaply to {villain}.`,`When {npc1}’s father refused to sell and followed {villain}’s cart up to the old quarry, {villain} struck him down from behind and left him at the edge of {place}, and now all of {town} blames {boss}.`,`Tonight, when the wind turns north, {villain} means to set fire to the brush piled at {boss}’s new den in the quarry high in {place} and drive {boss} and the others down the drove road onto {npc1}’s farm, the last one not yet sold.`]),goal:r(`Find ud af, hvem der i virkeligheden dræbte {npc1}s far, og stands {villain} ved hulen i stenbruddet i {place}, før vinden vender mod nord ved mørkets frembrud.`,`Find out who really killed {npc1}’s father, and stop {villain} at the quarry den in {place} before the wind turns north at nightfall.`),objective:{target:r(`{boss}, som hele {town} giver skylden, og hulen i det gamle stenbrud, hvor {boss} og nogle {foe} har søgt ly`,`{boss}, whom all of {town} blames, and the den in the old quarry where {boss} and some {foe} have taken refuge`),state:r(`Efter en måned på flugt angriber {boss} og de andre alt, der kommer nær hulen. Ved mundingen står seks risbunker, gennemvædet af tjære, og på kanten af stenbruddet venter {villain} med en fakkel på nordenvinden.`,`After a month on the run, {boss} and the others attack anything that comes near the den. Six brush piles soaked in tar stand at its mouth, and on the quarry rim {villain} waits with a torch for the north wind.`),resolution:r([`Hold ilden fra risbunkerne, eller vend {boss} og de andre væk fra drivvejen, og bring {villain} til {town} med beviserne.`,`Om {boss} skal dø eller have fred i hulen, er heltenes valg: Dusøren bliver betalt for et dødt uhyre, men kun sandheden redder {npc1}s gård.`],[`Keep the fire from the brush piles, or turn {boss} and the others away from the drove road, and bring {villain} to {town} with the proof.`,`Whether {boss} dies or is left in peace in the den is the heroes’ choice: the bounty is paid for a dead beast, but only the truth saves {npc1}’s farm.`])},villain:{want:r(`At eje hver eneste mark ved drivvejen, fra {town} op til {place}, uden at nogen nogensinde spørger, hvordan {villain} fik dem.`,`To own every field along the drove road, from {town} up to {place}, without anyone ever asking how {villain} came by them.`),plan:r([`Først satte {villain} ild til den gamle hule i {place}, så {boss} og nogle {foe} blev set ved gårdene om natten, og lod {npc2} slå naboernes får ihjel og slæbe dem ud i kanten af {place}.`,`Da {npc1}s far nægtede at sælge og så for meget ved stenbruddet, slog {villain} ham ned bagfra; nu betaler {villain} både begravelsen og dusøren på {boss}.`,`Ved mørkets frembrud, når vinden vender mod nord, tænder {villain} selv risbunkerne ved hulen i stenbruddet og driver {boss} og de andre ned ad drivvejen mod {npc1}s gård, den sidste, der ikke er solgt.`],[`First, {villain} set fire to the old den in {place} so that {boss} and some {foe} were seen near the farms at night, and had {npc2} kill the neighbours’ sheep and drag them to the edge of {place}.`,`When {npc1}’s father refused to sell and saw too much at the quarry, {villain} struck him down from behind; now {villain} is paying for both the funeral and the bounty on {boss}.`,`At nightfall, when the wind turns north, {villain} will light the brush piles at the quarry den in person and drive {boss} and the others down the drove road onto {npc1}’s farm, the last one not yet sold.`]),weakness:r([`{villain} stoler ikke på nogen og må selv tænde ilden, alene på kanten af stenbruddet.`,`Og den hornknap, der mangler i {villain}s frakke, ligger hos graveren: Stillet over for den kan {villain} ikke længere skyde skylden på {boss}.`],[`{villain} trusts no one and must light the fire alone, on the quarry rim.`,`And the horn button missing from {villain}’s coat is in the gravedigger’s keeping: faced with it, {villain} can no longer lay the blame on {boss}.`])},stakes:r(`Brænder risbunkerne, vælter {boss} og nogle {foe} ned over {npc1}s gård i nat: Folk kan dø, {villain} køber den sidste gård ved drivvejen, og mordet på {npc1}s far bliver for altid lagt på {boss}.`,`If the brush piles burn, {boss} and some {foe} come down on {npc1}’s farm tonight: people may die, {villain} buys the last farm on the drove road, and the murder of {npc1}’s father is laid on {boss} for good.`),clock:{start:r(`Morgen. {npc1}s far bliver begravet i {town} i dag, og de vejrkloge siger, at vinden vender mod nord ved mørkets frembrud, om ni timer.`,`Morning. {npc1}’s father is being buried in {town} today, and those who know the weather say the wind will turn north at nightfall, nine hours from now.`),ticks:[te(r(`Efter 2 timer`,`After 2 hours`),r(`{villain} forlader gravøllet og rider op ad drivvejen, og {npc2} driver alle {villain}s får op på den høje mark, væk fra vejen.`,`{villain} leaves the funeral feast and rides up the drove road, and {npc2} drives all of {villain}’s sheep up to the high field, away from the road.`),r(`{villain}s plads ved bordet står tom, og en lang række får med {villain}s brændemærke bliver drevet op ad bakken.`,`{villain}’s seat at the table stands empty, and a long line of sheep bearing {villain}’s brand is driven up the hill.`)),te(r(`Efter 6 timer`,`After 6 hours`),r(`{villain} når stenbruddet og hælder den sidste tjære over risbunkerne, og nogle {foe}, som uroen har drevet ud af hulen, strejfer ned gennem kløften.`,`{villain} reaches the quarry and pours the last of the tar over the brush piles, and some {foe}, driven out of the den by the disturbance, roam down through the gorge.`),r(`En skarp lugt af tjære driver ned ad kløften, og nogle {foe} viser sig ved højlys dag nær drivvejen.`,`A sharp smell of tar drifts down the gorge, and some {foe} show themselves in broad daylight near the drove road.`)),te(r(`Efter 9 timer (ved mørkets frembrud)`,`After 9 hours (at nightfall)`),r(`Vinden vender mod nord, {villain} sætter ild til risbunkerne, og {boss} og nogle {foe} flygter ned ad drivvejen mod {npc1}s gård.`,`The wind turns north, {villain} sets the brush piles alight, and {boss} and some {foe} flee down the drove road toward {npc1}’s farm.`),r(`Røg står op over {place}, og et rødt skær lyser i kløften over drivvejen.`,`Smoke rises over {place}, and a red glow lights the gorge above the drove road.`))],deadline:r(`Efter 9 timer, ved mørkets frembrud, er det for sent: Risbunkerne brænder, {boss} og nogle {foe} vælter ned ad drivvejen mod {npc1}s gård, og ingen i {town} vil nogensinde tro, at det var andet end uhyrets værk.`,`After 9 hours, at nightfall, it is too late: the brush piles burn, {boss} and some {foe} pour down the drove road toward {npc1}’s farm, and no one in {town} will ever believe it was anything but the beast’s doing.`)},clues:{who:[i(`town`,r(`{npc1} viser heltene et brev fra {villain} til faderen, skrevet dagen før han døde.`,`{npc1} shows the heroes a letter from {villain} to {npc1}’s father, written the day before he died.`),r(`{villain} pressede på for at få gården, med en trussel klædt ud som et naboråd.`,`{villain} was pressing for the farm, with a threat dressed up as neighbourly advice.`),ee([`Kære nabo,`,`jeg byder dig igen tre hundrede sølv for gården, og jeg byder ikke en fjerde gang.`,`Drivvejen er ikke noget sted for stædige folk længere. Sælg, før {place} bestemmer for dig.`,`– {villain}`],[`Dear neighbour,`,`once more I offer you three hundred silver for the farm, and I will not offer a fourth time.`,`The drove road is no place for stubborn folk any more. Sell before {place} decides for you.`,`— {villain}`])),i(`town`,r(`På porten til hver af de tomme gårde ved drivvejen sidder et opslag om salg til {villain}, og hvert opslag er dateret få dage efter den nat, da fårene i folden blev fundet døde.`,`Nailed to the gate of every empty farm on the drove road is a notice of sale to {villain}, each one dated a few days after the night the sheep in the fold were found dead.`),r(`Hver gang der dør får, sælger en bonde, og altid til {villain}.`,`Every time sheep die, a farmer sells, and always to {villain}.`),ee([`Gården er købt af {villain} for 110 sølv den 12. i høstmåneden,`,`tre dage efter at uhyret fra {place} slog fårene i folden ihjel.`,`Familien er flyttet til {town}. Uvedkommende må ikke betræde jorden.`],[`This farm was bought by {villain} for 110 silver on the 12th of the harvest month,`,`three days after the beast from {place} killed the sheep in the fold.`,`The family has moved to {town}. No trespassing.`])),i(`town`,r(`{npc3}, graveren, så liget, før kisten blev lukket: Der var kun ét sår, et slag i baghovedet, og i den knyttede hånd sad en hornknap, skåret med to krydsede hyrdestave.`,`{npc3}, the gravedigger, saw the body before the coffin was closed: there was only one wound, a blow to the back of the head, and clenched in the dead man’s hand was a horn button carved with two crossed crooks.`),r(`Et menneske slog den døde ned bagfra, og to krydsede hyrdestave er {villain}s brændemærke, det samme som på {villain}s får og frakkeknapper.`,`Someone struck the dead man down from behind, and two crossed crooks are {villain}’s brand, the same as on {villain}’s sheep and coat buttons.`)),i(`site`,r(`I asken i den brændte hule ligger bunden af en tjæretønde, brændemærket med to krydsede hyrdestave.`,`In the ashes of the burnt den lies the bottom of a tar barrel, branded with two crossed crooks.`),r(`Ilden, der jog {boss} ud af den gamle hule, blev tændt med {villain}s tjære.`,`The fire that drove {boss} out of the old den was lit with {villain}’s tar.`))],where:[i(`site`,r(`Fra den brændte hule fører et bredt bælte af nedtrådt krat og knækkede grene op ad skråningen mod det gamle stenbrud.`,`From the burnt den a broad swathe of trampled scrub and broken branches leads up the slope toward the old quarry.`),r(`{boss} flygtede fra ilden og har fundet en ny hule i stenbruddet.`,`{boss} fled the fire and has found a new den in the quarry.`)),i(`site`,r(`I kløften fører friske dryp af tjære og hjulspor efter en trækvogn op mod stenbruddet, og stien er kantet af nyhuggede stubbe, hvor krattet er ryddet.`,`In the gorge, fresh drips of tar and the ruts of a handcart lead up toward the quarry, and the path is lined with freshly cut stumps where the scrub has been cleared.`),r(`Nogen har for nylig kørt tjære og ris op til hulen i stenbruddet og gør klar til en ild dér.`,`Someone has recently hauled tar and brushwood up to the quarry den and is getting a fire ready there.`)),i(`town`,r(`I {npc2}s frakke ligger en seddel med {villain}s ordrer.`,`In {npc2}’s coat is a note with {villain}’s orders.`),r(`Hulen ligger i stenbruddet, og {villain} vil tænde ilden dér, når vinden vender mod nord.`,`The den is in the quarry, and {villain} means to light the fire there when the wind turns north.`),ee([`Hug ris i kløften, og stabl det ved hulen i stenbruddet. Kør de seks tjæretønder derop om dagen, mens hulen er stille.`,`Når vinden vender mod nord: alle mine får op på den høje mark, og hold dig væk fra drivvejen.`,`Brænd denne seddel. – {villain}`],[`Cut brush in the gorge and stack it at the den in the quarry. Haul the six tar barrels up there by day, while the den is quiet.`,`When the wind turns north: all my sheep up to the high field, and keep away from the drove road.`,`Burn this note. — {villain}`])),i(`town`,r(`{npc1} så faderen gå op mod det gamle stenbrud i skumringen den aften, han døde, efter en vogn, der kørte uden lys.`,`{npc1} saw their father go up toward the old quarry at dusk on the evening he died, following a cart that showed no light.`),r(`Der foregår noget ved stenbruddet, som faderen ikke måtte se.`,`Something is going on at the quarry that the dead farmer was not meant to see.`))]},endings:{success:r(`Ilden når aldrig at brænde, og {villain} bliver ført ind i {town} med hornknappen og sedlen til {npc2} som bevis. Rådet erklærer salgene ved drivvejen ugyldige, bønderne flytter hjem, og {npc1} giver heltene faderens sølvspænde, som lovet; nu spørger byen heltene, hvad der skal ske med {place}.`,`The fire never takes hold, and {villain} is brought into {town} with the horn button and the note to {npc2} as proof. The council declares the sales along the drove road void, the farmers move back, and {npc1} gives the heroes the dead farmer’s silver buckle, as promised; now the town asks the heroes what is to become of {place}.`),partial:r(`Heltene standser ilden eller får folkene på {npc1}s gård i sikkerhed, men {villain} slipper væk i mørket, eller beviserne holder ikke for rådet. Salgene står ved magt, {npc1}s gård ligger som en ø midt i {villain}s jord, og halvdelen af {town} kræver stadig en ny jagt i {place}.`,`The heroes stop the fire or get the household at {npc1}’s farm to safety, but {villain} slips away in the dark, or the proof does not hold up before the council. The sales stand, {npc1}’s farm is an island in {villain}’s land, and half of {town} still demands a new hunt in {place}.`),failure:r(`Ved mørkets frembrud brænder risbunkerne, og {boss} og nogle {foe} vælter ned ad drivvejen over {npc1}s gård. Byens jægere dræber, hvad de kan finde i {place}, {villain} bliver hyldet for at have betalt dusøren, og inden et år græsser {villain}s får på hver eneste mark ved drivvejen.`,`At nightfall the brush piles burn, and {boss} and some {foe} pour down the drove road onto {npc1}’s farm. The town’s hunters kill whatever they can find in {place}, {villain} is praised for paying the bounty, and within a year {villain}’s sheep graze every field along the drove road.`)}},re={opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc3`,`villain`],title:r(`Dusøren ved graven`,`The Bounty at the Graveside`),summary:r([`Om morgenen bliver {npc1}s far begravet på kirkegården i {town}, og {npc1} kommer hen til heltene ved graven med dusøropslaget i hånden og beder dem dræbe {boss} i {place}, før flere dør ved drivvejen.`,`{villain}, egnens rigeste fåreavler, har betalt både kisten, gravøllet og dusøren og trykker alle i hånden, men kigger igen og igen op mod vejrhanen på kirketårnet.`,`Byen kan give flere svar, før heltene går, men hver omvej koster tid, og de vejrkloge siger, at vinden vender mod nord ved mørkets frembrud.`],[`In the morning {npc1}’s father is buried in the churchyard of {town}, and {npc1} comes to the heroes at the graveside with the bounty notice in hand and asks them to kill {boss} in {place} before anyone else on the drove road dies.`,`{villain}, the richest sheep farmer in the district, has paid for the coffin, the funeral feast and the bounty and shakes everyone’s hand, but keeps glancing up at the weathervane on the church tower.`,`The town can give more answers before the heroes go, but every detour costs time, and those who know the weather say the wind will turn north at nightfall.`]),readAloud:r([`Regnen er lige holdt op, og kirkegården lugter af våd jord.`,`Seks bønder sænker en enkel kiste i graven, og ved gravens hoved står en velklædt skikkelse i en frakke med blanke hornknapper og holder hatten mod brystet.`,`På lågen ind til kirkegården er der slået et opslag op, og blækket er løbet en smule i regnen.`],[`The rain has just stopped, and the churchyard smells of wet earth.`,`Six farmers lower a plain coffin into the grave, and at its head stands a well-dressed figure in a coat with polished horn buttons, hat held to their chest.`,`A notice has been nailed to the churchyard gate, and its ink has run a little in the rain.`]),details:[r(`{npc1} fortæller, at faderen gik op mod det gamle stenbrud i skumringen for tre dage siden, efter en vogn, der kørte uden lys, og blev fundet næste morgen i kanten af {place}. {npc1} har også det brev, {villain} skrev til faderen dagen før, og viser det gerne frem; i byen bliver det læst som et godt naboråd.`,`{npc1} tells how their father went up toward the old quarry at dusk three days ago, following a cart that showed no light, and was found the next morning at the edge of {place}. {npc1} also has the letter {villain} wrote to him the day before and is glad to show it; in town it is read as good neighbourly advice.`),r(`Opslaget på lågen lover hundrede sølv til den, der dræber {boss} i {place}, betalt af {villain}. {villain} er venligheden selv, fortæller heltene, at {boss} holder til ved den brændte hule i den nederste del af {place}, og byder {npc1} en god pris for gården, "nu hvor den bliver for meget at klare alene". Efter to timer (første tik) forlader {villain} gravøllet og rider op ad drivvejen.`,`The notice on the gate promises a hundred silver to whoever kills {boss} in {place}, paid by {villain}. {villain} is kindness itself, tells the heroes that {boss} keeps to the burnt den in the lower part of {place}, and offers {npc1} a good price for the farm, "now that it will be too much to manage alone". After two hours (the first tick) {villain} leaves the funeral feast and rides up the drove road.`),r(`{npc3}, graveren, så liget, før kisten blev lukket: kun ét sår, et slag i baghovedet, og i den knyttede hånd en hornknap skåret med to krydsede hyrdestave, {villain}s brændemærke. Graveren tier, så længe {villain} står ved graven, og det koster en halv time at få {npc3} i enrum efter gravøllet.`,`{npc3}, the gravedigger, saw the body before the coffin was closed: only one wound, a blow to the back of the head, and in the dead man’s clenched hand a horn button carved with two crossed crooks, {villain}’s brand. The gravedigger keeps quiet as long as {villain} stands by the grave, and getting {npc3} alone after the feast costs half an hour.`)],checks:[a(`Wisdom (Perception)`,`medium`,r(`Heltene ser, at der mangler en hornknap i {villain}s frakke, den nederste, og at tråden er revet over, ikke klippet.`,`The heroes notice that a horn button is missing from {villain}’s coat, the bottom one, and that the thread was torn, not cut.`),r(`Heltene ser kun en sørgende nabo i en fin frakke.`,`The heroes see only a grieving neighbour in a fine coat.`)),a(`Charisma (Persuasion)`,`easy`,r(`{npc3} viser heltene knappen bag kirken og beder dem om ikke at sige, hvor de har den fra.`,`{npc3} shows the heroes the button behind the church and asks them not to say where they got it.`),r(`{npc3} ryster på hovedet og går; heltene må vente, til gravøllet er forbi, og det koster en halv time.`,`{npc3} shakes their head and walks off; the heroes must wait until the feast is over, which costs half an hour.`))],fight:!1,alternatives:[r(`Gå direkte op ad drivvejen: Heltene vinder tid, men ved intet om knappen og går derop i den tro, at {boss} er den skyldige.`,`Head straight up the drove road: the heroes gain time, but know nothing of the button and go up there believing {boss} is to blame.`),r(`Hold øje med {villain}: Den, der følger efter, når {villain} forlader gravøllet, ser {villain} ride forbi de tomme gårde og op mod kløften, ikke hjem.`,`Keep an eye on {villain}: whoever follows when {villain} leaves the feast sees {villain} ride past the empty farms and up toward the gorge, not home.`)],dmNotes:r(`Spil {villain} som den rareste person ved graven: gavmild, bevæget og hjælpsom. Lad vejrhanen på tårnet knirke, hver gang spillerne tøver; vinden er uret i dette eventyr.`,`Play {villain} as the kindest person at the graveside: generous, moved and helpful. Let the weathervane on the tower creak whenever the players hesitate; the wind is the clock of this adventure.`)},middle:[{kind:`investigation`,at:`town`,present:[`npc2`],title:r(`Foldene ved drivvejen`,`The Folds by the Drove Road`),summary:r([`Drivvejen går fra {town} forbi seks gårde, der alle står tomme, solgt til {villain} i løbet af den sidste måned, og videre op til {npc1}s gård, den sidste før {place}.`,`Ved folden, hvor de sidste får blev fundet døde, viser sporene, at det var et menneske og ikke {boss}, og oppe på bakken driver {npc2}, {villain}s fårehyrde, alle {villain}s får væk fra vejen.`,`Her kan heltene se, hvem der tjener på frygten, og få det første sikre ord om stenbruddet.`],[`The drove road runs from {town} past six farms that all stand empty, sold to {villain} within the last month, and on up to {npc1}’s farm, the last one before {place}.`,`At the fold where the last sheep were found dead, the signs show that a person was at work, not {boss}, and up on the hill {npc2}, {villain}’s shepherd, is driving all of {villain}’s sheep away from the road.`,`Here the heroes can see who profits from the fear, and get the first sure word of the quarry.`]),readAloud:r([`Langs drivvejen står gård efter gård med lukkede skodder, og på hver port sidder et opslag, slået op med søm.`,`Ved den sidste tomme gård ligger en fold, hvis låge er lukket pænt med en træklinke, og jorden indenfor er mørk og trampet op.`,`Oppe på bakken glider en lang række får væk fra vejen, og en hyrde med to hunde går bagved uden at se sig tilbage.`],[`Along the drove road stands farm after farm with shuttered windows, and a notice is nailed to every gate.`,`At the last empty farm lies a fold whose gate is neatly shut with a wooden latch, and the ground inside is dark and trampled.`,`Up on the hill a long line of sheep drifts away from the road, and a shepherd with two dogs walks behind them without looking back.`]),details:[r(`Opslagene på portene siger det samme: Gården er købt af {villain}, hver gang få dage efter den nat, da fårene i folden blev fundet døde. {villain}s egne får græsser tættest på {place}, men ingen af dem er blevet rørt.`,`The notices on the gates all say the same: the farm was bought by {villain}, each time a few days after the night the sheep in the fold were found dead. {villain}’s own sheep graze closest to {place}, yet not one of them has been touched.`),r(`I folden blev klinken løftet og lukket igen bagefter, og ifølge naboerne gøede hundene ikke de nætter, fårene døde. Fra folden går slæbespor ud mod kanten af {place}, og ved siden af dem aftryk af et par lappede støvler. Det var ikke {boss}, men en, som hundene på egnen kender.`,`In the fold the latch was lifted and shut again afterwards, and according to the neighbours the dogs did not bark on the nights the sheep died. Drag marks run from the fold out to the edge of {place}, and beside them the prints of a pair of patched boots. It was not {boss}, but someone the dogs of the district know.`),r(`{npc2} har vogtet får for alle gårdene ved drivvejen i tyve år, og hundene kender {npc2}; støvlerne er lappede på samme måde som aftrykkene. Fra første tik driver {npc2} {villain}s får op på den høje mark efter ordre, og i frakken ligger {villain}s seddel om ris, tjæretønder og nordenvinden. Stillet over for støvlerne eller sedlen bryder {npc2} sammen, tilstår fårene, sværger, at {npc2} aldrig rørte {npc1}s far, og fortæller om risbunkerne ved hulen i stenbruddet.`,`{npc2} has tended sheep for every farm on the drove road for twenty years, and the dogs know {npc2}; the shepherd’s boots have the same patch as the prints. From the first tick {npc2} drives {villain}’s sheep up to the high field on orders, and in {npc2}’s coat is {villain}’s note about brush, tar barrels and the north wind. Faced with the boots or the note, {npc2} breaks down, confesses to killing the sheep, swears never to have touched {npc1}’s father and tells of the brush piles at the den in the quarry.`)],checks:[a(`Wisdom (Survival)`,`easy`,r(`Heltene ser, at fårene blev slæbt bort på en grind af et menneske, og at støvleaftrykkene har en lap under venstre sål, ligesom hyrdens støvler.`,`The heroes see that someone dragged the sheep off on a hurdle, and that the boot prints have a patch under the left sole, just like the shepherd’s boots.`),r(`Regn og nysgerrige naboer har trådt sporene ud; heltene kan kun se, at der var et menneske i folden, ikke hvem.`,`Rain and curious neighbours have blurred the tracks; the heroes can only tell that someone was in the fold, not who.`)),a(`Wisdom (Insight)`,`medium`,r(`{npc2} er ingen morder, kun bange, og har gjort, hvad {villain} sagde; et roligt ord får {npc2} til at række sedlen frem og fortælle om stenbruddet.`,`{npc2} is no murderer, only frightened, and did what {villain} said; a calm word makes {npc2} hand over the note and tell of the quarry.`),r(`{npc2} kalder på hundene og driver fårene videre; heltene må indhente hyrden oppe på den høje mark, og det koster en halv time.`,`{npc2} calls the dogs and drives the sheep on; the heroes must catch up with the shepherd on the high field, which costs half an hour.`))],fight:!1,alternatives:[r(`Send {npc2} til {npc1}s gård med en advarsel: Hyrden kender vejen og kan få folkene på gården i sikkerhed, før natten kommer.`,`Send {npc2} to {npc1}’s farm with a warning: the shepherd knows the way and can get the household to safety before nightfall.`),r(`Spring foldene over, og gå direkte op i {place}: Heltene vinder en halv time, men ved ikke, hvor hulen er, eller hvornår ilden skal tændes.`,`Skip the folds and go straight up into {place}: the heroes gain half an hour, but do not know where the den is or when the fire is to be lit.`)],dmNotes:r(`Lad de tomme gårde tale: vasketøj, som ingen tog ind, en dukke i et vindue, en hund i lænke, som ingen har fodret. Spillerne skal mærke, hvad frygten har kostet, før de ser, hvem der har tjent på den.`,`Let the empty farms speak: washing nobody took in, a doll in a window, a chained dog nobody has fed. The players should feel what the fear has cost before they see who has profited from it.`)},{kind:`exploration`,at:`site`,present:[],title:r(`Den brændte hule`,`The Burnt Den`),summary:r([`I den nederste del af {place} ligger den gamle hule, hvor {boss} og nogle {foe} holdt til i årevis, og hvor {villain} sendte heltene hen.`,`Den står tom og sort af sod efter ilden for en måned siden, men i asken ligger bunden af en tjæretønde med {villain}s brændemærke, og et bredt bælte af nedtrådt krat fører derfra op mod det gamle stenbrud.`,`Her forstår heltene, at nogen jog {boss} ud med vilje.`],[`In the lower part of {place} lies the old den where {boss} and some {foe} made their home for years, and where {villain} sent the heroes.`,`It has stood empty and black with soot since the fire a month ago, but in the ashes lies the bottom of a tar barrel bearing {villain}’s brand, and a broad swathe of trampled scrub leads from there up toward the old quarry.`,`Here the heroes understand that someone drove {boss} out on purpose.`]),readAloud:r([`Krattet foran hulen er brændt helt ned til jorden, og stammerne omkring er sorte op til skulderhøjde.`,`Hulens munding er sodet, og indenfor ligger et tykt lag kold aske, hvor noget har ligget i mange år.`,`Halvt begravet i asken stikker en forkullet tøndebund op, og et brændemærke kan stadig ses på den.`],[`The scrub in front of the den is burnt down to the ground, and the trunks around it are black to shoulder height.`,`The mouth of the den is sooty, and inside lies a thick layer of cold ash where something lay for many years.`,`Half buried in the ash, the charred bottom of a barrel sticks up, a brand still visible on it.`]),details:[r(`Tøndebunden er brændemærket med to krydsede hyrdestave, {villain}s mærke, og asken lugter stadig svagt af tjære. Ilden blev lagt ved mundingen med vilje og hjulpet på vej med tjære, så den brændte indad; det var hverken et lynnedslag eller en skødesløs kulsvier.`,`The barrel bottom is branded with two crossed crooks, {villain}’s mark, and the ash still smells faintly of tar. The fire was laid at the mouth on purpose and helped along with tar so that it burned inward; this was neither a lightning strike nor a careless charcoal burner.`),r(`De gamle stier fra hulen fører slet ikke mod gårdene, men dybere ind i {place}. Ingen i {town} kan huske, at noget fra hulen kom ned til drivvejen før ilden; frygten begyndte samme uge, som hulen brændte.`,`The old paths from the den do not lead toward the farms at all, but deeper into {place}. No one in {town} remembers anything from the den coming down to the drove road before the fire; the fear began the same week the den burned.`),r(`Fra hulen fører et bredt bælte af nedtrådt krat og knækkede grene op ad skråningen mod det gamle stenbrud. Det er en måned gammelt, men friske spor fra de sidste nætter går samme vej, og et sted krydser de drivvejen, der går op gennem kløften.`,`From the den a broad swathe of trampled scrub and broken branches leads up the slope toward the old quarry. It is a month old, but fresh tracks from the last few nights run the same way, and at one point they cross the drove road that climbs the gorge.`)],checks:[a(`Intelligence (Investigation)`,`medium`,r(`Heltene ser, at ilden blev lagt med vilje: ris stablet ved mundingen og tjære hældt over, så ilden brændte indad. Det var et menneskes værk, og det samme kan ske igen et andet sted.`,`The heroes see that the fire was laid on purpose: brush stacked at the mouth and tar poured over it so that it burned inward. It was the work of human hands, and the same could happen again somewhere else.`),r(`Heltene ser kun en brandtomt; tøndebunden kan de tage med, men de kan ikke sige, om ilden var et uheld.`,`The heroes see only a burnt-out hollow; they can take the barrel bottom along, but cannot say whether the fire was an accident.`)),a(`Wisdom (Survival)`,`easy`,r(`Heltene følger bæltet op mod stenbruddet og ser, at der mellem de friske spor også er aftryk af støvler, der går op og kommer tilbage igen.`,`The heroes follow the swathe up toward the quarry and spot boot prints among the fresh tracks, going up and coming back down.`),r(`Skråningen er stejl og sporene mange; heltene går forkert og bruger en halv time på at finde vejen op mod stenbruddet.`,`The slope is steep and the tracks many; the heroes take a wrong turn and spend half an hour finding the path up toward the quarry.`))],fight:!1,alternatives:[r(`Tag tøndebunden med: Med brændemærket og hornknappen har heltene to ting med {villain}s mærke, som rådet kan se med egne øjne.`,`Take the barrel bottom along: with the brand and the horn button the heroes have two things bearing {villain}’s mark that the council can see with its own eyes.`),r(`Gå tilbage til drivvejen, og følg den op gennem kløften: Det er den vej, vognen kørte, og den vej, {villain} vil drive {boss} ned ad i aften.`,`Go back to the drove road and follow it up through the gorge: that is the way the cart went, and the way {villain} means to drive {boss} down tonight.`)],dmNotes:r(`Den brændte hule er stedet, hvor jagten vender. Lad spillerne stå i asken et øjeblik og forstå, at det, de blev sendt for at dræbe, først blev brændt ud af denne hule.`,`The burnt den is where the hunt turns around. Let the players stand in the ash for a moment and understand that whatever they were sent to kill was burned out of this den first.`)},{kind:`combat`,at:`site`,present:[],title:r(`Tjæresporet i kløften`,`The Tar Trail in the Gorge`),summary:r([`Drivvejen går op gennem en smal kløft mod det gamle stenbrud, og i dag er der dryppet frisk tjære i hjulspor efter en trækvogn, og stien er kantet af nyhuggede stubbe.`,`Uroen ved stenbruddet har drevet nogle {foe} ned i kløften, og de angriber alt, der kommer op ad stien.`,`Bag et klippefremspring står {villain}s hest tøjret i skjul: {villain} er allerede deroppe.`],[`The drove road climbs a narrow gorge toward the old quarry. Today fresh tar has dripped into the ruts of a handcart, and the path is lined with freshly cut stumps.`,`The disturbance at the quarry has driven some {foe} down into the gorge, and they attack anything that comes up the path.`,`Behind a rocky outcrop {villain}’s horse stands tethered out of sight: {villain} is already up there.`]),readAloud:r([`Kløften er smal og stejl, og drivvejen snor sig op mellem klippevægge, hvor krattet er hugget ned i en armslængdes afstand fra stien.`,`I hjulsporene ligger sorte, blanke dråber, der lugter skarpt af tjære.`,`Højere oppe rasler det i krattet, og så bliver der helt stille.`],[`The gorge is narrow and steep, and the drove road winds up between rock walls where the scrub has been cut back an arm’s length from the path.`,`In the wheel ruts lie black, glossy drops that smell sharply of tar.`,`Higher up something rustles in the scrub, and then everything goes quiet.`]),details:[r(`Nogle {foe} fra hulen i stenbruddet er drevet ned i kløften af larmen og lugten deroppe. De tjener ikke {villain}, men angriber alt, der kommer op ad stien, og trækker sig tilbage mod stenbruddet, når halvdelen af dem er faldet.`,`Some {foe} from the quarry den have been driven down into the gorge by the noise and the reek up there. They do not serve {villain}, but attack anything coming up the path, and fall back toward the quarry once half of them are down.`),r(`Tjæredråberne og hjulsporene fører op mod stenbruddet, og stubbene viser, hvor risene til bunkerne blev hugget. Bag et klippefremspring står {villain}s hest tøjret med to krydsede hyrdestave på sadeldækket; i sadeltasken ligger kun et fyrtøj og en ekstra fakkel.`,`The tar drops and wheel ruts lead up toward the quarry, and the stumps show where the brush for the piles was cut. Behind a rocky outcrop {villain}’s horse stands tethered, two crossed crooks on the saddlecloth; the saddlebag holds only a tinderbox and a spare torch.`),r(`Er der gået seks timer (andet tik), er kampen her en del af uroen, og nogle {foe} er allerede på vej ned mod drivvejen; slipper de forbi heltene, når de gårdene før natten. Fra kløften er der en halv times stigning op til stenbruddet.`,`If six hours have passed (the second tick), this fight is part of the unrest, and some {foe} are already heading down toward the drove road; if they slip past the heroes, they reach the farms before nightfall. From the gorge it is a half-hour climb to the quarry.`)],checks:[a(`Wisdom (Perception)`,`medium`,r(`Heltene ser bevægelsen i krattet i tide og tager imod angrebet et sted, hvor kløften er bred nok til at stå sammen.`,`The heroes spot the movement in the scrub in time and meet the attack where the gorge is wide enough to stand together.`),r(`Angrebet kommer fra begge sider af stien på én gang, og heltene må kæmpe spredt i den smalle kløft.`,`The attack comes from both sides of the path at once, and the heroes must fight strung out in the narrow gorge.`)),a(`Wisdom (Animal Handling)`,`easy`,r(`Heltene får {villain}s hest løs uden en lyd; uden hesten kan {villain} ikke ride hurtigt bort fra stenbruddet bagefter.`,`The heroes untie {villain}’s horse without a sound; without it {villain} cannot ride away from the quarry in a hurry afterwards.`),r(`Hesten vrinsker højt, og lyden bærer op til stenbruddet; {villain} ved nu, at nogen kommer.`,`The horse whinnies loudly, and the sound carries up to the quarry; {villain} now knows someone is coming.`))],fight:!0,alternatives:[r(`Klatr uden om kløften ad klippevæggen: Det er hårdt og koster en halv time, men heltene undgår kampen og kommer op på kanten af stenbruddet lige ved {villain}.`,`Climb around the gorge by the rock wall: it is hard going and costs half an hour, but the heroes avoid the fight and come out on the quarry rim right beside {villain}.`),r(`Lad dem komme forbi: Gemmer heltene sig, løber nogle {foe} ned ad stien mod drivvejen, og vejen op er fri, men {npc1}s gård får besøg før natten.`,`Let them go by: if the heroes hide, some {foe} run down the path toward the drove road and the way up is clear, but {npc1}’s farm will have visitors before nightfall.`)],dmNotes:r(`Kampen er ikke målet. Det, heltene møder her, er bange og trængt, ikke ondt; lad nogle {foe} flygte op mod stenbruddet, når det går dem imod, så spillerne kan følge efter og se, hvor de holder til.`,`The fight is not the point. What the heroes meet here is frightened and cornered, not wicked; let some {foe} flee up toward the quarry when it goes badly for them, so the players can follow them to their den.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:r(`Hulen i stenbruddet`,`The Den in the Quarry`),summary:r([`Øverst i kløften ligger det gamle stenbrud, og i dets bund har {boss} og nogle {foe} fundet en ny hule; ved mundingen står seks risbunker, gennemvædet af tjære.`,`{villain} står alene på kanten af stenbruddet med en fakkel og venter på nordenvinden. {boss} og de andre tjener ingen og angriber alt, der kommer nær hulen, og når ilden bliver tændt, bryder de ud i panik.`,`Heltene skal holde ilden fra risbunkerne, vende {boss} og de andre væk fra drivvejen og afgøre, hvad der skal ske med både {villain} og {boss}.`],[`At the head of the gorge lies the old quarry, and at its bottom {boss} and some {foe} have found a new den; six brush piles soaked in tar stand at the mouth.`,`{villain} stands alone on the quarry rim with a torch, waiting for the north wind. {boss} and the others serve no one and attack anything that comes near the den, and once the fire is lit, they break out in panic.`,`The heroes must keep the fire from the brush piles, turn {boss} and the others away from the drove road and decide what is to become of both {villain} and {boss}.`]),readAloud:r([`Stenbruddet er en dyb skål af grå klippe, og i bunden gaber en sort åbning i væggen.`,`Foran åbningen står risbunker, højere end en mand, og de skinner vådt og sort af tjære.`,`Oppe på kanten står en skikkelse i en frakke med hornknapper og holder en tændt fakkel, og flammen bøjer sig, da vinden begynder at dreje.`],[`The quarry is a deep bowl of grey rock, and at its bottom a black opening gapes in the wall.`,`In front of the opening stand brush piles taller than a man, glistening wet and black with tar.`,`Up on the rim a figure in a coat with horn buttons holds a lit torch, and the flame leans as the wind begins to turn.`]),details:[r(`{boss} og nogle {foe} har deres hule her og tjener ikke {villain}, der har sneget sig herop om dagen og er rædselsslagen for dem. Kommer heltene ned til hulen, går {boss} efter de nærmeste, og når ilden bliver tændt, bryder de alle ud og flygter væk fra flammerne.`,`{boss} and some {foe} have their den here and do not serve {villain}, who crept up here by day and is terrified of them. If the heroes come down to the den, {boss} goes for the nearest hero, and once the fire is lit, they all break out and flee from the flames.`),r(`Uden nordenvind spreder {boss} og de andre sig bare i {place}, når ilden bliver tændt; med den bærer vinden ild og røg ned gennem kløften og jager dem hele vejen ned ad drivvejen. Derfor venter {villain} på, at vinden vender ved mørkets frembrud (tredje tik). Bliver {villain} skræmt og kaster faklen for tidligt, brænder risene, men flugten går ind i {place}, og det første, der står i vejen, er heltene.`,`Without a north wind, {boss} and the others simply scatter into {place} when the fire is lit; with it, the wind carries fire and smoke down the gorge and chases them all the way down the drove road. That is why {villain} waits for the wind to turn at nightfall (the third tick). If {villain} panics and throws the torch too early, the brush burns, but {boss} and the others flee into {place}, and the first thing in their way is the heroes.`),r(`Står {villain} over for hornknappen, sedlen til {npc2} eller tøndebunden fra den brændte hule, er der intet at vinde ved ilden længere, og {villain} vil forhandle om gårdene, om penge og om at slippe for galgen. Truet af {boss} eller af heltene på kanten løber {villain} mod kløften, hvor hesten står, hvis den stadig står der.`,`Faced with the horn button, the note to {npc2} or the barrel bottom from the burnt den, {villain} has nothing left to gain from the fire and will bargain over the farms, over money and over escaping the gallows. Threatened by {boss}, or by the heroes on the rim, {villain} runs for the gorge where the horse is tethered, if it is still there.`)],checks:[a(`Dexterity (Acrobatics)`,`medium`,r(`En helt når op på kanten og vrider faklen ud af hånden på {villain}, før den rammer risene.`,`A hero reaches the rim and wrenches the torch out of {villain}’s hand before it hits the brush.`),r(`Faklen lander i risene, og tjæren tager fat med et brøl; heltene har én runde til at vælte den nærmeste bunke væk fra mundingen, før {boss} og de andre bryder ud.`,`The torch lands in the brush and the tar catches with a roar; the heroes have one round to topple the nearest pile away from the mouth before {boss} and the others break out.`)),a(`Charisma (Intimidation)`,`medium`,r(`Med beviserne i hånden får heltene {villain} til at kaste faklen fra sig og overgive sig hellere end at blive efterladt alene med {boss}.`,`With the proof in hand, the heroes make {villain} throw the torch aside and surrender rather than be left alone with {boss}.`),r(`{villain} skriger, at heltene er kommet for sent, og kaster faklen; {boss} og de andre bryder ud af hulen midt imellem dem.`,`{villain} shrieks that the heroes have come too late and throws the torch; {boss} and the others burst out of the den right between them.`))],fight:!0,alternatives:[r(`Forstyr ikke hulen: Vælter heltene risbunkerne væk fra mundingen i stilhed og tager {villain} på kanten, kan {boss} og de andre få lov at blive, hvor de er, og ingen behøver at kæmpe.`,`Leave the den undisturbed: if the heroes quietly topple the brush piles away from the mouth and take {villain} on the rim, {boss} and the others can stay where they are, and no one needs to fight.`),r(`Brug ilden selv: Tænder heltene risene, før vinden vender, og holder sig af vejen, spreder {boss} og de andre sig ind i {place}, væk fra gårdene, og {villain}s plan brænder op sammen med risene.`,`Set the fire first: if the heroes light the brush before the wind turns and keep out of the way, {boss} and the others scatter into {place}, away from the farms, and {villain}’s plan goes up in smoke with the brush.`)],dmNotes:r(`Lad vinden være det ur, alle kan mærke: Fakkelflammen bøjer sig lidt mere for hver runde. Og husk, at heltene blev hyret til at dræbe {boss}; lad dem selv afgøre, om det stadig er det rigtige.`,`Make the wind the clock everyone can feel: the torch flame leans a little further each round. And remember that the heroes were hired to kill {boss}; let them decide for themselves whether that is still the right thing to do.`)}},ie=e({kernel:()=>ce,scenes:()=>le}),ae=e=>Array.isArray(e)?e.join(` `):e,o=(e,t)=>({da:ae(e),en:ae(t)}),oe=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),s=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},se=(e,t,n)=>({when:e,event:t,sign:n}),c=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),ce={id:`wild-the-last-cairn`,titles:[o(`Den sidste varde`,`The Last Cairn`),o(`Storm over {place}`,`Storm over {place}`),o(`Varderne lyver`,`The Lying Cairns`)],missions:[`wilderness`],foes:`lair`,roles:{npc1:o(`en gammel vogter af varderne, der ikke længere kan klare stigningen`,`an old keeper of the cairns who can no longer manage the climb`),npc2:o(`en fjeldfører, som {villain} hyrede og efterlod i tågen på fjeldet`,`a fell guide whom {villain} hired and left behind in the fog on the fell`),npc3:o(`en stenhugger, der har hugget en skiferplade for {villain}`,`a stonecutter who has cut a slate for {villain}`),villain:o(`en mineejer fra den anden side af fjeldet, hvis mine mangler vand`,`a mine owner from the far side of the fell whose mine needs water`)},hook:o(`{npc1} venter ved daggry på heltene ved elvestenen og beder dem gå op ad vardestien til den sidste varde på toppen af {place} og redde grænseskiferen, før {villain} graver den op, og før stormen lukker fjeldet.`,`{npc1} waits for the heroes at the river stone at dawn and asks them to climb the cairn path to the last cairn on the summit of {place} and save the boundary slate before {villain} digs it up, and before the storm closes the fell.`),people:{npc1:{wants:o(`Vil se varderne stå, som de har stået i hundrede år, og skiferen ligge, hvor den hører hjemme.`,`Wants the cairns standing as they have stood for a hundred years, and the slate lying where it belongs.`),secret:o(`Skulle have gået linjen i sommer, som skikken kræver, men kunne ikke klare stigningen og sagde til rådet, at alt var i orden.`,`Should have walked the line this summer, as custom demands, but could not manage the climb and told the council all was well.`)},npc2:{wants:o(`Vil ned fra fjeldet i live og aldrig mere føre fremmede derop.`,`Wants to get off the fell alive and never guide strangers up there again.`),secret:o(`Fortalte selv {villain} om skiferen under den sidste varde for et krus øl og en sølvmønt og har fortrudt det lige siden.`,`Told {villain} about the slate under the last cairn for a mug of ale and a silver coin, and has regretted it ever since.`)},npc3:{wants:o(`Vil have betaling for sit arbejde og ikke trækkes ind i herremandens sager.`,`Wants to be paid for their work and not dragged into the lord’s affairs.`),secret:o(`Huggede den falske plade for dobbelt betaling, selv om det var {npc3}s egen bedstefar, der huggede den ægte skifer, og skammer sig over det.`,`Cut the false slate for double pay, although it was {npc3}’s own grandfather who cut the true one, and is ashamed of it.`)}},premise:o([`Grænsen mellem {town}s jord og herremandens løber fra elvestenen langs en række gamle varder op over {place} til den sidste varde på toppen, og under den ligger grænseskiferen, der viser, at højsøen, hvor {town}s elv udspringer, hører byen til.`,`Herremanden påstår nu, at linjen går under søen, og til foråret vil kongens landmåler grave under den sidste varde og afgøre sagen; får herremanden søen, får {villain} vandet til sin mine på den anden side af fjeldet og kan dæmme elven op.`,`I morges gik {villain} op på fjeldet med arbejdsfolk, en fjeldfører og en falsk skiferplade for at bygge en ny "sidste varde" ved søens udløb og for at grave den ægte skifer op og smadre den, før årets første snestorm lukker fjeldet til foråret.`],[`The boundary between the land of {town} and the lord’s land runs from the river stone along a line of old cairns up over {place} to the last cairn on the summit, and beneath it lies the boundary slate, which shows that the high lake where the river of {town} rises belongs to the town.`,`The lord now claims that the line runs below the lake, and in spring the king’s surveyor will dig under the last cairn and settle the matter; if the lord gets the lake, {villain} gets its water for the mine on the far side of the fell and can dam the river.`,`This morning {villain} went up onto the fell with workmen, a fell guide and a false slate, to build a new "last cairn" at the lake’s outflow and to dig up the true slate and smash it before the year’s first snowstorm closes the fell until spring.`]),goal:o(`Nå den sidste varde på toppen af {place} før {villain}, red grænseskiferen, og kom ned igen, før stormen lukker fjeldet ved mørkets frembrud.`,`Reach the last cairn on the summit of {place} before {villain} does, save the boundary slate and get back down before the storm closes the fell at nightfall.`),objective:{target:o(`Grænseskiferen under den sidste varde på toppen af {place}, det eneste bevis på, at højsøen hører {town} til`,`The boundary slate under the last cairn on the summit of {place}, the only proof that the high lake belongs to {town}`),state:o(`Sat i et leje af sten under vardens nederste lag. {villain} river varden ned for at nå den, og lige ved siden af, i et gammelt fårehus, har {boss} og nogle {foe} deres hule.`,`Set in a bed of stones under the bottom course of the cairn. {villain} is tearing the cairn down to reach it, and right beside it, in an old sheep shelter, {boss} and some {foe} have their lair.`),resolution:o([`Få skiferen hel ned til {town}, og tag den falske plade fra den nye varde ved søens udløb med som bevis.`,`Bliver skiferen slået i stykker, fortæller stykkerne stadig sandheden, hvis heltene samler dem, før sneen dækker toppen.`],[`Get the slate down to {town} whole, and take the false slate from the new cairn at the lake’s outflow as proof.`,`If the slate is smashed, the pieces still tell the truth, as long as the heroes gather them before the snow covers the summit.`])},villain:{want:o(`At få vandet fra højsøen til sin mine og blive den rigeste på begge sider af fjeldet.`,`To get the water of the high lake for the mine and become the richest person on both sides of the fell.`),plan:o([`Først fik {villain} {npc3} til at hugge en skiferplade i gammel stil, hvor grænsen går til en varde ved søens udløb, og lokkede {npc2} til at fortælle, hvor den ægte skifer ligger.`,`I morges lod {villain} en varde ved mosen flytte, så den, der følger efter, går ud i dyndet, og lod arbejdsfolkene bygge en ny varde over den falske plade ved søens udløb.`,`Før stormen ved mørkets frembrud graver {villain} selv den ægte skifer op under den sidste varde på toppen, smadrer den og spreder stenene, så sneen dækker pladsen til foråret.`],[`First, {villain} had {npc3} cut a slate in the old style stating that the boundary runs to a cairn at the lake’s outflow, and coaxed {npc2} into telling where the true slate lies.`,`This morning {villain} had a cairn by the mire moved so that anyone following walks into the mud, and had the workmen build a new cairn over the false slate at the lake’s outflow.`,`Before the storm at nightfall {villain} personally digs the true slate out from under the last cairn on the summit, smashes it and scatters the stones, so that the snow covers the spot until spring.`]),weakness:o([`{villain} kender ikke fjeldet og har jaget den eneste fører bort, der gør; i stormen kan {villain} ikke komme ned uden hjælp.`,`Alene på toppen med kulden og det, der bor i fårehuset, vil {villain} bytte alt for en vej ned, også skiferen.`],[`{villain} does not know the fell and has driven off the only guide who does; in the storm {villain} cannot get down without help.`,`Alone on the summit with the cold and whatever lives in the shelter, {villain} will trade anything for a way down, the slate included.`])},stakes:o(`Bliver den ægte skifer smadret, og dækker sneen toppen, finder landmåleren kun den falske plade til foråret: Højsøen går til herremanden, {villain} dæmmer udløbet op, og {town}s elv løber tør hver sommer fra nu af.`,`If the true slate is smashed and the snow covers the summit, the surveyor will find only the false slate in spring: the high lake goes to the lord, {villain} dams the outflow and the river of {town} runs dry every summer from then on.`),clock:{start:o(`Morgen. Skyerne tårner sig op i vest, og fårehyrderne siger, at årets første snestorm rammer {place} ved mørkets frembrud, om ti timer. {villain} red mod fjeldet for en time siden med seks arbejdsfolk, muldyr, brækjern og en slæde.`,`Morning. Clouds are piling up in the west, and the shepherds say the year’s first snowstorm will hit {place} at nightfall, ten hours from now. {villain} rode toward the fell an hour ago with six workmen, mules, crowbars and a sledge.`),ticks:[se(o(`Efter 3 timer`,`After 3 hours`),o(`Tågen lægger sig over mosen på højfjeldet, og fra nu af er varderne den eneste vej; den varde, {villain} lod flytte, peger lige ud i dyndet.`,`Fog settles over the mire on the high fell, and from now on the cairns are the only guide; the cairn {villain} had moved points straight into the mud.`),o(`Tågen sluger den næste varde, og jorden bliver blød under fødderne.`,`The fog swallows the next cairn, and the ground turns soft underfoot.`)),se(o(`Efter 6 timer`,`After 6 hours`),o(`{villain} når den sidste varde på toppen og begynder at rive den ned, mens arbejdsfolkene gør den nye varde ved søens udløb færdig; sluddet begynder.`,`{villain} reaches the last cairn on the summit and starts tearing it down, while the workmen finish the new cairn at the lake’s outflow; the sleet begins.`),o(`Slud i vinden og lyden af jern mod sten fra ryggen over søen.`,`Sleet on the wind, and the ring of iron on stone from the ridge above the lake.`)),se(o(`Efter 10 timer (ved mørkets frembrud)`,`After 10 hours (at nightfall)`),o(`Stormen bryder løs: {villain} smadrer skiferen og spreder vardens sten, og sneen dækker pladsen, hvor den sidste varde stod.`,`The storm breaks: {villain} smashes the slate and scatters the cairn’s stones, and the snow covers the spot where the last cairn stood.`),o(`Sneen fyger, varderne forsvinder én efter én, og vinden hyler over toppen.`,`Snow drives sideways, the cairns vanish one by one and the wind howls over the summit.`))],deadline:o(`Efter 10 timer, ved mørkets frembrud, er det for sent: Skiferen er smadret, sneen dækker toppen, og den, der stadig er oppe på {place}, må finde vej ned i stormen uden varder.`,`After 10 hours, at nightfall, it is too late: the slate is smashed, the snow covers the summit and anyone still up on {place} must find their way down through the storm without cairns.`)},clues:{who:[s(`town`,o(`{npc3}, stenhuggeren, har en afskrift af teksten på den skiferplade, {villain} bestilte og betalte dobbelt for.`,`{npc3}, the stonecutter, has a copy of the text on the slate {villain} ordered and paid double for.`),o(`{villain} har fået hugget en falsk grænseskifer, der flytter grænsen ned under søen.`,`{villain} has had a false boundary slate cut that moves the boundary down below the lake.`),oe([`Her løber grænsen mellem herremandens jord og {town}s`,`fra elvestenen langs varderne til den sidste varde ved højsøens udløb.`,`Hvad der ligger ovenfor, hører herremanden til. Sat i vor herres navn.`],[`Here runs the boundary between the lord’s land and that of {town},`,`from the river stone along the cairns to the last cairn at the outflow of the high lake.`,`All that lies above belongs to the lord. Set in our lord’s name.`])),s(`town`,o(`I pakningen på {villain}s muldyr i laden ligger landmålerværktøj, nye pæle, en tegning af en dæmning over højsøens udløb og et brev fra herremandens forvalter.`,`In the packs of {villain}’s mules in the barn lie surveying tools, new stakes, a drawing of a dam across the outflow of the high lake and a letter from the lord’s steward.`),o(`{villain} vil dæmme søen op for sin mine og har brug for, at grænsen går under søen.`,`{villain} means to dam the lake for the mine and needs the boundary to run below it.`),oe([`Mester {villain},`,`min herre giver Dem vandet fra højsøen til minen i tyve år`,`den dag, linjen er vist at gå under søen. Hvordan, vil han ikke vide.`,`– forvalteren`],[`Master {villain},`,`my lord grants you the water of the high lake for the mine for twenty years`,`from the day the line is shown to run below the lake. How, he does not wish to know.`,`— the steward`])),s(`site`,o(`Ved mosen står en varde på frisk, nedtrådt lyng med laven på den forkerte side, og i lyngen ligger en messingpolet fra {villain}s mine, stemplet med to krydsede hamre.`,`Where the cairn path skirts the misty mire, a cairn stands on freshly trampled heather with its lichen on the wrong side, and in the heather lies a brass token from {villain}’s mine, stamped with two crossed hammers.`),o(`{villain}s folk har flyttet varden, så den, der følger efter, går ud i dyndet.`,`{villain}’s people moved the cairn so that anyone following walks into the mud.`)),s(`site`,o(`Under den nye varde ved søens udløb ligger en skiferplade med gamle bogstaver, men rillerne er stadig hvide af frisk stenstøv.`,`Under the new cairn at the lake’s outflow lies a slate cut in old-style letters, but the grooves are still white with fresh stone dust.`),o(`Den nye "sidste varde" er bygget i dag over en falsk plade, og kun {villain} har grund til at sætte den der.`,`The new "last cairn" was built today over a false slate, and only {villain} has reason to put one there.`))],where:[s(`town`,o(`{npc1} kan det gamle vers om varderne, som vogterne har lært hinanden i hundrede år.`,`{npc1} knows the old verse about the cairns that the keepers have taught each other for a hundred years.`),o(`Den ægte sidste varde står på toppen ved Rokkestenen, og skiferen ligger under den.`,`The true last cairn stands on the summit by the Rocking Stone, and the slate lies beneath it.`),oe([`Fra elvestenen nitten varder går,`,`forbi mosen, hvor tågen står,`,`op over søen, hvor elven får vand,`,`til Rokkestenen på fjeldets rand.`,`Den sidste står højest, hvor ørnene bor,`,`og skiferen under den siger: Søen er vor.`],[`Nineteen cairns from the river stone,`,`past the mire where the fog lies alone,`,`over the lake where the river is fed,`,`to the Rocking Stone at the fell’s grey head.`,`The last stands highest, in wind and in snow,`,`and the slate beneath says whose lake lies below.`])),s(`town`,o(`Fårehyrden, der passer {villain}s muldyr, hørte {villain} spørge fjeldføreren, hvor langt der er fra søens udløb op til Rokkestenen.`,`The shepherd minding {villain}’s mules heard {villain} ask the fell guide how far it is from the lake’s outflow up to the Rocking Stone.`),o(`{villain} skal både til søens udløb og op til toppen ved Rokkestenen.`,`{villain} is heading both for the lake’s outflow and for the summit by the Rocking Stone.`)),s(`site`,o(`{npc2}, fjeldføreren, siger, at {villain} er på vej til toppen ved Rokkestenen for at grave den ægte skifer op under den sidste varde.`,`{npc2}, the fell guide, says that {villain} is on the way to the summit by the Rocking Stone to dig the true slate out from under the last cairn.`),o(`Skiferen er stadig under den sidste varde på toppen, og {villain} er der snart.`,`The slate is still under the last cairn on the summit, and {villain} will soon be there.`)),s(`site`,o(`Fra lejren ved søens udløb fører friske skrammer og tabte sten op ad ryggen mod Rokkestenen, og deroppe lyder slag af jern mod sten.`,`From the camp at the lake’s outflow, fresh scrapes and dropped stones lead up the ridge toward the Rocking Stone, and from up there comes the ring of iron on stone.`),o(`Den ægte sidste varde står på toppen ved Rokkestenen, og der graver {villain} lige nu.`,`The true last cairn stands on the summit by the Rocking Stone, and that is where {villain} is digging right now.`))]},endings:{success:o(`Skiferen kommer hel ned til {town} sammen med den falske plade, og {villain} står for rådet med forvalterens brev foran sig og kan ikke forklare noget af det. Til foråret går landmåleren op til den sidste varde med {npc1} båret på en båre, og hele byen bygger varden op igen, sten for sten.`,`The slate comes down to {town} whole, together with the false one, and {villain} stands before the council with the steward’s letter on the table and cannot explain any of it. In spring the surveyor climbs to the last cairn with {npc1} carried along on a stretcher, and the whole town rebuilds the cairn, stone by stone.`),partial:o(`Heltene redder kun nogle af stykkerne, eller {villain} slipper ned i stormen og fortæller sin egen historie først. Sagen trækker ud, landmåleren tvivler, og hele sommeren står {villain}s pæle omkring søen, mens byen venter på en dom.`,`The heroes save only some of the pieces, or {villain} gets down through the storm and is first to tell their side of the story. The case drags on, the surveyor wavers and all summer {villain}’s stakes stand around the lake while the town waits for a ruling.`),failure:o(`Ved mørkets frembrud er skiferen smadret, og sneen dækker toppen til foråret. Landmåleren finder kun den falske plade, højsøen går til herremanden, og {villain}s dæmning står færdig, før elven gennem {town} løber tør for første gang i mands minde.`,`At nightfall the slate is smashed and the snow covers the summit until spring. The surveyor finds only the false slate, the high lake goes to the lord and {villain}’s dam is finished before the river through {town} runs dry for the first time in living memory.`)}},le={opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc3`],title:o(`Skyerne i vest`,`Clouds in the West`),summary:o([`Ved daggry finder {npc1}, den gamle vogter af varderne i {town}, heltene ved elvestenen, hvor vardelinjen begynder, og beder dem gå op til den sidste varde på toppen af {place}, før {villain} graver skiferen under den op, og før stormen lukker fjeldet.`,`{villain}, mineejeren fra den anden side af fjeldet, red forbi for en time siden med arbejdsfolk, brækjern og en slæde, og skyerne tårner sig op i vest.`,`Byen kan give svar, før heltene går, men hver omvej koster tid, og ved mørkets frembrud kommer sneen.`],[`At dawn {npc1}, the old keeper of the cairns of {town}, finds the heroes at the river stone where the line of cairns begins, and asks them to climb to the last cairn on the summit of {place} before {villain} digs up the slate beneath it, and before the storm closes the fell.`,`{villain}, the mine owner from the far side of the fell, rode past an hour ago with workmen, crowbars and a sledge, and the clouds are piling up in the west.`,`The town can give answers before the heroes go, but every detour costs time, and at nightfall the snow comes.`]),readAloud:o([`Ved elven i udkanten af {town} står en mosgroet varde, og bag den klatrer en række små stenhobe op over fjeldet, til den sidste forsvinder i skyerne.`,`En gammel skikkelse med en knortet stok står ved varden og lægger en sten på toppen, som man gør, når nogen skal en lang vej.`,`Mod vest er himlen tung og gulgrå, og vinden har allerede en bid af sne i sig.`],[`By the river at the edge of {town} stands a mossy cairn, and behind it a row of small stone heaps climbs up over the fell until the last one vanishes into the clouds.`,`An old figure with a gnarled staff stands by the cairn and lays a stone on top, as people do when someone has a long way to go.`,`To the west the sky is heavy and yellow-grey, and the wind already has a bite of snow in it.`]),details:[o(`{npc1} fortæller, at grænsen mellem {town}s jord og herremandens løber fra elvestenen langs varderne til den sidste varde på toppen, og at grænseskiferen ligger under den. Herremanden påstår nu, at linjen går under højsøen, som {town}s elv løber fra, og til foråret vil kongens landmåler grave under den sidste varde og afgøre sagen. {npc1} kan det gamle vers om varderne og siger det gerne.`,`{npc1} explains that the boundary between the land of {town} and the lord’s land runs from the river stone along the cairns to the last cairn on the summit, and that the boundary slate lies beneath it. The lord now claims that the line runs below the high lake that feeds the river of {town}, and in spring the king’s surveyor will dig under the last cairn and settle the matter. {npc1} knows the old verse about the cairns and is glad to recite it.`),o(`{npc3}, stenhuggeren, har for nylig hugget en skiferplade med gamle bogstaver og et gammelt segl for {villain} og gemt en afskrift af teksten, fordi det hele lugtede af svindel. Det koster en halv time at få {npc3} til at finde afskriften frem.`,`{npc3}, the stonecutter, recently cut a slate with old-style letters and an old seal for {villain}, and kept a copy of the text because the whole thing smelled of fraud. Getting {npc3} to dig out the copy costs half an hour.`),o(`Der er ti timer til mørkets frembrud. {villain} har en times forspring, men følget er langsomt med slæden, og muldyrene må blive på gården under fjeldet, hvor stien bliver for stejl. Vardestien er sikker, men lang; fåresporet op ad urskråningen er kortere, men farligt i slud.`,`There are ten hours until nightfall. {villain} has an hour’s lead, but the mine owner’s company is slowed by the sledge, and the mules must stay at the farm below the fell, where the path grows too steep. The cairn path is safe but long; the sheep track up the scree is shorter, but dangerous in sleet.`),o(`Vejen: fra {town} til gården under fjeldet 1 time, fra gården til mosen på højfjeldet 3 timer ad vardestien eller 2 timer ad fåresporet, fra mosen til lejren ved søens udløb 2 timer langs varderne, og derfra en halv time op til toppen. Ad vardestien er heltene altså på toppen efter seks en halv time, ad fåresporet efter fem en halv; hvert ophold for spor eller hvil lægges oven i. Nedad går det hurtigere: fra toppen til lejren et kvarter, til mosen 1½ time og ned til gården 2 timer ad vardestien eller 1½ time ad fåresporet; nede ved gården er heltene i sikkerhed for stormen. Ad fåresporet begge veje tager det altså 8 timer og 45 minutter, ad vardestien begge veje 10 timer og et kvarter. Bærer heltene en såret fører, tager hvert stykke ned en halv gang længere; skiferen er ikke tungere, end at den kan bæres i en rygsæk.`,`Travel times: from {town} to the farm below the fell, 1 hour; from the farm to the mire on the high fell, 3 hours by the cairn path or 2 hours by the sheep track; from the mire to the camp at the lake’s outflow, 2 hours along the cairns; and from there half an hour up to the summit. By the cairn path the heroes reach the summit after six and a half hours, by the sheep track after five and a half; every stop for clues or rest adds to that. Going down is quicker: from the summit to the camp a quarter of an hour, to the mire 1½ hours and down to the farm 2 hours by the cairn path or 1½ hours by the sheep track; once at the farm, the heroes are safe from the storm. By the sheep track both ways it takes 8 hours and 45 minutes, by the cairn path both ways 10 hours and 15 minutes. If the heroes carry an injured guide, every leg down takes half again as long; the slate is no heavier than a pack can carry.`)],checks:[c(`Charisma (Persuasion)`,`easy`,o(`{npc3} finder afskriften frem og fortæller, at {villain} betalte det dobbelte for at få pladen hurtigt og spurgte, om den ville se gammel ud efter en vinter under sne.`,`{npc3} brings out the copy and tells how {villain} paid double to have the slate done quickly and asked whether it would look old after a winter under snow.`),o(`{npc3} vil ikke blandes ind i herremandens sager; afskriften kommer først frem, når heltene vender tilbage med beviser.`,`{npc3} will not be drawn into the lord’s affairs; the copy only comes out when the heroes return with proof.`)),c(`Wisdom (Survival)`,`medium`,o(`Heltene læser vejret: Tågen kommer før sluddet, og sneen før mørket. De pakker reb, ekstra kapper og fakler og ved, at de skal være på toppen, før lyset går.`,`The heroes read the weather: the fog will come before the sleet, and the snow before dark. They pack rope, spare cloaks and torches, and know they must be on the summit before the light goes.`),o(`Heltene undervurderer vejret og må bruge en halv time på gården under fjeldet på at skaffe reb og varmt tøj.`,`The heroes underestimate the weather and must spend half an hour at the farm below the fell getting rope and warm clothes.`))],fight:!1,alternatives:[o(`Gå direkte op uden omveje: Heltene vinder tid på {villain}, men har kun {npc1}s ord for, hvad der foregår.`,`Head straight up without detours: the heroes gain time on {villain}, but have only {npc1}’s word for what is going on.`),o(`Tag {npc1} med: Den gamle vogter kender hver varde, men kan ikke gå hurtigt og må bæres det sidste stykke; til gengæld farer heltene aldrig vild.`,`Take {npc1} along: the old keeper knows every cairn but cannot walk fast and must be carried the last stretch; in return, the heroes never lose their way.`)],dmNotes:o(`Lad spillerne lægge en sten på elvestenen, før de går. Beskriv skyerne i vest, hver gang de tøver; stormen er uret i dette eventyr, og {villain} er kun den ene af to fjender.`,`Let the players add a stone to the mossy cairn by the river before they go. Describe the clouds in the west whenever they hesitate; the storm is the clock of this adventure, and {villain} is only one of two enemies.`)},middle:[{kind:`rest`,at:`town`,present:[],title:o(`Muldyrene i laden`,`The Mules in the Barn`),summary:o([`Ved den sidste gård under fjeldet står {villain}s muldyr i laden, for herfra er stien for stejl; følget gik videre til fods med slæden for et par timer siden.`,`Fårehyrden på gården har set, hvilken vej de gik, og i muldyrenes pakning ligger en tegning og et brev, der viser, hvad {villain} vil med fjeldet.`,`Det er sidste chance for at få varmen, skaffe reb og vælge vej, før vardestien går op i tågen.`],[`At the last farm below the fell, {villain}’s mules stand in the barn, for from here the path is too steep; the mine owner’s company continued on foot with the sledge a couple of hours ago.`,`The shepherd at the farm saw which way they went, and in the mules’ packs lie a drawing and a letter that show what {villain} wants with the fell.`,`It is the last chance to get warm, find rope and choose a route before the cairn path climbs into the fog.`]),readAloud:o([`Gården ligger krøbet sammen i læ af en stenmur, og røgen fra skorstenen bliver revet vandret af vinden.`,`I laden står seks muldyr med sadlerne på og tygger hø, og en gammel fårehyrde giver dem vand.`,`Over gården forsvinder vardestien op i en grå væg af tåge, og til venstre for den går et smalt fårespor lige op ad urskråningen.`],[`The farm crouches in the lee of a stone wall, and the smoke from its chimney is torn sideways by the wind.`,`In the barn stand six mules, still saddled, chewing hay, and an old shepherd is giving them water.`,`Above the farm the cairn path disappears into a grey wall of fog, and to its left a narrow sheep track runs straight up the scree.`]),details:[o(`I muldyrenes pakning ligger landmålerværktøj, et bundt nye pæle og en tegning af en dæmning over højsøens udløb, og under den et brev fra herremandens forvalter til {villain}. Det viser, hvad det hele handler om: vandet i højsøen og {villain}s mine.`,`In the mules’ packs lie surveying tools, a bundle of new stakes and a drawing of a dam across the outflow of the high lake, and beneath it a letter from the lord’s steward to {villain}. Together they show what all this is about: the water of the high lake and {villain}’s mine.`),o(`Fårehyrden passer muldyrene for en sølvmønt og fortæller gerne, at følget tog vardestien med slæden og fjeldføreren {npc2} forrest, at en af arbejdsfolkene bar en skiferplade svøbt i sækkelærred, og at {villain} spurgte, hvor langt der er fra søens udløb op til Rokkestenen på toppen.`,`The shepherd is minding the mules for a silver coin and readily says that the mine owner’s company took the cairn path with the sledge and {npc2}, the fell guide, in front. One of the workmen carried a slate wrapped in sacking, and {villain} asked how far it is from the lake’s outflow up to the Rocking Stone on the summit.`),o(`Vardestien snor sig sikkert op ad de nederste skråninger; fåresporet går lige op ad urskråningen og sparer en time, men i slud er stenene glatte, og et fald koster mere end tid. Begge veje mødes ved mosen på højfjeldet, hvor tågen ligger efter tre timer (første tik). Gården har reb, vandrestave og varm suppe, og den, der hviler en halv time her, går resten af vejen uden at fryse.`,`The cairn path winds safely up the lower slopes; the sheep track goes straight up the scree and saves an hour, but in sleet the stones are slick, and a fall costs more than time. The two routes meet at the mire on the high fell, where the fog settles after three hours (the first tick). The farm has rope, walking staffs and hot soup, and anyone who rests here for half an hour goes the rest of the way without freezing.`)],checks:[c(`Intelligence (Investigation)`,`easy`,o(`Heltene forstår tegningen: Rykker grænsen ned under søen, kan {villain} dæmme udløbet op, og så løber {town}s elv tør hver sommer.`,`The heroes make sense of the drawing: if the boundary moves below the lake, {villain} can dam the outflow, and then the river of {town} runs dry every summer.`),o(`Tegningen er fuld af tal og streger; heltene ser, at den handler om søen, men ikke hvorfor.`,`The drawing is full of figures and lines; the heroes see that it is about the lake, but not why.`)),c(`Wisdom (Survival)`,`medium`,o(`Heltene ser, at sluddet ikke når urskråningen før om et par timer, og klatrer op ad fåresporet i tide; de vinder en time på {villain}.`,`The heroes judge that the sleet will not reach the scree for a couple of hours and climb the sheep track in time; they gain an hour on {villain}.`),o(`Heltene tager fejl af vejret; sluddet når dem midt på urskråningen, og de må kravle det sidste stykke og mister den time, de ville vinde.`,`The heroes misjudge the weather; the sleet catches them halfway up the scree, and they must crawl the last stretch and lose the hour they meant to gain.`))],fight:!1,alternatives:[o(`Lås laden: Uden muldyrene kan {villain} og arbejdsfolkene ikke komme hurtigt væk fra egnen bagefter, og fårehyrden lover at holde dem tilbage.`,`Lock the barn: without the mules, {villain} and the workmen cannot get away from the district in a hurry afterwards, and the shepherd promises to keep the mules there.`),o(`Spring gården over, og gå videre op ad vardestien: Heltene sparer en halv time, men går uden varmt tøj og reb og uden at vide, hvad {villain} vil.`,`Skip the farm and carry on up the cairn path: the heroes save half an hour, but go without warm clothes or rope, and without knowing what {villain} is after.`)],dmNotes:o(`Gården er et åndehul og et valg. Lad suppen dampe og vinden hyle om hjørnerne, og lad spillerne selv vælge mellem den sikre og den hurtige vej.`,`The farm is a breathing space and a choice. Let the soup steam and the wind howl round the corners, and let the players choose for themselves between the safe way and the fast one.`)},{kind:`exploration`,at:`site`,present:[`npc2`],title:o(`Mosen i tågen`,`The Misty Mire`),summary:o([`Oppe på højfjeldet går vardestien over en stor mose, og efter tre timer (første tik) ligger tågen så tæt, at heltene kun kan se fra den ene varde til den næste.`,`En af varderne er flyttet og peger lige ud i dyndet, og et stykke derfra sidder {npc2}, fjeldføreren, med en forvredet ankel; {villain} efterlod {npc2} her, da fjeldføreren nægtede at flytte varden.`,`Her skal heltene se, at varderne lyver, finde den rigtige vej videre og høre, hvad {villain} vil på toppen.`],[`High on the fell the cairn path crosses a great mire, and after three hours (the first tick) the fog is so thick that the heroes can only see from one cairn to the next.`,`One of the cairns has been moved and points straight into the mud, and a little way off sits {npc2}, the fell guide, with a twisted ankle; {villain} left {npc2} here when the guide refused to move the cairn.`,`Here the heroes must realise that the cairns are lying, find the true way on and hear what {villain} wants on the summit.`]),readAloud:o([`Tågen kommer drivende hen over lyngen, og snart er verden ikke større end et stenkast.`,`Varde efter varde dukker op af det grå, hver af dem en stenhob på højde med en mand, og stien mellem dem er trådt op af mange støvler og en slæde.`,`Ved den næste varde bliver jorden blød, og et sted ude i tågen råber en hæs stemme: "Ikke den vej!"`],[`Fog comes drifting over the heather, and soon the world is no bigger than a stone’s throw.`,`Cairn after cairn looms out of the grey, each a heap of stones the height of a man, and the path between them is trampled by many boots and a sledge.`,`At the next cairn the ground turns soft, and somewhere out in the fog a hoarse voice shouts: "Not that way!"`]),details:[o(`Den flyttede varde står på frisk, nedtrådt lyng, og laven sidder på den forkerte side af stenene: på læsiden, ikke mod vinden. Hvor den stod før, er der en firkant af bar, gul jord tyve skridt længere mod højre, og i lyngen ved den ligger en messingpolet fra {villain}s mine, stemplet med to krydsede hamre. Følger heltene den falske varde, ender de i dyndet, og det koster mindst en halv time at komme op igen.`,`The moved cairn stands on freshly trampled heather, and the lichen grows on the wrong side of its stones: on the lee side, not facing the wind. Where it used to stand there is a square of bare, yellow earth twenty paces to the right, and in the heather beside it lies a brass token from {villain}’s mine, stamped with two crossed hammers. If the heroes follow the false cairn, they end up in the mud, and getting out again costs at least half an hour.`),o(`{npc2} blev hyret til at føre følget op og skulle flytte varden, så den, der kom efter, gik ud i mosen; da fjeldføreren nægtede, gjorde arbejdsfolkene det selv, skubbede fjeldføreren omkuld og gik videre. Fjeldføreren fortæller, at {villain} er på vej til toppen ved Rokkestenen for at grave den ægte skifer op under den sidste varde, og at en ny varde skal bygges over en falsk plade ved søens udløb.`,`{npc2} was hired to guide the mine owner’s company up and was told to move the cairn so that anyone following would walk into the mire; when the guide refused, the workmen did it themselves, knocked the guide down and went on. The guide says that {villain} is on the way to the summit by the Rocking Stone to dig the true slate out from under the last cairn, and that a new cairn is to be built over a false slate at the lake’s outflow.`),o(`Hinsides mosen forlader slædesporet og de mange støvler varderne og går lige op mod ryggen over højsøen. {npc2} kan ikke gå, men kan sidde på en helts ryg og vise vejen; ellers må fjeldføreren vente her, og skal fjeldføreren overleve stormen, må nogen hente {npc2} på vejen ned.`,`Beyond the mire the tracks of the sledge and the many boots leave the cairns and head straight up toward the ridge above the high lake. {npc2} cannot walk but can ride on a hero’s back and show the way; otherwise the guide must wait here, and if the guide is to survive the storm, someone must fetch {npc2} on the way down.`)],checks:[c(`Wisdom (Survival)`,`medium`,o(`Heltene ser, at laven vender forkert, og finder firkanten af bar jord, hvor varden stod; de går uden om mosen uden at miste tid.`,`The heroes notice the lichen facing the wrong way and find the square of bare earth where the cairn stood; they go around the mire without losing time.`),o(`Heltene følger den falske varde ud i dyndet og må trække hinanden op; det koster en halv time og noget af udstyret.`,`The heroes follow the false cairn into the mud and must haul each other out; it costs half an hour and some of the gear.`)),c(`Wisdom (Medicine)`,`easy`,o(`Heltene binder {npc2}s ankel, og fjeldføreren kan humpe med og vise en skjult rende, der fører op til toppen bag Rokkestenen.`,`The heroes bind {npc2}’s ankle, and the guide can limp along and show a hidden gully that leads up to the summit behind the Rocking Stone.`),o(`{npc2} kan ikke støtte på foden og må bæres eller blive her i kulden.`,`{npc2} cannot put weight on the injured foot and must be carried or left here in the cold.`))],fight:!1,alternatives:[o(`Sæt den falske varde tilbage, hvor den stod: Det tager en halv time, men så farer ingen andre vild i mosen, og heltene har selv en sikker vej ned i stormen.`,`Put the false cairn back where it stood: it takes half an hour, but then no one else goes astray in the mire, and the heroes themselves have a safe way down in the storm.`),o(`Gå på line: Bundet sammen med reb kan heltene gå lige over mosen efter slædesporet; den, der synker, bliver trukket op, så længe nogen holder fast.`,`Rope up: tied together, the heroes can cross the mire straight along the sledge tracks; whoever sinks is pulled out, as long as someone holds on.`)],dmNotes:o(`Lad tågen gøre arbejdet: Beskriv kun det, heltene kan se, én varde ad gangen. Mosen skal koste tid, ikke liv, og tid er det eneste, {villain} har brug for. {npc2}s råb i tågen er heltenes første rigtige hjælp på fjeldet.`,`Let the fog do the work: describe only what the heroes can see, one cairn at a time. The mire should cost time, not lives, and time is all {villain} needs. {npc2}’s shout in the fog is the heroes’ first real help on the fell.`)},{kind:`combat`,at:`site`,present:[],title:o(`Lejren ved søens udløb`,`The Camp at the Outflow`),summary:o([`Hvor højsøen løber ud i {town}s elv, er {villain}s arbejdsfolk ved at bygge en ny varde af friske sten, og ved siden af står deres vindskjul med slæden og værktøjet.`,`Under den nye varde ligger den falske skiferplade, og nu har nogle {foe} fundet lejren og angriber i sluddet.`,`Her kan heltene sikre beviset på svindelen, men de må kæmpe for det, mens lyset går.`],[`Where the river of {town} flows out of the high lake, {villain}’s workmen are building a new cairn of fresh stones, and beside it stands their windbreak with the sledge and the tools.`,`Under the new cairn lies the false slate, and now some {foe} have found the camp and attack in the sleet.`,`Here the heroes can secure the proof of the fraud, but must fight for it as the light fades.`]),readAloud:o([`Søen ligger sort og stille under ryggen, og ved udløbet står en ny varde, hvis sten stadig er lyse på undersiden.`,`Bag et vindskjul af sejldug står en tom slæde, og en hakke ligger tabt i lyngen, som om nogen er løbet i en fart.`,`Oppe fra ryggen over søen lyder slag af jern mod sten, og nærmere, mellem stenene ved bredden, bevæger noget sig.`],[`The lake lies black and still beneath the ridge, and at its outflow stands a new cairn whose stones are still pale on their undersides.`,`Behind a windbreak of sailcloth stands an empty sledge, and a pick lies dropped in the heather, as if someone had run off in a hurry.`,`From the ridge above the lake comes the ring of iron on stone, and closer, among the rocks along the shore, something is moving.`]),details:[o(`Nogle {foe}, der har deres hule ved toppen, har fundet lejren. De tjener ikke {villain}, men angriber alt, der er her, og trækker sig op mod toppen, når halvdelen af dem er faldet. Er heltene her, før der er gået seks timer (andet tik), står arbejdsfolkene endnu og stabler sten, men de løber ned ad fjeldet, så snart kampen begynder.`,`Some {foe} that have their lair near the summit have found the camp. They do not serve {villain}, but attack anyone here, and fall back toward the summit once half of them are down. If the heroes arrive before six hours have passed (the second tick), the workmen are still stacking stones, but they run off down the fell as soon as the fight begins.`),o(`Under den nye varde ligger den falske skiferplade, hugget med gamle bogstaver: Grænsen går til den sidste varde ved højsøens udløb. Rillerne er stadig hvide af frisk stenstøv, og teksten er ord for ord den, {npc3} har en afskrift af.`,`Under the new cairn lies the false slate, cut in old-style letters: the boundary runs to the last cairn at the outflow of the high lake. The grooves are still white with fresh stone dust, and the text is word for word the one {npc3} kept a copy of.`),o(`Fra lejren fører friske skrammer og tabte sten op ad ryggen til toppen og Rokkestenen, en halv times stigning. Har heltene {npc2} med, kan fjeldføreren vise den skjulte rende, der kommer op bag Rokkestenen uden at blive set.`,`From the camp, fresh scrapes and dropped stones lead up the ridge to the summit and the Rocking Stone, a half-hour climb. If the heroes have {npc2} along, the guide can show the hidden gully that lets them come up behind the Rocking Stone unseen.`)],checks:[c(`Strength (Athletics)`,`medium`,o(`Heltene vælter den nye varde og får den falske plade fri, før nogen når dem; nu har de beviset for svindelen.`,`The heroes topple the new cairn and pull the false slate free before anything reaches them; now they hold the proof of the fraud.`),o(`Stenene er frosset fast i jorden; heltene får først pladen fri efter kampen, og det koster en halv time.`,`The stones are frozen into the ground; the heroes only get the slate free after the fight, and it costs half an hour.`)),c(`Wisdom (Perception)`,`easy`,o(`Heltene ser bevægelsen mellem stenene i tide og tager imod angrebet med ryggen mod vindskjulet.`,`The heroes spot the movement among the rocks in time and meet the attack with their backs to the windbreak.`),o(`Angrebet kommer ud af sluddet fra to sider, og den, der står ved varden, er alene.`,`The attack comes out of the sleet from two sides, and whoever stands by the cairn is alone.`))],fight:!0,alternatives:[o(`Lok {foe} væk med larm eller lys langs bredden, og vælt varden, mens de leder.`,`Lure the {foe} away with noise or light along the shore, and topple the cairn while they search.`),o(`Lad den nye varde stå, og skynd jer op mod toppen: Heltene sparer tiden her, men har intet bevis på svindelen, hvis skiferen på toppen går tabt.`,`Leave the new cairn standing and hurry on toward the summit: the heroes save the time here, but have no proof of the fraud if the slate on the summit is lost.`)],dmNotes:o(`Kampen foregår i slud og kulde: Den, der står stille, fryser. Den falske plade er værdifuld som bevis, men tung; lad spillerne mærke valget mellem at bære den og at nå toppen i tide.`,`The fight takes place in sleet and cold: whoever stands still freezes. The false slate is valuable as proof, but heavy; let the players feel the choice between carrying it and reaching the summit in time.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:o(`Den sidste varde`,`The Last Cairn`),summary:o([`På toppen af {place}, ved Rokkestenen, står det, der er tilbage af den sidste varde: en halv stenhob og et hul, hvor {villain} graver efter den gamle grænseskifer, mens stormen kommer.`,`Lige ved siden af ligger et gammelt fårehus i ruiner, hvor {boss} og nogle {foe} har deres hule; de tjener ingen og angriber alle på toppen, og arbejdsfolkene er flygtet.`,`Heltene skal redde skiferen, få {villain} med ned og selv overleve stormen.`],[`On the summit of {place}, by the Rocking Stone, stands what is left of the last cairn: half a heap of stones and a pit where {villain} is digging for the old boundary slate as the storm comes on.`,`Right beside it lies a ruined sheep shelter where {boss} and some {foe} have their lair; they serve no one and attack everyone on the summit, and the workmen have fled.`,`The heroes must save the slate, bring {villain} down and survive the storm themselves.`]),readAloud:o([`Toppen er en bar ryg af sten, hvor vinden river i kapperne, og sneen er begyndt at fyge.`,`Ved en stor sten, der vipper på kanten af ryggen, ligger vardens sten spredt i en bunke, og i hullet under dem knæler en skikkelse i en fin rejsekappe med et brækjern i hånden.`,`Bag hullet, i ruinen af et gammelt fårehus, rører noget sig.`],[`The summit is a bare spine of rock where the wind tears at your cloaks and the snow has begun to drift.`,`By a great stone that rocks on the edge of the ridge, the cairn’s stones lie scattered in a heap, and in the pit beneath them kneels a figure in a fine travelling cloak, crowbar in hand.`,`Behind the pit, in the ruin of an old sheep shelter, something stirs.`]),details:[o(`{boss} og nogle {foe} har deres hule i fårehuset. De er ude på fjeldet, da {villain} kommer, men vender hjem med stormen, og når heltene står på toppen, er de der også. De tjener ingen og angriber alle på toppen, også {villain}, der er mere bange for dem end for heltene.`,`{boss} and some {foe} have their lair in the shelter. They are out on the fell when {villain} arrives, but come home with the storm, and by the time the heroes stand on the summit, they are there too. They serve no one and attack everyone on the summit, even {villain}, who is more afraid of them than of the heroes.`),o(`Skiferen ligger i et leje af sten under vardens nederste lag. Når heltene kommer, har {villain} næsten gravet den fri; ved mørkets frembrud (tredje tik) slår {villain} den i stykker med brækjernet og kaster stykkerne ud over kanten. Selv brækket fortæller skiferen sandheden, hvis heltene samler stykkerne, før sneen dækker dem.`,`The slate lies in a bed of stones under the bottom course of the cairn. When the heroes arrive, {villain} has almost dug it free; at nightfall (the third tick) {villain} smashes it with the crowbar and flings the pieces over the edge. Even broken, the slate tells the truth if the heroes gather the pieces before the snow covers them.`),o(`{villain} kender ikke fjeldet og har jaget den eneste fører bort, der gør; i stormen kan {villain} ikke komme ned uden hjælp, og stillet over for {boss} eller kulden vil {villain} bytte alt for en vej ned: skiferen, en tilståelse, ja selv minen. Rokkestenen vipper, hvis nogen skubber til den, og falder den, kan den spærre fårehuset.`,`{villain} does not know the fell and has driven off the only guide who does; in the storm {villain} cannot get down without help, and faced with {boss} or the cold, {villain} will trade anything for a way down: the slate, a confession, even the mine. The Rocking Stone rocks if someone pushes it, and if it falls, it can block the shelter.`),o(`Kommer heltene før seks timer (andet tik), når de toppen før {villain} og kan vente bag Rokkestenen; kommer de mellem seks og ti timer, graver {villain}, og skiferen er hel; efter ti timer (tredje tik) er den smadret, og kun stykkerne i sneen er tilbage.`,`If the heroes arrive before six hours have passed (the second tick), they reach the summit before {villain} and can wait behind the Rocking Stone; between six and ten hours, {villain} is digging and the slate is whole; after ten hours (the third tick) it is smashed, and only the pieces in the snow are left.`)],checks:[c(`Dexterity (Acrobatics)`,`medium`,o(`En helt springer ned i hullet og river skiferen fra {villain}, før brækjernet rammer den.`,`A hero leaps down into the pit and wrenches the slate away from {villain} before the crowbar strikes it.`),o(`Brækjernet rammer, og skiferen knækker i tre stykker; heltene må samle dem i sneen, mens kampen raser.`,`The crowbar strikes, and the slate breaks into three pieces; the heroes must gather them from the snow while the fight rages.`)),c(`Wisdom (Survival)`,`hard`,o(`Heltene finder læ bag Rokkestenen og får alle, også {villain}, ned til lejren ved søen, før stormen gør toppen dødelig.`,`The heroes find shelter behind the Rocking Stone and get everyone, {villain} included, down to the camp by the lake before the storm makes the summit deadly.`),o(`Stormen lukker toppen; heltene må grave sig ned i hullet under varden og vente natten ud, og kulden tærer på hver eneste helt.`,`The storm closes in on the summit; the heroes must dig into the pit under the cairn and wait out the night, and the cold wears down every hero.`))],fight:!0,alternatives:[o(`Tilbyd {villain} en vej ned: Med stormen i ryggen giver {villain} skiferen fra sig og går med ned som heltenes fange hellere end at blive alene på toppen.`,`Offer {villain} a way down: with the storm at their back, {villain} hands over the slate and goes down as the heroes’ prisoner rather than be left alone on the summit.`),o(`Skub til Rokkestenen: Den spærrer fårehuset, så {boss} og de andre er fanget, mens heltene tager skiferen og {villain}; men stenen kan også rive resten af varden med sig.`,`Push the Rocking Stone: it blocks the shelter, trapping {boss} and the others while the heroes take the slate and {villain}; but the stone may also take the rest of the cairn with it.`)],dmNotes:o(`Stormen er den tredje part i kampen: Lad sneen tætne for hver runde, og lad den, der falder, ligge i kulden. Husk, at målet er skiferen, ikke sejren, og at {villain} kan blive den, heltene må redde.`,`The storm is the third party in the fight: let the snow thicken each round, and let whoever falls lie in the cold. Remember that the goal is the slate, not the victory, and that {villain} may become the one the heroes have to save.`)}},ue=e({kernel:()=>me,scenes:()=>he}),de=e=>Array.isArray(e)?e.join(` `):e,l=(e,t)=>({da:de(e),en:de(t)}),fe=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),u=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},pe=(e,t,n)=>({when:e,event:t,sign:n}),d=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),me={id:`siege-the-mill-at-dawn`,titles:[l(`Møllen ved daggry`,`The Mill at Dawn`),l(`Forræderen i {place}`,`The Traitor in {place}`),l(`Sand i sækkene`,`Sand in the Sacks`)],missions:[`siege`,`intrigue`],foes:`hirelings`,roles:{npc1:l(`en bonde fra landsbyen ved {place}`,`a farmer from the hamlet by {place}`),npc2:l(`en møllersvend, der har tjent hos {villain} i ti år`,`a journeyman miller who has worked for {villain} for ten years`),npc3:l(`en fremmed kræmmer, der slap ind lige før porten blev slået i`,`a travelling peddler who slipped in just before the gate was barred`),villain:l(`en møller, som hele dalen betror sin såsæd`,`a miller the whole valley trusts with its seed corn`)},hook:l(`{npc1}, en bonde fra landsbyen ved {place}, når {town} ved solnedgang på en skumvåd hest og beder heltene ride med tilbage og holde {place}, den befæstede mølle, til fogedens ryttere kan komme ved solopgang.`,`{npc1}, a farmer from the hamlet by {place}, reaches {town} at sunset on a lathered horse and begs the heroes to ride back and hold {place}, the walled mill, until the reeve’s riders can arrive at sunrise.`),people:{npc1:{wants:l(`Vil have sine børn og naboer levende gennem natten og såsæden i jorden til foråret.`,`Wants their children and neighbours alive through the night, and the seed corn in the ground in spring.`),secret:l(`Lagde mærke til pramme, der lå dybt i vandet ved den nederste bådebro sidste efterår, men tav, fordi {villain} samme uge eftergav landsbyen dens gæld til møllen.`,`Noticed barges lying low in the water at the lower landing last autumn, but kept quiet because that same week {villain} forgave the hamlet its debts to the mill.`)},npc2:{wants:l(`Vil redde møllen og sin mesters gode navn og er begyndt at frygte, at det ikke kan lade sig gøre på én gang.`,`Wants to save the mill and their master’s good name, and has begun to fear that the two cannot both be saved.`),secret:l(`Bar selv sække med sand op på kornloftet i ugerne efter høst, fordi {villain} sagde, at det var ballast til det gamle gulv, og tør ikke sige det til nogen.`,`Carried sacks of sand up to the granary in the weeks after harvest because {villain} said it was ballast for the old floor, and is afraid to tell anyone.`)},npc3:{wants:l(`Vil overleve natten uden at blive kastet ud over muren og være væk fra dalen ved første lys.`,`Wants to live through the night without being thrown over the wall, and to be gone from the valley at first light.`),secret:l(`Har en pakke smuglervarer i kræmmerkassen og frygter fogedens ryttere mere end angriberne; derfor har {npc3} ikke sagt et ord om det, der skete ved jernristen i skumringen.`,`Carries a parcel of smuggled goods in their pack and fears the reeve’s riders more than the attackers, which is why {npc3} has not said a word about what happened at the iron grating at dusk.`)}},premise:l([`Hver vinter ligger hele dalens såsæd på kornloftet i {place}, den gamle befæstede vandmølle ved åen, og {villain}, mølleren, har nøglen.`,`Sidste efterår, da kornprisen var skyhøj nedstrøms, solgte {villain} halvdelen i al hemmelighed og fyldte de bageste sække med avner og sand.`,`For at ingen nogensinde skal tælle sækkene, har {villain} lokket {boss} og nogle {foe} til dalen med et løfte: Den nat, landsbyens folk søger ly i møllen, bliver vejen ind åbnet indefra, og kornloftet skal brænde.`,`Den nat er i nat: Landsbyen har stænget sig inde i {place}, og fogedens ryttere i {town} kan tidligst være der ved solopgang.`],[`Every winter the whole valley’s seed corn lies in the granary of {place}, the old walled watermill by the river, and {villain}, the miller, holds the key.`,`Last autumn, when grain fetched a fortune downriver, {villain} secretly sold half the seed corn and filled the back sacks with chaff and sand.`,`So that nobody will ever count the sacks, {villain} has lured {boss} and some {foe} to the valley with a promise: on the night the hamlet’s people take refuge in the mill, the way in will be opened from inside, and the granary is to burn.`,`That night is tonight: the hamlet has barred itself inside {place}, and the reeve’s riders from {town} cannot be there before sunrise.`]),goal:l(`Forsvar {place} til solopgang, find forræderen indenfor, og hold angriberne ude af hjulhuset og ilden væk fra kornloftet.`,`Hold {place} until sunrise, find the traitor inside and keep the attackers out of the wheel house and the fire away from the granary.`),objective:{target:l(`Dalens såsæd, to hundrede sække på kornloftet over hjulhuset i {place}`,`The valley’s seed corn, two hundred sacks in the granary above the wheel house of {place}`),state:l([`De forreste rækker er godt korn, de bageste avner og sand, og {villain} har vædet de forreste med lampeolie.`,`Nede i graven under hjulet er jernristen over møllerenden savet løs, og {boss} og resten af angriberne venter på, at hjulet står stille.`],[`The front rows are good grain, the back rows chaff and sand, and {villain} has soaked the front rows in lamp oil.`,`Down in the pit beneath the wheel, the iron grating over the millrace has been sawn loose, and {boss} and the rest of the attackers are waiting for the wheel to stop.`]),resolution:l([`Hold hjulet i gang, eller forsvar hjulhuset mod {boss} til solopgang, og hold ilden væk fra kornloftet; skær en af de bageste sække op foran landsbyens folk, så falder {villain}s historie sammen.`,`Kan heltene ikke holde det hele, må de vælge mellem risten og kornet.`],[`Keep the wheel turning, or hold the wheel house against {boss} until sunrise, and keep the fire from the granary; cut open one of the back sacks in front of the hamlet’s people, and {villain}’s story falls apart.`,`If the heroes cannot hold it all, they must choose between the grating and the grain.`])},villain:{want:l(`At beholde sølvet fra det solgte korn, møllen og navnet som dalens ærlige møller, og at ingen nogensinde tæller sækkene på kornloftet.`,`To keep the silver from the secretly sold grain, the mill and a reputation as the valley’s honest miller, and to make sure nobody ever counts the sacks in the granary.`),plan:l([`Først solgte {villain} halvdelen af såsæden nedstrøms og fyldte de bageste sække med avner og sand.`,`Så lokkede {villain} angriberne til dalen, lod dem brænde en gård i udkanten og fik landsbyens folk til at søge ly i møllen, som de altid har gjort.`,`I timen før daggry standser {villain} hjulet, lukker slusen og løfter den løse jernrist, så {boss} og resten kan gå ind ad den tørlagte møllerende, og i virvaret tænder {villain} olien på kornloftet.`],[`First, {villain} sold half the seed corn downriver and filled the back sacks with chaff and sand.`,`Then {villain} lured the attackers to the valley, let them burn a farm on its edge and had the hamlet’s people take refuge in the mill, as they always have.`,`In the hour before dawn {villain} stops the wheel, closes the sluice and lifts the loose iron grating so that {boss} and the rest can walk in along the drained millrace, and in the confusion {villain} lights the oil in the granary.`]),weakness:l([`{villain} er ingen kriger og frygter angriberne næsten lige så meget som heltene; aftalen holder kun, så længe vejen ind bliver åbnet til tiden.`,`Og de bageste sække er fulde af sand: Én opskåret sæk foran landsbyens folk viser alle, hvad {villain} har gjort, og så har {villain} intet tilbage at kæmpe for.`],[`{villain} is no fighter and is almost as afraid of the attackers as of the heroes; the bargain only holds as long as the way in opens on time.`,`And the back sacks are full of sand: one sack cut open in front of the hamlet’s people shows everyone what {villain} has done, and then {villain} has nothing left to fight for.`])},stakes:l(`Går risten op, og brænder kornloftet, mister dalen på én nat sin såsæd og landsbyen alt, hvad den har båret med ind i møllen: Der bliver intet sået til foråret, familier må forlade dalen, og {villain} bliver ynket som mølleren, der mistede alt for at forsvare dem.`,`If the grating opens and the granary burns, in one night the valley loses its seed corn and the hamlet everything it carried into the mill: nothing is sown in spring, families must leave the valley and {villain} is pitied as the miller who lost everything defending them.`),clock:{start:l(`Solnedgang. {npc1} når {town} på en skumvåd hest: Landsbyen har stænget sig inde i {place}, angriberne samler sig i skoven på den anden side af åen, og fogedens ryttere kan tidligst være der ved solopgang, om tolv timer.`,`Sunset. {npc1} reaches {town} on a lathered horse: the hamlet has barred itself inside {place}, the attackers are gathering in the woods across the river and the reeve’s riders cannot be there before sunrise, twelve hours from now.`),ticks:[pe(l(`Efter 2 timer (da det er blevet helt mørkt)`,`After 2 hours (when it is fully dark)`),l(`Første stormløb: Nogle {foe} kommer over vadestedet og kaster sig mod porten, og bagefter viser det sig, at bommen for den lille låge ved stalden er løftet af indefra.`,`The first assault: some {foe} come across the ford and throw themselves at the gate, and afterwards it turns out that the bar of the postern by the stable was lifted off from inside.`),l(`Uro langs den anden bred og hunde, der gør i gården; bagefter ligger bommen fra den lille låge i halmen.`,`Movement along the far bank and dogs barking in the yard; afterwards the bar of the postern lies in the straw.`)),pe(l(`Efter 6 timer (ved midnat)`,`After 6 hours (at midnight)`),l(`{villain} giver tegn fra lugen på kornloftet med en afskærmet lygte: Aftalen står ved magt, og hjulet standser i timen før daggry.`,`{villain} signals from the granary hatch with a hooded lantern: the bargain stands, and the wheel will stop in the hour before dawn.`),l(`Et lys blinker tre gange i lugen på kornloftet, hvor ingen burde være, og på den anden side af åen blusser et bål op som svar.`,`A light blinks three times at the granary hatch, where nobody should be, and across the river a fire flares up in answer.`)),pe(l(`Efter 11 timer (i timen før daggry)`,`After 11 hours (in the hour before dawn)`),l(`{villain} standser hjulet, lukker slusen og løfter jernristen; {boss} og resten af angriberne går ind ad den tørlagte møllerende, og olien på kornloftet bliver tændt.`,`{villain} stops the wheel, closes the sluice and lifts the grating; {boss} and the rest of the attackers walk in along the drained millrace, and the oil in the granary is lit.`),l(`Det store hjul står stille for første gang hele natten, og i stilheden høres vand, der løber bort under møllen.`,`The great wheel stops for the first time all night, and in the silence water can be heard draining away beneath the mill.`))],deadline:l(`Efter 11 timer, i timen før daggry, er det for sent at standse planen i det stille: Hjulet står stille, risten går op, og angriberne er inde i {place}. Holder ingen hjulhuset og kornloftet, er såsæden aske, når fogedens ryttere når frem ved solopgang en time senere.`,`After 11 hours, in the hour before dawn, it is too late to stop the plan quietly: the wheel stops, the grating goes up and the attackers are inside {place}. If no one holds the wheel house and the granary, the seed corn is ash by the time the reeve’s riders arrive at sunrise an hour later.`)},clues:{who:[u(`town`,l(`Ved bådebroen i {town} viser en prammand den fragtseddel, {villain} betalte med, da halvfems sække såsæd sidste efterår blev lastet om natten ved {place} og sejlet ned ad åen.`,`At the landing in {town}, a bargeman shows the freight chit {villain} settled when ninety sacks of seed corn were loaded by night at {place} last autumn and shipped downriver.`),l(`{villain} har solgt af dalens såsæd i al hemmelighed; der kan ikke ligge så meget på kornloftet, som dalen tror.`,`{villain} has secretly sold part of the valley’s seed corn; the granary cannot hold as much as the valley believes.`),fe([`Fragtseddel. Fra den nederste bådebro ved {place}, lastet ved nattetid:`,`90 sække såsæd til handelshuset nedstrøms.`,`Fragten betalt af {villain}, møller. Ikke et ord til dalen.`],[`Freight chit. From the lower landing at {place}, loaded by night:`,`90 sacks of seed corn for the merchant house downriver.`,`Freight paid by {villain}, miller. Not a word to the valley.`])),u(`site`,l(`På kornloftet er de forreste sække fulde af godt korn, men skærer man en af de bageste op, vælter der avner og sand ud under et tyndt lag korn.`,`In the granary the front sacks hold good grain, but cut open one of the back sacks and chaff and sand pour out from under a thin layer of grain.`),l(`Halvdelen af såsæden er væk, og kun den, der har nøglen til kornloftet, kan have taget den: {villain}.`,`Half the seed corn is gone, and only whoever holds the key to the granary could have taken it: {villain}.`)),u(`site`,l(`Efter stormløbet ligger bommen fra den lille låge ved stalden i halmen, løftet af indefra, og melede fodspor fører fra lågen hen til møllehuset.`,`After the assault the bar of the postern by the stable lies in the straw, lifted off from inside, and floury footprints lead from the postern to the mill house.`),l(`Det var ikke en fremmed, der åbnede for angriberne, men en, der går i mel hver dag.`,`It was no stranger who opened the way for the attackers, but someone who walks in flour every day.`)),u(`site`,l(`{npc2}, møllersvenden, fortæller, at {villain} en nat sidste efterår sendte hele husstanden til høstgilde i landsbyen og blev alene tilbage, og at nøglen til kornloftet siden har hængt i en snor om {villain}s hals.`,`{npc2}, the journeyman, says that one night last autumn {villain} sent the whole household to the harvest feast in the hamlet and stayed behind alone, and that the granary key has hung on a cord round {villain}’s neck ever since.`),l(`{villain} tømte kornloftet den nat og lader ingen komme derop, så sækkene aldrig bliver talt.`,`{villain} emptied the granary that night and lets nobody up there, so that the sacks are never counted.`))],where:[u(`town`,l(`Den gamle møllebygger, der bor ved bådebroen i {town}, har stadig sin tegning af {place}: Møllerenden løber ud under muren gennem en bue, der er lukket med en jernrist.`,`The old millwright who lives by the landing in {town} still has their drawing of {place}: the millrace runs out under the wall through an arch closed with an iron grating.`),l(`Står hjulet stille og slusen nede, er møllerenden en vej ind i {place} under muren.`,`When the wheel stands still and the sluice is down, the millrace is a way into {place} under the wall.`),fe([`{place}, hjulhuset: Renden løber ud under muren gennem buen mod øst.`,`Jernrist for buen, seks bolte, sat i af mig.`,`Står slusen nede, er renden tør til knæet, og en mand kan gå ind under muren. Lad den aldrig stå nede om natten.`],[`{place}, the wheel house: the race runs out under the wall through the east arch.`,`Iron grating across the arch, six bolts, set by me.`,`With the sluice down the race is only knee-deep, and a man can walk in under the wall. Never leave it down at night.`])),u(`site`,l(`Nede i graven under hjulet er fire af de seks bolte i jernristen savet over og smurt ind i fedt og mel, så snittene ikke skinner.`,`Down in the pit beneath the wheel, four of the six bolts in the iron grating are sawn through and smeared with grease and flour so that the cuts do not shine.`),l(`Risten kan løftes, så snart hjulet står stille og renden løber tør; det er dér, angriberne skal ind.`,`The grating can be lifted as soon as the wheel stops and the race runs dry; that is where the attackers are to come in.`)),u(`site`,l(`På kornloftet lugter de forreste sække af lampeolie, og ved lugen ud mod åen står en afskærmet lygte, endnu varm.`,`In the granary the front rows of sacks reek of lamp oil, and by the hatch facing the river stands a hooded lantern, still warm.`),l(`Kornloftet skal brænde, og nogen giver tegn til angriberne fra lugen.`,`The granary is meant to burn, and someone signals to the attackers from the hatch.`)),u(`site`,l(`{npc3}, kræmmeren, som alle mistænker, så i skumringen fra åbredden {villain} stå med en sav og en lygte ved jernristen, hvor møllerenden løber ud under muren.`,`{npc3}, the peddler everyone suspects, saw {villain} from the riverbank at dusk, standing with a saw and a lantern at the iron grating where the millrace runs out under the wall.`),l(`Angriberne skal ind ad møllerenden under muren, og {villain} har selv gjort vejen klar.`,`The attackers are to come in by the millrace under the wall, and {villain} personally made the way ready.`))]},endings:{success:l(`Kornloftet står, risten er boltet fast, og da fogedens ryttere når {place} ved solopgang, flygter de sidste angribere over åen. Sandet fra de bageste sække bliver hældt ud i møllegården foran hele landsbyen, og {villain} bliver ført bort til {town}. Dalen har kun halvt så meget såsæd, som den troede, men {npc1} beder heltene blive til såningen og hjælpe med at hente resten tilbage fra handelshuset nedstrøms.`,`The granary stands and the grating is bolted fast; when the reeve’s riders reach {place} at sunrise, the last attackers flee across the river. The sand from the back sacks is poured out in the mill yard before the whole hamlet, and {villain} is taken away to {town}. The valley has only half the seed corn it thought it had, but {npc1} asks the heroes to stay until the sowing and help win the rest back from the merchant house downriver.`),partial:l(`Møllen holder til solopgang, men ilden når en del af kornloftet, og {villain} slipper ud ad møllerenden i virvaret. Det, der er tilbage af såsæden, rækker til de fleste gårde, og alle ved nu, at kornet var halvt sand; men uden mølleren kan ingen få sølvet tilbage, og {villain} er et sted nedstrøms med en fuld pung.`,`The mill holds until sunrise, but the fire reaches part of the granary, and {villain} escapes along the millrace in the confusion. What is left of the seed corn is enough for most farms, and everyone now knows the grain was half sand; but without the miller nobody can get the silver back, and {villain} is somewhere downriver with a full purse.`),failure:l(`I timen før daggry går risten op, og kornloftet brænder. Da fogedens ryttere når frem ved solopgang, er såsæden aske, og angriberne er væk med landsbyens sølv. {villain} står sodet og grædende i gården og bliver ynket som mølleren, der mistede alt, og til foråret må halvdelen af gårdene i dalen sælge jord for at købe korn, ofte til {villain}.`,`In the hour before dawn the grating goes up and the granary burns. When the reeve’s riders arrive at sunrise, the seed corn is ash and the attackers are gone with the hamlet’s silver. {villain} stands sooty and weeping in the yard and is pitied as the miller who lost everything, and in spring half the farms in the valley must sell land to buy seed, often to {villain}.`)}},he={opening:{kind:`opening`,at:`town`,present:[`npc1`],title:l(`Kroen ved bådebroen`,`The Inn by the Landing`),summary:l([`Ved solnedgang kommer {npc1}, en bonde fra landsbyen ved {place}, ridende til kroen ved bådebroen i {town} på en skumvåd hest.`,`Angribere har brændt en gård i dalen, landsbyens folk har stænget sig inde i {place}, den gamle befæstede mølle, og fogedens ryttere kan tidligst være der ved solopgang.`,`{npc1} beder heltene ride med tilbage og holde møllen natten igennem; ved bådebroen kan de få et par svar mere, men hver samtale koster tid.`],[`At sunset {npc1}, a farmer from the hamlet by {place}, rides up to the inn by the landing in {town} on a lathered horse.`,`Attackers have burned a farm in the valley, the hamlet’s people have barred themselves inside {place}, the old walled mill, and the reeve’s riders cannot get there before sunrise.`,`{npc1} begs the heroes to ride back and hold the mill through the night; at the landing they can get a few more answers, but every conversation costs time.`]),readAloud:l([`Solen går ned over åen, og pramme ligger fortøjet ved bådebroen.`,`En hest kommer i fuld galop ad vejen langs åen, hvid af skum om munden, og rytteren springer af foran kroen og råber om hjælp.`,`Langt oppe ad dalen stiger en tynd søjle af røg mod den røde himmel.`],[`The sun is going down over the river, and barges lie moored at the landing.`,`A horse comes at full gallop along the river road, white with foam at the mouth, and its rider leaps down in front of the inn, shouting for help.`,`Far up the valley a thin column of smoke rises against the red sky.`]),details:[l(`{npc1} fortæller: I går brændte angriberne en gård i udkanten af dalen, og i morges fik {villain}, mølleren, landsbyens folk til at søge ly i {place} med deres dyr og deres sølv, som de altid har gjort. Fogeden i {town} sender ryttere ved første lys, ikke før.`,`{npc1} explains: yesterday the attackers burned a farm on the edge of the valley, and this morning {villain}, the miller, had the hamlet’s people take refuge in {place} with their animals and their silver, as they always have. The reeve of {town} will send riders at first light, not before.`),l(`Ved bådebroen kan heltene få to svar, og hvert koster en halv time: en prammand på kroen, der sidste efterår sejlede halvfems sække såsæd fra {place} ned ad åen om natten, og den gamle møllebygger, der byggede møllehjulet om og stadig har sin tegning af møllen.`,`At the landing two people can give the heroes answers, at half an hour each: a bargeman at the inn who shipped ninety sacks of seed corn downriver from {place} by night last autumn, and the old millwright who rebuilt the mill wheel and still has their drawing of the mill.`),l(`Rider heltene straks, er de ved {place} efter halvanden time, lige før det første stormløb. Bliver de i byen, kommer de frem midt i det og må kæmpe sig ind gennem porten.`,`If the heroes ride at once, they reach {place} in an hour and a half, just before the first assault. If they linger in town, they arrive in the middle of it and must fight their way in at the gate.`)],checks:[d(`Charisma (Persuasion)`,`medium`,l(`Prammanden viser fragtsedlen og fortæller, at sækkene blev lastet i lygteskær ved den nederste bådebro, med mølleren alene på broen.`,`The bargeman shows the freight chit and says the sacks were loaded by lantern light at the lower landing, with the miller alone on the jetty.`),l(`Prammanden trækker på skuldrene: En last er en last. Heltene får kun at vide, at der gik korn fra {place} om natten sidste efterår.`,`The bargeman shrugs: a load is a load. The heroes learn only that grain left {place} by night last autumn.`)),d(`Intelligence (Investigation)`,`medium`,l(`På møllebyggerens tegning ser heltene buen, hvor møllerenden løber ud under muren, lukket med en jernrist med seks bolte: Står slusen nede, er renden tør.`,`On the millwright’s drawing the heroes see the arch where the millrace runs out under the wall, closed by an iron grating with six bolts: with the sluice down, the race is dry.`),l(`Tegningen er gammel og plettet; heltene ser kun, at møllerenden løber under muren, og den halve time er brugt.`,`The drawing is old and stained; the heroes see only that the millrace runs under the wall, and the half hour is spent.`))],fight:!1,alternatives:[l(`Rid straks: Heltene når {place} før det første stormløb og kan hjælpe med at sætte forsvaret, men ved intet om kornet, der blev solgt sidste efterår.`,`Ride at once: the heroes reach {place} before the first assault and can help set up the defences, but know nothing of the grain sold last autumn.`),l(`Lej prammandens pram: Ad åen tager det en halv time mere, men heltene kommer til {place} fra vandsiden, uset af angriberne ved vadestedet, og kan se buen, hvor møllerenden løber ud under muren.`,`Hire the bargeman’s barge: by river it takes half an hour longer, but the heroes come to {place} from the water side, unseen by the attackers at the ford, and can see the arch where the millrace runs out under the wall.`)],dmNotes:l(`Lad spillerne høre om {villain} gennem {npc1}: den gavmilde møller, der åbnede sine porte for hele landsbyen. Sig højt, hvad hvert svar ved bådebroen koster, og lad røgen over dalen vokse, mens de tøver.`,`Let the players hear of {villain} through {npc1}: the generous miller who opened the gates to the whole hamlet. Say aloud what each answer at the landing costs, and let the smoke over the valley grow while they hesitate.`)},middle:[{kind:`combat`,at:`site`,present:[`npc3`,`villain`],title:l(`Stormløbet ved porten`,`The Assault on the Gate`),summary:l([`Da det er blevet helt mørkt, kommer nogle {foe} over vadestedet og kaster sig mod porten til {place}, mens landsbyens folk står på muren med høtyve og sten.`,`Midt i kampen viser det sig, at den lille låge ved stalden står ulåst, og bagefter vender mængden sig mod {npc3}, en fremmed kræmmer, der slap ind lige før porten blev slået i.`,`Heltene skal holde porten og lågen og bagefter holde mængden fra at kaste kræmmeren ud over muren; {villain} er den første til at kræve det.`],[`When it is fully dark, some {foe} come across the ford and throw themselves at the gate of {place}, while the hamlet’s people stand on the wall with pitchforks and stones.`,`In the middle of the fight the postern by the stable turns out to be unbarred, and afterwards the crowd turns on {npc3}, a travelling peddler who slipped in just before the gate was barred.`,`The heroes must hold the gate and the postern, and afterwards keep the crowd from throwing the peddler over the wall; {villain} is the first to demand it.`]),readAloud:l([`Skygger samler sig ved vadestedet på den anden side af åen, og hundene i gården begynder at gø.`,`På muren står landsbyens folk tæt med høtyve, økser og spande med sten, og bag dem tramper køerne uroligt i gården.`,`Så plasker det i vadestedet, og noget hamrer mod porten.`],[`Shapes gather at the ford across the river, and the dogs in the yard begin to bark.`,`On the wall the hamlet’s people stand shoulder to shoulder with pitchforks, axes and buckets of stones, and behind them the cattle stamp uneasily in the yard.`,`Then there is splashing at the ford, and something hammers on the gate.`]),details:[l(`Angriberne prøver porten og muren for at finde den svage plet, ikke for at vinde i nat; når de har mistet nogle stykker, trækker de sig tilbage over åen. Imens finder en dreng fra landsbyen den lille låge ved stalden ulåst med bommen liggende i halmen, og nogle {foe} er allerede på vej derhen.`,`The attackers test the gate and the wall to find the weak spot, not to win tonight; once they have lost a few, they fall back across the river. Meanwhile a boy from the hamlet finds the postern by the stable unbarred, its bar lying in the straw, and some {foe} are already heading for it.`),l(`Bommen er løftet af indefra, og melede fodspor fører fra lågen hen til møllehuset. Mængden ser kun den fremmede: {npc3} kom ind lige før porten blev slået i, og ingen kender kræmmeren. {villain} kræver {npc3} kastet ud over muren, "før kræmmeren lukker resten ind".`,`The bar was lifted off from inside, and floury footprints lead from the postern to the mill house. The crowd sees only the stranger: {npc3} came in just before the gate was barred, and nobody knows the peddler. {villain} demands that {npc3} be thrown over the wall "before the peddler lets the rest in".`),l(`{npc3} har set noget, som kun kommer frem, hvis heltene skærmer kræmmeren: I skumringen stod {npc3} på åbredden og så {villain} med en sav og en lygte ved jernristen, hvor møllerenden løber ud under muren. Kræmmeren har tiet, for hvem tror en fremmed frem for dalens møller?`,`{npc3} has seen something that only comes out if the heroes shield the peddler: at dusk {npc3} stood on the riverbank and saw {villain} with a saw and a lantern at the iron grating where the millrace runs out under the wall. The peddler has kept quiet, for who would believe a stranger over the valley’s miller?`)],checks:[d(`Strength (Athletics)`,`medium`,l(`Heltene får lågen lukket og bommen lagt på igen, før angriberne når den; kampen bliver ved porten, hvor muren hjælper forsvarerne.`,`The heroes get the postern shut and barred again before the attackers reach it; the fight stays at the gate, where the wall helps the defenders.`),l(`Nogle {foe} når ind ad lågen og ind i gården, før den bliver lukket; kampen bliver hårdere, og en stak hø går i brand, men muren holder.`,`Some {foe} get in through the postern and into the yard before it is shut; the fight gets harder and a stack of hay catches fire, but the wall holds.`)),d(`Charisma (Persuasion)`,`medium`,l(`Heltene får mængden til at se på fodsporene: De er melede, og kræmmeren har aldrig sat sine ben i møllehuset. Mængden lader {npc3} være, og som tak fortæller kræmmeren heltene, hvad der skete ved jernristen i skumringen.`,`The heroes get the crowd to look at the footprints: they are floury, and the peddler has never set foot in the mill house. The crowd lets {npc3} be, and in thanks the peddler tells the heroes what happened at the iron grating at dusk.`),l(`Mængden låser {npc3} inde i en svinesti i stedet for at kaste kræmmeren ud; heltene kan tale med {npc3} senere, men kun gennem brædderne og kun, hvis de lover at få kræmmeren ud.`,`Instead of throwing the peddler out, the crowd locks {npc3} in a pigsty; the heroes can talk to {npc3} later, but only through the planks, and only if they promise to get the peddler out.`))],fight:!0,alternatives:[l(`Kast lys ud over muren: Brændende halmknipper på vadestedet viser, hvor angriberne er, så folk på muren kan ramme dem, og stormløbet bliver kortere.`,`Throw light over the wall: burning bundles of straw on the ford show where the attackers are, so the people on the wall can hit them, and the assault is shorter.`),l(`Lad lågen stå åben med vilje, og læg jer i baghold i stalden: De angribere, der kommer ind, går lige i fælden, og resten tror stadig, at deres hjælper indenfor er uopdaget.`,`Leave the postern open on purpose and lie in wait in the stable: the attackers who come in walk straight into the trap, and the rest still believe their helper inside is undiscovered.`)],dmNotes:l(`Første stormløb er en prøve, ikke selve belejringen: Lad angriberne trække sig, så snart de har mistet nogle stykker, og lad spillerne mærke, at det rigtige angreb endnu ikke er kommet. Mængdens vrede mod {npc3} er scenens anden kamp, og {villain} skal være den mest højrøstede i den.`,`The first assault is a test, not the siege itself: let the attackers fall back once they have lost a few, and let the players feel that the real attack has not come yet. The crowd’s anger at {npc3} is the scene’s second fight, and {villain} should be the loudest voice in it.`)},{kind:`investigation`,at:`site`,present:[`npc2`,`villain`],title:l(`Kornloftet over hjulet`,`The Granary over the Wheel`),summary:l([`Ved midnat blinker et lys tre gange i lugen på kornloftet, og på den anden side af åen blusser et bål op som svar; loftet er låst, og kun {villain} har nøglen.`,`Deroppe står dalens såsæd i lange rækker: De forreste sække lugter af lampeolie, og de bageste er fulde af avner og sand. Gennem en lem i gulvet kan man komme ned i hjulhuset og til jernristen i graven under hjulet.`,`{npc2}, møllersvenden, kan få heltene op ad sækkehejsen, og her samles beviserne mod {villain}.`],[`At midnight a light blinks three times at the granary hatch, and across the river a fire flares up in answer; the granary is locked, and only {villain} has the key.`,`Up there the valley’s seed corn stands in long rows: the front sacks smell of lamp oil, and the back ones are full of chaff and sand. A trapdoor in the floor leads down into the wheel house and to the iron grating in the pit beneath the wheel.`,`{npc2}, the journeyman, can get the heroes up by the sack hoist, and here the evidence against {villain} comes together.`]),readAloud:l([`Kornloftet er lavt og langt, og under taget står sækkene stablet i rækker, så langt lyset rækker.`,`Luften er tør og fuld af melstøv, men over den hænger en skarp lugt af lampeolie.`,`Midt i gulvet står en lem åben, og nedefra lyder det store hjul, der drejer og drejer i mørket.`],[`The granary is low and long, and under the roof the sacks are stacked in rows as far as the light reaches.`,`The air is dry and full of flour dust, but over it hangs a sharp smell of lamp oil.`,`In the middle of the floor a trapdoor stands open, and from below comes the sound of the great wheel, turning and turning in the dark.`]),details:[l(`Lyset i lugen var {villain}s tegn til angriberne: Aftalen står ved magt, og hjulet standser i timen før daggry. Når heltene når op, er døren låst, og {villain} sidder nede i møllestuen hos de sårede og deler brød og trøstende ord ud.`,`The light at the hatch was {villain}’s sign to the attackers: the bargain stands, and the wheel will stop in the hour before dawn. By the time the heroes get up there, the door is locked, and {villain} is sitting downstairs with the wounded, handing out bread and comfort.`),l(`De forreste sække er godt korn, vædet med lampeolie, så de vil brænde som fakler; de bageste er avner og sand under et tyndt lag korn. Ved lugen ud mod åen står en afskærmet lygte, endnu varm. {npc2} fortæller, at {villain} en nat sidste efterår sendte hele husstanden til høstgilde og blev alene tilbage, og at nøglen siden har hængt i en snor om {villain}s hals.`,`The front sacks are good grain, soaked in lamp oil so they will burn like torches; the back ones are chaff and sand under a thin layer of grain. By the hatch facing the river stands a hooded lantern, still warm. {npc2} tells how one night last autumn {villain} sent the whole household to the harvest feast and stayed behind alone, and how the key has hung on a cord round {villain}’s neck ever since.`),l(`Gennem lemmen kan heltene klatre ned i hjulhuset: Slusespillet er nysmurt, og nede i graven under hjulet er fire af de seks bolte i jernristen savet over og smurt ind i fedt og mel. Med jern fra smedjen i gården og en times arbejde kan heltene bolte risten fast igen, men så ved {villain}, at nogen har været dernede.`,`Through the trapdoor the heroes can climb down into the wheel house: the sluice winch is freshly greased, and down in the pit beneath the wheel four of the six bolts in the iron grating are sawn through and smeared with grease and flour. With iron from the forge in the yard and an hour’s work the heroes can bolt the grating fast again, but then {villain} will know someone has been down there.`)],checks:[d(`Dexterity (Stealth)`,`medium`,l(`Heltene kommer op og ned igen, uden at nogen i møllestuen hører dem.`,`The heroes get up and down again without anyone in the mill house hearing them.`),l(`Sækkehejsen knirker, så det høres i hele møllehuset; {villain} ved nu, at nogen har været på loftet, og holder sig tæt til hjulhuset resten af natten.`,`The sack hoist creaks loud enough to be heard all through the mill house; {villain} now knows someone has been in the granary and stays close to the wheel house for the rest of the night.`)),d(`Intelligence (Investigation)`,`easy`,l(`Heltene finder sandet, olien og de savede bolte og forstår sammenhængen: Kornloftet skal brænde, så ingen opdager, at halvdelen af kornet er væk, og risten skal op, når hjulet står stille.`,`The heroes find the sand, the oil and the sawn bolts and see how they fit together: the granary is to burn so that nobody discovers half the grain is gone, and the grating is to open when the wheel stops.`),l(`Heltene finder sandet i én sæk, men overser olien og de savede bolte; de ved, at noget er galt, men ikke, hvordan angrebet skal komme.`,`The heroes find the sand in one sack but miss the oil and the sawn bolts; they know something is wrong, but not how the attack is to come.`))],fight:!1,alternatives:[l(`Stil {villain} over for en opskåret sæk foran landsbyens folk nu: Mølleren benægter alt, kalder sandet kræmmerens værk og kræver heltene smidt ud, men folk begynder at tvivle, og {villain} bliver holdt under opsyn.`,`Confront {villain} now with a cut-open sack in front of the hamlet’s people: the miller denies everything, calls the sand the peddler’s work and demands that the heroes be thrown out, but people begin to doubt, and {villain} is kept under watch.`),l(`Sig ingenting, og lad {villain} tro, at planen holder: Så kan heltene vente i hjulhuset, når hjulet standser, og tage mølleren på fersk gerning.`,`Say nothing and let {villain} believe the plan holds: then the heroes can be waiting in the wheel house when the wheel stops, and catch the miller in the act.`)],dmNotes:l(`Her bliver mistanken til vished. Lad spillerne selv vælge, om de vil afsløre {villain} nu eller lægge en fælde til timen før daggry. Bank fra nu af en langsom, jævn takt i bordet en gang imellem for hjulet; den takt skal holde op i klimaks.`,`Here suspicion turns to certainty. Let the players choose for themselves whether to unmask {villain} now or set a trap for the hour before dawn. From now on, tap a slow, steady beat on the table now and then for the wheel; the beat stops at the climax.`)},{kind:`exploration`,at:`town`,present:[],title:l(`Bålet over åen`,`The Fire across the River`),summary:l([`Efter midnat ligger angriberne samlet om bålet på den anden side af åen, lige over for buen, hvor møllerenden løber ud under muren.`,`Går heltene ud ad lågen og over åen i mørket, kan de se, hvor mange der venter, og hvad de har gjort klar: planker, stænger og en rebstige til graven under hjulet.`,`Et udfald kan svække det sidste angreb, men hver time uden for muren er en time, hvor {villain} er alene med hjulet.`],[`After midnight the attackers are gathered round the fire across the river, right opposite the arch where the millrace runs out under the wall.`,`If the heroes slip out through the postern and across the river in the dark, they can see how many are waiting and what they have made ready: planks, poles and a rope ladder for the pit beneath the wheel.`,`A sortie can weaken the last attack, but every hour outside the wall is an hour in which {villain} is alone with the wheel.`]),readAloud:l([`Åen er sort og kold og løber stærkt over stenene ved vadestedet.`,`På den anden side brænder et bål i ly af elletræerne, og skygger bevæger sig frem og tilbage foran det.`,`Ved vandkanten ligger en stak friske planker og en sammenrullet rebstige, som om nogen skal ned i et hul.`],[`The river runs black and cold, fast over the stones of the ford.`,`On the far side a fire burns in the shelter of the alders, and shadows move back and forth in front of it.`,`At the water’s edge lie a stack of fresh planks and a coiled rope ladder, as if someone means to climb down into a pit.`]),details:[l(`Bålet er det, der svarede {villain}s lys. Her venter {boss} og resten af angriberne på, at hjulet står stille; de har ingen grund til at storme muren igen, så de hviler og holder kun et par vagter ved vadestedet.`,`The fire is the one that answered {villain}’s light. Here {boss} and the rest of the attackers wait for the wheel to stop; they have no reason to storm the wall again, so they rest and keep only a couple of lookouts at the ford.`),l(`Plankerne skal lægges i den tørlagte møllerende, og rebstigen skal ned i graven under hjulet. Forsvinder de, eller bliver de knækket og smidt i åen, tager det angriberne lang tid at komme ind ad renden, og det sidste angreb kommer i stedet over muren, hvor forsvarerne står klar.`,`The planks are to be laid in the drained millrace, and the rope ladder is for the pit beneath the wheel. If they vanish, or are broken and thrown in the river, the attackers take a long time getting in by the race, and the last attack comes over the wall instead, where the defenders are ready.`),l(`Mens heltene er uden for muren, er {villain} alene i møllen. Er mølleren ikke afsløret, bruger {villain} tiden til at smøre slusespillet en sidste gang og bære en krukke olie mere op på kornloftet; har heltene sat {npc2} til at vogte hjulhuset, finder de svenden slået bevidstløs, når de kommer tilbage.`,`While the heroes are outside the wall, {villain} is alone in the mill. If the miller has not been unmasked, {villain} uses the time to grease the sluice winch one last time and carry another jar of oil up to the granary; if the heroes left {npc2} to guard the wheel house, they find the journeyman knocked senseless when they return.`)],checks:[d(`Dexterity (Stealth)`,`medium`,l(`Heltene kommer over åen og helt hen til bålet uden at blive set og kan tage plankerne og stigen eller tælle angriberne og se, hvor {boss} hviler.`,`The heroes get across the river and right up to the fire unseen, and can take the planks and the ladder, or count the attackers and see where {boss} rests.`),l(`En vagt ved vadestedet slår alarm; heltene må trække sig tilbage over åen med angriberne i hælene, og bålet bliver flyttet længere ind mellem træerne.`,`A lookout at the ford raises the alarm; the heroes must fall back across the river with the attackers at their heels, and the fire is moved deeper among the trees.`)),d(`Wisdom (Perception)`,`easy`,l(`Heltene ser, at stien fra bålet går ned til vandet lige over for buen ved møllerenden og ikke mod porten: Det sidste angreb skal komme ad renden.`,`The heroes see that the path from the fire runs down to the water right opposite the arch at the millrace, not toward the gate: the last attack is to come by the race.`),l(`Det er for mørkt til at se andet end bålet; heltene ved, at angriberne er mange, men ikke, hvad de har gjort klar.`,`It is too dark to see anything but the fire; the heroes know the attackers are many, but not what they have made ready.`))],fight:!1,alternatives:[l(`Bliv bag muren: Heltene giver afkald på chancen for at svække angriberne, men {villain} er aldrig alene med hjulet.`,`Stay behind the wall: the heroes give up the chance to weaken the attackers, but {villain} is never alone with the wheel.`),l(`Tal med {boss}: Med en opskåret sæk fra kornloftet kan heltene vise, at mølleren har snydt alle, også angriberne. {boss} bliver ikke en ven, men vender vreden mod {villain}, når hjulet står stille.`,`Parley with {boss}: with a cut-open sack from the granary, the heroes can show that the miller has cheated everyone, the attackers too. {boss} does not become a friend, but turns on {villain} when the wheel stops.`)],dmNotes:l(`Udfaldet er spillernes chance for at tage initiativet. Gør det kort og farligt, og mind dem om, at hjulet drejer bag dem, og at nogen derinde ved, hvornår det skal stå stille.`,`The sortie is the players’ chance to seize the initiative. Keep it short and dangerous, and remind them that the wheel is turning behind them, and that someone inside knows when it is to stop.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`,`npc2`],title:l(`Når hjulet står stille`,`When the Wheel Stops`),summary:l([`I timen før daggry står det store hjul pludselig stille: {villain} har lukket slusen og løftet den løse jernrist, og {boss} og resten af angriberne kommer ind ad den tørlagte møllerende og op i hjulhuset.`,`Imens står {villain} ved trappen til kornloftet med en tændt lygte for at sætte ild til de oliedrukne sække.`,`Heltene skal holde hjulhuset, til fogedens ryttere når frem ved solopgang, redde kornet fra ilden og stille {villain} til regnskab foran landsbyens folk.`],[`In the hour before dawn the great wheel suddenly stops: {villain} has closed the sluice and lifted the loose iron grating, and {boss} and the rest of the attackers come in along the drained millrace and up into the wheel house.`,`Meanwhile {villain} stands at the granary stair with a lit lantern, ready to set fire to the oil-soaked sacks.`,`The heroes must hold the wheel house until the reeve’s riders arrive at sunrise, save the grain from the fire and make {villain} answer for it before the hamlet’s people.`]),readAloud:l([`Hele natten har hjulet drejet med en dyb, jævn rumlen, og nu står det stille.`,`I tavsheden høres vand løbe bort under gulvet, og så plask og rasl af jern nede i graven under hjulet.`,`Ved trappen til kornloftet blafrer en lygte, og en skikkelse med melstøv på ærmerne løfter den mod de øverste sække.`],[`All night the wheel has turned with a deep, steady rumble, and now it stands still.`,`In the silence you hear water draining away beneath the floor, then splashing and the rattle of iron down in the pit beneath the wheel.`,`At the granary stair a lantern flickers, and a figure with flour dust on their sleeves lifts it toward the topmost sacks.`]),details:[l(`{boss} og nogle {foe} kommer op fra graven, fordi {villain} har lovet dem en åben vej og alt, hvad landsbyens folk har båret med ind i møllen. De tjener ikke {villain} og er kun bundet af aftalen: Viser det sig, at kornet er halvt sand, eller at mølleren ikke kan holde, hvad der er lovet, vender {boss} sig mod {villain}.`,`{boss} and some {foe} come up out of the pit because {villain} promised them an open way and everything the hamlet’s people carried into the mill. They do not serve {villain} and are bound only by the bargain: if it turns out that the grain is half sand, or that the miller cannot deliver what was promised, {boss} turns on {villain}.`),l(`{villain} kæmper ikke, men vil sætte ild til de forreste sække og råbe brand, så det ser ud, som om angriberne gjorde det. Har heltene boltet risten fast eller holdt hjulet i gang, kommer angriberne i stedet over muren ved porten, og {villain} prøver at nå kornloftet i virvaret. Er mølleren allerede afsløret og spærret inde, prøver {villain} at slippe fri, så snart kampen begynder.`,`{villain} does not fight, but means to set fire to the front sacks and shout fire, so that it looks as if the attackers did it. If the heroes bolted the grating fast or kept the wheel turning, the attackers come over the wall at the gate instead, and {villain} tries to reach the granary in the confusion. If the miller has already been unmasked and locked up, {villain} tries to break free as soon as the fighting starts.`),l(`Én opskåret sæk fra de bageste rækker, der vælter sand ud foran landsbyens folk, afgør sagen: Mølleren har intet at sige. Ved solopgang høres hestene fra {town} på vejen, og de angribere, der stadig står, flygter over åen.`,`One sack from the back rows, cut open so that the sand spills out in front of the hamlet’s people, settles it: the miller has nothing to say. At sunrise the horses from {town} can be heard on the road, and the attackers still standing flee across the river.`)],checks:[d(`Dexterity (Acrobatics)`,`medium`,l(`Heltene når trappen og slår lygten ud af {villain}s hånd, før olien fænger.`,`The heroes reach the stair and knock the lantern out of {villain}’s hand before the oil catches.`),l(`Lygten rammer de forreste sække, og ilden fænger; heltene må vælge mellem at slukke branden og at holde angriberne nede i hjulhuset.`,`The lantern hits the front sacks and the fire catches; the heroes must choose between putting out the fire and holding the attackers down in the wheel house.`)),d(`Strength (Athletics)`,`hard`,l(`Heltene får slusen op igen: Vandet fosser ind i renden, hjulet begynder at dreje, og de angribere, der stadig er nede i graven, bliver skyllet ud under muren.`,`The heroes get the sluice open again: water floods into the race, the wheel begins to turn and the attackers still down in the pit are swept out under the wall.`),l(`{villain} har kilet slusespillet fast; heltene må kæmpe i hjulhuset, til nogen får slået kilen ud.`,`{villain} has wedged the sluice winch; the heroes must fight in the wheel house until someone knocks the wedge out.`))],fight:!0,alternatives:[l(`Vis {boss} sandet: Med en opskåret sæk i hånden kan heltene få angriberne til at forstå, at mølleren har snydt dem. {boss} vender sig mod {villain}, og mølleren beder heltene om beskyttelse og overgiver sig.`,`Show {boss} the sand: with a cut-open sack in hand, the heroes can make the attackers understand that the miller has cheated them. {boss} turns on {villain}, and the miller begs the heroes for protection and surrenders.`),l(`Lad {npc2} tage hjulet: Svenden kender slusen bedre end nogen og kan åbne den, mens heltene holder trappen; når hjulet drejer igen, er vejen ind lukket.`,`Let {npc2} take the wheel: the journeyman knows the sluice better than anyone and can open it while the heroes hold the stair; once the wheel turns again, the way in is closed.`)],dmNotes:l(`Lad stilheden være signalet: Hold op med at banke hjulets takt i bordet, når hjulet står stille, og lad spillerne mærke, hvad det betyder. Spil {villain} som et bange menneske, der er gået for langt, ikke som en kriger; det stærkeste øjeblik er sandet, der løber ud af sækken foran landsbyens folk.`,`Let the silence be the signal: stop tapping the wheel’s beat on the table when the wheel stops, and let the players feel what it means. Play {villain} as a frightened person who has gone too far, not as a fighter; the strongest moment is the sand running out of the sack in front of the hamlet’s people.`)}},ge=e({kernel:()=>be,scenes:()=>xe}),_e=e=>Array.isArray(e)?e.join(` `):e,f=(e,t)=>({da:_e(e),en:_e(t)}),ve=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),p=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},ye=(e,t,n)=>({when:e,event:t,sign:n}),m=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),be={id:`race-the-drowned-bell`,titles:[f(`Den druknede klokke`,`The Drowned Bell`),f(`Klokken fra {place}`,`The Bell of {place}`),f(`Før vandet kommer`,`Before the Water Comes`)],missions:[`race`,`exploration`],foes:`lair`,roles:{npc1:f(`en kirkeværge i den nye landsby, hvor folk fra {place} bor i dag`,`a churchwarden of the new village where the people of {place} live today`),npc2:f(`en gammel klokker, der ringede med klokken i {place}, den nat vandet kom`,`an old bell-ringer who rang the bell of {place} the night the water came`),npc3:f(`en slusevogter ved dæmningen, som {villain} har bestukket`,`a sluice keeper at the dam whom {villain} has bribed`),villain:f(`en klokkestøber i {town}, der har lovet templet en ny storklokke`,`a bell-founder of {town} who has promised the temple a great new bell`)},hook:f(`På trappen til templet i {town} beder {npc1}, kirkeværge i den nye landsby, heltene om at nå klokken i {place} før {villain}s folk og få den op over den gamle strandlinje, før vandet kommer tilbage.`,`On the steps of the temple in {town}, {npc1}, churchwarden of the new village, asks the heroes to reach the bell of {place} before {villain}’s crew and bring it above the old shoreline before the water comes back.`),people:{npc1:{wants:f(`Vil hænge klokken op i det nye kapel og ringe for de døde fra {place}, før de sidste, der husker dem, er borte.`,`Wants to hang the bell in the new chapel and ring it for the dead of {place} before the last of those who remember them are gone.`),secret:f(`Lånte penge af {villain} til kapellets tag sidste vinter og frygter, at klokkestøberen vil kræve dem tilbage, hvis heltene vinder.`,`Borrowed money from {villain} for the chapel roof last winter, and fears the bell-founder will call in the debt if the heroes win.`)},npc2:{wants:f(`Vil slå på klokken én gang til, før den hænger noget andet sted, eller før vandet tager den igen.`,`Wants to sound the bell one more time, before it hangs anywhere else or the water takes it again.`),secret:f(`Gemte kirkens sølv under gulvet i klokkestolen, den nat vandet kom, og har aldrig fortalt nogen, hvor det er.`,`Hid the church silver under the belfry floor the night the water came, and has never told anyone where it is.`)},npc3:{wants:f(`Vil beholde pengene og sin plads ved dæmningen uden at få flere druknede på samvittigheden.`,`Wants to keep the money and their post at the dam without any more drownings on their conscience.`),secret:f(`Lukkede selv slusen en dag for tidligt for tredive år siden på den gamle herres ordre og har hørt klokken under søen i hver storm siden.`,`Closed the gates a day early thirty years ago on the old lord’s order, and has heard the bell under the lake in every storm since.`)}},premise:f([`For tredive år siden blev dalen dæmmet op for at drive møllerne i {town}, og landsbyen {place} forsvandt under søen med kirke, tårn og klokke.`,`I sommer har slusen i dæmningen stået åben for reparationer, søen er faldet til det laveste i mands minde, og {place} ligger fri i mudderet.`,`{villain}, klokkestøberen i {town}, har lovet templet en storklokke støbt af den druknede klokke og har brugt forskuddet; efter dalens bjærgningsret tilhører klokken den, der først får den op over den gamle strandlinje.`,`Derfor har {villain} bestukket slusevogteren til at lukke slusen ved middagstid i stedet for ved solnedgang, og ved første lys kørte {villain}s folk ud over mudderet.`],[`Thirty years ago the valley was dammed to drive the mills of {town}, and the village of {place} vanished under the lake with its church, its tower and its bell.`,`This summer the gates in the dam have stood open for repairs, the lake has fallen to its lowest in living memory, and {place} lies bare in the mud.`,`{villain}, the bell-founder of {town}, has promised the temple a great bell cast from the drowned bell and has spent the advance; by the valley’s salvage law, the bell belongs to whoever first brings it above the old shoreline.`,`So {villain} has bribed the sluice keeper to close the gates at noon instead of at sunset, and at first light {villain}’s crew drove out across the mud.`]),goal:f(`Nå klokken i {place} før {villain}s folk, og få den op over den gamle strandlinje, før vandet kommer tilbage.`,`Reach the bell of {place} before {villain}’s crew, and bring it above the old shoreline before the water comes back.`),objective:{target:f(`Klokken fra {place}, støbt af landsbyens sølv og bronze for to hundrede år siden`,`The bell of {place}, cast from the village’s silver and bronze two hundred years ago`),state:f([`Hænger stadig i klokkestolen i det druknede kirketårn, grøn af ir og fuld af mudder, mens {villain}s folk rigger et hejseværk til for at fire den ned.`,`I den oversvømmede krypt under tårnet har {boss} og nogle {foe} haft deres leje, siden vandet faldt.`],[`Still hanging in the belfry of the drowned church tower, green with verdigris and full of mud, while {villain}’s crew rigs a hoist to lower it.`,`In the flooded crypt beneath the tower, {boss} and some {foe} have made their lair since the water fell.`]),resolution:f([`Kom før eller forbi {villain}s folk, fir klokken ned, og få den på en slæde og op over den gamle strandlinje, før vandet når kirkegården.`,`Kan heltene ikke få klokken med, kan de stadig hindre {villain} i at få den, men så tager søen den igen.`],[`Beat {villain}’s crew to the bell or get past them, then lower it and get it onto a sledge and above the old shoreline before the water reaches the churchyard.`,`If the heroes cannot take the bell, they can still keep {villain} from having it, but then the lake takes it again.`])},villain:{want:f(`At få klokken fra {place} i smelteovnen, så templets storklokke kan støbes af dens malm til indvielsen, og så ingen nogensinde kræver det brugte forskud tilbage.`,`To get the bell of {place} into the furnace, so the temple’s great bell can be cast from its metal in time for the consecration and nobody ever demands the spent advance back.`),plan:f([`Først lovede {villain} templet en storklokke med den druknede klokkes stemme og brugte forskuddet på gammel gæld.`,`Så bestak {villain} slusevogteren {npc3} til at lukke slusen ved middagstid i stedet for ved solnedgang, og ved første lys kørte {villain}s folk ud over mudderet med okser, slæde og hejseværk.`,`Ved middagstid står {villain} selv i klokkestolen i {place}, mens klokken bliver løftet af sin bjælke; når den er over den gamle strandlinje, er den {villain}s efter dalens bjærgningsret, og det stigende vand lukker vejen for alle, der kommer bagefter.`],[`First, {villain} promised the temple a great bell with the voice of the drowned bell, and spent the advance on old debts.`,`Then {villain} bribed {npc3}, the sluice keeper, to close the gates at noon instead of at sunset, and at first light {villain}’s crew drove out across the mud with oxen, a sledge and a hoist.`,`At noon {villain} will stand in the belfry at {place} in person as the bell is lifted off its beam; once it is above the old shoreline, it is {villain}’s by the valley’s salvage law, and the rising water will close the way to anyone who comes after.`]),weakness:f([`{villain}s folk er lejet for en dagløn og vil ikke drukne for klokkestøberens gæld; når vandet kommer, eller når de hører om bestikkelsen, slipper de rebene.`,`Og brevet i slusehuset beviser, at {villain} fik slusen lukket for tidligt: Med det som bevis vil templet aldrig tage imod klokken fra {villain}.`],[`{villain}’s crew work for a day’s wage and will not drown for the bell-founder’s debts; when the water comes, or when they hear of the bribe, they let go of the ropes.`,`And the letter in the sluice house proves that {villain} paid to have the gates closed early: with that as proof, the temple will never accept the bell from {villain}.`])},stakes:f(`Kommer {villain}s folk først ud med klokken, bliver den smeltet om i {town}, og folk fra {place} mister det sidste, de havde tilbage af deres landsby; får ingen den ud i tide, tager søen den igen, og tårnet styrter sammen over den.`,`If {villain}’s crew gets the bell out first, it is melted down in {town}, and the people of {place} lose the last thing they have left of their village; if nobody gets it out in time, the lake takes it again, and the tower falls on top of it.`),clock:{start:f(`Første lys. Søen er faldet til det laveste i mands minde, og {villain}s okser og slæde er lige kørt ud over mudderet fra den gamle strandlinje. Slusen skal lukke ved solnedgang, men {npc3} er betalt for at lukke den ved middagstid, om seks timer, og så når vandet {place} tre timer senere.`,`First light. The lake has fallen to its lowest in living memory, and {villain}’s oxen and sledge have just set out across the mud from the old shoreline. The gates are to close at sunset, but {npc3} has been paid to close them at noon, six hours from now, and then the water will reach {place} three hours later.`),ticks:[ye(f(`Efter 2 timer`,`After 2 hours`),f(`{villain}s folk når kirken i {place} ad den gamle vej, spærrer tårndøren og begynder at rigge en bom til i klokkestolen.`,`{villain}’s crew reaches the church at {place} by the old road, bars the tower door and starts rigging a boom in the belfry.`),f(`Hammerslag og råb fra kirketårnet bærer langt over mudderet, og en ny bom stikker ud af glamhullerne.`,`Hammering and shouts from the church tower carry far across the mud, and a new boom juts out of the louvres.`)),ye(f(`Efter 6 timer (ved middagstid)`,`After 6 hours (at noon)`),f(`{npc3} lukker slusen seks timer for tidligt, og søen begynder at stige fra den nederste ende af dalen; i klokkestolen løfter {villain}s folk klokken af dens gamle bjælke.`,`{npc3} closes the gates six hours early, and the lake begins to rise from the low end of the valley; in the belfry {villain}’s crew lifts the bell off its old beam.`),f(`Floden under dæmningen bliver stille, i de laveste huller i mudderet begynder vandet at brede sig, og tårnet knager, da klokken hænger frit.`,`The river below the dam falls quiet, water starts spreading in the lowest hollows of the mud, and the tower creaks as the bell hangs free.`)),ye(f(`Efter 9 timer (midt på eftermiddagen)`,`After 9 hours (in mid-afternoon)`),f(`Vandet når kirkegårdsmuren i {place}, og tårnet begynder at give sig; det, der ikke er på vej mod strandlinjen nu, når aldrig derop.`,`The water reaches the churchyard wall at {place}, and the tower begins to give way; whatever is not on its way to the shoreline by now will never get there.`),f(`Vand fosser ind over kirkegårdsmuren, og mørtel drysser ned fra klokkestolen.`,`Water pours over the churchyard wall, and mortar sifts down from the belfry.`))],deadline:f(`Efter 9 timer, midt på eftermiddagen, er det for sent: Vandet lukker sig om kirken, tårnet styrter sammen, og det, der ikke er på vej mod strandlinjen, ligger under søen igen i tredive år.`,`After 9 hours, in mid-afternoon, it is too late: the water closes around the church, the tower falls, and whatever is not on its way to the shoreline lies under the lake for another thirty years.`)},clues:{who:[p(`town`,f(`I slusehuset ved dæmningen ligger et brev med {villain}s segl under {npc3}s pung.`,`In the sluice house at the dam, a letter bearing {villain}’s seal lies under {npc3}’s purse.`),f(`{villain} har betalt for at få slusen lukket seks timer for tidligt: Søen begynder at stige ved middagstid og ikke ved solnedgang.`,`{villain} has paid to have the gates closed six hours early: the lake starts rising at noon, not at sunset.`),ve([`Luk slusen, når solen står højest, ikke ved solnedgang.`,`Vandet er tre timer om at nå kirken, og det er nok for mine folk.`,`Resten af pengene får du, når vandet står over kirketaget. – {villain}`],[`Close the gates when the sun stands highest, not at sunset.`,`The water takes three hours to reach the church, and that is enough for my crew.`,`The rest of the money is yours when the water stands over the church roof. — {villain}`])),p(`town`,f(`I templet i {town} viser skriveren kontrakten om den nye storklokke: {villain} har fået halvdelen af prisen forud, og klokken skal hænge til indvielsen om syv dage.`,`In the temple of {town}, the clerk shows the contract for the new great bell: {villain} has been paid half the price in advance, and the bell must be hanging in time for the consecration in seven days.`),f(`{villain} er ruineret, hvis den druknede klokke ikke er i smelteovnen inden indvielsen, og vil gøre alt for at nå den først.`,`{villain} is ruined if the drowned bell is not in the furnace before the consecration, and will do anything to reach it first.`),ve([`Kontrakt mellem templet i {town} og klokkestøber {villain}:`,`En storklokke, støbt af malmen fra den druknede klokke i {place}, hængt til indvielsen.`,`Halvdelen betalt forud. Kommer klokken ikke, betales forskuddet tilbage med det dobbelte.`],[`Contract between the temple of {town} and {villain}, bell-founder:`,`One great bell, cast from the metal of the drowned bell of {place}, hung in time for the consecration.`,`Half paid in advance. Should the bell not be delivered, the advance is to be repaid twice over.`])),p(`site`,f(`Ved indgangen til den druknede gade står nye pæle med røde klude og viser vej ud i det bundløse gadekær; de samme røde klude hænger på {villain}s slæde.`,`At the mouth of the drowned street, new stakes with red rags mark a way out into the bottomless village pond; the same red rags hang on {villain}’s sledge.`),f(`{villain}s folk har lagt et falsk spor for den, der kommer ad kirkestien, og det kan kun være på klokkestøberens ordre.`,`{villain}’s crew has laid a false trail for whoever comes by the church path, and it can only be on the bell-founder’s orders.`)),p(`site`,f(`På kirkegården brokker {villain}s folk sig over, at klokkestøberen vil have dem ude af {place} tre timer efter middag, "før vandet kommer", selv om alle i {town} siger, at slusen først lukker ved solnedgang.`,`In the churchyard, {villain}’s crew grumble that the bell-founder wants them out of {place} three hours after noon, "before the water comes", though everyone in {town} says the gates close at sunset.`),f(`{villain} ved, at vandet kommer tidligt, og det kan kun være, fordi {villain} selv har sørget for det.`,`{villain} knows the water will come early, and that can only be because {villain} arranged it.`))],where:[p(`town`,f(`{npc2}, den gamle klokker, kender kirkestien: Den går lige over mudderet fra strandlinjen til kirkegårdsporten og er halvt så lang som den gamle vej.`,`{npc2}, the old bell-ringer, knows the church path: it runs straight across the mud from the shoreline to the churchyard gate and is half the length of the old road.`),f(`Med {npc2} som fører kan heltene indhente {villain}s forspring.`,`With {npc2} as guide, the heroes can close the gap on {villain}’s crew.`),ve([`Kirkestien: fra den hvide sten ved strandlinjen lige mod tårnet.`,`Gennem gaden, forbi smedjen, ind ad kirkegårdsporten.`,`Tårnet: Trappen er rådden over det tolvte trin. Gå gennem krypten.`],[`The church path: from the white stone at the shoreline straight toward the tower.`,`Through the street, past the smithy, in at the churchyard gate.`,`The tower: the stair is rotten above the twelfth step. Go through the crypt.`])),p(`site`,f(`På kirkegården har {villain}s folk spærret tårndøren indefra og trukket stigen op, men {npc2} husker, at krypten under kirken har en smal trappe op i tårnet.`,`In the churchyard, {villain}’s crew has barred the tower door from inside and pulled up the ladder, but {npc2} remembers that the crypt under the church has a narrow stair up into the tower.`),f(`Vejen til klokken går gennem krypten, hvor vandet stadig står, og hvor noget har sit leje.`,`The way to the bell runs through the crypt, where the water still stands and something has its lair.`)),p(`site`,f(`Fra den druknede gade kan man se klokken gennem glamhullerne i kirketårnet: grøn af ir og stadig på sin bjælke, mens en ny bom stikker ud over kirkegården.`,`From the drowned street the bell can be seen through the louvres of the church tower: green with verdigris and still on its beam, while a new boom juts out over the churchyard.`),f(`Klokken er der endnu, og {villain}s folk er ved at rigge den til; der er tid, hvis heltene skynder sig.`,`The bell is still there, and {villain}’s crew is rigging it; there is time if the heroes hurry.`)),p(`site`,f(`Inde i kirken hænger klokkerebet stadig ned gennem hullet i hvælvingen, slimet af alger, men helt.`,`Inside the church the bell rope still hangs down through the hole in the vault, slimy with weed but whole.`),f(`Den, der kan klatre, kan nå klokkestolen uden om den spærrede tårndør.`,`Whoever can climb can reach the belfry without going through the barred tower door.`))]},endings:{success:f(`Klokken kommer op over den gamle strandlinje på slæden, mens vandet skyller ind over kirkegården bag den, og folk fra den nye landsby trækker i rebene. Den hænger i kapellet før høst, og {npc2} ringer med den første gang. {villain} må betale templets forskud tilbage med det dobbelte og mister værkstedet, og templet spørger heltene, om de kender en ærlig klokkestøber.`,`The sledge brings the bell above the old shoreline as the water washes over the churchyard behind it, with the people of the new village hauling on the ropes. It hangs in the chapel before harvest, and {npc2} is the first to ring it there. {villain} must repay the temple’s advance twice over and loses their workshop, and the temple asks the heroes whether they know an honest bell-founder.`),partial:f(`Heltene hindrer {villain} i at få klokken, men kan ikke selv få den ud i tide; vandet tager den igen, og tårnet styrter sammen over den. {villain} er ruineret, men folk fra {place} har mistet deres klokke for anden gang, og i storm siger de stadig, at man kan høre den under søen.`,`The heroes keep {villain} from getting the bell, but cannot get it out themselves in time; the water takes it again, and the tower falls on top of it. {villain} is ruined, but the people of {place} have lost their bell a second time, and in storms they still say it can be heard under the lake.`),failure:f(`{villain}s slæde når over strandlinjen med klokken, og efter dalens bjærgningsret er den klokkestøberens. En uge senere ringer templets nye storklokke over {town} med den druknede klokkes malm i sig, og {villain} bliver hyldet; folk fra {place} står på torvet og hører deres egen klokke, smeltet om under et andet navn.`,`{villain}’s sledge reaches the shoreline with the bell, and by the valley’s salvage law it belongs to the bell-founder. A week later the temple’s new great bell rings over {town} with the drowned bell’s metal in it, and {villain} is celebrated; the people of {place} stand in the square and hear their own bell, melted down under another name.`)}},xe={opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc2`],title:f(`Ved templet i {town}`,`At the Temple in {town}`),summary:f([`Ved første lys står {npc1}, kirkeværge i den nye landsby, hvor folk fra {place} bor i dag, på trappen til templet i {town}; templets råd har netop afvist at standse {villain}.`,`{npc1} beder heltene nå klokken i {place} før klokkestøberens folk og få den op over den gamle strandlinje, så den kan hænge i det nye kapel.`,`{villain}s okser og slæde er allerede kørt ud over mudderet, og hver time i byen er en time, klokkestøberen vinder.`],[`At first light {npc1}, churchwarden of the new village where the people of {place} live today, stands on the steps of the temple in {town}; the temple council has just refused to stop {villain}.`,`{npc1} asks the heroes to reach the bell of {place} before the bell-founder’s crew and bring it above the old shoreline, so it can hang in the new chapel.`,`{villain}’s oxen and sledge have already set out across the mud, and every hour in town is an hour the bell-founder gains.`]),readAloud:f([`Templets nye klokketårn står færdigt og tomt over torvet med en bjælke klar til en klokke, der endnu ikke er støbt.`,`På trappen står en kirkeværge i støvet tøj med et bundt reb over skulderen, og ved siden af står en gammel klokker og støtter sig til en stok.`,`Oppe fra dæmningen lyder det dybe brus af vand, der stadig strømmer ud gennem de åbne sluseporte.`],[`The temple’s new bell tower stands finished and empty above the square, a beam ready for a bell not yet cast.`,`On the steps stands a churchwarden in dusty clothes with a coil of rope over one shoulder, and beside the warden an old bell-ringer leans on a stick.`,`From the dam up the valley comes the deep roar of water still pouring out through the open gates.`]),details:[f(`{npc1} har {npc2} med, den gamle klokker, der ringede med klokken i {place}, den nat vandet kom. Klokkeren kender kirkestien, der går lige over mudderet fra strandlinjen til kirkegårdsporten: halvt så lang som den gamle vej, {villain}s folk har taget, men gennem den druknede gade og det bløde mudder.`,`{npc1} has brought {npc2}, the old bell-ringer who rang the bell of {place} the night the water came. The bell-ringer knows the church path, running straight across the mud from the shoreline to the churchyard gate: half the length of the old road {villain}’s crew has taken, but it leads through the drowned street and the soft mud.`),f(`Templets skriver viser gerne kontrakten: {villain} har fået halvdelen af prisen forud for en storklokke støbt af malmen fra den druknede klokke, og indvielsen er om syv dage. Efter dalens bjærgningsret tilhører alt, hvad søen har taget, den, der først bringer det op over den gamle strandlinje. Folk fra den nye landsby venter ved strandlinjen med reb og en vogn, men ingen af dem tør gå ud til {place}, hvor noget har rørt sig i de druknede huse, siden vandet faldt.`,`The temple’s clerk will happily show the contract: {villain} has been paid half the price in advance for a great bell cast from the metal of the drowned bell, and the consecration is seven days off. By the valley’s salvage law, whatever the lake has taken belongs to whoever first brings it above the old shoreline. People from the new village wait at the shoreline with ropes and a cart, but none of them dares go out to {place}, where something has stirred in the drowned houses since the water fell.`),f(`Vejen op ad dalen går over dæmningen, hvor slusevogteren skal lukke slusen ved solnedgang. Rider heltene straks, er de ved strandlinjen om to timer; et ophold ved dæmningen koster en halv time, og et besøg hos templets skriver lige så meget.`,`The road up the valley crosses the dam, where the sluice keeper is to close the gates at sunset. If the heroes ride at once, they reach the shoreline in two hours; a stop at the dam costs half an hour, and so does a visit to the temple’s clerk.`)],checks:[m(`Intelligence (History)`,`medium`,f(`Heltene kender bjærgningsretten til bunds: Den gælder ikke for gods, der er vundet ved svig, og et bevis på snyd kan gøre {villain}s krav ugyldigt.`,`The heroes know the salvage law well: it does not cover goods won by fraud, and proof of cheating can void {villain}’s claim.`),f(`Heltene ved kun, at klokken tilhører den, der først får den op over strandlinjen.`,`The heroes know only that the bell belongs to whoever first gets it above the shoreline.`)),m(`Charisma (Persuasion)`,`medium`,f(`Templets skriver går med til at ride med som vidne: Med et bevis på snyd kan skriveren erklære {villain}s krav ugyldigt på stedet.`,`The temple’s clerk agrees to ride along as a witness: with proof of cheating, the clerk can declare {villain}’s claim void on the spot.`),f(`Skriveren har travlt med indvielsen; heltene må selv bringe deres beviser til templet bagefter.`,`The clerk is busy with the consecration; the heroes must bring their proof to the temple themselves afterwards.`))],fight:!1,alternatives:[f(`Tag kirkestien med {npc2} som fører: Den sparer en time, men går gennem den druknede gade, hvor noget har slået sig ned, siden vandet faldt.`,`Take the church path with {npc2} as guide: it saves an hour, but runs through the drowned street, where something has settled since the water fell.`),f(`Følg {villain}s folk ad den gamle vej: Den er fast og sikker, men længere, og klokkestøberens folk har to timers forspring.`,`Follow {villain}’s crew along the old road: it is firm and safe but longer, and the bell-founder’s crew has a two-hour lead.`)],dmNotes:f(`Gør kapløbet synligt fra første øjeblik: Når heltene når strandlinjen, ser de okserne og slæden som små prikker ude på mudderet og tårnet midt i det hele. Sig højt, hvad hvert ophold koster.`,`Make the race visible from the first moment: when the heroes reach the shoreline, they see the oxen and sledge as small dots out on the mud and the tower standing in the middle of it all. Call out what each stop costs.`)},middle:[{kind:`social`,at:`town`,present:[`npc2`,`npc3`],title:f(`Slusehuset ved dæmningen`,`The Sluice House at the Dam`),summary:f([`Vejen op ad dalen går over dæmningen, hvor slusevogteren {npc3} bor i et lille stenhus ved spillet, der lukker slusen.`,`{npc3} skal lukke slusen ved solnedgang, men har fået en pung og et brev fra {villain}: Slusen skal lukkes ved middagstid, så vandet når {place} tre timer senere.`,`Her kan heltene opdage, at kapløbet er kortere, end de tror, og måske få slusevogteren til at holde slusen åben.`],[`The road up the valley crosses the dam, where {npc3}, the sluice keeper, lives in a small stone house by the winch that closes the gates.`,`{npc3} is to close the gates at sunset, but has been given a purse and a letter by {villain}: the gates are to close at noon, so the water reaches {place} three hours later.`,`Here the heroes can discover that the race is shorter than they think, and perhaps persuade the sluice keeper to keep the gates open.`]),readAloud:f([`Dæmningen er en lang vold af jord og sten, og i midten brøler vandet ud gennem de åbne sluseporte.`,`Ved det store spil, der lukker portene, står et lille stenhus med røg fra skorstenen.`,`På bænken udenfor sidder en gammel slusevogter og stirrer op ad dalen mod tårnet i mudderet, som om det var et genfærd.`],[`The dam is a long bank of earth and stone, and in the middle the water roars out through the open gates.`,`By the great winch that closes the gates stands a small stone house with smoke rising from the chimney.`,`On the bench outside sits an old sluice keeper, staring up the valley at the tower in the mud as if it were a ghost.`]),details:[f(`{npc3} har fået halvdelen af bestikkelsen i en pung og et brev med {villain}s segl; resten kommer, når vandet står over kirketaget. Pungen ligger på bordet i stenhuset, og brevet ligger under den.`,`{npc3} has received half the bribe in a purse, along with a letter bearing {villain}’s seal; the rest is to come when the water stands over the church roof. The purse lies on the table in the stone house, with the letter under it.`),f(`{npc3} var også slusevogter for tredive år siden og lukkede dengang slusen en dag for tidligt på den gamle herres ordre. Vandet steg på én nat; de fleste nåede ud, fordi {npc2} ringede med klokken, men ikke alle, og klokken blev hængende. De to gamle har ikke talt sammen siden, og et ord fra klokkeren vejer tungere end enhver trussel.`,`{npc3} was sluice keeper thirty years ago too, and closed the gates a day early back then on the old lord’s order. The water rose in a single night; most of the villagers got out because {npc2} rang the bell, but not everyone, and the bell was left hanging. The two old people have not spoken since, and a word from the bell-ringer weighs more than any threat.`),f(`Lukker {npc3} slusen ved middagstid, stiger søen fra den nederste ende af dalen og når kirkegården i {place} tre timer efter. Holder slusevogteren den åben til solnedgang, har heltene hele dagen, og {villain}s plan om at lukke vejen bag sig falder bort.`,`If {npc3} closes the gates at noon, the lake rises from the low end of the valley and reaches the churchyard at {place} three hours later. If the sluice keeper keeps them open until sunset, the heroes have the whole day, and {villain}’s plan to close the way behind the crew falls apart.`)],checks:[m(`Charisma (Persuasion)`,`medium`,f(`{npc3} giver heltene brevet og lover at holde slusen åben til solnedgang; slusevogteren vil ikke drukne nogen for anden gang.`,`{npc3} hands over the letter and promises to keep the gates open until sunset; the sluice keeper will not drown anyone a second time.`),f(`{npc3} nægter at sige noget, men heltene ser pungen, og slusevogteren kan ikke se dem i øjnene; ved middagstid lukker slusen.`,`{npc3} refuses to say anything, but the heroes see the purse, and the sluice keeper cannot meet their eyes; at noon the gates close.`)),m(`Wisdom (Insight)`,`easy`,f(`Slusevogteren er bange og skamfuld, og blikket går hele tiden fra tårnet i mudderet til spillet ved slusen.`,`The sluice keeper is frightened and ashamed, and keeps glancing from the tower in the mud to the winch at the gates.`),f(`{npc3} virker bare gammel og træt af arbejdet.`,`{npc3} just seems old and tired of the work.`))],fight:!1,alternatives:[f(`Tag håndsvinget fra spillet med jer: Så kan slusen ikke lukkes, før heltene bringer det tilbage, uanset hvad {npc3} har lovet.`,`Take the crank from the winch: then the gates cannot be closed until the heroes bring it back, whatever {npc3} has promised.`),f(`Lad {npc2} tale med {npc3}: De to gamle har ikke talt sammen i tredive år, og det tager en halv time, men bagefter holder slusevogteren slusen åben og giver heltene brevet.`,`Let {npc2} talk to {npc3}: the two old people have not spoken in thirty years, and it takes half an hour, but afterwards the sluice keeper keeps the gates open and gives the heroes the letter.`)],dmNotes:f(`Slusehuset er eventyrets skjulte ur: Giv spillerne en chance for at opdage, at fristen er en anden, end de tror. Spil {npc3} som en, der har ventet tredive år på at gøre noget godt igen.`,`The sluice house is the adventure’s hidden clock: give the players a chance to discover that the deadline is not the one they think. Play {npc3} as someone who has waited thirty years to put something right.`)},{kind:`combat`,at:`site`,present:[`npc2`],title:f(`Den druknede gade`,`The Drowned Street`),summary:f([`Kirkestien går over mudderet og ind i {place} ad den druknede gade, hvor husene står uden tag, og mudderet når til knæene.`,`Siden vandet faldt, har nogle {foe} slået sig ned i de druknede huse, og de falder over alle, der kommer forbi; ved gadens indgang har {villain}s folk sat falske pæle, der fører ud i det bundløse gadekær.`,`Fra gaden kan heltene se klokken i tårnet og {villain}s folk, der rigger den til; her afgøres det, om de kan indhente forspringet.`],[`The church path crosses the mud and enters {place} by the drowned street, where the houses stand roofless and the mud is knee-deep.`,`Since the water fell, some {foe} have settled in the drowned houses and fall on anyone who passes; at the mouth of the street, {villain}’s crew has set false stakes leading into the bottomless village pond.`,`From the street the heroes can see the bell in the tower and {villain}’s crew rigging it; here it is decided whether they can close the gap.`]),readAloud:f([`Gaden er en kanal af gråt mudder mellem huse uden tag, og fra vinduerne hænger lange tråde af tørret grøde.`,`Alt lugter af dynd og råddent træ, og for hvert skridt suger mudderet i støvlerne.`,`For enden af gaden rejser kirketårnet sig, og fra glamhullerne lyder hammerslag og råb.`],[`The street is a channel of grey mud between roofless houses, and long strands of dried weed hang from the windows.`,`Everything smells of silt and rotten wood, and with every step the mud sucks at your boots.`,`At the end of the street the church tower rises, and from its louvres come hammering and shouts.`]),details:[f(`Nogle {foe} har slået sig ned i de druknede huse og holder til i mørket bag de tomme vinduer. De angriber, når heltene er midt i gaden, hvor mudderet er dybest, og trækker sig tilbage ind i husene, når halvdelen er faldet.`,`Some {foe} have settled in the drowned houses and keep to the dark behind the empty windows. They attack when the heroes are in the middle of the street, where the mud is deepest, and fall back into the houses once half of them are down.`),f(`Ved gadens indgang står nye pæle med røde klude og viser vej ind over mudderet; de fører lige ud i det gamle gadekær, hvor mudderet ingen bund har. De samme røde klude hænger på bundtet af pæle på {villain}s slæde. {npc2} kender ikke den vej og standser heltene, hvis klokkeren går forrest.`,`At the mouth of the street, new stakes with red rags mark a way across the mud; they lead straight into the old village pond, where the mud has no bottom. The same red rags hang on the bundle of stakes on {villain}’s sledge. If the bell-ringer is leading, {npc2} does not recognise that route and stops the heroes.`),f(`Fra gaden kan man se klokken gennem glamhullerne: grøn af ir og stadig på sin bjælke, mens {villain}s folk rigger en bom til ud over kirkegården. Gaden ender ved kirkegårdsporten, og kommer heltene hertil før middag, er klokken endnu ikke løftet.`,`From the street the bell can be seen through the louvres: green with verdigris and still on its beam, while {villain}’s crew rigs a boom out over the churchyard. The street ends at the churchyard gate, and if the heroes get here before noon, the bell has not yet been lifted.`)],checks:[m(`Wisdom (Survival)`,`medium`,f(`Heltene ser, at pælene står i blødt mudder og er sat i dag; de går uden om gadekæret og finder fast grund langs husmurene.`,`The heroes see that the stakes stand in soft mud and were driven in today; they skirt the pond and find firm ground along the house walls.`),f(`Den forreste helt synker til livet i gadekæret; de andre får vedkommende op med reb, men kampen begynder, mens heltene står i mudderet.`,`The lead hero sinks to the waist in the pond; the others haul them out with a rope, but the fight begins while the heroes are still in the mud.`)),m(`Strength (Athletics)`,`medium`,f(`Heltene kæmper sig frem til en husmur og får fast grund under fødderne; kampen bliver lettere.`,`The heroes fight their way to a house wall and get firm ground underfoot; the fight gets easier.`),f(`Mudderet holder heltene fast; kampen bliver hårdere, til nogen finder en dørtærskel eller en trappe at stå på.`,`The mud holds the heroes fast; the fight is harder until someone finds a doorstep or a stair to stand on.`))],fight:!0,alternatives:[f(`Gå på murene: De fleste huse har stadig deres murkroner, og den, der kan holde balancen, kan gå fra mur til mur over gaden og undgå både mudderet og det meste af kampen.`,`Walk the walls: most houses still have their wall tops, and whoever can keep their balance can go from wall to wall above the street, avoiding both the mud and most of the fight.`),f(`Tag den gamle vej uden om landsbyen i stedet: Den er fast og fri for {foe}, men koster en time.`,`Take the old road around the village instead: it is firm and free of {foe}, but costs an hour.`)],dmNotes:f(`Mudderet er den egentlige fjende i gaden: Lad hvert skridt koste noget, og beskriv sugelyden. Lad heltene se klokken og {villain}s folk for enden af gaden, så de ved, hvor tæt kapløbet er.`,`The mud is the real enemy in the street: let every step cost something, and describe the sucking sound. Let the heroes see the bell and {villain}’s crew at the end of the street, so they know how close the race is.`)},{kind:`exploration`,at:`site`,present:[`npc2`,`villain`],title:f(`Slæden på kirkegården`,`The Sledge in the Churchyard`),summary:f([`På kirkegården står {villain}s slæde og okser, og en håndfuld lejede folk venter på, at klokken bliver firet ned; tårndøren er spærret indefra, og stigen er trukket op.`,`{villain}s folk er ingen krigere og vil ikke slås, men de vil heller ikke lukke nogen ind, og de brokker sig over, at klokkestøberen vil have dem ude af {place} tre timer efter middag.`,`Heltene skal finde en anden vej op til klokken: gennem den oversvømmede krypt, hvor noget har sit leje, op ad det gamle klokkereb inde i kirken eller ved at vinde {villain}s folk over på deres side.`],[`In the churchyard stand {villain}’s sledge and oxen, and a handful of hired hands wait for the bell to be lowered; the tower door is barred from inside, and the ladder has been pulled up.`,`{villain}’s crew are no fighters and will not brawl, but they will not let anyone in either, and they grumble that the bell-founder wants them out of {place} three hours after noon.`,`The heroes must find another way up to the bell: through the flooded crypt, where something has its lair, up the old bell rope inside the church or by winning {villain}’s crew over to their side.`]),readAloud:f([`Kirkegården er et felt af skæve gravsten, halvt begravet i mudder, og midt på den står en stor slæde med to okser, der tygger på tørret grøde.`,`Højt oppe stikker en ny bom ud fra glamhullerne, og et tykt reb hænger fra den ned mod slæden.`,`Ved tårndøren sidder tre lejede folk på en væltet gravsten og deler en flaske, og de rejser sig, da de ser heltene.`],[`The churchyard is a field of leaning gravestones half buried in mud, and in the middle of it stands a big sledge with two oxen chewing on dried weed.`,`High up, a new boom juts from the louvres, and a thick rope hangs from it down toward the sledge.`,`By the tower door three hired hands sit on a fallen gravestone sharing a bottle, and they get to their feet when they see you.`]),details:[f(`{villain}s folk er lejet for en dagløn og har ingen lyst til at slås; de har ordre til at holde alle ude af tårnet, til klokken er nede. De brokker sig over, at klokkestøberen vil have dem ude af {place} tre timer efter middag, "før vandet kommer", selv om alle i {town} siger, at slusen først lukker ved solnedgang.`,`{villain}’s crew work for a day’s wage and have no wish to fight; they are under orders to keep everyone out of the tower until the bell is down. They grumble that the bell-founder wants them out of {place} three hours after noon, "before the water comes", though everyone in {town} says the gates close at sunset.`),f(`Tårndøren er spærret indefra, og stigen er trukket op i tårnet. Men {npc2} husker, at krypten under kirken har en smal trappe op i tårnet; krypten står stadig under vand til knæene, og noget har sit leje dernede. Inde i kirken hænger klokkerebet også stadig ned gennem hullet i hvælvingen, slimet af alger, men helt.`,`The tower door is barred from inside, and the ladder has been pulled up into the tower. But {npc2} remembers that the crypt under the church has a narrow stair up into the tower; the crypt is still knee-deep in water, and something has its lair down there. Inside the church the bell rope also still hangs down through the hole in the vault, slimy with weed but whole.`),f(`Kommer heltene hertil før middag, står {villain} oppe i klokkestolen og leder arbejdet; ved middagstid bliver klokken løftet af bjælken. Råber heltene op til {villain}, tilbyder klokkestøberen dem penge for at gå hjem eller for at bære klokken for {villain}.`,`If the heroes get here before noon, {villain} is up in the belfry directing the work; at noon the bell is lifted off its beam. If the heroes call up to {villain}, the bell-founder offers them money to go home, or to carry the bell for {villain}.`)],checks:[m(`Dexterity (Stealth)`,`medium`,f(`Heltene vader gennem krypten og op ad den smalle trappe uden at vække det, der sover dernede.`,`The heroes wade through the crypt and up the narrow stair without waking what sleeps down there.`),f(`Vandet plasker, og noget rører sig i mørket bag dem; heltene når trappen, men det, der bor i krypten, er vågent og følger efter op i tårnet.`,`The water splashes and something stirs in the dark behind them; the heroes reach the stair, but whatever lives in the crypt is awake and follows them up into the tower.`)),m(`Strength (Athletics)`,`hard`,f(`Heltene klatrer op ad klokkerebet og står i klokkestolen, før {villain} ved, at de er i tårnet.`,`The heroes climb the bell rope and stand in the belfry before {villain} knows they are in the tower.`),f(`Rebet glider, og klatringen tager lang tid; ovenfra ser {villain} heltene komme og gør kniven klar ved bommen.`,`The rope slips and the climb takes a long time; from above {villain} sees the heroes coming and readies a knife at the boom.`))],fight:!1,alternatives:[f(`Vind {villain}s folk over: Fortæl dem om bestikkelsen ved slusen og om søen, der begynder at stige ved middagstid. De vil ikke drukne for klokkestøberens gæld, og lover heltene dem en plads på slæden, lukker de tårndøren op.`,`Win {villain}’s crew over: tell them about the bribe at the sluice and the lake that starts rising at noon. They will not drown for the bell-founder’s debts, and if the heroes promise them a place on the sledge, they open the tower door.`),f(`Tag slæden: Uden okser og slæde kan {villain} ikke få klokken ud, selv når den er nede, og klokkestøberen må forhandle med den, der holder tøjlerne.`,`Take the sledge: without oxen and sledge {villain} cannot get the bell out even once it is down, and the bell-founder must bargain with whoever holds the reins.`)],dmNotes:f(`Kirkegården er kapløbets valg: tre veje op, hver med sin pris. Lad spillerne høre hammerslagene fra tårnet og se rebet stramme sig, så de mærker, at middag nærmer sig.`,`The churchyard is where the race forks: three ways up, each with its price. Let the players hear the hammering from the tower and see the rope tighten, so they feel noon drawing near.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`,`npc2`],title:f(`Klokkestolen ved middagstid`,`The Belfry at Noon`),summary:f([`Ved middagstid står {villain} selv i klokkestolen i {place}, mens klokken bliver løftet af sin gamle bjælke og hænger frit i {villain}s hejseværk.`,`Larmen og det rystende tårn vækker {boss} og nogle {foe} i den oversvømmede krypt, og de kommer op ad tårntrappen mod alle, der er deroppe.`,`Heltene skal klare sig forbi {boss}, hindre {villain} i at kappe rebet og lade klokken styrte og få klokken ned på slæden, før vandet når kirkegården.`],[`At noon {villain} stands in the belfry at {place} in person as the bell is lifted off its old beam and hangs free in {villain}’s hoist.`,`The noise and the shaking tower wake {boss} and some {foe} in the flooded crypt, and they come up the tower stair and attack everyone above.`,`The heroes must get past {boss}, stop {villain} from cutting the rope and letting the bell fall, and get the bell down onto the sledge before the water reaches the churchyard.`]),readAloud:f([`Klokkestolen er et rum af våde bjælker og sollys, der falder skråt ind gennem glamhullerne.`,`Midt i det hænger klokken, større end en okse, grøn af ir og dryppende af mudder, i et nyt reb fra en bom, der stikker ud over kirkegården.`,`Ved bommen står en skikkelse i en fin, mudret kappe med en kniv i den ene hånd og rebet i den anden.`],[`The belfry is a room of wet beams and sunlight falling slantwise through the louvres.`,`In the middle of it hangs the bell, bigger than an ox, green with verdigris and dripping mud, slung from a new rope on a boom that juts out over the churchyard.`,`By the boom stands a figure in a fine, muddy coat, a knife in one hand and the rope in the other.`]),details:[f(`{boss} og nogle {foe} har haft deres leje i den oversvømmede krypt, siden vandet faldt; de tjener ingen og angriber alt, hvad der er i tårnet, også {villain}s folk, der flygter ned ad stigen. {villain} kæmper ikke, men truer med at kappe rebet: Klokken styrter gennem de rådne gulve og revner, men malm er malm, og en revnet klokke kan stadig smeltes.`,`{boss} and some {foe} have laired in the flooded crypt since the water fell; they serve no one and attack everyone in the tower, including {villain}’s crew, who flee down the ladder. {villain} does not fight, but threatens to cut the rope: the bell will crash through the rotten floors and crack, but metal is metal, and a cracked bell can still be melted down.`),f(`Klokken kan fires ned med {villain}s eget hejseværk, men det kræver mindst to par hænder ved spillet og ét ved bommen. Blev slusen lukket ved middagstid, står vandet ved kirkegårdsmuren tre timer senere, og slæden skal være på vej mod strandlinjen inden da.`,`The bell can be lowered with {villain}’s own hoist, but it takes at least two pairs of hands at the winch and one at the boom. If the gates were closed at noon, the water reaches the churchyard wall three hours later, and the sledge must be on its way to the shoreline by then.`),f(`Bliver {villain} trængt op i en krog, eller kommer vandet, før klokken er nede, forhandler klokkestøberen: halvdelen af templets betaling for hjælp til at få klokken ud, eller bare et løfte om ikke at blive overladt til vandet. {npc2} vil slå på klokken én gang, før den bliver firet ned; klangen kan høres helt ud til strandlinjen, hvor folk fra den nye landsby venter med reb.`,`If {villain} is cornered, or the water comes before the bell is down, the bell-founder bargains: half the temple’s payment for help getting the bell out, or just a promise not to be left to the water. {npc2} wants to strike the bell once before it is lowered; its note carries all the way to the shoreline, where the people of the new village wait with ropes.`)],checks:[m(`Dexterity (Acrobatics)`,`medium`,f(`En helt springer hen til bommen og griber {villain}s arm, før kniven når rebet.`,`A hero leaps to the boom and catches {villain}’s arm before the knife reaches the rope.`),f(`Kniven skærer halvt igennem rebet; klokken hænger skævt i de sidste tråde, og heltene har én runde til at sikre den med et nyt reb.`,`The knife cuts halfway through the rope; the bell hangs crooked by its last strands, and the heroes have one round to secure it with a fresh rope.`)),m(`Strength (Athletics)`,`medium`,f(`Heltene firer klokken ned og får den på slæden uden en skramme; okserne trækker an, og kapløbet mod vandet begynder.`,`The heroes lower the bell and get it onto the sledge without a scratch; the oxen take the strain, and the race against the water begins.`),f(`Klokken går for hurtigt ned og rammer slæden så hårdt, at en mede knækker; heltene må skifte den eller trække slæden selv, og det koster en halv time.`,`The bell comes down too fast and hits the sledge so hard that a runner cracks; the heroes must replace it or haul the sledge themselves, which costs half an hour.`))],fight:!0,alternatives:[f(`Lad {npc2} slå på klokken: Klangen går over hele dalen, og folk fra den nye landsby kommer løbende over mudderet med reb og stænger og kan trække slæden, selv om okserne er stukket af.`,`Let {npc2} strike the bell: the note carries over the whole valley, and the people of the new village come running across the mud with ropes and poles and can haul the sledge even if the oxen have bolted.`),f(`Vis {villain} brevet fra slusehuset: Med beviset på bestikkelsen vil templet aldrig tage imod klokken, og klokkestøberen har intet at vinde ved at lade den styrte; {villain} beder i stedet om at komme sikkert ud før vandet.`,`Show {villain} the letter from the sluice house: with proof of the bribe, the temple will never accept the bell, and the bell-founder has nothing to gain by letting it fall; instead {villain} begs to be brought out safely before the water comes.`)],dmNotes:f(`Klimaks er et kapløb i kapløbet: Er vandet på vej, så sig højt hver runde, hvor det står, og lad hvert slag mod tårnet få mørtel til at drysse. {villain} er en desperat skyldner, ikke en kriger; den stærkeste vej ud er at få klokkestøberen til at se, at spillet er tabt.`,`The climax is a race within the race: if the water is coming, call out each round where it stands, and let every blow against the tower shake mortar loose. {villain} is a desperate debtor, not a fighter; the best way to end it is to make the bell-founder see that the game is lost.`)}},Se=e({kernel:()=>Te,scenes:()=>Ee}),Ce=e=>Array.isArray(e)?e.join(` `):e,h=(e,t)=>({da:Ce(e),en:Ce(t)}),g=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),_=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},we=(e,t,n)=>({when:e,event:t,sign:n}),v=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),Te={id:`explore-the-sunken-garden`,titles:[h(`Haven på bunden af søen`,`The Garden at the Bottom of the Lake`),h(`Den hvide feberblomst`,`The White Feverbloom`),h(`Én nat i {place}`,`One Night in {place}`)],missions:[`exploration`,`dungeon-crawl`],foes:`hirelings`,roles:{npc1:h(`en gammel kortmager, der har ventet hele livet på at se bunden af søen`,`an old cartographer who has waited a lifetime to see the bottom of the lake`),npc2:h(`en urtekyndig, der plejer de feversyge i {town}`,`a herbalist who nurses the fever-sick of {town}`),npc3:h(`en slusevogter, der passer {villain}s sluser på dæmningen`,`a sluice-keeper who works {villain}’s sluices on the dam`),villain:h(`en rig møller, hvis forfader byggede dæmningen og druknede haven`,`a wealthy miller whose ancestor built the dam and drowned the garden`)},hook:h(`{npc1} venter på heltene oppe på dæmningen ved solnedgang med en afskrift af havens gamle plan og beder dem gå ned og kortlægge {place} helt ned til drivhuset på bunden og bringe frøene af den hvide feberblomst op, før {villain} lukker sluserne ved daggry.`,`{npc1} waits for the heroes up on the dam at sunset with a copy of the garden’s old plan and asks them to go down and chart {place} all the way to the glasshouse at the bottom, and to bring up the seed of the white feverbloom before {villain} closes the sluices at dawn.`),people:{npc1:{wants:h(`Vil have kortet over {place} færdigt og lagt på rådets bord, før vandet kommer tilbage.`,`Wants the chart of {place} finished and laid on the council’s table before the water comes back.`),secret:h(`Pejlede søens dybde fra en båd for {villain} sidste sommer og fik godt betalt for at tie; det var de pejlinger, der viste {villain}, hvor drivhuset ligger.`,`Sounded the lake from a boat for {villain} last summer and was paid well to keep quiet; those soundings showed {villain} where the glasshouse lies.`)},npc2:{wants:h(`Vil have den hvide feberblomst til at gro i {town} igen, før sensommeren tager flere af de svageste.`,`Wants the white feverbloom growing in {town} again before late summer takes more of the weakest.`),secret:h(`Solgte familiens gamle opskrift på feberteen til {villain} for en pung sølv og har skammet sig over det, siden det blev klart, hvad {villain} ville med den.`,`Sold their family’s old recipe for the fever tea to {villain} for a purse of silver, and has been ashamed of it ever since realising what {villain} wanted it for.`)},npc3:{wants:h(`Vil beholde sin plads på dæmningen uden at have nogens død på samvittigheden.`,`Wants to keep their post on the dam without anyone’s death on their conscience.`),secret:h(`Har set lygter ved den gamle vandlednings udløb tre nætter i træk og fik ekstra løn af {villain} for at se den anden vej.`,`Has seen lanterns at the outlet of the old conduit three nights running and was paid extra by {villain} to look the other way.`)}},premise:h([`For to hundrede år siden byggede {villain}s forfader dæmningen ved {town} og druknede {place}, apotekernes have i dalen, og med den den hvide feberblomst, den eneste kur mod den sumpfeber, der siden har plaget egnen hver sensommer.`,`Nu er søen tømt, så dæmningen kan repareres, og haven ligger blottet med sine trapper, springvand og sit knuste drivhus; under drivhuset ligger havens frøkælder, forseglet med bly.`,`{villain}, der ejer dæmningen og sluserne, har solgt frøene på forhånd til et apotekerhus i hovedstaden og vil tømme kælderen i nat.`,`Ved daggry lukker {villain} sluserne, og vandet skjuler både haven og tyveriet.`],[`Two hundred years ago {villain}’s ancestor built the dam at {town} and drowned {place}, the apothecaries’ garden in the valley, and with it the white feverbloom, the only cure for the marsh fever that has plagued the region every late summer since.`,`Now the lake has been drained so the dam can be repaired, and the garden lies bare with its stairs, fountains and shattered glasshouse; beneath the glasshouse lies the garden’s seed cellar, sealed with lead.`,`{villain}, who owns the dam and the sluices, has sold the seed in advance to an apothecary house in the capital and means to empty the cellar tonight.`,`At dawn {villain} closes the sluices, and the water hides both the garden and the theft.`]),goal:h(`Kortlæg {place} helt ned til drivhuset på bunden, og bring frøene af den hvide feberblomst og kortet hjem til {town}, før vandet vender tilbage ved daggry.`,`Chart {place} all the way down to the glasshouse at the bottom, and bring the white feverbloom seed and the chart home to {town} before the water returns at dawn.`),objective:{target:h(`Krukkerne med frø af den hvide feberblomst i frøkælderen under drivhuset`,`The jars of white feverbloom seed in the seed cellar beneath the glasshouse`),state:h(`På hylderne i frøkælderen under drivhuset på havens bund, blandt hundrede andre krukker, der kun er mærket med havens tegn. Fra midnat står {villain} selv dernede med den stjålne side fra plantebogen og udvælger krukkerne, mens {boss} og {villain}s lejede {foe} bærer dem op gennem den gamle vandledning, og vandet stiger i drivhuset.`,`On the shelves of the seed cellar beneath the glasshouse at the bottom of the garden, among a hundred other jars marked only with the garden’s signs. From midnight {villain} stands down there in person with the page stolen from the planting book, choosing the jars, while {boss} and {villain}’s hired {foe} carry them up the old conduit and the water rises in the glasshouse.`),resolution:h([`Få mindst én krukke feberblomst op ad vandtrappen eller ud gennem vandledningen, før vandet fylder kælderen ved daggry, og tegn kælderen ind på kortet, så rådet kan se, hvad der stod der.`,`Kan heltene ikke redde krukkerne, er et færdigt kort med de tømte hylder det eneste bevis på, hvad {villain} tog.`],[`Get at least one jar of feverbloom up the water stair or out through the conduit before the water fills the cellar at dawn, and draw the cellar onto the chart so that the council can see what was stored there.`,`If the heroes cannot save the jars, a finished chart showing the emptied shelves is the only proof of what {villain} took.`])},villain:{want:h(`At sælge frøene af den hvide feberblomst til apotekerhuset i hovedstaden for en formue, så møllen, der har tabt penge i årevis, kan betale sig igen.`,`To sell the white feverbloom seed to the apothecary house in the capital for a fortune, so that the mill, which has lost money for years, can pay its way again.`),plan:h([`Først lånte {villain} havens plantebog i byens arkiv og rev siden om frøkælderen ud, så kun {villain} ved, hvilke tegn på krukkerne der betyder feberblomst.`,`I tre nætter har {villain}s lejede {foe} gravet den gamle vandledning fri fra bakken ved den anden bred og ned til kælderen; i nat bryder de forseglingen, og ved midnat går {villain} selv derned for at udvælge krukkerne og lader samtidig sluserne lukke halvt.`,`Ved daggry lukkes sluserne helt, haven drukner igen med alle spor af tyveriet, og {villain} går op gennem vandledningen med de rigtige krukker.`],[`First, {villain} borrowed the garden’s planting book from the town archive and tore out the page about the seed cellar, so that only {villain} knows which signs on the jars mean feverbloom.`,`For three nights {villain}’s hired {foe} have been digging out the old conduit from the hill on the far shore down to the cellar; tonight they break the seal, and at midnight {villain} goes down in person to choose the jars and has the sluices half closed at the same time.`,`At dawn the sluices close fully, the garden drowns again with every trace of the theft, and {villain} climbs out through the conduit with the right jars.`]),weakness:h([`{villain} kan ikke svømme, har aldrig før været nede på søbunden og regner med vandledningen som eneste vej ud.`,`Og uden den stjålne side kan {villain} ikke skelne feberblomstens krukker fra de hundrede andre, så den, der får fat i siden eller selv kender tegnet, er et skridt foran {villain}.`],[`{villain} cannot swim, has never been down on the lake bed before and is counting on the conduit as the only way out.`,`And without the stolen page {villain} cannot tell the feverbloom jars from the hundred others, so whoever gets hold of the page, or knows the sign, is a step ahead of {villain}.`])},stakes:h(`Forsvinder frøene, eller drukner de med haven, har {town} intet at stille op mod sumpfeberen: Den tager de svageste hver sensommer, og den eneste kur bliver solgt dyrt i hovedstaden, mens {npc1}s kort ender med et hvidt felt midt i søen.`,`If the seed vanishes or drowns with the garden, {town} has no defence against the marsh fever: it takes the weakest every late summer, and the only cure is sold dear in the capital, while {npc1}’s chart ends up with a blank space in the middle of the lake.`),clock:{start:h(`Solnedgang. Søen har været tømt i tre dage, dæmningen er repareret, og {villain}, der ejer sluserne, har slået fast, at de lukkes ved daggry, om ni timer. {npc1} har bedt om flere dage og fået nej.`,`Sunset. The lake has been empty for three days, the dam is repaired, and {villain}, who owns the sluices, has ruled that they close at dawn, nine hours from now. {npc1} asked for a few more days and was refused.`),ticks:[we(h(`Efter 2 timer`,`After 2 hours`),h(`{villain}s lejede {foe} bryder blyforseglingen på lugen i drivhusets gulv og begynder at bære krukker op gennem vandledningen.`,`{villain}’s hired {foe} break the lead seal on the hatch in the glasshouse floor and begin carrying jars up through the conduit.`),h(`Lygter bevæger sig nede ved drivhuset, og lyden af knust glas bærer over den tørre søbund.`,`Lanterns move down by the glasshouse, and the sound of breaking glass carries across the dry lake bed.`)),we(h(`Efter 5 timer (ved midnat)`,`After 5 hours (at midnight)`),h(`{villain} går selv ned i frøkælderen med den stjålne side for at udvælge krukkerne, og efter {villain}s ordre begynder {npc3}, slusevogteren, at lukke sluserne halvt, så vandet stiger i havens nederste bassiner.`,`{villain} goes down into the seed cellar in person with the stolen page to choose the jars, and on {villain}’s orders {npc3}, the sluice-keeper, begins to close the sluices halfway, so the water rises in the garden’s lowest basins.`),h(`Sluseværkets hjul skriger oppe på dæmningen, åen i den gamle kanal går i stå, og der står blankt vand i de nederste bassiner, hvor der før var mudder.`,`The sluice wheels shriek up on the dam, the stream in the old channel falters, and bright water stands in the lowest basins where there was mud before.`)),we(h(`Efter 9 timer (ved daggry)`,`After 9 hours (at dawn)`),h(`Sluserne lukkes helt, vandet strømmer ind i drivhuset og fylder frøkælderen, og {villain} går op gennem vandledningen med de krukker, {villain} har valgt.`,`The sluices close fully, the water pours into the glasshouse and fills the seed cellar, and {villain} climbs up through the conduit with the jars {villain} has chosen.`),h(`Vandet stiger synligt op ad havens trapper, og i drivhuset står det til knæene.`,`The water climbs visibly up the garden’s stairs and stands knee-deep in the glasshouse.`))],deadline:h(`Efter 9 timer, ved daggry, er det for sent: Vandet fylder drivhuset og frøkælderen, {villain} er oppe med feberblomstens krukker, og alt andet i {place} er druknet igen.`,`After 9 hours, at dawn, it is too late: the water fills the glasshouse and the seed cellar, {villain} is out with the feverbloom jars, and everything else in {place} has drowned again.`)},clues:{who:[_(`town`,h(`{npc1} har opdaget, at siden om frøkælderen mangler i havens plantebog i byens arkiv, og arkivets udlånsbog viser, at kun {villain} har haft bogen ude i år.`,`{npc1} has found that the page about the seed cellar is missing from the garden’s planting book in the town archive, and the archive’s lending book shows that only {villain} has had the book out this year.`),h(`{villain} har revet siden ud for at være den eneste, der ved, hvilke krukker der rummer feberblomsten.`,`{villain} tore the page out to be the only one who knows which jars hold the feverbloom.`),g([`Udlånsbog, {town}s arkiv:`,`Havens plantebog, ét bind. Udlånt til {villain}, møller. Afleveret efter ni dage.`,`Tilføjet af arkivaren: Side 41, frøkælderen, mangler.`],[`Lending book, archive of {town}:`,`The garden’s planting book, one volume. Lent to {villain}, miller. Returned after nine days.`,`Added by the archivist: page 41, the seed cellar, is missing.`])),_(`town`,h(`{npc2}, den urtekyndige, fortæller, at {villain} i sidste måned spurgte, hvordan feberblomstens frø ser ud, og hvor længe de kan holde sig i en forseglet krukke, og betalte godt for, at {npc2} ikke sagde det til nogen.`,`{npc2}, the herbalist, says that last month {villain} asked what feverbloom seed looks like and how long it keeps in a sealed jar, and paid well for {npc2} to tell no one.`),h(`{villain} ved, at frøene ligger i haven, og vil have dem.`,`{villain} knows the seed is in the garden and means to have it.`)),_(`town`,h(`{npc3}, slusevogteren, har en skriftlig ordre fra {villain} om at begynde at lukke sluserne ved midnat i stedet for ved daggry, selv om himlen er klar.`,`{npc3}, the sluice-keeper, has a written order from {villain} to begin closing the sluices at midnight instead of at dawn, though the sky is clear.`),h(`{villain} vil have vand i haven, før nogen kan nå at kortlægge den færdig.`,`{villain} wants water in the garden before anyone can finish charting it.`),g([`Til slusevogteren:`,`Begynd at lukke sluserne ved midnat, halvt, og helt ved daggry.`,`Der er storm på vej. Tal ikke om det. – {villain}`],[`To the sluice-keeper:`,`Close the sluices halfway at midnight and fully at dawn.`,`There is a storm coming. Do not speak of it. — {villain}`])),_(`site`,h(`Ved foden af vandtrappen ligger en taske, som {villain}s mandskab har tabt, med en skriftlig ordre i.`,`At the foot of the water stair lies a satchel dropped by {villain}’s crew, with a written order inside.`),h(`{villain} står bag tyveriet, kommer selv ned ved midnat og vil knuse alt, der ikke skal sælges.`,`{villain} is behind the theft, will come down in person at midnight and means to smash everything that is not for sale.`),g([`Til holdet ved drivhuset:`,`Alle krukker med et klokketegn pakkes i halm. Jeg udvælger selv de rigtige ved midnat.`,`Resten slås i stykker; køberen vil være den eneste med havens frø. – {villain}`],[`To the crew at the glasshouse:`,`Every jar with a bell sign is to be packed in straw. I will choose the right ones myself at midnight.`,`The rest are to be smashed; the buyer wants to be the only one with the garden’s seed. — {villain}`]))],where:[_(`town`,h(`{npc1}s afskrift af havens gamle plan viser vejen ned gennem haven og et kammer under drivhuset med en streg, der løber op ad bakken.`,`{npc1}’s copy of the garden’s old plan shows the way down through the garden and a chamber beneath the glasshouse with a line running up the hill.`),h(`Frøkælderen ligger under drivhuset på havens bund, og vandledningen fra bakken er en anden vej ind.`,`The seed cellar lies beneath the glasshouse at the bottom of the garden, and the conduit from the hill is a second way in.`),g([`Apotekernes have i {place}, tegnet efter plantebogen:`,`Vandtrappen: syv terrasser ned fra porten. Stenlabyrinten: neden for trappens fod.`,`Drivhuset nederst, og under det frøkælderen, kølet af vandledningen fra kilden på bakken.`],[`The apothecaries’ garden at {place}, drawn from the planting book:`,`The water stair: seven terraces down from the gate. The stone maze: below the foot of the stair.`,`The glasshouse at the bottom, and beneath it the seed cellar, cooled by the conduit from the spring on the hill.`])),_(`site`,h(`Midt ned ad vandtrappen går friske slæbespor efter en slæde og aftryk af mange fødder, alle på vej ned mod drivhuset, og ingen af dem kommer op igen.`,`Down the middle of the water stair run fresh drag marks from a sledge and the prints of many feet, all heading down toward the glasshouse, and none of them comes back up.`),h(`Mandskabet arbejder ved drivhuset og har en anden vej ud end trappen.`,`The crew is at work by the glasshouse and has a way out other than the stair.`)),_(`site`,h(`Midt i stenlabyrinten står en høj sten med havens plan hugget ind: drivhuset nederst, et kammer under det og over kammerets luge en klokke med tre dråber.`,`In the middle of the stone maze stands a tall stone carved with the garden’s plan: the glasshouse at the bottom, a chamber beneath it and, over the chamber’s hatch, a bell with three drops.`),h(`Frøkælderen ligger under drivhuset, og klokken med tre dråber er feberblomstens tegn.`,`The seed cellar lies beneath the glasshouse, and the bell with three drops is the sign of the feverbloom.`)),_(`town`,h(`Fra slusehuset på dæmningen kan man se lygter på bakken ved den anden bred, hvor den gamle vandlednings udløb er gravet fri, og hvor to tomme vogne holder ved hullet.`,`From the sluice house on the dam, lanterns can be seen on the hill by the far shore, where the outlet of the old conduit has been dug open and two empty carts wait by the hole.`),h(`{villain}s folk går ind og ud af frøkælderen gennem vandledningen, og den vej regner {villain} også med at komme ud.`,`{villain}’s people go in and out of the seed cellar through the conduit, and that is the way {villain} means to come out too.`))]},endings:{success:h(`Kortet ligger på rådets bord med frøkælderen tegnet ind, og krukkerne med hvid feberblomst står hos {npc2}. Næste sommer gror feberblomsten i bede bag byens feberhus, {villain} må forklare rådet, hvad lejede folk lavede i vandledningen, og {npc1} beder heltene være med, når søen en dag bliver tømt igen.`,`The chart lies on the council’s table with the seed cellar drawn in, and the jars of white feverbloom are safe in {npc2}’s keeping. Next summer the feverbloom grows in beds behind the town’s fever house, {villain} must explain to the council what hired hands were doing in the conduit, and {npc1} asks the heroes to come along when the lake is drained again one day.`),partial:h(`Heltene kommer op med nogle få krukker, men {villain} slipper ud gennem vandledningen med resten, og haven drukner, før kortet er færdigt. {npc2} får feberblomsten til at spire i et enkelt bed, men ingen kan bevise, hvor {villain}s køber i hovedstaden har sine frø fra.`,`The heroes come up with a few jars, but {villain} gets out through the conduit with the rest, and the garden drowns before the chart is finished. {npc2} gets the feverbloom to sprout in a single bed, but nobody can prove where {villain}’s buyer in the capital got the seed.`),failure:h(`Ved daggry stiger vandet over drivhuset, og haven er væk igen i to hundrede år. {villain}s køber sælger feberblomst i hovedstaden til en pris, ingen i {town} kan betale, {npc1}s kort ender med et hvidt felt midt i søen, og sensommeren kommer med feberen, som den altid har gjort.`,`At dawn the water rises over the glasshouse, and the garden is gone again for two hundred years. {villain}’s buyer sells feverbloom in the capital at a price nobody in {town} can pay, {npc1}’s chart ends up with a blank space in the middle of the lake, and late summer brings the fever as it always has.`)}},Ee={opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc2`],title:h(`Bunden af søen`,`The Bottom of the Lake`),summary:h([`Ved solnedgang står {npc1}, en gammel kortmager, oppe på dæmningen sammen med heltene og ser ned på den tømte sø, hvor {place} er dukket op af mudderet.`,`{npc1} beder dem kortlægge haven helt ned til drivhuset og bringe frøene af den hvide feberblomst op, før {villain} lukker sluserne ved daggry; {npc2}, den urtekyndige, er kommet med for at fortælle, hvad frøene betyder for {town}.`,`Byen kan give flere svar, men hver omvej koster tid, og nede ved drivhuset er nogen allerede i gang.`],[`At sunset {npc1}, an old cartographer, stands up on the dam with the heroes and looks down on the drained lake, where {place} has risen out of the mud.`,`{npc1} asks them to chart the garden all the way down to the glasshouse and to bring up the seed of the white feverbloom before {villain} closes the sluices at dawn; {npc2}, the herbalist, has come along to explain what the seed means to {town}.`,`There are more answers in town, but every detour costs time, and down by the glasshouse someone is already at work.`]),readAloud:h([`Fra dæmningen ligner søen en stor, grå skål, der er ved at tørre ind, og nede på bunden ligger en have.`,`Terrasser falder ned ad skråningen som en kæmpes trappe, stenfigurer står til knæene i mudder imellem dem, og nederst glimter jernribberne af et drivhus i det sidste lys.`,`Ved siden af heltene ryster en gammel kortmager et rullet papir ud og holder det fast mod vinden med begge hænder.`],[`From the dam the lake looks like a great grey bowl drying out, and down at its bottom lies a garden.`,`Terraces fall down the slope like a giant’s stair, stone figures stand knee-deep in mud between them, and at the very bottom the iron ribs of a glasshouse glint in the last of the light.`,`Beside you, an old cartographer shakes out a rolled sheet of paper and holds it down against the wind with both hands.`]),details:[h(`{npc1}s afskrift af havens plan viser vandtrappen, stenlabyrinten og drivhuset nederst med et kammer under det, men i byens arkiv mangler siden om kammeret i havens plantebog, og udlånsbogen viser, at kun {villain} har haft bogen ude i år. {npc1} har bedt {villain} om flere dage og fået nej.`,`{npc1}’s copy of the garden’s plan shows the water stair, the stone maze and the glasshouse at the bottom with a chamber beneath it, but in the town archive the page about the chamber is missing from the garden’s planting book, and the lending book shows that only {villain} has had the book out this year. {npc1} asked {villain} for a few more days and was refused.`),h(`{npc2} fortæller om den hvide feberblomst: en lille hvid klokke, der kun groede i apotekernes have, og hvis te brød sumpfeberen. Feberen har taget fem af de svageste i {town} denne sommer. I sidste måned kom {villain} og spurgte, hvordan frøene ser ud, og hvor længe de kan holde sig, og betalte godt for, at {npc2} tav.`,`{npc2} tells of the white feverbloom: a little white bell-shaped flower that grew only in the apothecaries’ garden and whose tea broke the marsh fever. The fever has taken five of the weakest in {town} this summer. Last month {villain} came asking what the seed looks like and how long it keeps, and paid well for {npc2}’s silence.`),h(`Vejen ned går ad jernstigen ved dæmningens fod og videre ned ad vandtrappen, og på vejen kommer heltene forbi slusehuset, hvor {npc3}, slusevogteren, holder vagt. En tur rundt om søen til den anden bred tager en time; ethvert andet besøg i byen koster en halv time.`,`The way down is by the iron ladder at the foot of the dam and on down the water stair, and on the way the heroes pass the sluice house, where {npc3}, the sluice-keeper, keeps watch. A walk round the lake to the far shore takes an hour; any other visit in town costs half an hour.`)],checks:[v(`Wisdom (Insight)`,`medium`,h(`{npc1} tilstår at have pejlet søens dybde fra en båd for {villain} sidste sommer. Pejlingerne viste præcis, hvor drivhuset ligger, og nu frygter {npc1}, hvad {villain} ville med dem.`,`{npc1} confesses to sounding the lake from a boat for {villain} last summer. The soundings showed exactly where the glasshouse lies, and now {npc1} fears what {villain} wanted them for.`),h(`{npc1} virker bare gammel og ivrig. Heltene hører først om pejlingerne, når de selv nævner {villain}.`,`{npc1} seems merely old and eager. The heroes do not hear about the soundings until they mention {villain} themselves.`)),v(`Intelligence (History)`,`easy`,h(`Heltene ser, at stregen fra kammeret op ad bakken er en vandledning, og at den kommer ud ved den anden bred: en anden vej ind i frøkælderen.`,`The heroes see that the line from the chamber up the hill is a conduit, and that it comes out on the far shore: a second way into the seed cellar.`),h(`Stregen ligner bare en sti. Heltene forstår først, hvad den er, når de ser lygterne ved den anden bred.`,`The line looks like a mere path. The heroes do not understand what it is until they see the lanterns on the far shore.`))],fight:!1,alternatives:[h(`Gå direkte ned ad jernstigen og vandtrappen: Heltene sparer tiden i byen, men ved intet om ordren om at lukke sluserne ved midnat.`,`Go straight down the iron ladder and the water stair: the heroes save the time in town but know nothing of the order to close the sluices at midnight.`),h(`Gå rundt om søen til vandledningens udløb på den anden bred: Det tager en time og fører uden om labyrinten, men i vandledningen går {villain}s lejede {foe} frem og tilbage med krukker.`,`Walk round the lake to the conduit’s outlet on the far shore: it takes an hour and avoids the maze, but {villain}’s hired {foe} go to and fro in the conduit with jars.`)],dmNotes:h(`Lad haven ligge dernede som et løfte: Beskriv den fra dæmningen, før nogen går ned, og lad et lys bevæge sig ved drivhuset, mens {npc1} taler. Sig højt, hvad hver omvej koster.`,`Let the garden lie down there like a promise: describe it from the dam before anyone goes down, and let a light move by the glasshouse while {npc1} talks. Say aloud what every detour costs.`)},middle:[{kind:`social`,at:`town`,present:[`npc3`],title:h(`Slusehuset på dæmningen`,`The Sluice House on the Dam`),summary:h([`Midt på dæmningen ligger slusehuset over de store hjul, der åbner og lukker sluserne, og her holder {npc3}, slusevogteren, vagt alene.`,`{npc3} har en skriftlig ordre fra {villain} om at begynde at lukke sluserne ved midnat i stedet for ved daggry, og fra vinduet kan man se lygter ved den anden bred.`,`Heltene kan vinde {npc3} for sig og købe tid eller i det mindste finde ud af, hvor {villain}s folk går ind.`],[`In the middle of the dam stands the sluice house over the great wheels that open and close the sluices, and here {npc3}, the sluice-keeper, keeps watch alone.`,`{npc3} has a written order from {villain} to begin closing the sluices at midnight instead of at dawn, and from the window, lanterns can be seen on the far shore.`,`The heroes can win {npc3} over and buy time, or at least learn where {villain}’s people go in.`]),readAloud:h([`Slusehuset lugter af tjære og vådt reb, og gulvet ryster svagt under de store hjul og kæder.`,`En slusevogter sidder ved vinduet med en pibe, der for længst er gået ud, og et brev ligger foldet ud på bordet under en lysestage.`,`Langt ude over den tørre sø blinker to lygter på bakken ved den anden bred.`],[`The sluice house smells of tar and wet rope, and the floor trembles faintly under the great wheels and chains.`,`A sluice-keeper sits at the window with a pipe that went out long ago, and a letter lies unfolded on the table under a candlestick.`,`Far out across the dry lake two lanterns wink on the hill by the far shore.`]),details:[h(`Ordren er fra {villain}: Sluserne skal lukkes halvt ved midnat og helt ved daggry, "på grund af storm", selv om himlen er klar. {npc3} skylder {villain} sin plads og sit hus på dæmningen og tør ikke sige nej.`,`The order is from {villain}: the sluices are to be half closed at midnight and fully at dawn, "because of a storm", though the sky is clear. {npc3} owes {villain} their post and their house on the dam and dares not refuse.`),h(`Fra vinduet kan man se den gamle vandlednings udløb på bakken ved den anden bred: gravet fri, med to tomme vogne ved hullet. {npc3} har set lygter dér tre nætter i træk og fik ekstra løn for at se den anden vej.`,`From the window the outlet of the old conduit can be seen on the hill by the far shore: dug open, with two empty carts by the hole. {npc3} has seen lanterns there three nights running and was paid extra to look the other way.`),h(`Holder {npc3} sluserne åbne til daggry, stiger vandet ikke før til sidst, men ved midnat opdager {villain}, at åen stadig løber, og skynder sig med krukkerne. Lukker {npc3} som befalet, står der vand i havens nederste bassiner fra midnat, og det stiger en hånd i timen.`,`If {npc3} keeps the sluices open until dawn, the water does not rise until the very end, but at midnight {villain} notices that the stream is still running and hurries with the jars. If {npc3} closes them as ordered, water stands in the garden’s lowest basins from midnight and rises a hand’s breadth an hour.`)],checks:[v(`Charisma (Persuasion)`,`medium`,h(`{npc3} lover at "glemme" ordren til daggry og giver heltene brevet med som bevis. Vandet stiger ikke ved midnat.`,`{npc3} promises to "forget" the order until dawn and gives the heroes the letter as proof. The water does not rise at midnight.`),h(`{npc3} holder sig til ordren, men lader brevet ligge, så heltene kan læse det. Ved midnat begynder sluserne at lukke.`,`{npc3} sticks to the order but leaves the letter where the heroes can read it. At midnight the sluices begin to close.`)),v(`Wisdom (Perception)`,`easy`,h(`Heltene ser, at lygterne ved den anden bred står ved et hul i bakken, og at en tredje lygte forsvinder ned i det: Der er en vej ind i haven, som ikke går ad trappen.`,`The heroes see that the lanterns on the far shore stand by a hole in the hill, and that a third lantern disappears down into it: there is a way into the garden that does not go by the stair.`),h(`Lygterne ligner fiskere på bredden. Heltene forstår først, hvad de er, når de finder sporene på vandtrappen, der ikke kommer op igen.`,`The lanterns look like fishers on the shore. The heroes do not understand what they are until they find the tracks on the water stair that never come back up.`))],fight:!1,alternatives:[h(`Kil sluseværkets store hjul fast med en bjælke: Så kan sluserne ikke lukkes ved midnat, men {npc3} mister sin plads, og {villain} hører om det ved midnat.`,`Wedge the great sluice wheel with a beam: then the sluices cannot close at midnight, but {npc3} loses their post, and {villain} hears of it at midnight.`),h(`Tag ordren med til rådet: Rådet kan intet gøre før i morgen, men brevet er et bevis, der vejer tungt, når heltene kommer op igen.`,`Take the order to the council: the council can do nothing before morning, but the letter is proof that weighs heavily when the heroes come back up.`)],dmNotes:h(`Slusehuset er stedet, hvor spillerne kan købe sig tid. Spil {npc3} som et ærligt menneske i klemme, ikke som en skurk; den, der viser {npc3} respekt, får mere end den, der truer.`,`The sluice house is where the players can buy time. Play {npc3} as an honest person in a tight spot, not a villain; whoever shows {npc3} respect gets more than whoever threatens.`)},{kind:`exploration`,at:`site`,present:[],title:h(`Vandtrappen`,`The Water Stair`),summary:h([`Vejen ned i {place} går ad vandtrappen, havens store trappe af brede stentrin, der falder ned over syv terrasser mod drivhuset på bunden.`,`Her ligger havens vidundere i mudderet: stenfisk, et blomsterur og et springvand, der stadig løber, og hver terrasse, heltene tegner ind, er et felt på {npc1}s kort.`,`Midt ned ad trappen går friske slæbespor, der ikke kommer op igen, og ved trappens fod ligger en taske, som {villain}s mandskab har tabt.`],[`The way down into {place} is the water stair, the garden’s great flight of broad stone steps falling over seven terraces toward the glasshouse at the bottom.`,`Here the garden’s wonders lie in the mud: stone fish, a flower clock and a fountain that still runs, and every terrace the heroes draw in fills another square of {npc1}’s chart.`,`Down the middle of the stair run fresh drag marks that never come back up, and at the foot of the stair lies a satchel dropped by {villain}’s crew.`]),readAloud:h([`Vandtrappen falder ned gennem haven i lange, brede trin af grå sten, glatte af slam, og på hvert trin sidder en stenfisk med åben mund, som om vandet lige er holdt op med at løbe.`,`Til begge sider ligger terrasserne i mudder, fulde af muslingeskaller, døde siv og en enkelt fisk, der stadig spræller i en pyt.`,`På tredje terrasse står en ring af tolv bede om et solur, og længere nede pibler klart vand fra næbbet på en hejre af bronze.`],[`The water stair falls through the garden in long, broad steps of grey stone, slick with silt, and on every step sits a stone fish with an open mouth, as if the water had only just stopped running.`,`On both sides the terraces lie in mud, full of mussel shells, dead reeds and a lone fish still flapping in a puddle.`,`On the third terrace a ring of twelve beds surrounds a sundial, and further down clear water trickles from the beak of a bronze heron.`]),details:[h(`Blomsteruret på tredje terrasse er tolv bede i en ring om et solur, ét for hver af dagens timer; bronzehejren på femte terrasse får stadig vand fra kilden på bakken og giver det eneste rene vand på søbunden. At gå hele trappen ned tager en halv time; hver terrasse, heltene tegner ordentligt ind undervejs, lægger ti minutter til, så alle syv tegnet ind koster en time og 40 minutter.`,`The flower clock on the third terrace is twelve beds in a ring round a sundial, one for each hour of the day; the bronze heron on the fifth terrace is still fed by the spring on the hill and gives the only clean water on the lake bed. Walking down the whole stair takes half an hour; every terrace the heroes draw in properly on the way adds ten minutes, so with all seven drawn in, the descent takes an hour and 40 minutes.`),h(`Mudderet ved siden af trappen er blødt som grød og går til livet nogle steder; selve trappen er glat, men sikker. Midt ned ad trinene går friske slæbespor efter en slæde og aftryk af mange fødder, alle på vej ned mod drivhuset, og ingen af dem kommer op igen.`,`The mud beside the stair is soft as porridge and waist-deep in places; the stair itself is slick but safe. Down the middle of the steps run fresh drag marks from a sledge and the prints of many feet, all heading down toward the glasshouse, and none of them comes back up.`),h(`Ved trappens fod ligger en taske, som {villain}s mandskab har tabt, med {villain}s ordre om at pakke alle krukker med et klokketegn og slå resten i stykker. Efter midnat står der vand i bassinerne neden for trappen, hvis sluserne er begyndt at lukke.`,`At the foot of the stair lies a satchel dropped by {villain}’s crew, holding {villain}’s order to pack every jar with a bell sign and smash the rest. After midnight, water stands in the basins below the stair if the sluices have begun to close.`)],checks:[v(`Intelligence (Investigation)`,`medium`,h(`Heltene tegner trappen og terrasserne nøjagtigt ind, og kortet viser det, sporene siger: Alle går ned til drivhuset, og ingen kommer tilbage. Mandskabet har en anden vej ud.`,`The heroes draw the stair and the terraces in accurately, and the chart shows what the tracks say: everyone goes down to the glasshouse, and nobody comes back. The crew has another way out.`),h(`Kortet bliver groft og skævt. Heltene kan bruge en halv time mere på at gøre det rigtigt eller gå videre med en skitse, som rådet senere vil tvivle på.`,`The chart comes out rough and crooked. The heroes can spend another half hour getting it right, or go on with a sketch the council will doubt later.`)),v(`Wisdom (Survival)`,`easy`,h(`Heltene finder den faste kant langs trappen og holder sig fra det dybe mudder.`,`The heroes find the firm edge along the stair and keep out of the deep mud.`),h(`En helt synker i til livet og må trækkes op af de andre; det koster ti minutter og en ting fra oppakningen, som mudderet beholder.`,`One hero sinks in to the waist and must be hauled out by the others; it costs ten minutes and one item from the pack, which the mud keeps.`))],fight:!1,alternatives:[h(`Følg vandet fra bronzehejren: Det løber i en smal stenrende lige ned mod drivhuset og sparer en halv time, men renden er glat, og den går uden om labyrinten, så heltene ikke ser stenen i midten.`,`Follow the water from the bronze heron: it runs in a narrow stone channel straight down toward the glasshouse and saves half an hour, but the channel is slippery, and it goes round the maze, so the heroes miss the stone at its heart.`),h(`Klatr op på en terrassemur, og se ud over hele haven: Det giver kortet et overblik, og heltene kan tælle lygterne nede ved drivhuset.`,`Climb onto a terrace wall and look out over the whole garden: it gives the chart its overview, and the heroes can count the lanterns down by the glasshouse.`)],dmNotes:h(`Giv vidunderne plads: Det er en have, ingen har set i to hundrede år. Spørg spillerne, hvad de tegner ind, og lad lyset nede ved drivhuset minde dem om, at nogen er der før dem.`,`Give the wonders room: this is a garden no one has seen for two hundred years. Ask the players what they draw in, and let the light down by the glasshouse remind them that someone got there first.`)},{kind:`combat`,at:`site`,present:[],title:h(`Stenlabyrinten`,`The Stone Maze`),summary:h([`Neden for vandtrappen ligger havens labyrint af lave stenmure, hugget med alle havens planter, og her har {villain} sat nogle {foe} på vagt for at holde nysgerrige væk fra drivhuset.`,`Midt i labyrinten står en høj sten med havens plan og feberblomstens tegn, en klokke med tre dråber.`,`Den, der kan læse væggene, kender de rigtige krukker i kælderen uden {villain}s stjålne side.`],[`Below the water stair lies the garden’s maze of low stone walls, carved with every plant of the garden, and here {villain} has set some {foe} on watch to keep the curious away from the glasshouse.`,`In the middle of the maze stands a tall stone bearing the garden’s plan and the feverbloom’s sign, a bell with three drops.`,`Whoever can read the walls will know the right jars in the cellar without {villain}’s stolen page.`]),readAloud:h([`Labyrintens mure når kun til hoften, men de står tæt, og mudderet mellem dem er dybt.`,`På hver sten er der hugget en plante, blade, rødder og blomster, og under hver et lille tegn.`,`Midt i labyrinten rejser sig en høj sten, og bag den knitrer et lille bål, hvor ingen burde sidde.`],[`The maze walls are only hip-high, but they stand close together, and the mud between them is deep.`,`On every stone a plant is carved, with its leaves, roots and flowers, and beneath each one is a small sign.`,`In the middle of the maze a tall stone rises, and behind it a small fire crackles where no one ought to be sitting.`]),details:[h(`Vagterne er {foe}, som {villain} har betalt for at holde nysgerrige væk; de kender labyrintens gange og bruger murene som dækning. Begynder en kamp, løber en af dem mod drivhuset for at advare {boss}, medmindre heltene standser løberen.`,`The guards are {foe} that {villain} has paid to keep the curious away; they know the maze’s paths and use the walls as cover. If a fight starts, one of them runs for the glasshouse to warn {boss}, unless the heroes stop the runner.`),h(`Den høje sten viser havens plan: drivhuset nederst, et kammer under det og en streg op ad bakken, vandledningen. Over kammerets luge er der hugget en klokke med tre dråber. Den samme klokke står på væggene ved feberblomsten, og de samme tegn står på krukkerne i kælderen.`,`The tall stone shows the garden’s plan: the glasshouse at the bottom, a chamber beneath it and a line up the hill, the conduit. Over the chamber’s hatch a bell with three drops is carved. The same bell marks the feverbloom on the walls, and the same signs are stamped on the jars in the cellar.`),h(`Murene giver halv dækning, og den, der springer over en mur, lander i mudder til knæene og bruger resten af sin bevægelse. Efter midnat står der vand i labyrintens nederste gange, hvis sluserne er begyndt at lukke.`,`The walls give half cover, and anyone who jumps a wall lands knee-deep in mud and loses the rest of their movement. After midnight, water stands in the lowest paths of the maze if the sluices have begun to close.`)],checks:[v(`Intelligence (Investigation)`,`medium`,h(`Heltene læser væggene og stenen: Klokken med tre dråber er feberblomsten, og i kælderen vil de kende dens krukker med det samme.`,`The heroes read the walls and the stone: the bell with three drops is the feverbloom, and in the cellar they will know its jars at a glance.`),h(`Heltene tegner stenen af til kortet, men først i kælderen, når {villain} rækker ud efter de samme krukker, forstår de, hvilket tegn der er feberblomstens.`,`The heroes copy the stone onto the chart, but only in the cellar, when {villain} reaches for the same jars, do they understand which sign is the feverbloom’s.`)),v(`Dexterity (Stealth)`,`medium`,h(`Heltene når bålet uset og vælger selv, hvor kampen skal stå, eller smutter forbi mod drivhuset.`,`The heroes reach the fire unseen and choose where the fight happens, or slip past toward the glasshouse.`),h(`Vagterne hører dem i mudderet, og en af dem løber mod drivhuset; når heltene når frem, venter {boss} på dem.`,`The guards hear them in the mud, and one runs for the glasshouse; when the heroes get there, {boss} is waiting for them.`))],fight:!0,alternatives:[h(`Gå oven på murene: Det er hurtigt og tørt, men vagterne ved bålet ser heltene på lang afstand.`,`Walk along the tops of the walls: it is quick and dry, but the guards at the fire see the heroes from far off.`),h(`Kast en lygte ud i mudderet på den anden side af labyrinten, og lad vagterne gå efter den, mens heltene læser stenen.`,`Throw a lantern into the mud on the far side of the maze and let the guards go after it while the heroes read the stone.`)],dmNotes:h(`Labyrinten er både kamp og nøgle: Mens nogle helte kæmper, kan en anden læse væggene. Den, der kender feberblomstens tegn, sparer dyrebare minutter i kælderen.`,`The maze is both a fight and a key: while some heroes fight, another can read the walls. Whoever knows the feverbloom’s sign saves precious minutes in the cellar.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:h(`Frøkælderen under drivhuset`,`The Seed Cellar beneath the Glasshouse`),summary:h([`Nederst i haven står drivhuset, og i gulvet står lugen til frøkælderen åben; dernede står hylde efter hylde med forseglede krukker.`,`Fra midnat er {villain} her selv med lampe og den stjålne side og udvælger feberblomstens krukker, mens {boss} og {villain}s lejede {foe} bærer kasser op gennem vandledningen, og efter midnat siver vandet ind.`,`Heltene skal redde krukkerne, tegne kælderen ind på kortet og komme op, før vandet fylder den ved daggry.`],[`At the bottom of the garden stands the glasshouse, and in its floor the hatch to the seed cellar lies open; below is shelf after shelf of sealed jars.`,`From midnight {villain} is here in person with a lamp and the stolen page, choosing the feverbloom jars, while {boss} and {villain}’s hired {foe} carry crates up through the conduit, and after midnight the water seeps in.`,`The heroes must save the jars, draw the cellar onto the chart and get out before the water fills it at dawn.`]),readAloud:h([`Drivhuset rejser sig af mudderet som skelettet af en kæmpefisk: buede jernribber, hvor kun hver anden rude stadig sidder, grøn af alger.`,`Midt på gulvet står en luge åben, og fra hullet stiger lampelys og en kold lugt af voks og jord.`,`Nedenunder står hylde efter hylde med lerkrukker, og ved den bageste væg holder en skikkelse i en god frakke, mudret til knæene, et gulnet papir op mod lampen og peger på krukke efter krukke.`],[`The glasshouse rises out of the mud like the skeleton of a giant fish: curved iron ribs in which only every other pane remains, green with algae.`,`In the middle of the floor a hatch stands open, and lamplight and a cold smell of wax and earth rise from the hole.`,`Below is shelf after shelf of clay jars, and by the back wall a figure in a good coat, muddy to the knees, holds a yellowed paper up to the lamp and points at jar after jar.`]),details:[h(`{boss} og nogle {foe} er hyret af {villain} til at grave og bære og vogter lugen og vandledningen. De kæmper for deres løn og flygter op gennem vandledningen, når {boss} falder, eller når vandet når dem til knæene. {villain} kæmper ikke, holder sig bag dem med siden og byder heltene halvdelen af krukkerne, når kampen vender. Kommer heltene før midnat, er {villain} her ikke endnu, men kommer ned gennem vandledningen ved midnat og går lige ind i dem.`,`{boss} and some {foe} have been hired by {villain} to dig and carry, and they guard the hatch and the conduit. They fight for their pay and flee up the conduit when {boss} falls or when the water reaches their knees. {villain} does not fight, keeps behind them with the page and offers the heroes half the jars when the fight turns. If the heroes arrive before midnight, {villain} is not here yet, but comes down the conduit at midnight and walks straight into them.`),h(`Der står hundrede krukker på hylderne, forseglet med voks og hver mærket med et tegn; tolv bærer klokken med tre dråber. Uden tegnet eller siden må heltene åbne krukke efter krukke og lede efter de sorte, flade frø, og hver krukke koster et minut. Vandledningen begynder i den bageste væg og fører op til bakken ved den anden bred; den er {villain}s eneste vej ud, for {villain} kan ikke svømme.`,`A hundred jars stand on the shelves, sealed with wax and each marked with a sign; twelve bear the bell with three drops. Without the sign or the page the heroes must open jar after jar looking for the flat black seeds, and every jar costs a minute. The conduit starts in the back wall and leads up to the hill on the far shore; it is {villain}’s only way out, for {villain} cannot swim.`),h(`Efter midnat siver vandet ind gennem drivhusets gulv og drypper ned gennem lugen; det stiger en hånd i timen og fylder kælderen ved daggry. Holdt {npc3} sluserne åbne, er kælderen tør til daggry. At tegne kælderen ind på kortet tager ti minutter. Er vandledningen spærret, eller står nogen i den, har {villain} ingen vej ud og forhandler om at blive ført op ad vandtrappen.`,`After midnight the water seeps in through the glasshouse floor and drips down through the hatch; it rises a hand’s breadth an hour and fills the cellar at dawn. If {npc3} kept the sluices open, the cellar stays dry until dawn. Drawing the cellar onto the chart takes ten minutes. If the conduit is blocked, or someone stands in it, {villain} has no way out and bargains to be led up the water stair.`)],checks:[v(`Strength (Athletics)`,`medium`,h(`En helt river kassen med feberblomstens krukker fra bærerne og får den op gennem lugen, før nogen kan slå den i stykker.`,`A hero wrenches the crate of feverbloom jars from the carriers and gets it up through the hatch before anyone can smash it.`),h(`Kassen falder, og to krukker går i stykker; resten er hele, men heltene må samle frøene op af mudderet med hænderne, og det koster en runde.`,`The crate falls and two jars break; the rest are whole, but the heroes must gather the seed out of the mud by hand, and it costs a round.`)),v(`Charisma (Intimidation)`,`medium`,h(`Med vandet stigende og ordren fra tasken i heltenes hånd giver {villain} op, rækker dem siden og beder om at blive ført op ad trappen.`,`With the water rising and the order from the satchel in the heroes’ hands, {villain} gives up, hands them the page and begs to be led up the stair.`),h(`{villain} griber den nærmeste kasse og vader mod vandledningen, mens {boss} spærrer vejen for heltene.`,`{villain} grabs the nearest crate and wades for the conduit while {boss} blocks the heroes’ way.`))],fight:!0,alternatives:[h(`Spær vandledningen fra bakken, før heltene går ned, hvis de har fundet udløbet: Så er {villain} lukket inde med vandet og giver krukkerne fra sig for at komme op.`,`Block the conduit from the hill before going down, if the heroes have found the outlet: then {villain} is shut in with the water and gives up the jars to get out.`),h(`Lok {boss} og bærerne væk fra lugen med et råb fra vandledningen, mens én helt tager kassen med klokketegnet.`,`Draw {boss} and the carriers away from the hatch with a shout from the conduit while one hero takes the crate with the bell sign.`)],dmNotes:h(`Lad vandet være uret: Sig, hvor højt det står, hver gang en ny runde begynder efter midnat. {villain} er ingen kriger, kun en, der er bange for vand, og den frygt er heltenes bedste våben.`,`Let the water be the clock: say how high it stands every time a new round begins after midnight. {villain} is no fighter, only someone afraid of water, and that fear is the heroes’ best weapon.`)}},De=e({kernel:()=>je,scenes:()=>Me}),Oe=e=>Array.isArray(e)?e.join(` `):e,y=(e,t)=>({da:Oe(e),en:Oe(t)}),ke=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),b=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},Ae=(e,t,n)=>({when:e,event:t,sign:n}),x=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),je={id:`intrigue-the-two-seals`,titles:[y(`To segl på ét brev`,`Two Seals on One Letter`),y(`Revnen i seglet`,`The Crack in the Seal`),y(`Told ved porten`,`Toll at the Gate`)],missions:[`intrigue`,`investigation`],foes:`people`,roles:{npc1:y(`en oldermand for bondelauget i dalen`,`an alderman of the valley farmers’ guild`),npc2:y(`en borgmester, der skal læse tillægget op ved byporten`,`a mayor who is to read the addendum aloud at the town gate`),npc3:y(`en gravør, der skar et sølvsegl for {villain} i foråret`,`an engraver who cut a silver seal for {villain} in the spring`),villain:y(`en kornhandler i rådet, der har nøglen til byens arkiv`,`a grain merchant on the council who holds the key to the town archive`)},hook:y(`{npc1}, oldermand for bondelauget, lægger ved midnat lavets ægte segl på bordet foran heltene og beder dem bevise, at seglet på tillægget er falsk, før borgmesteren læser det op ved byporten ved middagstid.`,`{npc1}, alderman of the farmers’ guild, lays the guild’s true seal on the table before the heroes at midnight and asks them to prove that the seal on the addendum is false before the mayor reads it aloud at the town gate at noon.`),people:{npc1:{wants:y(`Vil have bøndernes ord renset, før nogen i dalen løfter en plejl mod byen.`,`Wants the farmers’ name cleared before anyone in the valley raises a flail against the town.`),secret:y(`Lovede de unge bønder, at de må slå til ved porten, hvis tillægget bliver læst op, og kan ikke længere holde dem tilbage.`,`Promised the young farmers that they may take up their flails at the gate if the addendum is read out, and can no longer hold them back.`)},npc2:{wants:y(`Vil have penge til den nye bro uden at miste dalens korn og byens fred.`,`Wants money for the new bridge without losing the valley’s grain or the town’s peace.`),secret:y(`Tvivlede på tillægget fra første dag, men lod det passere, fordi byen mangler penge til broen.`,`Doubted the addendum from the first day, but let it pass because the town needs money for the bridge.`)},npc3:{wants:y(`Vil holde sig ude af det hele og have sit værksted i fred.`,`Wants to stay out of the whole affair and work in peace.`),secret:y(`Lavede et ekstra aftryk af det nye segl i voks og gemte det, fordi {villain}s betaling virkede for stor til at være ærlig.`,`Made an extra wax impression of the new seal and kept it, because {villain}’s payment seemed too large to be honest.`)}},premise:y([`I hundrede år har bønderne i dalen solgt deres korn på markedet i {town} uden told, sådan som markedsbrevet siger, beseglet med byens tårn og bondelaugets kornneg.`,`I foråret fandt {villain}, en kornhandler i rådet og arkivets værge, et tillæg til brevet i arkivet i {place}, det gamle tårn ved floden: Tillægget bærer begge segl og giver byen ret til told ved porten.`,`Bønderne sværger, at deres segl er falsk, og byen kalder dem edsbrydere, men det er {villain}, der har ladet seglet skære.`,`Bliver tillægget læst op ved høstmarkedet i morgen middag, slår bønderne til ved porten, og når dalen og byen ligger i fejde, må bønderne sælge deres korn til {villain} ved gårdene for halv pris.`],[`For a hundred years the farmers of the valley have sold their grain at the market in {town} free of toll, as laid down in the market charter, which is sealed with the town’s tower and the farmers’ sheaf.`,`This spring {villain}, a grain merchant on the council and keeper of the archive, found an addendum to the charter in the archive at {place}, the old tower by the river: it bears both seals and gives the town the right to a toll at the gate.`,`The farmers swear that their seal on it is false, and the town calls them oath-breakers, but it was {villain} who had the seal cut.`,`If the addendum is read out at the harvest market at noon tomorrow, the farmers will take up their flails at the gate, and with the valley and the town at feud, they will have to sell their grain to {villain} at the farm gates for half its worth.`]),goal:y(`Bevis, at bondelaugets segl på tillægget er falsk, og bring beviset fra {place} til {npc2} ved byporten, før tillægget bliver læst op ved middagstid.`,`Prove that the farmers’ seal on the addendum is false, and bring the proof from {place} to {npc2} at the town gate before the addendum is read out at noon.`),objective:{target:y(`Det falske bondesegl, som {villain} har gemt i arkivets seglskab`,`The false copy of the farmers’ seal that {villain} has hidden in the archive’s seal cabinet`),state:y(`I hvælvingen under {place}, mellem hundrede gamle segl i et skab med små skuffer, bevogtet af {boss} og nogle {foe}, som {villain} har hyret til at holde bønderne væk fra arkivet. Ved daggry går {villain} selv derned for at smelte det i et fyrfad og brænde bøndernes gamle breve, der kan afsløre det.`,`In the vault beneath {place}, among a hundred old seals in a cabinet of small drawers, guarded by {boss} and some {foe} that {villain} has hired to keep the farmers away from the archive. At dawn {villain} goes down there in person to melt it in a brazier and burn the farmers’ old letters that could expose it.`),resolution:y([`Tag seglet, før det smelter, og helst også bundtet med de gamle breve, og læg dem frem for {npc2} ved porten før middag, sammen med gravørens ord, hvis heltene har det.`,`Er seglet smeltet, kan de gamle breve med revnen og {npc3}s vidnesbyrd stadig standse oplæsningen, men ikke bevise, hvem der stod bag.`],[`Seize the seal before it melts, and the bundle of old letters if possible, and lay them before {npc2} at the gate before noon, with the engraver’s word if the heroes have it.`,`If the seal has been melted, the old letters with the crack and {npc3}’s testimony can still stop the reading, but cannot prove who was behind it.`])},villain:{want:y(`At holde bønderne ude af markedet, så de må sælge deres korn ved gårdene til {villain} for halv pris, og selv sælge det dyrt i {town}, når vinteren kommer.`,`To keep the farmers out of the market, so that they must sell their grain at the farm gates to {villain} for half its worth, and to sell it dear in {town} when winter comes.`),plan:y([`Først lod {villain} en gravør skære en kopi af bondelaugets segl i sølv og beseglede et falsk tillæg til markedsbrevet med den og med byens eget segl fra arkivet.`,`I foråret fandt {villain} tillægget i arkivet, så alle kunne se det, og fik rådet til at kræve told af bøndernes vogne fra og med høstmarkedet.`,`Ved daggry går {villain} selv ned i hvælvingen under {place} for at smelte det falske segl og brænde de gamle breve, der kan afsløre det, og ved middagstid står {villain} ved porten, når tillægget bliver læst op.`],[`First, {villain} had an engraver cut a copy of the farmers’ guild seal in silver and sealed a false addendum to the market charter with it and with the town’s own seal from the archive.`,`In the spring {villain} found the addendum in the archive for all to see and persuaded the council to demand toll from the farmers’ carts, starting with the harvest market.`,`At dawn {villain} will go down into the vault beneath {place} in person to melt the false seal and burn the old letters that could expose it, and at noon {villain} will stand at the gate as the addendum is read out.`]),weakness:y([`{villain} er pertentlig og bad gravøren skære seglet rent, uden den grimme revne i det gamle aftryk; {villain} ved ikke, at revnen har stået i hvert ægte aftryk siden flodåret for halvtreds år siden.`,`Og seglet er af sølv: {villain} vil hellere smelte det om end kaste det i floden, og det tager tid.`],[`{villain} is fastidious and had the engraver cut the seal clean, without the ugly crack in the old impression, not knowing that the crack has shown in every true impression since the flood year fifty years ago.`,`And the seal is silver: {villain} would rather melt it down than throw it in the river, and that takes time.`])},stakes:y(`Bliver tillægget læst op ved middagstid, kræver vagten told af den første vogn, og bønderne svarer med plejlene: Fejden mellem {town} og dalen begynder med blod på brostenene, markedet står tomt, og dalens korn ender i {villain}s magasiner for halv pris.`,`If the addendum is read out at noon, the watch demands toll from the first cart, and the farmers answer with their flails: the feud between {town} and the valley begins with blood on the cobbles, the market stands empty, and the valley’s grain ends up in {villain}’s granaries at half its worth.`),clock:{start:y(`Midnat. Bønderne fra dalen har slået lejr uden for byporten med vogne fulde af korn og plejle under presenningerne, og ved middagstid læser {npc2}, borgmesteren, tillægget op ved porten.`,`Midnight. The valley farmers have camped outside the town gate with carts full of grain and flails under the tarpaulins, and at noon {npc2}, the mayor, is to read the addendum aloud at the gate.`),ticks:[Ae(y(`Efter 2 timer`,`After 2 hours`),y(`{villain} hører, at nogen stiller spørgsmål om seglet, og sender {boss} og nogle {foe} efter {npc3}, gravøren, som bliver låst inde i {place}, så ingen kan tale med {npc3} før middag.`,`{villain} hears that someone is asking about the seal and sends {boss} and some {foe} for {npc3}, the engraver, who is locked up in {place} so that nobody can talk to {npc3} before noon.`),y(`Gravørens dør står åben, lampen brænder stadig, og værktøjet ligger spredt over gulvet.`,`The engraver’s door stands open, the lamp is still burning, and tools lie scattered across the floor.`)),Ae(y(`Efter 6 timer (ved daggry)`,`After 6 hours (at dawn)`),y(`{villain} låser sig ind i hvælvingen under {place} med en kurv trækul, tænder fyrfadet og begynder at smelte det falske segl og brænde bundtet med bøndernes gamle breve.`,`{villain} goes down into the vault beneath {place} with a basket of charcoal, lights the brazier and begins to melt the false seal and burn the bundle of the farmers’ old letters.`),y(`Røg stiger op af tårnets skorsten, der ellers aldrig ryger i høsttiden, og vagterne ved tårnets dør er blevet flere.`,`Smoke rises from the tower chimney, which otherwise never smokes at harvest time, and there are more guards at the tower door.`)),Ae(y(`Efter 12 timer (ved middagstid)`,`After 12 hours (at noon)`),y(`Markedsklokken ringer, {npc2} læser tillægget op ved porten, vagten kræver told af den første vogn, og bønderne løfter plejlene.`,`The market bell rings, {npc2} reads the addendum aloud at the gate, the watch demands toll from the first cart, and the farmers raise their flails.`),y(`Klokken ringer over byen, og der bliver helt stille ved porten, da borgmesteren træder op på trappen.`,`The bell rings over the town, and the gate falls silent as the mayor climbs the steps.`))],deadline:y(`Efter 12 timer, ved middagstid, er det for sent: Tillægget er læst op, den første vogn er standset ved porten, og fejden mellem {town} og dalen er begyndt.`,`After 12 hours, at noon, it is too late: the addendum has been read out, the first cart has been stopped at the gate, and the feud between {town} and the valley has begun.`)},clues:{who:[b(`town`,y(`{npc3}, gravøren, skar i foråret et segl i sølv for {villain} efter et gammelt voksaftryk af bondelaugets kornneg og fik besked på at udelade den hårfine streg tværs over neget.`,`{npc3}, the engraver, cut a seal in silver for {villain} this spring from an old wax impression of the farmers’ sheaf and was told to leave out the fine line across the sheaf.`),y(`{villain} har ladet bondelaugets segl efterligne, og kopien er uden revnen.`,`{villain} had the farmers’ seal copied, and the copy has no crack.`)),b(`town`,y(`{npc1} ved, at {villain}s karle allerede har været rundt på gårdene i dalen og tilbudt at købe kornet ved laden, "når I ikke længere må sælge i byen".`,`{npc1} knows that {villain}’s hired men have already been round the farms of the valley offering to buy the grain at the barn door, "once you can no longer sell in town".`),y(`{villain} vidste på forhånd, at bønderne ville blive holdt ude af markedet, og vil tjene på det.`,`{villain} knew in advance that the farmers would be kept out of the market, and means to profit from it.`)),b(`site`,y(`I læsestuen ligger arkivets protokol, og på siden for det år, tillægget skulle være lagt ind, er en linje skrabet ud og skrevet om med friskere blæk i {villain}s pæne håndskrift.`,`In the reading room lies the archive’s register, and on the page for the year the addendum was supposedly placed there, one line has been scraped away and rewritten in fresher ink in {villain}’s neat hand.`),y(`Tillægget kom aldrig ind i arkivet ad lovlig vej; {villain} har selv skrevet det ind i protokollen.`,`The addendum never entered the archive by lawful means; {villain} wrote it into the register personally.`),ke([`Lagt ind i arkivet, høstmåneden:`,`Nr. 7: Tillæg til markedsbrevet, med byens og bondelaugets segl.`,`(Linjen er skrabet ud og skrevet om. Under den kan man stadig skimte: Nr. 7: Regnskab for broen.)`],[`Placed in the archive, harvest month:`,`No. 7: Addendum to the market charter, with the seals of the town and the farmers’ guild.`,`(The line has been scraped away and rewritten. Beneath it, the old entry can still be made out: No. 7: Accounts for the bridge.)`])),b(`town`,y(`{npc2}, borgmesteren, fortæller, at det var {villain}, der fandt tillægget, {villain}, der bad om at få arkivets eneste nøgle, og {villain}, der selv betaler vagterne ved tårnet.`,`{npc2}, the mayor, says it was {villain} who found the addendum, {villain} who asked to hold the archive’s only key and {villain} who pays the guards at the tower out of {villain}’s own purse.`),y(`{villain} har haft tillægget og arkivet i sin hånd fra første dag.`,`{villain} has had the addendum and the archive in hand from the first day.`))],where:[b(`town`,y(`Under gravørens arbejdsbord ligger en seddel med {villain}s håndskrift.`,`Under the engraver’s bench lies a note in {villain}’s hand.`),y(`Det falske segl ligger gemt blandt de gamle segl i arkivets skab i {place}.`,`The false seal is hidden among the old seals in the archive’s cabinet at {place}.`),ke([`Til gravøren:`,`Skær en nøjagtig kopi af vedlagte aftryk, i sølv, men uden den grimme streg tværs over neget.`,`Seglet skal ligge blandt sine brødre i arkivets skab. Tal ikke om det. – {villain}`],[`To the engraver:`,`Cut an exact copy of the enclosed impression, in silver, but without the ugly line across the sheaf.`,`The seal is to lie among its brothers in the archive’s cabinet. Do not speak of it. — {villain}`])),b(`site`,y(`I læsestuen i {place} fører friske dryp af rød lak hen til trappen ned til hvælvingen, og krogen til seglskabets nøgle er tom.`,`In the reading room of {place}, fresh drips of red sealing wax lead to the stair down to the vault, and the hook for the seal cabinet’s key is empty.`),y(`Nogen har for nylig været nede ved seglskabet med varm lak, og nøglen er hos {villain}.`,`Someone has recently been down at the seal cabinet with hot wax, and {villain} has the key.`)),b(`site`,y(`I læsestuen ligger arkivets fortegnelse over seglskabet, og ud for skuffe 7 står en ny linje med frisk blæk.`,`In the reading room lies the archive’s catalogue of the seal cabinet, and the entry for drawer 7 is a new line in fresh ink.`),y(`Det falske segl ligger i skuffe 7 i seglskabet i hvælvingen, forklædt som et gammelt segl, bønderne skulle have lagt fra sig.`,`The false seal lies in drawer 7 of the seal cabinet in the vault, disguised as an old seal the farmers supposedly laid aside.`),ke([`Seglskabet, hvælvingen:`,`Skuffe 6: byens gamle segl, tre stykker.`,`Skuffe 7: bondelaugets gamle segl, aflagt, sølv. Lagt ind af arkivets værge.`],[`The seal cabinet, the vault:`,`Drawer 6: the town’s old seals, three pieces.`,`Drawer 7: the farmers’ guild’s old seal, retired, silver. Placed there by the keeper of the archive.`])),b(`town`,y(`{npc1} har set lys i kælderen under {place} sent om natten, hver gang bønderne var i byen med korn i foråret, og har kunnet lugte varm lak fra kældervinduet.`,`{npc1} has seen a light in the cellar beneath {place} late at night every time the farmers were in town with grain this spring, and has smelled hot wax at the cellar window.`),y(`{villain} har arbejdet med segl og lak i hvælvingen under tårnet.`,`{villain} has been working with seals and wax in the vault beneath the tower.`))]},endings:{success:y(`Ved porten lægger heltene det falske segl ved siden af bøndernes ægte, og hele markedet kan se, at revnen mangler. {npc2} river tillægget over, {villain} bliver ført bort af vagten, og bønderne kører deres vogne ind på torvet uden told; {npc1} lover heltene en plads ved dalens høstbord, så længe de lever.`,`At the gate the heroes lay the false seal beside the farmers’ true one, and the whole market can see that the crack is missing. {npc2} tears up the addendum, {villain} is led away by the watch, and the farmers drive their carts into the square free of toll; {npc1} promises the heroes a place at the valley’s harvest table for as long as they live.`),partial:y(`Heltene standser oplæsningen med de gamle breve eller gravørens ord, men uden det falske segl kan ingen bevise, hvem der lod det skære. Tillægget bliver lagt til side, freden holder, og {villain} sidder stadig i rådet med nøglen til arkivet og et nag til heltene.`,`The heroes stop the reading with the old letters or the engraver’s word, but without the false seal nobody can prove who had it cut. The addendum is set aside, the peace holds, and {villain} still sits on the council with the key to the archive and a grudge against the heroes.`),failure:y(`Ved middagstid bliver tillægget læst op, vagten standser den første vogn, og plejlene svinger ved porten. Fejden lukker markedet, dalens korn ender i {villain}s magasiner for halv pris, og til vinter sælger {villain} brødet dyrt til en by, der stadig tror, at bønderne er edsbrydere.`,`At noon the addendum is read out, the watch stops the first cart, and the flails swing at the gate. The feud closes the market, the valley’s grain ends up in {villain}’s granaries at half its worth, and come winter {villain} sells the bread dear to a town that still believes the farmers are oath-breakers.`)}},Me={opening:{kind:`opening`,at:`town`,present:[`npc1`],title:y(`Oldermanden ved midnat`,`The Alderman at Midnight`),summary:y([`Ved midnat kommer {npc1}, oldermand for bondelauget, ind fra bøndernes lejr uden for byporten og lægger lavets ægte segl på bordet foran heltene.`,`I morgen middag læser {npc2}, borgmesteren, et tillæg til markedsbrevet op ved porten, og bønderne sværger, at deres segl på det er falsk; {npc1} beder heltene bevise det, før de unge bønder slår til.`,`Byen har tre spor: borgmesteren med tillægget, den eneste gravør, der skærer i sølv, og arkivet i {place}, hvor tillægget blev fundet.`],[`At midnight {npc1}, alderman of the farmers’ guild, comes in from the farmers’ camp outside the town gate and lays the guild’s true seal on the table before the heroes.`,`At noon tomorrow {npc2}, the mayor, is to read an addendum to the market charter aloud at the gate, and the farmers swear their seal on it is false; {npc1} asks the heroes to prove it before the young farmers lash out.`,`The town holds three leads: the mayor with the addendum, the only engraver who cuts silver and the archive at {place}, where the addendum was found.`]),readAloud:y([`Kroen er næsten tom, da en bredskuldret skikkelse i en støvet kappe sætter sig ved heltenes bord uden at spørge.`,`Ud af en læderpung kommer et segl af bronze: et kornneg med syv aks, og tværs over neget en hårfin revne.`,`Gennem vinduet ses bøndernes bål uden for byporten, og fra lejren lyder lav sang og lyden af nogen, der sliber et blad.`],[`The inn is nearly empty when a broad-shouldered figure in a dusty cloak sits down at your table without asking.`,`Out of a leather pouch comes a bronze seal: a sheaf with seven ears, and across the sheaf a hairline crack.`,`Through the window the farmers’ fires burn outside the town gate, and from the camp come low singing and the sound of someone whetting a blade.`]),details:[y(`Revnen kom i seglet i flodåret for halvtreds år siden, da lavets kiste blev skyllet ud af laden, og siden har den stået i hvert aftryk, bønderne har sat på et brev. Tillægget siges at være beseglet for tredive år siden, men byen tror ikke på bønderne, når de taler om deres eget segl.`,`The seal cracked in the flood year fifty years ago, when the guild chest was washed out of the barn, and ever since the crack has shown in every impression the farmers have set on a letter. The addendum is said to have been sealed thirty years ago, but the town will not take the farmers’ word about their own seal.`),y(`{npc1} ved, at {villain}s karle allerede har været rundt på gårdene og tilbudt at købe kornet ved laden, "når I ikke længere må sælge i byen". Tillægget ligger hos {npc2} i rådhuset, kun én gravør i {town} skærer i sølv, nemlig {npc3}, og til arkivet i {place} har {villain} den eneste nøgle. Hvert besøg i byen koster en halv time.`,`{npc1} knows that {villain}’s hired men have already been round the farms offering to buy the grain at the barn door, "once you can no longer sell in town". The addendum is with {npc2} at the town hall, only one engraver in {town}, {npc3}, cuts silver, and {villain} holds the only key to the archive at {place}. Every visit in town costs half an hour.`),y(`I lejren har de unge bønder plejle under presenningerne og vil ikke betale en eneste mønt i told. Går heltene ud i lejren, kan de se, hvor tæt det er på at gå galt, og vinde de unge bønders tålmodighed for en nat.`,`In the camp the young farmers keep flails under the tarpaulins and will not pay a single coin in toll. If the heroes go out to the camp, they see how close things are to going wrong, and can win the young farmers’ patience for one night.`)],checks:[x(`Wisdom (Insight)`,`easy`,y(`{npc1} taler sandt om seglet, men skjuler noget: Presset tilstår {npc1} at have lovet de unge bønder, at de må slå til ved porten, hvis tillægget bliver læst op.`,`{npc1} speaks the truth about the seal but is hiding something: pressed, {npc1} admits to having promised the young farmers that they may take up their flails at the gate if the addendum is read out.`),y(`Heltene ser kun en træt og vred oldermand. Løftet til de unge bønder hører de først om ved porten.`,`The heroes see only a tired, angry alderman. They hear of the promise to the young farmers only at the gate.`)),x(`Intelligence (History)`,`medium`,y(`Heltene ved, at et segl, der er revnet, viser revnen i alle aftryk bagefter: Er tillægget ægte, må revnen stå i det. Gamle breve med bøndernes segl fra årene efter flodåret kan bevise det, og dem har arkivet.`,`The heroes know that a cracked seal shows the crack in every impression afterwards: if the addendum is genuine, the crack must be in it. Old letters with the farmers’ seal from the years after the flood year can prove it, and the archive has them.`),y(`Heltene forstår først, hvad revnen betyder, når de selv ser tillægget hos borgmesteren.`,`The heroes do not grasp what the crack means until they see the addendum at the mayor’s.`))],fight:!1,alternatives:[y(`Gå ud i bøndernes lejr først: Det koster en halv time, men de unge bønder lover at vente, til heltene er tilbage, og {npc1} kan følge med til borgmesteren.`,`Go out to the farmers’ camp first: it costs half an hour, but the young farmers promise to wait until the heroes return, and {npc1} can come along to the mayor.`),y(`Gå direkte mod {place}: Heltene sparer tiden i byen, men ved ikke, hvad de leder efter i arkivet, eller hvem der vogter det.`,`Head straight for {place}: the heroes save the time in town, but do not know what they are looking for in the archive or who guards it.`)],dmNotes:y(`Lad seglet gå rundt ved bordet, og lad spillerne selv finde revnen. Når de forstår, at revnen er et vidne, har eventyret sin tråd.`,`Pass the seal round the table and let the players find the crack themselves. Once they understand that the crack is a witness, the adventure has its thread.`)},middle:[{kind:`investigation`,at:`town`,present:[`npc2`],title:y(`Revnen i seglet`,`The Crack in the Seal`),summary:y([`I rådhuset sidder {npc2}, borgmesteren, sent oppe med tillægget og talen til i morgen.`,`Lægger heltene et frisk aftryk af bøndernes ægte segl ved siden af seglet på tillægget, mangler revnen, men borgmesteren tør ikke standse oplæsningen på det alene: Bønderne kan have revnet deres segl med vilje.`,`Kun de gamle breve i arkivet eller selve det falske segl kan overbevise {npc2}, og arkivet er {villain}s.`],[`In the town hall {npc2}, the mayor, is sitting up late over the addendum and tomorrow’s speech.`,`If the heroes lay a fresh impression of the farmers’ true seal beside the seal on the addendum, the crack is missing, but the mayor dares not stop the reading on that alone: the farmers could have cracked their seal on purpose.`,`Only the old letters in the archive or the false seal itself can convince {npc2}, and the archive is in {villain}’s keeping.`]),readAloud:y([`Rådssalen er mørk bortset fra en lampe ved den ene ende af det lange bord.`,`På et stykke grønt klæde ligger et gulnet brev med to segl i rød lak: et tårn og et kornneg.`,`En træt borgmester ser op fra en halvskrevet tale og lægger pennen fra sig.`],[`The council hall is dark except for a lamp at one end of the long table.`,`On a piece of green cloth lies a yellowed letter with two seals in red wax: a tower and a sheaf.`,`A tired mayor looks up from a half-written speech and sets the pen down.`]),details:[y(`Tillægget giver byen ret til told af hver vogn med korn ved porten på markedsdage og bærer byens tårn og bøndernes kornneg. Neget på tillægget er skarpt og helt, uden revne. Papiret er gulnet, men lakken er blank som lak, der er få måneder gammel.`,`The addendum gives the town the right to toll every cart of grain at the gate on market days and bears the town’s tower and the farmers’ sheaf. The sheaf on the addendum is sharp and whole, without a crack. The paper is yellowed, but the wax is as glossy as wax only a few months old.`),y(`{npc2} fortæller, at det var {villain}, der fandt tillægget, {villain}, der bad om arkivets eneste nøgle, og {villain}, der selv betaler vagterne ved tårnet. Byen mangler penge til den nye bro, og {npc2} har tvivlet fra første dag, men vil have mere end bøndernes ord.`,`{npc2} says it was {villain} who found the addendum, {villain} who asked for the archive’s only key and {villain} who pays the guards at the tower. The town needs money for the new bridge, and {npc2} has had doubts from the first day, but wants more than the farmers’ word.`),y(`Bringer heltene det falske segl, de gamle breve med revnen eller gravøren selv, lover {npc2} at standse oplæsningen ved porten. Kommer heltene i løbet af de første to timer, kan {npc2} sende vagten efter {npc3}, før {villain}s folk når frem.`,`If the heroes bring the false seal, the old letters with the crack or the engraver in person, {npc2} promises to stop the reading at the gate. If the heroes come within the first two hours, {npc2} can send the watch for {npc3} before {villain}’s people get there.`)],checks:[x(`Intelligence (Investigation)`,`easy`,y(`Heltene ser, at revnen mangler, og at lakken er for ny til et brev på tredive år. Det er nok til, at {npc2} vil lytte.`,`The heroes see that the crack is missing and that the wax is too new for a letter thirty years old. It is enough to make {npc2} listen.`),y(`Heltene ser kun, at revnen mangler; {npc2} trækker på skuldrene og siger, at et segl kan revne når som helst.`,`The heroes see only that the crack is missing; {npc2} shrugs and says a seal can crack at any time.`)),x(`Charisma (Persuasion)`,`medium`,y(`{npc2} giver heltene et brev med borgmesterens segl, der åbner tårnets dør for dem, men ikke hvælvingen; den nøgle har kun {villain}.`,`{npc2} gives the heroes a letter with the mayor’s seal that opens the tower door to them, but not the vault; only {villain} has that key.`),y(`{npc2} vil ikke blande sig før middag. Heltene må selv finde en vej ind i {place}, og vagterne ved døren adlyder kun {villain}.`,`{npc2} will not get involved before noon. The heroes must find their own way into {place}, and the guards at the door obey only {villain}.`))],fight:!1,alternatives:[y(`Bed {npc2} om at kalde {villain} til rådhuset nu: {villain} kommer, smiler og forklarer alt, men ved fra nu af, at heltene er på sporet.`,`Ask {npc2} to summon {villain} to the town hall now: {villain} comes, smiles and explains everything, but from now on knows the heroes are on the trail.`),y(`Tag en tegning af tillæggets segl med: Den kan lægges ved siden af det falske segl, når heltene finder det.`,`Take a drawing of the addendum’s seal along: it can be laid beside the false seal once the heroes find it.`)],dmNotes:y(`Borgmesteren er ingen skurk, bare en, der mangler penge og et godt bevis. Lad {npc2} være den, der til sidst skal overbevises ved porten.`,`The mayor is no villain, just someone short of money and good proof. Let {npc2} be the one who must be convinced at the gate in the end.`)},{kind:`social`,at:`town`,present:[`npc3`],title:y(`Gravørens værksted`,`The Engraver’s Workshop`),summary:y([`{npc3}, den eneste gravør i {town}, der skærer i sølv, bor over sit værksted i en smal gade ved floden.`,`I foråret skar {npc3} et segl i sølv for {villain} efter et gammelt voksaftryk af et kornneg og fik besked på at udelade en hårfin streg; nu er {npc3} bange.`,`Efter 2 timer kommer {villain}s folk efter {npc3}, og så er værkstedet tomt bortset fra en seddel under arbejdsbordet.`],[`{npc3}, the only engraver in {town} who cuts silver, lives above their workshop in a narrow street by the river.`,`In the spring {npc3} cut a seal in silver for {villain} from an old wax impression of a sheaf and was told to leave out a fine line; now {npc3} is afraid.`,`After 2 hours {villain}’s people come for {npc3}, and then the workshop is empty except for a note under the bench.`]),readAloud:y([`Værkstedet lugter af olie og metalspåner, og på arbejdsbordet ligger små stempler, file og en lup på et stativ.`,`Lampen brænder stadig, og i døren til baglokalet står en gravør med sværte på fingrene og en fil i hånden, som var den et våben.`,`Under bordet stikker hjørnet af en seddel frem mellem spånerne.`],[`The workshop smells of oil and metal filings, and on the bench lie small punches, files and a lens on a stand.`,`The lamp is still burning, and in the doorway to the back room stands an engraver with blackened fingers and a file held like a weapon.`,`Under the bench the corner of a note sticks out among the filings.`]),details:[y(`{npc3} skar seglet efter et gammelt voksaftryk, som {villain} kom med, og fik besked på at gøre det "rent", uden stregen tværs over neget. {npc3} gemte et ekstra aftryk af det nye segl i voks, fordi betalingen var for stor til at være ærlig, og giver det til den, der kan love beskyttelse.`,`{npc3} cut the seal from an old wax impression {villain} brought and was told to make it "clean", without the line across the sheaf. {npc3} kept an extra wax impression of the new seal because the payment was too large to be honest, and will give it to anyone who can promise protection.`),y(`Under arbejdsbordet ligger {villain}s bestilling: en nøjagtig kopi i sølv, uden stregen, og seglet skal ligge "blandt sine brødre i arkivets skab". Sedlen bliver liggende, også hvis {npc3} er væk.`,`Under the bench lies {villain}’s order: an exact copy in silver, without the line, and the seal is to lie "among its brothers in the archive’s cabinet". The note stays there even if {npc3} is gone.`),y(`Efter 2 timer kommer {boss} og nogle {foe} efter {npc3} og låser gravøren inde i {place}. Er heltene her, når de kommer, trækker de sig og melder det til {villain}, der fordobler vagten ved tårnet. Kommer heltene senere, står døren åben, lampen brænder, og værktøjet ligger spredt over gulvet.`,`After 2 hours {boss} and some {foe} come for {npc3} and lock the engraver up in {place}. If the heroes are here when they arrive, {boss} and the others withdraw and report to {villain}, who doubles the guard at the tower. If the heroes come later, the door stands open, the lamp is burning and the tools lie scattered across the floor.`)],checks:[x(`Charisma (Persuasion)`,`medium`,y(`{npc3} lover at vidne for borgmesteren, hvis heltene holder {villain}s folk væk, og giver dem det ekstra aftryk i voks.`,`{npc3} promises to testify before the mayor if the heroes keep {villain}’s people away, and gives them the extra wax impression.`),y(`{npc3} nægter at sige noget, men kigger ned på sedlen under bordet, så heltene ved, hvor de skal lede.`,`{npc3} refuses to say a word but glances down at the note under the bench, so the heroes know where to look.`)),x(`Intelligence (Investigation)`,`easy`,y(`Heltene finder sedlen mellem spånerne og ved nu, at det falske segl ligger i arkivets skab i {place}.`,`The heroes find the note among the filings and now know that the false seal lies in the archive’s cabinet at {place}.`),y(`Heltene finder sedlen, men først efter at have vendt hele værkstedet; det koster en halv time.`,`The heroes find the note, but only after turning the whole workshop over; it costs half an hour.`))],fight:!1,alternatives:[y(`Tag {npc3} med til rådhuset med det samme: Med gravøren i sikkerhed hos borgmesteren kan {villain}s folk ikke nå vidnet.`,`Take {npc3} to the town hall at once: with the engraver safe with the mayor, {villain}’s people cannot reach the witness.`),y(`Gem jer i værkstedet, og lad {villain}s folk tage {npc3}: Følg efter dem, og de fører heltene lige til tårnets bagdør, men så sidder gravøren inde i {place}.`,`Hide in the workshop and let {villain}’s people take {npc3}: follow them, and they lead the heroes straight to the tower’s back door, but then the engraver is shut up in {place}.`)],dmNotes:y(`Gravøren er det vidne, der kan nævne {villain}s navn. Lad spillerne mærke uret: Kommer de for sent, fortæller den tomme stue og den brændende lampe resten.`,`The engraver is the witness who can name {villain}. Let the players feel the clock: if they come too late, the empty room and the burning lamp tell the rest.`)},{kind:`exploration`,at:`site`,present:[],title:y(`Læsestuen i tårnet`,`The Reading Room in the Tower`),summary:y([`{place} er et gammelt tårn ved floden, hvor byens arkiv fylder tre etager, og hvor {villain}s vagter holder døren.`,`Oppe i læsestuen ligger arkivets protokol med en linje, der er skrabet ud og skrevet om, og fortegnelsen over seglskabet med en ny linje ud for skuffe 7.`,`Herfra går trappen ned til hvælvingen, hvor seglskabet står.`],[`{place} is an old tower by the river where the town archive fills three floors and {villain}’s guards hold the door.`,`Up in the reading room lie the archive’s register, with a line scraped away and rewritten, and the catalogue of the seal cabinet, with a new entry for drawer 7.`,`From here the stair goes down to the vault where the seal cabinet stands.`]),readAloud:y([`Tårnets trapper knirker, og overalt står reoler med bundter af breve, bundet med snor og mærket med årstal.`,`I læsestuen står en pult med en stor protokol, og på gulvet foran trappen ned til hvælvingen glinser små, røde dryp.`,`Nedefra lyder stemmer og en gang imellem en latter, der giver genlyd i hvælvingen.`],[`The tower stairs creak, and everywhere stand shelves of bundled letters tied with string and marked with years.`,`In the reading room stands a lectern with a great register, and on the floor before the stair down to the vault small red drops glisten.`,`From below come voices and now and then a laugh that echoes in the vault.`]),details:[y(`Vagterne er {foe}, som {villain} har hyret til at holde bønderne væk fra arkivet; de holder tårnets dør og trappen ned til hvælvingen, men går aldrig op i læsestuen. Med {npc2}s brev kommer heltene ind ad døren; ellers må de ind ad bagdøren ved floden eller gennem et vindue på anden etage.`,`The guards are {foe} that {villain} has hired to keep the farmers away from the archive; they hold the tower door and the stair down to the vault but never go up to the reading room. With {npc2}’s letter the heroes get in through the door; otherwise they must use the back door by the river or a window on the second floor.`),y(`I protokollen er linjen for tillægget skrabet ud og skrevet om med friskere blæk i {villain}s pæne håndskrift; under den kan man stadig skimte "regnskab for broen". I fortegnelsen over seglskabet står der ud for skuffe 7: "bondelaugets gamle segl, aflagt, sølv", men bønderne har aldrig lagt et segl fra sig.`,`In the register the line for the addendum has been scraped away and rewritten in fresher ink in {villain}’s neat hand; beneath it "accounts for the bridge" can still be made out. In the catalogue of the seal cabinet, the entry for drawer 7 reads: "the farmers’ guild’s old seal, retired, silver", but the farmers have never laid a seal aside.`),y(`På reolerne står bundterne med bøndernes breve år for år, men bundtet fra årene efter flodåret mangler: {villain} har båret det ned i hvælvingen. Efter daggry stiger der røg op fra hvælvingen, og trappen ned er spærret af vagter.`,`On the shelves the bundles of the farmers’ letters stand year by year, but the bundle from the years after the flood year is missing: {villain} has carried it down into the vault. After dawn smoke rises from the vault, and the stair down is blocked by guards.`)],checks:[x(`Dexterity (Stealth)`,`medium`,y(`Heltene kommer op i læsestuen, uden at vagterne ved døren hører dem, og kan læse protokollen i ro.`,`The heroes reach the reading room without the guards at the door hearing them and can read the register in peace.`),y(`En trappe knirker, og en vagt kommer op for at se efter; heltene må gemme sig bag en reol eller snakke sig ud af det, og vagten bliver mistænksom.`,`A step creaks and a guard comes up to look; the heroes must hide behind a shelf or talk their way out, and the guard grows suspicious.`)),x(`Intelligence (Investigation)`,`medium`,y(`Heltene finder både den skrabede linje i protokollen og skuffe 7 i fortegnelsen og ved nu præcis, hvor i seglskabet det falske segl ligger.`,`The heroes find both the scraped line in the register and the entry for drawer 7 in the catalogue, and now know exactly where in the seal cabinet the false seal lies.`),y(`Heltene finder kun protokollen; skuffe 7 må de lede efter i hvælvingen, og det tager tid, mens vagterne er der.`,`The heroes find only the register; they must search for drawer 7 in the vault, and that takes time with the guards there.`))],fight:!1,alternatives:[y(`Tag protokollen med: Den er tung, men den viser, at tillægget aldrig kom ind i arkivet ad lovlig vej.`,`Take the register along: it is heavy, but it shows that the addendum never entered the archive by lawful means.`),y(`Vent i læsestuen til daggry, og se {villain} gå ned med kurven med trækul: Så ved heltene, at {villain} er dernede, og hvor mange vagter der følger med.`,`Wait in the reading room until dawn and watch {villain} go down with the basket of charcoal: then the heroes know {villain} is down there and how many guards go along.`)],dmNotes:y(`Læsestuen er stilheden før konfrontationen. Lad spillerne lægge brikkerne sammen her: tillægget, revnen, protokollen og skuffe 7.`,`The reading room is the quiet before the confrontation. Let the players put the pieces together here: the addendum, the crack, the register and drawer 7.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:y(`Seglskabet i hvælvingen`,`The Seal Cabinet in the Vault`),summary:y([`I hvælvingen under {place} står seglskabet med hundrede små skuffer, og fra daggry står {villain} her selv ved et fyrfad, smelter det falske segl i en digel og fodrer ilden med bøndernes gamle breve.`,`{boss} og nogle {foe}, som {villain} har hyret, holder trappen og døren; har {villain}s folk hentet {npc3}, sidder gravøren låst inde i et sidekammer.`,`Heltene skal have seglet ud af ilden, redde brevene og nå porten før middag.`],[`In the vault beneath {place} stands the seal cabinet with a hundred small drawers, and from dawn {villain} is here in person at a brazier, melting the false seal in a crucible and feeding the farmers’ old letters to the fire.`,`{boss} and some {foe} hired by {villain} hold the stair and the door; if {villain}’s people fetched {npc3}, the engraver sits locked in a side chamber.`,`The heroes must get the seal out of the fire, save the letters and reach the gate before noon.`]),readAloud:y([`Hvælvingen er lav og varm, og røgen hænger under loftet.`,`Langs væggen står et højt skab med hundrede små skuffer, og en af dem står åben.`,`Midt på gulvet gløder et fyrfad, og over det bøjer en skikkelse i en fin, sort rådskappe sig over en lille digel og lægger et gulnet brev på kullene.`],[`The vault is low and warm, and smoke hangs under the ceiling.`,`Along the wall stands a tall cabinet with a hundred small drawers, and one of them stands open.`,`In the middle of the floor a brazier glows, and beside it a figure in a fine black council robe bends over a small crucible and lays a yellowed letter on the coals.`]),details:[y(`{boss} og nogle {foe} er hyret af {villain} og vogter trappen og døren til hvælvingen. De kæmper for deres løn, men ikke for et falsk segl, og overgiver sig eller flygter, når {boss} falder. {villain} kæmper ikke, holder sig ved fyrfadet og prøver at få seglet til at smelte, før heltene når frem.`,`{boss} and some {foe}, hired by {villain}, guard the stair and the door of the vault. They fight for their pay, but not for a false seal, and surrender or flee when {boss} falls. {villain} does not fight, stays by the brazier and tries to get the seal to melt before the heroes reach it.`),y(`Seglet skal ligge en time i kullene, før det smelter. Kommer heltene før daggry, ligger det stadig i skuffe 7, og {villain} går lige ind i dem med sin kurv. Kommer de inden for den første time efter daggry, er det blødt, men helt; senere er det en klump sølv med halvdelen af neget. Bundtet med de gamle breve brænder langsomt, ét brev ad gangen, og hvert brev, der bliver reddet, viser revnen.`,`The seal must lie in the coals for an hour before it melts. If the heroes come before dawn, it still lies in drawer 7, and {villain} walks straight into them with the basket. If they come within the first hour after dawn, it is soft but whole; later it is a lump of silver bearing half the sheaf. The bundle of old letters burns slowly, one letter at a time, and every letter saved shows the crack.`),y(`Har {villain}s folk hentet {npc3}, sidder gravøren låst inde i et sidekammer og kan vidne, hvis heltene får døren op. Når kampen vender, tilbyder {villain} at erklære tillægget for "tvivlsomt" mod selv at slippe for retten, og ellers prøver {villain} at nå porten først med sin egen udgave af sagen.`,`If {villain}’s people fetched {npc3}, the engraver sits locked in a side chamber and can testify if the heroes get the door open. When the fight turns, {villain} offers to declare the addendum "doubtful" in exchange for being spared a trial, and otherwise tries to reach the gate first with another version of events.`)],checks:[x(`Dexterity (Sleight of Hand)`,`medium`,y(`En helt får diglen ud af kullene med en tang, før seglet smelter, og neget står stadig skarpt og helt, uden revne.`,`A hero gets the crucible out of the coals with tongs before the seal melts, and the sheaf still stands sharp and whole, without a crack.`),y(`Diglen vælter, og seglet falder i kullene; heltene får det ud, men kanten er smeltet, og kun halvdelen af neget kan sammenlignes.`,`The crucible tips and the seal drops into the coals; the heroes get it out, but the edge has melted, and only half the sheaf can be compared.`)),x(`Charisma (Intimidation)`,`medium`,y(`Med protokollen, sedlen fra gravøren og seglet foran sig giver {villain} op, kalder vagterne tilbage og beder om at blive ført til borgmesteren i stedet for til bønderne.`,`Faced with the register, the engraver’s note and the seal, {villain} gives up, calls the guards off and begs to be taken to the mayor rather than to the farmers.`),y(`{villain} kaster resten af brevene i ilden og løber op ad trappen mod porten, mens {boss} spærrer vejen for heltene.`,`{villain} throws the rest of the letters into the fire and runs up the stair toward the gate while {boss} blocks the heroes’ way.`))],fight:!0,alternatives:[y(`Hent {npc2} til tårnet: Med borgmesteren som vidne tør vagterne ikke løfte et våben, og {villain} må forklare fyrfadet.`,`Bring {npc2} to the tower: with the mayor as witness the guards dare not raise a weapon, and {villain} must explain the brazier.`),y(`Kom før daggry, tag seglet i skuffe 7, og vent i mørket: Når {villain} kommer ned med kurven, ligger beviset allerede i heltenes hænder.`,`Come before dawn, take the seal from drawer 7 and wait in the dark: when {villain} comes down with the basket, the proof is already in the heroes’ hands.`)],dmNotes:y(`Konfrontationen sker her og ikke i en tale ved porten. Lad {villain} forklare og forklare, til beviserne ligger på bordet. Sig, hvor mange timer der er til middag, når kampen er slut: Porten venter stadig.`,`The confrontation happens here, not in a speech at the gate. Let {villain} explain and explain until the proof lies on the table. When the fight is over, tell the players how many hours are left until noon: the gate is still waiting.`)}},Ne=e({kernel:()=>Le,scenes:()=>Re}),Pe=e=>Array.isArray(e)?e.join(` `):e,S=(e,t)=>({da:Pe(e),en:Pe(t)}),Fe=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),C=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},Ie=(e,t,n)=>({when:e,event:t,sign:n}),w=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),Le={id:`hunt-the-poisoned-spring`,titles:[S(`Den forgiftede kilde`,`The Poisoned Spring`),S(`Bittert vand fra {place}`,`Bitter Water from {place}`),S(`Grevens grønne klæde`,`The Count’s Green Cloth`)],missions:[`monster-hunt`],foes:`beasts`,roles:{npc1:S(`en brøndvogter, der har passet {town}s brønd i tredive år`,`a well-keeper who has tended the well of {town} for thirty years`),npc2:S(`en kusk, der har kørt tønder op i {place} om natten for {villain}`,`a carter who has hauled barrels up into {place} by night for {villain}`),npc3:S(`en kulsvier, som {boss} sårede i {place} for en uge siden`,`a charcoal burner whom {boss} wounded in {place} a week ago`),villain:S(`en farvermester, der har fået sit livs største ordre på grønt klæde`,`a master dyer who has landed the biggest order of a lifetime for green cloth`)},hook:S(`{npc1} trækker en spand op af {town}s brønd foran heltene, lader dem smage det bitre vand og beder dem gå ind i {place}, standse {boss}, før flere bliver såret i skoven, og finde ud af, hvad der er galt med kilden, før brønden er ødelagt.`,`{npc1} draws a bucket from the well of {town} in front of the heroes, lets them taste the bitter water and asks them to go into {place}, stop {boss} before anyone else is hurt in the woods, and find out what is wrong with the spring before the well is ruined.`),people:{npc1:{wants:S(`Vil redde brønden, som {npc1}s slægt har passet i fire led, og vil ikke lukke den, før der er rent vand et andet sted.`,`Wants to save the well that {npc1}’s family has tended for four generations, and will not close it until there is clean water somewhere else.`),secret:S(`Har smagt bitterheden i over en uge og tiet, fordi {villain} bad om, at der ikke blev skabt panik i byen, før {boss} var død.`,`Has tasted the bitterness for over a week and kept quiet, because {villain} asked that no panic be stirred up in town until {boss} was dead.`)},npc2:{wants:S(`Vil have sin sidste løn og komme langt væk fra {place}, før nogen spørger, hvad der var i tønderne.`,`Wants the last of their wages and to get far away from {place} before anyone asks what was in the barrels.`),secret:S(`Ved godt, at tønderne lækker grønt, og har set fiskene flyde døde i bækken under kilden, men kørte videre for dobbelt løn.`,`Knows the barrels leak green, and has seen dead fish floating in the brook below the spring, but kept driving for double pay.`)},npc3:{wants:S(`Vil have {boss} dræbt og kunne passe sine miler igen uden at frygte skoven.`,`Wants {boss} dead and to tend the kilns again without fearing the woods.`),secret:S(`Var på krybskytteri ved slugten over kilden, da {boss} angreb om natten, og har fortalt alle, at det skete ved milerne.`,`Was poaching at the swallow hole above the spring when {boss} attacked in the night, and has told everyone it happened at the kilns.`)}},premise:S([`Kilden i {place} har i århundreder givet vand til {town}s brønd gennem en åre i klippen, og i grotten ved kilden har {boss} og nogle {foe} levet i årevis uden at genere nogen.`,`I sommer fik {villain}, byens farvermester, sit livs største ordre: tre hundrede alen grønt klæde til grevens garde, farvet med et bittert grønt salt, der er giftigt. Rådet har forbudt farveriet at tømme sine kar i elven, så i stedet har {villain} ladet {npc2} køre tønderne med det brugte farvebad op ad den gamle kulvej og tømme dem i slugten over kilden, hvor alt forsvinder ned i jorden.`,`Giften er sivet ned i kildegrotten: {boss} og de andre er blevet gale af smerte og har angrebet kulsviere og hyrder i skoven, og nu er vandet i {town}s brønd begyndt at smage bittert.`,`I nat, før laugets synsmænd kommer til farveriet, kører {villain} selv det store bundkar op i tolv tønder og tømmer det i slugten; når så meget gift når brønden, er den ødelagt i årevis.`],[`For centuries the spring in {place} has fed the well of {town} through a vein in the rock, and in the cave beside the spring {boss} and some {foe} have lived for years without troubling anyone.`,`This summer {villain}, the town’s master dyer, landed the biggest order of a lifetime: three hundred ells of green cloth for the count’s guard, dyed with a bitter, poisonous green salt. The council has forbidden the dye works to empty its vats into the river, so instead {villain} has had {npc2} haul the barrels of spent dye bath up the old charcoal track and pour them into the swallow hole above the spring, where everything vanishes into the ground.`,`The poison has seeped down into the spring cave: {boss} and the others have been driven mad with pain and have attacked charcoal burners and herders in the woods, and now the water in the well of {town} has begun to taste bitter.`,`Tonight, before the guild’s inspectors come to the dye works, {villain} personally drives the contents of the great settling vat up in twelve barrels and pours them into the swallow hole; when that much poison reaches the well, it is ruined for years.`]),goal:S(`Find ud af, hvad der forgifter kilden, og stands både {boss} og {villain} ved slugten over kilden i {place}, før det sidste læs bliver tømt ved midnat.`,`Find out what is poisoning the spring, and stop both {boss} and {villain} at the swallow hole above the spring in {place} before the last load is poured at midnight.`),objective:{target:S(`Slugten over kilden, hvor {villain}s tønder bliver tømt, og {boss}, som giften har drevet til raseri`,`The swallow hole above the spring, where {villain}’s barrels are poured, and {boss}, whom the poison has driven to fury`),state:S(`Fra slugten siver giften ned i kildegrotten, hvor {boss} og nogle {foe} har deres hule, og gale af smerte angriber de alt, der kommer nær. I nat kører {villain} selv det sidste og største læs derop: tolv tønder fra farveriets bundkar.`,`From the swallow hole the poison seeps down into the spring cave where {boss} and some {foe} have their lair, and, mad with pain, they attack anything that comes near. Tonight {villain} drives the last and largest load up there in person: twelve barrels from the dye works’ settling vat.`),resolution:S([`Stands læsset, før det bliver tømt i slugten, og stands {boss}, før {boss} og de andre bryder ned mod {town}; bring {villain} til {town} med tønderne som bevis.`,`Holder giften op, er kilden klar igen inden foråret; om {boss} skal dø eller have lov at komme sig i grotten, er heltenes valg.`],[`Stop the load before it is poured into the swallow hole, and stop {boss} before {boss} and the others break out toward {town}; bring {villain} to {town} with the barrels as proof.`,`Once the poison stops, the spring runs clear again before winter is out; whether {boss} must die or be left to recover in the cave is the heroes’ choice.`])},villain:{want:S(`At levere grevens grønne klæde til tiden, beholde farveriets gode navn og slippe for at betale det, det koster at koge farvebadet ind og grave det ned, som rådet kræver.`,`To deliver the count’s green cloth on time, keep the dye works’ good name and avoid paying what it costs to boil down the dye bath and bury it, as the council demands.`),plan:S([`Hele sommeren har {villain} ladet {npc2} køre tønderne med det brugte farvebad op ad den gamle kulvej forbi milerne og tømme dem i slugten over kilden i {place}.`,`Da {boss} angreb vognen ved slugten i sidste uge, nægtede {npc2} at køre mere, og {villain} begyndte at fortælle alle i {town}, at det er {boss}s skidt i kilden, der gør vandet bittert.`,`I nat, før laugets synsmænd kommer til farveriet i morgen tidlig, kører {villain} selv det store bundkar op i tolv tønder og tømmer dem i slugten, én efter én, til den sidste er tom ved midnat.`],[`All summer {villain} has had {npc2} haul the barrels of spent dye bath up the old charcoal track past the kilns and pour them into the swallow hole above the spring in {place}.`,`When {boss} attacked the wagon at the swallow hole last week, {npc2} refused to drive any more, and {villain} began telling everyone in {town} that it is {boss}’s filth in the spring that makes the water bitter.`,`Tonight, before the guild’s inspectors come to the dye works in the morning, {villain} personally drives the contents of the great settling vat up in twelve barrels and pours them into the swallow hole one by one, until the last is empty at midnight.`]),weakness:S([`{villain} er rædselsslagen for {boss} og kender ikke vejen i mørke; uden kusken må {villain} selv køre vognen op med to svende og lygter, der kan ses langt væk.`,`Og tønderne bærer farveriets brændemærke: Bliver ét eneste læs fanget ved slugten, kan {villain} ikke længere skyde skylden på {boss}.`],[`{villain} is terrified of {boss} and does not know the way in the dark; without the carter, {villain} must drive the wagon up in person with two journeymen and lanterns that can be seen from far away.`,`And the barrels bear the dye works’ brand: if a single load is caught at the swallow hole, {villain} can no longer lay the blame on {boss}.`])},stakes:S(`Bliver bundkarret tømt i slugten, når giften {town}s brønd inden daggry, og brønden er ødelagt i årevis; {boss} og nogle {foe} bryder rasende ned mod byen, og {villain} leverer grevens klæde til tiden, mens hele {town} giver {boss} skylden.`,`If the settling vat is emptied into the swallow hole, the poison reaches the well of {town} before dawn and the well is ruined for years; {boss} and some {foe} break out toward the town in a rage, and {villain} delivers the count’s cloth on time while all of {town} blames {boss}.`),clock:{start:S(`Middag. Vandet i {town}s brønd smager bittert, og {npc1} siger, at brønden ikke tåler meget mere. Laugets synsmænd kommer til farveriet i morgen tidlig, og inden da skal {villain}s store bundkar være tomt; der er tolv timer til midnat.`,`Noon. The water in the well of {town} tastes bitter, and {npc1} says the well cannot take much more. The guild’s inspectors come to the dye works early tomorrow, and before then {villain}’s great settling vat must be empty; there are twelve hours until midnight.`),ticks:[Ie(S(`Efter 3 timer`,`After 3 hours`),S(`{villain} lukker farveriet "for rengøring", og svendene begynder at tappe bundkarret over i tolv tønder i gården bag muren.`,`{villain} closes the dye works "for cleaning", and the journeymen begin drawing off the settling vat into twelve barrels in the yard behind the wall.`),S(`Porten til farveriet er lukket midt på dagen, og en bitter lugt af eddike og metal driver ud over gaden.`,`The gate of the dye works is shut in the middle of the day, and a bitter smell of vinegar and metal drifts out over the street.`)),Ie(S(`Efter 7 timer (ved solnedgang)`,`After 7 hours (at sunset)`),S(`{villain} kører ud af farveriet med vognen og de tolv tønder, giften fra de sidste nætter når helt ned i brønden, og nogle {foe}, gale af smerte, strejfer ned langs bækken fra kilden.`,`{villain} drives out of the dye works with the wagon and the twelve barrels, the poison from the last few nights reaches all the way down into the well, and some {foe}, mad with pain, roam down along the brook from the spring.`),S(`En tungt lastet vogn ruller ud mod {place} uden lygter, spanden kommer uklar og stinkende op af brønden, og fra skovbrynet lyder skrig og knækkende grene.`,`A heavily loaded wagon rolls out toward {place} without lanterns, the bucket comes up cloudy and foul from the well, and from the forest edge come screams and the crack of breaking branches.`)),Ie(S(`Efter 12 timer (ved midnat)`,`After 12 hours (at midnight)`),S(`Den sidste af de tolv tønder er tømt i slugten, og {boss} og nogle {foe} bryder rasende op fra kildegrotten; giften når brønden inden daggry.`,`The last of the twelve barrels has been poured into the swallow hole, and {boss} and some {foe} burst up from the spring cave in a rage; the poison reaches the well before dawn.`),S(`Lygter blinker på skrænten over kilden, og så lyder skrig og et brag af splintret træ ud over hele skoven.`,`Lanterns flicker on the slope above the spring, and then screams and a crash of splintering wood ring out over the whole forest.`))],deadline:S(`Efter 12 timer, ved midnat, er det for sent: Bundkarret er tømt i slugten, {town}s brønd er ødelagt i årevis, og {boss} og nogle {foe}, gale af giften, bryder ned mod byen.`,`After 12 hours, at midnight, it is too late: the settling vat has been emptied into the swallow hole, the well of {town} is ruined for years, and {boss} and some {foe}, maddened by the poison, break out toward the town.`)},clues:{who:[C(`town`,S(`På porten til farveriet ved elven hænger rådets påbud fra sidste år, men gruberne bag farveriet, hvor farvebadet skulle graves ned, er groet til med nælder.`,`On the gate of the dye works by the river hangs the council’s order from last year, yet the pits behind the works, where the dye bath was to be buried, are overgrown with nettles.`),S(`Farveriet har farvet grønt hele sommeren uden at grave noget ned; {villain}s brugte farvebad er kørt et andet sted hen.`,`The dye works has dyed green all summer without burying anything; {villain}’s spent dye bath has been taken somewhere else.`),Fe([`Rådet i {town} til farvermester {villain}:`,`Efter at fiskene døde i elven, forbydes det farveriet at tømme sine kar i elven.`,`Brugt farvebad skal koges ind og graves ned i forseglede kar på farveriets egen grund, til synsmændene har set det.`,`Overtrædelse straffes med lukning. – Rådet`],[`The council of {town} to master dyer {villain}:`,`Since the fish died in the river, the dye works is forbidden to empty its vats into the river.`,`Spent dye bath shall be boiled down and buried in sealed vessels on the works’ own ground, once the inspectors have seen it.`,`Breach of this order is punished by closure. — The Council`])),C(`town`,S(`Den spand, {npc1} trækker op af brønden, efterlader en tynd grøn ring på træet, præcis samme grønne farve som klædet på farveriets tørrestativer, og det bitre vand lugter af eddike og metal.`,`The bucket {npc1} draws from the well leaves a thin green ring on the wood, exactly the same green as the cloth on the dye works’ drying racks, and the bitter water smells of vinegar and metal.`),S(`Det, der forgifter brønden, kommer fra farveriet, ikke fra {boss}.`,`Whatever is poisoning the well comes from the dye works, not from {boss}.`)),C(`site`,S(`{npc3}, kulsvieren ved milerne, indrømmer at have været på krybskytteri ved slugten den nat, {boss} angreb, og at have set en vogn med farveriets mærke tømme tønde efter tønde ned i slugten, lige før {boss} kom rasende op af jorden.`,`{npc3}, the charcoal burner at the kilns, admits to poaching at the swallow hole the night {boss} attacked, and to seeing barrel after barrel poured into the hole from a wagon bearing the dye works’ mark, just before {boss} came raging up out of the ground.`),S(`{villain}s folk tømmer farveriets affald i slugten over kilden, og det er det, der har drevet {boss} op.`,`{villain}’s people are pouring the dye works’ waste into the swallow hole above the spring, and that is what drove {boss} to the surface.`)),C(`site`,S(`I bækken fra kilden ligger stave og bånd fra knuste tønder, og på en af stavene ses farveriets brændemærke: en krog med tre garnfed.`,`In the brook from the spring lie staves and hoops from smashed barrels, and on one stave the dye works’ brand can be seen: a hook with three skeins of yarn.`),S(`Tønderne, der forgifter kilden, kommer fra {villain}s farveri.`,`The barrels poisoning the spring come from {villain}’s dye works.`))],where:[C(`town`,S(`{npc2}, farveriets kusk, fortæller, at hvert læs gik op ad den gamle kulvej forbi milerne til slugten over kilden, og at {boss} kom op af jorden dernede i sidste uge.`,`{npc2}, the dye works’ carter, says that every load went up the old charcoal track past the kilns to the swallow hole above the spring, and that {boss} came up out of the ground there last week.`),S(`Tønderne bliver tømt i slugten over kilden, og det er lige dér, {boss} holder til.`,`The barrels are poured into the swallow hole above the spring, and that is exactly where {boss} lairs.`)),C(`town`,S(`På døren til karrummet i farveriet sidder en seddel med {villain}s ordrer til svendene.`,`On the door of the vat room in the dye works is a note with {villain}’s orders to the journeymen.`),S(`{villain} kører selv det sidste og største læs op til slugten over kilden i nat og tømmer det inden midnat.`,`{villain} is personally driving the last and largest load up to the swallow hole above the spring tonight and pouring it in before midnight.`),Fe([`I dag: Bundkarret tappes på tolv tønder. Ingen udenforstående i gården.`,`Vognen klar ved solnedgang. Ingen lygter før kulvejen. Jeg kører selv, siden kusken er for fin til det.`,`Alt skal være i slugten før midnat, og karret skal være skuret, før synsmændene kommer. – {villain}`],[`Today: draw off the settling vat into twelve barrels. No outsiders in the yard.`,`Wagon ready at sunset. No lanterns before the charcoal track. I will drive myself, since the carter is too good for it.`,`Everything in the swallow hole before midnight, and the vat scrubbed before the inspectors come. — {villain}`])),C(`site`,S(`Fra milerne i skovbrynet fører den gamle kulvej op mod slugten, og i den står dybe hjulspor efter en tungt lastet vogn; vandet i sporene har et grønt skær, og langs vejen ligger knust lygteglas.`,`From the kilns at the forest edge the old charcoal track leads up toward the swallow hole, and in it lie deep ruts left by a heavily loaded wagon; the water in the ruts has a green sheen, and broken lantern glass lies along the way.`),S(`Farveriets vogn kører op til slugten over kilden, og den kommer igen.`,`The dye works’ wagon drives up to the swallow hole above the spring, and it will come again.`)),C(`site`,S(`Op ad bækken fra kilden bliver den grønne skorpe på stenene tykkere, og ved kildens munding pibler det grønne vand ud af en revne, der fører lige op mod slugten på skrænten ovenover.`,`Up the brook from the spring the green crust on the stones grows thicker, and at the mouth of the spring the green water seeps from a crack that runs straight up toward the swallow hole on the slope above.`),S(`Giften kommer ned gennem slugten over kilden, og grotten nedenunder er {boss}s hule.`,`The poison comes down through the swallow hole above the spring, and the cave beneath it is {boss}’s lair.`))]},endings:{success:S(`Det sidste læs bliver aldrig tømt, og {villain} bliver ført ind i {town} med tønderne og sedlen til svendene som bevis. Rådet lukker farveriet og lader {villain} betale for at rense kilden, {npc1} lukker brønden en måned og åbner den igen for klart vand, og dusøren bliver betalt, uanset hvad heltene valgte at gøre med {boss}.`,`The last load is never poured, and {villain} is brought into {town} with the barrels and the note to the journeymen as proof. The council closes the dye works and makes {villain} pay for cleaning the spring, {npc1} closes the well for a month and reopens it when the water runs clear, and the bounty is paid whatever the heroes chose to do with {boss}.`),partial:S(`Heltene standser {boss} eller læsset, men ikke begge dele i tide: Enten når en del af giften brønden, og {town} må hente vand ved elven hele vinteren, eller også slipper {villain} væk i mørket, og beviserne holder ikke for rådet. Farveriet arbejder videre, og ingen ved, om slugten bliver brugt igen.`,`The heroes stop {boss} or the load, but not both in time: either some of the poison reaches the well and {town} must fetch water from the river all winter, or {villain} slips away in the dark and the proof does not hold up before the council. The dye works carries on, and no one knows whether the swallow hole will be used again.`),failure:S(`Ved midnat er bundkarret tømt i slugten. Inden daggry er {town}s brønd ødelagt, {boss} og nogle {foe} bryder rasende ned mod byen, og {villain} leverer grevens grønne klæde til tiden, mens hele {town} giver {boss} skylden for det døde vand.`,`At midnight the settling vat has been emptied into the swallow hole. Before dawn the well of {town} is ruined, {boss} and some {foe} break out toward the town in a rage, and {villain} delivers the count’s green cloth on time while all of {town} blames {boss} for the dead water.`)}},Re={opening:{kind:`opening`,at:`town`,present:[`npc1`,`villain`],title:S(`Det bitre vand`,`The Bitter Water`),summary:S([`Ved middagstid trækker {npc1}, byens brøndvogter, en spand op af {town}s brønd foran heltene: Vandet smager bittert, og {npc1} beder dem gå ind i {place}, standse {boss}, før flere bliver såret i skoven, og finde ud af, hvad der er galt med kilden, som brønden får sit vand fra.`,`{villain}, byens farvermester, kommer forbi med grønne hænder og et venligt smil og forklarer, at det er {boss}s skidt i kilden, der gør vandet bittert; dræber heltene {boss}, bliver vandet godt igen.`,`Byen kan give flere svar, før heltene går, men hver omvej koster tid, og {npc1} frygter, at brønden ikke tåler en nat mere.`],[`At noon {npc1}, the town’s well-keeper, draws a bucket from the well of {town} in front of the heroes: the water tastes bitter, and {npc1} asks them to go into {place}, stop {boss} before anyone else is hurt in the woods, and find out what is wrong with the spring that feeds the well.`,`{villain}, the town’s master dyer, comes by with green hands and a friendly smile and explains that it is {boss}’s filth in the spring that makes the water bitter; if the heroes kill {boss}, the water will be sweet again.`,`The heroes can find more answers in town before they go, but every detour costs time, and {npc1} fears the well cannot take another night.`]),readAloud:S([`Brønden på torvet har et tag af gamle egeplanker, og rebet knirker, mens spanden kommer op.`,`Vandet i spanden er klart nok, men det lugter svagt af eddike og metal, og hvor det har stået, sidder en tynd grøn ring på træet.`,`Nede ved elven blafrer lange baner af grønt klæde på farveriets tørrestativer, og en velklædt skikkelse med grønne hænder kommer gående op mod brønden.`],[`The well in the square has a roof of old oak planks, and the rope creaks as the bucket comes up.`,`The water in the bucket is clear enough, but it smells faintly of vinegar and metal, and where it has stood a thin green ring clings to the wood.`,`Down by the river, long lengths of green cloth flap on the dye works’ drying racks, and a well-dressed figure with green hands comes walking up toward the well.`]),details:[S(`{npc1} fortæller, at brønden får sit vand fra kilden i {place} gennem en åre i klippen, og at vandet blev bittert samme uge, som {boss} begyndte at angribe kulsviere og hyrder i skoven. Den grønne ring på spanden har samme farve som klædet på farveriets stativer, men {npc1} har ikke tænkt over det, for {villain} har sagt, at det er {boss}s skyld.`,`{npc1} explains that the well gets its water from the spring in {place} through a vein in the rock, and that the water turned bitter the same week {boss} began attacking charcoal burners and herders in the woods. The green ring on the bucket is the same colour as the cloth on the dye works’ racks, but {npc1} has thought nothing of it, because {villain} has said it is {boss}’s fault.`),S(`{villain} er venligheden selv, lover heltene en ekstra belønning, når {boss} er død, og råder dem til at lede i den nordlige del af {place}, langt fra den gamle kulvej. {villain} kigger igen og igen op på solen, og efter tre timer (første tik) lukker {villain} farveriet "for rengøring".`,`{villain} is kindness itself, promises the heroes an extra reward once {boss} is dead, and advises them to search the northern part of {place}, far from the old charcoal track. {villain} keeps glancing up at the sun, and after three hours (the first tick) {villain} closes the dye works "for cleaning".`),S(`{npc3}, kulsvieren, som {boss} sårede for en uge siden, ligger ikke i byen, men passer stadig sin mile i skovbrynet ved kulvejen, fordi kulsvieren ikke har råd til at lade den gå ud. Lukker {npc1} brønden, må hele {town} hente vand i elven, lige nedenfor farveriet.`,`{npc3}, the charcoal burner {boss} wounded a week ago, is not laid up in town but still tending a kiln at the forest edge by the charcoal track, unable to afford to let it go out. If {npc1} closes the well, all of {town} must fetch water from the river, just below the dye works.`)],checks:[w(`Wisdom (Perception)`,`easy`,S(`Heltene ser, at den grønne ring på spanden har præcis samme farve som klædet på farveriets stativer og som {villain}s hænder, der er farvet helt op til håndleddene.`,`The heroes notice that the green ring on the bucket is exactly the colour of the cloth on the dye works’ racks, and of {villain}’s hands, which are stained right up to the wrists.`),S(`Heltene ser kun en spand bittert vand og en hjælpsom farvermester.`,`The heroes see only a bucket of bitter water and a helpful master dyer.`)),w(`Wisdom (Insight)`,`medium`,S(`{villain} er bange, ikke for {boss}, men for tiden: {villain} vil have heltene ud af byen og væk fra kulvejen så hurtigt som muligt.`,`{villain} is afraid, not of {boss} but of running out of time: {villain} wants the heroes out of town and away from the charcoal track as fast as possible.`),S(`{villain} virker som en borger, der vil hjælpe byen, og heltene tænker ikke mere over det.`,`{villain} seems a citizen eager to help the town, and the heroes think no more of it.`))],fight:!1,alternatives:[S(`Gå direkte ind i {place}: Heltene vinder tid, men går efter {boss} i den tro, at det er {boss}s skyld, at vandet er bittert.`,`Head straight into {place}: the heroes gain time, but go after {boss} believing it is {boss}’s fault that the water is bitter.`),S(`Få {npc1} til at lukke brønden med det samme: Ingen drikker mere af den i dag, men rådet raser, og hele byen må gå ned til elven efter vand.`,`Have {npc1} close the well at once: no one drinks from it today, but the council is furious, and the whole town must walk down to the river for water.`)],dmNotes:S(`Spil {villain} som en travl, venlig borger, der gerne hjælper. Lad spanden gå rundt blandt spillerne; det bitre vand er uret i dette eventyr, og hver gang de tøver, kommer den næste spand lidt mere uklar op.`,`Play {villain} as a busy, friendly citizen glad to help. Let the bucket go round the table; the bitter water is the clock of this adventure, and whenever they hesitate, the next bucket comes up a little cloudier.`)},middle:[{kind:`investigation`,at:`town`,present:[`npc2`],title:S(`Farveriet ved elven`,`The Dye Works by the River`),summary:S([`Farveriet ligger ved elven i udkanten af {town}, og bag muren står farvekar, tørrestativer og en stor vogn, som svendene er ved at læsse med tønder.`,`På porten hænger rådets påbud om, at farveriet ikke må tømme sine kar i elven, men gruberne, hvor farvebadet skulle graves ned, er groet til; i gården sidder {npc2}, farveriets kusk, og nægter at køre flere læs op i {place}.`,`Her kan heltene se, hvor giften kommer fra, og få det første sikre ord om slugten over kilden.`],[`The dye works stands by the river at the edge of {town}, and behind its wall are dye vats, drying racks and a big wagon the journeymen are loading with barrels.`,`On the gate hangs the council’s order that the works must not empty its vats into the river, yet the pits where the dye bath was to be buried are overgrown; in the yard sits {npc2}, the works’ carter, refusing to drive any more loads up into {place}.`,`Here the heroes can see where the poison comes from, and get the first sure word of the swallow hole above the spring.`]),readAloud:S([`Bag farveriets mur damper store kar, og luften er skarp af eddike, aske og noget bittert, der sætter sig i halsen.`,`Lange baner af grønt klæde hænger til tørre, og under dem står en tung vogn, halvt læsset med tjærede tønder, hver med et brændemærke på låget.`,`Op ad det ene hjul sidder en kusk med en flaske i hånden og stirrer på vognen, som om den kunne bide.`],[`Behind the dye works’ wall, great vats steam, and the air is sharp with vinegar, ash and something bitter that catches in the throat.`,`Long lengths of green cloth hang drying, and beneath them stands a heavy wagon half loaded with tarred barrels, each with a brand on its lid.`,`Against one wheel sits a carter with a bottle in hand, staring at the wagon as if it might bite.`]),details:[S(`Rådets påbud hænger på porten, men gruberne bag farveriet er groet til med nælder, og ingen har gravet dér i år, selv om farveriet har farvet grønt hele sommeren. Bundkarret, hvor sommerens farvebad samler sig, er fyldt til randen, og ved siden af står tolv tomme tønder; fra første tik (efter tre timer) er porten lukket, og svendene tapper karret over i dem.`,`The council’s order hangs on the gate, but the pits behind the works are overgrown with nettles, and no one has dug there this year, although the works has dyed green all summer. The settling vat, where the summer’s dye bath collects, is full to the brim, and twelve empty barrels stand beside it; from the first tick (after three hours) the gate is shut and the journeymen draw the vat off into them.`),S(`{npc2} har kørt farveriets tønder op ad den gamle kulvej forbi milerne og tømt dem i slugten over kilden hele sommeren, for dobbelt løn og uden spørgsmål. I sidste uge kom {boss} op af jorden ved slugten og angreb vognen, og nu nægter {npc2} at køre mere; kusken ved, at {villain} vil have det sidste og største læs derop i nat og har sagt, at så kører {villain} selv.`,`{npc2} has hauled the works’ barrels up the old charcoal track past the kilns and poured them into the swallow hole above the spring all summer, for double pay and no questions. Last week {boss} came up out of the ground at the swallow hole and attacked the wagon, and now {npc2} refuses to drive any more; the carter knows that {villain} wants the last and largest load up there tonight and means to drive it in person.`),S(`På døren til karrummet sidder {villain}s seddel til svendene med ordrer for natten. I skrivestuen ligger grevens ordre på tre hundrede alen grønt klæde, der skal leveres om fire dage, og et regnskab med en natlig kørsel hver uge hele sommeren, men aldrig et læs brænde til at koge farvebadet ind.`,`On the door of the vat room is {villain}’s note to the journeymen with orders for the night. In the counting room lie the count’s order for three hundred ells of green cloth, due in four days, and an account book showing a night haul every week all summer, but never a load of firewood to boil down the dye bath.`)],checks:[w(`Intelligence (Investigation)`,`medium`,S(`Heltene ser, at gruberne ikke er rørt i år, og at regnskabet har en natlig kørsel hver uge hele sommeren; det brugte farvebad er kørt et andet sted hen.`,`The heroes see that the pits have not been touched this year, and that the accounts show a night haul every week all summer; the spent dye bath has been taken somewhere else.`),S(`Svendene jager heltene ud af karrummet, før de har set regnskabet; de må finde {npc2} for at vide mere, og det koster en halv time.`,`The journeymen chase the heroes out of the vat room before they have seen the accounts; they must find {npc2} to learn more, which costs half an hour.`)),w(`Charisma (Persuasion)`,`easy`,S(`{npc2} fortæller alt om kulvejen, slugten over kilden og {villain}s sidste læs i nat og beder heltene om at sige til rådet, at kusken kun kørte vognen.`,`{npc2} tells everything about the charcoal track, the swallow hole above the spring and {villain}’s last load tonight, and asks the heroes to tell the council that the carter only drove the wagon.`),S(`{npc2} tror, at heltene er sendt af {villain}, og flygter ud ad bagporten; heltene må indhente kusken nede ved elven, og det koster en halv time.`,`{npc2} thinks the heroes were sent by {villain} and flees through the back gate; the heroes must catch the carter down by the river, which costs half an hour.`))],fight:!1,alternatives:[S(`Tag en hjulbolt fra vognen: Vognen kommer først af sted, når {villain} har skaffet en ny, men {villain} ved så, at nogen har gennemskuet planen, og vogter læsset selv.`,`Take a linchpin from the wagon: the wagon cannot leave until {villain} finds another, but {villain} then knows someone has seen through the plan, and guards the load in person.`),S(`Gå til rådet med påbuddet og regnskabet: Rådet kan lukke farveriet, men et rådsmøde tager timer, og {villain} kører alligevel i nat.`,`Take the order and the accounts to the council: the council can close the dye works, but a council meeting takes hours, and {villain} drives out tonight all the same.`)],dmNotes:S(`Farveriet skal føles travlt og dygtigt, ikke ondt: Svendene arbejder hårdt for en ordre, der redder deres løn. Lad spillerne regne det ud selv: tre hundrede alen grønt klæde, men ikke en eneste grube gravet. Hvor er alt det brugte farvebad blevet af?`,`The dye works should feel busy and skilled, not wicked: the journeymen work hard for an order that saves their wages. Let the players work it out themselves: three hundred ells of green cloth, but not a single pit dug. Where has all the spent dye bath gone?`)},{kind:`social`,at:`site`,present:[`npc3`],title:S(`Milerne i skovbrynet`,`The Kilns at the Forest Edge`),summary:S([`Hvor kulvejen går ind i {place}, ryger milerne i skovbrynet, og ved den mindste af dem sidder {npc3}, kulsvieren, som {boss} sårede for en uge siden, med armen i bind.`,`{npc3} har fortalt hele {town}, at {boss} angreb ved milerne, men var i virkeligheden på krybskytteri ved slugten over kilden den nat og så, hvad farveriets vogn tømte dernede.`,`Herfra fører friske hjulspor op ad kulvejen mod slugten, og nede i dalen løber bækken fra kilden grøn.`],[`Where the charcoal track enters {place}, the kilns at the forest edge are smoking, and by the smallest of them sits {npc3}, the charcoal burner {boss} wounded a week ago, with one arm in a sling.`,`{npc3} has told all of {town} that {boss} attacked at the kilns, but in truth was poaching at the swallow hole above the spring that night and saw what was poured down there from the dye works’ wagon.`,`From here fresh wheel ruts lead up the charcoal track toward the swallow hole, and down in the dell the brook from the spring runs green.`]),readAloud:S([`I skovbrynet står tre miler og ryger som små, sorte høje, og luften er tung af røg og harpiks.`,`Ved den mindste mile sidder en sodet skikkelse med den ene arm i et snavset bind og passer ilden med den anden.`,`Bag milerne fører en gammel kulvej op i skoven, og hjulsporene i den er så dybe, at vandet står i dem med et svagt grønt skær.`],[`At the forest edge three kilns smoke like small black mounds, and the air is heavy with smoke and resin.`,`By the smallest kiln sits a soot-blackened figure with one arm in a dirty sling, tending the fire with the other.`,`Behind the kilns an old charcoal track leads up into the woods, its wheel ruts so deep that water stands in them with a faint green sheen.`]),details:[S(`{npc3} vil helst tale om, hvordan {boss} kom op af jorden i mørket, og vil have {boss} dræbt. Men der er ingen kampspor ved milerne, og kulsvierens støvler er grønne af slam op til anklerne. Indrømmer {npc3}, at det skete ved slugten, fortæller kulsvieren, at farveriets vogn kom op ad kulvejen ved midnat, at kusken tømte tønde efter tønde ned i slugten, og at {boss} kom rasende op af jorden lige bagefter, som om noget brændte dernede.`,`{npc3} would rather talk about how {boss} came up out of the ground in the dark, and wants {boss} killed. But there are no signs of a struggle at the kilns, and the charcoal burner’s boots are green with sludge up to the ankles. Once {npc3} admits it happened at the swallow hole, the charcoal burner tells how the dye works’ wagon came up the charcoal track at midnight, how the carter poured barrel after barrel into the hole, and how {boss} came raging up out of the ground right afterwards, as if something were burning down there.`),S(`Kulvejen bag milerne fører op til slugten over kilden, en halv times gang. I hjulsporene står vand med et grønt skær, og langs vejen ligger knust lygteglas og et tøndebånd; vognen har kørt her hver uge hele sommeren.`,`The charcoal track behind the kilns leads up to the swallow hole above the spring, half an hour’s walk. Water with a green sheen stands in the ruts, and broken lantern glass and a barrel hoop lie along the way; the wagon has come this way every week all summer.`),S(`Fra milerne kan heltene se ned i dalen, hvor bækken fra kilden løber: Langs bredden er græsset gult, og ingen fugle synger. Efter syv timer (andet tik) strejfer nogle {foe}, gale af smerte, ned langs bækken mod milerne, og {npc3} beder heltene om ikke at lade kulsvieren være alene.`,`From the kilns the heroes can look down into the dell where the brook from the spring runs: the grass along the bank is yellow, and no birds sing. After seven hours (the second tick) some {foe}, mad with pain, roam down along the brook toward the kilns, and {npc3} begs the heroes to stay.`)],checks:[w(`Wisdom (Insight)`,`medium`,S(`Heltene ser, at {npc3} lyver om stedet, ikke om {boss}; et roligt ord og et løfte om at tie om krybskytteriet får kulsvieren til at fortælle om vognen og tønderne ved slugten.`,`The heroes see that {npc3} is lying about the place, not about {boss}; a calm word and a promise to keep quiet about the poaching get the charcoal burner to tell of the wagon and the barrels at the swallow hole.`),S(`{npc3} holder fast i historien om milerne; heltene får kun at vide, at {boss} kom op af jorden i mørket, og at kulvejen fører op mod slugten.`,`{npc3} sticks to the story of the kilns; the heroes learn only that {boss} came up out of the ground in the dark, and that the charcoal track leads up toward the swallow hole.`)),w(`Wisdom (Medicine)`,`easy`,S(`Heltene renser {npc3}s sår og ser, at bindet er stift af grønt slam, det samme som i hjulsporene; kulsvieren må have ligget i slammet ved slugten, ikke ved milerne.`,`The heroes clean {npc3}’s wound and see that the sling is stiff with green sludge, the same as in the ruts; the charcoal burner must have lain in the sludge at the swallow hole, not at the kilns.`),S(`Såret er betændt, og {npc3} har feber; det koster en halv time at få kulsvieren lagt til rette i læ ved milen.`,`The wound is festering and {npc3} has a fever; it costs half an hour to settle the charcoal burner in shelter by the kiln.`))],fight:!1,alternatives:[S(`Følg kulvejen direkte op til slugten: Det er den korteste vej, men heltene kommer frem uden at have set, hvor giften løber hen, eller hvor {boss} holder til.`,`Follow the charcoal track straight up to the swallow hole: it is the shortest way, but the heroes arrive without having seen where the poison goes or where {boss} lairs.`),S(`Send {npc3} til {town} med bud til {npc1}: Kulsvieren kan få {npc1} til at lukke brønden i nat, så ingen drikker af den, før giften er væk.`,`Send {npc3} to {town} with word for {npc1}: the charcoal burner can get {npc1} to close the well tonight, so no one drinks from it until the poison is gone.`)],dmNotes:S(`{npc3} fortæller kun én løgn, og den er lille: stedet. Lad spillerne mærke, at kulsvieren er mere bange for at blive hængt for krybskytteri end for {boss}, og lad sandheden komme, når de viser, at de er ligeglade med en stjålet hare.`,`{npc3} tells only one lie, and a small one: the place. Let the players feel that the charcoal burner is more afraid of being hanged for poaching than of {boss}, and let the truth come out once they show they do not care about a stolen hare.`)},{kind:`combat`,at:`site`,present:[],title:S(`Bækken fra kilden`,`The Brook from the Spring`),summary:S([`Bækken fra kilden løber gennem en dyb dal under slugten, og jo længere heltene følger den op, desto grønnere bliver vandet, og desto mere dødt er alt langs bredden.`,`Nogle {foe} fra kildegrotten, gale af giften, strejfer langs bækken og angriber alt, der kommer nær vandet.`,`Ved kildens munding pibler det grønne vand ud af en revne, der fører op mod slugten på skrænten ovenover, og her ser heltene, hvor giften kommer fra.`],[`The brook from the spring runs through a deep dell below the swallow hole, and the further the heroes follow it upstream, the greener the water grows and the more lifeless the banks become.`,`Some {foe} from the spring cave, maddened by the poison, roam along the brook and attack anything that comes near the water.`,`At the mouth of the spring the green water seeps from a crack that runs up toward the swallow hole on the slope above, and here the heroes see where the poison comes from.`]),readAloud:S([`Bækken klukker mellem mosgroede sten, men der er ingen frøer og ingen fluer, og græsset langs bredden er gult og visnet.`,`På stenene i vandet sidder en tynd, grøn skorpe, og lidt længere oppe ligger et halvt tøndebånd og ruster i strømmen.`,`Så bliver der stille i krattet på den anden side af bækken, og noget pjasker hurtigt gennem vandet.`],[`The brook chuckles between mossy stones, but there are no frogs and no flies, and the grass along the bank is yellow and withered.`,`A thin green crust coats the stones in the water, and a little further up half a barrel hoop lies rusting in the current.`,`Then the scrub on the far side of the brook falls silent, and something splashes fast through the water.`]),details:[S(`Nogle {foe} fra kildegrotten er drevet ud af smerten og strejfer langs bækken. De angriber alt nær vandet, men flygter op mod kilden, når halvdelen af dem er faldet. Er der gået syv timer (andet tik), er de allerede på vej ned mod milerne, og slipper de forbi heltene, når de skovbrynet før natten.`,`Some {foe} from the spring cave have been driven out by the pain and roam along the brook. They attack anything near the water, but flee up toward the spring once half of them are down. If seven hours have passed (the second tick), they are already heading down toward the kilns, and if they slip past the heroes, they reach the forest edge before nightfall.`),S(`I bækken ligger stave og bånd fra knuste tønder, som vandet har ført ned fra kilden, og på en af stavene ses farveriets brændemærke: en krog med tre garnfed. Den grønne skorpe på stenene bliver tykkere, jo nærmere heltene kommer kilden.`,`In the brook lie staves and hoops from smashed barrels that the water has carried down from the spring, and on one stave the dye works’ brand can be seen: a hook with three skeins of yarn. The green crust on the stones grows thicker the closer the heroes come to the spring.`),S(`Kilden springer frem i en lav grotte i skrænten, og vandet pibler grønt ud af en revne i loftet, der fører lige op mod slugten ovenover. Dybt inde i grotten rører noget sig: Det er {boss}s hule, og grotten og slugten hænger sammen gennem revnen. Fra kilden er der en halv times stigning op ad skrænten til slugten.`,`The spring wells up in a low cave in the slope, and the water seeps green from a crack in the roof that runs straight up toward the swallow hole above. Deep inside the cave something stirs: this is {boss}’s lair, and the cave and the swallow hole are joined by the crack. From the spring it is a half-hour climb up the slope to the swallow hole.`)],checks:[w(`Wisdom (Perception)`,`medium`,S(`Heltene hører pjaskene i tide og tager imod angrebet på en bred sten midt i bækken, hvor ingen kan komme bag dem.`,`The heroes hear the splashing in time and meet the attack on a broad stone in the middle of the brook, where nothing can get behind them.`),S(`Angrebet kommer fra begge bredder på én gang, og heltene må kæmpe med fødderne i det bitre vand.`,`The attack comes from both banks at once, and the heroes must fight with their feet in the bitter water.`)),w(`Intelligence (Nature)`,`easy`,S(`Heltene ser, at det, der angriber dem, er sygt og plaget, ikke ondt: Giften i vandet gør dem gale, og holder giften op, kan de falde til ro igen.`,`The heroes see that what attacks them is sick and tormented, not wicked: the poison in the water is driving the attackers mad, and once it stops they may calm down again.`),S(`Heltene ser kun et rasende angreb og forstår ikke, hvorfor de er så vilde.`,`The heroes see only a furious attack and do not understand why the attackers are so wild.`))],fight:!0,alternatives:[S(`Lok dem væk fra vandet med larm eller lys længere nede ad bækken, og gå forbi, mens de leder.`,`Lure the attackers away from the water with noise or light further down the brook, and slip past while they search.`),S(`Gå uden om dalen ad kulvejen: Heltene undgår kampen, men ser ikke revnen ved kilden og ved ikke, at slugten og grotten hænger sammen.`,`Go around the dell by the charcoal track: the heroes avoid the fight, but do not see the crack at the spring and do not know that the swallow hole and the cave are joined.`)],dmNotes:S(`Kampen er ikke målet. Det, heltene møder her, er sygt og plaget; lad dem se nogle {foe} drikke af bækken og vride sig bagefter, så spillerne forstår, at det virkelige uhyre i dette eventyr har et brændemærke.`,`The fight is not the point. What the heroes meet here is sick and tormented; let them see some {foe} drink from the brook and writhe afterwards, so the players understand that the real monster in this adventure carries a brand.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:S(`Slugten over kilden`,`The Swallow Hole above the Spring`),summary:S([`Højt på skrænten over kilden ligger slugten, et gammelt hul i jorden, hvor alt, der bliver hældt ned, siver videre ned i kildegrotten, hvor {boss} og nogle {foe} har deres hule.`,`Om aftenen kommer {villain} selv op ad kulvejen med to svende, vognen og tolv tønder fra bundkarret og tømmer dem én efter én, bange for hver lyd i mørket; når en tønde bliver tømt, eller når nogen tænder lys ved slugten, bryder {boss} og de andre rasende op fra grotten og angriber alt, hvad de møder, også {villain}.`,`Heltene skal standse læsset, før det bliver tømt, standse {boss}, før {boss} og de andre bryder ned mod {town}, og afgøre, hvad der skal ske med {villain}.`],[`High on the slope above the spring lies the swallow hole, an old pit in the ground where everything poured in seeps on down into the spring cave, where {boss} and some {foe} have their lair.`,`In the evening {villain} comes up the charcoal track in person with two journeymen, the wagon and twelve barrels from the settling vat, and pours them in one by one, afraid of every sound in the dark. Whenever a barrel is poured, or anyone lights a lamp at the swallow hole, {boss} and the others burst up from the cave in a rage and attack whatever they meet, {villain} included.`,`The heroes must stop the load before it is poured, stop {boss} before {boss} and the others break out toward {town}, and decide what is to become of {villain}.`]),readAloud:S([`Højt på skrænten gaber slugten som en sort tragt i skovbunden, og omkring den er alt dødt: Træerne står uden blade, og jorden er farvet grøn og sort.`,`Ved kanten holder en tung vogn med tønder, og to svende vipper en tønde op over kanten i skæret fra en afskærmet lygte, mens en skikkelse med grønne hænder hvisker til dem, at de skal skynde sig.`,`Nede fra slugten lyder et dybt, gurglende ekko, og så noget andet, der ikke er vand.`],[`High on the slope the swallow hole gapes like a black funnel in the forest floor, and around it everything is dead: the trees stand leafless, and the ground is stained green and black.`,`At the edge stands a heavy wagon loaded with barrels, and two journeymen tip a barrel over the rim by the light of a shuttered lantern while a figure with green hands whispers at them to hurry.`,`From down in the hole comes a deep, gurgling echo, and then something else that is not water.`]),details:[S(`{boss} og nogle {foe} har deres hule i kildegrotten under slugten, og giften har gjort dem gale af smerte. De tjener ikke {villain}, der er rædselsslagen for dem, men bryder op gennem slugten, hver gang en tønde bliver tømt, eller når nogen tænder lys. Hver runde, der går, vipper svendene en tønde mere over kanten, og for hver tønde bliver raseriet dernede værre.`,`{boss} and some {foe} have their lair in the spring cave beneath the swallow hole, and the poison has driven them mad with pain. They do not serve {villain}, who is terrified of them, but burst up through the swallow hole whenever a barrel is poured or anyone lights a lamp. Each round, the journeymen tip one more barrel over the rim, and with every barrel the fury down below grows worse.`),S(`Tønderne bærer farveriets brændemærke, og de tolv tønder er hele sommerens rest fra bundkarret: Bliver de alle tømt, når giften {town}s brønd inden daggry. Vælter heltene vognen eller kiler hjulene fast, kommer der ikke flere tønder i slugten; svendene er ingen kæmpere og løber, så snart {boss} viser sig.`,`The barrels bear the dye works’ brand, and the twelve barrels hold the whole summer’s dregs from the settling vat: if they are all poured, the poison reaches the well of {town} before dawn. If the heroes overturn the wagon or chock its wheels, no more barrels go into the hole; the journeymen are no fighters and run as soon as {boss} appears.`),S(`Står {villain} over for tønderne, påbuddet fra porten eller sedlen til svendene, er der intet at vinde længere, og {villain} vil forhandle: om penge til at rense kilden, om grevens ordre og om at slippe for rådet. Truet af {boss} eller af heltene flygter {villain} ned ad kulvejen og lader svendene i stikken.`,`Faced with the barrels, the order from the gate or the note to the journeymen, {villain} has nothing left to gain and will bargain: over money to clean the spring, over the count’s order and over escaping the council. Threatened by {boss} or by the heroes, {villain} flees down the charcoal track and leaves the journeymen to their fate.`)],checks:[w(`Strength (Athletics)`,`medium`,S(`En helt kiler vognens hjul fast og vrider tønden fra svendene, før den bliver tømt; der kommer ikke mere gift i slugten i nat.`,`A hero chocks the wagon’s wheels and wrenches the barrel away from the journeymen before it is poured; no more poison goes into the swallow hole tonight.`),S(`Tønden vipper over kanten og bliver tømt med et gurglende plask dernede, og {boss} og de andre bryder op af slugten midt mellem heltene og vognen.`,`The barrel tips over the rim and empties with a gurgling splash below, and {boss} and the others burst up out of the hole right between the heroes and the wagon.`)),w(`Charisma (Intimidation)`,`medium`,S(`Med tønderne og sedlen for øjnene forstår {villain}, at alt er tabt, og overgiver sig hellere end at blive efterladt alene ved slugten med {boss}.`,`With the barrels and the note before their eyes, {villain} understands that all is lost and surrenders rather than be left alone at the swallow hole with {boss}.`),S(`{villain} råber til svendene, at de skal tømme resten, og løber mod kulvejen; svendene vipper en tønde mere, før de flygter.`,`{villain} shouts at the journeymen to pour the rest and runs for the charcoal track; the journeymen tip one more barrel before they flee.`))],fight:!0,alternatives:[S(`Prop slugten: Fylder heltene hullet med sten og jord, løber giften af ned ad skrænten i stedet for ned i kilden, og {boss} og de andre får fred til at komme sig; men det tager en halv time midt i kampen.`,`Plug the swallow hole: if the heroes fill it with stones and earth, the poison runs off down the slope instead of into the spring, and {boss} and the others are left in peace to recover; but it takes half an hour in the middle of the fight.`),S(`Lad {villain} hælde selv: Venter heltene i mørket, til {villain} vipper den første tønde, er {villain} fanget på fersk gerning, og intet råd kan tvivle; men så vågner {boss} dernede.`,`Let {villain} do the pouring: if the heroes wait in the dark until {villain} tips the first barrel, {villain} is caught in the act and no council can doubt it; but then {boss} wakes down below.`)],dmNotes:S(`Lad tønderne være det ur, alle kan se: Sæt tolv mønter på bordet, og tag én væk, hver gang en tønde bliver tømt. Husk, at heltene blev hyret til at standse {boss}; lad dem selv afgøre, om det stadig betyder at dræbe, når de ved, hvem der forgiftede kilden.`,`Make the barrels the clock everyone can see: put twelve coins on the table and take one away each time a barrel is poured. Remember that the heroes were hired to stop {boss}; let them decide for themselves whether that still means killing, once they know who poisoned the spring.`)}},ze=e({kernel:()=>Ue,scenes:()=>We}),Be=e=>Array.isArray(e)?e.join(` `):e,T=(e,t)=>({da:Be(e),en:Be(t)}),Ve=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),E=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},He=(e,t,n)=>({when:e,event:t,sign:n}),D=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),Ue={id:`wild-the-frozen-pass`,titles:[T(`Det frosne pas`,`The Frozen Pass`),T(`Brød til ti gange prisen`,`Bread at Ten Times the Price`),T(`Den skårne bro`,`The Cut Bridge`)],missions:[`wilderness`],foes:`beasts`,roles:{npc1:T(`en muldriver fra karavanen, der gav alt for én tur i {villain}s kurv for at hente hjælp`,`a muleteer from the caravan who gave everything for one crossing in {villain}’s basket to fetch help`),npc2:T(`en karl på herberget, der sælger {villain}s brød til de strandede rejsende`,`a hired hand at the hospice who sells {villain}’s bread to the stranded travellers`),npc3:T(`en rebslager i {town}, der slog broens nye tove sidste sommer`,`a ropemaker in {town} who laid the bridge’s new ropes last summer`),villain:T(`en købmand, der ejer herberget på passet og kurvelinen over kløften`,`a merchant who owns the hospice in the pass and the basket line across the gorge`)},hook:T(`{npc1} finder heltene i {town} ved daggry, med rim i håret og en tom pung, og beder dem gå op i {place} og føre de strandede rejsende på herberget ned, før den næste storm lukker passet.`,`{npc1}, with frost in their hair and an empty purse, finds the heroes in {town} at dawn and begs them to go up into {place} and lead the stranded travellers at the hospice down before the next storm closes the pass.`),people:{npc1:{wants:T(`Vil have resten af karavanen ned fra passet, før stormen kommer, og vil aldrig betale {villain} en mønt mere.`,`Wants the rest of the caravan down from the pass before the storm comes, and will never pay {villain} another coin.`),secret:T(`Tog karavanens fælles sølv for at betale for turen i kurven og frygter, at de andre tror, at {npc1} er flygtet med det.`,`Took the caravan’s shared silver to pay for the crossing in the basket, and fears the others think {npc1} has run off with it.`)},npc2:{wants:T(`Vil ned fra passet med de andre, uden at nogen finder ud af, hvad der skete med broen.`,`Wants to get down from the pass with the others without anyone finding out what happened to the bridge.`),secret:T(`Holdt lygten for {villain}, da broens tove blev skåret over i stormnatten, og troede, at det kun var for at holde gæsterne på herberget en nat mere.`,`Held the lantern for {villain} when the bridge ropes were cut on the night of the storm, believing it was only to keep the guests at the hospice one more night.`)},npc3:{wants:T(`Vil have sit gode navn renset, for i {town} siger folk, at broen faldt, fordi tovene var dårlige.`,`Wants their good name cleared, for in {town} people say the bridge fell because the ropes were poor.`),secret:T(`Solgte {villain} fire ruller reservetov til broen sidste efterår og har tiet om det, fordi {villain} er rebslagerbanens bedste kunde.`,`Sold {villain} four coils of spare rope for the bridge last autumn and has kept quiet about it, because {villain} is the ropewalk’s best customer.`)}},premise:T([`Den eneste vej fra passet i {place} ned til {town} går over hængebroen over kløften, og øverst i passet ligger herberget, som {villain} ejer sammen med forrådet og den kurveline, som varer bliver halet over kløften med.`,`For tre nætter siden lukkede en storm vejen tilbage over passet bag en karavane på over tyve rejsende, og samme nat skar {villain} broens tove over og gav stormen skylden.`,`Siden har {villain} solgt brød til ti gange prisen og ladet folk krydse kløften én ad gangen i kurven for alt, hvad de ejer; de, der ikke kan betale, sidder stadig på herberget, og brændet slipper op.`,`Ved mørkets frembrud rammer den næste storm, og da vil {villain} krydse som den sidste med pengekisten og skære linen over bag sig, så ingen kan følge efter og fortælle, hvad der skete med broen.`],[`The only way from the pass in {place} down to {town} crosses the hanging bridge over the gorge, and at the top of the pass stands the hospice, which {villain} owns together with its stores and the basket line used to haul goods across the gorge.`,`Three nights ago a storm closed the way back over the pass behind a caravan of more than twenty travellers, and that same night {villain} cut the bridge’s ropes and blamed the storm.`,`Since then {villain} has sold bread at ten times the price and let people cross the gorge one at a time in the basket for everything they own; those who cannot pay are still at the hospice, and the firewood is running out.`,`At nightfall the next storm hits, and then {villain} means to cross last with the strongbox and cut the line behind them, so that no one can follow and tell what happened to the bridge.`]),goal:T(`Kom over kløften til herberget i {place}, få alle de strandede rejsende ned over kløften, og stands {villain} ved kurvelinen, før stormen rammer ved mørkets frembrud.`,`Cross the gorge to the hospice in {place}, get all the stranded travellers down across the gorge and stop {villain} at the basket line before the storm hits at nightfall.`),objective:{target:T(`Kurvelinen ved brohovedet over kløften, den eneste vej ned fra herberget i {place} til {town}`,`The basket line at the bridgehead over the gorge, the only way down from the hospice in {place} to {town}`),state:T(`Broens tove er skåret over, og dækket hænger ned ad klippen. Ved kurvelinens spil sidder {villain} med to karle og en pengekiste fuld af de rejsendes ejendele, og i det gamle tårn ved brohovedet har {boss} og nogle {foe} deres vinterhule.`,`The bridge’s ropes have been cut and its deck hangs down the cliff. At the basket line’s windlass sits {villain} with two hired hands and a strongbox full of the travellers’ belongings, and in the old tower at the bridgehead {boss} and some {foe} have their winter lair.`),resolution:T([`Få alle de rejsende over kløften, før stormen rammer, i kurven eller på en ny overgang slået med reservetovene fra herberget, og bring {villain} ned til {town} med de afskårne tove og pengekisten som bevis.`,`Bliver linen skåret over, kan reservetovene stadig bære de sidste over, hvis nogen får den første ende over kløften.`],[`Get every traveller across the gorge before the storm hits, in the basket or on a new crossing rigged with the spare ropes from the hospice, and bring {villain} down to {town} with the cut ropes and the strongbox as proof.`,`If the line is cut, the spare ropes can still carry the last of them across, as long as someone gets the first end over the gorge.`])},villain:{want:T(`At blive rig på én vinter ved at sælge brød og overfart til folk, der ikke har noget valg.`,`To grow rich in a single winter by selling bread and passage to people who have no choice.`),plan:T([`Da stormen for tre nætter siden lukkede vejen tilbage over passet bag karavanen, skar {villain} broens tove over, mens {npc2} holdt lygten, og gav stormen skylden.`,`Siden har {villain} gemt reservetovene i brændeskuret, solgt herbergets brød og brænde til ti gange prisen og ladet de rejsende krydse kløften én ad gangen i kurven for alt, hvad de ejer.`,`Ved mørkets frembrud, når den næste storm rammer, hejser {villain} pengekisten over, krydser selv som den sidste og skærer linen over bag sig, så ingen kan følge efter og fortælle, hvad der skete med broen.`],[`When the storm closed the way back over the pass behind the caravan three nights ago, {villain} cut the bridge’s ropes while {npc2} held the lantern, and blamed the storm.`,`Since then {villain} has hidden the spare ropes in the woodshed, sold the hospice’s bread and firewood at ten times the price and let the travellers cross the gorge one at a time in the basket for everything they own.`,`At nightfall, when the next storm hits, {villain} hauls the strongbox across, crosses last in person and cuts the line behind them, so that no one can follow and tell what happened to the bridge.`]),weakness:T([`{villain} er grådig: Pengekisten er for tung til at krydse i samme tur som {villain}, og {villain} vil hellere blive i stormen end efterlade den.`,`Og de afskårne tove hænger stadig ned ad klippen under brohovedet, hvor enhver kan se, at de er skåret over med en kniv og ikke slidt over af stormen.`],[`{villain} is greedy: the strongbox is too heavy to cross in the same trip as {villain}, and {villain} would rather stay in the storm than leave it behind.`,`And the cut ropes still hang down the cliff below the bridgehead, where anyone can see that they were cut with a knife and not worn through by the storm.`])},stakes:T(`Når stormen rammer, sidder de rejsende, der ikke kunne betale, stadig på herberget uden brænde og brød, og passet er lukket i ugevis; {villain} er nede i {town} med alt, hvad de ejede, og fortæller, at stormen tog både broen og linen.`,`When the storm hits, the travellers who could not pay are still at the hospice without firewood or bread, and the pass is closed for weeks; {villain} is down in {town} with everything the travellers owned, telling everyone that the storm took both the bridge and the line.`),clock:{start:T(`Daggry. Skyerne ligger tunge over toppene, og de vejrkloge i {town} siger, at den næste storm rammer passet ved mørkets frembrud, om otte timer. På herberget sidder over tyve rejsende, de fleste uden en mønt tilbage, og brændet slipper op i aften.`,`Dawn. Clouds lie heavy over the peaks, and the weather-wise in {town} say the next storm will hit the pass at nightfall, eight hours from now. More than twenty travellers wait at the hospice, most of them without a coin left, and the firewood runs out tonight.`),ticks:[He(T(`Efter 2 timer`,`After 2 hours`),T(`{villain} fordobler prisen på en tur i kurven og lader {npc2} sælge herbergets sidste brænde til den højestbydende; de, der ikke kan betale, sidder i kulden.`,`{villain} doubles the price of a crossing in the basket and has {npc2} sell the hospice’s last firewood to the highest bidder; those who cannot pay sit in the cold.`),T(`Fra vejen under kløften ses kurven gå over afgrunden igen og igen med én rejsende ad gangen, og røgen fra herbergets skorsten bliver tyndere.`,`From the road below the gorge the basket can be seen crossing the drop again and again with one traveller at a time, and the smoke from the hospice chimney grows thinner.`)),He(T(`Efter 5 timer`,`After 5 hours`),T(`Vinden tager til, og sneen begynder at fyge; {boss} og nogle {foe} tager to muldyr fra herbergets stald, og {villain} lader karlene bære pengekisten ned til spillet ved brohovedet.`,`The wind rises and the snow begins to drift; {boss} and some {foe} take two mules from the hospice stable, and {villain} has the hired hands carry the strongbox down to the windlass at the bridgehead.`),T(`Sneen fyger ned i kløften, isen på isfaldet bliver glat som glas, og ved stalden er der blodige spor i sneen.`,`Snow drifts down into the gorge, the ice on the frozen falls turns slick as glass and there are bloody tracks in the snow by the stable.`)),He(T(`Efter 8 timer (ved mørkets frembrud)`,`After 8 hours (at nightfall)`),T(`Stormen rammer: {villain} hejser pengekisten over kløften, krydser selv som den sidste og skærer kurvelinen over bag sig, og de, der stadig er på herberget, er fanget uden brænde.`,`The storm hits: {villain} hauls the strongbox across the gorge, crosses last in person and cuts the basket line behind them, and those still at the hospice are trapped without firewood.`),T(`Sneen kommer vandret ind over passet, og linen over kløften synker ned i mørket og forsvinder.`,`Snow drives sideways over the pass, and the line across the gorge sinks into the dark and is gone.`))],deadline:T(`Efter 8 timer, ved mørkets frembrud, er det for sent: Stormen lukker passet, kurvelinen er skåret over, og de rejsende, der stadig er på herberget, må klare sig uden brænde og brød, til nogen kan komme op igen om flere uger.`,`After 8 hours, at nightfall, it is too late: the storm closes the pass, the basket line is cut and the travellers still at the hospice must get by without firewood or bread until someone can come up again in several weeks.`)},clues:{who:[E(`town`,T(`I rebslagerbanens ordrebog står {villain}s køb fra sidste efterår: to bæretove til broen og fire ruller reservetov, betalt kontant og hentet op til herberget.`,`The ropewalk’s order book records {villain}’s purchase from last autumn: two bearing ropes for the bridge and four coils of spare rope, paid in cash and taken up to the hospice.`),T(`{villain} har tovene til at sætte broen op igen, men har ikke gjort det.`,`{villain} has the ropes to put the bridge back up, but has not done so.`),Ve([`Rebslagerbanen i {town}. Solgt i slagtemåneden:`,`Til {villain}, herberget på passet: 2 bæretove af tjæret hamp, 60 favne hver.`,`Samme: 4 ruller reservetov til broen, 40 favne hver.`,`Betalt kontant. Hentet med slæde.`],[`The ropewalk of {town}. Sold in the slaughter month:`,`To {villain}, the hospice in the pass: 2 bearing ropes of tarred hemp, 60 fathoms each.`,`The same: 4 coils of spare rope for the bridge, 40 fathoms each.`,`Paid in cash. Fetched by sledge.`])),E(`town`,T(`{npc1} har en af de prissedler med, som {villain} har slået op i herbergets skænkestue.`,`{npc1} has brought one of the price notices {villain} has nailed up in the hospice’s common room.`),T(`{villain} tjener på hver dag, de rejsende sidder fast, og har ingen grund til at få broen op igen.`,`{villain} profits from every day the travellers are stuck, and has no reason to get the bridge back up.`),Ve([`Herberget på passet. Priser fra i dag, til broen er oppe igen:`,`Et brød: 5 sølv. En skål suppe: 3 sølv. En favn brænde: 20 sølv.`,`En plads i kurven over kløften: 50 sølv for hver, der skal over, betales forud. Muldyr og varer tages i bytte.`,`Ingen kredit. – {villain}`],[`The hospice in the pass. Prices from today, until the bridge is up again:`,`A loaf: 5 silver. A bowl of soup: 3 silver. A fathom of firewood: 20 silver.`,`A place in the basket across the gorge: 50 silver a head, paid in advance. Mules and goods taken in exchange.`,`No credit. — {villain}`])),E(`site`,T(`I kløften hænger broens dæk ned ad klippen, og for enden af de to bæretove er snittet glat og lige, skåret med en kniv og ikke flosset af stormen.`,`In the gorge the bridge deck hangs down the cliff, and at the ends of the two bearing ropes the cut is smooth and straight, made with a knife and not frayed by the storm.`),T(`Broen blev skåret ned fra herbergets side af kløften, og kun {villain}s folk var der den nat.`,`The bridge was cut down from the hospice side of the gorge, and only {villain}’s people were there that night.`)),E(`site`,T(`I brændeskuret bag herberget ligger fire ruller nyt tjæret tov gemt under en presenning, med rebslagerbanens mærke på hver rulle.`,`In the woodshed behind the hospice lie four coils of new tarred rope hidden under a tarpaulin, the ropewalk’s mark on every coil.`),T(`{villain} har gemt de tove, der kunne sætte broen op igen, så de rejsende er nødt til at betale for kurven.`,`{villain} has hidden the ropes that could put the bridge back up, so that the travellers have no choice but to pay for the basket.`))],where:[E(`town`,T(`{npc1} hørte {villain} sige til karlene ved spillet: "Når stormen kommer, krydser jeg som den sidste, og så skal linen væk."`,`{npc1} heard {villain} tell the hired hands at the windlass: "When the storm comes, I cross last, and then the line goes."`),T(`{villain} vil være ved kurvelinens spil ved brohovedet ved mørkets frembrud for at skære linen over.`,`{villain} will be at the basket line’s windlass by the bridgehead at nightfall, to cut the line.`)),E(`site`,T(`Oppe fra kanten af isfaldet i kløften kan heltene se kurvelinens spil ved brohovedet, hvor {villain} sidder med to karle og en jernbeslået kiste, og det gamle tårn uden tag lige ved siden af; spor i sneen fører fra tårnet ned langs kløften.`,`From the top of the frozen falls in the gorge, the heroes can see the basket line’s windlass by the bridgehead, where {villain} sits with two hired hands and an iron-bound chest, and the old roofless tower right beside it; tracks in the snow lead from the tower down along the gorge.`),T(`Vejen ned, pengene og {boss}s hule er alle ved brohovedet.`,`The way down, the money and {boss}’s lair are all at the bridgehead.`)),E(`site`,T(`I {npc2}s forklæde på herberget ligger en seddel med {villain}s ordrer for aftenen.`,`In {npc2}’s apron at the hospice is a note with {villain}’s orders for the evening.`),T(`{villain} vil krydse som den sidste fra brohovedet ved mørkets frembrud med pengekisten og skære linen over bag sig.`,`{villain} means to cross last from the bridgehead at nightfall with the strongbox and cut the line behind them.`),Ve([`Hold dem inde på herberget, når det mørkner, og luk døren.`,`Bær kisten ned til spillet ved brohovedet, når sneen begynder.`,`Ingen andre i kurven efter mig. Det, der sker med linen, er stormens skyld. – {villain}`],[`Keep them inside the hospice when it grows dark, and shut the door.`,`Carry the chest down to the windlass at the bridgehead when the snow begins.`,`No one else in the basket after me. Whatever happens to the line is the storm’s doing. — {villain}`])),E(`site`,T(`{npc2}, karlen på herberget, tilstår at have holdt lygten, da {villain} skar broens tove over i stormnatten, og at {villain} har svoret, at linen skal samme vej, når stormen kommer.`,`{npc2}, the hired hand at the hospice, confesses to holding the lantern when {villain} cut the bridge ropes on the night of the storm, and says {villain} has sworn the line will go the same way when the storm comes.`),T(`Den eneste vej ned er kurvelinen ved brohovedet, og {villain} vil skære den over ved mørkets frembrud.`,`The only way down is the basket line at the bridgehead, and {villain} means to cut it at nightfall.`))]},endings:{success:T(`Alle de rejsende kommer over kløften, før stormen lukker passet, og {villain} bliver ført ned til {town} med pengekisten og de afskårne tove som bevis. Rådet giver de rejsende deres ejendele tilbage fra kisten, {npc3} slår nye tove til broen til foråret, og karavanen giver heltene en andel af det salt, de fik igen.`,`Every traveller gets across the gorge before the storm closes the pass, and {villain} is brought down to {town} with the strongbox and the cut ropes as proof. The council returns the travellers’ belongings from the chest, {npc3} lays new ropes for the bridge in spring and the caravan gives the heroes a share of the salt they got back.`),partial:T(`Heltene får de fleste ned, men ikke alle, eller {villain} slipper over kløften med pengekisten og fortæller sin egen historie først i {town}. Nogle rejsende må vente stormen ud på herberget, til heltene kan gå op efter dem, og byen strides hele vinteren om, hvem der skar broen.`,`The heroes get most of them down, but not all, or {villain} slips across the gorge with the strongbox and is first to tell their side of the story in {town}. Some travellers must wait out the storm at the hospice until the heroes can go back up for them, and all winter the town argues over who cut the bridge.`),failure:T(`Ved mørkets frembrud skærer {villain} linen over, og stormen lukker passet. Der går uger, før nogen kan komme op til herberget, og {villain} køber sig et hus i {town} for de rejsendes sølv og fortæller alle, at stormen tog både broen og linen.`,`At nightfall {villain} cuts the line and the storm closes the pass. Weeks pass before anyone can get up to the hospice, and {villain} buys a house in {town} with the travellers’ silver and tells everyone that the storm took both the bridge and the line.`)}},We={opening:{kind:`opening`,at:`town`,present:[`npc1`],title:T(`Muldriveren fra passet`,`The Muleteer from the Pass`),summary:T([`Ved daggry finder {npc1}, en muldriver fra den strandede karavane, heltene i {town} med rim i håret og en tom pung og beder dem gå op i {place} og føre de rejsende på herberget ned, før den næste storm lukker passet.`,`Broen over kløften er faldet, og den eneste vej over er {villain}s kurv på linen, hvor én rejsende ad gangen kan krydse for alt, hvad de ejer; {npc1} gav karavanens sidste sølv for en enkelt tur.`,`Byen kan give svar, før heltene går, men hver omvej koster tid, og de vejrkloge siger, at stormen rammer ved mørkets frembrud.`],[`At dawn {npc1}, a muleteer from the stranded caravan, with frost in their hair and an empty purse, finds the heroes in {town} and begs them to go up into {place} and lead the travellers at the hospice down before the next storm closes the pass.`,`The bridge over the gorge has fallen, and the only way across is {villain}’s basket on the line, in which one traveller at a time can cross for everything they own; {npc1} gave the caravan’s last silver for a single crossing.`,`The town can give answers before the heroes go, but every detour costs time, and the weather-wise say the storm will hit at nightfall.`]),readAloud:T([`Kroen er fuld af damp fra våde kapper, og ude på gaden ligger sneen til knæene.`,`Ved ilden sidder en muldriver med rim i håret og fingre, der ikke vil lukke sig om kruset, og stirrer op mod passet, hvor skyerne allerede ligger tunge over toppene.`,`På bordet ligger en krøllet prisseddel og en pung, der er vendt med vrangen ud.`],[`The inn is full of steam from wet cloaks, and out in the street the snow lies knee-deep.`,`By the fire sits a muleteer with frost in their hair and fingers that will not close around the mug, staring up at the pass, where the clouds already lie heavy over the peaks.`,`On the table lie a crumpled price notice and a purse turned inside out.`]),details:[T(`{npc1} fortæller, at karavanen kom over passet fra den anden side for fire dage siden og søgte ly på herberget, da stormen kom. Om morgenen var vejen tilbage begravet i sne, og broen over kløften hang ned ad klippen; {villain}, der ejer herberget, sagde, at stormen havde taget den, og at den ikke kan sættes op igen før foråret.`,`{npc1} tells how the caravan came over the pass from the far side four days ago and took shelter at the hospice when the storm came. In the morning the way back was buried in snow and the bridge over the gorge hung down the cliff; {villain}, who owns the hospice, said the storm had taken it and that it could not be put back up before spring.`),T(`{npc1} har {villain}s prisseddel med fra herbergets skænkestue og viser den gerne frem: brød til ti gange prisen, brænde for sølv og en plads i kurven for halvtreds sølv, betalt forud. Over tyve rejsende sidder stadig deroppe, de fleste uden en mønt tilbage, og {npc1} hørte {villain} sige til karlene, at linen skal væk, når stormen kommer.`,`{npc1} has brought {villain}’s price notice from the hospice’s common room and is glad to show it: bread at ten times the price, firewood for silver and a place in the basket for fifty silver, paid in advance. More than twenty travellers are still up there, most of them without a coin left, and {npc1} heard {villain} tell the hired hands that the line must go when the storm comes.`),T(`Der er otte timer til mørkets frembrud. Vejen fra {town} op til kløften tager to timer i sneen; derfra er der kun kurven, som {villain}s karle sender over for den, der betaler, eller isfaldet i kløften, som ingen har klatret op ad om vinteren i mands minde. {npc3}, rebslageren, slog broens tove sidste sommer og har reb og kramper at sælge.`,`There are eight hours until nightfall. The road from {town} up to the gorge takes two hours through the snow; from there, there is only the basket, which {villain}’s hands send across for anyone who pays, or the frozen falls in the gorge, which no one has climbed in winter in living memory. {npc3}, the ropemaker, laid the bridge’s ropes last summer and has rope and climbing irons for sale.`)],checks:[D(`Wisdom (Insight)`,`easy`,T(`Heltene ser, at {npc1} skammer sig over noget; et venligt ord får muldriveren til at indrømme, at pengene til turen var karavanens fælles sølv, og at de andre deroppe venter på, at {npc1} kommer tilbage med hjælp.`,`The heroes see that {npc1} is ashamed of something; a kind word gets the muleteer to admit that the money for the crossing was the caravan’s shared silver, and that the others up there are waiting for {npc1} to come back with help.`),T(`{npc1} er for træt og bange til at sige mere end det nødvendige; heltene får kun prissedlen og vejen.`,`{npc1} is too tired and frightened to say more than the bare minimum; the heroes get only the price notice and directions.`)),D(`Charisma (Persuasion)`,`medium`,T(`Kroværten og et par stærke folk fra {town} lover at gå op til kløften med slæder, tæpper og varm suppe og tage imod de rejsende på denne side.`,`The innkeeper and a few strong folk from {town} promise to go up to the gorge with sledges, blankets and hot soup to meet the travellers on this side.`),T(`Ingen i {town} vil gå op mod passet med en storm på vej; de rejsende må klare sig selv, når de er kommet over.`,`No one in {town} will go up toward the pass with a storm on the way; the travellers must fend for themselves once they are across.`))],fight:!1,alternatives:[T(`Gå direkte op mod kløften: Heltene vinder tid, men har hverken reb eller kramper til isfaldet og må betale {villain} for kurven eller vende om.`,`Head straight up to the gorge: the heroes gain time, but have neither rope nor climbing irons for the frozen falls and must pay {villain} for the basket or turn back.`),T(`Tag {npc1} med: Muldriveren kender herberget og de rejsende og kan få dem til at stole på heltene, men er udmattet og går langsomt i sneen.`,`Take {npc1} along: the muleteer knows the hospice and the travellers and can get them to trust the heroes, but is exhausted and slow in the snow.`)],dmNotes:T(`Lad prissedlen gå rundt ved bordet; den siger mere om {villain} end noget, {npc1} kan fortælle. Hver gang spillerne tøver, så lad skyerne synke lidt længere ned over passet.`,`Let the price notice go round the table; it says more about {villain} than anything {npc1} can say. Whenever the players hesitate, let the clouds sink a little lower over the pass.`)},middle:[{kind:`investigation`,at:`town`,present:[`npc3`],title:T(`Rebslagerbanen`,`The Ropewalk`),summary:T([`I udkanten af {town} ligger rebslagerbanen, en lang lade, hvor {npc3} slog broens nye tove sidste sommer, og hvor hele byen nu siger, at tovene var dårlige.`,`{npc3} ved, at de tove kunne bære et muldyrtog i ti år, og at {villain} sidste efterår købte fire ruller reservetov til broen, som aldrig er kommet i brug.`,`Her kan heltene skaffe reb og kramper til isfaldet og forstå, at broen ikke faldt af sig selv.`],[`At the edge of {town} lies the ropewalk, a long shed where {npc3} laid the bridge’s new ropes last summer, and where the whole town now says the ropes were poor.`,`{npc3} knows those ropes could carry a mule train for ten years, and that last autumn {villain} bought four coils of spare rope for the bridge that have never been used.`,`Here the heroes can get rope and climbing irons for the frozen falls, and come to understand that the bridge did not fall by itself.`]),readAloud:T([`Rebslagerbanen er en lade så lang, at man knap kan se den anden ende i halvmørket, og luften lugter af tjære og hamp.`,`Langs væggene hænger tove i alle tykkelser, og midt på gulvet drejer en skikkelse med tjæresorte hænder et hjul, mens tre lange garn snor sig sammen til ét.`,`Over døren hænger et stykke tov, tykt som en arm, og under det står der skrevet med kridt: Dette holder.`],[`The ropewalk is a shed so long that you can barely see the far end in the gloom, and the air smells of tar and hemp.`,`Ropes of every thickness hang along the walls, and in the middle of the floor a figure with tar-black hands turns a wheel while three long strands twist together into one.`,`Above the door hangs a length of rope as thick as an arm, and beneath it someone has chalked: This holds.`]),details:[T(`{npc3} slog broens to bæretove af tjæret hamp, tykke som en arm, og hver eneste rebslager på egnen ved, at sådan et tov ikke slides over af én storm. Hører {npc3}, at broen bare faldt, ryster rebslageren på hovedet: Et tov, der knækker, flosser over en armslængde; et tov, der bliver skåret over, er glat og lige.`,`{npc3} laid the bridge’s two bearing ropes of tarred hemp, as thick as an arm, and every ropemaker in the district knows that such a rope is not worn through by a single storm. Told that the bridge simply fell, the ropemaker shakes their head: a rope that snaps frays over an arm’s length; a rope that is cut is smooth and straight.`),T(`I rebslagerbanens ordrebog står {villain}s køb fra sidste efterår: to bæretove og fire ruller reservetov, betalt kontant og hentet op til herberget. Reservetovene er nok til at slå en smal overgang over kløften, et tov at gå på og to at holde i, men ingen har set dem siden.`,`The ropewalk’s order book records {villain}’s purchase from last autumn: two bearing ropes and four coils of spare rope, paid in cash and taken up to the hospice. The spare ropes are enough to rig a narrow crossing over the gorge, one rope to walk on and two to hold, but no one has seen them since.`),T(`{npc3} kan sælge heltene reb og jernkramper og fortælle, at isfaldet i kløften blev klatret af smuglere i gamle dage: Der sidder stadig rustne kramper i klippen bag isen, og den, der finder dem, kan komme op på en time. Kurven er hurtigere, men {villain}s karle sender den kun over for den, der betaler, og {villain} vil vide, hvem der kommer.`,`{npc3} can sell the heroes rope and climbing irons and tell them that smugglers climbed the frozen falls in the gorge in the old days: rusty irons are still set in the rock behind the ice, and whoever finds them can get up in an hour. The basket is faster, but {villain}’s hands only send it across for those who pay, and {villain} will want to know who is coming.`)],checks:[D(`Charisma (Persuasion)`,`easy`,T(`{npc3} finder ordrebogen frem og giver heltene en rulle af det bedste tov og et sæt kramper til isfaldet for intet; rebslageren vil have sit gode navn tilbage.`,`{npc3} brings out the order book and gives the heroes a coil of the best rope and a set of irons for the frozen falls for nothing; the ropemaker wants their good name back.`),T(`{npc3} vil ikke tale om {villain}, rebslagerbanens bedste kunde; heltene må betale fuld pris for reb og kramper, og ordrebogen kommer først frem, når de vender tilbage.`,`{npc3} will not talk about {villain}, the ropewalk’s best customer; the heroes must pay full price for rope and irons, and the order book only comes out when they return.`)),D(`Intelligence (Investigation)`,`medium`,T(`Heltene ser i ordrebogen, at reservetovene blev hentet op til herberget og aldrig sendt tilbage; skal broen repareres, ligger tovene på herberget.`,`The heroes see in the order book that the spare ropes were taken up to the hospice and never sent back; if the bridge is to be mended, the ropes are at the hospice.`),T(`Ordrebogen er fuld af tal og navne; heltene finder kun købet af bæretovene og må gætte resten.`,`The order book is full of figures and names; the heroes find only the purchase of the bearing ropes and must guess the rest.`))],fight:!1,alternatives:[T(`Køb kun det nødvendige, og gå med det samme: Heltene sparer en halv time, men ved ikke, at reservetovene ligger på herberget.`,`Buy only what is needed and leave at once: the heroes save half an hour, but do not know that the spare ropes are at the hospice.`),T(`Tag {npc3} med: Rebslageren kan slå en ny overgang over kløften på en time, hvis tovene findes, men er ingen klatrer og må hejses op ad isfaldet.`,`Take {npc3} along: the ropemaker can rig a new crossing over the gorge in an hour if the ropes are found, but is no climber and must be hauled up the frozen falls.`)],dmNotes:T(`Rebslagerbanen er stedet, hvor spillerne forstår, at det her ikke var et uheld. Lad {npc3} binde et tov om en bjælke og lade en helt prøve at rive det over; ingen kan, og det er hele pointen.`,`The ropewalk is where the players understand that this was no accident. Let {npc3} tie a rope round a beam and let a hero try to tear it apart; no one can, and that is the whole point.`)},{kind:`combat`,at:`site`,present:[],title:T(`Isfaldet i kløften`,`The Frozen Falls in the Gorge`),summary:T([`To timers gang over {town} går vejen ind i {place} og ender ved kløften, hvor broens dæk hænger ned ad klippen, og hvor {villain}s kurv glider frem og tilbage over afgrunden på sin line.`,`Den eneste anden vej op er isfaldet i kløften, et frossent vandfald med gamle smuglerkramper bag isen, og her jager nogle {foe} langs klippevæggen.`,`Her ser heltene, at broen blev skåret ned, og må kæmpe sig op til herbergets side af kløften.`],[`Two hours’ walk above {town} the road enters {place} and ends at the gorge, where the bridge deck hangs down the cliff and {villain}’s basket slides back and forth over the drop on its line.`,`The only other way up is the frozen falls in the gorge, a waterfall turned to ice with old smugglers’ irons behind it, and here some {foe} hunt along the cliff face.`,`Here the heroes see that the bridge was cut down, and must fight their way up to the hospice side of the gorge.`]),readAloud:T([`Kløften åbner sig foran jer som et sår i fjeldet, og fra kanten hænger broens dæk lodret ned i dybet og klaprer i vinden som en løs skodde.`,`Over afgrunden glider en kurv langsomt hen ad en line, og på den anden side ses et træspil, et gammelt tårn og røgen fra et herberg højere oppe.`,`Et stykke oppe ad kløften hænger et vandfald frosset fast til klippen, blåt og hvidt, og noget bevæger sig hen over isen.`],[`The gorge opens before you like a wound in the mountain, and from its edge the bridge deck hangs straight down into the depths, clattering in the wind like a loose shutter.`,`Over the drop a basket glides slowly along a line, and on the far side stand a wooden windlass, an old tower and, higher up, the smoke of a hospice.`,`A little way up the gorge a waterfall hangs frozen to the cliff, blue and white, and something is moving across the ice.`]),details:[T(`Broens dæk hænger fra ankerstolperne på denne side, og den, der kravler et stykke ned ad det, kan se enderne af bæretovene: Snittet er glat og lige, skåret med en kniv og ikke flosset. Broen blev skåret ned fra herbergets side af kløften.`,`The bridge deck hangs from the anchor posts on this side, and whoever climbs a little way down it can see the ends of the bearing ropes: the cut is smooth and straight, made with a knife and not frayed. The bridge was cut down from the hospice side of the gorge.`),T(`Nogle {foe} jager langs kløften om vinteren og har deres hule i det gamle tårn ved brohovedet på den anden side. De angriber den, der hænger på isfaldet, og trækker sig tilbage mod tårnet, når halvdelen af dem er faldet. Er der gået fem timer (andet tik), fyger sneen, og isen er glat som glas.`,`Some {foe} hunt along the gorge in winter and have their lair in the old tower at the bridgehead on the far side. They attack whoever hangs on the frozen falls, and fall back toward the tower once half of them are down. If five hours have passed (the second tick), the snow is drifting and the ice is slick as glass.`),T(`Bag isen sidder rustne smuglerkramper i klippen, og med reb og jernkramper kan heltene klatre op på en time; uden dem tager det to, og et fald koster mere end tid. Oppe fra kanten kan heltene se kurvelinens spil ved brohovedet, hvor {villain} sidder med to karle og en jernbeslået kiste, og herberget en halv times gang højere oppe.`,`Behind the ice, rusty smugglers’ irons are set in the rock, and with rope and climbing irons the heroes can climb up in an hour; without them it takes two, and a fall costs more than time. From the top the heroes can see the basket line’s windlass at the bridgehead, where {villain} sits with two hired hands and an iron-bound chest, and the hospice half an hour’s walk higher up.`)],checks:[D(`Strength (Athletics)`,`medium`,T(`Heltene finder de gamle kramper bag isen og klatrer op i god orden; den, der står øverst, kan holde de andre i rebet, når angrebet kommer.`,`The heroes find the old irons behind the ice and climb in good order; whoever is highest can hold the others on the rope when the attack comes.`),T(`Isen brækker under en helt, der bliver hængende i rebet over afgrunden, og angrebet kommer, mens de andre hiver vedkommende op.`,`The ice breaks under a hero, who is left dangling on the rope over the drop, and the attack comes while the others haul their companion up.`)),D(`Wisdom (Perception)`,`easy`,T(`Heltene ser bevægelsen på isen i tide og tager imod angrebet på en hylde ved foden af isfaldet med ryggen mod klippen.`,`The heroes spot the movement on the ice in time and meet the attack on a ledge at the foot of the frozen falls, backs to the rock.`),T(`Angrebet kommer ovenfra, mens heltene er midt på isen, og de må kæmpe hængende i rebet.`,`The attack comes from above while the heroes are halfway up the ice, and they must fight hanging on the rope.`))],fight:!0,alternatives:[T(`Betal for kurven: {villain}s karle sender kurven over for den, der betaler, og heltene undgår isfaldet; men {villain} tager imod dem ved spillet, smiler og ved nu præcis, hvem der er kommet.`,`Pay for the basket: {villain}’s hands send it across for anyone who pays, and the heroes avoid the frozen falls; but {villain} meets them at the windlass, smiles and now knows exactly who has come.`),T(`Lok dem væk med lys eller larm ved broens ankerstolper, og klatr, mens de leder.`,`Lure the hunters away with light or noise at the bridge’s anchor posts, and climb while they search.`)],dmNotes:T(`Kampen foregår på is og i reb: Den, der står stille, glider, og den, der falder, hænger. Lad spillerne mærke, at hvert minut her er et minut, hvor de rejsende sidder uden brænde.`,`The fight takes place on ice and on ropes: whoever stands still slips, and whoever falls hangs. Let the players feel that every minute here is a minute the travellers sit without firewood.`)},{kind:`social`,at:`site`,present:[`npc2`],title:T(`Herberget på passet`,`The Hospice in the Pass`),summary:T([`Øverst i passet ligger herberget, et lavt stenhus fuldt af sultne, frysende rejsende, der har solgt alt, hvad de ejede, til {villain} for brød og brænde.`,`{npc2}, karlen, står bag disken og sælger {villain}s brød efter prissedlen, men ser ikke nogen i øjnene; i brændeskuret bag huset ligger reservetovene til broen, gemt under en presenning.`,`Her skal heltene vinde de rejsendes tillid, finde tovene og få alle klar til at gå ned, før stormen rammer.`],[`At the top of the pass stands the hospice, a low stone house full of hungry, freezing travellers who have sold everything they owned to {villain} for bread and firewood.`,`{npc2}, the hired hand, stands behind the counter selling {villain}’s bread at the posted prices, but looks no one in the eye; in the woodshed behind the house the spare ropes for the bridge lie hidden under a tarpaulin.`,`Here the heroes must win the travellers’ trust, find the ropes and get everyone ready to go down before the storm hits.`]),readAloud:T([`Herbergets skænkestue er fuld af mennesker, der sidder tæt omkring en ild, der er for lille, og børn, der sover i deres forældres kapper.`,`Bag disken står en karl med et brød i hånden, og på væggen bagved er en prisseddel slået op med søm.`,`Da døren går op, og sneen fyger ind, vender alle sig mod jer, og et øjeblik er der helt stille.`],[`The hospice’s common room is full of people huddled around a fire that is too small, and children asleep in their parents’ cloaks.`,`Behind the counter stands a hired hand holding a loaf, and on the wall behind it a price notice is nailed up.`,`As the door opens and the snow blows in, everyone turns toward you, and for a moment the room is silent.`]),details:[T(`Over tyve rejsende sidder her: muldrivere, saltkøbmænd og en familie af pilgrimme, de fleste uden en mønt tilbage. Brændet rækker til i aften og brødet til i morgen, og hver dag har {villain} hævet prisen. Er {npc1} med, rejser karavanens folk sig og omfavner muldriveren; ellers tror de, at {npc1} er flygtet med deres fælles sølv.`,`More than twenty travellers are stranded here: muleteers, salt merchants and a family of pilgrims, most of them without a coin left. The firewood will last until tonight and the bread until tomorrow, and every day {villain} has raised the price. If {npc1} is along, the caravan folk rise and embrace the muleteer; otherwise they believe {npc1} has run off with their shared silver.`),T(`{npc2} holdt lygten for {villain}, da broens tove blev skåret over i stormnatten, og har ikke sovet siden. I karlens forklæde ligger {villain}s seddel med ordrer for aftenen; stillet over for sedlen eller de afskårne tove bryder {npc2} sammen, tilstår og fortæller, at {villain} vil krydse som den sidste med pengekisten ved mørkets frembrud og skære linen over bag sig.`,`{npc2} held the lantern for {villain} when the bridge ropes were cut on the night of the storm, and has not slept since. In the hired hand’s apron is {villain}’s note with orders for the evening; faced with the note or the cut ropes, {npc2} breaks down, confesses and reveals that {villain} means to cross last with the strongbox at nightfall and cut the line behind them.`),T(`I brændeskuret bag herberget ligger fire ruller nyt tjæret tov under en presenning, med rebslagerbanens mærke på hver rulle. Med dem kan heltene slå en smal overgang over kløften ved brohovedet, et tov at gå på og to at holde i, hvis nogen kan få den første ende over; med {npc3} eller en dygtig hånd tager det en time. Fra herberget er der en halv times gang ned til brohovedet.`,`In the woodshed behind the hospice lie four coils of new tarred rope under a tarpaulin, the ropewalk’s mark on every coil. With them the heroes can rig a narrow crossing over the gorge at the bridgehead, one rope to walk on and two to hold, if someone can get the first end across; with {npc3} or a skilled hand it takes an hour. From the hospice it is half an hour’s walk down to the bridgehead.`)],checks:[D(`Charisma (Persuasion)`,`medium`,T(`De rejsende stoler på heltene og gør sig klar til at gå ned sammen, de svageste forrest og de stærkeste bagerst med børnene på ryggen.`,`The travellers trust the heroes and make ready to go down together, the weakest in front and the strongest at the back with the children on their backs.`),T(`De rejsende tør ikke gå ud i sneen på fremmedes ord; heltene må vise dem tovene eller få {npc2} til at tale, og det koster en halv time.`,`The travellers dare not go out into the snow on the word of strangers; the heroes must show them the spare ropes or get {npc2} to talk, which costs half an hour.`)),D(`Wisdom (Insight)`,`easy`,T(`Heltene ser, at {npc2} skammer sig over noget værre end priserne; et roligt ord får karlen til at række sedlen frem og fortælle om stormnatten.`,`The heroes see that {npc2} is ashamed of something worse than the prices; a calm word gets the hired hand to give up the note and tell of the night of the storm.`),T(`{npc2} gemmer sig i køkkenet; heltene må selv finde sedlen i forklædet på krogen, og det koster en halv time.`,`{npc2} hides in the kitchen; the heroes must find the note in the apron on its hook themselves, which costs half an hour.`))],fight:!1,alternatives:[T(`Del herbergets forråd ud: Bryder heltene forrådskammeret op og deler brød og brænde ud, får de rejsende kræfter til turen ned, men karlene løber ned til {villain} med nyheden.`,`Share out the hospice stores: if the heroes break open the storeroom and hand out bread and firewood, the travellers find the strength for the way down, but the hired hands run down to {villain} with the news.`),T(`Lad de svageste blive på herberget med {npc2} og alt brændet: Resten kommer hurtigere ned, men nogen må gå op efter dem, når stormen er ovre.`,`Leave the weakest at the hospice with {npc2} and all the firewood: the rest get down faster, but someone must go back up for them once the storm is over.`)],dmNotes:T(`Herberget er eventyrets hjerte: Giv de rejsende ansigter, en gammel pilgrim, der deler sit sidste brød, et barn, der spørger, om heltene har en bro med. Spillerne skal mærke, hvad {villain}s priser koster, før de møder {villain}.`,`The hospice is the heart of the adventure: give the travellers faces, such as an old pilgrim sharing a last loaf or a child asking whether the heroes have brought a bridge. The players should feel what {villain}’s prices cost before they meet {villain}.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:T(`Kurvelinen over kløften`,`The Basket Line over the Gorge`),summary:T([`Ved brohovedet på herbergets side af kløften står kurvelinens spil, og her sidder {villain} med to karle og pengekisten og sælger de sidste ture over, mens stormen kommer; i det gamle tårn lige ved siden af har {boss} og nogle {foe} deres vinterhule.`,`Ved mørkets frembrud vil {villain} krydse som den sidste og skære linen over bag sig, og når de rejsende samles ved brohovedet, kommer {boss} og de andre ud af tårnet og angriber alle ved kløften, også {villain}.`,`Heltene skal få alle de rejsende over kløften, i kurven eller på et nyt tov, standse {villain} og overleve stormen.`],[`At the bridgehead on the hospice side of the gorge stands the windlass of the basket line, and here {villain} sits with two hired hands and the strongbox, selling the last crossings as the storm comes on; in the old tower right beside it {boss} and some {foe} have their winter lair.`,`At nightfall {villain} means to cross last and cut the line behind them, and when the travellers gather at the bridgehead, {boss} and the others come out of the tower and attack everyone at the gorge, {villain} included.`,`The heroes must get every traveller across the gorge, in the basket or on a new rope, stop {villain} and survive the storm.`]),readAloud:T([`Ved kanten af kløften knirker et stort træspil, og linen forsvinder ud i sneen mod den anden side.`,`Ved spillet sidder en velklædt skikkelse i en pelskåbe på en jernbeslået kiste og tæller mønter i skæret fra en lygte, mens to karle holder i håndtagene.`,`Bag dem rejser et gammelt tårn sig uden tag, og fra den sorte døråbning kommer en lyd, der får karlene til at se sig over skulderen.`],[`At the edge of the gorge a great wooden windlass creaks, and the line vanishes into the snow toward the far side.`,`At the windlass a well-dressed figure in a fur cloak sits on an iron-bound chest, counting coins by the light of a lantern while two hired hands hold the cranks.`,`Behind them rises an old roofless tower, and from its black doorway comes a sound that makes the hands glance over their shoulders.`]),details:[T(`{boss} og nogle {foe} har deres vinterhule i det gamle tårn og har levet af herbergets muldyr, siden broen faldt. De tjener ikke {villain}, der kun tør sidde ved spillet, fordi lygten og karlene holder dem væk om dagen; ved mørkets frembrud, eller når de rejsende samles ved brohovedet, kommer de ud. Karlene løber, så snart {boss} viser sig.`,`{boss} and some {foe} have their winter lair in the old tower and have lived off the hospice’s mules since the bridge fell. They do not serve {villain}, who dares sit at the windlass only because the lantern and the hired hands keep them off by day; at nightfall, or when the travellers gather at the bridgehead, they come out. The hired hands run as soon as {boss} appears.`),T(`Kurven kan bære én voksen ad gangen, og hver tur tager ti minutter i stormen. Rider en helt over i kurven med enden af et reservetov, kan heltene slå en smal overgang ved siden af linen, og så kan de rejsende gå over to ad gangen med hænderne på tovet. Ved mørkets frembrud (tredje tik) vil {villain} hejse pengekisten over, krydse selv og skære linen over fra den anden side.`,`The basket can carry one adult at a time, and each crossing takes ten minutes in the storm. If a hero rides across in the basket with the end of a spare rope, the heroes can rig a narrow crossing beside the line, and then the travellers can cross two at a time with their hands on the rope. At nightfall (the third tick) {villain} means to haul the strongbox across, cross in person and cut the line from the far side.`),T(`Står {villain} over for de afskårne tove, sedlen til {npc2} eller ordrebogen fra rebslagerbanen, er der intet at vinde ved at skære linen over, og {villain} vil forhandle: om penge, om de rejsendes ejendele og om at slippe for rådet. Truet af {boss} eller af heltene forsøger {villain} at flygte over i kurven, men vil ikke efterlade kisten.`,`Faced with the cut ropes, the note to {npc2} or the order book from the ropewalk, {villain} has nothing to gain by cutting the line and will bargain: over money, over the travellers’ belongings and over escaping the council. Threatened by {boss} or by the heroes, {villain} tries to flee across in the basket, but will not leave the chest behind.`)],checks:[D(`Strength (Athletics)`,`medium`,T(`Heltene holder spillet, mens {boss} og de andre angriber, og kurven går over og tilbage, til alle rejsende er på den anden side.`,`The heroes hold the windlass while {boss} and the others attack, and the basket goes across and back until every traveller is on the far side.`),T(`Spillet glider, og kurven hænger stille midt over kløften med en rejsende i; heltene må kæmpe sig hen til håndtagene, før vinden river kurven løs.`,`The windlass slips, and the basket hangs still in the middle of the gorge with a traveller in it; the heroes must fight their way to the cranks before the wind tears the basket loose.`)),D(`Charisma (Intimidation)`,`medium`,T(`Med beviserne i hånden og {boss} i ryggen giver {villain} op, overgiver pengekisten og beder om at komme med over som heltenes fange.`,`Faced with the proof, and with {boss} at their back, {villain} gives up, hands over the strongbox and asks to go across as the heroes’ prisoner.`),T(`{villain} hejser kisten op i kurven og forsøger at krydse selv; heltene må holde linen, mens {boss} og de andre angriber.`,`{villain} heaves the chest into the basket and tries to cross; the heroes must hold the line while {boss} and the others attack.`))],fight:!0,alternatives:[T(`Tag spillet før mørket: Kommer heltene til brohovedet, før de rejsende er samlet, kan de tage spillet og pengekisten fra {villain} og karlene, før {boss} og de andre kommer ud af tårnet.`,`Take the windlass before dark: if the heroes reach the bridgehead before the travellers gather, they can take the windlass and the strongbox from {villain} and the hired hands before {boss} and the others come out of the tower.`),T(`Send {villain} over først: Sender heltene {villain} over i kurven uden kisten, skærer {villain} ikke linen over, så længe alt, hvad {villain} har tjent, står på denne side.`,`Send {villain} across first: if the heroes send {villain} over in the basket without the chest, {villain} will not cut the line as long as everything {villain} has earned is still on this side.`)],dmNotes:T(`Kurven er uret, alle kan se: Hver tur over kløften tager ti minutter, og for hver runde bliver sneen tættere. Husk, at målet er de rejsende, ikke {villain}; lad spillerne vælge mellem at fange {villain} og at holde spillet.`,`The basket is the clock everyone can see: each crossing takes ten minutes, and with every round the snow grows thicker. Remember that the goal is the travellers, not {villain}; let the players choose between catching {villain} and holding the windlass.`)}},Ge=e({kernel:()=>Ye,scenes:()=>Xe}),Ke=e=>Array.isArray(e)?e.join(` `):e,O=(e,t)=>({da:Ke(e),en:Ke(t)}),qe=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),k=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},Je=(e,t,n)=>({when:e,event:t,sign:n}),A=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),Ye={id:`siege-the-wreckers-light`,titles:[O(`Vragrøvernes lys`,`The Wreckers’ Light`),O(`Ilden i {place}`,`The Fire in {place}`),O(`Strandfogedens nøgle`,`The Wreck-Master’s Key`)],missions:[`siege`],foes:`people`,roles:{npc1:O(`en lods fra havnen i {town}`,`a harbour pilot of {town}`),npc2:O(`en gammel fyrpasser, der har holdt ilden i {place} i tredive år`,`an old lighthouse keeper who has kept the fire of {place} for thirty years`),npc3:O(`en gammel fisker på Kragenæsset, der står i gæld til {villain}`,`an old fisher on Crow Point who is in debt to {villain}`),villain:O(`en strandfoged, som hele kysten stoler på`,`a wreck-master the whole coast trusts`)},hook:O(`{npc1}, en lods fra havnen i {town}, finder heltene i skumringen og beder dem gå ud ad ebbevejen til {place}, før tidevandet lukker den, og holde ilden i fyret brændende til daggry, for i nat skal en rig handelskogge forbi skærene ved Tænderne.`,`{npc1}, a harbour pilot of {town}, finds the heroes at dusk and begs them to cross the causeway to {place} before the tide closes it and keep the fire of the lighthouse burning until dawn, for tonight a rich merchant cog must pass the rocks called the Teeth.`),people:{npc1:{wants:O(`Vil have koggen sikkert i havn og aldrig mere trække druknede sømænd op af stranden under Tænderne.`,`Wants the cog safe in harbour, and never again to drag drowned sailors off the beach below the Teeth.`),secret:O(`Så to nætter sidste vinter vinfade blive båret op fra stranden efter et forlis, men tav, fordi {villain} skaffede {npc1} pladsen som lods.`,`Twice last winter saw casks of wine carried up from the beach after a wreck, but kept quiet because {villain} got {npc1} the post of pilot.`)},npc2:{wants:O(`Vil holde ilden i gang til daggry, som hver nat i tredive år, og aldrig mere se et skib på Tænderne.`,`Wants to keep the fire going until dawn, as on every night for thirty years, and never again see a ship on the Teeth.`),secret:O(`Lod ilden brænde ned to nætter sidste vinter, fordi {villain} sagde, at fogeden ville fange smuglere ved Tænderne i mørke, og ved nu, at det var de nætter, skibene forliste.`,`Let the fire burn low on two nights last winter because {villain} said the reeve meant to catch smugglers at the Teeth in the dark, and knows now that those were the nights the ships were wrecked.`)},npc3:{wants:O(`Vil beholde sit hus på næsset og slippe for gælden til {villain} uden at få druknede sømænd på samvittigheden.`,`Wants to keep their cottage on the point and be free of the debt to {villain} without drowned sailors on their conscience.`),secret:O(`Syede selv det nye olietøj til {villain}s "redningsmandskab" og ved, at det i nat skal bæres af nogle, der aldrig har reddet et liv.`,`Sewed the new oilskins for {villain}’s "rescue crew" and knows they are to be worn tonight by a crew that has never saved a life.`)}},premise:O([`Ude på en klippeholm for enden af en ebbevej står {place}, det gamle fyr, hvis ild leder skibene forbi Tænderne, en række skær ud for {town}.`,`{villain}, kystens strandfoged, får efter den gamle strandret en tredjedel af alt, hvad havet driver i land, og leverer kullet til fyret; i fem år har {villain} i al hemmelighed ført vragrøverne og sørget for, at ilden brændte ned de nætter, hvor et rigt skib skulle forbi.`,`I nat skal en handelskogge fra syden med vin, klæde og købmændenes sølv forbi skærene i storm, og {villain} har lejet {boss} og nogle {foe} til at slukke ilden, mens en falsk lygte på Kragenæsset lokker koggen ind på Tænderne.`,`Fyrpasseren er alene derude, tidevandet lukker ebbevejen ved mørkets frembrud, og ingen fra {town} kan komme over før ved lavvande i timen før daggry.`],[`Out on a rocky islet at the end of a tidal causeway stands {place}, the old lighthouse whose fire guides ships past the Teeth, a line of rocks off {town}.`,`Under the old strand law {villain}, the coast’s wreck-master, receives a third of everything the sea drives ashore, and also delivers the lighthouse coal; for five years {villain} has secretly led the wreckers and made sure the fire burned low on the nights a rich ship was due.`,`Tonight a merchant cog from the south, loaded with wine, cloth and the merchants’ silver, must pass the rocks in a storm, and {villain} has hired {boss} and some {foe} to put out the fire while a false lantern on Crow Point lures the cog onto the Teeth.`,`The keeper is alone out there, the tide closes the causeway at nightfall and nobody from {town} can cross before low water in the hour before dawn.`]),goal:O(`Hold ilden i {place} brændende til daggry, slå vragrøvernes angreb tilbage, og afslør, hvem på land der fører dem.`,`Keep the fire of {place} burning until dawn, beat back the wreckers’ attacks and expose who on shore leads them.`),objective:{target:O(`Ilden i fyrkurven øverst i {place}, det eneste lys, der viser skibene vejen forbi Tænderne`,`The fire in the beacon basket at the top of {place}, the only light that shows ships the way past the Teeth`),state:O([`Ilden brænder, men kullet i kulskuret i fyrgården er alt, hvad der er til daggry, og {villain} har en nøgle til tårndøren som den, der leverer kullet.`,`På Kragenæsset står en falsk lygte klar, og {boss} og resten af vragrøverne venter i klitterne ved den anden ende af ebbevejen på lavvande.`],[`The fire burns, but the coal in the coal shed in the yard is all there is until dawn, and {villain}, who delivers the coal, holds a key to the tower door.`,`On Crow Point a false lantern stands ready, and {boss} and the rest of the wreckers wait in the dunes at the far end of the causeway for low water.`]),resolution:O([`Hold kulskuret og tårnet, og hold ilden i gang, til koggen er forbi Tænderne ved daggry; læg tværbommen for tårndøren, så nøglen ikke hjælper, og vis folkene fra {town}, hvem der går i olietøjet på {villain}s ordre, så falder strandfogedens gode navn.`,`Kan heltene ikke holde det hele, må de vælge mellem kullet og døren.`],[`Hold the coal shed and the tower, and keep the fire going until the cog is past the Teeth at dawn; drop the crossbar on the tower door so the key is no use; show the people of {town} who wears the oilskins on {villain}’s orders, and the wreck-master’s good name is gone.`,`If the heroes cannot hold it all, they must choose between the coal and the door.`])},villain:{want:O(`At få sin tredjedel af koggens last efter loven og vragrøvernes andel oveni, at beholde navnet som kystens redningsmand, og at ingen nogensinde lægger strandfogedens vragbog ved siden af skibenes fragtbreve.`,`To take a third of the cog’s cargo by law and the wreckers’ share besides, to keep a name as the coast’s rescuer and to make sure nobody ever lays the wreck-master’s wreck book beside the ships’ bills of lading.`),plan:O([`Først sendte {villain} fyrpasseren en krukke stærk vin "til stormnatten" med sovedrik i, så ilden blev tændt for sent, og fik {npc3} til at rejse en falsk lygte på Kragenæsset, der fra havet ligner fyret.`,`Ved mørkets frembrud går nogle {foe} i land på holmen for at få kullet i havet og slå tårndøren ind, og ved midnat bliver den falske lygte tændt.`,`I timen før daggry, når ebbevejen er tør, kommer {villain} selv over med {boss} og resten i redningsmandskabets olietøj, låser tårndøren op med sin egen nøgle og slukker ilden, netop som koggen skal forbi Tænderne.`],[`First {villain} sent the keeper a jar of strong wine "for the storm night" with a sleeping draught in it, so that the fire would be lit too late, and had {npc3} raise a false lantern on Crow Point that looks like the lighthouse from the sea.`,`At nightfall some {foe} land on the islet to get the coal into the sea and break down the tower door, and at midnight the false lantern is lit.`,`In the hour before dawn, when the causeway runs dry, {villain} crosses in person with {boss} and the rest in the rescue crew’s oilskins, unlocks the tower door with the wreck-master’s own key and puts out the fire just as the cog must pass the Teeth.`]),weakness:O([`{villain} er ingen kriger og har brug for, at døren bliver åbnet, og at navnet holder; vragrøverne følger kun strandfogeden for deres andel, og en tværbom for døren gør nøglen værdiløs.`,`Og olietøjet skjuler kun noget i mørke: Står {villain} ved daggry blandt vragrøverne foran folkene fra {town}, eller bliver strandkontorets messingmærker fundet hos dem, er strandfogeden færdig.`],[`{villain} is no fighter and needs the door opened and their good name intact; the wreckers follow the wreck-master only for their share, and a crossbar on the door makes the key worthless.`,`And the oilskins are a disguise only in the dark: if {villain} stands among the wreckers at dawn in front of the people of {town}, or the strand office’s brass tokens are found on them, the wreck-master is finished.`])},stakes:O(`Går ilden ud, mens koggen er ud for Tænderne, styrer den efter den falske lygte og går på skærene: Tyve sømænd drukner, lasten forsvinder i {villain}s kældre, fyrpasseren får skylden for det slukkede lys, og om morgenen leder {villain} redningen og bliver hyldet for det.`,`If the fire goes out while the cog is off the Teeth, the cog steers for the false lantern and strikes the rocks: twenty sailors drown, the cargo vanishes into {villain}’s cellars and the keeper is blamed for letting the light go out. In the morning {villain} leads the rescue and is praised for it.`),clock:{start:O(`Skumring. Fra lodshuset i {town} ser {npc1}, at ilden i {place} er tændt for sent og brænder svagt, og at fyrpasserens røde lygte hænger ud fra galleriet: et nødsignal. Stormen tager til, koggen er set i det sidste dagslys, og om to timer, ved mørkets frembrud, lukker tidevandet ebbevejen til næste lavvande i timen før daggry.`,`Dusk. From the pilot house in {town}, {npc1} sees that the fire of {place} was lit too late and burns weakly, and that the keeper’s red lantern hangs from the gallery: a call for help. The storm is rising and the cog was sighted in the last of the daylight; in two hours, at nightfall, the tide closes the causeway until the next low water in the hour before dawn.`),ticks:[Je(O(`Efter 2 timer (ved mørkets frembrud)`,`After 2 hours (at nightfall)`),O(`Første angreb: Nogle {foe} går i land ved holmens bådebro og går løs på kulskuret i fyrgården med økser og spande for at få kullet i havet, mens andre hamrer på tårndøren.`,`The first assault: some {foe} land at the islet’s jetty and go for the coal shed in the yard with axes and buckets to get the coal into the sea, while others hammer on the tower door.`),O(`Bådlygter på det sorte vand og så økseslag mod kulskurets dør i blæsten.`,`Boat lanterns on the black water, then axe blows against the coal shed door in the wind.`)),Je(O(`Efter 6 timer (ved midnat, ved højvande)`,`After 6 hours (at midnight, at high water)`),O(`Den falske lygte på Kragenæsset bliver tændt, og fra havet ligner den nu ilden i {place}; i klitterne ved ebbevejen samler {villain} sit "redningsmandskab". Har heltene fældet masten, er det et bål; har {npc3} lovet dem at lade lygten være, forbliver næsset mørkt.`,`The false lantern on Crow Point is lit, and from the sea it now looks just like the fire of {place}; in the dunes by the causeway {villain} gathers the "rescue crew". If the heroes felled the mast, it is a bonfire; if {npc3} promised to leave the lantern unlit, the point stays dark.`),O(`Et nyt lys blusser op mod syd, lige så højt som fyrets eget, og langt ude ses koggens lanterne vende.`,`A new light flares up to the south, as high as the lighthouse’s own, and far out the cog’s lantern can be seen turning.`)),Je(O(`Efter 9 timer (i timen før daggry, ved lavvande)`,`After 9 hours (in the hour before dawn, at low water)`),O(`{villain} kommer over den tørre ebbevej med {boss} og resten af vragrøverne i olietøj, kalder på fyrpasseren ved tårndøren og stikker nøglen i låsen, netop som koggen skal forbi Tænderne.`,`{villain} crosses the dry causeway with {boss} and the rest of the wreckers in oilskins, calls for the keeper at the tower door and puts the key in the lock, just as the cog must pass the Teeth.`),O(`En række lygter bevæger sig ud ad den dryppende ebbevej, og en velkendt stemme råber, at hjælpen fra {town} er kommet.`,`A line of lanterns moves out along the dripping causeway, and a well-known voice calls out that help has come from {town}.`))],deadline:O(`Efter 9 timer, i timen før daggry, er koggen ud for Tænderne: Er ilden i {place} slukket da, styrer koggen efter den falske lygte og går på skærene. Ved daggry en time senere kan folkene fra {town} komme over ebbevejen, men så er det for sent.`,`After 9 hours, in the hour before dawn, the cog is off the Teeth: if the fire of {place} is out then, the cog steers for the false lantern and strikes the rocks. At dawn an hour later the people of {town} can cross the causeway, but by then it is too late.`)},clues:{who:[k(`town`,O(`I lodshuset ved havnen i {town} viser {npc1} fragtbrevet fra "De tre søstre", der forliste på Tænderne sidste vinter: fyrre fade vin om bord, men i {villain}s vragbog står der kun seks fade bjærget.`,`In the pilot house by the harbour in {town}, {npc1} shows the bill of lading of the "Three Sisters", wrecked on the Teeth last winter: forty casks of wine aboard, but {villain}’s wreck book lists only six casks salvaged.`),O(`{villain} skriver mindre i vragbogen, end havet giver, og sælger resten i al hemmelighed; strandfogeden tjener på forlisene.`,`{villain} records less in the wreck book than the sea gives up and sells the rest in secret; the wreck-master profits from the wrecks.`),qe([`Fragtbrev, "De tre søstre", fra syden til {town}:`,`Fyrre fade rødvin, tolv baller klæde, en kiste med købmændenes sølv.`,`Strandfogedens vragbog, samme nat: seks fade vin bjærget, resten tabt i havet. – {villain}`],[`Bill of lading, the "Three Sisters", from the south to {town}:`,`Forty casks of red wine, twelve bales of cloth, one chest of the merchants’ silver.`,`The wreck-master’s wreck book, the same night: six casks of wine salvaged, the rest lost at sea. — {villain}`])),k(`town`,O(`På Kragenæsset indrømmer {npc3}, den gamle fisker, at {villain} har eftergivet gælden mod, at lygten bliver tændt ved midnat og passet til daggry.`,`On Crow Point, {npc3}, the old fisher, admits that {villain} has forgiven the debt in return for the lantern being lit at midnight and tended until dawn.`),O(`Den falske lygte er {villain}s værk: Strandfogeden vil have koggen ind på Tænderne.`,`The false lantern is {villain}’s doing: the wreck-master wants the cog on the Teeth.`)),k(`site`,O(`Efter angrebet på kulskuret ligger der hos de faldne angribere blanke messingmærker med strandkontorets anker, den slags {villain} betaler bjærgningsfolk med.`,`After the assault on the coal shed, the fallen attackers carry bright brass tokens stamped with the anchor of the strand office, the kind {villain} pays salvage crews with.`),O(`Vragrøverne bliver betalt fra strandfogedens eget kontor.`,`The wreckers are paid from the wreck-master’s own office.`)),k(`site`,O(`I fyrpasserens kammer under fyrkurven står en stenkrukke med stærk vin, sendt "med strandfogedens hilsen til stormnatten"; bundfaldet lugter af valmue, og {npc2} sov fra eftermiddagen til skumringen efter et enkelt bæger.`,`In the keeper’s room below the beacon stands a stone jar of strong wine, sent "with the wreck-master’s compliments for the storm night"; the dregs smell of poppy, and {npc2} slept from the afternoon until dusk after a single cup.`),O(`{villain} ville have fyrpasseren til at sove i nat, så ilden blev tændt for sent.`,`{villain} wanted the keeper asleep tonight so that the fire would be lit too late.`),qe([`Til fyrpasseren på {place}:`,`En krukke af den gode til stormnatten. Drik den varm, og sov godt; kullet kommer, som det plejer.`,`Med strandfogedens hilsen. – {villain}`],[`To the keeper of {place}:`,`A jar of the good stuff for the storm night. Drink it warm and sleep well; the coal will come as it always does.`,`With the wreck-master’s compliments. — {villain}`]))],where:[k(`town`,O(`I lodshuset ved havnen hænger {npc1}s tidevandstavle: Ebbevejen til {place} står under vand fra mørkets frembrud til timen før daggry, og netop da skal koggen forbi Tænderne.`,`In the pilot house by the harbour hangs {npc1}’s tide board: the causeway to {place} is under water from nightfall until the hour before dawn, and that is just when the cog must pass the Teeth.`),O(`Det afgørende angreb kommer over ebbevejen i timen før daggry, når den er tør, og samtidig med at koggen er ud for skærene.`,`The decisive attack will come over the causeway in the hour before dawn, when it runs dry, at the very moment the cog is off the rocks.`),qe([`Tidevand ved {town}, i nat:`,`Ebbevejen til fyret lukker ved mørkets frembrud.`,`Lavvande og tør vej igen i timen før daggry.`,`Kogge ventet forbi Tænderne ved samme tid. Hold ilden høj.`],[`Tides at {town}, tonight:`,`The causeway to the lighthouse closes at nightfall.`,`Low water and a dry way again in the hour before dawn.`,`Cog expected past the Teeth at the same time. Keep the fire high.`])),k(`town`,O(`På Kragenæsset står en ny lygtemast, lige så høj som fyret set fra havet, og ved foden ligger en stak nyt olietøj af den slags, redningsmandskabet i {town} bærer.`,`On Crow Point stands a new lantern mast, as tall as the lighthouse when seen from the sea, and at its foot lies a pile of new oilskins of the kind the rescue crew of {town} wears.`),O(`Den falske lygte skal tage fyrets plads, og vragrøverne vil komme forklædt som redningsmandskabet, som ingen ville lukke døren for.`,`The false lantern is meant to take the lighthouse’s place, and the wreckers mean to come disguised as the rescue crew, whom nobody would shut the door on.`)),k(`site`,O(`Efter angrebet på kulskuret hænger døren flækket, og tre sække kul er væk i havet; resten rækker til daggry, men kun hvis ikke én sæk mere går tabt.`,`After the assault on the coal shed its door hangs split, and three sacks of coal have gone into the sea; what is left will last until dawn, but only if not one more sack is lost.`),O(`Vragrøverne vil sulte ilden: Uden kullet i kulskuret går den ud længe før daggry.`,`The wreckers mean to starve the fire: without the coal in the shed it goes out long before dawn.`)),k(`site`,O(`Fra galleriet ved fyrkurven ser {npc2} ved midnat det nye lys på næsset og fortæller, at tårndøren har to nøgler: fyrpasserens og den, {villain} bruger, når kullet bliver leveret.`,`From the gallery by the beacon at midnight, {npc2} sees the new light on the point and explains that the tower door has two keys: the keeper’s, and the one {villain} uses when the coal is delivered.`),O(`Det sidste angreb kommer ikke over muren, men gennem tårndøren, med {villain}s egen nøgle.`,`The last attack will not come over the wall but through the tower door, with {villain}’s own key.`))]},endings:{success:O(`Ilden brænder til daggry, og koggen runder Tænderne i det første grå lys og går ind i havnen i {town}. Ved lavvande kommer folkene fra {town} over ebbevejen og finder vragrøverne i redningsmandskabets olietøj med strandkontorets mærker i lommerne, og {villain} bliver ført bort i lænker. Købmændene fra koggen beder heltene blive, til vragbogen er gået igennem, og de første fade vin fra "De tre søstre" dukker op i strandfogedens kældre.`,`The fire burns until dawn, and the cog rounds the Teeth in the first grey light and comes into harbour at {town}. At low water the people of {town} cross the causeway and find the wreckers in the rescue crew’s oilskins with the strand office’s tokens in their pockets, and {villain} is led away in chains. The merchants from the cog ask the heroes to stay until the wreck book has been gone through, and the first casks of wine from the "Three Sisters" turn up in the wreck-master’s cellars.`),partial:O(`Ilden blafrer og går ud et øjeblik, og koggen skraber Tænderne og går på grund på sandet indenfor, men besætningen kommer i land i live. {villain} slipper væk over ebbevejen i mørket og videre med en båd, og selv om alle nu ved, hvem der førte vragrøverne, ligger koggens sølv på bunden, og strandfogeden er et sted langs kysten med vragbogen under armen.`,`The fire flickers and goes out for a moment, and the cog scrapes the Teeth and runs aground on the sand inside them, but the crew get ashore alive. {villain} escapes over the causeway in the dark and away by boat, and although everyone now knows who led the wreckers, the cog’s silver lies on the bottom, and the wreck-master is somewhere along the coast with the wreck book under one arm.`),failure:O(`I timen før daggry går ilden i {place} ud, og koggen styrer efter lygten på Kragenæsset (eller sejler blindt, hvis næsset var mørkt) og går på Tænderne. Ved daggry leder {villain} redningen fra stranden, skriver lasten ind i vragbogen som tabt i havet og giver fyrpasseren skylden for det slukkede lys, og i {town} bliver strandfogeden hyldet for at have trukket de sidste sømænd op af bølgerne.`,`In the hour before dawn the fire of {place} goes out, and the cog steers for the lantern on Crow Point (or sails blind, if the point was dark) and strikes the Teeth. At dawn {villain} leads the rescue from the beach, enters the cargo in the wreck book as lost at sea and blames the keeper for letting the light go out, and in {town} the wreck-master is praised for pulling the last sailors out of the waves.`)}},Xe={opening:{kind:`opening`,at:`town`,present:[`npc1`],title:O(`Lodshuset ved havnen`,`The Pilot House by the Harbour`),summary:O([`I skumringen står {npc1}, en lods fra havnen i {town}, i døren til lodshuset og ser ud mod {place}, det gamle fyr på klippeholmen for enden af ebbevejen: Ilden blev tændt for sent, den brænder svagt, og fyrpasserens røde lygte hænger ud fra galleriet.`,`En rig handelskogge er set i det sidste dagslys og skal forbi Tænderne i nat, og om to timer lukker tidevandet ebbevejen til timen før daggry.`,`{npc1} beder heltene gå derud og holde ilden i gang natten igennem; ved havnen kan de få et par svar mere, men hver samtale koster tid.`],[`At dusk {npc1}, a harbour pilot of {town}, stands in the doorway of the pilot house looking out at {place}, the old lighthouse on the rocky islet at the end of the causeway: the fire was lit too late and burns weakly, and the keeper’s red lantern hangs from the gallery.`,`A rich merchant cog was sighted in the last of the daylight and must pass the Teeth tonight, and in two hours the tide closes the causeway until the hour before dawn.`,`{npc1} begs the heroes to go out there and keep the fire going through the night; at the harbour they can get a few more answers, but every conversation costs time.`]),readAloud:O([`Blæsten river skum af bølgerne i havnen, og fiskerbådene rykker i fortøjningerne.`,`Ude for enden af den lange, våde ebbevej står fyret på sin klippeholm, og ilden i toppen blafrer lavt og gult, hvor den burde stå højt og hvidt.`,`Under ilden hænger en lille rød lygte og svinger i stormen.`],[`The wind tears foam off the waves in the harbour, and the fishing boats jerk at their moorings.`,`Out at the end of the long, wet causeway the lighthouse stands on its rocky islet, and the fire at the top flickers low and yellow where it should burn high and white.`,`Below the fire a small red lantern hangs, swinging in the storm.`]),details:[O(`{npc1} forklarer: Den røde lygte betyder, at fyrpasseren er i nød. Kullet til fyret leverer {villain}, strandfogeden, der også fører redningsmandskabet og efter strandretten får en tredjedel af alt, hvad havet driver i land. {villain} er ude langs stranden med redningsfolkene i aften, "som altid i storm".`,`{npc1} explains: the red lantern means the keeper is in trouble. The lighthouse coal is delivered by {villain}, the wreck-master, who also leads the rescue crew and by strand law receives a third of everything the sea drives ashore. {villain} is out along the beach with the rescue crew tonight, "as always in a storm".`),O(`I lodshuset ligger fragtbrevet fra "De tre søstre", der forliste på Tænderne sidste vinter; {npc1} skulle have ført skibet ind og har aldrig forstået, hvorfor vragbogen nævner så lidt. Det tager en halv time at få {npc1} til at tale om det, og at gennemgå tidevandstavlen tager lige så lang tid.`,`In the pilot house lies the bill of lading of the "Three Sisters", wrecked on the Teeth last winter; {npc1} was to have brought that ship in and has never understood why the wreck book mentions so little. Getting {npc1} to talk about it takes half an hour, and going through the tide board takes as long.`),O(`Kystvejen til ebbevejen går forbi Kragenæsset, hvor der i dag er rejst en ny mast; et ophold dér koster en halv time. Går heltene straks, er de på holmen lige før det første angreb; kommer de sent, må de vade det sidste stykke i stigende vand og kommer frem midt i angrebet.`,`The coast road to the causeway passes Crow Point, where a new mast was raised today; a stop there costs half an hour. If the heroes go at once, they reach the islet just before the first assault; if they come late, they must wade the last stretch in rising water and arrive in the middle of it.`)],checks:[A(`Wisdom (Insight)`,`medium`,O(`{npc1} holder noget tilbage, og da heltene siger det højt, kommer det: To nætter sidste vinter så lodsen vinfade blive båret op fra stranden efter et forlis, og fragtbrevet fra "De tre søstre" passer ikke med vragbogen.`,`{npc1} is holding something back, and when the heroes say so, it comes out: on two nights last winter the pilot saw casks of wine carried up from the beach after a wreck, and the bill of lading of the "Three Sisters" does not match the wreck book.`),O(`{npc1} taler kun om koggen og stormen; heltene hører intet om de gamle forlis.`,`{npc1} talks only of the cog and the storm; the heroes hear nothing of the old wrecks.`)),A(`Intelligence (Nature)`,`easy`,O(`Heltene læser tidevandstavlen rigtigt: Ebbevejen er tør igen i timen før daggry, netop når koggen skal forbi Tænderne, og den, der vil slukke ilden, kommer da.`,`The heroes read the tide board correctly: the causeway runs dry again in the hour before dawn, just when the cog must pass the Teeth, and whoever means to put out the fire will come then.`),O(`Heltene ved kun, at ebbevejen lukker ved mørkets frembrud; at den åbner igen før daggry, går dem forbi.`,`The heroes know only that the causeway closes at nightfall; that it opens again before dawn escapes them.`))],fight:!1,alternatives:[O(`Gå straks: Heltene når holmen før det første angreb og kan hjælpe fyrpasseren med at gøre klar, men ved intet om de gamle forlis eller tidevandet.`,`Go at once: the heroes reach the islet before the first assault and can help the keeper get ready, but know nothing about the old wrecks or the tide.`),O(`Lån {npc1}s båd: Over havnen og uden om næsset tager det en halv time mere i stormen, men heltene kommer til holmen fra havsiden, uset, og ser de bådlygter, der venter i læ af skærene.`,`Borrow {npc1}’s boat: across the harbour and round the point it takes half an hour longer in the storm, but the heroes come to the islet from the sea side, unseen, and see the boat lanterns waiting in the lee of the rocks.`)],dmNotes:O(`Lad spillerne høre om {villain} gennem {npc1}: den modige strandfoged, der altid er først på stranden, når et skib går på. Sig højt, hvad hvert svar koster, og lad den røde lygte svinge, mens de tøver.`,`Let the players hear of {villain} through {npc1}: the brave wreck-master who is always first on the beach when a ship goes aground. Say aloud what each answer costs, and let the red lantern swing while they hesitate.`)},middle:[{kind:`exploration`,at:`town`,present:[`npc3`],title:O(`Lygten på Kragenæsset`,`The Lantern on Crow Point`),summary:O([`Kystvejen ud til ebbevejen går forbi Kragenæsset, en lav pynt syd for fyret, hvor der i dag er rejst en ny mast med en lygte i toppen, lige så høj som fyret set fra havet.`,`{npc3}, en gammel fisker, der står i gæld til {villain}, er ved at fylde olie på lygten og skal tænde den ved midnat.`,`Her kan heltene se, hvordan koggen skal lokkes ind på Tænderne, og måske få fiskeren til at sige, hvem der betaler.`],[`The coast road out to the causeway passes Crow Point, a low headland south of the lighthouse, where a new mast with a lantern at the top was raised today, as tall as the lighthouse when seen from the sea.`,`{npc3}, an old fisher who is in debt to {villain}, is filling the lantern with oil and is to light it at midnight.`,`Here the heroes can see how the cog is to be lured onto the Teeth, and perhaps get the fisher to say who is paying.`]),readAloud:O([`Pynten er nøgen og fuld af tang, og bølgerne brydes hvide på skærene lige ud for den.`,`Midt på næsset står en ny, tjæret mast med en stor lygte i toppen, og derfra kan man se fyret mod nord og havnen bag det.`,`En gammel fisker står på en stige med en oliekande og stivner, da heltene kommer.`],[`The headland is bare and strewn with weed, and the waves break white on the rocks just off it.`,`In the middle of the point stands a new, tarred mast with a great lantern at the top, and from here you can see the lighthouse to the north, with the harbour behind it.`,`An old fisher stands on a ladder with an oil can and freezes as you arrive.`]),details:[O(`Set fra havet står lygten på Kragenæsset lige dér, hvor fyret burde være, når man kommer sydfra; en skipper, der mister fyret af syne og ser lygten i stedet, styrer lige ind på Tænderne. Ved masten ligger en stak nyt olietøj af den slags, redningsmandskabet i {town} bærer, og en rulle reb fra redningsbåden.`,`Seen from the sea, the lantern on Crow Point stands just where the lighthouse should be for a ship coming from the south; a skipper who loses sight of the lighthouse and sees the lantern instead steers straight onto the Teeth. By the mast lies a pile of new oilskins of the kind the rescue crew of {town} wears, and a coil of rope from the rescue boat.`),O(`{npc3} har fået gælden til {villain} eftergivet mod at tænde lygten ved midnat og passe den til daggry. Fiskeren syede selv olietøjet på strandfogedens ordre og ved, at det ikke skal bæres af redningsfolk. {npc3} er bange og skamfuld og har aldrig før set et skib gå på skærene uden at gå ned på stranden for at hjælpe.`,`{npc3} has had the debt to {villain} forgiven in return for lighting the lantern at midnight and tending it until dawn. The fisher sewed the oilskins on the wreck-master’s orders and knows they are not meant for any rescue crew. {npc3} is frightened and ashamed, and has never before seen a ship strike the rocks without going down to the beach to help.`),O(`Ødelægger heltene lygten, tænder vragrøverne i stedet et bål på næsset ved midnat; det er svagere og lettere at skelne fra fyret, og en opmærksom skipper bliver højst narret af det i en time. Hvert ophold på næsset koster tid, og ebbevejen lukker ved mørkets frembrud.`,`If the heroes destroy the lantern, the wreckers light a bonfire on the point at midnight instead; it is weaker and easier to tell from the lighthouse, and a watchful skipper is fooled by it for an hour at most. Every stop on the point costs time, and the causeway closes at nightfall.`)],checks:[A(`Charisma (Persuasion)`,`medium`,O(`{npc3} fortæller alt: gælden, lygten ved midnat og olietøjet til {villain}s "redningsmandskab", der skal over ebbevejen i timen før daggry. Fiskeren lover at lade lygten være slukket.`,`{npc3} tells everything: the debt, the lantern at midnight and the oilskins for {villain}’s "rescue crew", who are to cross the causeway in the hour before dawn. The fisher promises to leave the lantern dark.`),O(`{npc3} tier af frygt for strandfogeden; heltene ved kun, at lygten er bestilt, ikke af hvem.`,`{npc3} keeps silent for fear of the wreck-master; the heroes know only that the lantern was ordered, not by whom.`)),A(`Intelligence (Investigation)`,`easy`,O(`Heltene ser, at lygten står præcis på linje med havneindløbet set fra Tænderne: Den er rejst for at lokke et skib på skærene og for intet andet.`,`The heroes see that the lantern stands exactly in line with the harbour mouth as seen from the Teeth: it was raised to lure a ship onto the rocks and for nothing else.`),O(`Masten kunne være et sømærke; heltene ser ikke, hvorfor den står netop dér.`,`The mast could be a sea mark; the heroes do not see why it stands just there.`))],fight:!1,alternatives:[O(`Fæld masten: Med økser og en halv times arbejde ligger lygten i tangen, og vragrøverne må nøjes med et bål, men så ved {villain}, at nogen har været på næsset.`,`Fell the mast: with axes and half an hour’s work the lantern lies in the weed and the wreckers must make do with a bonfire, but then {villain} knows someone has been on the point.`),O(`Tag {npc3} med ud til fyret: Fiskeren kender holmen og bådebroen og kan vise, hvor vragrøverne vil gå i land, men så er der ingen til at holde lygten slukket.`,`Take {npc3} out to the lighthouse: the fisher knows the islet and its jetty and can show where the wreckers will land, but then nobody is left to keep the lantern dark.`)],dmNotes:O(`Næsset viser spillerne fælden fra skibets side. Spil {npc3} som et ærligt menneske, der er trængt op i en krog, ikke som en skurk; et venligt ord og et løfte om hjælp med gælden vejer mere end trusler.`,`The point shows the players the trap from the ship’s side. Play {npc3} as an honest person driven into a corner, not as a villain; a kind word and a promise of help with the debt weigh more than threats.`)},{kind:`combat`,at:`site`,present:[`npc2`],title:O(`Angrebet på kulskuret`,`The Assault on the Coal Shed`),summary:O([`Ved mørkets frembrud lukker tidevandet ebbevejen, og kort efter går nogle {foe} i land ved holmens lille bådebro med økser, spande og stager.`,`De går ikke efter tårnet, men efter kulskuret i fyrgården, hvor alt kullet til natten ligger: Kommer kullet i havet, går ilden ud længe før daggry.`,`Heltene skal holde kulskuret og tårndøren, mens {npc2}, den gamle fyrpasser, holder ilden i gang øverst i tårnet.`],[`At nightfall the tide closes the causeway, and soon afterwards some {foe} land at the islet’s small jetty with axes, buckets and poles.`,`They do not go for the tower but for the coal shed in the yard, where all the coal for the night is kept: if the coal goes into the sea, the fire goes out long before dawn.`,`The heroes must hold the coal shed and the tower door while {npc2}, the old keeper, keeps the fire going at the top of the tower.`]),readAloud:O([`Stormen hyler om tårnet, og skumsprøjt fejer ind over muren om fyrgården.`,`Nede ved bådebroen danser lygter på det sorte vand, og skikkelser springer i land, én efter én.`,`Så lyder det første økseslag mod døren til kulskuret.`],[`The storm howls round the tower, and spray sweeps in over the wall of the yard.`,`Down at the jetty lanterns dance on the black water, and shapes leap ashore one after another.`,`Then the first axe blow strikes the door of the coal shed.`]),details:[O(`Vragrøverne prøver kun at få kullet i havet og døren slået ind, ikke at tage holmen i nat; når de har mistet nogle stykker, eller når tre sække er i havet, trækker de sig tilbage til bådene og ror i læ af skærene. Kullet, der er tilbage, rækker til daggry, men kun hvis ikke én sæk mere går tabt.`,`The wreckers are only trying to get the coal into the sea and the door broken in, not to take the islet tonight; once they have lost a few, or three sacks are in the sea, they fall back to the boats and row into the lee of the rocks. The coal that is left will last until dawn, but only if not one more sack is lost.`),O(`Hos de faldne angribere finder heltene blanke messingmærker med strandkontorets anker, den slags {villain} betaler bjærgningsfolk med, og som kan veksles til sølv på strandkontoret i {town}. {npc2} kender dem straks og bliver stille.`,`On the fallen attackers the heroes find bright brass tokens stamped with the anchor of the strand office, the kind {villain} pays salvage crews with, which can be changed for silver at the strand office in {town}. {npc2} recognises them at once and falls silent.`),O(`{npc2} er stadig tung af søvn efter eftermiddagens vin og har kun lige fået ilden til at brænde ordentligt. Fyrpasseren skal bruge en hjælper til at bære kul op ad de hundrede trin hver time, og hver time, ingen bærer, falder ilden.`,`{npc2} is still heavy with sleep after the afternoon’s wine and has only just got the fire burning properly. The keeper needs a helper to carry coal up the hundred steps every hour, and for every hour that nobody does, the fire sinks lower.`)],checks:[A(`Strength (Athletics)`,`medium`,O(`Heltene får kulskurets dør stivet af med en bjælke, før den giver sig; vragrøverne får ikke en eneste sæk med, og kampen bliver ved døren, hvor muren hjælper forsvarerne.`,`The heroes brace the coal shed door with a beam before it gives; the wreckers do not get a single sack, and the fight stays at the door, where the wall helps the defenders.`),O(`Døren flækker, og tre sække kul går i havet, før vragrøverne bliver drevet tilbage; resten rækker kun til daggry, hvis heltene sparer på hver skovlfuld.`,`The door splits and three sacks of coal go into the sea before the wreckers are driven back; what is left lasts until dawn only if the heroes save every shovelful.`)),A(`Wisdom (Perception)`,`easy`,O(`Heltene ser, at bådene ikke ror mod land, men lægger sig i læ af skærene og venter: Angrebet var en prøve, og det rigtige kommer senere.`,`The heroes see that the boats do not row for the shore but lie in the lee of the rocks and wait: the assault was a test, and the real one is still to come.`),O(`Heltene tror, at vragrøverne er slået på flugt, og ingen holder vagt ved bådebroen den næste time.`,`The heroes believe the wreckers have been put to flight, and nobody keeps watch at the jetty for the next hour.`))],fight:!0,alternatives:[O(`Bær kullet ind i tårnet: Med alle hænder i gang er kullet inde på en halv time, og vragrøverne finder et tomt skur, men tårnets nederste rum bliver fyldt, og døren kan kun lige lukkes.`,`Carry the coal into the tower: with every hand at work the coal is inside in half an hour and the wreckers find an empty shed, but the bottom room of the tower is full, and the door barely shuts.`),O(`Brænd bådene: Den, der kommer ned til bådebroen, mens kampen står ved kulskuret, kan sætte ild til en af vragrøvernes både; de andre trækker sig straks for at redde resten.`,`Burn the boats: whoever gets down to the jetty while the fight is at the coal shed can set fire to one of the wreckers’ boats; the wreckers pull back at once to save the rest.`)],dmNotes:O(`Angrebet på kulskuret er en prøve, ikke selve belejringen: Lad vragrøverne trække sig, så snart de har mistet nogle stykker, og lad spillerne mærke, at det rigtige angreb endnu ikke er kommet. Tæl kulsækkene højt ved bordet; de er nattens ur.`,`The assault on the coal shed is a test, not the siege itself: let the wreckers fall back once they have lost a few, and let the players feel that the real attack has not come yet. Count the coal sacks aloud at the table; they are the night’s clock.`)},{kind:`investigation`,at:`site`,present:[`npc2`],title:O(`Fyrkurven ved midnat`,`The Beacon at Midnight`),summary:O([`Ved midnat står vandet højest, og fra galleriet ved fyrkurven ser heltene et nyt lys blusse op på Kragenæsset, lige så højt som fyrets eget.`,`Mens de bærer kul op ad trappen, kan de gennemsøge fyrpasserens kammer under fyrkurven: vinkrukken fra {villain}, fyrpasserens logbog over de sidste vintres nætter og krogen ved døren, hvor den anden nøgle hang, før strandfogeden tog den.`,`{npc2} begynder at forstå, hvad der skete de nætter, hvor ilden brændte ned, og her samles beviserne mod {villain}.`],[`At midnight the tide is at its highest, and from the gallery by the beacon the heroes see a new light flare up on Crow Point, as high as the lighthouse’s own.`,`While they carry coal up the stair, they can search the keeper’s room below the beacon: the wine jar from {villain}, the keeper’s logbook for the past winters and the hook by the door where the second key hung before the wreck-master took it.`,`{npc2} begins to understand what happened on the nights the fire burned low, and here the evidence against {villain} comes together.`]),readAloud:O([`Øverst i tårnet brøler ilden i den store jernkurv, og varmen slår mod heltene, mens regnen hvæser på galleriets sten.`,`Mod syd, over det sorte vand, brænder et andet lys, lige så højt og lige så gult.`,`Langt ude på havet vender en enkelt skibslanterne langsomt mod land.`],[`At the top of the tower the fire roars in the great iron basket, and the heat beats against you while the rain hisses on the stones of the gallery.`,`To the south, across the black water, another light burns, just as high and just as yellow.`,`Far out at sea a single ship’s lantern turns slowly toward land.`]),details:[O(`Lyset på Kragenæsset er den falske lygte, tændt ved midnat som aftalt; har heltene fældet masten, er det i stedet et bål, svagere og mere rødt. Ude på havet har koggen set begge lys, og skipperen ved ikke, hvilket der er fyret. Ilden i fyrkurven skal stå højere og klarere end det falske lys resten af natten, og det kræver kul hver time.`,`The light on Crow Point is the false lantern, lit at midnight as agreed; if the heroes felled the mast, it is a bonfire instead, weaker and redder. Out at sea the cog has seen both lights, and its skipper does not know which is the lighthouse. The fire in the beacon must burn higher and brighter than the false light for the rest of the night, and that takes coal every hour.`),O(`Har {npc3} lovet heltene at lade lygten være slukket, holder fiskeren løftet: Ved midnat er næsset mørkt, og der er intet nyt lys mod syd. Så gælder natten kun ilden i fyrkurven, for slukker {villain} den før daggry, sejler koggen blindt i stormen og går på Tænderne alligevel.`,`If {npc3} promised the heroes that the lantern would stay dark, the fisher keeps the promise: at midnight the point is dark, and there is no new light to the south. Then all that matters tonight is the fire in the beacon, for if {villain} puts it out before dawn, the cog sails blind in the storm and strikes the Teeth all the same.`),O(`I fyrpasserens kammer står stenkrukken med vin "med strandfogedens hilsen til stormnatten"; bundfaldet lugter af valmue. I fyrpasserens logbog står de to nætter sidste vinter, hvor ilden brændte ned "på strandfogedens ord", og de samme nætter forliste "De tre søstre" og en fiskerbåd på Tænderne. {npc2} har aldrig lagt de to ting sammen før nu.`,`In the keeper’s room stands the stone jar of wine "with the wreck-master’s compliments for the storm night"; the dregs smell of poppy. The keeper’s logbook records the two nights last winter when the fire burned low "on the wreck-master’s word", and on those same nights the "Three Sisters" and a fishing boat were wrecked on the Teeth. {npc2} has never put the two together until now.`),O(`Tårndøren har to nøgler: fyrpasserens og den, {villain} bruger, når kullet bliver leveret. Døren kan kun holdes, hvis tværbommen bliver lagt for indefra, men bommen er rådden og knækker ved første stød; med en bjælke fra kulskuret og en times arbejde kan heltene lave en ny.`,`The tower door has two keys: the keeper’s, and the one {villain} uses when the coal is delivered. The door can only be held if the crossbar is dropped from inside, but the bar is rotten and will snap at the first blow; with a beam from the coal shed and an hour’s work the heroes can make another.`)],checks:[A(`Intelligence (Investigation)`,`easy`,O(`Heltene lægger vinen, logbogen og messingmærkerne sammen: Strandfogeden har slukket ilden før, og i nat skal det ske igen, med {villain}s egen nøgle.`,`The heroes put the wine, the logbook and the brass tokens together: the wreck-master has put the fire out before, and tonight it is to happen again, with {villain}’s own key.`),O(`Heltene finder vinkrukken, men overser logbogen; de ved, at nogen ville have fyrpasseren til at sove, men ikke hvem.`,`The heroes find the wine jar but miss the logbook; they know someone wanted the keeper asleep, but not who.`)),A(`Wisdom (Insight)`,`medium`,O(`{npc2} fortæller sandheden om de to nætter sidste vinter og om {villain}s ord om smuglerne og beder heltene om hjælp til at gøre det godt igen; fyrpasseren vil vidne foran hele {town}.`,`{npc2} tells the truth about the two nights last winter and what {villain} said about the smugglers, and asks the heroes to help set it right; the keeper will bear witness before all of {town}.`),O(`{npc2} skammer sig for meget til at tale og forsvarer strandfogeden: {villain} har reddet flere sømænd end nogen anden på kysten.`,`{npc2} is too ashamed to speak and defends the wreck-master: {villain} has saved more sailors than anyone else on the coast.`))],fight:!1,alternatives:[O(`Byg ilden højere: Med tønder, møbler og trappens løse brædder kan heltene få ilden til at stå dobbelt så højt resten af natten, så ingen skipper kan tage fejl, men så er der intet tilbage at fyre med, hvis kullet slipper op.`,`Build the fire higher: with barrels, furniture and the loose boards of the stair the heroes can make the fire burn twice as high for the rest of the night, so no skipper can mistake it, but then there is nothing left to burn if the coal runs out.`),O(`Send et lyssignal til koggen: {npc2} kender lodsernes tegn, og med lygten fra galleriet kan heltene blinke "hold fra land" ud over vandet; skipperen forstår det, hvis en helt holder lygten stille i en time.`,`Signal the cog: {npc2} knows the pilots’ signs, and with the lantern from the gallery the heroes can flash "keep off the land" across the water; the skipper understands it if a hero holds the lantern steady for an hour.`)],dmNotes:O(`Her bliver mistanken til vished, og spillerne har tid til at forberede sig: Lad dem selv vælge, om de vil lave en ny tværbom, give koggen tegn eller hvile. Lad de to lys over vandet være det billede, der hænger over resten af natten.`,`Here suspicion turns to certainty, and the players have time to prepare: let them choose whether to make a new crossbar, signal the cog or rest. Let the two lights over the water be the picture that hangs over the rest of the night.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`,`npc2`],title:O(`Lyset før daggry`,`The Light before Dawn`),summary:O([`I timen før daggry løber ebbevejen tør, og en række lygter kommer ud ad den: {villain} selv i spidsen for redningsmandskabet, alle i nyt olietøj, og stemmen, hele kysten kender, råber, at hjælpen fra {town} er kommet.`,`Under hætterne er det {boss} og resten af vragrøverne, og {villain} stikker sin nøgle i tårndøren for at komme op og slukke ilden, netop som koggen skal forbi Tænderne.`,`Heltene skal holde døren og trappen, holde ilden i gang til daggry og vise alle, hvem strandfogeden har taget med.`],[`In the hour before dawn the causeway runs dry, and a line of lanterns comes out along it: {villain} in person at the head of the rescue crew, all in new oilskins, and the voice the whole coast knows calls out that help has come from {town}.`,`Under the hoods are {boss} and the rest of the wreckers, and {villain} puts a key in the tower door, meaning to climb up and put out the fire just as the cog must pass the Teeth.`,`The heroes must hold the door and the stair, keep the fire going until dawn and show everyone whom the wreck-master has brought along.`]),readAloud:O([`Vandet trækker sig tilbage fra ebbevejen med en lang, sugende lyd, og stenene skinner sorte i regnen.`,`Ude på vejen kommer en række lygter nærmere, og forrest går en skikkelse med en fin kappe under olietøjet og vinker op mod tårnet.`,`"Fyrpasser! Luk op, hjælpen er her!" Så skraber en nøgle i låsen.`],[`The water draws back from the causeway with a long, sucking sound, and the stones shine black in the rain.`,`Out on the causeway a line of lanterns comes closer, and at the front walks a figure with a fine coat under their oilskins, waving up at the tower.`,`"Keeper! Open up, help is here!" Then a key scrapes in the lock.`]),details:[O(`{boss} og nogle {foe} går under hætterne, fordi {villain} har lovet dem en åben dør og halvdelen af koggens last. De tjener ikke {villain} og er kun bundet af aftalen: Bliver døren ikke åbnet, eller viser det sig, at strandfogeden ikke kan holde, hvad der er lovet, vender {boss} sig mod {villain}.`,`{boss} and some {foe} hide under the hoods because {villain} promised them an open door and half the cog’s cargo. They do not serve {villain} and are bound only by the bargain: if the door does not open, or the wreck-master turns out to be unable to deliver what was promised, {boss} turns on {villain}.`),O(`{villain} kæmper ikke, men vil op ad trappen med en spand havvand til ilden og bagefter råbe, at vragrøverne nåede at slukke den, før redningsmandskabet kom. Er tværbommen lagt for, hjælper nøglen ikke, og vragrøverne må slå døren ind eller klatre op ad muren til galleriet, mens {villain} bliver nervøs nede på vejen. Er strandfogeden allerede afsløret, prøver {villain} at slippe væk over ebbevejen, før vandet stiger igen.`,`{villain} does not fight, but means to climb the stair with a bucket of seawater for the fire and afterwards cry that the wreckers put it out before the rescue crew arrived. If the crossbar is down, the key is no use, and the wreckers must break the door in or climb the wall to the gallery while {villain} grows nervous down on the causeway. If the wreck-master has already been exposed, {villain} tries to escape over the causeway before the water rises again.`),O(`Ved daggry står koggen klar af Tænderne, og fra land kommer folkene fra {town} ud over ebbevejen. En hætte, der bliver revet af, så alle ser, hvem der går i redningsmandskabets olietøj, afgør sagen: Strandfogeden har intet at sige.`,`At dawn the cog stands clear of the Teeth, and from the shore the people of {town} come out along the causeway. One hood torn back, so that everyone sees who walks in the rescue crew’s oilskins, settles it: the wreck-master has nothing to say.`)],checks:[A(`Strength (Athletics)`,`medium`,O(`Heltene holder døren, mens den nye tværbom bliver lagt for; nøglen drejer i låsen, men døren rokker sig ikke, og vragrøverne må gå den lange vej op ad muren.`,`The heroes hold the door while the new crossbar is dropped into place; the key turns in the lock, but the door does not budge, and the wreckers must go the long way up the wall.`),O(`Døren går op, før bommen er lagt for, og kampen står på trappen, trin for trin, mens nogen må blive ved ilden.`,`The door opens before the bar is down, and the fight is on the stair, step by step, while someone must stay by the fire.`)),A(`Charisma (Intimidation)`,`hard`,O(`Heltene river hætten af en af de forreste og råber ud over ebbevejen, hvem strandfogeden har med; de ægte redningsfolk, der er fulgt efter fra {town}, standser, og {villain} står alene i lygteskæret.`,`The heroes tear the hood off one of the foremost and shout across the causeway whom the wreck-master has brought; the real rescue crew, who followed from {town}, stop, and {villain} stands alone in the lantern light.`),O(`Råbene drukner i stormen, og {villain} råber tilbage, at fyret er faldet i vragrøvernes hænder; heltene må holde ilden, til daggry viser sandheden.`,`The shouts are lost in the storm, and {villain} shouts back that the lighthouse has fallen to the wreckers; the heroes must hold the fire until dawn shows the truth.`))],fight:!0,alternatives:[O(`Lad {villain} komme ind alene: Heltene åbner døren på klem for strandfogeden og smækker den i for resten; med {villain} som fange inde i tårnet tør {boss} ikke slukke ilden med magt, og strandfogeden forhandler for at redde sit eget skind.`,`Let {villain} in alone: the heroes open the door a crack for the wreck-master and slam it on the rest; with {villain} a prisoner inside the tower, {boss} does not dare put out the fire by force, and the wreck-master bargains for safety.`),O(`Vis {boss} fragtbrevet fra "De tre søstre": Strandfogeden har snydt vragrøverne for deres andel af hvert forlis. {boss} vender sig mod {villain}, og strandfogeden beder heltene om beskyttelse og overgiver sig.`,`Show {boss} the bill of lading of the "Three Sisters": the wreck-master has cheated the wreckers of their share in every wreck. {boss} turns on {villain}, and the wreck-master begs the heroes for protection and surrenders.`)],dmNotes:O(`Lad den venlige stemme være det uhyggelige: {villain} lyder som redningen selv. Spil strandfogeden som en, der er vant til at blive takket, ikke som en kriger; det stærkeste øjeblik er hætten, der bliver revet af i lygteskæret foran folkene fra {town}.`,`Let the friendly voice be the frightening part: {villain} sounds like rescue itself. Play the wreck-master as someone used to being thanked, not as a fighter; the strongest moment is the hood torn off in the lantern light in front of the people of {town}.`)}},Ze=e({kernel:()=>tt,scenes:()=>nt}),Qe=e=>Array.isArray(e)?e.join(` `):e,j=(e,t)=>({da:Qe(e),en:Qe(t)}),$e=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),M=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},et=(e,t,n)=>({when:e,event:t,sign:n}),N=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),tt={id:`race-the-last-ferry`,titles:[j(`Den sidste færge`,`The Last Ferry`),j(`Liljerne i {place}`,`The Lilies of {place}`),j(`Det kappede reb`,`The Cut Rope`)],missions:[`race`],foes:`lair`,roles:{npc1:j(`en urtekyndig, der har passet de syge i {town} hele efteråret`,`a herbalist who has nursed the sick of {town} all autumn`),npc2:j(`en gammel ålefanger, der kender stierne gennem kæret`,`an old eel-catcher who knows the paths through the fen`),npc3:j(`en færgemand, der skal sejle sæsonens sidste færge`,`a ferryman who is to run the last ferry of the season`),villain:j(`en apoteker i {town}, der sælger den eneste medicin mod feberen`,`an apothecary of {town} who sells the only remedy for the fever`)},hook:j(`{npc1}, en urtekyndig, der har passet de syge i {town} hele efteråret, beder heltene sejle med sæsonens sidste færge til {place}, grave rødderne af kærliljerne op før {villain}s folk og være tilbage ved færgelejet, før færgen bliver trukket op for vinteren ved solnedgang.`,`{npc1}, a herbalist who has nursed the sick of {town} all autumn, asks the heroes to take the last ferry of the season to {place}, dig up the fen lily roots ahead of {villain}’s crew and be back at the landing before the ferry is drawn up for the winter at sunset.`),people:{npc1:{wants:j(`Vil have rødderne til sygestuen, før endnu et barn dør, og koge te af dem til alle, rig eller fattig.`,`Wants the roots in the sickroom before another child dies, and to brew tea from them for everyone, rich or poor.`),secret:j(`Solgte selv {villain} opskriften på liljeteen for to år siden for at betale husleje og frygter, at det er derfor, apotekeren nu vil have hele bedet.`,`Sold {villain} the recipe for the lily tea two years ago to pay the rent, and fears that is why the apothecary now wants the whole bed.`)},npc2:{wants:j(`Vil se sit syge barnebarn rask igen og se klostrets have en sidste gang, før vandet tager kæret for vinteren.`,`Wants to see their sick grandchild well again, and the abbey garden one last time before the water takes the fen for the winter.`),secret:j(`Tegnede selv det kort over stierne, som {villain} købte i foråret, men har tiet, fordi apotekeren giver barnebarnet feberdrikken på kredit.`,`Drew the map of the fen paths that {villain} bought in spring, but has kept quiet because the apothecary gives their grandchild the fever draught on credit.`)},npc3:{wants:j(`Vil have færgen over floden en sidste gang og op i vinterlejet, før efterårsfloden kommer.`,`Wants the ferry across the river one last time and up into its winter berth before the autumn flood comes.`),secret:j(`Tog imod en ekstra sølvmønt fra {villain} for at sejle graverne over før solopgang og har siden haft på fornemmelsen, at kniven i rebet blev betalt af samme pung.`,`Took an extra silver coin from {villain} to carry the diggers over before sunrise, and has suspected ever since that the same purse paid someone to cut the rope.`)}},premise:j([`I flere uger har kærfeberen bredt sig i {town}, og det eneste, der virker, er te af kærliljens rødder; de eneste kærliljer i mange dages omkreds gror i den gamle havedam i {place}, en klosterruin på en ø ude i kæret på den anden side af floden.`,`{villain}, apotekeren i {town}, har hele efteråret solgt de syge en dyr feberdrik, der ikke virker, og vil nu eje hver eneste rod, så liljeteen kun kan købes på apoteket til den pris, {villain} sætter.`,`I dag sejler færgen for sidste gang i år: Ved solnedgang bliver den trukket op for vinteren, og i nat kommer efterårsfloden ind over kæret og dækker dammen til foråret.`,`Ved første lys sejlede {villain} over med sine gravere, bag dem blev færgerebet kappet, og ved færgekroen bliver der solgt kort over stierne, som apotekeren har ladet ændre.`],[`For weeks marsh fever has been spreading through {town}, and the only thing that works is tea from fen lily roots; the only fen lilies within many days’ travel grow in the old garden pond of {place}, a ruined abbey on an island out in the fen across the river.`,`All autumn {villain}, the apothecary of {town}, has sold the sick a costly fever draught that does not work, and now means to own every last root, so that lily tea can only be bought at the apothecary’s, at whatever price {villain} sets.`,`Today the ferry runs for the last time this year: at sunset it is drawn up for the winter, and tonight the autumn flood comes in over the fen and covers the pond until spring.`,`At first light {villain} crossed with a crew of diggers, and behind them the ferry rope was cut; the maps of the fen paths sold at the ferry inn have been altered on the apothecary’s orders.`]),goal:j(`Nå liljedammen i {place} før {villain}s folk, grav rødderne op, og vær tilbage ved færgelejet med dem før solnedgang.`,`Reach the lily pond of {place} before {villain}’s crew, dig up the roots and be back at the ferry landing with them before sunset.`),objective:{target:j(`Rødderne af de sidste kærliljer, der gror i den gamle havedam i {place}`,`The roots of the last fen lilies, growing in the old garden pond of {place}`),state:j([`Liljerne står i dammen midt i klostrets have, og {villain}s folk er i gang med at grave dem op med spader og kurve; kun {villain} kan kende de rigtige rødder fra de almindelige.`,`I de sammenstyrtede munkeceller ved haven har {boss} og nogle {foe} deres leje, og larmen fra gravningen vil vække dem.`],[`The lilies grow in the pond in the middle of the abbey garden, and {villain}’s crew are digging them up with spades and baskets; only {villain} can tell the true roots from the common ones.`,`In the collapsed monks’ cells beside the garden, {boss} and some {foe} have their lair, and the noise of the digging will wake them.`]),resolution:j([`Kom før eller forbi {villain}s folk, grav rødderne op, eller tag dem fra apotekeren, og nå tilbage til færgelejet før solnedgang.`,`Kan heltene ikke nå færgen med rødderne, kan de stadig plante nogle af dem i dammen igen, så bedet ikke er tabt, men så må {town} vente til foråret.`],[`Get there ahead of {villain}’s crew or get past them, and dig up the roots or take them from the apothecary; then get back to the ferry landing before sunset.`,`If the heroes cannot reach the ferry with the roots, they can still replant some in the pond so the bed is not lost, but then {town} must wait until spring.`])},villain:{want:j(`At eje hver eneste rod, så liljeteen kun kan købes på apoteket til den pris, {villain} sætter, og så ingen opdager, at apotekets dyre feberdrik aldrig har virket.`,`To own every last root, so that lily tea can only be bought at the apothecary’s, at whatever price {villain} sets, and so that nobody discovers the apothecary’s costly fever draught never worked.`),plan:j([`Først købte {villain} ålefangerens kort over stierne gennem kæret og lod afskrifter ændre, så stien til klostret fører ud i hængedyndet; afskrifterne bliver solgt ved færgekroen.`,`Ved første lys sejlede {villain} over med sine gravere, og en af dem blev tilbage og kappede færgerebet, så ingen kunne følge efter.`,`Hele dagen graver {villain}s folk i liljedammen i {place}, mens {villain} selv sorterer rødderne, og ved solnedgang sejler de hjem med apotekets egen pram, der ligger skjult i sivene bag klostret, mens færgen bliver trukket op, og efterårsfloden lukker kæret bag dem.`],[`First {villain} bought the eel-catcher’s map of the fen paths and had copies altered so that the path to the abbey leads into the quaking bog; the copies are sold at the ferry inn.`,`At first light {villain} crossed with the diggers, and one of them stayed behind and cut the ferry rope so that nobody could follow.`,`All day {villain}’s crew dig in the lily pond at {place} while {villain} sorts the roots, and at sunset they sail home on the apothecary’s own barge, hidden in the reeds behind the abbey, while the ferry is drawn up and the autumn flood closes the fen behind them.`]),weakness:j([`{villain}s gravere er lejet for en dagløn og har ingen lyst til at blive i kæret, når vandet kommer; de ved ikke, at apotekeren betalte for kniven i færgerebet.`,`Og kun {villain} kan kende de rigtige rødder: Uden apotekeren er kurvene fulde af almindelige liljer, og med rodkniven og det falske kort som bevis vil ingen i {town} købe noget hos {villain} igen.`],[`{villain}’s diggers are hired for a day’s wage and have no wish to stay in the fen when the water comes; they do not know the apothecary paid to have the ferry rope cut.`,`And only {villain} can pick out the true roots: without the apothecary the baskets are full of common lilies, and with the root knife and the false map as proof, nobody in {town} will buy anything from {villain} again.`])},stakes:j(`Får {villain} alle rødderne, koster liljeteen mere, end de fattige i {town} kan betale, og feberen tager de svageste hele vinteren; når ingen frem i tide, tager vandet bedet, og der er ingen te før foråret.`,`If {villain} gets every root, the lily tea costs more than the poor of {town} can pay, and the fever takes the weakest all winter; if nobody gets there in time, the water takes the bed and there is no tea before spring.`),clock:{start:j(`Første lys. {villain}s gravere er lige sejlet over med dagens første færge, og færgerebet driver kappet i strømmen bag dem. Ved solnedgang, om ti timer, bliver færgen trukket op for vinteren, og i nat kommer efterårsfloden ind over kæret.`,`First light. {villain}’s diggers have just crossed on the day’s first ferry, and behind them the cut ferry rope drifts in the current. At sunset, ten hours from now, the ferry is drawn up for the winter, and tonight the autumn flood comes in over the fen.`),ticks:[et(j(`Efter 3 timer`,`After 3 hours`),j(`{villain}s folk når {place} ad den rigtige sti, sætter to gravere til at vogte porten og begynder at grave i liljedammen, mens {villain} sorterer rødderne.`,`{villain}’s crew reaches {place} by the true path, sets two diggers to guard the gate and starts digging in the lily pond while {villain} sorts the roots.`),j(`Røg fra et bål stiger op fra klosterruinen ude i kæret, og ænder letter skræppende fra dammen.`,`The smoke of a fire rises from the ruined abbey out in the fen, and ducks take off squawking from the pond.`)),et(j(`Efter 6 timer (ved middagstid)`,`After 6 hours (at noon)`),j(`Halvdelen af bedet er gravet op, og floden begynder at stige; stierne gennem kæret bliver bløde, og hver time derude koster mere.`,`Half the bed is dug up, and the river begins to rise; the paths through the fen turn soft, and every hour out there costs more.`),j(`Brunt vand løber ind i grøfterne langs stierne, og larmen af spader fra haven vækker noget i de sammenstyrtede munkeceller.`,`Brown water runs into the ditches along the paths, and the noise of spades in the garden wakes something in the collapsed monks’ cells.`)),et(j(`Efter 10 timer (ved solnedgang)`,`After 10 hours (at sunset)`),j(`{villain} og graverne bærer de sidste kurve til den skjulte pram og sejler over floden, mens {npc3} trækker færgen op for vinteren; det, der ikke er på vej over floden nu, er tabt til foråret.`,`{villain} and the diggers carry the last baskets to the hidden barge and cross the river while {npc3} draws the ferry up for the winter; whatever is not on its way across the river now is lost until spring.`),j(`Færgemandens horn lyder for sidste gang over floden, og en lav pram glider ud fra sivene bag klostret.`,`The ferryman’s horn sounds over the river for the last time, and a low barge slides out of the reeds behind the abbey.`))],deadline:j(`Efter 10 timer, ved solnedgang, bliver færgen trukket op for vinteren, og {villain}s pram glider over floden; er rødderne ikke på vej over da, ligger de på apotekets hylder eller under efterårsfloden til foråret.`,`After 10 hours, at sunset, the ferry is drawn up for the winter, and {villain}’s barge slides across the river; if the roots are not on their way across by then, they end up on the apothecary’s shelves or under the autumn flood until spring.`)},clues:{who:[M(`town`,j(`I sygestuen i {town} viser {npc1} en tom flaske af apotekets feberdrik: Under den røde farve er det kun vand, honning og en smule valmue, og den har kostet en sølvmønt om dagen hele efteråret.`,`In the sickroom of {town}, {npc1} shows an empty bottle of the apothecary’s fever draught: under the red colouring it is only water, honey and a little poppy, and it has cost a silver coin a day all autumn.`),j(`{villain} har solgt de syge en drik, der ikke virker, og har alt at tabe, hvis liljeteen bliver kogt gratis i sygestuen.`,`{villain} has sold the sick a draught that does not work, and has everything to lose if lily tea is brewed for free in the sickroom.`),$e([`Apotekets feberdrik`,`Tre skefulde morgen og aften, til feberen viger.`,`En sølvmønt flasken. Kun hos {villain}, apoteker i {town}.`],[`The Apothecary’s Fever Draught`,`Three spoonfuls morning and evening until the fever breaks.`,`One silver coin the bottle. Only from {villain}, apothecary of {town}.`])),M(`town`,j(`Ved færgelejet er færgerebet skåret rent over, og i mudderet under pælen ligger en krum rodkniv med apotekets morter brændt ind i skaftet.`,`At the ferry landing the rope has been cut clean through, and in the mud below the post lies a curved root knife with the apothecary’s mortar burned into the handle.`),j(`Rebet blev kappet af {villain}s folk, så ingen kunne følge efter dem over floden.`,`The rope was cut by {villain}’s crew so that nobody could follow them across the river.`)),M(`town`,j(`{npc2} kender sin egen tegning igen i det kort, heltene har med: Nogen har flyttet stien, så den falske linje fører ud i hængedyndet, og nederst står {villain}s navn som køber.`,`{npc2} recognises their own drawing in the map the heroes carry: someone has moved the path, so that the false line leads into the quaking bog, and at the bottom {villain} is named as the buyer.`),j(`{villain} lod kortet ændre, så alle, der følger det, synker i kæret, før de når liljerne.`,`{villain} had the map altered so that anyone who follows it sinks in the fen before reaching the lilies.`),$e([`Stien til klostret, tegnet af {npc2}:`,`Fra færgelejet langs pilene til den hvide sten.`,`Derfra lige mod kirketårnet over den grønne flade.`,`Solgt til {villain}, apoteker.`],[`The path to the abbey, drawn by {npc2}:`,`From the ferry landing along the willows to the white stone.`,`From there straight toward the church tower across the green flat.`,`Sold to {villain}, apothecary.`])),M(`site`,j(`Ved porten til klosteret brokker {villain}s gravere sig over, at apotekeren lod en af dem blive tilbage ved floden ved daggry "for at gøre noget ved rebet", og at de skal hjem med apotekets egen pram og ikke med færgen.`,`At the abbey gate, {villain}’s diggers grumble that the apothecary left one of them behind by the river at dawn "to see to the rope", and that they are to go home on the apothecary’s own barge, not the ferry.`),j(`{villain} fik færgerebet kappet og har sørget for sin egen vej hjem.`,`{villain} had the ferry rope cut and has made sure of a way home.`))],where:[M(`town`,j(`I sygestuen fortæller {npc1}, at kærliljerne kun gror i den gamle havedam midt i klostrets have i {place}, og at kun de hvide rødder med røde årer hjælper mod feberen.`,`In the sickroom, {npc1} explains that the fen lilies grow only in the old garden pond in the middle of the abbey garden at {place}, and that only the white roots with red veins work against the fever.`),j(`Målet er liljedammen i klosterhaven, og den, der graver, skal kende de rigtige rødder.`,`The goal is the lily pond in the abbey garden, and whoever digs must be able to recognise the true roots.`),$e([`Kærlilje: hvid blomst, flydende blade.`,`Kun roden duer: hvid med røde årer, så tyk som en tommelfinger.`,`Kog den i vand en time. Én kop morgen og aften.`],[`Fen lily: white flower, floating leaves.`,`Only the root will do: white with red veins, as thick as a thumb.`,`Boil it in water for an hour. One cup morning and evening.`])),M(`town`,j(`{npc2} viser den rigtige sti: Den går ikke over den grønne flade, som det falske kort siger, men i en bue langs pilene til den gamle stendæmning, der fører ud til øen.`,`{npc2} shows the true path: it does not cross the green flat, as the false map says, but curves along the willows to the old stone dyke that leads out to the island.`),j(`Med {npc2} som fører kan heltene nå øen uden om hængedyndet og indhente forspringet.`,`With {npc2} as guide, the heroes can reach the island round the quaking bog and close the gap.`)),M(`site`,j(`Fra porten til klosteret kan man se ind i haven: Liljedammen er halvt gravet op, kurve med rødder står på bredden, og {villain} sidder ved vandet og sorterer dem.`,`From the abbey gate one can see into the garden: the lily pond is half dug up, baskets of roots stand on the bank, and {villain} sits by the water sorting them.`),j(`Der er stadig rødder i dammen, og de gode ligger i {villain}s kurve; der er tid, hvis heltene skynder sig.`,`There are still roots in the pond, and the good ones lie in {villain}’s baskets; there is time if the heroes hurry.`)),M(`site`,j(`Bag klosteret fører et frisk spor af slæbte kurve ned gennem sivene til en pram med apotekets morter malet på stævnen.`,`Behind the abbey a fresh trail of dragged baskets leads down through the reeds to a barge with the apothecary’s mortar painted on the bow.`),j(`{villain} skal ikke hjem med færgen: Rødderne skal over floden med prammen ved solnedgang, og dér kan de tages.`,`{villain} is not going home by ferry: the roots are to cross the river on the barge at sunset, and there they can be taken.`))]},endings:{success:j(`Heltene når færgen i det sidste lys med kurvene fulde af rigtige rødder, og færgemanden trækker dem over floden, mens vandet allerede stiger i kæret bag dem. I sygestuen koger {npc1} liljete til alle, rig eller fattig, og feberen slipper sit tag inden for en uge. Rodkniven og det falske kort ligger på rådhusbordet i {town}, og {villain} må lukke apoteket og betale hver sølvmønt for den værdiløse feberdrik tilbage.`,`The heroes reach the ferry in the last light with baskets full of true roots, and the ferryman hauls them across the river as the water is already rising in the fen behind them. In the sickroom {npc1} brews lily tea for everyone, rich or poor, and the fever loosens its grip within a week. The root knife and the false map lie on the council table in {town}, and {villain} must close the shop and pay back every silver coin for the worthless fever draught.`),partial:j(`Heltene hindrer {villain} i at få rødderne over floden, men når ikke selv færgen med dem alle; de planter de fleste i dammen igen og kommer hjem med en håndfuld. {npc1} kan koge te til de sygeste, og {villain}s feberdrik bliver ikke solgt mere, men vinteren bliver lang i {town}, og der går en uge, før den sidste feber er brudt.`,`The heroes keep {villain} from getting the roots across the river, but cannot reach the ferry with all of them; they replant most in the pond and come home with a handful. {npc1} can brew tea for the sickest, and {villain}’s fever draught is sold no more, but the winter is long in {town}, and a week passes before the last fever breaks.`),failure:j(`{villain}s pram glider over floden i tusmørket med alle rødderne, og bag den tager vandet bedet. Hele vinteren sælger apoteket liljete til en pris, kun de rige kan betale, og {villain} bliver takket for at have reddet byen; i de fattige huse i {town} tager feberen de svageste.`,`{villain}’s barge slides across the river in the dusk with every root, and behind it the water takes the bed. All winter the apothecary sells lily tea at a price only the rich can pay, and {villain} is thanked for saving the town; in the poor houses of {town} the fever takes the weakest.`)}},nt={opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc2`],title:j(`Sygestuen i {town}`,`The Sickroom in {town}`),summary:j([`Ved første lys står {npc1}, en urtekyndig, der har passet de syge i {town} hele efteråret, i døren til sygestuen, hvor feberen har lagt halvdelen af kvarteret i sengene.`,`{npc1} beder heltene sejle over floden til {place}, den gamle klosterruin på en ø ude i kæret, og grave rødderne af kærliljerne op, før {villain}s folk tager dem alle; ved solnedgang bliver sæsonens sidste færge trukket op for vinteren.`,`{villain}s gravere er allerede sejlet over, og hver time i byen er en time, apotekeren vinder.`],[`At first light {npc1}, a herbalist who has nursed the sick of {town} all autumn, stands in the doorway of the sickroom, where half the quarter lies in bed with the fever.`,`{npc1} asks the heroes to cross the river to {place}, the old ruined abbey on an island out in the fen, and dig up the fen lily roots before {villain}’s crew takes them all; at sunset the last ferry of the season is drawn up for the winter.`,`{villain}’s diggers have already crossed, and every hour in town is an hour the apothecary gains.`]),readAloud:j([`Sygestuen er lang og lav og fuld af senge, og luften er tung af røg fra urter, der ulmer i en skål.`,`Ved en af sengene sidder en gammel ålefanger i lange vandstøvler og holder et barn i hånden.`,`Gennem vinduet ses floden, bred og brun, og langt ude på den anden side en grå ruin i kæret.`],[`The sickroom is long and low and full of beds, and the air is heavy with the smoke of herbs smouldering in a bowl.`,`By one of the beds sits an old eel-catcher in tall waders, holding a child’s hand.`,`Through the window you can see the river, wide and brown, and far off on the other side a grey ruin in the fen.`]),details:[j(`{npc1} forklarer: Kun te af kærliljens rødder hjælper mod feberen, og liljerne gror kun i den gamle havedam i {place}. {villain}, apotekeren, har solgt de syge en dyr feberdrik hele efteråret og sejlede over i morges med sine gravere for at tage hele bedet.`,`{npc1} explains: only tea from fen lily roots works against the fever, and the lilies grow only in the old garden pond at {place}. {villain}, the apothecary, has sold the sick a costly fever draught all autumn and crossed this morning with a crew of diggers to take the whole bed.`),j(`{npc2}, den gamle ålefanger, hvis barnebarn ligger i sygestuen, kender stierne gennem kæret og vil gerne føre heltene, men går langsomt. Ved færgekroen bliver der solgt kort over stierne, og alle i byen siger, at de er gode.`,`{npc2}, the old eel-catcher whose grandchild lies in the sickroom, knows the paths through the fen and is willing to guide the heroes, but walks slowly. At the ferry inn maps of the paths are sold, and everyone in town says they are good.`),j(`Færgen går fra færgelejet nedenfor byen, og turen over tager en halv time; på den anden side er der tre timers gang gennem kæret til øen. Ved solnedgang, om ti timer, trækker færgemanden færgen op for vinteren, og i nat kommer efterårsfloden ind over kæret.`,`The ferry leaves from the landing below the town, and the crossing takes half an hour; on the far side it is three hours’ walk through the fen to the island. At sunset, ten hours from now, the ferryman draws the ferry up for the winter, and tonight the autumn flood comes in over the fen.`)],checks:[N(`Wisdom (Medicine)`,`medium`,j(`Heltene smager på apotekets feberdrik og ved straks, at den kun er vand, honning og en smule valmue: Den lindrer, men helbreder ikke.`,`The heroes taste the apothecary’s fever draught and know at once that it is only water, honey and a little poppy: it soothes but does not heal.`),j(`Drikken smager bittert og stærkt; heltene kan ikke sige, om den hjælper.`,`The draught tastes bitter and strong; the heroes cannot tell whether it helps.`)),N(`Intelligence (Nature)`,`easy`,j(`{npc1} lærer heltene at kende den rigtige rod: hvid med røde årer og så tyk som en tommelfinger; nu behøver de ikke {villain} til at sortere.`,`{npc1} teaches the heroes to recognise the true root: white with red veins and as thick as a thumb; now they do not need {villain} to sort them.`),j(`Heltene lærer kun, at roden er hvid; i dammen vil de have svært ved at skelne den fra de almindelige liljer.`,`The heroes learn only that the root is white; in the pond they will struggle to tell it from the common lilies.`))],fight:!1,alternatives:[j(`Tag {npc2} med som fører: Ålefangeren kender den rigtige sti, men går langsomt; heltene må bære eller støtte {npc2} det sidste stykke.`,`Take {npc2} along as guide: the eel-catcher knows the true path but walks slowly; the heroes must carry or support {npc2} over the last stretch.`),j(`Gå til apoteket først: Svenden er alene i butikken og viser med lidt overtalelse heltene lageret, hvor kasser med tomme flasker står klar til liljeteen; det koster en time.`,`Go to the apothecary’s shop first: the apprentice is alone there and, with a little persuasion, shows the heroes the storeroom, where crates of empty bottles stand ready for the lily tea; it costs an hour.`)],dmNotes:j(`Gør kapløbet synligt fra første øjeblik: Fra færgelejet kan heltene se røgen fra {villain}s bål ude ved ruinen. Sig højt, hvad hvert ophold koster, og lad et barn hoste i sygestuen, mens de tøver.`,`Make the race visible from the first moment: from the ferry landing the heroes can see the smoke of {villain}’s fire out by the ruin. Say aloud what each stop costs, and let a child cough in the sickroom while they hesitate.`)},middle:[{kind:`social`,at:`town`,present:[`npc3`],title:j(`Færgelejet ved floden`,`The Ferry Landing by the River`),summary:j([`Ved færgelejet nedenfor byen driver færgerebet kappet i strømmen, og færgen ligger ubrugelig ved bredden; {villain}s gravere blev sejlet over ved daggry, og kort efter blev rebet skåret over.`,`{npc3}, færgemanden, der skal sejle sæsonens sidste færge, er rasende og hjælpeløs: Uden reb kan færgen ikke trækkes over, og ved solnedgang skal den op i vinterlejet.`,`Her skal heltene finde en vej over floden, og på færgekroen bliver der solgt kort over stierne gennem kæret.`],[`At the ferry landing below the town the cut ferry rope drifts in the current, and the ferry lies useless at the bank; {villain}’s diggers were taken across at dawn, and soon afterwards the rope was cut.`,`{npc3}, the ferryman who is to run the last ferry of the season, is furious and helpless: without a rope the ferry cannot be hauled across, and at sunset it must go up into its winter berth.`,`Here the heroes must find a way across the river, and at the ferry inn maps of the paths through the fen are sold.`]),readAloud:j([`Floden er bred og brun og løber stærkt efter regnen, og på hver bred står en tyk pæl, som rebet skulle løbe imellem.`,`Den flade færge ligger på grund ved bredden, og fra pælen hænger en rebende, skåret rent over.`,`En færgemand står til knæene i vandet og bander, så det kan høres helt op til kroen.`],[`The river is wide and brown and runs hard after the rain, and on each bank stands a thick post the rope should run between.`,`The flat ferry lies aground at the bank, and from the near post hangs a rope’s end, cut clean through.`,`A ferryman stands knee-deep in the water, swearing loud enough to be heard all the way up to the inn.`]),details:[j(`Rebet er skåret rent over med en kniv, og i mudderet under pælen ligger en krum rodkniv med apotekets morter brændt ind i skaftet. {npc3} sejlede {villain} og graverne over før solopgang mod en ekstra sølvmønt; en af graverne blev tilbage på denne bred, og da færgemanden kom op fra kroen, var rebet kappet.`,`The rope has been cut clean through with a knife, and in the mud below the post lies a curved root knife with the apothecary’s mortar burned into the handle. {npc3} took {villain} and the diggers across before sunrise for an extra silver coin; one of the diggers stayed behind on this bank, and when the ferryman came down from the inn, the rope was cut.`),j(`Der er tre veje over: splejse et nyt reb og få det over floden mod strømmen, hvilket tager en time; låne {npc3}s lille jolle, der kun tager to ad gangen og skal sejle frem og tilbage; eller vade over ved det gamle vadested en time længere oppe ad floden, hvor strømmen er stærk. Kun med et nyt reb kan færgen sejle igen ved solnedgang.`,`There are three ways across: splice a new rope and get it over the river against the current, which takes an hour; borrow {npc3}’s little skiff, which takes only two at a time and must go back and forth; or wade the old ford an hour further up the river, where the current is strong. Only with a new rope can the ferry run again at sunset.`),j(`På færgekroen sælger krofatter kort over stierne gennem kæret for en sølvmønt stykket; en fremmed kom med en bunke i går og sagde, at de var tegnet af den bedste ålefanger i {town}. Kortet viser en lige sti fra færgelejet over en grøn flade til klostret.`,`At the ferry inn the innkeeper sells maps of the paths through the fen for a silver coin apiece; a stranger brought a stack yesterday and said they were drawn by the best eel-catcher in {town}. The map shows a straight path from the landing across a green flat to the abbey.`)],checks:[N(`Strength (Athletics)`,`medium`,j(`Heltene får et nyt reb over floden og spændt fast; færgen kan sejle igen, og {npc3} lover at vente på dem ved den anden bred til sidste lys.`,`The heroes get a new rope across the river and make it fast; the ferry can run again, and {npc3} promises to wait for them at the far bank until the last light.`),j(`Strømmen river rebet med sig to gange, og det tager to timer; færgen sejler, men forspringet er vokset.`,`The current tears the rope away twice, and it takes two hours; the ferry runs, but the lead has grown.`)),N(`Wisdom (Insight)`,`easy`,j(`{npc3} indrømmer den ekstra sølvmønt for at sejle før solopgang og fortæller, at en af graverne blev tilbage på denne bred "for at gøre noget ved rebet".`,`{npc3} admits to taking the extra silver coin for crossing before sunrise and says that one of the diggers stayed behind on this bank "to see to the rope".`),j(`{npc3} bander kun over rebet; heltene hører intet om sølvmønten.`,`{npc3} only swears about the rope; the heroes hear nothing of the silver coin.`))],fight:!1,alternatives:[j(`Tag jollen: Det går hurtigere end at splejse rebet, men færgen kan ikke sejle ved solnedgang, og heltene må finde en anden vej hjem med rødderne.`,`Take the skiff: it is quicker than splicing the rope, but the ferry cannot run at sunset, and the heroes must find another way home with the roots.`),j(`Vis {npc3} rodkniven: Færgemanden kender apotekets mærke, og for at få ram på {villain} ror {npc3} selv heltene over i jollen og venter ved den anden bred med et nyt reb.`,`Show {npc3} the root knife: the ferryman knows the apothecary’s mark, and to get back at {villain}, {npc3} rows the heroes over in the skiff and waits at the far bank with a new rope.`)],dmNotes:j(`Færgelejet er kapløbets første forhindring og den sidste færges ur: Lad færgemanden sige højt, hvornår færgen skal op for vinteren, og lad spillerne vælge mellem en hurtig vej over og en sikker vej hjem.`,`The ferry landing is the race’s first obstacle and the last ferry’s clock: let the ferryman say aloud when the ferry goes up for the winter, and let the players choose between a quick way across and a safe way home.`)},{kind:`combat`,at:`town`,present:[`npc2`],title:j(`Den falske sti`,`The False Path`),summary:j([`På den anden side går stien ud i kæret mellem pil og siv, og kortet fra færgekroen viser en lige vej over en grøn flade til øen med klosterruinen.`,`Den grønne flade er hængedynd, og i sivene omkring den har nogle {foe} deres jagtmark; de venter på det, der synker.`,`Kun {npc2} kender den rigtige sti i en bue langs pilene, og her afgøres det, om heltene kan indhente forspringet.`],[`On the far side the path runs out into the fen between willow and reed, and the map from the ferry inn shows a straight way across a green flat to the island with the ruined abbey.`,`The green flat is quaking bog, and in the reeds around it some {foe} have their hunting ground; they wait for whatever sinks.`,`Only {npc2} knows the true path, curving along the willows, and here it is decided whether the heroes can close the gap.`]),readAloud:j([`Kæret er en verden af siv, højere end en rytter, og stierne er smalle striber af fast jord mellem sort vand.`,`Foran heltene åbner sivene sig mod en flade af grønt, så jævn som en eng, og langt ude på den anden side rejser klosterruinen sig.`,`Det er helt stille; ikke en fugl synger over den grønne flade.`],[`The fen is a world of reeds taller than a rider, and the paths are narrow strips of firm ground between black water.`,`Ahead of you the reeds open onto a flat of green, as smooth as a meadow, and far off on the other side the ruined abbey rises.`,`It is utterly still; not a bird sings over the green flat.`]),details:[j(`Den grønne flade er hængedynd: et tæppe af mos over bundløst mudder, der bærer et barn, men ikke en voksen med oppakning. Den, der går ud på den, synker til livet efter ti skridt. {npc2} kender sin egen tegning igen i kortet og ser straks, at stien er flyttet.`,`The green flat is quaking bog: a carpet of moss over bottomless mud that will bear a child but not a grown traveller with a pack. Whoever walks out onto it sinks to the waist within ten steps. {npc2} recognises their own drawing in the map and sees at once that the path has been moved.`),j(`Nogle {foe} har deres jagtmark i sivene om hængedyndet og angriber, når heltene er ude på den grønne flade eller står fast i mudderet; de trækker sig tilbage ind i sivene, når halvdelen er faldet.`,`Some {foe} have their hunting ground in the reeds around the quaking bog and attack when the heroes are out on the green flat or stuck in the mud; they fall back into the reeds once half of them are down.`),j(`Den rigtige sti går i en bue langs pilene til den gamle stendæmning, munkene byggede ud til øen; den er en time længere end den falske, men fast hele vejen. Fra dæmningen kan man se røgen fra {villain}s bål i klosterhaven.`,`The true path curves along the willows to the old stone dyke the monks built out to the island; it is an hour longer than the false one but firm all the way. From the dyke the smoke of {villain}’s fire can be seen in the abbey garden.`)],checks:[N(`Wisdom (Survival)`,`medium`,j(`Heltene ser, at intet dyr har trådt på den grønne flade, og at sivene omkring den er trampet ned: De går uden om og finder fast grund langs pilene.`,`The heroes see that no animal has set foot on the green flat and that the reeds around it are trampled: they go round and find firm ground along the willows.`),j(`Den forreste helt synker til livet i hængedyndet; de andre får vedkommende op med reb, men kampen begynder, mens heltene står i mudderet.`,`The lead hero sinks to the waist in the quaking bog; the others haul them out with a rope, but the fight begins while the heroes are still in the mud.`)),N(`Strength (Athletics)`,`medium`,j(`Heltene kæmper sig frem til en pilerod og får fast grund under fødderne; kampen bliver lettere.`,`The heroes fight their way to a willow root and get firm ground underfoot; the fight gets easier.`),j(`Mudderet holder heltene fast; kampen bliver hårdere, til nogen finder en pilerod at stå på.`,`The mud holds the heroes fast; the fight is harder until someone finds a willow root to stand on.`))],fight:!0,alternatives:[j(`Lad {npc2} gå forrest: Ålefangeren fører heltene uden om hængedyndet og det meste af kampen, men det koster en time, og {npc2} må hvile undervejs.`,`Let {npc2} lead: the eel-catcher takes the heroes round the quaking bog and clear of most of the fight, but it costs an hour, and {npc2} must rest on the way.`),j(`Læg broer af siv: Med knipper af skårne siv lagt i rækker kan heltene gå over kanten af hængedyndet og spare en halv time, men knipperne larmer, og nogle {foe} kommer straks.`,`Lay bridges of reeds: with bundles of cut reeds laid in rows the heroes can cross the edge of the quaking bog and save half an hour, but the bundles are noisy, and some {foe} come at once.`)],dmNotes:j(`Hængedyndet er den egentlige fjende på den falske sti: Lad den grønne flade se fredelig ud, og lad stilheden være advarslen. Lad heltene se klosterruinen og røgen hele tiden, så de ved, hvor tæt kapløbet er.`,`The quaking bog is the real enemy on the false path: let the green flat look peaceful, and let the silence be the warning. Let the heroes see the ruined abbey and the smoke the whole time, so they know how close the race is.`)},{kind:`exploration`,at:`site`,present:[`npc2`,`villain`],title:j(`Porten til klosteret`,`The Abbey Gate`),summary:j([`Stendæmningen ender ved den gamle port til klosteret, hvor to af {villain}s gravere holder vagt med spader; bag muren ligger haven med liljedammen.`,`Graverne er lejet for en dagløn og vil ikke slås, men de har ordre til at holde alle ude, til kurvene er fulde, og de brokker sig over, at de skal hjem med apotekets egen pram og ikke med færgen.`,`Heltene skal ind i haven: forbi graverne, over den sammenstyrtede mur ved munkecellerne, hvor noget har sit leje, eller ved at vinde graverne over på deres side.`],[`The stone dyke ends at the old gate of the abbey, where two of {villain}’s diggers stand guard with spades; behind the wall lies the garden with the lily pond.`,`The diggers are hired for a day’s wage and will not fight, but they are under orders to keep everyone out until the baskets are full, and they grumble that they are to go home on the apothecary’s own barge and not the ferry.`,`The heroes must get into the garden: past the diggers, over the fallen wall by the monks’ cells, where something has its lair, or by winning the diggers over to their side.`]),readAloud:j([`Klosterporten er en bue af grå sten, og selve porten er for længst rådnet væk; i stedet står to gravere med mudrede spader og spærrer vejen.`,`Gennem buen ses en vildtvoksende have og midt i den en dam, hvor hvide blomster flyder mellem brune, oprodede blade.`,`Ved dammens bred sidder en skikkelse i en fin, grøn kappe og lægger rødder i en kurv, én ad gangen.`],[`The abbey gate is an arch of grey stone, and the gate itself rotted away long ago; instead two diggers with muddy spades bar the way.`,`Through the arch you see a wild garden, and in the middle of it a pond where white flowers float among brown, uprooted leaves.`,`On the bank of the pond sits a figure in a fine green coat, laying roots in a basket one at a time.`]),details:[j(`Graverne er lejet i {town} for en dagløn og har ingen lyst til at slås. De brokker sig over, at apotekeren lod en af dem blive tilbage ved floden ved daggry "for at gøre noget ved rebet", og at de skal hjem med apotekets pram, der ligger skjult i sivene bag klostret, og ikke med færgen.`,`The diggers were hired in {town} for a day’s wage and have no wish to fight. They grumble that the apothecary left one of them behind by the river at dawn "to see to the rope", and that they are to go home on the apothecary’s barge, hidden in the reeds behind the abbey, not the ferry.`),j(`Fra porten kan man se, at dammen er halvt gravet op, og at kurvene på bredden er fulde af rødder; {villain} sorterer dem, for kun apotekeren kan kende de rigtige fra de almindelige. Bag klostret fører et frisk spor af slæbte kurve ned gennem sivene til prammen.`,`From the gate one can see that the pond is half dug up and that the baskets on the bank are full of roots; {villain} sorts them, for only the apothecary can tell the true ones from the common ones. Behind the abbey a fresh trail of dragged baskets leads down through the reeds to the barge.`),j(`Ved munkecellerne er muren styrtet sammen, og den, der klatrer over, kommer ind i haven uden om porten; men cellerne er mørke og stinker, og {npc2} siger, at noget har haft sit leje dér, siden munkene gik. Råber heltene til {villain}, tilbyder apotekeren dem penge for at gå hjem eller for at bære kurvene til prammen.`,`By the monks’ cells the wall has fallen in, and whoever climbs over gets into the garden without passing the gate; but the cells are dark and reek, and {npc2} says something has laired there since the monks left. If the heroes call out to {villain}, the apothecary offers them money to go home, or to carry the baskets to the barge.`)],checks:[N(`Dexterity (Stealth)`,`medium`,j(`Heltene klatrer over muren ved munkecellerne uden at vække det, der sover dernede, og står i haven, før {villain} ved, at de er kommet.`,`The heroes climb the wall by the monks’ cells without waking what sleeps there, and stand in the garden before {villain} knows they have come.`),j(`Sten rasler ned i cellerne, og noget rører sig i mørket; heltene når haven, men det, der bor i cellerne, er vågent.`,`Stones rattle down into the cells and something stirs in the dark; the heroes reach the garden, but whatever lives in the cells is awake.`)),N(`Charisma (Persuasion)`,`medium`,j(`Heltene fortæller graverne om kniven i færgerebet og om floden, der kommer i nat; de vil ikke strande i kæret for apotekerens skyld og træder til side.`,`The heroes tell the diggers about the cut ferry rope and the flood coming tonight; unwilling to be stranded in the fen for the apothecary’s sake, the diggers step aside.`),j(`Graverne tror ikke på heltene og råber på {villain}, der nu ved, at kapløbet ikke er vundet endnu.`,`The diggers do not believe the heroes and shout for {villain}, who now knows the race is not won yet.`))],fight:!1,alternatives:[j(`Tag prammen: Uden prammen kan {villain} ikke få kurvene over floden, og apotekeren må forhandle med den, der holder fortøjningen.`,`Take the barge: without it, {villain} cannot get the baskets across the river, and the apothecary must bargain with whoever holds the mooring rope.`),j(`Gå lige ind ad porten: Graverne viger for våben, men løber straks til {villain}, og kampen om dammen begynder, før heltene er klar.`,`Walk straight in at the gate: the diggers give way at the sight of weapons but run at once to {villain}, and the fight for the pond begins before the heroes are ready.`)],dmNotes:j(`Porten er kapløbets valg: tre veje ind, hver med sin pris. Lad spillerne se kurvene blive fyldt på bredden og solen synke, så de mærker, at færgen venter.`,`The gate is the race’s choice: three ways in, each with its price. Let the players see the baskets filling on the bank and the sun sinking, so they feel the ferry waiting.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`,`npc2`],title:j(`Liljedammen før solnedgang`,`The Lily Pond before Sunset`),summary:j([`Midt på eftermiddagen sidder {villain} selv ved liljedammen i {place} og sorterer de sidste rødder, mens graverne bærer kurvene mod den skjulte pram.`,`Larmen og rodet i dammen har vækket {boss} og nogle {foe} i de sammenstyrtede munkeceller, og de kommer ud i haven mod alle, der er der.`,`Heltene skal klare sig forbi {boss}, hindre {villain} i at kaste de gode rødder i dammen eller slippe væk med dem, og nå færgen, før den bliver trukket op ved solnedgang.`],[`In mid-afternoon {villain} sits by the lily pond at {place}, sorting the last roots while the diggers carry baskets toward the hidden barge.`,`The noise and the churned-up pond have woken {boss} and some {foe} in the collapsed monks’ cells, and they come out into the garden and go for everyone there.`,`The heroes must get past {boss} and stop {villain} from throwing the good roots into the pond or escaping with them, then reach the ferry before it is drawn up at sunset.`]),readAloud:j([`Haven er et virvar af brændenælder og vildtvoksende urter, og over det hele hænger lugten af mudder og knuste blade.`,`Dammen er brun og oprodet, og på bredden står kurv ved kurv med hvide rødder.`,`Fra de sammenstyrtede celler bag haven lyder en skraben og et brag af sten, der vælter, og graverne taber deres spader.`],[`The garden is a tangle of nettles and wild herbs, and over all of it hangs the smell of mud and crushed leaves.`,`The pond is brown and churned up, and on the bank stands basket after basket of white roots.`,`From the collapsed cells behind the garden comes a scraping and the crash of falling stones, and the diggers drop their spades.`]),details:[j(`{boss} og nogle {foe} har haft deres leje i munkecellerne, længe før nogen gravede i dammen; de tjener ingen og angriber alt, hvad der er i haven, også graverne, der flygter mod prammen. {villain} kæmper ikke, men truer med at kaste de gode rødder ud i det dybe vand midt i dammen, hvor ingen kan finde dem før foråret.`,`{boss} and some {foe} have laired in the monks’ cells since long before anyone dug in the pond; they serve no one and attack anyone in the garden, even the diggers, who flee toward the barge. {villain} does not fight, but threatens to throw the good roots into the deep water in the middle of the pond, where nobody can find them before spring.`),j(`Rødderne skal bæres i kurve tilbage ad stendæmningen og stien langs pilene; det tager to timer, og færgen bliver trukket op ved solnedgang. Har heltene splejset færgerebet, venter {npc3} ved den anden bred; ellers må de nå jollen eller tage {villain}s pram.`,`The roots must be carried in baskets back along the stone dyke and the path by the willows; that takes two hours, and the ferry is drawn up at sunset. If the heroes spliced the ferry rope, {npc3} is waiting at the far bank; otherwise they must reach the skiff or take {villain}’s barge.`),j(`Bliver {villain} trængt op i en krog, eller kommer {boss} for tæt på, forhandler apotekeren: halvdelen af rødderne for en sikker vej til prammen, eller bare et løfte om ikke at blive efterladt i kæret. {npc2} kan kende de rigtige rødder lige så godt som {villain} og vil fylde en kurv til sygestuen, før noget andet sker.`,`If {villain} is cornered, or {boss} comes too close, the apothecary bargains: half the roots for safe passage to the barge, or just a promise not to be left in the fen. {npc2} can pick out the true roots as well as {villain} can and wants to fill a basket for the sickroom before anything else happens.`)],checks:[N(`Dexterity (Acrobatics)`,`medium`,j(`En helt springer over kurvene og griber {villain}s arm, før de gode rødder ryger i dammen.`,`A hero leaps over the baskets and catches {villain}’s arm before the good roots go into the pond.`),j(`En kurv ryger i dammen; heltene kan dykke efter rødderne i det mudrede vand, men det koster en halv time.`,`One basket goes into the pond; the heroes can dive for the roots in the muddy water, but it costs half an hour.`)),N(`Strength (Athletics)`,`medium`,j(`Heltene får kurvene på ryggen og hele vejen tilbage ad stendæmningen i god tid; færgen venter, og kapløbet mod solnedgangen er vundet.`,`The heroes shoulder the baskets and get them all the way back along the stone dyke in good time; the ferry is waiting, and the race against sunset is won.`),j(`Kurvene er tunge, og vandet stiger allerede på stien; heltene må efterlade halvdelen eller løbe det sidste stykke i tusmørket.`,`The baskets are heavy and the water is already rising on the path; the heroes must leave half behind or run the last stretch in the dusk.`))],fight:!0,alternatives:[j(`Lad {npc2} fylde kurvene: Mens heltene holder {boss} væk fra dammen, graver og sorterer ålefangeren, og der er rødder nok til sygestuen, selv om {villain} slipper væk med resten.`,`Let {npc2} fill the baskets: while the heroes keep {boss} away from the pond, the eel-catcher digs and sorts, and there are roots enough for the sickroom even if {villain} escapes with the rest.`),j(`Vis {villain} rodkniven fra færgelejet: Med beviset på det kappede reb vil ingen i {town} købe så meget som en rod på apoteket igen, og apotekeren har intet at vinde ved at kaste dem i dammen; {villain} beder i stedet om en plads på færgen.`,`Show {villain} the root knife from the ferry landing: with proof of the cut rope, nobody in {town} will buy so much as a root at the apothecary’s again, and the apothecary has nothing to gain by throwing the roots in the pond; instead {villain} begs for a place on the ferry.`)],dmNotes:j(`Lad solen være uret: Sig højt hver runde, hvor lavt den står, og lad kurvene blive tungere. Spil {villain} som en fin borger, der aldrig før har stået i mudder, ikke som en kriger; det stærkeste øjeblik er, når {npc2} holder en rigtig rod op, og graverne forstår, hvem de har arbejdet for.`,`Let the sun be the clock: say aloud each round how low it hangs, and let the baskets grow heavier. Play {villain} as a genteel townsperson who has never stood in mud before, not as a fighter; the strongest moment is when {npc2} holds up a true root and the diggers understand whom they have been working for.`)}},rt=e({kernel:()=>st,scenes:()=>ct}),it=e=>Array.isArray(e)?e.join(` `):e,P=(e,t)=>({da:it(e),en:it(t)}),at=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),F=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},ot=(e,t,n)=>({when:e,event:t,sign:n}),I=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),st={id:`explore-the-star-tower`,titles:[P(`Stjernetårnet`,`The Star Tower`),P(`Når vandrerne mødes`,`When the Wanderers Meet`),P(`Hundrede år bag bronzedøren`,`A Hundred Years behind the Bronze Door`)],missions:[`exploration`],foes:`hirelings`,roles:{npc1:P(`en almanakskriver, hvis oldemor var den sidste stjernelæser i tårnet`,`an almanac-maker whose great-grandmother was the last star-reader in the tower`),npc2:P(`en vogter af den slægt, der har vogtet porten til tårnets gård i hundrede år`,`a warden from the family that has kept the gate to the tower’s courtyard for a hundred years`),npc3:P(`en muldyrdriver, som {villain} har hyret til at vente ved klippefoden`,`a mule driver whom {villain} has hired to wait at the foot of the cliff`),villain:P(`en lærd samler fra hovedstaden, der har fået rådets lov til at gå først ind i tårnet`,`a learned collector from the capital who has the council’s leave to enter the tower first`)},hook:P(`{npc1} indhenter heltene ved foden af bjergvejen i skumringen med en afskrift af oldemoderens tegning af tårnet og beder dem gå op og kortlægge {place} helt op til stjernehjulet i kuplen og tegne hjulet af, før bronzedøren lukker sig ved daggry i hundrede år.`,`{npc1} catches up with the heroes at the foot of the mountain road at dusk, carrying a copy of {npc1}’s great-grandmother’s drawing of the tower, and asks them to go up and chart {place} all the way to the star wheel in the dome, and to draw the wheel before the bronze door closes at dawn for a hundred years.`),people:{npc1:{wants:P(`Vil have stjernehjulet og kuplens stjernekort tegnet af, så {town} kan få en almanak for de næste hundrede år.`,`Wants the star wheel and the dome’s star chart drawn, so that {town} can have an almanac for the next hundred years.`),secret:P(`Solgte i vinter oldemoderens dagbog med tårnets tegninger til {villain} for at betale en gæld; det var dagbogen, der viste {villain}, hvad der sidder i stjernehjulet.`,`Sold their great-grandmother’s diary with the tower’s drawings to {villain} last winter to pay a debt; it was the diary that showed {villain} what the star wheel holds.`)},npc2:{wants:P(`Vil holde slægtens ed og se tårnet lukke sig igen ved daggry, uden at noget er forsvundet.`,`Wants to keep the family’s oath and see the tower close again at dawn with nothing missing.`),secret:P(`Kender slægtens gamle rim om, at stjernehjulets fod tæller hver eneste stjerne, men har aldrig sagt det til nogen uden for slægten, fordi eden forbyder det.`,`Knows the family’s old rhyme that the star wheel’s base counts every single star, but has never shared it with anyone outside the family, because the oath forbids it.`)},npc3:{wants:P(`Vil have sin løn og komme hjem med alle tolv muldyr i god behold.`,`Wants their wages and to get home with all twelve mules safe and sound.`),secret:P(`Har fået dobbelt løn for at køre ad den gamle bagvej mod hovedstaden ved daggry uden om {town} og har regnet ud, at ingen ærlig last tager den vej.`,`Has been paid double to take the old back road toward the capital at dawn without passing through {town}, and has worked out that no honest load goes that way.`)}},premise:P([`For hundrede år siden forseglede stjernelæserne {place}, deres tårn på bjerget over {town}, og efterlod byen en almanak for hundrede år og en ed: {npc2}s slægt skulle vogte porten, til de to vandrere igen stod sammen over tinden.`,`I nat sker det, og bronzedøren står åben til daggry; øverst under kuplen drejer stjernehjulet stadig, et bronzeinstrument med tolv krystalstjerner, der viser himlen for de næste hundrede år, netop som byens almanak løber ud.`,`{villain}, en lærd samler fra hovedstaden, har fået rådets lov til at gå først ind, men har solgt hjulets stjerner og bronzehjerte til en fyrste og vil fire dem ned ad klippen fra kuplens galleri i nat.`,`Ved daggry lukker døren sig i hundrede år, og {villain} vil gå ud alene med vogternes stjålne lygte i hånden og give slægten skylden.`],[`A hundred years ago the star-readers sealed {place}, their tower on the mountain above {town}, and left the town an almanac for a hundred years and an oath: {npc2}’s family was to keep the gate until the Two Wanderers stood together over the peak again.`,`Tonight it happens, and the bronze door stands open until dawn; at the top, beneath the dome, the star wheel still turns, a bronze instrument with twelve crystal stars that shows the sky for the next hundred years, just as the town’s almanac runs out.`,`{villain}, a learned collector from the capital, has the council’s leave to go in first, but has sold the wheel’s stars and bronze heart to a prince and means to lower them down the cliff from the dome gallery tonight.`,`At dawn the door closes for a hundred years, and {villain} means to walk out alone with the wardens’ stolen lantern in hand and put the blame on the family.`]),goal:P(`Kortlæg {place} helt op til kuplen, hold stjernehjulet helt, og bring tegningen af hjulet og stjernekortet ned til {town}, før bronzedøren lukker sig ved daggry.`,`Chart {place} all the way up to the dome, keep the star wheel whole, and bring the drawing of the wheel and the star chart down to {town} before the bronze door closes at dawn.`),objective:{target:P(`Stjernehjulet i kuplen med sine tolv krystalstjerner og sit bronzehjerte`,`The star wheel in the dome, with its twelve crystal stars and its bronze heart`),state:P(`I kuplen øverst i {place}, hvor hjulet har drejet i hundrede år. Fra døren går op, står {villain} selv deroppe med {npc1}s oldemors dagbog, og fra midnat skruer {boss} og nogle {foe} krystalstjernerne af og fire dem ned ad klippen fra kuplens galleri; til sidst, lige før daggry, skal bronzehjertet, tandhjulet der bærer hjulets kalender, samme vej.`,`In the dome at the top of {place}, where the wheel has turned for a hundred years. From the moment the door opens, {villain} is up there in person with {npc1}’s great-grandmother’s diary, and from midnight {boss} and some {foe} unscrew the crystal stars and lower them down the cliff from the dome gallery. Last of all, just before dawn, the bronze heart, the gear that carries the wheel’s calendar, is to go the same way.`),resolution:P([`Hold stjernehjulet helt, eller få krystalstjernerne og bronzehjertet tilbage, og tegn hjulet og kuplens stjernekort af, før døren lukker sig ved daggry.`,`Er hjulet allerede plyndret, er en tegning af hjulets fod, hvor stjernelæserne huggede tal og vægt for hver stjerne, beviset på, hvad {villain} tog, og at vogterne er uskyldige.`],[`Keep the star wheel whole, or get the crystal stars and the bronze heart back, and draw the wheel and the dome’s star chart before the door closes at dawn.`,`If the wheel has already been plundered, a drawing of the wheel’s base, where the star-readers carved the number and weight of every star, proves what {villain} took and that the wardens are innocent.`])},villain:{want:P(`At sælge stjernehjulets krystalstjerner og bronzehjerte til en fyrste i hovedstaden, der samler på vidundere, og at forlade {town} som den lærde, der reddede, hvad der kunne reddes.`,`To sell the star wheel’s crystal stars and bronze heart to a prince in the capital who collects wonders, and to leave {town} as the scholar who saved what could be saved.`),plan:P([`Først købte {villain} i vinter {npc1}s oldemors dagbog med tårnets tegninger, fik rådets lov til at gå først ind "for at beskytte instrumentet" og tog i går nøglerne fra {npc2}s slægt; en uge før forsvandt slægtens gamle bronzelygte fra vogterhuset under {villain}s besøg.`,`I nat lader {villain} {boss} og sine lejede {foe} skrue krystalstjernerne af og fire dem ned ad klippen fra kuplens galleri til {npc3}s muldyr, der kører ad bagvejen mod hovedstaden ved daggry.`,`Lige før døren lukker sig, går {villain} ud alene med lygten fra vogterhuset i hånden, "fundet ved det plyndrede hjul", og anklager vogterne, mens døren lukker sig om beviset i hundrede år.`],[`First, {villain} bought {npc1}’s great-grandmother’s diary with the tower’s drawings last winter, won the council’s leave to go in first "to protect the instrument" and took the keys from {npc2}’s family yesterday; a week before that, the family’s old bronze lantern vanished from the wardens’ house during {villain}’s visit.`,`Tonight {villain} has {boss} and the hired {foe} unscrew the crystal stars and lower them down the cliff from the dome gallery to {npc3}’s mules, which leave by the back road toward the capital at dawn.`,`Just before the door closes, {villain} walks out alone with the lantern from the wardens’ house in hand, "found by the plundered wheel", and accuses the wardens while the door closes on the evidence for a hundred years.`]),weakness:P([`{villain} har højdeskræk og vil ikke ned ad rebet fra galleriet, så {villain} må ud ad bronzedøren før daggry; den, der holder trappen, holder {villain}.`,`Og {villain} kan ikke læse stjernelæsernes gamle skrift og ved ikke, at de huggede tal og vægt for hver krystalstjerne i hjulets fod, så en tegning af foden viser præcis, hvad der mangler.`],[`{villain} is afraid of heights and will not go down the rope from the gallery, so {villain} must leave by the bronze door before dawn; whoever holds the stair holds {villain}.`,`And {villain} cannot read the star-readers’ old script and does not know that they carved the number and weight of every crystal star into the wheel’s base, so a drawing of the base shows exactly what is missing.`])},stakes:P(`Forsvinder krystalstjernerne og bronzehjertet, kan ingen nogensinde læse himlen af hjulet igen, og {town}, hvis gamle almanak løber ud i år, må så og høste i blinde. Lukker døren sig om et plyndret hjul, bliver {npc2}s slægt jaget fra bjerget som tyve, og {villain} sælger vidunderet i hovedstaden.`,`If the crystal stars and the bronze heart vanish, nobody can ever read the sky from the wheel again, and {town}, whose old almanac runs out this year, must sow and reap blind. If the door closes on a plundered wheel, {npc2}’s family is driven from the mountain as thieves, and {villain} sells the wonder in the capital.`),clock:{start:P(`Skumring. I nat står de to vandrere sammen over bjerget for første gang i hundrede år, og når deres lys falder gennem spalten i kuplen, går bronzedøren op. {villain} har rådets lov til at gå først ind, {npc2}s slægt er sendt bort fra porten, og bjergvejen op til tårnet tager to timer.`,`Dusk. Tonight the Two Wanderers stand together over the mountain for the first time in a hundred years, and when their light falls through the slit in the dome, the bronze door opens. {villain} has the council’s leave to go in first, {npc2}’s family has been sent away from the gate, and the mountain road up to the tower takes two hours.`),ticks:[ot(P(`Efter 2 timer (når vandrerne står op over tinden)`,`After 2 hours (when the Wanderers rise over the peak)`),P(`Lyset falder gennem spalten, bronzedøren glider op, og {villain} går ind med {boss} og sine lejede {foe}; de spænder reb og trisse fast på kuplens galleri og sænker rebet ned ad klippen.`,`The light falls through the slit, the bronze door slides open, and {villain} goes in with {boss} and the hired {foe}; they rig rope and pulley on the dome gallery and let the rope down the cliff.`),P(`En dyb, ren tone ruller ned ad bjerget, og en smal stribe lys står op fra kuplen.`,`A deep, clear note rolls down the mountain, and a thin blade of light rises from the dome.`)),ot(P(`Efter 5 timer (ved midnat)`,`After 5 hours (at midnight)`),P(`{villain} lader stjernehjulet standse, og {boss} og mandskabet begynder at skrue krystalstjernerne af; den første kasse går ned ad rebet fra galleriet til {npc3}s muldyr ved klippefoden.`,`{villain} has the star wheel stopped, and {boss} and the crew begin to unscrew the crystal stars; the first crate goes down the rope from the gallery to {npc3}’s mules at the foot of the cliff.`),P(`Den svage tikken, der har lydt i tårnet hele natten, holder op, og en lille kasse svinger ned ad klippen i skæret fra en lygte.`,`The faint ticking heard in the tower all night stops, and a small crate swings down the cliff in the glow of a lantern.`)),ot(P(`Efter 8 timer (ved daggry)`,`After 8 hours (at dawn)`),P(`Vandrerne går ned, lyset forlader spalten, og bronzedøren lukker sig i hundrede år; lige før går {villain} ud med vogternes lygte i hånden og råber, at vogterne har plyndret tårnet, mens den sidste kasse med bronzehjertet når klippefoden.`,`The Wanderers set, the light leaves the slit, and the bronze door closes for a hundred years; just before it does, {villain} walks out with the wardens’ lantern in hand, crying that the wardens have plundered the tower, while the last crate with the bronze heart reaches the foot of the cliff.`),P(`Sten skurer mod sten i hele tårnet, og bronzedøren begynder langsomt at glide i.`,`Stone grinds on stone throughout the tower, and the bronze door slowly begins to slide shut.`))],deadline:P(`Efter 8 timer, ved daggry, er det for sent: Bronzedøren er lukket i hundrede år om et plyndret hjul, {villain}s kasser er på vej mod hovedstaden, og hele {town} tror, at {npc2}s slægt har stjålet tårnets skat.`,`After 8 hours, at dawn, it is too late: the bronze door is closed for a hundred years on a plundered wheel, {villain}’s crates are on their way to the capital, and all of {town} believes that {npc2}’s family stole the tower’s treasure.`)},clues:{who:[F(`town`,P(`{npc2}, vogteren, har rådets brev, som {villain} viste frem ved porten i går: {villain} alene leder åbningen, og vogternes slægt skal aflevere nøglerne og blive nede i byen, til døren er lukket igen.`,`{npc2}, the warden, has the council’s letter that {villain} showed at the gate yesterday: {villain} alone leads the opening, and the wardens’ family is to hand over the keys and stay down in town until the door has closed again.`),P(`{villain} vil være alene i tårnet i nat og have vogterne langt væk.`,`{villain} wants to be alone in the tower tonight, with the wardens far away.`),at([`Fra rådet i {town}:`,`Den lærde {villain} leder åbningen af tårnet og går først ind for at beskytte instrumentet.`,`Vogternes slægt afleverer nøglerne og bliver i byen, til bronzedøren er lukket igen.`,`Tilføjet med {villain}s hånd: Ingen vogter må komme nær porten i nat.`],[`From the council of {town}:`,`The learned {villain} leads the opening of the tower and enters first to protect the instrument.`,`The wardens’ family hands over the keys and stays in town until the bronze door has closed again.`,`Added in {villain}’s hand: No warden is to come near the gate tonight.`])),F(`town`,P(`{npc3}, muldyrdriveren, er hyret af {villain} til at vente ved klippefoden med tolv muldyr og tage imod kasser, der skal fires ned ad klippen i et reb fra tårnets galleri.`,`{npc3}, the mule driver, has been hired by {villain} to wait at the foot of the cliff with twelve mules and take in crates that are to be lowered down the cliff on a rope from the tower’s gallery.`),P(`{villain} vil have noget ud af tårnet uden om bronzedøren og uden om {town}.`,`{villain} means to get something out of the tower without using the bronze door and without passing through {town}.`)),F(`town`,P(`{npc2} fortæller, at slægtens gamle bronzelygte med vogternes tegn forsvandt fra vogterhuset for en uge siden, samme dag som {villain} kom på besøg for at "studere eden".`,`{npc2} says that the family’s old bronze lantern with the wardens’ sign vanished from the wardens’ house a week ago, on the same day {villain} came visiting to "study the oath".`),P(`{villain} har taget lygten og vil bruge den til at give vogterne skylden for noget.`,`{villain} took the lantern and means to use it to put the blame for something on the wardens.`)),F(`site`,P(`På kuplens galleri ligger {villain}s ordre til mandskabet i en kasse ved trissen.`,`On the dome gallery, {villain}’s order to the crew lies in a crate by the pulley.`),P(`{villain} står bag plyndringen og vil give vogterne skylden med lygten fra vogterhuset.`,`{villain} is behind the plundering and means to blame the wardens with the lantern from the wardens’ house.`),at([`Til mandskabet:`,`Én krystalstjerne i hver kasse, pakket i halm, og fires ned fra galleriet til muldyrene. Hjertet tages ud til sidst, før daggry.`,`Lygten fra vogterhuset går med mig ud ad døren ved daggry. Rådet skal se, hvem der var her i nat. – {villain}`],[`To the crew:`,`One crystal star to each crate, packed in straw, and lowered from the gallery to the mules. The heart comes out last, before dawn.`,`The lantern from the wardens’ house goes out through the door with me at dawn. The council shall see who was here tonight. — {villain}`]))],where:[F(`town`,P(`{npc1}s afskrift af oldemoderens tegning viser vejen fra bronzedøren op ad stjernetrappen, galleriet om kuplen og øverst stjernehjulet med en note om hjulets fod.`,`{npc1}’s copy of their great-grandmother’s drawing shows the way from the bronze door up the star stair, the gallery round the dome and, at the top, the star wheel with a note about the wheel’s base.`),P(`Stjernehjulet står øverst i kuplen, og vejen derop går ad stjernetrappen forbi galleriet.`,`The star wheel stands at the top, in the dome, and the way up is by the star stair, past the gallery.`),at([`{place}, tegnet af den sidste stjernelæser:`,`Bronzedøren: åbner, når de to vandrere står sammen, og lukker, når de går ned. Stjernetrappen: tre hundrede trin.`,`Galleriet om kuplen, og i kuplen hjulet med de tolv stjerner og hjertet. Hjulets fod tæller dem alle.`],[`{place}, drawn by the last star-reader:`,`The bronze door: opens when the Two Wanderers stand together and closes when they set. The star stair: three hundred steps.`,`The gallery round the dome, and in the dome the wheel with the twelve stars and the heart. The wheel’s base counts them all.`])),F(`site`,P(`Ved stjernetrappens øverste trin har {villain}s folk sat kridtpile på væggen med ordet "hjulet" og tolv streger, og ingen af kasserne er kommet ned ad trappen igen.`,`By the top step of the star stair {villain}’s people have chalked arrows on the wall with the word "wheel" and twelve strokes, and none of the crates has come back down the stair.`),P(`{villain}s folk arbejder øverst i tårnet ved hjulet med tolv kasser, og kasserne skal ud ad en anden vej end trappen.`,`{villain}’s people are at work by the wheel at the top of the tower, with twelve crates that are meant to leave by some way other than the stair.`)),F(`site`,P(`På kuplens galleri er en trisse spændt fast til brystværnet, og i den nærmeste kasse ligger en krystalstjerne i halm, skruet løs med friske mærker i messingen.`,`On the dome gallery a pulley is lashed to the parapet, and in the nearest crate lies a crystal star in straw, unscrewed, with fresh marks in the brass.`),P(`Krystalstjernerne bliver skruet af hjulet i kuplen lige ovenover og firet ned ad klippen herfra.`,`The crystal stars are being unscrewed from the wheel in the dome just above and lowered down the cliff from here.`)),F(`town`,P(`Fra klippefoden kan man se lys i kuplen og et reb, der hænger fra galleriet ned til muldyrene, og hver gang rebet rykker, kommer en lille kasse ned.`,`From the foot of the cliff, light can be seen in the dome, and a rope hangs from the gallery down to the mules; every time the rope jerks, a small crate comes down.`),P(`Det, {villain}s folk tager, kommer fra kuplen øverst i tårnet og skal ud ad galleriet, ikke ad døren.`,`Whatever {villain}’s people are taking comes from the dome at the top of the tower and leaves by the gallery, not by the door.`))]},endings:{success:P(`Da bronzedøren lukker sig ved daggry, står heltene uden for porten med tegningen af hjulet, dets fod og kuplens stjernekort, og krystalstjernerne er reddet. {npc1} skriver en ny almanak for de næste hundrede år, {villain} må forklare rådet, hvorfor stjernerne lå i {villain}s kasser, og {npc2}s slægt får nøglerne tilbage og heltenes navne hugget ind i porten.`,`When the bronze door closes at dawn, the heroes stand outside the gate with the drawing of the wheel, its base and the dome’s star chart, and the crystal stars are saved. {npc1} writes a new almanac for the next hundred years, {villain} must explain to the council why the stars lay in {villain}’s crates, and {npc2}’s family gets the keys back and carves the heroes’ names into the gate.`),partial:P(`Heltene kommer ud med en tegning af hjulets fod og nogle af stjernerne, men {villain} slipper ned ad bjerget med resten, og døren lukker sig om et halvt plyndret hjul. Tegningen frikender {npc2}s slægt, men {npc1}s almanak får huller, hvor stjernerne mangler, og ingen kan bevise, hvilken fyrste der købte dem.`,`The heroes come out with a drawing of the wheel’s base and some of the stars, but {villain} gets down the mountain with the rest, and the door closes on a half-plundered wheel. The drawing clears {npc2}’s family, but {npc1}’s almanac has gaps where the stars are missing, and nobody can prove which prince bought them.`),failure:P(`Ved daggry lukker bronzedøren sig i hundrede år om et plyndret hjul. {villain} viser vogternes lygte frem på torvet i {town}, {npc2}s slægt bliver jaget fra bjerget som tyve, krystalstjernerne bliver solgt i hovedstaden, og {town} går ind i det første år i et århundrede uden en almanak.`,`At dawn the bronze door closes for a hundred years on a plundered wheel. {villain} holds up the wardens’ lantern in the square of {town}, {npc2}’s family is driven from the mountain as thieves, the crystal stars are sold in the capital, and {town} enters its first year in a century without an almanac.`)}},ct={opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc2`],title:P(`Almanakkens sidste år`,`The Almanac’s Last Year`),summary:P([`I skumringen indhenter {npc1}, en almanakskriver, heltene ved foden af bjergvejen under {place}, og med kommer {npc2}, en vogter, som {villain} i går sendte ned fra tårnets port.`,`{npc1} beder heltene gå op og kortlægge tårnet helt op til stjernehjulet i kuplen og tegne hjulet af, før bronzedøren lukker sig ved daggry i hundrede år; {npc2} fortæller om eden, om rådets brev og om slægtens forsvundne lygte.`,`Byen og bjerget kan give flere svar, men hver omvej koster tid, og oppe på tinden venter {villain} allerede ved døren.`],[`At dusk {npc1}, an almanac-maker, catches up with the heroes at the foot of the mountain road below {place}, and {npc2}, a warden whom {villain} sent down from the tower’s gate yesterday, comes along.`,`{npc1} asks the heroes to go up and chart the tower all the way to the star wheel in the dome, and to draw the wheel before the bronze door closes at dawn for a hundred years; {npc2} tells of the oath, the council’s letter and the family’s missing lantern.`,`There are more answers in town and on the mountain, but every detour costs time, and up on the peak {villain} is already waiting at the door.`]),readAloud:P([`Over {town} rejser bjerget sig sort mod en himmel, der langsomt fyldes med stjerner, og helt oppe på tinden står et tårn med en kuppel af grønt kobber.`,`Lavt i øst står to klare stjerner så tæt sammen, at de næsten rører hinanden, og alle på vejen standser og ser op.`,`Ved bjergvejens første sving venter en almanakskriver med blæk på fingrene og en papirrulle under armen, og ved siden af står en vogter i en slidt grå kappe og ser op mod tårnet med sammenbidte kæber.`],[`Above {town} the mountain rises black against a sky slowly filling with stars, and at the very top of the peak stands a tower with a dome of green copper.`,`Low in the east two bright stars stand so close together that they almost touch, and everyone on the road stops and looks up.`,`At the first bend of the mountain road an almanac-maker waits with inky fingers and a roll of paper under one arm, and beside the almanac-maker stands a warden in a worn grey cloak, jaw clenched, looking up at the tower.`]),details:[P(`Byens almanak, som stjernelæserne skrev for hundrede år, før de forseglede tårnet, slutter med denne høst. {npc1}s afskrift af oldemoderens tegning viser bronzedøren, stjernetrappen, galleriet om kuplen og øverst stjernehjulet med en note: "Hjulets fod tæller stjernerne." Med en tegning af hjulet og kuplens stjernekort kan {npc1} skrive almanakken for de næste hundrede år.`,`The town’s almanac, which the star-readers wrote to last a hundred years before they sealed the tower, ends with this harvest. {npc1}’s copy of their great-grandmother’s drawing shows the bronze door, the star stair, the gallery round the dome and, at the top, the star wheel with a note: "The wheel’s base counts the stars." With a drawing of the wheel and the dome’s star chart, {npc1} can write the almanac for the next hundred years.`),P(`{npc2}s slægt har vogtet porten til tårnets gård i hundrede år, men har aldrig sat sin fod bag bronzedøren; det forbyder eden. I går kom {villain} med rådets brev, tog nøglerne og sendte {npc2} ned fra bjerget. Slægtens gamle bronzelygte med vogternes tegn forsvandt fra vogterhuset for en uge siden, samme dag som {villain} kom på besøg for at "studere eden".`,`{npc2}’s family has kept the gate to the tower’s courtyard for a hundred years but has never set foot beyond the bronze door; the oath forbids it. Yesterday {villain} came with the council’s letter, took the keys and sent {npc2} down the mountain. The family’s old bronze lantern with the wardens’ sign vanished from the wardens’ house a week ago, on the same day {villain} came visiting to "study the oath".`),P(`Bjergvejen op til porten tager to timer. En sti fører uden om til klippefoden under tårnets galleri, hvor {npc3}, en muldyrdriver, venter med muldyr, som {villain} har lejet; den omvej koster en halv time. Ethvert andet besøg i byen koster også en halv time.`,`The mountain road up to the gate takes two hours. A path leads round to the foot of the cliff below the tower’s gallery, where {npc3}, a mule driver, waits with mules {villain} has hired; that detour costs half an hour. Any other visit in town also costs half an hour.`)],checks:[I(`Wisdom (Insight)`,`medium`,P(`{npc1} tilstår at have solgt oldemoderens dagbog med tårnets tegninger til {villain} i vinter for at betale en gæld. Dagbogen beskriver krystalstjernerne i hjulet, og nu frygter {npc1}, hvad {villain} vil med dem.`,`{npc1} confesses to selling their great-grandmother’s diary with the tower’s drawings to {villain} last winter to pay a debt. The diary describes the crystal stars in the wheel, and now {npc1} fears what {villain} wants with them.`),P(`{npc1} virker bare ivrig og nervøs. Heltene hører først om dagbogen, når de selv nævner {villain}.`,`{npc1} seems merely eager and nervous. The heroes do not hear about the diary until they mention {villain} themselves.`)),I(`Intelligence (History)`,`easy`,P(`Heltene kender sagnet om stjernelæserne: De huggede tal og vægt for hver krystalstjerne ind i hjulets fod, så en tegning af foden viser præcis, hvad hjulet skal bære.`,`The heroes know the tale of the star-readers: they carved the number and weight of every crystal star into the wheel’s base, so a drawing of the base shows exactly what the wheel should carry.`),P(`Noten på tegningen siger heltene intet. De forstår først, hvad den betyder, når de står ved hjulets fod.`,`The note on the drawing means nothing to the heroes. They do not understand it until they stand at the wheel’s base.`))],fight:!1,alternatives:[P(`Gå direkte op ad bjergvejen: Heltene sparer omvejen, men ved intet om rebet fra galleriet, før de selv ser det.`,`Go straight up the mountain road: the heroes save the detour, but know nothing of the rope from the gallery until they see it themselves.`),P(`Tag {npc2} med op: Vogteren kender en gammel sti forbi porten, som {villain}s folk ikke vogter, men eden forbyder {npc2} at gå længere end til bronzedøren.`,`Take {npc2} along: the warden knows an old path past the gate that {villain}’s people do not guard, but the oath forbids {npc2} to go further than the bronze door.`)],dmNotes:P(`Lad de to stjerner stå på himlen hele aftenen, og lad dem rykke tættere sammen, hver gang spillerne ser op. Tårnet er et vidunder, ikke en fælde: Sig højt, hvad hver omvej koster, og lad {npc2}s vrede vise, hvad der står på spil for slægten.`,`Keep the two stars in the sky all evening and let them draw closer each time the players look up. The tower is a wonder, not a trap: say aloud what every detour costs, and let {npc2}’s anger show what is at stake for the family.`)},middle:[{kind:`social`,at:`town`,present:[`npc3`],title:P(`Muldyrene ved klippefoden`,`The Mules at the Cliff Foot`),summary:P([`Ved klippefoden under tårnets galleri venter {npc3}, en muldyrdriver, med tolv muldyr med tomme kløvsadler.`,`{villain} har hyret {npc3} til at tage imod kasser, der skal fires ned ad klippen fra galleriet, og til at køre ved daggry; herfra kan man se lys i kuplen og et reb, der hænger ned fra galleriet.`,`Heltene kan vinde {npc3} for sig og spolere {villain}s vej ud eller i det mindste se, hvor kasserne skal hen.`],[`At the foot of the cliff below the tower’s gallery, {npc3}, a mule driver, waits with twelve mules under empty packsaddles.`,`{villain} has hired {npc3} to take in crates that are to be lowered down the cliff from the gallery, and to drive off at dawn; from here, light can be seen in the dome, and a rope hangs down from the gallery.`,`The heroes can win {npc3} over and spoil {villain}’s way out, or at least see where the crates are meant to go.`]),readAloud:P([`Stenuren under tårnet ligger hvid i stjernelyset, og tolv muldyr står bundet i en række og tygger i deres mulekurve.`,`En muldyrdriver sidder på en sten med en lygte mellem knæene og ser op ad klippen, hvor et reb hænger ned fra et galleri langt deroppe og svajer i vinden.`,`Fra kuplen over galleriet falder en smal stribe gyldent lys ud i natten.`],[`The scree below the tower lies white in the starlight, and twelve mules stand tethered in a row, chewing in their nosebags.`,`A mule driver sits on a stone with a lantern between their knees, looking up the cliff, where a rope hangs from a gallery far above and sways in the wind.`,`From the dome above the gallery a thin strip of golden light falls out into the night.`]),details:[P(`{villain} har hyret {npc3} med tolv muldyr. Kasserne skal fires ned ad klippen fra galleriet, læsses på dyrene og køres bort ved daggry ad en vej, som {npc3} helst ikke vil tale om.`,`{villain} has hired {npc3} and twelve mules. The crates are to be lowered down the cliff from the gallery, loaded onto the animals and driven off at dawn by a road {npc3} would rather not talk about.`),P(`Rebet kom ned ad klippen, lige efter bronzedøren gik op, og hænger i en trisse på galleriet. Fra midnat kommer kasserne ned én ad gangen, hver med en krystalstjerne i halmen. Den, der klatrer op ad rebet, når galleriet på en halv time uden at gå ad stjernetrappen.`,`The rope came down the cliff just after the bronze door opened and hangs from a pulley on the gallery. From midnight the crates come down one at a time, each with a crystal star in the straw. Whoever climbs the rope reaches the gallery in half an hour without taking the star stair.`),P(`Nægter {npc3} at læsse, bliver kasserne stående ved klippefoden, og {villain}s plan om at få stjernerne ud uden om {town} falder fra hinanden. Men {npc3} har brug for lønnen og frygter {villain}s lejede folk mere end heltene.`,`If {npc3} refuses to load, the crates stay at the foot of the cliff, and {villain}’s plan to get the stars out without passing through {town} falls apart. But {npc3} needs the pay and is more afraid of {villain}’s hired hands than of the heroes.`)],checks:[I(`Charisma (Persuasion)`,`medium`,P(`{npc3} lover at lade kasserne stå og gemme dem til heltene, og fortæller, at {villain} har betalt dobbelt for at køre uden om {town} ved daggry.`,`{npc3} promises to leave the crates where they land and keep them for the heroes, and tells them that {villain} paid double to drive round {town} at dawn.`),P(`{npc3} trækker på skuldrene og bliver ved dyrene. Ved daggry kører muldyrene med det, der er kommet ned.`,`{npc3} shrugs and stays with the animals. At dawn the mules leave with whatever has come down.`)),I(`Wisdom (Perception)`,`easy`,P(`Heltene tæller lygterne på galleriet og ser skygger bevæge sig om trissen: Der står mindst fire deroppe, og rebet er spændt fast til brystværnet.`,`The heroes count the lanterns on the gallery and see shadows moving round the pulley: at least four people stand up there, and the rope is tied to the parapet.`),P(`Galleriet er bare en mørk kant højt oppe. Heltene ved først, hvor mange der venter, når de selv står deroppe.`,`The gallery is just a dark ledge high above. The heroes do not learn how many are waiting until they stand up there themselves.`))],fight:!1,alternatives:[P(`Klatr op ad rebet: Det er hurtigt, men hårdt, og heltene kommer op midt blandt {villain}s folk på galleriet uden at have set stjernetrappen.`,`Climb the rope: it is quick but hard, and the heroes come up in the middle of {villain}’s people on the gallery without having seen the star stair.`),P(`Skær rebet over nedefra: Så kan der ikke komme flere kasser ned ad klippen, men {villain}s folk deroppe ved straks, at nogen er på vej.`,`Cut the rope from below: then no more crates can come down the cliff, but {villain}’s people above know at once that someone is coming.`)],dmNotes:P(`Klippefoden er stedet, hvor spillerne ser {villain}s plan med egne øjne. Spil {npc3} som en ærlig arbejder, der godt ved, at noget er galt; den, der tilbyder {npc3} en anden løn eller et sikkert sted til dyrene, får mest.`,`The cliff foot is where the players see {villain}’s plan with their own eyes. Play {npc3} as an honest worker who knows full well that something is wrong; whoever offers {npc3} other wages or a safe place for the animals gets the most out of the driver.`)},{kind:`exploration`,at:`site`,present:[],title:P(`Stjernetrappen`,`The Star Stair`),summary:P([`Bag bronzedøren snor stjernetrappen sig tre hundrede trin op gennem {place}, og i trinene er himlens stjernebilleder lagt ind i sølv og bjergkrystal.`,`På hver afsats ligger et af stjernelæsernes rum, urørt i hundrede år: et vandur, der stadig drypper, talerør af messing og vægge malet med vandrernes baner, og hvert rum, heltene tegner ind, er et felt på {npc1}s kort.`,`Ved trappens øverste trin har {villain}s folk tegnet kridtpile og tolv streger på væggen.`],[`Behind the bronze door the star stair winds three hundred steps up through {place}, and the constellations of the sky are set into its steps in silver and rock crystal.`,`On every landing lies one of the star-readers’ rooms, untouched for a hundred years: a water clock that still drips, speaking tubes of brass and walls painted with the paths of the Wanderers, and every room the heroes draw in fills another square of {npc1}’s chart.`,`By the top step of the stair {villain}’s people have chalked arrows and twelve strokes on the wall.`]),readAloud:P([`Bronzedøren står åben, og bag den går en trappe i ring op gennem mørket, så stejl, at man kan røre trinet over sig med hånden.`,`I hvert trin glimter stjernebilleder af sølv og krystal, og hvor stjernelyset fra spalten højt oppe rammer dem, gløder de svagt, som om trappen selv var en nattehimmel.`,`Et sted ovenover drypper vand i jævn takt, og fra væggen lyder en hul hvisken, som om nogen talte i et rør langt borte.`],[`The bronze door stands open, and behind it a stair winds up through the dark, so steep that you can touch the step above with your hand.`,`In every step constellations of silver and crystal glitter, and where the starlight from the slit high above strikes them, they glow faintly, as if the stair itself were a night sky.`,`Somewhere above, water drips in an even beat, and from the wall comes a hollow whisper, as if someone were speaking into a pipe far away.`]),details:[P(`Stjernelæsernes rum ligger på hvert halvtredsindstyvende trin: vandurets kammer, hvor et kobberkar stadig drypper timerne ud; skrivestuen med pulte og indtørret blæk; og kammeret med talerørene, hvor man kan høre alt, hvad der bliver sagt i kuplen. Hvert rum, heltene tegner ordentligt ind, koster ti minutter, hele trappen en halv time.`,`The star-readers’ rooms lie on every fiftieth step: the chamber of the water clock, where a copper vessel still drips out the hours; the writing room with desks and dried ink; and the chamber of the speaking tubes, where everything said in the dome can be heard. Drawing a room in properly costs ten minutes, and the whole stair half an hour.`),P(`I talerørenes kammer kan heltene høre {villain} i kuplen give ordrer: "Én stjerne i hver kasse, og pas på hjertet." Fra midnat lyder der skruer og knirkende metal i rørene, og den svage tikken fra hjulet holder op.`,`In the chamber of the speaking tubes the heroes can hear {villain} giving orders in the dome: "One star to each crate, and mind the heart." From midnight the tubes carry the sound of screws and creaking metal, and the faint ticking of the wheel stops.`),P(`Ved trappens øverste trin har {villain}s folk sat kridtpile på væggen med ordet "hjulet" og tolv streger, én for hver tom kasse, der er båret op. Herfra fører en lav dør ud til kuplens galleri og en smal trappe videre op i selve kuplen.`,`By the top step of the stair {villain}’s people have chalked arrows on the wall with the word "wheel" and twelve strokes, one for each empty crate carried up. From here a low door leads out to the dome gallery, and a narrow stair goes on up into the dome itself.`)],checks:[I(`Intelligence (Investigation)`,`medium`,P(`Heltene tegner trappen og rummene nøjagtigt ind, og kortet viser det, kridtstregerne siger: Tolv kasser er gået op, og ingen er kommet ned ad trappen. Stjernerne skal ud ad galleriet.`,`The heroes draw the stair and the rooms in accurately, and the chart shows what the chalk strokes say: twelve crates have gone up and none has come down the stair. The stars are meant to leave by the gallery.`),P(`Trappen snor sig, og kortet bliver skævt; heltene må tælle trinene om, og det koster en halv time, eller gå videre med en skitse, som {npc1} ikke kan bruge.`,`The stair winds, and the chart comes out crooked; the heroes must count the steps again, which costs half an hour, or go on with a sketch {npc1} cannot use.`)),I(`Wisdom (Perception)`,`easy`,P(`I talerørene hører heltene, hvor mange stemmer der er i kuplen og på galleriet, og at {villain} vil have bronzehjertet taget ud til sidst, lige før daggry.`,`In the speaking tubes the heroes hear how many voices there are in the dome and on the gallery, and that {villain} wants the bronze heart taken out last, just before dawn.`),P(`Rørene hvisker kun. Heltene ved først, hvem der er deroppe, når de står ansigt til ansigt med dem.`,`The tubes only whisper. The heroes do not learn who is up there until they stand face to face with them.`))],fight:!1,alternatives:[P(`Spring rummene over, og løb op ad trappen: Det sparer en halv time, men kortet får huller, og heltene hører ikke {villain} i talerørene.`,`Skip the rooms and run up the stair: it saves half an hour, but the chart has gaps, and the heroes do not hear {villain} in the speaking tubes.`),P(`Tal ind i talerøret: En stemme fra "stjernelæserne" kan skræmme {villain}s lejede folk, men {villain} lader sig ikke narre længe.`,`Speak into the speaking tube: a voice from "the star-readers" can frighten {villain}’s hired hands, but {villain} will not be fooled for long.`)],dmNotes:P(`Giv vidunderne plads: Ingen har gået her i hundrede år. Spørg spillerne, hvad de tegner ind, lad vanduret dryppe timerne ud, mens de gør det, og lad talerørene minde dem om, at nogen er deroppe før dem.`,`Give the wonders room: no one has walked here for a hundred years. Ask the players what they draw in, let the water clock drip out the hours while they do, and let the speaking tubes remind them that someone got there first.`)},{kind:`combat`,at:`site`,present:[],title:P(`Kuplens galleri`,`The Dome Gallery`),summary:P([`Galleriet er en smal stengang rundt om kuplens fod med et lavt brystværn og et lodret fald ned til stenuren.`,`Her har {villain} sat nogle {foe} til at fire kasser med krystalstjerner ned ad klippen i reb og trisse, og vinden river i dem.`,`I en kasse ved trissen ligger {villain}s ordre til mandskabet, og den viser, hvem lygten fra vogterhuset skal ramme.`],[`The gallery is a narrow stone walk round the foot of the dome, with a low parapet and a sheer drop to the scree below.`,`Here {villain} has set some {foe} to lower crates of crystal stars down the cliff by rope and pulley, and the wind tears at them.`,`In a crate by the pulley lies {villain}’s order to the crew, and it shows whom the lantern from the wardens’ house is meant to ruin.`]),readAloud:P([`Den lave dør går ud til en smal gang af sten, og vinden slår heltene i ansigtet, så lygterne blafrer.`,`Ude ved brystværnet knirker en trisse, et reb løber stramt ned i mørket, og ved siden af står en stabel små kasser med halm, der stritter ud mellem brædderne.`,`Over dem buer kuplen sig, grøn og våd af dug, og gennem spalten i den falder lyset fra de to vandrere som en klinge.`],[`The low door opens onto a narrow walk of stone, and the wind strikes you in the face so that your lanterns gutter.`,`Out by the parapet a pulley creaks, a rope runs taut down into the dark, and beside it stands a stack of small crates with straw bristling between the boards.`,`Above them the dome curves, green and wet with dew, and through the slit in it the light of the Two Wanderers falls like a blade.`]),details:[P(`Mandskabet er {foe}, som {villain} har hyret til at bære og fire; de kender gangen og bruger kuplens ribber som dækning. Begynder en kamp, løber en af dem op i kuplen for at advare {boss}, medmindre heltene standser løberen.`,`The crew are {foe} that {villain} has hired to carry and lower the crates; they know the walk and use the dome’s ribs as cover. If a fight starts, one of them runs up into the dome to warn {boss}, unless the heroes stop the runner.`),P(`Gangen er kun to skridt bred, og brystværnet når til knæet. Den, der bliver skubbet mod det, skal holde balancen eller hænge ud over kanten, og der kommer et vindstød hver tredje runde. Skæres rebet over med en kasse på vej ned, knuses krystalstjernen på stenuren.`,`The walk is only two paces wide, and the parapet is only knee-high. Anyone shoved against it must keep their balance or hang out over the edge, and a gust comes every third round. If the rope is cut with a crate on its way down, the crystal star shatters on the scree.`),P(`I kassen ved trissen ligger {villain}s ordre: Krystalstjernerne skal fires ned, én i hver kasse, og lygten fra vogterhuset skal med {villain} ud ad døren ved daggry. Gennem kuplens nederste ruder kan man se stjernehjulet, {boss} og {villain} med en lampe og en gammel dagbog.`,`In the crate by the pulley lies {villain}’s order: the crystal stars are to be lowered one to a crate, and the lantern from the wardens’ house goes out through the door with {villain} at dawn. Through the dome’s lowest panes the star wheel can be seen, with {boss} and {villain}, who holds a lamp and an old diary.`)],checks:[I(`Strength (Athletics)`,`medium`,P(`En helt griber rebet og hiver kassen, der er på vej ned, op igen, før nogen kan skære den løs; krystalstjernen i halmen er hel.`,`A hero seizes the rope and hauls the descending crate back up before anyone can cut it loose; the crystal star in the straw is unharmed.`),P(`Rebet glider gennem hænderne, og kassen hamrer ned ad klippen; heltene kan kun håbe, at {npc3} griber den dernede.`,`The rope slides through the hero’s hands and the crate slams down the cliff; the heroes can only hope {npc3} catches it below.`)),I(`Intelligence (Investigation)`,`easy`,P(`Heltene finder ordren i kassen ved trissen og ved nu, at {villain} vil gå ud ad døren ved daggry med vogternes lygte som "bevis".`,`The heroes find the order in the crate by the pulley and now know that {villain} means to walk out the door at dawn with the wardens’ lantern as "proof".`),P(`I kampens larm blæser papiret ud over kanten, og heltene når kun at læse ordet "lygten".`,`In the noise of the fight the paper blows over the edge, and the heroes only manage to read the word "lantern".`))],fight:!0,alternatives:[P(`Kravl over kuplens ribber i stedet for ad gangen: Det er farligt i vinden, men heltene kommer ind i kuplen ad spalten lige over {villain}.`,`Climb over the dome’s ribs instead of along the walk: it is dangerous in the wind, but the heroes enter the dome through the slit right above {villain}.`),P(`Tal med mandskabet: De er lejet til at bære, ikke til at dø, og ser de {villain}s ordre om at give vogterne skylden, lægger nogle af dem rebet fra sig.`,`Talk to the crew: they were hired to carry, not to die, and if they see {villain}’s order to blame the wardens, some of them lay down the rope.`)],dmNotes:P(`Galleriet er kampen med udsigt: Lad vinden og kanten være lige så farlige som mandskabet, og lad lyset fra spalten falde på kampen. Den, der redder en kasse, redder en stjerne.`,`The gallery is the fight with a view: let the wind and the edge be as dangerous as the crew, and let the light from the slit fall on the fight. Whoever saves a crate saves a star.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:P(`Stjernehjulet i kuplen`,`The Star Wheel in the Dome`),summary:P([`Øverst i {place} står stjernehjulet i kuplen: et bronzeinstrument, højere end et hus, med tolv arme, og på hver arm sidder en krystalstjerne, der viser, hvor himlens stjerner står i de næste hundrede år.`,`Fra døren gik op, har {villain} været her med {npc1}s oldemors dagbog, og fra midnat skruer {boss} og nogle {foe} stjernerne af og pakker dem i kasser; til sidst skal bronzehjertet, tandhjulet der bærer hjulets kalender, tages ud.`,`Heltene skal standse plyndringen, tegne hjulet og dets fod af og komme ud ad bronzedøren, før den lukker sig ved daggry.`],[`At the top of {place} the star wheel stands in the dome: a bronze instrument taller than a house, with twelve arms, and on each arm sits a crystal star showing where the stars of the sky will stand for the next hundred years.`,`Since the door opened, {villain} has been here with {npc1}’s great-grandmother’s diary, and from midnight {boss} and some {foe} unscrew the stars and pack them into crates; last of all the bronze heart, the gear that carries the wheel’s calendar, is to come out.`,`The heroes must stop the plundering, draw the wheel and its base, and get out through the bronze door before it closes at dawn.`]),readAloud:P([`Kuplen er et vældigt, mørkt rum, og hele loftet er malet med himlen: stjernebilleder i guld på blåt, slidt af hundrede års fugt.`,`Midt i rummet står et hjul af bronze, højere end et hus, med tolv arme, og på de fleste af dem gløder en krystalstjerne i lyset fra spalten; tre arme er allerede tomme.`,`Ved hjulets fod står en skikkelse i en fin rejsekappe med en lampe og en åben dagbog og peger op mod den næste stjerne.`],[`The dome is a vast, dark room, and the whole ceiling is painted with the sky: constellations in gold on blue, worn by a hundred years of damp.`,`In the middle of the room stands a wheel of bronze, taller than a house, with twelve arms, and on most of them a crystal star glows in the light from the slit; three arms are already empty.`,`At the foot of the wheel a figure in a fine travelling cloak holds a lamp and an open diary and points up at the next star.`]),details:[P(`{boss} og nogle {foe} er hyret af {villain} til at skrue og bære og vogter hjulet og trappen. De kæmper for deres løn og flygter ned ad trappen, når {boss} falder, eller når døren begynder at lukke. {villain} kæmper ikke, holder sig bag hjulet med dagbogen og tilbyder heltene en andel af fyrstens betaling, når kampen vender. Kommer heltene før midnat, sidder stjernerne stadig på hjulet, og {villain} står og læser i dagbogen.`,`{boss} and some {foe} have been hired by {villain} to unscrew and carry, and they guard the wheel and the stair. They fight for their pay and flee down the stair when {boss} falls or when the door begins to close. {villain} does not fight, keeps behind the wheel with the diary and offers the heroes a share of the prince’s payment when the fight turns. If the heroes arrive before midnight, the stars are still on the wheel and {villain} stands reading the diary.`),P(`I hjulets stenfod har stjernelæserne hugget tal og vægt for hver af de tolv krystalstjerner og for bronzehjertet i deres gamle skrift. En tegning af foden tager ti minutter og viser præcis, hvad der mangler; sammen med kasserne er den beviset på, at det var {villain} og ikke vogterne, der plyndrede hjulet. Kuplens malede stjernekort tager en halv time at tegne af.`,`In the wheel’s stone base the star-readers carved the number and weight of each of the twelve crystal stars and of the bronze heart in their old script. A drawing of the base takes ten minutes and shows exactly what is missing; together with the crates it is the proof that it was {villain}, and not the wardens, who plundered the wheel. The dome’s painted star chart takes half an hour to draw.`),P(`Ved daggry begynder bronzedøren at glide i, og et kvarter senere er den lukket; den, der stadig er i tårnet, er spærret inde i hundrede år eller må ned ad rebet fra galleriet. {villain} har højdeskræk og vil ikke røre rebet. Står nogen på trappen, har {villain} ingen vej ud og forhandler om at blive ført ned, før døren lukker sig.`,`At dawn the bronze door begins to slide shut, and a quarter of an hour later it is closed; anyone still in the tower is shut in for a hundred years or must go down the rope from the gallery. {villain} is afraid of heights and will not touch the rope. If someone holds the stair, {villain} has no way out and bargains to be led down before the door closes.`)],checks:[I(`Intelligence (Investigation)`,`medium`,P(`Heltene læser tallene i hjulets fod og tegner dem af: tolv stjerner og ét hjerte, og hver kasse på galleriet passer til en af dem. Det er et bevis, rådet ikke kan bortforklare.`,`The heroes read the figures in the wheel’s base and copy them: twelve stars and one heart, and every crate on the gallery matches one of them. It is proof the council cannot explain away.`),P(`Skriften er gammel og slidt; heltene får kun halvdelen med, før døren begynder at lukke, og rådet vil tvivle på resten.`,`The script is old and worn; the heroes get only half of it before the door begins to close, and the council will doubt the rest.`)),I(`Charisma (Intimidation)`,`medium`,P(`Med kasserne, ordren fra galleriet og døren, der snart lukker, giver {villain} op, rækker heltene vogternes lygte og beder om at blive ført ned ad trappen.`,`Faced with the crates, the order from the gallery and the door about to close, {villain} gives up, hands the heroes the wardens’ lantern and begs to be led down the stair.`),P(`{villain} griber bronzehjertet og løber mod trappen, mens {boss} spærrer vejen for heltene.`,`{villain} grabs the bronze heart and runs for the stair while {boss} blocks the heroes’ way.`))],fight:!0,alternatives:[P(`Hold trappen, før heltene går op i kuplen: Med en helt på øverste trin er {villain} lukket inde mellem hjulet og kanten og giver stjernerne fra sig for at komme ned.`,`Hold the stair before going up into the dome: with a hero on the top step, {villain} is shut in between the wheel and the edge and gives up the stars to get down.`),P(`Tal i talerøret fra trappen, og lok {boss} og mandskabet ned mod en "patrulje fra rådet", mens én helt tegner hjulets fod.`,`Speak into the speaking tube from the stair and lure {boss} and the crew down toward a "patrol from the council" while one hero draws the wheel’s base.`)],dmNotes:P(`Lad lyset fra spalten være uret: Sig, hvor langt det er gledet hen over gulvet, hver gang en ny runde begynder efter midnat. {villain} kæmper ikke, men taler om lærdom, om fyrstens guld og om, at vogterne alligevel aldrig så hjulet; lad heltene vælge mellem at lytte og at tegne.`,`Let the light from the slit be the clock: say how far it has slid across the floor each time a new round begins after midnight. {villain} does not fight but talks: of learning, of the prince’s gold and of how the wardens never saw the wheel anyway; let the heroes choose between listening and drawing.`)}},lt=e({kernel:()=>pt,scenes:()=>mt}),ut=e=>Array.isArray(e)?e.join(` `):e,L=(e,t)=>({da:ut(e),en:ut(t)}),dt=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),R=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},ft=(e,t,n)=>({when:e,event:t,sign:n}),z=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),pt={id:`festival-the-switched-crown`,titles:[L(`Den byttede krone`,`The Switched Crown`),L(`Tretten aks`,`Thirteen Ears of Grain`),L(`Kroning ved midnat`,`Crowning at Midnight`)],missions:[`festival`,`intrigue`],foes:`people`,roles:{npc1:L(`en gammel guldsmed, der har pudset høstkronen før hver høstfest i fyrre år`,`an old goldsmith who has polished the harvest crown before every harvest festival for forty years`),npc2:L(`en ung bonde, der vandt kornvejningen i år og skal krones ved midnat`,`a young farmer who won the grain weighing this year and is to be crowned at midnight`),npc3:L(`en tinstøber, der i sommer støbte en forgyldt krone "til et omrejsende teater"`,`a pewterer who cast a gilded crown "for a travelling theatre" this summer`),villain:L(`en godsejer og kirkeværge, hvis gods har vundet høstkronen tyve år i træk`,`a landowner and churchwarden whose estate has won the harvest crown twenty years running`)},hook:L(`{npc1} trækker heltene ind bag sin bod på høstmarkedet sidst på eftermiddagen, lægger en tegning af høstkronen på bordet og hvisker, at kronen på alteret i {place} er falsk, og beder dem finde den ægte og afsløre byttet før kroningen ved midnat.`,`{npc1} draws the heroes in behind a stall at the harvest market late in the afternoon, lays a drawing of the harvest crown on the table, whispers that the crown on the altar in {place} is false, and asks them to find the true one and expose the switch before the crowning at midnight.`),people:{npc1:{wants:L(`Vil se den ægte krone på {npc2}s hoved ved midnat og ingen skygge af mistanke over sin egen bod.`,`Wants to see the true crown on {npc2}’s head at midnight, with no shadow of suspicion over the goldsmith’s stall.`),secret:L(`Var alene med kronen i sakristiet før daggry og lod den ligge, mens festen blev ringet ind, og frygter, at hele byen vil tro, at det var {npc1}, der byttede den.`,`Was alone with the crown in the vestry before dawn and left it lying there while the festival was rung in, and fears that the whole town will believe it was {npc1} who switched it.`)},npc2:{wants:L(`Vil krones ved midnat og levere korn til byens kornlade, så gården kan betale sin gæld.`,`Wants to be crowned at midnight and supply the town granary, so that the farm can pay its debts.`),secret:L(`Skylder {villain} penge fra en dårlig høst for tre år siden og har ikke fortalt nogen, at {villain} kan tage gården, hvis gælden ikke er betalt til midvinter.`,`Owes {villain} money from a bad harvest three years ago and has told no one that {villain} can take the farm if the debt is not paid by midwinter.`)},npc3:{wants:L(`Vil holde sit værksted og sit gode navn ude af hele sagen.`,`Wants to keep their workshop and good name out of the whole affair.`),secret:L(`Fik betaling i mønter fra kapellets høstbøsse og ikke fra noget teater og har gemt den tegning, kronen blev støbt efter.`,`Was paid in coins from the chapel’s harvest box, not by any theatre, and has kept the drawing the crown was cast from.`)}},premise:L([`Hvert år ved høstfesten i {town} bliver den gamle høstkrone, tretten aks af forgyldt sølv, sat på hovedet af den, der har vundet kornvejningen, og med kronen følger retten til at levere korn til byens kornlade det næste år.`,`I tyve år har {villain}s gods vundet, men i år vandt {npc2}, en ung bonde, og {villain} har sørget for, at kronen, der hviler på alteret i {place}, det gamle høstkapel ved torvet, er en forgyldt kopi af tin.`,`Den ægte krone ligger gemt i den første høstvinders stenkiste i krypten under kapellet, hvor {npc2}s vinderneg hviler til midnat, og i nat vil {villain}, der som kirkeværge binder neget til optoget, binde kronen ind midt i det.`,`Ved kroningen råber {villain} tyv, vagten finder den ægte krone i {npc2}s neg, og kronen og kornretten går tilbage til {villain}.`],[`Every year at the harvest festival of {town} the old harvest crown, thirteen ears of gilded silver, is set on the head of whoever has won the grain weighing, and with the crown comes the right to supply the town granary for the next year.`,`For twenty years {villain}’s estate has won, but this year the winner was {npc2}, a young farmer, and {villain} has made sure that the crown resting on the altar in {place}, the old harvest chapel by the square, is a gilded pewter copy.`,`The true crown lies hidden in the first harvest winner’s stone coffin in the crypt beneath the chapel, where {npc2}’s winning sheaf rests until midnight, and tonight {villain}, who as churchwarden binds the sheaf for the procession, means to bind the crown into the heart of it.`,`At the crowning {villain} cries thief, the watch finds the true crown in {npc2}’s sheaf, and the crown and the grain right go back to {villain}.`]),goal:L(`Find den ægte høstkrone i krypten under {place}, og bevis for hele {town}, at kronerne er byttet, og hvem der byttede dem, før kroningen ved midnat.`,`Find the true harvest crown in the crypt beneath {place}, and prove to all of {town} that the crowns were switched, and who switched them, before the crowning at midnight.`),objective:{target:L(`Den ægte høstkrone, som {villain} har gemt i krypten under {place}`,`The true harvest crown that {villain} has hidden in the crypt beneath {place}`),state:L(`I den første høstvinders stenkiste i krypten under {place}, svøbt i et gammelt alterklæde, ved siden af {npc2}s vinderneg. Fra solnedgang holder {boss} og nogle {foe} vagt ved kryptens gitter, og fra høstbålet bliver tændt, sidder {villain} selv dernede og binder kronen ind midt i neget, der skal bæres op til torvet ved midnat.`,`In the first harvest winner’s stone coffin in the crypt beneath {place}, wrapped in an old altar cloth, beside {npc2}’s winning sheaf. From sunset {boss} and some {foe} stand guard at the crypt gate, and from the moment the harvest bonfire is lit, {villain} sits down there in person, binding the crown into the heart of the sheaf that is to be carried up to the square at midnight.`),resolution:L([`Tag den ægte krone, før den er bundet ind i neget, og bær den til torvet før midnat sammen med den falske fra alteret, så hele byen kan se forskel på dem; {npc3}s ord eller tegningen, kopien blev støbt efter, viser, hvem der stod bag.`,`Når heltene ikke krypten i tide, kan de stadig afsløre kopien på torvet med det bøjede aks og tinstøberens ord, men den ægte krone bliver fundet i {npc2}s neg, og byen ved ikke, hvem den skal tro.`],[`Take the true crown before it is bound into the sheaf and carry it to the square before midnight together with the false one from the altar, so the whole town can see the difference; {npc3}’s word or the drawing the copy was cast from shows who was behind it.`,`If the heroes do not reach the crypt in time, they can still expose the copy in the square with the pewterer’s word and the missing bent ear, but the true crown is found in {npc2}’s sheaf, and the town will not know whom to believe.`])},villain:{want:L(`At beholde høstkronen og retten til at levere korn til byens kornlade, som {villain}s gods har haft i tyve år, og at knuse {npc2}, så ingen ung bonde prøver at slå {villain} igen.`,`To keep the harvest crown and the right to supply the town granary, which {villain}’s estate has held for twenty years, and to crush {npc2} so that no young farmer tries to beat {villain} again.`),plan:L([`Først lånte {villain} kapellets gamle inventarium og lod {npc3}, en tinstøber, støbe en forgyldt kopi af høstkronen efter tegningen i det, "til et omrejsende teater".`,`Ved daggry i dag, mens {npc1} ringede festen ind, byttede {villain}, der som kirkeværge har nøglerne til kapellet og krypten, kronerne i sakristiet og gemte den ægte i den første høstvinders stenkiste i krypten, hvor {npc2}s vinderneg skal hvile til midnat.`,`Når høstbålet bliver tændt, går {villain} ned for at binde neget til optoget, som skikken byder, og binder kronen ind midt i det; ved kroningen løfter {villain} den falske krone, råber tyv og lader vagten skære neget op.`],[`First, {villain} borrowed the chapel’s old inventory and had {npc3}, a pewterer, cast a gilded copy of the harvest crown from the drawing in it, "for a travelling theatre".`,`At dawn today, while {npc1} rang in the festival, {villain}, who as churchwarden holds the keys to the chapel and the crypt, switched the crowns in the vestry and hid the true one in the first harvest winner’s stone coffin in the crypt, where {npc2}’s winning sheaf is to rest until midnight.`,`When the harvest bonfire is lit, {villain} goes down to bind the sheaf for the procession, as custom demands, and binds the crown into the heart of it; at the crowning {villain} lifts the false crown, cries thief and lets the watch cut the sheaf open.`]),weakness:L([`{villain} stoler ikke på sine lejede folk med kronen og skal efter skik binde neget alene, så {villain} sidder selv i krypten med kronen i hænderne i de sidste timer, og neget skal bindes, så ingen kan se, at det har været åbnet; det tager tid.`,`Og kopien blev støbt efter tegningen i inventariet, som er ældre end haglstormen for tyve år siden: Den har tretten lige aks, mens den ægte krone har haft et bøjet aks lige siden, og det ved {npc1} og alle gamle bønder i {town}.`],[`{villain} does not trust the hired hands with the crown and by custom must bind the sheaf alone, so {villain} sits in the crypt in person with the crown in hand in the last hours, and the sheaf must be bound so that nobody can see it has been opened; that takes time.`,`And the copy was cast from the drawing in the inventory, which is older than the hailstorm twenty years ago: it has thirteen straight ears, while the true crown has had a bent ear ever since, and {npc1} and every old farmer in {town} know it.`])},stakes:L(`Bliver den ægte krone fundet i {npc2}s neg ved kroningen, bliver {npc2} ført bort i lænker som tyv, gården går til {villain} for en gammel gæld, og kronen og kornretten bliver hos {villain} i mange år endnu. Ingen ung bonde i {town} tør vinde kornvejningen igen, og høstfesten ender i skam.`,`If the true crown is found in {npc2}’s sheaf at the crowning, {npc2} is led away in chains as a thief, the farm goes to {villain} for an old debt, and the crown and the grain right stay with {villain} for many years to come. No young farmer in {town} will dare win the grain weighing again, and the harvest festival ends in shame.`),clock:{start:L(`Sen eftermiddag på høstfestens dag. Kornvejningen er netop forbi, {npc2} har vundet, og {villain} har efter skik båret {npc2}s vinderneg ned i krypten under {place}, hvor det hviler til midnat. Ved midnat sætter {villain} som kirkeværge kronen på {npc2}s hoved foran hele {town}; indtil da hviler kronen, eller det, alle tror er kronen, på alteret.`,`Late afternoon on the day of the harvest festival. The grain weighing has just ended, {npc2} has won, and by custom {villain} has carried {npc2}’s winning sheaf down into the crypt beneath {place}, where it rests until midnight. At midnight {villain}, as churchwarden, sets the crown on {npc2}’s head before all of {town}; until then the crown, or what everyone believes is the crown, rests on the altar.`),ticks:[ft(L(`Efter 2 timer (ved solnedgang)`,`After 2 hours (at sunset)`),L(`{villain}s lejede {foe} tager plads som "æresvagt" i {place}, lukker gitteret til krypten og viser alle væk fra alteret, også {npc1}.`,`{villain}’s hired {foe} take their places as an "honour guard" in {place}, close the gate to the crypt and turn everyone away from the altar, {npc1} included.`),L(`Fremmede vagter med festens røde bånd om armen står ved kapellets dør, og den gamle guldsmed bliver vist ud på trappen.`,`Unfamiliar guards with the festival’s red ribbon on their arms stand at the chapel door, and the old goldsmith is shown out onto the steps.`)),ft(L(`Efter 5 timer (når høstbålet bliver tændt)`,`After 5 hours (when the harvest bonfire is lit)`),L(`Mens hele byen samles om bålet på torvet, går {villain} ned i krypten, som skikken byder, mens {boss} vogter gitteret; {villain} tager den ægte krone op af den første høstvinders kiste og begynder at binde den ind midt i {npc2}s neg.`,`As the whole town gathers round the bonfire in the square, {villain} goes down into the crypt as custom demands, while {boss} guards the gate; {villain} takes the true crown out of the first harvest winner’s coffin and begins to bind it into the heart of {npc2}’s sheaf.`),L(`Bålet flammer op på torvet, kapellets klokke slår ét enkelt slag, som når kirkeværgen går ned til neget, og bag gitteret til krypten bevæger sig en lygte.`,`The bonfire flares up in the square, the chapel bell strikes a single stroke, as it does when the churchwarden goes down to the sheaf, and behind the gate to the crypt a lantern moves.`)),ft(L(`Efter 7 timer (ved midnat)`,`After 7 hours (at midnight)`),L(`Klokkerne ringer til kroning, neget bliver båret op og kørt på {npc2}s vogn i spidsen for optoget, og da {villain} løfter den falske krone fra puden på torvet, råber {villain} tyv, og vagten skærer neget op og finder den ægte.`,`The bells ring for the crowning, the sheaf is carried up and placed on {npc2}’s wagon at the head of the procession, and as {villain} lifts the false crown from its cushion in the square, {villain} cries thief, and the watch cuts the sheaf open and finds the true one.`),L(`Klokkerne ringer over hele {town}, optoget sætter sig i bevægelse fra kapelgården, og torvet bliver stille.`,`The bells ring all over {town}, the procession sets off from the chapel yard, and the square falls silent.`))],deadline:L(`Efter 7 timer, ved midnat, er det for sent: Den ægte krone er fundet i {npc2}s neg foran hele byen, {npc2} er ført bort som tyv, og kronen og kornretten går til {villain}.`,`After 7 hours, at midnight, it is too late: the true crown has been found in {npc2}’s sheaf before the whole town, {npc2} has been led away as a thief, and the crown and the grain right go to {villain}.`)},clues:{who:[R(`town`,L(`{npc3}, tinstøberen, støbte i sommer en forgyldt krone med tretten aks efter en tegning fra kapellets gamle inventarium, bestilt af {villain} "til et omrejsende teater", og fik betaling i mønter fra kapellets høstbøsse.`,`{npc3}, the pewterer, cast a gilded crown with thirteen ears this summer from a drawing out of the chapel’s old inventory, ordered by {villain} "for a travelling theatre", and was paid in coins from the chapel’s harvest box.`),L(`{villain} har ladet høstkronen kopiere og betalt med kapellets penge.`,`{villain} had the harvest crown copied and paid with the chapel’s money.`),dt([`Til tinstøberen:`,`Én krone efter vedlagte tegning, tretten aks, forgyldt, så den kan tåle fakkellys.`,`Til et teater, der kommer til høstfesten. Betalingen følger med budet. Tal ikke om det. – {villain}, kirkeværge`],[`To the pewterer:`,`One crown, from the enclosed drawing: thirteen ears, gilded well enough to pass in torchlight.`,`For a theatre coming to the harvest festival. Payment comes with the messenger. Do not speak of it. — {villain}, churchwarden`])),R(`town`,L(`{npc2} fortæller, at {villain} kom over efter kornvejningen og tilbød at købe hele høsten for halv pris med ordene: "Tag imod, før kronen gør dig ulykkelig."`,`{npc2} says that {villain} came over after the grain weighing and offered to buy the whole harvest at half price, saying: "Take it, before that crown brings you grief."`),L(`{villain} vidste på forhånd, at noget ville ramme {npc2} ved kroningen.`,`{villain} knew in advance that something would strike {npc2} at the crowning.`)),R(`town`,L(`{npc1}, guldsmeden, har opdaget, at kapellets gamle inventarium med tegningen af høstkronen har været lånt ud til {villain} hele sommeren.`,`{npc1}, the goldsmith, has discovered that the chapel’s old inventory with the drawing of the harvest crown has been lent out to {villain} all summer.`),L(`{villain} har haft den tegning, som en kopi af kronen kunne støbes efter.`,`{villain} has had the drawing from which a copy of the crown could be cast.`)),R(`site`,L(`I sakristiet i {place} ligger kapellets nøglebog: Kryptens nøgle blev hentet ved daggry i dag og er ikke afleveret igen, og ud for står {villain}s navn.`,`In the vestry of {place} lies the chapel’s key book: the crypt key was taken out at dawn today and has not been returned, and {villain}’s name is written beside it.`),L(`{villain} var i krypten, mens kronen lå i sakristiet ved daggry, og har stadig nøglen.`,`{villain} was in the crypt while the crown lay in the vestry at dawn, and still has the key.`),dt([`Kapellets nøglebog, høstfestens dag:`,`Sakristiet: åbnet før daggry af {npc1}, guldsmed, for at pudse kronen.`,`Krypten: nøglen hentet ved daggry af {villain}, kirkeværge. Ikke afleveret.`],[`The chapel’s key book, the day of the harvest festival:`,`The vestry: opened before dawn by {npc1}, goldsmith, to polish the crown.`,`The crypt: key taken at dawn by {villain}, churchwarden. Not returned.`]))],where:[R(`town`,L(`{npc1}, guldsmeden, så ved daggry {villain} komme op ad trappen fra krypten med kalkstøv på knæene, mens kronen lå i sakristiet, og hørte et tungt stenlåg falde på plads dernede.`,`{npc1}, the goldsmith, saw {villain} come up the stair from the crypt at dawn with lime dust on their knees while the crown lay in the vestry, and heard a heavy stone lid fall into place down below.`),L(`{villain} har lagt noget i en af stenkisterne i krypten under kapellet.`,`{villain} has put something into one of the stone coffins in the crypt beneath the chapel.`)),R(`site`,L(`I sakristiet går friske spor af kalkstøv fra bordet, hvor kronen blev pudset, hen til gitteret til krypten, og gitterets hængsler er nyligt smurt.`,`In the vestry, fresh tracks of lime dust run from the table where the crown was polished to the gate of the crypt, and the gate’s hinges have just been oiled.`),L(`Nogen bar noget fra sakristiet ned i krypten, og gitteret er blevet åbnet i dag.`,`Someone carried something from the vestry down into the crypt, and the gate has been opened today.`)),R(`site`,L(`I sakristiet ligger en lap af et gammelt alterklæde med kalkstøv i folderne, revet af det klæde, der plejer at dække den første høstvinders stenkiste i krypten.`,`In the vestry lies a scrap of an old altar cloth with lime dust in its folds, torn from the cloth that usually covers the first harvest winner’s stone coffin in the crypt.`),L(`Kronen er svøbt i alterklædet fra den første høstvinders kiste i krypten.`,`The crown is wrapped in the altar cloth from the first harvest winner’s coffin in the crypt.`)),R(`town`,L(`{npc3} afleverede selv kopien ved kapellets sidedør natten før festen, og {villain} tog imod den og bar den ned ad trappen til krypten, ikke op i sakristiet.`,`{npc3} delivered the copy at the chapel’s side door the night before the festival, and {villain} took it and carried it down the stair to the crypt, not up to the vestry.`),L(`{villain} har brugt krypten under kapellet som gemmested for kronerne.`,`{villain} has used the crypt beneath the chapel as the hiding place for the crowns.`))]},endings:{success:L(`Ved midnat lægger heltene de to kroner side om side på torvet, og hele {town} kan se det bøjede aks. {npc2} bliver kronet med den ægte krone, {villain} bliver ført bort af vagten med neget fra krypten som bevis, og {npc1} pudser kronen igen næste år med heltene som æresgæster ved festen.`,`At midnight the heroes lay the two crowns side by side in the square, and all of {town} can see the bent ear. {npc2} is crowned with the true crown, {villain} is led away by the watch with the sheaf from the crypt as proof, and next year {npc1} polishes the crown again, with the heroes as guests of honour at the festival.`),partial:L(`Heltene redder {npc2} fra anklagen, men uden {npc3}s ord eller tegningen kan ingen bevise, hvem der byttede kronerne. Kroningen bliver holdt, kornretten går til {npc2}, og {villain} sidder stadig som kirkeværge med nøglerne til kapellet og et nag til heltene.`,`The heroes save {npc2} from the charge, but without {npc3}’s word or the drawing nobody can prove who switched the crowns. The crowning goes ahead, the grain right goes to {npc2}, and {villain} remains churchwarden, with the keys to the chapel and a grudge against the heroes.`),failure:L(`Ved midnat skærer vagten neget op, og den ægte krone ruller ud på brostenene foran hele byen. {npc2} bliver ført bort i lænker, gården går til {villain} for den gamle gæld, og {villain}s gods får kronen et år mere, mens {npc1} tier, og ingen ung bonde i {town} tør vinde kornvejningen igen.`,`At midnight the watch cuts the sheaf open, and the true crown rolls out onto the cobbles before the whole town. {npc2} is led away in chains, the farm goes to {villain} for the old debt, and {villain}’s estate takes the crown for another year, while {npc1} keeps silent and no young farmer in {town} dares win the grain weighing again.`)}},mt={opening:{kind:`opening`,at:`town`,present:[`npc1`],title:L(`Guldsmedens bod`,`The Goldsmith’s Stall`),summary:L([`Sidst på eftermiddagen på høstfesten trækker {npc1}, en gammel guldsmed, heltene ind bag sin bod på markedet og lægger en tegning af høstkronen på bordet.`,`Kronen, der hviler på alteret i {place}, har tretten lige aks og er let som tin, mens den ægte har haft et bøjet aks i tyve år; {npc1} beder heltene finde den ægte og afsløre byttet før kroningen ved midnat.`,`Byen har tre spor: {npc2}, som skal krones, tinstøberen i den smalle gade og kapellet selv, hvor {villain} har nøglerne.`],[`Late in the afternoon of the harvest festival, {npc1}, an old goldsmith, draws the heroes in behind a market stall and lays a drawing of the harvest crown on the table.`,`The crown resting on the altar in {place} has thirteen straight ears and is as light as pewter, while the true one has had a bent ear for twenty years; {npc1} asks the heroes to find the true crown and expose the switch before the crowning at midnight.`,`The town holds three leads: {npc2}, who is to be crowned; the pewterer in the narrow street; and the chapel itself, where {villain} holds the keys.`]),readAloud:L([`Torvet summer af høstfest: Spillemænd spiller ved brønden, børn løber rundt med kranse af aks, og over det hele hænger duften af nybagt brød og stegt flæsk.`,`Bag en bod fuld af sølvskeer og ringe vinker en gammel guldsmed heltene nærmere med en sværtet finger og trækker et lærredsforhæng for.`,`På bordet ligger en gulnet tegning af en krone af tretten aks, og ved siden af er ét af dem tegnet igen, bøjet, med en rystende streg.`],[`The square hums with the harvest festival: fiddlers play by the well, children run about with wreaths of wheat ears, and over it all hangs the smell of fresh bread and roast pork.`,`Behind a stall full of silver spoons and rings, an old goldsmith beckons you closer with a blackened finger and draws a canvas curtain shut.`,`On the table lies a yellowed drawing of a crown of thirteen ears, and beside it a single ear is drawn again, bent, in a shaky hand.`]),details:[L(`Den ægte høstkrone er tretten aks af forgyldt sølv, og under haglstormen for tyve år siden blev det trettende aks bøjet; {npc1} rettede det aldrig, fordi bønderne kalder det "haglens mærke". Kronen på alteret har tretten lige aks, og da {npc1} løftede den ved middagstid, var den alt for let.`,`The true harvest crown is thirteen ears of gilded silver, and in the hailstorm twenty years ago the thirteenth ear was bent; {npc1} never straightened it, because the farmers call it "the hail’s mark". The crown on the altar has thirteen straight ears, and when {npc1} lifted it at noon it was far too light.`),L(`{npc1} pudsede kronen i sakristiet før daggry og lod den ligge, mens festen blev ringet ind; på vej ned fra klokketårnet så {npc1} {villain} komme op ad trappen fra krypten med kalkstøv på knæene. {npc1} tør ikke sige det højt: Det var {npc1}, der var alene med kronen, og {villain} er kirkeværge.`,`{npc1} polished the crown in the vestry before dawn and left it lying there while the festival was rung in; on the way down from the bell tower, {npc1} saw {villain} come up the stair from the crypt with lime dust on their knees. {npc1} dares not say it aloud: it was {npc1} who was alone with the crown, and {villain} is the churchwarden.`),L(`Ved midnat sætter {villain} som kirkeværge kronen på hovedet af {npc2}, der vandt kornvejningen. {npc2} pynter sin vogn til optoget i kapelgården, tinstøberen {npc3} har værksted i en smal gade bag torvet, og nøglerne til kapellet og krypten har {villain}. Hvert besøg i byen koster en halv time.`,`At midnight {villain}, as churchwarden, sets the crown on the head of {npc2}, who won the grain weighing. {npc2} is decorating a wagon for the procession in the chapel yard, the pewterer {npc3} keeps a workshop in a narrow street behind the square, and {villain} holds the keys to the chapel and the crypt. Every visit in town costs half an hour.`)],checks:[z(`Wisdom (Insight)`,`easy`,L(`{npc1} er bange, ikke for kronen, men for sig selv: Presset indrømmer {npc1} at have været alene med kronen i sakristiet og at frygte, at byen vil tro, det var guldsmeden, der byttede den.`,`{npc1} is afraid, not for the crown but for the goldsmith’s own skin: pressed, {npc1} admits to having been alone with the crown in the vestry and to fearing that the town will believe it was the goldsmith who switched it.`),L(`Heltene ser kun en ivrig gammel guldsmed. Frygten hører de først om, når {villain} peger på {npc1} ved kroningen.`,`The heroes see only an eager old goldsmith. They do not learn of this fear until {villain} points at {npc1} at the crowning.`)),z(`Intelligence (Investigation)`,`medium`,L(`Heltene ser, at tegningen er ældre end haglstormen: Den, der støbte kopien, har brugt en tegning som denne og aldrig set selve kronen, og sådan en tegning findes i kapellets gamle inventarium.`,`The heroes see that the drawing is older than the hailstorm: whoever cast the copy used a drawing like this one and never saw the crown itself, and such a drawing is kept in the chapel’s old inventory.`),L(`Heltene ser kun, at aksene er forskellige. Hvorfor kopien er lavet sådan, forstår de først hos tinstøberen.`,`The heroes see only that the ears differ. They do not understand why the copy was made that way until they visit the pewterer.`))],fight:!1,alternatives:[L(`Gå direkte til kapellet: Heltene sparer tiden i byen, men ved ikke, hvad de leder efter i sakristiet, og fra solnedgang står {villain}s æresvagt ved døren.`,`Go straight to the chapel: the heroes save the time in town, but do not know what they are looking for in the vestry, and from sunset {villain}’s honour guard stands at the door.`),L(`Slå alarm på torvet nu: Ingen tror på en gammel guldsmed uden bevis, og {villain} hører det inden for en time og fordobler vagten ved krypten.`,`Raise the alarm in the square now: nobody believes an old goldsmith without proof, and {villain} hears of it within the hour and doubles the guard at the crypt.`)],dmNotes:L(`Lad festen være larmende og glad omkring heltene; intrigen er det, kun de ser. Lad spillerne holde tegningen og selv finde det bøjede aks: Når de ved, hvad de skal se efter, kan de kende den ægte krone overalt.`,`Let the festival be loud and happy around the heroes; the intrigue is what only they can see. Let the players hold the drawing and find the bent ear themselves: once they know what to look for, they will know the true crown anywhere.`)},middle:[{kind:`social`,at:`town`,present:[`npc2`],title:L(`Vognen med kransen`,`The Garlanded Wagon`),summary:L([`I kapelgården pynter {npc2}, årets høstvinder, sin vogn med kranse af aks til optoget ved midnat, omgivet af venner og naboer.`,`{npc2} ved intet om byttet, men fortæller, at {villain} kom over efter kornvejningen og tilbød at købe hele høsten for halv pris med en trussel pakket ind i et smil.`,`Heltene kan advare {npc2} og vinde vennerne for sig, før neget skal bæres op fra krypten.`],[`In the chapel yard, {npc2}, this year’s harvest winner, is decorating a wagon with wreaths of wheat ears for the midnight procession, surrounded by friends and neighbours.`,`{npc2} knows nothing of the switch, but says that {villain} came over after the grain weighing and offered to buy the whole harvest at half price, with a threat wrapped in a smile.`,`The heroes can warn {npc2} and win over {npc2}’s friends before the sheaf is carried up from the crypt.`]),readAloud:L([`I kapelgården står festens vogne på række, og den forreste er så tæt pyntet med kranse og bånd, at hjulene næsten ikke kan ses.`,`En ung bonde med solbrændt nakke står oppe på vognen og tager imod endnu en krans fra en flok grinende naboer.`,`Bag vognen rejser kapellets mur sig grå og stille, og fra sidedøren falder et smalt stykke lys ud over brostenene.`],[`In the chapel yard the festival wagons stand in a row, and the foremost is so thickly decorated with wreaths and ribbons that its wheels can hardly be seen.`,`A young farmer with a sunburnt neck stands up on the wagon, taking yet another wreath from a crowd of laughing neighbours.`,`Behind the wagon the chapel wall rises grey and quiet, and from the side door a narrow strip of light falls across the cobbles.`]),details:[L(`{npc2} vandt kornvejningen med et neg, der vejede en tredjedel mere end {villain}s, og hele kapelgården ved det. Efter vejningen kom {villain} over, tilbød at købe hele høsten for halv pris og sagde: "Tag imod, før kronen gør dig ulykkelig." Så bar {villain} selv vinderneget ned i krypten, som skikken byder.`,`{npc2} won the grain weighing with a sheaf that weighed a third more than {villain}’s, and the whole chapel yard knows it. After the weighing {villain} came over, offered to buy the whole harvest at half price and said: "Take it, before that crown brings you grief." Then {villain} carried the winning sheaf down into the crypt in person, as custom demands.`),L(`Ved midnat bliver vinderneget båret op fra krypten og kørt på {npc2}s vogn i spidsen for optoget til torvet, hvor det skal stå foran kronen. Efter skik binder kirkeværgen neget alene i krypten, fra høstbålet bliver tændt, til klokken ringer til optog et kvarter før midnat.`,`At midnight the winning sheaf is carried up from the crypt and driven to the square on {npc2}’s wagon at the head of the procession, to stand before the crown. By custom the churchwarden binds the sheaf alone in the crypt from the lighting of the harvest bonfire until the bell rings for the procession a quarter of an hour before midnight.`),L(`En karl i {villain}s farver har drevet rundt i kapelgården hele eftermiddagen uden at have noget at gøre der og spurgt, hvem der skal bære neget op ved midnat, og om vagten står ved torvet.`,`A hired hand in {villain}’s colours has been loitering in the chapel yard all afternoon with no business there, asking who is to carry the sheaf up at midnight and whether the watch will be posted at the square.`)],checks:[z(`Wisdom (Insight)`,`medium`,L(`{npc2} tilstår en gammel gæld til {villain} fra en dårlig høst; uden kornretten mister {npc2} gården til midvinter, og det ved {villain}.`,`{npc2} confesses to an old debt to {villain} from a bad harvest; without the grain right {npc2} will lose the farm by midwinter, and {villain} knows it.`),L(`{npc2} ler det hele bort og vender tilbage til kransene. Gælden hører heltene først om, når {villain} nævner den ved kroningen.`,`{npc2} laughs it all off and turns back to the wreaths. The heroes do not hear of the debt until {villain} mentions it at the crowning.`)),z(`Charisma (Persuasion)`,`easy`,L(`{npc2}s venner lover at gå ned efter neget sammen, så snart klokken ringer, og at lade ingen andre røre det.`,`{npc2}’s friends promise to go down for the sheaf together as soon as the bell rings, and to let nobody else touch it.`),L(`{npc2} vil ikke ødelægge festen med mistanke, og vennerne går til bålet som alle andre.`,`{npc2} will not spoil the festival with suspicion, and the friends go to the bonfire like everyone else.`))],fight:!1,alternatives:[L(`Følg karlen i {villain}s farver: Fra kapelgården går karlen lige hen til kapellets sidedør og banker tre gange.`,`Follow the hired hand in {villain}’s colours: from the chapel yard the hired hand goes straight to the chapel’s side door and knocks three times.`),L(`Få {npc2} til at kræve sit neg at se før bålet, som vinderen har ret til: Kronen er ikke i det endnu, men {villain} ved fra nu af, at nogen er på sporet.`,`Have {npc2} demand to see the sheaf before the bonfire, as is the winner’s right: the crown is not in it yet, but from now on {villain} knows someone is on the trail.`)],dmNotes:L(`{npc2} er den, der har mest at tabe, og ved det ikke. Lad glæden i kapelgården være ægte, så spillerne mærker, hvad {villain} vil ødelægge.`,`{npc2} has the most to lose and does not know it. Let the joy in the chapel yard be real, so the players feel what {villain} means to destroy.`)},{kind:`investigation`,at:`town`,present:[`npc3`],title:L(`Tinstøberens værksted`,`The Pewterer’s Workshop`),summary:L([`{npc3}, tinstøberen, har værksted i en smal gade bag torvet og holder lukket under festen.`,`I sommer støbte {npc3} en forgyldt krone med tretten aks efter en tegning, som {villain} kom med, "til et omrejsende teater", men intet teater er kommet til festen, og {npc3} er begyndt at regne det ud.`,`Heltene kan få bestillingen, tegningen og {npc3}s vidnesbyrd, hvis de kan love beskyttelse mod {villain}.`],[`{npc3}, the pewterer, keeps a workshop in a narrow street behind the square and has closed it for the festival.`,`This summer {npc3} cast a gilded crown with thirteen ears from a drawing {villain} brought, "for a travelling theatre", but no theatre has come to the festival, and {npc3} has begun to work it out.`,`The heroes can get the order, the drawing and {npc3}’s testimony if they can promise protection from {villain}.`]),readAloud:L([`Skodderne er lukkede, men der lyser fra en sprække, og indenfor lugter der af varmt metal og trækul.`,`På arbejdsbordet ligger tinbarrer, forme af ler og et lille fad med bladguld, og på væggen hænger halvfærdige kander og fade.`,`En tinstøber med brændte fingre ser op fra en form og stiller sig hurtigt foran en skuffe.`],[`The shutters are closed, but light shows through a crack, and inside it smells of hot metal and charcoal.`,`On the bench lie ingots of pewter, clay moulds and a small dish of gold leaf, and half-finished jugs and plates hang on the wall.`,`A pewterer with burnt fingers looks up from a mould and quickly steps in front of a drawer.`]),details:[L(`Bestillingen kom fra {villain} sammen med en tegning fra kapellets gamle inventarium, og betalingen var mønter fra kapellets høstbøsse, præget med kapellets kornneg. {npc3} kendte mønterne og undrede sig, men tog imod.`,`The order came from {villain} together with a drawing from the chapel’s old inventory, and the payment was coins from the chapel’s harvest box, stamped with the chapel’s sheaf. {npc3} recognised the coins and had doubts, but took the money anyway.`),L(`I skuffen ligger bestillingen og tegningen, kopien blev støbt efter: tretten lige aks, tegnet før haglstormen. {npc3} afleverede selv kopien ved kapellets sidedør natten før festen, og {villain} bar den ned ad trappen til krypten.`,`In the drawer lie the order and the drawing the copy was cast from: thirteen straight ears, drawn before the hailstorm. {npc3} delivered the copy at the chapel’s side door the night before the festival, and {villain} carried it down the stair to the crypt.`),L(`Efter solnedgang kommer en karl i {villain}s farver forbi for at minde {npc3} om at tie. Er heltene her, går karlen igen og melder det til {villain}, der sætter flere vagter ved krypten; ellers lover {npc3} at tie og lukker skodderne helt.`,`After sunset a hired hand in {villain}’s colours comes by to remind {npc3} to keep quiet. If the heroes are here, the hired hand leaves again and reports to {villain}, who puts more guards on the crypt; otherwise {npc3} promises silence and closes the shutters tight.`)],checks:[z(`Charisma (Persuasion)`,`medium`,L(`{npc3} lover at vidne på torvet, hvis heltene står ved siden af, og giver dem bestillingen og tegningen.`,`{npc3} promises to testify in the square if the heroes stand by {npc3}, and gives them the order and the drawing.`),L(`{npc3} nægter at sige noget, men lader skuffen stå åben, så heltene kan se bestillingen.`,`{npc3} refuses to say a word but leaves the drawer open, so the heroes can see the order.`)),z(`Intelligence (Investigation)`,`easy`,L(`Heltene ser kapellets kornneg på mønterne i {npc3}s pengekasse: Kun kirkeværgen tømmer kapellets høstbøsse.`,`The heroes see the chapel’s sheaf on the coins in {npc3}’s cash box: only the churchwarden empties the chapel’s harvest box.`),L(`Mønterne ligner andre mønter. Heltene forstår først, hvor de kom fra, når de ser den tomme høstbøsse i sakristiet.`,`The coins look like any others. The heroes do not understand where they came from until they see the empty harvest box in the vestry.`))],fight:!1,alternatives:[L(`Tag {npc3} med til guldsmedens bod: Med tinstøberen i sikkerhed hos {npc1} kan {villain}s folk ikke nå vidnet før midnat.`,`Take {npc3} to the goldsmith’s stall: with the pewterer safe with {npc1}, {villain}’s people cannot reach the witness before midnight.`),L(`Brug {npc3}s håndelag: Tinstøberen kan vise heltene, hvordan en nål under forgyldningen afslører tin, et kneb, der virker på alteret foran alle.`,`Use {npc3}’s know-how: the pewterer can show the heroes how a needle under the gilt reveals pewter, a trick that works on the altar in front of everyone.`)],dmNotes:L(`Tinstøberen er det vidne, der kan nævne {villain}s navn, men er mest bange for sit eget værksted. Lad spillerne vælge mellem at true og at love; den, der lover beskyttelse og holder det, får både tegningen og vidnet.`,`The pewterer is the witness who can name {villain}, but fears most for their own workshop. Let the players choose between threats and promises; whoever promises protection and keeps the promise gets both the drawing and the witness.`)},{kind:`investigation`,at:`site`,present:[],title:L(`Sakristiet i kapellet`,`The Chapel Vestry`),summary:L([`{place} er et gammelt høstkapel ved torvet, hvor kronen hviler på alteret til kroningen, og fra solnedgang står {villain}s lejede æresvagt ved døren og ved gitteret til krypten.`,`Bag alteret ligger sakristiet med kapellets nøglebog, spor af kalkstøv og en lap af et gammelt alterklæde, og herfra går trappen ned til krypten.`,`Her kan heltene afsløre den falske krone og finde ud af, hvor den ægte ligger.`],[`{place} is an old harvest chapel by the square, where the crown rests on the altar until the crowning, and from sunset {villain}’s hired honour guard stands at the door and at the gate to the crypt.`,`Behind the altar lies the vestry with the chapel’s key book, tracks of lime dust and a scrap of an old altar cloth, and from here the stair goes down to the crypt.`,`Here the heroes can expose the false crown and work out where the true one lies.`]),readAloud:L([`Kapellet er lavt og varmt af hundrede lys, og fra bjælkerne hænger kranse af aks fra hvert år, festen er blevet holdt.`,`På alteret ligger en krone af tretten gyldne aks på en rød pude og glimter i lysene, og bag alteret står en smal dør på klem.`,`Inde i sakristiet lugter der af voks og kold kalk, og i hjørnet fører en stentrappe ned mod et gitter, hvor mørket begynder.`],[`The chapel is low and warm with a hundred candles, and wreaths of wheat ears from every year the festival has been held hang from the beams.`,`On the altar a crown of thirteen golden ears lies on a red cushion, glittering in the candlelight, and behind the altar a narrow door stands ajar.`,`Inside the vestry it smells of wax and cold lime, and in the corner a stone stair leads down toward a gate where the darkness begins.`]),details:[L(`Fra solnedgang står {villain}s lejede {foe} som "æresvagt" ved kapellets dør og ved gitteret til krypten og viser alle væk fra alteret; de går aldrig ind i sakristiet. Før solnedgang er kapellet åbent for alle, der vil se kronen.`,`From sunset {villain}’s hired {foe} stand as an "honour guard" at the chapel door and at the crypt gate and turn everyone away from the altar; they never go into the vestry. Before sunset the chapel is open to anyone who wants to see the crown.`),L(`I sakristiet ligger nøglebogen, hvor kryptens nøgle står som hentet af {villain} ved daggry og ikke afleveret. Fra bordet, hvor kronen blev pudset, går friske spor af kalkstøv hen til gitteret, og i hjørnet ligger en lap af alterklædet fra den første høstvinders stenkiste med kalk i folderne.`,`In the vestry lies the key book, where the crypt key is recorded as taken by {villain} at dawn and not returned. From the table where the crown was polished, fresh tracks of lime dust run to the gate, and in the corner lies a scrap of the altar cloth from the first harvest winner’s stone coffin with lime in its folds.`),L(`Kronen på alteret er let, og en nål under forgyldningen viser gråt tin. Kapellets høstbøsse i sakristiet er næsten tom, selv om det er festens dag. Gitteret til krypten er låst, og kun {villain} har nøglen, men låsen er gammel, og hængslerne er nyligt smurt.`,`The crown on the altar is light, and a needle under the gilt shows grey pewter. The chapel’s harvest box in the vestry is almost empty, though it is the day of the festival. The gate to the crypt is locked and only {villain} has the key, but the lock is old and the hinges have just been oiled.`)],checks:[z(`Dexterity (Stealth)`,`medium`,L(`Heltene glider forbi æresvagten og ind i sakristiet uden at blive set og kan undersøge alt i ro.`,`The heroes slip past the honour guard into the vestry unseen and can examine everything in peace.`),L(`En vagt ser dem og kalder på de andre; heltene må snakke sig ud af det, og inden for en halv time hører {villain}, at nogen har været i sakristiet.`,`A guard spots them and calls to the others; the heroes must talk their way out, and within half an hour {villain} hears that someone has been in the vestry.`)),z(`Intelligence (Investigation)`,`medium`,L(`Heltene finder både nøglebogen og lappen af alterklædet og ved nu, at den ægte krone ligger i den første høstvinders stenkiste i krypten.`,`The heroes find both the key book and the scrap of altar cloth and now know that the true crown lies in the first harvest winner’s stone coffin in the crypt.`),L(`Heltene finder kun nøglebogen; hvilken af kryptens mange stenkister kronen ligger i, må de lede efter dernede.`,`The heroes find only the key book; down below, they must search the crypt’s many stone coffins for the crown.`))],fight:!1,alternatives:[L(`Tag den falske krone med fra alteret: Den skal ligge ved siden af den ægte, når byen skal se forskel, men æresvagten opdager straks, at puden er tom, og sender bud til {villain}.`,`Take the false crown from the altar: it must lie beside the true one if the town is to see the difference, but the honour guard notices at once that the cushion is empty and sends word to {villain}.`),L(`Vent i sakristiet til høstbålet: Så går {villain} selv forbi på vej ned i krypten, og heltene ved, hvor mange der følger med.`,`Wait in the vestry until the harvest bonfire is lit: then {villain} comes past in person on the way down into the crypt, and the heroes see how many go along.`)],dmNotes:L(`Sakristiet er stilheden midt i festen. Lad musik og latter trænge ind gennem væggene, mens spillerne lægger brikkerne sammen: den lette krone, nøglebogen, kalkstøvet og lappen af alterklædet.`,`The vestry is the quiet in the middle of the festival. Let music and laughter press in through the walls while the players put the pieces together: the light crown, the key book, the lime dust and the scrap of altar cloth.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:L(`Neget i krypten`,`The Sheaf in the Crypt`),summary:L([`Under {place} ligger krypten med høstvindernes stenkister i lange rækker, og ved den første høstvinders kiste ligger {npc2}s vinderneg på en sten, klar til optoget.`,`Fra høstbålet bliver tændt, sidder {villain} selv her og binder den ægte krone ind midt i neget, mens {boss} og nogle {foe} holder trappen og gitteret.`,`Heltene skal få kronen ud, før neget bliver båret op, og nå torvet med begge kroner før midnat.`],[`Beneath {place} lies the crypt with the harvest winners’ stone coffins in long rows, and by the first harvest winner’s coffin {npc2}’s winning sheaf lies on a stone, ready for the procession.`,`From the moment the harvest bonfire is lit, {villain} sits here in person, binding the true crown into the heart of the sheaf, while {boss} and some {foe} hold the stair and the gate.`,`The heroes must get the crown out before the sheaf is carried up, and reach the square with both crowns before midnight.`]),readAloud:L([`Krypten er kold og lav, og lygtelyset falder på stenkister med udhuggede neg og navne, der næsten er slidt væk.`,`For enden af gangen er låget skubbet halvt af den ældste kiste, og ved siden af ligger et stort, gyldent neg på en sten med strå spredt rundt om.`,`Over neget bøjer en skikkelse i kirkeværgens sorte kappe sig med et bindebånd mellem tænderne, og mellem stråene glimter spidsen af et gyldent aks, der er bøjet.`],[`The crypt is cold and low, and the lantern light falls on stone coffins carved with sheaves and names worn almost away.`,`At the end of the passage the lid of the oldest coffin has been pushed half off, and beside it a great golden sheaf lies on a stone with straw scattered all around.`,`Over the sheaf bends a figure in the churchwarden’s black robe with a binding cord between their teeth, and between the stalks glints the tip of a golden ear, bent.`]),details:[L(`{boss} og nogle {foe} er hyret af {villain} og holder trappen og gitteret til krypten. De kæmper for deres løn, men ikke for en stjålet krone, og overgiver sig eller flygter, når {boss} falder. {villain} kæmper ikke, holder sig ved neget og tilbyder heltene en andel af kornretten, når kampen vender. Kommer heltene før høstbålet, ligger kronen stadig i kisten, og {villain} går lige ind i dem med sin lygte.`,`{boss} and some {foe} have been hired by {villain} and hold the stair and the gate of the crypt. They fight for their pay, but not for a stolen crown, and surrender or flee when {boss} falls. {villain} does not fight, stays by the sheaf and offers the heroes a share of the grain right when the fight turns. If the heroes come before the harvest bonfire is lit, the crown still lies in the coffin, and {villain} walks straight into them with a lantern.`),L(`At binde kronen ind, så neget ser urørt ud, tager {villain} to timer. Kommer heltene i den første time, ligger kronen åbent i halmen; senere er den bundet ind, og neget skal skæres op for at få den ud. Kronen har tretten aks, og det trettende er bøjet; lagt ved siden af kopien fra alteret kan hele byen se forskel.`,`Binding the crown in so that the sheaf looks untouched takes {villain} two hours. If the heroes come in the first hour, the crown lies open in the straw; later it is bound in, and the sheaf must be cut open to get it out. The crown has thirteen ears, and the thirteenth is bent; laid beside the copy from the altar, it shows the whole town the difference.`),L(`Krypten har kun én vej ud: trappen op til sakristiet. Når klokken ringer til optog et kvarter før midnat, kommer {npc2}s venner ned for at bære neget op. Står heltene på trappen, har {villain} ingen vej ud og forhandler om at få lov at gå op som kirkeværge og "finde" kronen selv for at redde ansigtet.`,`The crypt has only one way out: the stair up to the vestry. When the bell rings for the procession a quarter of an hour before midnight, {npc2}’s friends come down to carry the sheaf up. If the heroes hold the stair, {villain} has no way out and bargains to be allowed up as churchwarden to "find" the crown personally and save face.`)],checks:[z(`Dexterity (Sleight of Hand)`,`medium`,L(`En helt får kronen ud af neget uden at rive det i stykker, og neget kan stadig bæres op til torvet, som skikken byder.`,`A hero works the crown out of the sheaf without tearing it apart, and the sheaf can still be carried up to the square as custom demands.`),L(`Neget går op i stråene, og kronen ruller ud over stengulvet; heltene har kronen, men vinderneget er ødelagt, og {npc2} må krones uden.`,`The sheaf comes apart and the crown rolls out across the stone floor; the heroes have the crown, but the winning sheaf is ruined, and {npc2} must be crowned without it.`)),z(`Charisma (Intimidation)`,`medium`,L(`Med nøglebogen, tinstøberens bestilling og kronen i neget foran sig giver {villain} op, kalder vagterne tilbage og beder om at blive ført til rådet i stedet for til torvet.`,`Faced with the key book, the pewterer’s order and the crown in the sheaf, {villain} gives up, calls the guards off and begs to be taken to the council rather than to the square.`),L(`{villain} river kronen ud af neget og løber op ad trappen mod torvet, mens {boss} spærrer vejen for heltene.`,`{villain} tears the crown out of the sheaf and runs up the stair toward the square while {boss} blocks the heroes’ way.`))],fight:!0,alternatives:[L(`Hent {npc2}s venner tidligt: Med en flok bønder på trappen tør æresvagten ikke løfte et våben, og {villain} må forklare, hvorfor kronen ligger i neget.`,`Fetch {npc2}’s friends early: with a crowd of farmers on the stair the honour guard dares not raise a weapon, and {villain} must explain why the crown lies in the sheaf.`),L(`Kom før høstbålet, tag kronen op af kisten, og læg en sten i alterklædet: Når {villain} kommer ned for at binde neget, er kronen allerede i heltenes hænder.`,`Come before the harvest bonfire is lit, take the crown out of the coffin and leave a stone in the altar cloth: when {villain} comes down to bind the sheaf, the crown is already in the heroes’ hands.`)],dmNotes:L(`Lad musikken fra torvet sive ned gennem stenene, og sig, hvor længe der er til midnat, når kampen er slut: Torvet venter stadig. {villain} vil hellere redde ansigtet end skindet; brug det, når {villain} forhandler.`,`Let the music from the square seep down through the stones, and say how long is left until midnight when the fight is over: the square is still waiting. {villain} would rather save face than skin; use that when {villain} bargains.`)}},ht=e({kernel:()=>vt,scenes:()=>yt}),gt=e=>Array.isArray(e)?e.join(` `):e,B=(e,t)=>({da:gt(e),en:gt(t)}),_t=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),V=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},H=(e,t,n)=>({when:e,event:t,sign:n}),U=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),vt={id:`investigation-the-missing-bride`,titles:[B(`Brylluppet ved daggry`,`The Wedding at Dawn`),B(`Ægtepagten`,`The Marriage Contract`),B(`Spurven i møllen`,`The Sparrow in the Mill`)],missions:[`investigation`,`rescue`],foes:`people`,roles:{npc1:B(`en gammel kok i {villain}s hus, der har passet {npc2}, siden {npc2}s forældre døde`,`an old cook in {villain}’s household who has looked after {npc2} since {npc2}’s parents died`),npc2:B(`en ung arving, der skulle giftes ved daggry og er flygtet fra brylluppet`,`a young heir who was to be married at dawn and has fled the wedding`),npc3:B(`en færgemand, der satte {npc2} over floden ved skumring og har lovet at tie`,`a ferryman who took {npc2} across the river at dusk and promised to keep quiet`),villain:B(`en agtet og velstående borger i {town}, {npc2}s værge og nærmeste slægtning, der har arrangeret brylluppet`,`a respected, well-to-do citizen of {town}, {npc2}’s guardian and next of kin, who arranged the wedding`)},hook:B(`Sent om aftenen trækker {npc1} heltene ind i køkkenet i {villain}s hus, hvor bryllupsmaden står urørt, og beder dem finde ud af, hvad der virkelig er sket med {npc2}, og finde {npc2}, før følget drager ud ved daggry, og før nogen anden gør det.`,`Late in the evening {npc1} draws the heroes into the kitchen of {villain}’s house, where the bridal feast stands untouched, and begs them to find out what really happened to {npc2}, and to find {npc2} before the search party sets out at dawn, and before anyone else does.`),people:{npc1:{wants:B(`Vil have {npc2} i sikkerhed, langt fra købmanden og fra dette hus, uden at miste den eneste plads, {npc1} har.`,`Wants {npc2} safe, far from the merchant and from this house, without losing the only position {npc1} has.`),secret:B(`Slog selv slåen fra køkkendøren for {npc2} ved skumring og gav {npc2} brød med på vejen uden at spørge hvorhen, og har ikke sagt det til nogen, mindst af alt til {villain}.`,`Drew back the bar of the kitchen door for {npc2} at dusk and gave {npc2} bread for the road without asking where to, and has told no one, least of all {villain}.`)},npc2:{wants:B(`Vil aldrig giftes med købmanden og vil møde rådet med testamentet i hånden, så hele {town} hører, hvad {villain} har gjort.`,`Wants never to marry the merchant, and to meet the council with the will in hand so that all of {town} hears what {villain} has done.`),secret:B(`Vil giftes med barndomsvennen og ingen anden og har aldrig turdet sige det til {villain}, der har forbudt de to at ses.`,`Means to marry the childhood friend and no one else, and has never dared tell {villain}, who has forbidden the two to meet.`)},npc3:{wants:B(`Vil holde sit løfte til {npc2} og holde færgen uden for de fine folks strid.`,`Wants to keep their promise to {npc2} and to keep the ferry out of the quarrels of the well-to-do.`),secret:B(`Fik {npc2}s guldring som betaling for at tie og løj {villain} op i ansigtet ved mørkets frembrud, og er bange for, hvad {villain} gør, når løgnen kommer frem.`,`Was paid with {npc2}’s gold ring to keep quiet and lied to {villain}’s face at nightfall, and fears what {villain} will do when the lie comes out.`)}},premise:B([`{npc2}, den unge arving til mølleretten ved {place}, den forfaldne vandmølle på den anden side af floden, skulle giftes ved daggry med en rig købmand, som {npc2}s værge, {villain}, skylder en formue, og i ægtepagten har {villain} skrevet mølleretten ind som medgift, så købmanden får den og eftergiver gælden.`,`Men testamentet efter {npc2}s forældre, som {villain} har holdt låst inde, siger, at mølleretten aldrig må gives bort, og at den går til {town}, hvis {npc2} dør uden arvinger; ved skumring tog {npc2} testamentet og flygtede over floden med en barndomsven, og de to skjuler sig nu i den gamle hjulkælder under {place}.`,`{villain} fortæller hele {town}, at nogle {foe} fra {place} bar {npc2} bort, har fået rådet til at drage derud ved daggry og har i al hemmelighed hyret {boss} og nogle {foe} til at finde {npc2} først: Dør {npc2} ugift, og brænder testamentet, arver {villain} mølleretten efter loven som nærmeste slægtning.`],[`{npc2}, the young heir to the milling right at {place}, the ruined watermill across the river, was to be married at dawn to a rich merchant to whom {npc2}’s guardian, {villain}, owes a fortune. In the marriage contract {villain} has written the milling right in as the dowry, so that the merchant gets it and forgives the debt.`,`But the will of {npc2}’s parents, which {villain} has kept locked away, says that the milling right may never be given away, and that it goes to {town} if {npc2} dies without heirs. At dusk {npc2} took the will and fled across the river with a childhood friend, and the two are now hiding in the old wheel pit beneath {place}.`,`{villain} tells all of {town} that {foe} from {place} carried {npc2} off, has got the council to set out there at dawn and has secretly hired {boss} and some {foe} to find {npc2} first: if {npc2} dies unmarried and the will burns, the law gives the milling right to {villain} as next of kin.`]),goal:B(`Find ud af, hvad der virkelig er sket med {npc2}, find {npc2} i {place} før {villain}s lejede folk, og få {npc2} og testamentet frem for rådet, når det samles ved daggry.`,`Find out what really happened to {npc2}, find {npc2} in {place} before {villain}’s hirelings do, and bring {npc2} and the will before the council when it gathers at dawn.`),objective:{target:B(`{npc2}, den unge arving, og forældrenes testamente, som {npc2} bærer i et læderhylster under kappen`,`{npc2}, the young heir, and the parents’ will that {npc2} carries in a leather case under the cloak`),state:B(`Skjult i hjulkælderen under møllehuset i {place} sammen med en barndomsven, med et tællelys, et tæppe og brød til en nat. Efter 4 timer kommer {boss} og nogle {foe} og gennemsøger møllen (efter 6 timer, hvis de måtte gå uden om ad den gamle bro), efter 6 timer kommer {villain} selv med en krukke lampeolie, og ved daggry, efter 8 timer, sætter {villain} ild til møllen.`,`Hidden in the wheel pit beneath the mill house at {place} with a childhood friend, a tallow candle, a blanket and bread for one night. After 4 hours {boss} and some {foe} come to search the mill (after 6 hours if they had to go round by the old bridge). After 6 hours {villain} comes in person with a jar of lamp oil, and at dawn, after 8 hours, {villain} sets fire to the mill.`),resolution:B([`Find {npc2} før {boss}, vind {npc2}s tillid, og få {npc2} og testamentet sikkert frem for rådet, der samles ved færgelejet ved daggry og når {place} halvanden time senere: Gå rådet i møde ad stien, eller hold møllen, til det kommer.`,`Brænder testamentet, kan {npc2}s eget ord, ægtepagten fra skrivestuen og færgemandens vidneudsagn stadig vælte {villain}s historie, men ikke værgemålet.`],[`Find {npc2} before {boss} does, win {npc2}’s trust, and bring {npc2} and the will safely before the council, which gathers at the ferry landing at dawn and reaches {place} an hour and a half later: go to meet it along the path, or hold the mill until it comes.`,`If the will burns, {npc2}’s own word, the marriage contract from the study and the ferryman’s testimony can still bring down {villain}’s story, but not the guardianship.`])},villain:{want:B(`At slippe for gælden til købmanden, beholde sit gode navn i {town} og få mølleretten ved {place} i {villain}s egne hænder, med eller uden {npc2}.`,`To be rid of the debt to the merchant, keep a good name in {town} and get the milling right at {place} into {villain}’s own hands, with or without {npc2}.`),plan:B([`Først skrev {villain} som værge mølleretten ind i ægtepagten som medgift til købmanden, der så ville eftergive {villain}s gæld, og holdt testamentet, der forbyder det, låst inde i skrinet i skrivestuen.`,`Da {npc2} forsvandt ved skumring med testamentet, fortalte {villain} hele {town}, at nogle {foe} fra {place} havde båret {npc2} bort, fik rådet til at drage derud ved daggry og hyrede i al hemmelighed {boss} og nogle {foe} til at finde {npc2} og testamentet først.`,`Ved midnat banker {boss} sandheden ud af færgemanden, efter 6 timer kommer {villain} selv til {place} med lampeolie for at se testamentet brænde, og ved daggry sætter {villain} ild til møllen, så følget kun finder aske og en historie om {foe}.`],[`First, as guardian, {villain} wrote the milling right into the marriage contract as the dowry for the merchant, who would then forgive {villain}’s debt, and kept the will that forbids it locked in the strongbox in the study.`,`When {npc2} vanished at dusk with the will, {villain} told all of {town} that {foe} from {place} had carried {npc2} off, got the council to set out there at dawn and secretly hired {boss} and some {foe} to find {npc2} and the will first.`,`At midnight {boss} will beat the truth out of the ferryman; after 6 hours {villain} will come to {place} in person with lamp oil to see the will burn, and at dawn {villain} will set fire to the mill, so that the search party finds only ashes and a story about {foe}.`]),weakness:B([`{villain} stoler ikke på de lejede folk med testamentet og må selv til {place} for at se det brænde, og {villain} kender ikke hjulkælderen, som kun den gamle møllers familie kender.`,`Hele planen hviler på historien om {foe}: Ser nogen fra {town} {npc2} i live med testamentet, falder den, og så vil {villain} hellere forhandle end lade sig fange sammen med {boss}.`],[`{villain} does not trust the hirelings with the will and must go to {place} in person to see it burn, and {villain} does not know of the wheel pit, which only the old miller’s family knows of.`,`The whole plan rests on the story about {foe}: if anyone from {town} sees {npc2} alive with the will, the story falls apart, and then {villain} would rather bargain than be caught alongside {boss}.`])},stakes:B(`Brænder møllen med {npc2} i hjulkælderen og testamentet med, arver {villain} mølleretten efter loven, sælger den til købmanden for gælden, og hele {town} tror for altid, at nogle {foe} tog {npc2}. Ingen spørger mere til {villain}s år som værge, og {npc1}, der lukkede {npc2} ud, må bære skylden alene.`,`If the mill burns with {npc2} in the wheel pit and the will with it, {villain} inherits the milling right by law, sells it to the merchant for the debt, and all of {town} believes forever that {foe} took {npc2}. Nobody asks about {villain}’s years as guardian again, and {npc1}, who let {npc2} out, must carry the guilt alone.`),clock:{start:B(`Sen aften, otte timer før daggry. {npc2} forsvandt ved skumring, og et par timer senere slog {villain} alarm og fortalte hele {town}, at nogle {foe} fra {place} havde båret {npc2} bort; ved daggry drager rådet derud i stedet for at holde bryllup. Imens leder {boss} og nogle {foe} i al stilhed vejene og kroerne igennem efter {npc2} på {villain}s ordre.`,`Late evening, eight hours before dawn. {npc2} vanished at dusk, and a couple of hours later {villain} raised the alarm and told all of {town} that {foe} from {place} had carried {npc2} off; at dawn, instead of holding a wedding, the council will set out there. Meanwhile {boss} and some {foe} quietly search the roads and the inns for {npc2} on {villain}’s orders.`),ticks:[H(B(`Efter 2 timer (ved midnat)`,`After 2 hours (at midnight)`),B(`{boss} og nogle {foe} kommer ned til færgelejet, banker sandheden og nøglen til lænken ud af {npc3} og sætter over floden med færgen, mens en af dem løber tilbage til rådhuset med bud til {villain}.`,`{boss} and some {foe} come down to the ferry landing, beat the truth and the key to the chain out of {npc3} and cross the river by the ferry, while one of them runs back to the council hall with word for {villain}.`),B(`Et råb og et brag fra færgehuset, og færgens lygte glider ud over det sorte vand.`,`A shout and a crash from the ferry house, and the ferry’s lantern slides out across the black water.`)),H(B(`Efter 4 timer`,`After 4 hours`),B(`{boss} og nogle {foe} har ledt engene langs floden igennem på vejen og når nu {place}, bryder ind i møllerhuset og begynder at gennemsøge møllen med fakler; måtte de gå uden om ad den gamle bro, når de først frem efter 6 timer.`,`{boss} and some {foe}, having combed the riverside meadows on the way, reach {place}, break into the miller’s cottage and start searching the mill by torchlight; if they had to go round by the old bridge, they do not arrive until after 6 hours.`),B(`Fakler bevæger sig mellem møllens mure, og fra mølledammen lyder knas af brædder, der bliver revet op.`,`Torches move between the mill’s walls, and from the millpond comes the crack of boards being torn up.`)),H(B(`Efter 6 timer`,`After 6 hours`),B(`{villain} når selv {place} til hest ad vejen over den gamle bro med en lygte og en krukke lampeolie efter at have sagt til vagten, at {villain} rider i forvejen for at finde sporet; nu leder {villain} selv søgningen og vil se testamentet brænde.`,`{villain} reaches {place} in person on horseback by the road over the old bridge, with a lantern and a jar of lamp oil, having told the watch that {villain} is riding ahead to find the trail; now {villain} directs the search and means to see the will burn.`),B(`En enkelt lygte kommer ridende langs flodbredden, og i {town} siger vagten, at {villain} er redet i forvejen.`,`A single lantern comes riding along the riverbank, and in {town} the watch says that {villain} has ridden on ahead.`)),H(B(`Efter 8 timer (ved daggry)`,`After 8 hours (at dawn)`),B(`Rådet og følget samles ved færgelejet i {town}, og i {place} opgiver {villain} søgningen, hælder olien ud over møllehusets gulv og sætter ild til; er {npc2} stadig i hjulkælderen, kommer {npc2} aldrig ud, og testamentet brænder med.`,`The council and the search party gather at the ferry landing in {town}, and at {place}, {villain} gives up the search, pours the oil over the floor of the mill house and sets it alight; if {npc2} is still in the wheel pit, {npc2} never comes out, and the will burns too.`),B(`Røg stiger op over {place} i det første grå lys og kan ses fra hele {town}.`,`Smoke rises over {place} in the first grey light and can be seen from all over {town}.`))],deadline:B(`Efter 8 timer, ved daggry, er det for sent: Møllen brænder med {npc2} i hjulkælderen, testamentet er aske, og da følget når frem halvanden time senere, står {villain} grædende ved ruinen med en historie om {foe}.`,`After 8 hours, at dawn, it is too late: the mill burns with {npc2} in the wheel pit, the will is ash, and when the search party arrives an hour and a half later, {villain} stands weeping by the ruin with a story about {foe}.`)},clues:{who:[V(`town`,B(`I {villain}s skrivestue ligger en afskrift af ægtepagten, hvor mølleretten ved {place} er skrevet ind som {npc2}s medgift, og et brev fra købmanden, der eftergiver {villain}s gæld den dag, {npc2} er gift.`,`In {villain}’s study lies a copy of the marriage contract, with the milling right at {place} written in as {npc2}’s dowry, and a letter from the merchant forgiving {villain}’s debt on the day {npc2} is married.`),B(`{villain} ville give {npc2}s arv bort for at slippe for sin egen gæld.`,`{villain} meant to give away {npc2}’s inheritance to be rid of {villain}’s own debt.`),_t([`Kære {villain},`,`når mølleretten ved {place} står i ægtepagten som medgift, og {npc2} er gift med mig ved daggry,`,`er Deres gæld til mig strøget, hver en skilling.`,`Sørg for, at brylluppet holdes til tiden.`],[`Dear {villain},`,`once the milling right at {place} is written into the marriage contract as the dowry and {npc2} is wed to me at dawn,`,`your debt to me is struck out, every penny.`,`See that the wedding is held on time.`])),V(`town`,B(`Slåen på køkkendøren er hel og står lænet op ad væggen, og i gården bag køkkenet er der ingen andre spor end {npc2}s egne støvleaftryk, der går ud ad porten mod floden.`,`The bar of the kitchen door is whole and leans against the wall, and in the yard behind the kitchen there are no tracks but {npc2}’s own boot prints, going out through the gate toward the river.`),B(`Ingen brød ind: {npc2} gik selv, og {villain}s historie om {foe} er løgn.`,`Nobody broke in: {npc2} left willingly, and {villain}’s story about {foe} is a lie.`)),V(`town`,B(`{npc3}, færgemanden, fortæller, at {villain} kom ned til færgen ved mørkets frembrud, en time før alarmen gik, og spurgte, om {npc2} var sat over med et læderhylster under armen.`,`{npc3}, the ferryman, says that {villain} came down to the ferry at nightfall, an hour before the alarm was raised, and asked whether {npc2} had crossed with a leather case under one arm.`),B(`{villain} vidste, at {npc2} var flygtet med papirerne, før {villain} fortalte byen om {foe}.`,`{villain} knew {npc2} had fled with the papers before telling the town about {foe}.`)),V(`site`,B(`I slusehuset ved dammen ligger en krøllet seddel, skrevet med {villain}s egen hånd og tabt, da {villain} og købmanden var herude for at måle op i sommer.`,`In the sluice house by the millpond lies a crumpled note in {villain}’s own hand, dropped when {villain} and the merchant came out to take measurements this summer.`),B(`{villain} har regnet på, hvad {npc2}s død og et forsvundet testamente er værd for {villain}.`,`{villain} has worked out what {npc2}’s death and a vanished will would be worth to {villain}.`),_t([`Mølleretten: 600 sølv (købmandens bud).`,`Min gæld til købmanden: 600 sølv. Går lige op ved brylluppet.`,`Uden testamentet: Dør {npc2} ugift, er alt mit efter loven.`],[`The milling right: 600 silver (the merchant’s offer).`,`My debt to the merchant: 600 silver. Comes out even at the wedding.`,`Without the will: if {npc2} dies unmarried, everything is mine by law.`]))],where:[V(`town`,B(`I asken i kakkelovnen i {npc2}s kammer ligger et halvbrændt brev, skrevet med en anden hånd end {npc2}s.`,`In the ashes of the stove in {npc2}’s bedchamber lies a half-burnt letter in a hand other than {npc2}’s.`),B(`{npc2} gik frivilligt til færgen ved skumring og videre til den gamle mølle, {place}, sammen med en ven.`,`{npc2} went willingly to the ferry at dusk and on to the old mill, {place}, with a friend.`),_t([`… ved færgen, når solen går ned. Tag kun det, du kan bære …`,`… den gamle mølle. Der leder ingen, alle er bange for stedet …`,`… brænd dette.`],[`… at the ferry when the sun goes down. Take only what you can carry …`,`… the old mill. Nobody looks there, everyone is afraid of the place …`,`… burn this.`])),V(`town`,B(`{npc3}, færgemanden, satte {npc2} og en barndomsven over floden ved skumring, så dem gå op ad stien langs møllebækken mod {place} og fik en guldring som betaling for at tie.`,`{npc3}, the ferryman, took {npc2} and a childhood friend across the river at dusk, watched them go up the path along the millstream toward {place} and was paid in a gold ring to keep quiet.`),B(`{npc2} er i {place} på den anden side af floden.`,`{npc2} is at {place}, across the river.`)),V(`site`,B(`Ved dammen går to par friske støvlespor fra stien, ikke hen til møllerhuset, men over planken ved afløbsrenden til en lav dør i møllens side.`,`By the millpond two pairs of fresh boot prints leave the path, not toward the miller’s cottage but over the plank across the tailrace to a low door in the side of the mill.`),B(`{npc2} og vennen gemmer sig inde i selve møllen, ved hjulet.`,`{npc2} and the friend are hiding inside the mill itself, by the wheel.`)),V(`site`,B(`Fra planken over afløbsrenden ved dammen skinner et svagt lys ud af en revne i hjulhuset lige over renden, og der lugter af tællelys og nybagt brød fra et sted under møllens gulv.`,`From the plank across the tailrace by the millpond a faint light leaks from a crack in the wheelhouse just above the race, and there is a smell of tallow and fresh bread from somewhere beneath the mill floor.`),B(`Der er et skjul under møllens gulv ved hjulet, og nogen er dernede lige nu.`,`There is a hiding place beneath the mill floor by the wheel, and someone is down there right now.`))]},endings:{success:B(`{npc2} står levende foran rådet med testamentet i hånden, og ægtepagten bliver revet over, for mølleretten måtte aldrig gives bort. {villain} bliver ført bort af vagten og må stå til regnskab for hvert år som værge; fik heltene {npc3} til at vidne, ved hele {town}, at {villain} kendte sandheden, før alarmen gik. Til foråret begynder {npc2} at bygge møllen op igen, og {npc1} bager det første brød af dens mel.`,`{npc2} stands alive before the council with the will in hand, and the marriage contract is torn up, for the milling right could never be given away. {villain} is led off by the watch and must account for every year as guardian; if the heroes got {npc3} to testify, all of {town} knows that {villain} knew the truth before the alarm was raised. In spring {npc2} starts to rebuild the mill, and {npc1} bakes the first bread from its flour.`),partial:B(`{npc2} overlever, men testamentet brænder i møllen. Uden det står {npc2}s ord mod værgens, {villain} kalder heltene for bortførere, og brylluppet er kun udsat; vidner {npc3} om {villain}s besøg ved færgen, tager rådet dog værgemålet fra {villain}, til sagen er afgjort. Imens skjuler {npc1} {npc2} i køkkenet, og halvdelen af {town} tror stadig på historien om {foe}.`,`{npc2} survives, but the will burns in the mill. Without it {npc2}’s word stands against the guardian’s, {villain} calls the heroes kidnappers, and the wedding is only postponed; if {npc3} testifies about {villain}’s visit to the ferry, the council at least takes the guardianship from {villain} until the matter is settled. Meanwhile {npc1} hides {npc2} in the kitchen, and half of {town} still believes the story about {foe}.`),failure:B(`Ved daggry står møllen i flammer, og {npc2} kommer aldrig op af hjulkælderen. Da følget når frem, står {villain} grædende ved ruinen og takker byen for at komme; {town} jager {foe} i en uge, {villain} arver mølleretten og sælger den til købmanden for gælden, og {npc1} bliver sat på gaden for at have ladet køkkendøren stå åben. {npc3}, der kender sandheden, tør aldrig sige den højt.`,`At dawn the mill is in flames, and {npc2} never comes out of the wheel pit. When the search party arrives, {villain} stands weeping by the ruin and thanks the town for coming; {town} hunts {foe} for a week, {villain} inherits the milling right and sells it to the merchant for the debt, and {npc1} is turned out for leaving the kitchen door open. {npc3}, who knows the truth, never dares to say it aloud.`)}},yt={opening:{kind:`opening`,at:`town`,present:[`npc1`],title:B(`Køkkenet i bryllupshuset`,`The Wedding Kitchen`),summary:B([`Sent om aftenen trækker {npc1}, den gamle kok i {villain}s hus, heltene ind i køkkenet, hvor maden til brylluppet står urørt.`,`{npc2}, der skulle giftes ved daggry, forsvandt ved skumring, og {villain} fortæller hele {town}, at nogle {foe} fra {place} bar {npc2} bort; rådet vil drage derud ved daggry.`,`{npc1} tror ikke på historien og beder heltene finde ud af, hvad der virkelig er sket, og finde {npc2}, før nogen anden gør det.`],[`Late in the evening {npc1}, the old cook in {villain}’s household, draws the heroes into the kitchen, where the food for the wedding stands untouched.`,`{npc2}, who was to be married at dawn, vanished at dusk, and {villain} is telling all of {town} that {foe} from {place} carried {npc2} off; the council means to set out there at dawn.`,`{npc1} does not believe the story and asks the heroes to find out what really happened, and to find {npc2} before anyone else does.`]),readAloud:B([`Køkkenet er varmt og fuldt af bryllupsmad til brudeparret: stegte høns, honningkager i lange rækker og et kransekagetårn, som ingen kommer til at spise.`,`En gammel kok med melede hænder lukker døren til gården bag heltene og taler lavt.`,`Ude fra torvet, hvor vagten samler folk til at drage ud ved daggry, lyder råb, og fakler bevæger sig forbi vinduet.`],[`The kitchen is warm and full of food for the bridal feast: roast hens, honey cakes in long rows and a tower of almond rings that no one will ever eat.`,`An old cook with floury hands shuts the door to the yard behind you and speaks in a low voice.`,`From the square, where the watch is gathering people to set out at dawn, come shouts, and torches move past the window.`]),details:[B(`{npc1} fortæller: {npc2} skulle giftes ved daggry med en rig købmand, mange år ældre, og brylluppet er arrangeret af {villain}, {npc2}s værge og nærmeste slægtning. Som medgift følger mølleretten ved {place}, eneretten til at male dalens korn; {npc2} arvede den efter forældrene, der døde for tolv år siden, og møllen har ligget øde lige så længe, men købmanden vil bygge den op igen. {npc2} har været bleg og stille i to dage og forsvandt ved skumring, og et par timer senere slog {villain} alarm og sagde, at nogle {foe} fra {place} var kravlet ind ad {npc2}s vindue og havde båret {npc2} bort.`,`{npc1} explains: {npc2} was to be married at dawn to a rich merchant, many years older, in a match arranged by {villain}, {npc2}’s guardian and next of kin. The dowry is the milling right at {place}, the sole right to grind the valley’s grain; {npc2} inherited it when {npc2}’s parents died twelve years ago, and the mill has lain derelict for just as long, but the merchant means to rebuild it. {npc2} has been pale and quiet for two days and vanished at dusk, and a couple of hours later {villain} raised the alarm, saying that {foe} from {place} had climbed in at {npc2}’s window and carried {npc2} off.`),B(`Slåen på køkkendøren er hel og står lænet op ad væggen, og i gården bag køkkenet er der ingen andre spor end {npc2}s egne støvleaftryk, der går ud ad porten mod floden. Ingen har set noget kravle over tagene. {npc1} siger ikke noget om slåen, men flytter sig uroligt, når heltene ser på den.`,`The bar of the kitchen door is whole and leans against the wall, and in the yard behind the kitchen there are no tracks but {npc2}’s own boot prints, going out through the gate toward the river. Nobody saw anything climb over the roofs. {npc1} says nothing about the bar, but shifts uneasily when the heroes look at it.`),B(`Der er otte timer til daggry. {npc2}s kammer og {villain}s skrivestue ligger ovenpå, og {villain} er på rådhuset med vagten. Færgemanden {npc3} bor ved færgelejet, og den gamle bro ligger opstrøms. Vejen: fra huset til færgelejet et kvarter, over floden med trækfærgen et kvarter og fra færgelejet på den anden side 1 time ad stien langs møllebækken til {place}, i alt halvanden time. Uden færgen går vejen over den gamle bro: 4 timer til fods og 2 til hest. Hvert besøg i {town} koster en halv time ud over vejen.`,`There are eight hours until dawn. {npc2}’s bedchamber and {villain}’s study are upstairs, and {villain} is at the council hall with the watch. {npc3}, the ferryman, lives by the ferry landing, and the old bridge lies upstream. Distances: from the house to the ferry landing a quarter of an hour, across the river by the rope ferry a quarter of an hour, and from the far landing 1 hour along the path by the millstream to {place}, an hour and a half in all. Without the ferry the route goes over the old bridge: 4 hours on foot, 2 on horseback. Every visit in {town} costs half an hour on top of the walk.`)],checks:[U(`Wisdom (Insight)`,`easy`,B(`{npc1} tilstår at have slået slåen fra for {npc2} ved skumring og givet {npc2} brød med på vejen uden at spørge hvorhen. {npc1} giver heltene et løsen: Siger de "Spurv", det kælenavn, kun {npc1} har brugt, siden {npc2} var lille, ved {npc2}, at de kommer fra køkkenet.`,`{npc1} admits drawing back the bar for {npc2} at dusk and giving {npc2} bread for the road without asking where to. {npc1} gives the heroes a password: if they say "Sparrow", the pet name only {npc1} has used since {npc2} was small, {npc2} will know they come from the kitchen.`),B(`{npc1} holder på sin hemmelighed af frygt for at miste pladsen. Heltene får intet løsen, og {npc2} vil ikke uden videre stole på fremmede.`,`{npc1} keeps the secret for fear of losing their position. The heroes get no password, and {npc2} will not readily trust strangers.`)),U(`Intelligence (Investigation)`,`medium`,B(`Heltene ser, at slåen er trukket fra indefra og aldrig brudt, og at sporene i gården kun er {npc2}s: Ingen kom ind, og {npc2} gik selv.`,`The heroes see that the bar was drawn back from inside and never broken, and that the only tracks in the yard are {npc2}’s: nobody came in, and {npc2} left willingly.`),B(`Gården er trådt op af vagten og nysgerrige naboer; at {npc2} gik frivilligt, finder heltene først ud af ovenpå eller ved færgen.`,`The yard has been trampled by the watch and curious neighbours; the heroes do not learn that {npc2} left willingly until they go upstairs or to the ferry.`))],fight:!1,alternatives:[B(`Gå direkte til færgelejet: Heltene sparer tiden i huset, men ved ikke, hvorfor {npc2} flygtede, og har intet at vise rådet om {villain}.`,`Go straight to the ferry landing: the heroes save the time in the house, but do not know why {npc2} fled and have nothing to show the council against {villain}.`),B(`Gå til rådhuset, og kald historien en løgn: Uden beviser tror ingen på en kok og nogle fremmede, og fra nu af ved {villain}, at nogen er på sporet, og sender bud til {boss}.`,`Go to the council hall and call the story a lie: without proof nobody believes a cook and a few strangers, and from now on {villain} knows someone is on the trail and sends word to {boss}.`)],dmNotes:B(`Lad den urørte bryllupsmad tale: Hver tallerken er et spørgsmål. {npc1} er heltenes eneste ven i huset og mere bange for at have sendt {npc2} i ulykke end for {villain}; den, der vinder kokkens tillid, får nøglen til resten.`,`Let the untouched wedding food speak: every plate is a question. {npc1} is the heroes’ only friend in the house and more afraid of having sent {npc2} into danger than of {villain}; whoever wins the cook’s trust gets the key to the rest.`)},middle:[{kind:`investigation`,at:`town`,present:[],title:B(`Kammeret og skrivestuen`,`The Bedchamber and the Study`),summary:B([`{npc2}s kammer ligger ovenpå i {villain}s hus, og ved siden af ligger {villain}s skrivestue, låst, men {npc1} ved, hvor nøglen hænger.`,`{villain} er på rådhuset og lægger planer med vagten og kommer først hjem efter 4 timer for at hente sin hest og en krukke lampeolie.`,`Her kan heltene se, at historien om {foe} ikke passer, og finde ud af, hvorfor {npc2} flygtede, og hvorhen.`],[`{npc2}’s bedchamber is upstairs in {villain}’s house, and next to it lies {villain}’s study, locked, but {npc1} knows where the key hangs.`,`{villain} is at the council hall making plans with the watch and does not come home until after 4 hours, to fetch a horse and a jar of lamp oil.`,`Here the heroes can see that the story about {foe} does not hold up, and find out why {npc2} fled, and where to.`]),readAloud:B([`Kammeret er lille og pænt, og på sengen ligger bryllupsdragten lagt frem, urørt, med en krans af hvide blomster ovenpå.`,`Skodderne står åbne ud mod gården, og potterne med pelargonier står pænt på række i vindueskarmen.`,`Inde ved siden af lugter skrivestuen af lak og pibetobak, og på skrivebordet står et jernbeslået skrin under et portræt af to smilende mennesker.`],[`The bedchamber is small and neat, and the wedding clothes are laid out on the bed, untouched, with a wreath of white flowers on top.`,`The shutters stand open onto the yard, and pots of geraniums sit in a tidy row on the sill.`,`Next door the study smells of sealing wax and pipe smoke, and on the desk stands an iron-bound strongbox beneath a portrait of two smiling people.`]),details:[B(`{villain} har vist vagten de åbne skodder i kammeret som stedet, hvor {foe} kom ind, men potterne i vindueskarmen står urørte, der er ikke en ridse i karmen, og mosset på tagstenene under vinduet er helt. Rejsekappen og støvlerne er væk fra knagen, og sengen er ikke sovet i.`,`{villain} has shown the watch the open shutters as the way {foe} came in, but the pots on the sill stand untouched, there is not a scratch on the frame, and the moss on the roof tiles below the window is unbroken. The heir’s travelling cloak and boots are gone from their peg, and the bed has not been slept in.`),B(`I asken i kakkelovnen i {npc2}s kammer ligger et halvbrændt brev, skrevet med en anden hånd end {npc2}s. Det, der er tilbage, nævner færgen ved solnedgang og den gamle mølle, hvor ingen leder.`,`In the ashes of the stove in {npc2}’s bedchamber lies a half-burnt letter in a hand other than {npc2}’s. What is left of it mentions the ferry at sundown and the old mill, where nobody looks.`),B(`I skrivebordet i {villain}s skrivestue ligger en afskrift af ægtepagten, hvor mølleretten ved {place} er skrevet ind som {npc2}s medgift, og et brev fra købmanden, der eftergiver {villain}s gæld den dag, {npc2} er gift. Det jernbeslåede skrin, hvor testamentet efter {npc2}s forældre plejer at ligge i et læderhylster, er tomt; nøglen til det hænger bag portrættet af {npc2}s forældre, hvor den altid har hængt, og det har {npc2} vidst, siden {npc2} var barn.`,`In the desk in {villain}’s study lies a copy of the marriage contract, with the milling right at {place} written in as {npc2}’s dowry, and a letter from the merchant forgiving {villain}’s debt on the day {npc2} is married. The iron-bound strongbox where the will of {npc2}’s parents is kept in a leather case is empty; its key hangs behind the portrait of {npc2}’s parents, where it has always hung, and {npc2} has known that since childhood.`)],checks:[U(`Intelligence (Investigation)`,`medium`,B(`Heltene finder det halvbrændte brev i kakkelovnen og ser, at ingen fremmed har været i kammeret: {npc2} gik selv, og målet var færgen og den gamle mølle.`,`The heroes find the half-burnt letter in the stove and see that no stranger has been in the room: {npc2} left willingly, heading for the ferry and the old mill.`),B(`Asken smuldrer mellem fingrene; heltene ser kun, at rejsetøjet er væk, og må finde ud af resten ved færgen.`,`The ashes crumble between their fingers; the heroes see only that the travelling clothes are gone, and must learn the rest at the ferry.`)),U(`Dexterity (Sleight of Hand)`,`medium`,B(`Heltene åbner skrivebordet og skrinet med nøglen bag portrættet og lægger alt tilbage, så {villain} intet mærker.`,`The heroes open the desk and the strongbox with the key behind the portrait and put everything back, so that {villain} notices nothing.`),B(`Låsen i skrivebordet driller, og en skuffe flækker. Heltene får papirerne, men når {villain} kommer hjem efter 4 timer, ser {villain} skuffen og ved, at nogen er på sporet.`,`The desk lock sticks, and a drawer splits. The heroes get the papers, but when {villain} comes home after 4 hours, {villain} sees the drawer and knows someone is on the trail.`))],fight:!1,alternatives:[B(`Tag ægtepagten og købmandens brev med: De er beviser for rådet, men når {villain} kommer hjem efter 4 timer, savner {villain} dem og ved, at nogen er på sporet.`,`Take the marriage contract and the merchant’s letter along: they are proof for the council, but when {villain} comes home after 4 hours, {villain} misses them and knows someone is on the trail.`),B(`Vent i huset, til {villain} kommer hjem efter 4 timer, og følg efter: {villain} rider ud ad vejen over den gamle bro med en krukke lampeolie, og den, der følger efter til hest, bliver ført lige til {place} og når frem efter 6 timer.`,`Wait in the house until {villain} comes home after 4 hours, and follow: {villain} rides out by the road over the old bridge with a jar of lamp oil, and anyone following on horseback is led straight to {place}, arriving after 6 hours.`)],dmNotes:B(`Lad kammeret fortælle, at {npc2} gik frivilligt, og skrivestuen fortælle hvorfor. {npc1} holder vagt i køkkenet nedenunder og banker på loftet med et kosteskaft, så snart {villain}s skridt lyder i gården.`,`Let the bedchamber show that {npc2} left willingly, and the study show why. {npc1} keeps watch in the kitchen below and knocks on the ceiling with a broom handle as soon as {villain}’s steps sound in the yard.`)},{kind:`social`,at:`town`,present:[`npc3`],title:B(`Færgelejet`,`The Ferry Landing`),summary:B([`Ved floden, et kvarter fra torvet, bor {npc3}, færgemanden, i et lille hus ved trækfærgen, der om natten ligger lænket til pælen.`,`{npc3} satte {npc2} og en barndomsven over ved skumring og har lovet at tie, og da {villain} kom ned ved mørkets frembrud og spurgte, løj {npc3}.`,`Her kan heltene få sandheden og en vej over floden og sørge for, at {villain}s lejede folk ingen af delene får, når de kommer ved midnat.`],[`By the river, a quarter of an hour from the square, {npc3}, the ferryman, lives in a small house beside the rope ferry, which lies chained to its post at night.`,`{npc3} took {npc2} and a childhood friend across at dusk and promised to keep quiet, and when {villain} came down at nightfall asking, {npc3} lied.`,`Here the heroes can get the truth and a way across the river, and make sure {villain}’s hirelings get neither when they come at midnight.`]),readAloud:B([`Færgehuset ligger lavt ved vandet med en lygte over døren, og ved pælen ligger en bred, flad færge lænket fast med et tykt tov, der løber ud over floden og forsvinder i mørket.`,`Floden er bred og strid af forårsvand, og på den anden side ses kun sorte elletræer.`,`På bænken uden for døren sidder en færgemand med vejrbidte hænder og splejser tov uden at se op.`],[`The ferry house sits low by the water with a lantern over the door, and at the post lies a broad, flat ferry, chained fast, with a thick rope running out across the river and vanishing into the dark.`,`The river is wide and swift with spring water, and on the far side only black alders can be seen.`,`On the bench outside the door sits a ferryman with weathered hands, splicing rope without looking up.`]),details:[B(`{npc3} satte {npc2} og en barndomsven over floden ved skumring, så dem gå op ad stien langs møllebækken mod {place} og fik en guldring som betaling for at tie. Ringen hænger i en snor under færgemandens skjorte, og indeni står navnene på {npc2}s forældre.`,`{npc3} took {npc2} and a childhood friend across the river at dusk, watched them go up the path along the millstream toward {place} and was paid in a gold ring to keep quiet. The ring hangs on a cord under the ferryman’s shirt, engraved inside with the names of {npc2}’s parents.`),B(`Ved mørkets frembrud, en time før alarmen gik, kom {villain} selv ned til færgen og spurgte, om {npc2} var sat over med et læderhylster under armen; {npc3} løj og sagde, at ingen var sat over i aften. Siden har {npc3} hørt historien om {foe} fra {place} og forstået, at den ikke passer, og er bange.`,`At nightfall, an hour before the alarm was raised, {villain} came down to the ferry in person and asked whether {npc2} had crossed with a leather case under one arm; {npc3} lied and said no one had crossed tonight. Since then {npc3} has heard the story about {foe} from {place}, knows it does not hold up and is afraid.`),B(`Trækfærgen hales over langs tovet på et kvarter, og nøglen til lænken har kun {npc3}. Ved midnat (efter 2 timer) kommer {boss} og nogle {foe} ned til færgelejet: Er {npc3} der alene, banker de sandheden og nøglen ud af færgemanden og sætter over. Står heltene på færgelejet, vil {boss} ikke slås så tæt på byen og trækker sig. Ligger færgen på den anden side af floden ved midnat, eller står heltene på færgelejet, gætter {boss} resten, men de lejede folk må gå uden om ad den gamle bro og når først {place} efter 6 timer i stedet for 4.`,`The ferry is hauled across along its rope in a quarter of an hour, and only {npc3} has the key to the chain. At midnight (after 2 hours) {boss} and some {foe} come down to the landing: if {npc3} is there alone, they beat the truth and the key out of the ferryman and cross. If the heroes stand on the landing, {boss} will not fight so close to town and pulls back. If the ferry lies on the far side of the river at midnight, or the heroes stand on the landing, {boss} guesses the rest, but the hirelings must go round by the old bridge and do not reach {place} until after 6 hours instead of 4.`)],checks:[U(`Charisma (Persuasion)`,`medium`,B(`{npc3} fortæller alt, viser ringen og sætter heltene over. Færgemanden bliver på den anden side med færgen lænket til pælen dér, så {villain}s lejede folk må gå uden om ad den gamle bro; ved daggry henter {npc3} rådet over og vidner for det.`,`{npc3} tells everything, shows the ring and takes the heroes across. The ferryman stays on the far side with the ferry chained to the post there, so {villain}’s hirelings must go round by the old bridge; at dawn {npc3} ferries the council across and testifies before it.`),B(`{npc3} holder fast i løgnen, men sætter heltene over for en sølvmønt uden at spørge om noget og haler færgen tilbage; når {boss} kommer ved midnat, er færgemanden alene ved pælen.`,`{npc3} sticks to the lie, but takes the heroes across for a silver coin without asking questions and hauls the ferry back; when {boss} comes at midnight, the ferryman is alone at the post.`)),U(`Wisdom (Insight)`,`easy`,B(`Heltene ser, at {npc3} lyver af frygt og ikke af ondskab, og får øje på guldringen i snoren; nævner de ringen, har de fordel på at overtale færgemanden.`,`The heroes see that {npc3} is lying out of fear, not malice, and spot the gold ring on its cord; if they mention the ring, they have advantage on the check to persuade the ferryman.`),B(`{npc3} virker bare mut og træt, og ringen ser heltene først, hvis færgemanden selv viser dem den.`,`{npc3} just seems sullen and tired, and the heroes only see the ring if the ferryman shows it to them.`))],fight:!1,alternatives:[B(`Bryd lænken op, og hal jer selv over: Det larmer og tager en halv time, men så ligger færgen på den anden side af floden; {npc3} bliver tilbage og står alene, når {boss} kommer ved midnat.`,`Break the chain and haul the ferry across: it is noisy and takes half an hour, but then the ferry lies on the far side of the river; {npc3} stays behind, alone, when {boss} comes at midnight.`),B(`Gå over den gamle bro: Heltene behøver ikke færgemanden, men vejen tager 4 timer til fods eller 2 til hest, og {npc3} står alene, når {boss} kommer ved midnat.`,`Go by the old bridge: the heroes do not need the ferryman, but the route takes 4 hours on foot or 2 on horseback, and {npc3} is alone when {boss} comes at midnight.`)],dmNotes:B(`{npc3} er et ærligt menneske, der har løjet for at holde et løfte. Lad spillerne mærke, at sandheden koster færgemanden noget: Den, der taler i nat, skal stå ansigt til ansigt med {villain} i morgen.`,`{npc3} is an honest soul who has lied to keep a promise. Let the players feel that the truth costs the ferryman something: whoever speaks tonight must face {villain} tomorrow.`)},{kind:`exploration`,at:`site`,present:[],title:B(`Dammen ved møllen`,`The Millpond`),summary:B([`{place} er en forfalden vandmølle ved en mølledam en times gang fra færgelejet på den anden side af floden: et skævt møllehus af tømmer på en fod af sten med det store hjul på siden, et tomt møllerhus og et lille slusehus ved dammen.`,`Her skal heltene finde ud af, hvor {npc2} gemmer sig, før {villain}s lejede folk gør det.`,`Efter 4 timer, eller efter 6, hvis de måtte gå uden om ad den gamle bro, gennemsøger {boss} og nogle {foe} stedet med fakler.`],[`{place} is a ruined watermill by a millpond an hour’s walk from the far ferry landing: a crooked timber mill house on a stone footing with the great wheel at its side, an empty miller’s cottage and a small sluice house by the pond.`,`Here the heroes must work out where {npc2} is hiding before {villain}’s hirelings do.`,`After 4 hours, or after 6 if they had to go round by the old bridge, {boss} and some {foe} search the place by torchlight.`]),readAloud:B([`Stien ender ved en sort mølledam, hvor sivene står højt, og bag den rejser møllen sig: et skævt møllehus af tømmer på en fod af sten med et møllehjul så stort som et hus, der står helt stille.`,`Ved dammens ende står et lille slusehus med en rusten dør på klem, og et stykke derfra et møllerhus med tomme vinduer.`,`Under hjulet klukker vandet i afløbsrenden, og en smal planke fører over renden til en lav dør i møllens side.`],[`The path ends at a black millpond where the reeds stand tall, and behind it the mill rises: a crooked timber mill house on a stone footing, with a mill wheel as big as a house standing perfectly still.`,`At the end of the pond stands a small sluice house with a rusty door ajar, and some way off a miller’s cottage with empty windows.`,`Under the wheel the water chuckles in the tailrace, and a narrow plank leads across the race to a low door in the side of the mill.`]),details:[B(`Ved dammen går to par friske støvlespor fra stien, ikke hen til møllerhuset, men over planken ved afløbsrenden til den lave dør i møllens side. Fra planken skinner et svagt lys ud af en revne i hjulhuset lige over renden, og der lugter af tællelys og nybagt brød fra et sted under møllens gulv.`,`By the millpond two pairs of fresh boot prints leave the path, not toward the miller’s cottage but over the plank across the tailrace to the low door in the side of the mill. From the plank a faint light leaks from a crack in the wheelhouse just above the race, and there is a smell of tallow and fresh bread from somewhere beneath the mill floor.`),B(`I slusehuset ved dammen ligger en krøllet seddel, skrevet med {villain}s egen hånd og tabt, da {villain} og købmanden var herude for at måle op i sommer. Den regner mølleretten op imod {villain}s gæld og slutter med, hvad der sker, hvis {npc2} dør ugift, og testamentet er væk. Møllerhuset har stået tomt i tolv år.`,`In the sluice house by the millpond lies a crumpled note in {villain}’s own hand, dropped when {villain} and the merchant came out to take measurements this summer. It weighs the milling right against {villain}’s debt and ends with what happens if {npc2} dies unmarried and the will is gone. The miller’s cottage has stood empty for twelve years.`),B(`{boss} og nogle {foe} kommer efter 4 timer ad stien fra færgelejet, eller efter 6 timer langs flodbredden fra den gamle bro, og gennemsøger møllerhuset og møllen med fakler; de kender ikke hjulkælderen og går ind ad møllens hoveddør, ikke over planken. Hvis {villain} ved, at nogen er på sporet, sætter de en vagt ved dammen: fra de kommer, hvis heltene talte på rådhuset, og fra 6 timer, hvis {villain} først så det i skrivestuen. Efter 6 timer står {villain}s hest bundet ved slusehuset.`,`{boss} and some {foe} arrive after 4 hours by the path from the ferry landing, or after 6 hours along the riverbank from the old bridge, and search the miller’s cottage and the mill by torchlight. They do not know of the wheel pit and go in by the mill’s main door, not over the plank. If {villain} knows someone is on the trail, the hirelings post a lookout by the pond: from their arrival if the heroes spoke out at the council hall, and after 6 hours if {villain} only found out in the study. After 6 hours {villain}’s horse stands tied by the sluice house.`)],checks:[U(`Wisdom (Survival)`,`medium`,B(`Heltene læser sporene og går lige over planken uden at spilde et øjeblik; de ved nu, at {npc2} er inde i møllen, under gulvet ved hjulet.`,`The heroes read the tracks and go straight over the plank without wasting a moment; they now know {npc2} is inside the mill, beneath the floor by the wheel.`),B(`Heltene gennemsøger møllerhuset og slusehuset først og mister en halv time, før de finder planken.`,`The heroes search the miller’s cottage and the sluice house first and lose half an hour before they find the plank.`)),U(`Dexterity (Stealth)`,`medium`,B(`Er de lejede folk her, glider heltene gennem sivene og over planken uden at blive set og når møllen før faklerne; står der en vagt ved dammen, er slaget svært i stedet for middel.`,`If the hirelings are here, the heroes slip through the reeds and over the plank unseen and reach the mill before the torches; if a lookout stands by the pond, the check is hard instead of medium.`),B(`En fakkel svinger mod sivene, og der lyder et råb; {boss} og de lejede folk når møllehuset samtidig med heltene, og kampen begynder dér.`,`A torch swings toward the reeds and a shout goes up; {boss} and the hirelings reach the mill house at the same time as the heroes, and the fight begins there.`))],fight:!1,alternatives:[B(`Gå ind ad møllens hoveddør: Det er hurtigere end planken, men døren vender lige ud mod dammen, hvor alle faklerne kan se den.`,`Go in by the mill’s main door: it is quicker than the plank, but the door faces straight onto the pond, where every torch can see it.`),B(`Lad som om, I hører til eftersøgningen: Med en fakkel og et par bandeord kan heltene gå lige igennem de lejede folk, men kun indtil {boss} ser dem i ansigtet.`,`Pose as searchers: with a torch and a few curses the heroes can walk straight through the hirelings, but only until {boss} sees their faces.`)],dmNotes:B(`Mølledammen er stilheden før kampen. Lad frøerne tie, når nogen nærmer sig, og vandet dryppe fra det standsede hjul, og lad spillerne selv finde planken og lyset under hjulet: Det er heltene, der skal finde {npc2}, ikke omvendt.`,`The millpond is the quiet before the fight. Let the frogs fall silent when anyone comes near and the water drip from the idle wheel, and let the players find the plank and the light under the wheel themselves: it is the heroes who must find {npc2}, not the other way round.`)}],climax:{kind:`climax`,at:`site`,present:[`npc2`,`villain`],title:B(`Hjulkælderen`,`The Wheel Pit`),summary:B([`Under gulvet i møllehuset i {place} ligger hjulkælderen, et lavt stenkammer ved det store møllehjul, som kun den gamle møllers familie kender; her sidder {npc2} og barndomsvennen med testamentet og venter på, at det bliver lyst.`,`Efter 4 timer, eller efter 6, hvis de måtte gå uden om ad den gamle bro, gennemsøger {boss} og nogle {foe} møllen over hovedet på dem; efter 6 timer kommer {villain} selv med lampeolie, og ved daggry sætter {villain} ild til møllen.`,`Heltene skal vinde {npc2}s tillid, holde {npc2} i live og testamentet helt gennem natten og standse {villain}, før olien brænder.`],[`Beneath the floor of the mill house at {place} lies the wheel pit, a low stone chamber beside the great mill wheel that only the old miller’s family knows of; here {npc2} and the childhood friend sit with the will, waiting for daylight.`,`After 4 hours, or after 6 if they had to go round by the old bridge, {boss} and some {foe} search the mill over their heads; after 6 hours {villain} comes in person with lamp oil, and at dawn {villain} sets fire to the mill.`,`The heroes must win {npc2}’s trust, keep {npc2} alive and the will whole through the night, and stop {villain} before the oil burns.`]),readAloud:B([`Inde i møllen ligger to store møllesten under et lag af gammelt melstøv, og langs væggene rådner sække i bunker.`,`Bjælkerne knager, når nogen går, og gennem væggen kan man høre vandet klukke i afløbsrenden under det store hjul.`,`Foran møllestenene ligger en bunke sække, der er skubbet lidt til side, og under dem lyder gulvet hult.`],[`Inside the mill two great millstones lie under a layer of old flour dust, and sacks rot in heaps along the walls.`,`The beams creak when anyone walks, and through the wall the water can be heard chuckling in the tailrace under the great wheel.`,`In front of the millstones lies a heap of sacks, pushed a little aside, and beneath them the floor rings hollow.`]),details:[B(`Kommer heltene, før de lejede folk er her, er møllen stille, og de kan nå {npc2} og gøre klar. {boss} og nogle {foe} kommer efter 4 timer ad stien fra færgelejet, eller efter 6 timer langs flodbredden fra den gamle bro, hvis de måtte gå uden om; de gennemsøger møllen med fakler, men kender ikke hjulkælderen. Blev heltene set ved mølledammen, når de lejede folk møllehuset samtidig med heltene, og kampen begynder, før nogen når lugen. {villain} kommer til hest ad vejen over den gamle bro efter 6 timer med en lygte og en krukke lampeolie.`,`If the heroes come before the hirelings, the mill is quiet, and they can reach {npc2} and get ready. {boss} and some {foe} arrive after 4 hours by the path from the ferry landing, or after 6 hours along the riverbank from the old bridge if they had to go round; they search the mill by torchlight, but do not know of the wheel pit. If the heroes were seen at the millpond, the hirelings reach the mill house at the same moment as the heroes, and the fight begins before anyone reaches the hatch. {villain} rides up by the road over the old bridge after 6 hours with a lantern and a jar of lamp oil.`),B(`I hjulkælderen sidder {npc2} og barndomsvennen, den gamle møllers barn, med et tællelys, et tæppe og brødet fra {npc1}s køkken. {npc2} lukker ikke lugen op for fremmede: Siger heltene "Spurv", det kælenavn, kun {npc1} bruger, stoler {npc2} straks på dem; ellers må de overtale {npc2}. Testamentet ligger i et læderhylster under {npc2}s kappe. {npc2} vil ikke tilbage over floden i mørket, for i {town} er {villain} stadig værge og kan låse {npc2} inde til brylluppet; hører {npc2}, at rådet drager ud ved daggry, vil {npc2} blive her og møde det med testamentet i hånden.`,`In the wheel pit sit {npc2} and the childhood friend, the old miller’s child, with a tallow candle, a blanket and the bread from {npc1}’s kitchen. {npc2} will not open the hatch to strangers: if the heroes say "Sparrow", the pet name only {npc1} uses, {npc2} trusts them at once; otherwise they must persuade {npc2}. The will lies in a leather case under {npc2}’s cloak. {npc2} will not go back across the river in the dark, for in {town}, {villain} is still the guardian and can lock {npc2} in until the wedding; on hearing that the council sets out at dawn, {npc2} wants to stay here and meet it with the will in hand.`),B(`{boss} og nogle {foe} er hyret af {villain} og kæmper for betalingen, ikke for {villain}: Falder {boss}, overgiver resten sig eller flygter. {villain} kæmper ikke, holder sig ved døren med lygten og olien og vil have testamentet: {villain} tilbyder at kalde de lejede folk tilbage, hvis heltene giver {villain} det, og siden en pung sølv og en del af mølleretten. Ved daggry, efter 8 timer, hælder {villain} olien ud over møllehusets gulv og sætter ild til, hvis ingen har standset {villain} inden.`,`{boss} and some {foe}, hired by {villain}, fight for their pay, not for {villain}: when {boss} falls, the rest surrender or flee. {villain} does not fight, keeps by the door with the lantern and the oil and wants the will: {villain} offers to call off the hirelings if the heroes hand it over, and after that a purse of silver and a share of the milling right. At dawn, after 8 hours, {villain} pours the oil over the floor of the mill house and sets it alight, unless someone has stopped {villain} first.`),B(`Brænder møllen, tager ilden det tørre tømmer og det gamle melstøv på et øjeblik: Efter ti runder falder gulvet over hjulkælderen sammen og spærrer lugen. Vennen kender den anden vej ud, afløbsrenden under hjulet, der kun er knæhøj, så længe slusen er lukket; åbner nogen slusen, begynder hjulet at dreje med et brøl, der overdøver alt, og så kan ingen vade ud ad renden. Rådet og følget samles ved færgelejet ved daggry og når {place} halvanden time senere; med {npc2} kan heltene gå dem i møde ad stien.`,`If the mill burns, the fire catches the dry timber and the old flour dust in moments: after ten rounds the floor over the wheel pit falls in and blocks the hatch. The friend knows the other way out, the tailrace under the wheel, only knee-deep as long as the sluice is shut; if anyone opens the sluice, the wheel starts to turn with a roar that drowns everything, and then nobody can wade out by the race. The council and the search party gather at the ferry landing at dawn and reach {place} an hour and a half later; with {npc2} the heroes can go to meet them along the path.`)],checks:[U(`Charisma (Persuasion)`,`medium`,B(`{npc2} åbner lugen, viser heltene testamentet og følger deres plan, når bare den ender foran rådet.`,`{npc2} opens the hatch, shows the heroes the will and follows their plan, as long as it ends before the council.`),B(`{npc2} og vennen bliver i hjulkælderen med lugen lukket, og heltene må holde møllen over dem, til rådet kommer.`,`{npc2} and the friend stay in the wheel pit with the hatch shut, and the heroes must hold the mill above them until the council comes.`)),U(`Charisma (Intimidation)`,`medium`,B(`Stillet over for {npc2} i live og de beviser, heltene har samlet, giver {villain} op, kalder de lejede folk tilbage og beder om at blive ført til rådet og ikke til mængden.`,`Faced with {npc2} alive and the proof the heroes have gathered, {villain} gives up, calls off the hirelings and begs to be taken to the council rather than to the crowd.`),B(`{villain} slår oliekrukken i gulvet, kaster lygten efter den og løber mod hesten ved slusehuset; møllen brænder fra det øjeblik, og {boss} dækker flugten.`,`{villain} smashes the oil jar on the floor, throws the lantern after it and runs for the horse by the sluice house; the mill burns from that moment, and {boss} covers the escape.`))],fight:!0,alternatives:[B(`Få {npc2} og vennen ud ad afløbsrenden under hjulet, inden {boss} kommer, og gem jer i elleskoven ved møllebækken til daggry; men går nogen til slusen imens, bliver renden en strid strøm.`,`Lead {npc2} and the friend out by the tailrace under the wheel before {boss} comes, and hide in the alder wood by the millstream until dawn; but if anyone opens the sluice meanwhile, the race becomes a torrent.`),B(`Fortæl de lejede folk, hvad de er en del af: Kun {boss} kender hele ordren, de andre tror, de skal hente en bortløben arving, og med {villain}s seddel fra slusehuset eller testamentet i hånden kan heltene få flere af dem til at gå deres vej.`,`Tell the hirelings what they are part of: only {boss} knows the whole order, the rest believe they are fetching a runaway heir, and with {villain}’s note from the sluice house or the will in hand the heroes can talk several of them into walking away.`)],dmNotes:B(`Klimaks er en nat under gulvbrædderne: Lad støvler gå hen over hovederne på heltene og fakkellyset sive ned gennem sprækkerne. {villain} vil hellere have testamentet end blod, for uden testamentet kan {npc2} stadig giftes bort; brug det, når {villain} forhandler, og husk, at daggry er fristen: Ved første lys brænder olien, og rådet kommer først halvanden time senere.`,`The climax is a night beneath the floorboards: let boots tread over the heroes’ heads and torchlight seep down through the cracks. {villain} would rather have the will than blood, for without the will {npc2} can still be married off; use that when {villain} bargains, and remember that dawn is the deadline: at first light the oil burns, and the council does not arrive until an hour and a half later.`)}},bt=e({kernel:()=>wt,scenes:()=>Tt}),xt=e=>Array.isArray(e)?e.join(` `):e,W=(e,t)=>({da:xt(e),en:xt(t)}),St=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),G=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},Ct=(e,t,n)=>({when:e,event:t,sign:n}),K=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),wt={id:`crawl-the-founders-charter`,titles:[W(`Grundlæggerens brev`,`The Founder’s Charter`),W(`Græs til koen`,`Grass for the Cow`),W(`Før tinget sætter sig`,`Before the Court Sits`)],missions:[`dungeon-crawl`,`race`],foes:`hirelings`,roles:{npc1:W(`en gammel klokker ved bakkekapellet, der har nøglerne og kortet over {place}`,`an old sexton of the hill chapel, who keeps the keys and the map of {place}`),npc2:W(`rådets skriver, der kender stiftelsesbrevets gemmested fra rådets gamle inventarium`,`the council’s clerk, who knows from the council’s old inventory where the charter lies`),npc3:W(`en graver, der har set lys og hørt hamren nede i {place}`,`a gravedigger who has seen lights and heard hammering down in {place}`),villain:W(`herremandens forvalter, der vil have {town}s fælled indhegnet`,`the lord’s steward, who wants the commons of {town} enclosed`)},hook:W(`{npc1} hamrer på heltenes dør to timer før daggry med en ring af nøgler og et gulnet kort over {place} og beder dem nå grundlæggerens grav før {villain}s folk og bringe byens stiftelsesbrev til herredstinget i tingstuen inden middag.`,`{npc1} hammers on the heroes’ door two hours before dawn, carrying a ring of keys and a yellowed map of {place}, and begs them to reach the founder’s tomb before {villain}’s crew and bring the town’s charter to the county court in the moot hall by noon.`),people:{npc1:{wants:W(`Vil se stiftelsesbrevet på dommerbordet ved middagstid og grundlæggerens grav lukket og i fred bagefter.`,`Wants to see the charter on the judge’s table at noon, and the founder’s tomb closed and left in peace afterwards.`),secret:W(`Var den, der for et år siden over en kande øl fortalte {villain}, at grundlæggeren "har byens ret i sine døde hænder", og ved, at det var sådan, {villain} fik øje på brevet.`,`Was the one who, over a jug of ale a year ago, told {villain} that the founder "holds the town’s right in dead hands", and knows that this is how {villain} learned of the charter.`)},npc2:{wants:W(`Vil se brevet i herredsfogedens hænder og ikke blive husket som den skriver, der lod det forsvinde.`,`Wants to see the charter in the county judge’s hands and not be remembered as the clerk who let it vanish.`),secret:W(`Lånte inventariet ud til {villain} uden rådets lov, fordi {villain} lovede skriveren en plads på herregården, og opdagede først i aftes, at siden om graven var skåret ud.`,`Lent the inventory to {villain} without the council’s leave, because {villain} promised the clerk a post at the manor, and only discovered last night that the page about the tomb had been cut out.`)},npc3:{wants:W(`Vil beholde sin stilling og sin ko på fælleden og aldrig mere sætte sine ben i {place}.`,`Wants to keep their job and their cow on the commons, and never to set foot in {place} again.`),secret:W(`Tog imod en sølvmønt fra {villain} ved midnat for at låse gitteret over benskakten op og tie stille, og har kun fortalt {npc1} om lysene, ikke om mønten.`,`Took a silver coin from {villain} at midnight to unlock the grate over the bone chute and keep quiet, and has told {npc1} only about the lights, not about the coin.`)}},premise:W([`Under bakkekapellet over {town} ligger {place}, byens gamle katakomber, og nederst i dem grundlæggerens grav, hvor byens stiftelsesbrev med kongens segl har ligget i grundlæggerens hænder, siden byen blev grundlagt; det er brevet, der giver folk i {town} ret til fælleden.`,`{villain}, herremandens forvalter, har fået herremanden til at bede herredstinget om lov til at indhegne fælleden til herremandens får, og når tinget sætter sig i tingstuen ved middagstid, vinder {villain} sagen, hvis byen ikke kan lægge originalen på dommerbordet.`,`I nat sendte {villain} nogle {foe} med {boss} i spidsen ned ad benskakten på kirkegården for at finde graven og bryde døren op, og ved daggry går {villain} selv derned for at se brevet brænde med egne øjne.`],[`Beneath the hill chapel above {town} lies {place}, the town’s old catacombs, and at the bottom of them the founder’s tomb, where the town’s charter with the king’s seal has lain in the founder’s hands since the town was founded; it is the charter that gives the people of {town} their right to the commons.`,`{villain}, the lord’s steward, has had the lord petition the county court for leave to enclose the commons for the lord’s sheep, and when the court sits in the moot hall at noon, {villain} wins the case unless the town can lay the original on the judge’s table.`,`Tonight {villain} sent some {foe} led by {boss} down the bone chute in the churchyard to find the tomb and break its door, and at dawn {villain} goes down in person to watch the charter burn.`]),goal:W(`Nå grundlæggerens grav nederst i {place} før {villain}s folk, red byens stiftelsesbrev, og læg det på dommerbordet i tingstuen i {town}, før herredstinget sætter sig ved middagstid.`,`Reach the founder’s tomb at the bottom of {place} before {villain}’s crew, save the town’s charter and lay it on the judge’s table in the moot hall of {town} before the county court sits at noon.`),objective:{target:W(`Byens stiftelsesbrev med kongens segl, der giver folk i {town} ret til fælleden`,`The town’s founding charter with the king’s seal, which gives the people of {town} their right to the commons`),state:W(`I et blyhylster under grundlæggerens foldede hænder i stenkisten bag gravens dør, der kun åbner for fællesrimet. {boss} og nogle {foe} hamrer løs på dørens karm, der giver sig efter 5 timer, og fra 3½ time efter start står {villain} selv bag dem med lampeolie og fyrtøj.`,`In a lead case under the founder’s folded hands in the stone coffin behind the tomb door, which opens only to the commons rhyme. {boss} and some {foe} are hammering at the door frame, which gives after 5 hours, and from 3½ hours after the start {villain} stands behind them in person with lamp oil and a tinderbox.`),resolution:W([`Kom forbi {boss} og holdet, og stil dørens fire hjul efter fællesrimet, før karmen giver sig efter 5 timer; tag hylsteret, og bær brevet ud og ned i tingstuen, før herredstinget sætter sig ved middagstid.`,`Når {villain} at sætte ild til brevet, kan heltene stadig rive det ud af flammerne, men et brev med smeltet segl godtager herredsfogeden måske ikke.`],[`Get past {boss} and the crew and set the door’s four wheels by the commons rhyme before the frame gives after 5 hours; take the case and carry the charter out and down to the moot hall before the county court sits at noon.`,`If {villain} manages to set the charter alight, the heroes can still tear it from the flames, but the county judge may not accept a charter with a melted seal.`])},villain:{want:W(`At få {town}s fælled indhegnet til herremandens får og selv få forpagtningen af den, uden at nogen nogensinde spørger, hvor stiftelsesbrevet blev af.`,`To have the commons of {town} enclosed for the lord’s sheep and win the lease of them, without anyone ever asking what became of the charter.`),plan:W([`Først fik {villain} herremanden til at bede herredstinget om fælleden, lånte rådets gamle inventarium "til brug for tinget" og skar siden om stiftelsesbrevet ud.`,`I nat betalte {villain} graveren for at låse gitteret over benskakten op og sendte nogle {foe} med {boss} i spidsen derned med forhammere, mejsler og en rebstige for at finde grundlæggerens grav og bryde døren op, men ikke røre brevet.`,`Ved daggry går {villain} selv ned ad rebstigen, ser brevet brænde med egne øjne og er tilbage i tingstuen ved middagstid for at vinde sagen.`],[`First, {villain} got the lord to petition the county court for the commons, borrowed the council’s old inventory "for the use of the court" and cut out the page about the charter.`,`Tonight {villain} paid the gravedigger to unlock the grate over the bone chute and sent some {foe} led by {boss} down with sledgehammers, chisels and a rope ladder to find the founder’s tomb and break its door, but not to touch the charter.`,`At dawn {villain} climbs down the rope ladder in person, watches the charter burn and is back in the moot hall by noon to win the case.`]),weakness:W([`{villain} er ingen kriger, hader mørket og vandet dernede og stoler ikke på holdet, der kunne sælge brevet tilbage til byen; derfor skal {villain} selv derned og selv op igen ad den samme rebstige.`,`Trækkes stigen op, har {villain} ingen anden vej ud end kapellets trappe, som klokkeren vogter, og forhandler hellere end at blive dernede.`],[`{villain} is no fighter, hates the dark and the water down there and does not trust the crew, who could sell the charter back to the town; so {villain} must go down in person and come back up by the same rope ladder.`,`If the ladder is pulled up, {villain} has no way out except the chapel stair, which the sexton guards, and would rather bargain than stay below.`])},stakes:W(`Brænder brevet, eller når det ikke tingstuen ved middagstid, dømmer herredsfogeden fælleden til herremanden: Hegnene går op inden høst, herremandens får græsser, hvor byens køer gik, folk i {town} mister deres brænde og vand, og {villain} får forpagtningen.`,`If the charter burns or does not reach the moot hall by noon, the county judge awards the commons to the lord: the fences go up before harvest, the lord’s sheep graze where the town’s cows used to, the people of {town} lose their firewood and water, and {villain} gets the lease.`),clock:{start:W(`Sidst på natten, to timer før daggry. {villain}s hold gik ned ad benskakten på kirkegården ved midnat og har i en time hamret løs på døren til grundlæggerens grav. Herredstinget sætter sig i tingstuen i {town} ved middagstid, om otte timer.`,`Late in the night, two hours before dawn. {villain}’s crew went down the bone chute in the churchyard at midnight and has been hammering at the door of the founder’s tomb for an hour. The county court sits in the moot hall of {town} at noon, eight hours from now.`),ticks:[Ct(W(`Efter 2 timer (ved daggry)`,`After 2 hours (at dawn)`),W(`{villain} klatrer alene ned ad holdets rebstige i benskakten med en lygte, en flaske lampeolie og et fyrtøj og følger holdets spor ned mod graven.`,`{villain} climbs down the crew’s rope ladder in the bone chute alone, with a lantern, a flask of lamp oil and a tinderbox, and follows the crew’s tracks down toward the tomb.`),W(`En lygte forsvinder ned i benskakten på kirkegården, og den, der er i gravgangene eller benkapellet, hører rebstigen knirke og ser en enkelt lygte langt bagude.`,`A lantern disappears down the bone chute in the churchyard, and anyone in the galleries or the bone chapel hears the rope ladder creak and sees a single lantern far behind.`)),Ct(W(`Efter 3½ time`,`After 3½ hours`),W(`{villain} når grundlæggerens grav (efter 4 timer, hvis rebet over den druknede krypt er skåret over) og står bag holdet med olien og fyrtøjet, mens de hamrer løs på dørens karm.`,`{villain} reaches the founder’s tomb (after 4 hours if the rope over the drowned crypt has been cut) and stands behind the crew with the oil and the tinderbox while they hammer at the door frame.`),W(`Hamringen standser et øjeblik, en skarp stemme giver ordrer, og så falder slagene tættere end før.`,`The hammering stops for a moment, a sharp voice gives orders, and then the blows come faster than before.`)),Ct(W(`Efter 5 timer`,`After 5 hours`),W(`Dørens karm giver sig, og holdet vælter døren. {villain} tager blyhylsteret fra grundlæggerens hænder, hælder olie over brevet og sætter ild til det med det samme.`,`The door frame gives, and the crew topples the door. {villain} takes the lead case from the founder’s hands, pours oil over the charter and sets it alight at once.`),W(`Et brag af sten ruller gennem krypterne, hamringen hører op, og lidt efter driver en lugt af brændt pergament og smeltet lak op ad trapperne.`,`A crash of stone rolls through the crypts, the hammering stops, and a little later a smell of burnt parchment and melted wax drifts up the stairs.`)),Ct(W(`Efter 8 timer (ved middagstid)`,`After 8 hours (at noon)`),W(`Herredstinget sætter sig i tingstuen. Ligger stiftelsesbrevet ikke på dommerbordet, dømmer herredsfogeden fælleden til herremanden, og {villain} får forpagtningen.`,`The county court sits in the moot hall. If the charter is not on the judge’s table, the county judge awards the commons to the lord, and {villain} gets the lease.`),W(`Klokken over tingstuen ringer ud over {town}, og folk stimler sammen på torvet.`,`The bell above the moot hall rings out over {town}, and people crowd into the square.`))],deadline:W(`Efter 8 timer, ved middagstid, er det for sent: Herredstinget har dømt fælleden til herremanden. Selve brevet går tabt allerede efter 5 timer, når døren giver sig, hvis ingen standser {villain} ved graven.`,`After 8 hours, at noon, it is too late: the county court has awarded the commons to the lord. The charter itself is lost as early as 5 hours in, when the door gives, unless someone stops {villain} at the tomb.`)},clues:{who:[G(`town`,W(`{npc1}, klokkeren, fortæller, at {villain} for en måned siden kom til klokkerboligen og bad om nøglen til grundlæggerens grav "på herremandens vegne", og at {villain} spurgte, hvem der ellers kendte vejen derned, da {npc1} sagde nej.`,`{npc1}, the sexton, says that a month ago {villain} came to the sexton’s house asking for the key to the founder’s tomb "on the lord’s behalf", and when {npc1} refused, asked who else knew the way down.`),W(`{villain} har villet ned til stiftelsesbrevet, siden sagen om fælleden begyndte.`,`{villain} has wanted to get at the charter ever since the case about the commons began.`)),G(`town`,W(`I udlånsbogen i tingstuen står det, at {villain} lånte rådets gamle inventarium i sidste uge, og da det kom tilbage, var siden om grundlæggerens grav skåret ud med en kniv.`,`The lending book in the moot hall shows that {villain} borrowed the council’s old inventory last week, and when it came back, the page about the founder’s tomb had been cut out with a knife.`),W(`{villain} har taget den side, der viser, hvor brevet ligger, så ingen andre kan finde det.`,`{villain} took the page that shows where the charter lies, so that nobody else could find it.`),St([`Rådets udlånsbog:`,`Rådets gamle inventarium, udlånt til {villain}, herremandens forvalter, efter ønske, til brug for tinget.`,`Leveret tilbage tre dage efter. Modtaget af {npc2}, skriver.`,`(Side 14 mangler. Opdaget i aftes. – {npc2})`],[`The council’s lending book:`,`The council’s old inventory, lent to {villain}, the lord’s steward, on request, for the use of the court.`,`Returned three days later. Received by {npc2}, clerk.`,`(Page 14 missing. Noticed last night. — {npc2})`])),G(`town`,W(`{npc3}, graveren, så ved midnat {villain} selv føre et hold med lygter, forhammere og en rebstige over kirkegården til gitteret over benskakten og pege dem ned.`,`{npc3}, the gravedigger, saw {villain} personally lead a crew with lanterns, sledgehammers and a rope ladder across the churchyard at midnight to the grate over the bone chute, and point them down.`),W(`{villain} sendte holdet derned og var der selv.`,`{villain} sent the crew down and was there in person.`)),G(`site`,W(`Blandt de pakninger, holdet har efterladt på trappen i den druknede krypt, ligger en ordre i {villain}s hånd.`,`Among the packs the crew left on the steps in the drowned crypt lies an order in {villain}’s hand.`),W(`{villain} står bag og kommer selv ned til graven for at brænde brevet.`,`{villain} is behind it and is coming down to the tomb in person to burn the charter.`),St([`Find grundlæggerens grav, og bryd døren op.`,`Rør intet derinde, før jeg kommer. Jeg går selv ned ved daggry og vil se det brænde med egne øjne.`,`Halvdelen nu, resten når det er aske. – {villain}`],[`Find the founder’s tomb and break the door.`,`Touch nothing inside until I come. I am coming down myself at dawn and will see it burn with my own eyes.`,`Half now, the rest when it is ash. — {villain}`]))],where:[G(`town`,W(`{npc2}, rådets skriver, kan den udskårne side udenad og skriver den ned for heltene.`,`{npc2}, the council’s clerk, knows the cut-out page by heart and writes it down for the heroes.`),W(`Brevet ligger i grundlæggerens grav nederst i {place}, bag den druknede krypt, og døren åbnes med det, fælleden giver.`,`The charter lies in the founder’s tomb at the bottom of {place}, beyond the drowned crypt, and the door is opened by what the commons give.`),St([`Efter hukommelsen, side 14 i rådets inventarium:`,`Byens stiftelsesbrev med kongens segl, i et blyhylster i grundlæggerens hænder.`,`Graven ligger nederst i {place}, bag den druknede krypt.`,`Døren åbner kun for det, grundlæggeren gav os alle.`],[`From memory, page 14 of the council’s inventory:`,`The town’s charter with the king’s seal, in a lead case in the founder’s hands.`,`The tomb lies at the bottom of {place}, beyond the drowned crypt.`,`The door opens only to what the founder gave us all.`])),G(`town`,W(`{npc3}, graveren, hørte for en time siden hamren komme op gennem lysskakten ved grundlæggerstenen nederst på kirkegården, og stenen står lige over grundlæggerens grav.`,`{npc3}, the gravedigger, heard hammering come up the light shaft by the founder’s stone at the bottom of the churchyard an hour ago, and the stone stands right above the founder’s tomb.`),W(`Holdet er nået til grundlæggerens grav og er ved at bryde døren op.`,`The crew has reached the founder’s tomb and is breaking the door.`)),G(`site`,W(`I gravgangene sidder en lille ko hugget i stenen ved hvert sving, der fører nedad, og ved de nyeste kridtkryds har nogen gnedet støvet af køerne.`,`In the fallen galleries a small cow is carved in the stone at every turning that leads downward, and beside the newest chalk crosses someone has rubbed the dust off the cows.`),W(`Grundlæggerens mærke viser vejen ned til graven, og holdet har fundet den.`,`The founder’s mark shows the way down to the tomb, and the crew has found it.`)),G(`site`,W(`I benkapellet, under en nedrevet væg af kranier, ligger den side, {villain} skar ud af rådets gamle inventarium.`,`In the bone chapel, under a torn-down wall of skulls, lies the page {villain} cut from the council’s old inventory.`),W(`Brevet ligger i grundlæggerens grav bag den druknede krypt, og {villain} vil selv være der, før det brænder.`,`The charter lies in the founder’s tomb beyond the drowned crypt, and {villain} means to be there in person before it burns.`),St([`Rådets inventarium, side 14:`,`Byens stiftelsesbrev med kongens segl, i et blyhylster i grundlæggerens hænder.`,`Graven ligger nederst i {place}, bag den druknede krypt.`,`Døren åbner kun for det, grundlæggeren gav os alle.`,`I margenen, med en anden hånd: Bryd døren op. Intet brændes, før jeg er der. – {villain}`],[`The council’s inventory, page 14:`,`The town’s charter with the king’s seal, in a lead case in the founder’s hands.`,`The tomb lies at the bottom of {place}, beyond the drowned crypt.`,`The door opens only to what the founder gave us all.`,`In the margin, in another hand: Break the door. Nothing is burned until I am there. — {villain}`])),G(`site`,W(`I den druknede krypt er et reb spændt over vandet fra trappen til en lav bue på den anden side, og bag buen fortsætter holdets våde fodspor.`,`In the drowned crypt a rope is strung across the water from the stair to a low arch on the far side, and beyond the arch the crew’s wet footprints go on.`),W(`Grundlæggerens grav ligger bag buen, og holdet er der nu.`,`The founder’s tomb lies beyond the arch, and the crew is there now.`))]},endings:{success:W(`Ved middagstid lægger heltene stiftelsesbrevet på dommerbordet, og herredsfogeden læser det højt og holder kongens segl op for hele {town}. Med ordren i {villain}s egen hånd, udlånsbogen og {npc3}s ord bliver {villain} ført bort for gravrøveri, fælleden forbliver byens, og byen giver heltene ret til at lade deres heste græsse der, så længe de lever, mens {npc1} lukker grundlæggerens grav igen.`,`At noon the heroes lay the charter on the judge’s table, and the county judge reads it aloud and holds up the king’s seal before all of {town}. With the order in {villain}’s own hand, the lending book and {npc3}’s word, {villain} is led away for grave robbing, the commons stay the town’s, and the town grants the heroes the right to graze their horses there for as long as they live, while {npc1} closes the founder’s tomb again.`),partial:W(`Heltene redder brevet, men svedent og med seglet smeltet, eller {villain} slipper op ad rebstigen, når tingstuen først og kalder dem gravrøvere. Uden et helt segl, eller uden {villain} i lænker og vidner, der tør tale, udsætter herredsfogeden sagen til næste ting; fælleden står åben så længe, og {villain} er stadig forvalter og har et år til at finde en anden vej.`,`The heroes save the charter, but it is scorched and its seal has melted; or {villain} gets up the rope ladder, reaches the moot hall first and calls them grave robbers. Without a whole seal, or without {villain} in chains and witnesses who dare speak, the county judge puts the case off until the next session; the commons stay open until then, and {villain} is still steward, with a year to find another way.`),failure:W(`Ved middagstid er brevet aske eller stadig dernede, og herredsfogeden dømmer fælleden til herremanden. Hegnspælene går i jorden, før ugen er omme, og {npc3}s ko er den første, der bliver jaget af græsset; {npc1} får skylden for den brudte grav, og {villain} får forpagtningen og en plads ved herremandens bord.`,`At noon the charter is ash or still down below, and the county judge awards the commons to the lord. The fence posts go into the ground before the week is out, and {npc3}’s cow is the first to be driven off the grass; {npc1} is blamed for the broken tomb, and {villain} gets the lease and a seat at the lord’s table.`)},force:W(`Med magt: besejr {boss} og holdet ved døren. Selve døren er en fod tyk sten og kan ikke brydes op i tide; karmen giver sig først efter 5 timer, også for heltene, så døren åbnes med hjulene og fællesrimet. `,`By force: defeat {boss} and the crew at the door. The door itself is a foot of stone and cannot be broken in time; the frame gives only after 5 hours, for the heroes too, so the door is opened with the wheels and the commons rhyme. `)},Tt={opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc2`,`npc3`],title:W(`Klokkerens nøgler`,`The Sexton’s Keys`),summary:W([`To timer før daggry hamrer {npc1}, den gamle klokker ved bakkekapellet over {town}, på heltenes dør med en ring af nøgler og et kort over {place}, byens gamle katakomber under kapellet.`,`Nogen er ved at bryde ind i grundlæggerens grav nederst i {place}, hvor byens stiftelsesbrev ligger, og ved middagstid afgør herredstinget, om herremanden må indhegne fælleden; {npc1} beder heltene nå graven før {villain}s folk og bringe brevet til tingstuen i tide.`,`Byen kan give svar, før de går: {npc2}, rådets skriver, i tingstuen og {npc3}, graveren, på kirkegården. Hvert ophold koster tid.`],[`Two hours before dawn {npc1}, the old sexton of the hill chapel above {town}, hammers on the heroes’ door, carrying a ring of keys and a map of {place}, the town’s old catacombs beneath the chapel.`,`Someone is breaking into the founder’s tomb at the bottom of {place}, where the town’s charter lies, and at noon the county court decides whether the lord may enclose the commons; {npc1} asks the heroes to reach the tomb before {villain}’s crew and bring the charter to the moot hall in time.`,`Before they go, the heroes can get answers in town: {npc2}, the council’s clerk, at the moot hall, and {npc3}, the gravedigger, in the churchyard. Every stop costs time.`]),readAloud:W([`Det hamrer på døren, længe før hanen galer.`,`Udenfor står en gammel skikkelse i en sort kappe med en lygte i den ene hånd og en tung ring af jernnøgler i den anden, og bag den rejser bakken med kapellet sig som en sort skygge mod en himmel uden stjerner.`,`Den gamle breder et gulnet kort ud på bordet og hvisker: "De er ved at bryde grundlæggerens grav op. Og ved middagstid skal brevet ligge på dommerbordet."`],[`Someone hammers on the door long before cockcrow.`,`Outside stands an old figure in a black cloak, a lantern in one hand and a heavy ring of iron keys in the other, and behind it the hill with its chapel rises like a black shadow against a starless sky.`,`The old one spreads a yellowed map on the table and whispers: "They are breaking into the founder’s tomb. And at noon the charter must lie on the judge’s table."`]),details:[W(`{npc1} fortæller, at byens stiftelsesbrev med kongens segl har ligget i et blyhylster i grundlæggerens hænder nederst i {place}, siden byen blev grundlagt, og at det giver folk i {town} ret til fælleden. {villain}, herremandens forvalter, har bedt herredstinget om lov til at indhegne fælleden til herremandens får, og ved middagstid godtager herredsfogeden kun originalen med seglet. For en måned siden kom {villain} til klokkerboligen og bad om nøglen til grundlæggerens grav "på herremandens vegne", og da {npc1} sagde nej, spurgte {villain}, hvem der ellers kendte vejen derned.`,`{npc1} explains that the town’s charter with the king’s seal has lain in a lead case in the founder’s hands at the bottom of {place} since the town was founded, and that it gives the people of {town} their right to the commons. {villain}, the lord’s steward, has asked the county court for leave to enclose the commons for the lord’s sheep, and at noon the county judge will accept only the original with its seal. A month ago {villain} came to the sexton’s house asking for the key to the founder’s tomb "on the lord’s behalf", and when {npc1} refused, asked who else knew the way down.`),W(`{npc1} låser døren til trappen bag kapellets alter op for heltene og bliver selv ved den, så ingen andre kommer op ad trappen, og heltene får kortet. Det viser gravgangene med en rød streg gennem de gange, der stadig står, benkapellet, den druknede krypt og nederst grundlæggerens grav, og i margenen benskakten, en stenrende i kirkegårdens hjørne, hvor graveren tipper gamle knogler ned. Mens heltene pakker, nynner {npc1} fællesrimet, som hvert barn i {town} kan: "Græs til koen, brænde til gryden, vand fra brønden, sten til muren. Det fik vi alle, store og små, og det skal ingen herre få."`,`{npc1} unlocks the door to the stair behind the chapel altar for the heroes, stays by it so that nobody else comes up the stair, and gives the heroes the map. It shows the galleries with a red line through the ones still standing, the bone chapel, the drowned crypt and, at the bottom, the founder’s tomb, and in the margin the bone chute, a stone-lined shaft in the corner of the churchyard where the gravedigger tips old bones down. While the heroes pack, {npc1} hums the commons rhyme every child in {town} knows: "Grass for the cow and wood for the pot, water from the well and stone for the wall. It was given to all of us, great and small, and no lord shall have it at all."`),W(`{npc2}, rådets skriver, bor over tingstuen ved torvet, en halv times omvej. I udlånsbogen står det, at {villain} lånte rådets gamle inventarium i sidste uge "til brug for tinget"; da det kom tilbage, var siden om grundlæggerens grav skåret ud, og det opdagede {npc2} først i aftes. Skriveren kan siden udenad og skriver den ned for heltene: Brevet ligger i grundlæggerens hænder bag den druknede krypt, og døren åbner kun for det, grundlæggeren gav os alle.`,`{npc2}, the council’s clerk, lives above the moot hall on the square, a half-hour detour. The lending book shows that {villain} borrowed the council’s old inventory last week "for the use of the court"; when it came back, the page about the founder’s tomb had been cut out, and {npc2} only found that out last night. The clerk knows the page by heart and writes it down for the heroes: the charter lies in the founder’s hands beyond the drowned crypt, and the door opens only to what the founder gave us all.`),W(`{npc3}, graveren, sidder i graverhuset på kirkegården, lige på vejen op til kapellet, og et kvarter er nok til at få graveren til at tale. Ved midnat så graveren {villain} selv føre et hold med lygter, forhammere og en rebstige over kirkegården til gitteret over benskakten og pege dem ned, og for en time siden kom der hamren op gennem lysskakten ved grundlæggerstenen nederst på kirkegården; stenen står lige over grundlæggerens grav. Om sølvmønten og rebstigen tier {npc3}, til nogen gennemskuer det.`,`{npc3}, the gravedigger, sits in the gravedigger’s hut in the churchyard, right on the way up to the chapel, and a quarter of an hour is enough to get the gravedigger talking. At midnight the gravedigger saw {villain} personally lead a crew with lanterns, sledgehammers and a rope ladder across the churchyard to the grate over the bone chute and point them down. An hour ago hammering came up the light shaft by the founder’s stone at the bottom of the churchyard, and the stone stands right above the founder’s tomb. {npc3} keeps quiet about the silver coin and the rope ladder until someone sees through it.`),W(`Vejen: fra {town} op til bakkekapellet en halv time; besøget hos {npc2} koster en halv time mere, og at få {npc3} til at tale et kvarter. Fra kapellet ned ad trappen og gennem gravgangene til benkapellet 1 time efter den røde streg plus et kvarter om det nye skred (tre kvarter, hvis heltene må grave sig igennem); eller ned ad holdets rebstige i benskakten et kvarter og derfra et kvarter til benkapellet. Fra benkapellet et kvarter ned til den druknede krypt, et kvarter over den ad den tørre afsats eller en halv time, hvis heltene vader langs holdets reb, og et kvarter videre til grundlæggerens grav. Uden ophold er heltene ved graven efter 2½ time ad trappen eller 1¾ time ad benskakten; hvert ophold i byen eller dernede lægges oven i. {villain} går ned ad rebstigen efter 2 timer og står ved graven efter 3½, og døren giver sig efter 5.`,`Travel times: from {town} up to the hill chapel, half an hour; the visit to {npc2} costs half an hour more, and getting {npc3} to talk a quarter of an hour. From the chapel down the stair and through the galleries to the bone chapel 1 hour along the red line, plus a quarter of an hour around the new fall (three quarters if the heroes must dig through); or down the crew’s rope ladder in the bone chute a quarter of an hour, and from there a quarter of an hour to the bone chapel. From the bone chapel a quarter of an hour down to the drowned crypt, a quarter of an hour across it by the dry ledge or half an hour if the heroes wade along the crew’s rope, and a quarter of an hour on to the founder’s tomb. Without stops the heroes reach the tomb after 2½ hours by the stair or 1¾ hours by the bone chute; every stop in town or below adds to that. {villain} climbs down the rope ladder after 2 hours and stands at the tomb after 3½, and the door gives after 5.`)],checks:[K(`Wisdom (Insight)`,`medium`,W(`{npc3} tilstår at have taget imod en sølvmønt fra {villain} for at låse gitteret op og fortæller, at holdet lod rebstigen hænge, fordi {villain} selv vil ned ad den ved daggry. Graveren tilbyder at trække stigen op, når {villain} er nede; så kan hverken {villain} eller holdet komme op igen, for kun {npc1} kan åbne døren til kapellets trappe.`,`{npc3} confesses to taking a silver coin from {villain} to unlock the grate, and reveals that the crew left the rope ladder hanging because {villain} means to climb down it at dawn. The gravedigger offers to pull the ladder up once {villain} is down; then neither {villain} nor the crew can get back up, for only {npc1} can open the door to the chapel stair.`),W(`{npc3} siger ikke mere end det, graveren har set. Rebstigen finder heltene selv ved benskakten, men ingen holder øje med den, og {villain}s vej op igen er åben.`,`{npc3} says no more than what the gravedigger saw. The heroes find the rope ladder at the bone chute themselves, but nobody watches it, and {villain}’s way back up stays open.`)),K(`Charisma (Persuasion)`,`easy`,W(`{npc2} lover at stå i tingstuen ved middagstid med udlånsbogen og vidne om den udskårne side, selv om det kan koste pladsen som skriver.`,`{npc2} promises to stand in the moot hall at noon with the lending book and testify about the cut-out page, even if it costs the clerk’s post.`),W(`{npc2} giver heltene udlånsbogen, men tør ikke selv vidne; bogen siger, hvem der lånte inventariet, men ikke, hvem der skar siden ud.`,`{npc2} gives the heroes the lending book but dares not testify; the book says who borrowed the inventory, but not who cut out the page.`))],fight:!1,alternatives:[W(`Gå direkte op uden omveje: Heltene sparer tiden i byen, men har kun {npc1}s ord og fællesrimet at gå efter, og ingen holder øje med rebstigen.`,`Head straight up without detours: the heroes save the time in town, but have only {npc1}’s word and the commons rhyme to go on, and nobody watches the rope ladder.`),W(`Tag holdets vej ned ad benskakten: Den sparer tre kvarter, men rebstigen er glat, og det er også den vej, {villain} kommer ned ved daggry.`,`Take the crew’s way down the bone chute: it saves three quarters of an hour, but the rope ladder is slippery, and it is also the way {villain} comes down at dawn.`)],dmNotes:W(`Lad spillerne selv vælge mellem viden og tid, og sig højt, hvad hvert ophold koster. Lad {npc1} nynne fællesrimet, mens heltene pakker: Det er nøglen til grundlæggerens dør, men det ved ingen endnu.`,`Let the players choose between knowledge and time themselves, and say aloud what each stop costs. Let {npc1} hum the commons rhyme while the heroes pack: it is the key to the founder’s door, but nobody knows that yet.`)},middle:[{kind:`exploration`,at:`site`,present:[],title:W(`Gravgangene`,`The Fallen Galleries`),summary:W([`Bag kapellets alter fører en stentrappe ned i gravgangene, hvor {town}s døde har ligget i nicher i hundreder af år, og hvor loftet er styrtet ned mange steder.`,`Den røde streg på {npc1}s kort går gennem de gange, der stadig står, men i nat har hamringen dybt nede revet et nyt skred løs tværs over den.`,`Holdet kom en anden vej, ned ad benskakten, der ender i en bunke knogler i den fjerne ende af gangene, og det er også den vej, {villain} kommer ved daggry.`],[`Behind the chapel altar a stone stair leads down into the galleries where the dead of {town} have lain in niches for hundreds of years, and where the ceiling has come down in many places.`,`The red line on {npc1}’s map runs through the galleries still standing, but tonight the hammering far below has shaken loose a new fall right across it.`,`The crew came another way, down the bone chute, which ends in a heap of bones at the far end of the galleries, and that is also the way {villain} comes at dawn.`]),readAloud:W([`Trappen bag alteret drejer ned i et mørke, der lugter af kalk og gammelt støv.`,`Til begge sider er væggene fulde af nicher, og i hver niche ligger en svøbt skikkelse eller en bunke brune knogler; ved hvert sving sidder en lille ko hugget i stenen.`,`Længere fremme er gangen fyldt fra gulv til loft med frisk sten, støvet hænger stadig i lygtelyset, og et dumpt slag et sted dybt nede får gruset til at rasle.`],[`The stair behind the altar winds down into a darkness that smells of lime and old dust.`,`On both sides the walls are full of niches, and in every niche lies a wrapped shape or a heap of brown bones; at every turning a small cow is carved in the stone.`,`Further on, the passage is filled from floor to ceiling with fresh stone, the dust still hangs in the lantern light, and a dull blow somewhere far below sets the gravel rattling.`]),details:[W(`Den røde streg fører gennem gravgangene til benkapellet på en time. Ved hvert sving, der fører nedad, sidder en lille ko hugget i stenen, grundlæggerens gamle mærke, og ved de nyeste af holdets kridtkryds har nogen gnedet støvet af køerne. Følger heltene køerne, kommer de aldrig ind i de gange, der er styrtet sammen.`,`The red line leads through the galleries to the bone chapel in an hour. At every turning that leads downward a small cow is carved in the stone, the founder’s old mark, and beside the newest of the crew’s chalk crosses someone has rubbed the dust off the cows. If the heroes follow the cows, they never end up in the galleries that have fallen in.`),W(`Midt i gravgangene, hvor gangen er smallest, ligger det nye skred tværs over den røde streg, og hver gang slagene dernede går gennem stenen, drysser der grus fra loftet. Kortet viser med blegt blæk en gammel sidegang, der går udenom gennem to halvt sammenstyrtede nicher: et kvarter ekstra. Den, der ikke finder den, må grave sig igennem skredet med hænder og skjolde: tre kvarter.`,`Halfway through the galleries, where the passage is narrowest, the new fall lies right across the red line, and every time the blows below go through the stone, gravel trickles from the ceiling. In faded ink the map shows an old side gallery that goes around through two half-collapsed niches: a quarter of an hour extra. Whoever does not find it must dig through the fall with hands and shields: three quarters of an hour.`),W(`Benskakten er en stenrende fra kirkegårdens hjørne, og den ender i en bunke gamle knogler i den fjerne ende af gravgangene, på den anden side af skredet. Holdets rebstige hænger i den, og fra knoglebunken fører holdets støvlespor et kvarter videre til benkapellet.`,`The bone chute is a stone-lined shaft that runs down from the corner of the churchyard and ends in a heap of old bones at the far end of the galleries, beyond the fall. The crew’s rope ladder hangs in it, and from the bone heap the crew’s boot prints lead a quarter of an hour on to the bone chapel.`),W(`Før der er gået 2 timer, er der ingen andre i gravgangene. Efter 2 timer kommer {villain} alene ned ad rebstigen med en lygte, en flaske lampeolie og et fyrtøj, står ved foden af den efter 2¼ time og går langsomt efter holdets spor mod benkapellet. Er heltene ved knoglebunken på det tidspunkt, kan de tage imod {villain} dér.`,`Before 2 hours have passed, nobody else is in the galleries. After 2 hours {villain} comes down the rope ladder alone with a lantern, a flask of lamp oil and a tinderbox, stands at its foot after 2¼ hours and walks slowly along the crew’s tracks toward the bone chapel. If the heroes are at the bone heap then, they can be waiting for {villain} there.`)],checks:[K(`Intelligence (Investigation)`,`medium`,W(`Heltene finder sidegangen på kortet og kommer uden om skredet på et kvarter.`,`The heroes find the side gallery on the map and get around the fall in a quarter of an hour.`),W(`Heltene finder ikke sidegangen og må grave sig igennem skredet; det tager tre kvarter.`,`The heroes do not find the side gallery and must dig through the fall; it takes three quarters of an hour.`)),K(`Strength (Athletics)`,`medium`,W(`Heltene, der tager benskakten, kommer ned ad den glatte rebstige uden en lyd.`,`Heroes who take the bone chute get down the slippery rope ladder without a sound.`),W(`En helt glider på rebstigen og falder det sidste stykke ned i knoglebunken; faldet gør ondt, og raslen bærer langt: Holdets vagter i den druknede krypt er klar, når heltene kommer.`,`A hero slips on the rope ladder and falls the last stretch into the bone heap; the fall hurts, and the rattle carries far: the crew’s guards in the drowned crypt are ready when the heroes arrive.`))],fight:!1,alternatives:[W(`Vent på {villain} ved foden af rebstigen: Er heltene her før 2 timer, kan de tage {villain} i det øjeblik, støvlerne rører knoglerne; men imens hamrer holdet videre ved graven.`,`Wait for {villain} at the foot of the rope ladder: if the heroes are here before 2 hours, they can seize {villain} the moment {villain}’s boots touch the bones; but meanwhile the crew keeps hammering at the tomb.`),W(`Grav en åbning foroven: To helte kan grave en åbning under loftet på en halv time, så alle kan kravle over skredet; det går hurtigere end at grave hele vejen igennem, men den, der kravler sidst, kan få mere sten ned over sig.`,`Dig an opening at the top: two heroes can dig a gap under the ceiling in half an hour, so that everyone can crawl over the fall; it is quicker than digging all the way through, but the last one across may bring more stone down.`)],dmNotes:W(`Gravgangene er stille og døde; lad hvert dumpt slag dernede få gruset til at drysse fra loftet. Skredet skal koste tid, ikke liv, og sig højt, hvad hver vej koster.`,`The galleries are still and dead; let every dull blow below set gravel trickling from the ceiling. The fall should cost time, not lives. Say aloud what each route costs.`)},{kind:`investigation`,at:`site`,present:[],title:W(`Benkapellet`,`The Bone Chapel`),summary:W([`Midt i {place} ligger benkapellet, et lavt kapel, hvis vægge er muret af kranier og lårben i mønstre, og hvor {town}s første slægter ligger.`,`Holdet ledte her i over en time, før de fandt trappen bag alteret: En væg af kranier er revet ned, hver niche har et kridtkryds, og under kranierne ligger den side, {villain} skar ud af rådets inventarium.`,`Hen over alterets forside er fællesrimet hugget med fire små billeder, og det er nøglen til døren nederst; bag alteret fører en trappe ned til den druknede krypt.`],[`In the middle of {place} lies the bone chapel, a low chapel whose walls are built of skulls and thighbones in patterns, where the first families of {town} rest.`,`The crew searched here for over an hour before they found the stair behind the altar: a wall of skulls has been torn down, every niche bears a chalk cross, and under the skulls lies the page {villain} cut from the council’s inventory.`,`Across the front of the altar the commons rhyme is carved with four small pictures, and that is the key to the door below; behind the altar a stair leads down to the drowned crypt.`]),readAloud:W([`Lygtelyset falder på tusind tomme øjenhuler: Væggene, buerne og selv lysekronen er lavet af knogler, lagt i roser, kors og lange rækker.`,`Den ene væg er revet ned, så kranierne ligger spredt over gulvet som brosten, og på hver niche sidder et friskt kridtkryds.`,`Alteret er en blok af sten, og hen over dets forside løber fire linjer i gamle bogstaver med et lille billede over hver gave.`],[`The lantern light falls on a thousand empty eye sockets: the walls, the arches and even the chandelier are made of bones, laid in roses, crosses and long rows.`,`One wall has been torn down, so that the skulls lie scattered over the floor like cobblestones, and every niche bears a fresh chalk cross.`,`The altar is a block of stone, and across its front run four lines in old letters with a small picture above each gift.`]),details:[W(`Under den nedrevne væg af kranier ligger siden fra rådets gamle inventarium, som holdet har tabt i rodet. Den siger, hvor brevet ligger, og hvordan døren åbnes, og i margenen står en ordre i {villain}s hånd.`,`Under the torn-down wall of skulls lies the page from the council’s old inventory, which the crew dropped in the mess. It says where the charter lies and how the door opens, and in the margin is an order in {villain}’s hand.`),W(`Hen over alterets forside er fællesrimet hugget, og over de fire gaver står fire små billeder i rimets rækkefølge: en ko, et knippe brænde, en brønd og en mur. Billederne er de samme, som sidder på hjulene i døren til grundlæggerens grav, og ordene kender heltene fra {npc1}.`,`Across the front of the altar the commons rhyme is carved, and above the four gifts stand four small pictures in the rhyme’s order: a cow, a bundle of firewood, a well and a wall. The pictures are the same as those on the wheels in the door of the founder’s tomb, and the heroes know the words from {npc1}.`),W(`Den halve væg af kranier, der stadig står, hælder ud over gulvet; den, der klatrer i bunken uden at se sig for, kan få resten ned over sig. Bag alteret fører en smal trappe et kvarter ned til den druknede krypt, og nedefra lyder dryp af vand og, indtil døren giver sig efter 5 timer, slagene fra holdets forhammere.`,`The half wall of skulls still standing leans out over the floor; whoever climbs the heap without looking may bring the rest down. Behind the altar a narrow stair leads a quarter of an hour down to the drowned crypt, and from below comes the drip of water and, until the door gives after 5 hours, the blows of the crew’s sledgehammers.`),W(`Før 2½ time er der ingen levende i kapellet. Efter 2½ time kommer {villain} gennem benkapellet, alene med lygten, og går videre ned ad trappen bag alteret; er heltene her da, kan de skjule sig mellem knoglerne og lade {villain} gå forbi eller tage {villain} her.`,`Before 2½ hours there is nobody living in the chapel. After 2½ hours {villain} comes through the bone chapel, alone with the lantern, and goes on down the stair behind the altar; if the heroes are here then, they can hide among the bones and let {villain} pass, or seize {villain} here.`)],checks:[K(`Intelligence (Investigation)`,`medium`,W(`Heltene finder siden under kranierne uden at vælte resten af væggen og ved nu, at brevet ligger bag den druknede krypt, og at {villain} selv kommer for at se det brænde.`,`The heroes find the page under the skulls without toppling the rest of the wall, and now know that the charter lies beyond the drowned crypt and that {villain} is coming in person to see it burn.`),W(`Heltene finder først siden efter en halv times rodeteri i kranierne.`,`The heroes only find the page after half an hour of rummaging through the skulls.`)),K(`Intelligence (History)`,`easy`,W(`Heltene ser, at billederne over rimet er de fire gaver, grundlæggeren gav byen, i rimets rækkefølge: ko, brænde, brønd og mur. Ved graven kan de stille dørens hjul rigtigt uden at slå.`,`The heroes see that the pictures above the rhyme are the four gifts the founder gave the town, in the rhyme’s order: cow, firewood, well and wall. At the tomb they can set the door’s wheels right without a roll.`),W(`Heltene ser kun gamle billeder over et børnerim; hvad de skal bruges til, må de regne ud ved døren.`,`The heroes see only old pictures above a children’s rhyme; what they are for, they must work out at the door.`))],fight:!1,alternatives:[W(`Tag {villain} i benkapellet: Er heltene her efter 2½ time, kan de gemme sig mellem knoglerne og gribe {villain}, når lygten kommer gennem kapellet. Uden {villain} brænder ingen brevet, når døren giver sig efter 5 timer, men holdet holder på det, til {boss} mister tålmodigheden efter 6.`,`Seize {villain} in the bone chapel: if the heroes are here after 2½ hours, they can hide among the bones and grab {villain} when the lantern comes through the chapel. Without {villain} nobody burns the charter when the door gives after 5 hours, but the crew holds on to it until {boss} loses patience after 6.`),W(`Spring benkapellet over, og gå lige ned ad trappen bag alteret: Heltene sparer tiden til at lede, men har hverken siden eller alterets billeder.`,`Skip the bone chapel and go straight down the stair behind the altar: the heroes save the time spent searching, but have neither the page nor the altar’s pictures.`)],dmNotes:W(`Benkapellet skal være uhyggeligt, men ikke farligt: Ingen af de døde rejser sig. Lad spillerne selv se, at billederne over rimet er de fire gaver, {npc1} nynnede om; det er eventyrets gåde, og den skal kunne løses.`,`The bone chapel should be eerie but not dangerous: none of the dead rise. Let the players see for themselves that the pictures above the rhyme are the four gifts {npc1} hummed about; it is the adventure’s riddle, and it must be solvable.`)},{kind:`combat`,at:`site`,present:[],title:W(`Den druknede krypt`,`The Drowned Crypt`),summary:W([`Under benkapellet ligger den gamle krypt, hvor kilden under bakken har fået vandet til at stå brysthøjt, så kun lågene af stenkisterne stikker op som små øer.`,`Holdet har spændt et reb over vandet til en lav bue på den anden side, og på trappen derovre har {boss} sat nogle {foe} til at holde overgangen, mens resten hamrer løs på grundlæggerens dør.`,`Langs østvæggen løber en gammel, tør afsats, der står med blegt blæk på {npc1}s kort; ellers må heltene vade langs rebet og kæmpe i vandet.`],[`Beneath the bone chapel lies the old crypt, where the spring under the hill has raised the water chest-deep, so that only the lids of the stone coffins stick up like little islands.`,`The crew has strung a rope across the water to a low arch on the far side, and on the far steps {boss} has set some {foe} to hold the crossing while the rest hammer at the founder’s door.`,`Along the east wall runs an old, dry ledge, marked in faded ink on {npc1}’s map; otherwise the heroes must wade along the rope and fight in the water.`]),readAloud:W([`Trappen ender i sort vand, der ligger blankt og stille under hvælvingen og lugter af kalk og kulde.`,`Stenkister stikker op af vandet her og der, og hen over dem løber et vådt reb til en lav bue på den anden side, hvor en lygte står på trappen, og et par skikkelser sidder ved den.`,`Bag buen hamrer nogen løs på sten, og hvert slag sender små ringe ud over vandet.`],[`The stair ends in black water that lies smooth and still under the vault and smells of lime and cold.`,`Stone coffins stick up from the water here and there, and across them runs a wet rope to a low arch on the far side, where a lantern stands on the steps and a few figures sit beside it.`,`Beyond the arch someone is hammering at stone, and every blow sends small rings out across the water.`]),details:[W(`Vandet er iskoldt og når en voksen til brystet; små helte må svømme eller bæres. Den tørre afsats begynder bag en stenkiste ved foden af trappen og løber langs østvæggen til trappen på den anden side: et kvarter, én ad gangen. At vade langs holdets reb tager en halv time, og i vandet bevæger en helt sig kun med halv fart.`,`The water is icy and reaches an adult’s chest; small heroes must swim or be carried. The dry ledge starts behind a stone coffin at the foot of the stair and runs along the east wall to the steps on the far side: a quarter of an hour, one at a time. Wading along the crew’s rope takes half an hour, and in the water a hero moves at only half speed.`),W(`Nogle {foe} holder trappen under buen med en lygte og holdets pakninger. De angriber alle, der kommer over vandet, og trækker sig ind under buen mod grundlæggerens grav, når halvdelen af dem er faldet. Er en helt faldet i benskakten, er de klar, når heltene kommer.`,`Some {foe} hold the steps under the arch with a lantern and the crew’s packs. They attack anyone who comes across the water, and fall back through the arch toward the founder’s tomb once half of them are down. If a hero fell in the bone chute, the guards are ready when the heroes arrive.`),W(`I holdets pakninger på trappen ligger reservelygter, en krukke lampeolie, brød, en pung med herregårdens mønter og en ordre i {villain}s hånd. Bag buen fortsætter holdets våde fodspor et kvarter videre til grundlæggerens grav.`,`In the crew’s packs on the steps lie spare lanterns, a jar of lamp oil, bread, a purse of the manor’s coins and an order in {villain}’s hand. Beyond the arch the crew’s wet footprints go on for a quarter of an hour to the founder’s tomb.`),W(`{villain} kommer ned ad trappen fra benkapellet efter 2¾ time, vader over langs rebet og er på trappen derovre efter 3¼ time; finder {villain} vagterne faldne, går {villain} alligevel videre mod hamringen, hvor holdet er. Har heltene skåret rebet over, tør {villain} knap gå ud i vandet og bruger en time på at komme over, så {villain} først når graven efter 4 timer. Efter 5 timer hører hamringen bag buen op, og lugten af røg kommer gennem buen.`,`{villain} comes down the stair from the bone chapel after 2¾ hours, wades across along the rope and is on the far steps after 3¼ hours; if {villain} finds the guards down, {villain} still goes on toward the hammering, where the crew is. If the heroes have cut the rope, {villain} hardly dares step into the water and needs an hour to get across, so {villain} only reaches the tomb after 4 hours. After 5 hours the hammering beyond the arch stops, and the smell of smoke comes through the arch.`)],checks:[K(`Wisdom (Perception)`,`easy`,W(`Heltene finder begyndelsen på afsatsen bag stenkisten og kommer tørskoede over på et kvarter.`,`The heroes find the start of the ledge behind the stone coffin and cross dry-shod in a quarter of an hour.`),W(`Heltene finder ikke afsatsen i mørket og må vade langs rebet: en halv time i det kolde vand, og kampen tager de i vandet.`,`The heroes do not find the ledge in the dark and must wade along the rope: half an hour in the cold water, and they fight in the water.`)),K(`Dexterity (Stealth)`,`medium`,W(`Heltene når trappen derovre, før vagterne ser deres lys, og overrasker dem.`,`The heroes reach the far steps before the guards see their light, and take them by surprise.`),W(`Et lys glimter i vandet, og vagterne er klar, når heltene når trappen.`,`A light glints on the water, and the guards are ready when the heroes reach the steps.`))],fight:!0,alternatives:[W(`Skær rebet over, når I er ovre: Så kan holdet ikke komme hurtigt tilbage, og {villain} når først graven efter 4 timer i stedet for 3½.`,`Cut the rope once the heroes are across: then the crew cannot get back quickly, and {villain} only reaches the tomb after 4 hours instead of 3½.`),W(`Vent på {villain} på trappen: Fra 2¾ time vader {villain} over langs rebet, alene og med lygten højt; den, der står på trappen derovre, kan tage imod {villain} midt i vandet.`,`Wait for {villain} on the steps: from 2¾ hours {villain} wades across along the rope, alone, with the lantern held high; whoever stands on the far steps can meet {villain} in the middle of the water.`)],dmNotes:W(`Lad vandet gøre kampen hård: Den, der står i vandet, er langsom og kold, og den, der falder, skal trækkes op. Sig, hvor lang tid der er gået, når kampen er forbi; hamringen bag buen fortsætter, indtil der er gået 5 timer.`,`Let the water make the fight hard: whoever stands in it is slow and cold, and whoever falls must be hauled out. Say how much time has passed when the fight is over; the hammering beyond the arch goes on until 5 hours have passed.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:W(`Grundlæggerens grav`,`The Founder’s Tomb`),summary:W([`Bag den druknede krypt ligger grundlæggerens grav: et hvælvet gravkammer med en stendør, der kun åbner for fællesrimet, og bag den grundlæggerens stenkiste med brevet i blyhylsteret.`,`{boss} og nogle {foe} hamrer løs på dørens karm, der giver sig efter 5 timer; fra 3½ time står {villain} selv bag dem med lampeolie og fyrtøj for at se brevet brænde.`,`Heltene skal få brevet ud, før det brænder, og være i tingstuen med det ved middagstid.`],[`Beyond the drowned crypt lies the founder’s tomb: a vaulted chamber with a stone door that opens only to the commons rhyme, and behind it the founder’s stone coffin with the charter in its lead case.`,`{boss} and some {foe} are hammering at the door frame, which gives after 5 hours; from 3½ hours {villain} stands behind them in person with lamp oil and a tinderbox to watch the charter burn.`,`The heroes must get the charter out before it burns and be in the moot hall with it at noon.`]),readAloud:W([`Bag buen åbner sig et hvælvet gravkammer, hvor lygter står på gulvet mellem værktøj og stenstøv.`,`For enden står en dør af grå sten med fire stenhjul i en række og en indskrift over dem, og rundt om dørens karm hamrer skikkelser med forhammere og mejsler, så gnisterne springer.`,`Hvert slag får støvet til at drysse fra hvælvingen, og en sort revne løber allerede op ad karmen fra gulv til loft.`],[`Beyond the arch a vaulted tomb chamber opens up, with lanterns standing on the floor among tools and stone dust.`,`At the far end stands a door of grey stone with four stone wheels in a row and an inscription above them, and around its frame figures hammer away with sledgehammers and chisels, making the sparks fly.`,`Every blow brings dust trickling from the vault, and a black crack already runs up the frame from floor to ceiling.`]),details:[W(`{boss} og nogle {foe} har hamret løs på dørens karm, siden en time før start; de prøvede hjulene først, men fik kun jernspærren til at falde igen og igen, og kender ikke rimet. Karmen giver sig efter 5 timer. Holdet kæmper for sin løn, ikke for et brev, og overgiver sig eller flygter mod benskakten, når {boss} falder.`,`{boss} and some {foe} have been hammering at the door frame since an hour before the start; they tried the wheels first but only made the iron bar drop again and again, and they do not know the rhyme. The frame gives after 5 hours. The crew fights for pay, not for a charter, and surrenders or flees toward the bone chute when {boss} falls.`),W(`{villain}s vej: ved foden af rebstigen efter 2¼ time, i benkapellet efter 2½, i vandet i den druknede krypt fra 2¾ til 3¼ og her ved graven efter 3½ (efter 4, hvis rebet over krypten er skåret over). Kommer heltene før, er {villain} her ikke endnu, men træder ind under buen med lygten, olien og fyrtøjet på det tidspunkt, også midt i en kamp. Har heltene allerede brevet, byder {villain} dem penge og en forpagtning og flygter mod rebstigen, hvis de siger nej; går heltene fra graven med brevet før 3½ time, møder de {villain} på vejen tilbage.`,`{villain}’s route: at the foot of the rope ladder after 2¼ hours, in the bone chapel after 2½, in the water of the drowned crypt from 2¾ to 3¼, and here at the tomb after 3½ (after 4 if the rope over the crypt has been cut). If the heroes come earlier, {villain} is not here yet, but steps in under the arch with the lantern, the oil and the tinderbox at that time, even in the middle of a fight. If the heroes already have the charter, {villain} offers them money and a lease and flees toward the rope ladder if they refuse; if the heroes leave the tomb with the charter before 3½ hours, they meet {villain} on the way back.`),W(`Når {villain} er kommet, står {villain} bag holdet og driver dem på. Når karmen giver sig efter 5 timer, tager {villain} hylsteret fra grundlæggerens hænder, hælder olie over brevet og sætter ild til det med det samme; er heltene her, har de én runde til at rive det ud af flammerne, og kommer de senere, er brevet aske, og {villain} og holdet er på vej op ad rebstigen. Har heltene taget {villain} på vejen, tager {boss} hylsteret, når karmen giver sig, og venter; kommer {villain} ikke inden 6 timer, brænder {boss} brevet alligevel og fører holdet op ad rebstigen.`,`Once {villain} has arrived, {villain} stands behind the crew and drives them on. When the frame gives after 5 hours, {villain} takes the case from the founder’s hands, pours oil over the charter and sets it alight at once. If the heroes are here, they have one round to tear it from the flames, and if they come later, the charter is ash and {villain} and the crew are on their way up the rope ladder. If the heroes have seized {villain} on the way, {boss} takes the case when the frame gives and waits; if {villain} has not come by 6 hours, {boss} burns the charter anyway and leads the crew up the rope ladder.`),W(`Døren er en fod tyk sten med fire stenhjul i en række under indskriften "Jeg åbner kun for det, jeg gav jer alle." Rundt om hvert hjul er hugget seks billeder: en ko, et knippe brænde, en brønd, en mur, et får og en krone. Stilles hjulene fra venstre mod højre på ko, brænde, brønd og mur, som i fællesrimet, glider døren op; får og krone er herremandens og kongens, ikke gaver til alle. Et hjul drejes med en handling, og står hjulene forkert, falder en jernspærre i væggen med et brag, og hjulene sidder fast i ti minutter. Har heltene forstået alteret i benkapellet, skal de ikke slå for at stille hjulene rigtigt. Vil heltene i stedet bryde døren op med magt, må det ske ved karmen, som holdet allerede har revnet, og det er larmende og langsomt; hjulene åbner den på et øjeblik.`,`The door is a foot of solid stone with four stone wheels in a row beneath the inscription "I open only to what I gave you all." Around each wheel six pictures are carved: a cow, a bundle of firewood, a well, a wall, a sheep and a crown. Set from left to right to cow, firewood, well and wall, as in the commons rhyme, the wheels let the door slide open; the sheep and the crown belong to the lord and the king, not to everyone. Turning a wheel takes an action, and if the wheels are set wrong, an iron bar drops in the wall with a crash and the wheels are stuck for ten minutes. If the heroes understood the altar in the bone chapel, they need no roll to set the wheels right. If the heroes would rather break the door by force, it has to be at the frame the crew has already cracked, which is loud and slow; the wheels open it in a moment.`),W(`Bag døren står grundlæggerens stenkiste med et stenbillede på låget, hvis hænder er foldet over et blyhylster; i det ligger brevet. Fra graven til tingstuen tager det 2½ time ad trappen eller 1¾ time op ad rebstigen og en time mere med en fange eller en båret helt: Skal brevet nå dommerbordet ved middagstid, må heltene gå herfra senest efter 5½ time ad trappen eller 6¼ time ad rebstigen. Har {npc3} trukket rebstigen op, kan {villain} og holdet kun komme ud ad kapellets trappe, som {npc1} vogter, og {villain} forhandler hellere end at blive dernede; heltene selv kan råbe op gennem skakten, så sænker graveren stigen igen.`,`Behind the door stands the founder’s stone coffin with a stone figure on its lid whose hands are folded over a lead case; the charter lies inside. Getting from the tomb to the moot hall takes 2½ hours by the stair or 1¾ hours up the rope ladder, and an hour more with a prisoner or a carried hero. If the charter is to reach the judge’s table by noon, the heroes must leave here by 5½ hours if they take the stair, or by 6¼ hours if they take the rope ladder. If {npc3} has pulled the rope ladder up, {villain} and the crew can only get out by the chapel stair, which {npc1} guards, and {villain} would rather bargain than stay below; the heroes themselves can shout up the chute, and the gravedigger lowers the ladder again.`)],checks:[K(`Intelligence (Investigation)`,`medium`,W(`Heltene ser, at får og krone er herremandens og kongens, ikke gaver til alle, og stiller hjulene efter rimet ved første forsøg; døren glider op.`,`The heroes see that the sheep and the crown belong to the lord and the king, not to everyone, and set the wheels by the rhyme at the first try; the door slides open.`),W(`Et hjul står forkert; jernspærren falder med et brag, og hjulene sidder fast i ti minutter, før heltene kan prøve igen.`,`One wheel is wrong; the iron bar drops with a crash, and the wheels are stuck for ten minutes before the heroes can try again.`)),K(`Dexterity (Sleight of Hand)`,`medium`,W(`En helt river det brændende brev ud af olien, før ilden når seglet; kun kanterne er svedne.`,`A hero tears the burning charter out of the oil before the fire reaches the seal; only the edges are scorched.`),W(`Heltene får brevet ud, men det er halvt brændt, og seglet er smeltet til en klump; herredsfogeden vil måske ikke godtage det.`,`The heroes get the charter out, but it is half burnt and the seal has melted into a lump; the county judge may not accept it.`))],fight:!0,alternatives:[W(`Byd {boss} mere end {villain}: Holdet arbejder for penge, og lover heltene en dusør fra byen for brevet, træder {boss} til side, og {villain} står alene med olien.`,`Offer {boss} more than {villain} does: the crew works for money, and if the heroes promise a reward from the town for the charter, {boss} stands aside, and {villain} is left alone with the oil.`),W(`Lad holdet gøre arbejdet: Gem jer under buen, og slå til, når karmen giver sig efter 5 timer; men så har {villain} olien klar, og heltene har kun én runde.`,`Let the crew do the work: hide under the arch and strike when the frame gives after 5 hours; but then {villain} has the oil ready, and the heroes have only one round.`)],dmNotes:W(`Sig, hvor lang tid der er gået, når heltene træder ind under buen, og hold øje med 3½ og 5 timer: {villain}s lygte under buen og karmens brag er scenens to vendepunkter. Spillerne skal kunne løse gåden selv; slaget er for den gruppe, der går i stå.`,`Say how much time has passed when the heroes step in under the arch, and watch for 3½ and 5 hours: {villain}’s lantern under the arch and the crash of the frame are the scene’s two turning points. The players should be able to solve the riddle themselves; the roll is for a group that gets stuck.`)}},Et=e({kernel:()=>kt,scenes:()=>At}),Dt=e=>Array.isArray(e)?e.join(` `):e,q=(e,t)=>({da:Dt(e),en:Dt(t)}),Ot=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),J=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},Y=(e,t,n)=>({when:e,event:t,sign:n}),X=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),kt={id:`intrigue-the-false-heir`,titles:[q(`Arvingen, der kom hjem`,`The Heir Who Came Home`),q(`Medaljonen fra branden`,`The Medallion from the Fire`),q(`Seglet ved festen`,`The Seal at the Feast`)],missions:[`intrigue`,`investigation`],foes:`people`,roles:{npc1:q(`en gammel tjener, der passede herremandens eneste barn indtil natten med branden`,`an old servant who looked after the lord’s only child until the night of the fire`),npc2:q(`en ung fremmed, der kom til {town} med barnets medaljon og i morgen skal anerkendes som arving`,`a young stranger who came to {town} with the child’s medallion and is to be acknowledged as heir tomorrow`),npc3:q(`en kroejer på Den Røde Hane, hvor {npc2} tog ind den første aften`,`an innkeeper at the Red Cockerel, where {npc2} took a room on the first evening`),villain:q(`den afdøde herremands hofmester, der har styret {place} i tyve år`,`the late lord’s chamberlain, who has run {place} for twenty years`)},hook:q(`{npc1}, en gammel tjener, der passede herremandens eneste barn indtil natten med branden, sender bud efter heltene ved solnedgang, lægger en lille træhest i deres hænder og beder dem finde ud af, om {npc2}, den unge fremmede, der skal have herremandens segl ved festen på {place} i morgen, virkelig er barnet, for i morgen skal {npc1} omfavne {npc2} foran alle gæsterne.`,`{npc1}, an old servant who looked after the lord’s only child until the night of the fire, sends for the heroes at sunset, puts a small wooden horse into their hands and asks them to find out whether {npc2}, the young stranger who is to receive the lord’s seal at the feast in {place} tomorrow, truly is the child. Tomorrow {npc1} must embrace {npc2} before all the guests.`),people:{npc1:{wants:q(`Vil vide, om det virkelig er barnet, og vil ikke lyve foran hele egnen ved festen.`,`Wants to know whether the stranger truly is the child, and will not lie before the whole county at the feast.`),secret:q(`Har taget imod {villain}s pung: en livrente for resten af livet, hvis {npc1} omfavner {npc2} ved festen og siger "det er barnet". Pungen ligger uåbnet under gulvbrædderne.`,`Has accepted {villain}’s purse: a pension for life if {npc1} embraces {npc2} at the feast and says "this is the child". The purse lies unopened under the floorboards.`)},npc2:{wants:q(`Vil være nogens barn: have et navn og et hjem og aldrig mere drage rundt med en skuespillertrup.`,`Wants to be someone’s child: to have a name and a home and never again tramp the roads with a troupe of players.`),secret:q(`Er et hittebarn og en tidligere omrejsende skuespiller, som {villain} købte fri af truppen i sommer; tror halvt på {villain}s hvisken om, at {npc2} måske virkelig er barnet, og gemmer {villain}s lektiebreve i foret i sin kiste som sikkerhed.`,`Is a foundling and a former strolling player whom {villain} bought out of a troupe this summer; half believes {villain}’s whisper that {npc2} may truly be the child, and keeps {villain}’s lesson letters in the lining of their trunk as insurance.`)},npc3:{wants:q(`Vil holde kroen ude af herskabets strid og beholde festens gæster som kunder.`,`Wants to keep the inn out of the gentry’s quarrels and hold on to the feast guests as customers.`),secret:q(`Fik sølv af {villain} for at sige, at {npc2} kom alene og uanmeldt, men skrev alligevel sandheden ind i kroens bog, for en kroejer lyver ikke i sin bog.`,`Took silver from {villain} to say that {npc2} arrived alone and unannounced, but wrote the truth in the inn’s ledger all the same, for an innkeeper does not lie in the ledger.`)}},premise:q([`For tyve år siden brændte vestfløjen på {place}, den gamle herregård på bakken over {town}, og herremandens eneste barn forsvandt samme nat; herremanden ledte i tyve år og døde i foråret uden arving.`,`For en måned siden kom {npc2}, en ung fremmed, til {town} med den sølvmedaljon, barnet bar den nat, og {villain}, den afdøde herremands hofmester, genkendte medaljonen på torvet; i morgen ved festen i storsalen på {place} skal {villain} give herremandens segl til {npc2} og selv blive den unge arvings formynder.`,`Sandheden er, at barnet døde i røgen, mens {villain}, dengang en ung forvalter i huset, bar pengekisten ud først; {villain} murede barnet inde i en niche i krypten under kapellet og svor over for herremanden, at vuggen var tom og vinduet åbent, så alle troede, at bortførere havde taget barnet.`,`I sommer tog {villain} medaljonen ud af graven og købte {npc2}, et hittebarn på den rette alder, fri af en omrejsende skuespillertrup for at styre {place} gennem en arving, der skylder {villain} alt.`],[`Twenty years ago the west wing of {place}, the old manor on the hill above {town}, burned, and the lord’s only child vanished that same night; the lord searched for twenty years and died this spring without an heir.`,`A month ago {npc2}, a young stranger, came to {town} wearing the silver medallion the child wore that night, and {villain}, the late lord’s chamberlain, recognised the medallion in the square. Tomorrow at the feast in the great hall of {place}, {villain} is to hand the lord’s seal to {npc2} and become the young heir’s guardian.`,`The truth is that the child died in the smoke while {villain}, then a young steward of the household, carried the strongbox out first. {villain} walled the child into a niche in the crypt beneath the chapel and swore to the lord that the cradle was empty and the window open, so that everyone believed kidnappers had taken the child.`,`This summer {villain} took the medallion from the grave and bought {npc2}, a foundling of the right age, out of a travelling troupe of players, in order to rule {place} through an heir who owes {villain} everything.`]),goal:q(`Find ud af, om {npc2} virkelig er herremandens forsvundne barn, og læg sandheden frem for gæsterne i storsalen på {place}, før {villain} giver {npc2} herremandens segl klokken tre i morgen eftermiddag.`,`Find out whether {npc2} truly is the lord’s lost child, and lay the truth before the guests in the great hall of {place} before {villain} hands {npc2} the lord’s seal at three tomorrow afternoon.`),objective:{target:q(`Graven med herremandens barn i krypten under kapellet på {place} og det, der ligger i den`,`The grave of the lord’s child in the crypt beneath the chapel of {place}, and what lies in it`),state:q([`Muret inde i en niche i kryptens ældste væg, hvor {villain} lagde barnet natten med branden: et lille bundt i et blåt tæppe, tvillingen til {npc1}s træhest og resten af den fine kæde, som medaljonen blev revet af.`,`Krypten ligger under kapellet bag højsædet i storsalen, hvor {villain} våger hele natten med {boss} og fra middag sidder ved højbordet med seglet, mens {boss} og nogle {foe} vogter døren bag højsædet; ad den gamle trappe fra barnekammeret i den brændte vestfløj kan man komme derned uset.`],[`Walled into a niche in the oldest wall of the crypt, where {villain} laid the child on the night of the fire: a small bundle in a blue blanket, the twin of {npc1}’s wooden horse and the rest of the fine chain the medallion was torn from.`,`The crypt lies beneath the chapel behind the high seat of the great hall, where {villain} keeps watch all night with {boss} and from noon sits at the high table with the seal, while {boss} and some {foe} guard the door behind the high seat. The crypt can be reached unseen by the old stair from the nursery in the burnt west wing.`]),resolution:q([`Åbn nichen foran gæsterne, eller bring træhesten og kæden fra graven til højbordet før klokken tre, og lad {npc1} kende træhesten eller {npc2} fortælle sandheden; så kan ingen i salen tvivle.`,`Uden graven kan {npc2}s tilståelse eller {villain}s breve stadig standse anerkendelsen, men så kalder {villain} brevene forfalskninger og tilståelsen en skuespillers hævn og beholder nøglerne til {place}.`],[`Open the niche before the guests, or bring the wooden horse and the chain from the grave to the high table before three, and let {npc1} recognise the horse or {npc2} tell the truth; then nobody in the hall can doubt it.`,`Without the grave, {npc2}’s confession or {villain}’s letters can still stop the acknowledgement, but then {villain} calls the letters forgeries and the confession a player’s revenge, and keeps the keys of {place}.`])},villain:{want:q(`At beholde {place}: styre godset gennem en arving, der skylder {villain} alt, og aldrig stå til regnskab for brandnatten. Uden arving tilfalder {place} kronen, og kronens foged ville opdage, at der mangler tyve års sølv i herremandens kasse.`,`To keep {place}: to run the estate through an heir who owes {villain} everything, and never answer for the night of the fire. Without an heir {place} falls to the crown, and the crown’s bailiff would find twenty years of silver missing from the lord’s coffers.`),plan:q([`I sommer tog {villain} medaljonen ud af barnets grav, købte {npc2} fri af en skuespillertrup for penge fra godsets kasse og lærte {npc2} husets historier i lange breve.`,`For en måned siden lod {villain} {npc2} tage ind på kroen i {town}, og en uge senere "genkendte" {villain} medaljonen på torvet foran hele byen.`,`I morgen klokken tre, når kapelklokken slår, lægger {villain} herremandens segl i {npc2}s hånd foran gæsterne i storsalen og bliver selv udnævnt til den unge arvings formynder; forinden skal {npc1} træde frem og omfavne arvingen, så ingen tvivler.`],[`This summer {villain} took the medallion from the child’s grave, bought {npc2} out of a troupe of players with money from the estate’s coffers and taught {npc2} the household’s stories in long letters.`,`A month ago {villain} had {npc2} take a room at the inn in {town}, and a week later {villain} "recognised" the medallion in the square before the whole town.`,`Tomorrow at three, when the chapel bell strikes, {villain} will put the lord’s seal in {npc2}’s hand before the guests in the great hall and be named the young heir’s guardian; first {npc1} is to step forward and embrace the heir, so that nobody doubts the claim.`]),weakness:q([`{villain} har aldrig kunnet få sig selv til at røre graven, undtagen den ene gang efter medaljonen, og tænder hvert år på brandnatten et lille hvidt lys foran nichen; står {villain} over for den åbne niche eller barnets træhest foran andre, brister facaden.`,`Og {villain} har brug for, at {npc1} omfavner {npc2} ved festen: Uden den gamle tjeners ja begynder gæsterne at tvivle.`],[`{villain} has never been able to touch the grave except the one time for the medallion, and every year on the night of the fire lights a small white candle before the niche; if {villain} is faced with the open niche or the child’s wooden horse in front of others, the mask cracks.`,`And {villain} needs {npc1} to embrace {npc2} at the feast: without the old servant’s word, the guests will begin to doubt.`])},stakes:q(`Får {npc2} seglet klokken tre, ejer {npc2} {place} i navnet, mens {villain} styrer godset i gerning: Tyveriet fra herremandens kasse bliver aldrig opdaget, {npc1} har løjet foran hele egnen, og herremandens barn ligger glemt i en tilmuret niche.`,`If {npc2} receives the seal at three, {npc2} holds {place} in name while {villain} runs the estate in fact: the theft from the lord’s coffers is never discovered, {npc1} has lied before the whole county, and the lord’s child lies forgotten in a walled-up niche.`),clock:{start:q(`Solnedgang, aftenen før festen. {npc2} har boet på kroen Den Røde Hane i {town}, siden den unge fremmede kom for en måned siden, og i morgen klokken tre skal {npc2} have herremandens segl af {villain} foran gæsterne i storsalen på {place}, en halv times gang op ad bakkevejen. {villain} går ikke i seng i nat: Fra solnedgang til festen er {villain} i storsalen med {boss} og ser til forberedelserne.`,`Sunset, the evening before the feast. {npc2} has lodged at the Red Cockerel inn in {town} since arriving a month ago, and tomorrow at three {npc2} is to receive the lord’s seal from {villain} before the guests in the great hall of {place}, half an hour’s walk up the hill road. {villain} does not go to bed tonight: from sunset until the feast {villain} is in the great hall with {boss}, seeing to the preparations.`),ticks:[Y(q(`Efter 2 timer`,`After 2 hours`),q(`{villain}, der er urolig den sidste nat, sender nogle {foe} ned i krostuen på Den Røde Hane og andre ud i den brændte vestfløj, hvor den gamle trappe fra barnekammeret går ned til krypten, for at holde vagt; har heltene allerede spurgt til {npc2} i byen, skal vagterne holde øje med dem.`,`{villain}, uneasy on the last night, sends some {foe} down to keep watch in the taproom of the Red Cockerel and others out to keep watch in the burnt west wing, where the old stair from the nursery goes down to the crypt. If the heroes have already asked about {npc2} in town, the watchers are told to look out for them.`),q(`To af {villain}s {foe} i {place}s nye livré sidder over det samme krus øl i krostuen og holder øje med døren, og en lygte bevæger sig mellem de sorte bjælker i vestfløjen.`,`Two of {villain}’s {foe} in the new livery of {place} sit in the taproom nursing their ale and watching the door, and a lantern moves among the black beams of the west wing.`)),Y(q(`Efter 5 timer (ved midnat)`,`After 5 hours (at midnight)`),q(`En lukket vogn med {place}s våben henter {npc2} på kroen og kører den unge fremmede op til gæstekammeret i østtårnet "for at sove den sidste nat under faderens tag"; kisten bliver stående på kroen, og gæstekammeret bliver låst udefra.`,`A closed carriage bearing the arms of {place} fetches {npc2} from the inn and takes the young stranger up to the guest chamber in the east tower "to spend the last night under the family roof"; the trunk stays behind at the inn, and the guest chamber is locked from the outside.`),q(`Vognlygterne forsvinder op ad bakkevejen, og vinduet over krostuen bliver mørkt.`,`The carriage lamps vanish up the hill road, and the window above the taproom goes dark.`)),Y(q(`Efter 11 timer (ved daggry)`,`After 11 hours (at dawn)`),q(`Gæsterne begynder at komme til {place}: Porten bliver kun åbnet for gæster med indbydelse og deres husstand, gårdene fyldes med heste og tjenestefolk, og {villain} tager imod i storsalen med {boss} ved sin side.`,`The guests begin to arrive at {place}: the gate opens only for guests with an invitation and their households, the yards fill with horses and servants, and {villain} receives everyone in the great hall with {boss} at hand.`),q(`Vogne og ryttere snor sig op ad bakkevejen, og over porthuset hejses {place}s gamle banner med egetræet for første gang i tyve år.`,`Carriages and riders wind up the hill road, and over the gatehouse the old oak-tree banner of {place} is raised for the first time in twenty years.`)),Y(q(`Efter 17 timer (ved middag)`,`After 17 hours (at noon)`),q(`Festen begynder i storsalen: {villain} sætter sig ved højbordet med {npc2} ved sin side og seglet på en rød pude, {boss} tager plads ved den lille dør bag højsædet, og {npc1} får plads ved det nederste bord for at træde frem, når klokken slår tre.`,`The feast begins in the great hall: {villain} sits down at the high table with {npc2} alongside and the seal on a red cushion, {boss} takes up position at the small door behind the high seat, and {npc1} is seated at the lowest table, to step forward when the bell strikes three.`),q(`Trompeter lyder fra porthuset, og duften af stegt vildt hænger over hele gården.`,`Trumpets sound from the gatehouse, and the smell of roast venison hangs over every yard.`)),Y(q(`Efter 20 timer (klokken tre om eftermiddagen)`,`After 20 hours (at three in the afternoon)`),q(`Kapelklokken slår tre, {villain} læser anerkendelsen op, {npc1} bliver kaldt frem for at omfavne arvingen, og {villain} lægger seglet i {npc2}s hånd, mens gæsterne rejser sig og sværger.`,`The chapel bell strikes three, {villain} reads out the acknowledgement, {npc1} is called forward to embrace the heir, and {villain} puts the seal in {npc2}’s hand while the guests rise and swear fealty.`),q(`Klokken over kapellet slår tre tunge slag, og der bliver helt stille i storsalen.`,`The bell above the chapel strikes three heavy strokes, and the great hall falls utterly silent.`))],deadline:q(`Efter 20 timer, klokken tre om eftermiddagen, er det for sent: Seglet er i {npc2}s hånd, gæsterne har svoret, og {villain} er arvingens formynder.`,`After 20 hours, at three in the afternoon, it is too late: the seal is in {npc2}’s hand, the guests have sworn fealty, and {villain} is the heir’s guardian.`)},clues:{who:[J(`town`,q(`I kroens bog på Den Røde Hane står {npc2}s værelse betalt en måned forud af {villain} dagen før, {npc2} kom, og {npc3}, kroejeren, har skrevet, at {villain} kom ind ad bagdøren den første aften og gik ved daggry, en uge før {villain} "genkendte" medaljonen på torvet.`,`In the ledger of the Red Cockerel, {npc2}’s room is entered as paid a month ahead by {villain} the day before {npc2} arrived, and {npc3}, the innkeeper, has written that {villain} came in by the back door on the first evening and left at dawn, a week before {villain} "recognised" the medallion in the square.`),q(`{villain} kendte {npc2}, før genkendelsen på torvet; optrinnet var aftalt på forhånd.`,`{villain} knew {npc2} before the recognition in the square; the scene was arranged in advance.`),Ot([`Den Røde Hane, kroens bog:`,`Værelset over krostuen betalt en måned forud af {villain}, hofmester på {place}. Gæsten kommer i morgen med postvognen.`,`Næste dag: Gæsten kom. Hofmesteren kom ind ad bagdøren om aftenen og gik ved daggry.`],[`The Red Cockerel, the inn’s ledger:`,`Room above the taproom paid one month ahead by {villain}, chamberlain of {place}. The guest arrives tomorrow by the post coach.`,`Next day: the guest came. The chamberlain came in by the back door in the evening and left at dawn.`])),J(`town`,q(`I foret i {npc2}s kiste på kroen ligger et bundt breve med {villain}s håndskrift: lektier i husets historier, som {npc2} skal kunne udenad.`,`In the lining of {npc2}’s trunk at the inn lies a bundle of letters in {villain}’s hand: lessons in the household’s stories that {npc2} must know by heart.`),q(`Alt, hvad {npc2} "husker" fra barndommen, har {villain} lært {npc2}.`,`Everything {npc2} "remembers" from childhood, {villain} taught.`),Ot([`Lær dette udenad, og brænd brevet:`,`Hundene hed Ravn og Bølge. Barnekammeret var blåt. Den gamle tjener sang om den lille grå hest.`,`Medaljonen bærer du i det sorte bånd; kæden blev tabt for længe siden.`,`Spørger nogen om branden, husker du kun røg og nogens arme. – {villain}`],[`Learn this by heart, and burn the letter:`,`The hounds were called Raven and Wave. The nursery was blue. The old servant sang about the little grey horse.`,`You wear the medallion on the black ribbon; the chain was lost long ago.`,`If anyone asks about the fire, you remember only smoke and someone’s arms. — {villain}`])),J(`site`,q(`I {villain}s skrivepult i østtårnet ligger godsets regnskabsbog, og under "Reparation af møllen" står tre poster fra i sommer med {villain}s hånd: en skuespiller løst fri af sin trup, festtøj syet efter mål sendt med brev og et sort silkebånd.`,`In {villain}’s writing desk in the east tower lies the estate’s account book, and under "Repairs to the mill" stand three entries from this summer in {villain}’s hand: a player released from a troupe, feast clothes made to measures sent by letter, and a black silk ribbon.`),q(`{villain} købte og klædte {npc2} på for herremandens penge, måneder før {npc2} kom til {town}.`,`{villain} bought and dressed {npc2} with the lord’s money months before {npc2} came to {town}.`),Ot([`Godsets regnskabsbog, sommeren, under "Reparation af møllen":`,`Til mesteren for skuespillertruppen, for at løse én spiller fri af sin kontrakt: 30 guldstykker.`,`Festtøj til gæsten, mål sendt med brev: 12 guldstykker.`,`Et sort silkebånd: 2 sølvstykker.`],[`The estate’s account book, summer, under "Repairs to the mill":`,`To the master of the players’ troupe, to release one player from contract: 30 gold pieces.`,`Feast clothes for the guest, measures sent by letter: 12 gold pieces.`,`One black silk ribbon: 2 silver pieces.`])),J(`town`,q(`{npc1} husker, at {villain}, dengang en ung forvalter i huset, natten med branden sendte {npc1} op for at vække fruen og lovede selv at bære barnet ud, og at {villain} bagefter svor, at vuggen var tom og vinduet åbent; men vinduet i barnekammeret havde været malet fast i årevis.`,`{npc1} remembers that on the night of the fire {villain}, then a young steward of the household, sent {npc1} to wake the lady and promised to carry the child out personally, and that {villain} afterwards swore the cradle was empty and the window open; but the nursery window had been painted shut for years.`),q(`{villain} var den sidste, der gik til barnet, og historien om bortførerne er {villain}s egen.`,`{villain} was the last to go to the child, and the story of the kidnappers is {villain}’s own invention.`)),J(`site`,q(`I barnekammeret i den brændte vestfløj er vinduet stadig malet fast under soden, og malingen løber ubrudt hen over hasperne.`,`In the nursery in the burnt west wing the window is still painted shut under the soot, and the paint runs unbroken over the catches.`),q(`Ingen bar barnet ud gennem det vindue: Historien om bortførerne, som {villain} fortalte herremanden, er løgn.`,`Nobody carried the child out through that window: the story of the kidnappers that {villain} told the lord is a lie.`))],where:[J(`town`,q(`Ved herremandens begravelse i foråret så {npc1} i kryptens ældste væg under kapellet en lille tilmuret niche med brandnattens dato ridset ind i mørtlen og foran den stumpen af et lille hvidt lys, sådan et, man tænder for et dødt barn.`,`At the lord’s burial this spring, {npc1} saw a small walled-up niche in the oldest wall of the crypt beneath the chapel, with the date of the fire scratched into the mortar and before it the stub of a small white candle, the kind lit for a dead child.`),q(`Et barn ligger muret inde i krypten under kapellet på {place}, og nogen sørger over det i al hemmelighed.`,`A child lies walled up in the crypt beneath the chapel of {place}, and someone mourns the child in secret.`)),J(`town`,q(`{npc3}, kroejeren, fortæller, at {villain} hvert år på brandnatten sidder alene i krostuen til midnat, køber et lille hvidt lys, sådan et, man tænder for et dødt barn, og går op til kapellet på {place} med det.`,`{npc3}, the innkeeper, says that every year on the night of the fire {villain} sits alone in the taproom until midnight, buys a small white candle, the kind lit for a dead child, and walks up to the chapel at {place} with it.`),q(`{villain} sørger over et dødt barn i kapellet på {place}, ikke over et stjålet.`,`{villain} mourns a dead child at the chapel of {place}, not a stolen one.`)),J(`site`,q(`I en skuffe i {villain}s skrivepult i østtårnet ligger et bundt små hvide lys, sådan nogle, man tænder for et dødt barn, ved siden af en almanak, hvor brandnattens dato er ringet ind i hvert eneste år i tyve år, og ved døren er krogen mærket "Krypten" tom.`,`In a drawer of {villain}’s writing desk in the east tower, a bundle of small white candles, the kind lit for a dead child, lies beside an almanac in which the date of the fire is circled for each of the last twenty years, and by the door the hook marked "Crypt" is empty.`),q(`{villain} går ned i krypten hvert år på brandnatten og bærer selv kryptens nøgle: Det, {villain} sørger over, ligger dernede.`,`{villain} goes down into the crypt every year on the night of the fire and carries the crypt key: what {villain} mourns lies down there.`)),J(`site`,q(`Bag det forkullede klædeskab i barnekammeret er den smalle trappe ned til krypten under kapellet ryddet for murbrokker, og på trinene ligger krummer af frisk mørtel og stænk af kalk.`,`Behind the charred wardrobe in the nursery, the narrow stair down to the crypt beneath the chapel has been cleared of rubble, and on the steps lie crumbs of fresh mortar and spatters of lime.`),q(`Nogen er gået ned i krypten ad denne vej i sommer med mørtel og har muret noget til igen.`,`This summer someone went down this way to the crypt with mortar and walled something up again.`))]},endings:{success:q(`Før klokken tre ser gæsterne graven eller det, der lå i den: {npc1} kender straks træhesten, og den sønderrevne kæde passer til leddene i {npc2}s medaljon. {villain} bliver ført bort af byfogeden, herremandens barn bliver lagt i en rigtig grav ved siden af herremanden og fruen, og {npc1} bærer lyset. Har {npc2} fortalt sandheden, lader gæsterne {npc2} ride bort med en hest og en pung i stedet for at komme i galgen; ellers følger {npc2} med {villain} i byfogedens kælder.`,`Before three the guests see the grave or what lay in it: {npc1} recognises the wooden horse at once, and the torn chain matches the links in {npc2}’s medallion. {villain} is led away by the reeve, the lord’s child is laid in a proper tomb beside the lord and the lady, and {npc1} carries the candle. If {npc2} told the truth, the guests let {npc2} ride away with a horse and a purse instead of going to the gallows; if not, {npc2} follows {villain} into the reeve’s cellar.`),partial:q(`Heltene standser anerkendelsen med {npc2}s tilståelse eller {villain}s breve, men uden graven kan ingen bevise, hvad der skete med barnet natten med branden. {villain} kalder brevene forfalskninger og tilståelsen en skuespillers hævn, {npc2} bliver kastet i kælderen som bedrager, og gæsterne, der ikke ved, hvem de skal tro, lader {villain} beholde nøglerne til {place}, til kronens foged kommer til foråret; nichen i krypten forbliver urørt, og {villain} glemmer ikke heltene.`,`The heroes stop the acknowledgement with {npc2}’s confession or {villain}’s letters, but without the grave nobody can prove what became of the child on the night of the fire. {villain} calls the letters forgeries and the confession a player’s revenge, {npc2} is thrown into the cellar as a fraud, and the guests, unsure whom to believe, leave {villain} the keys of {place} until the crown’s bailiff comes in spring; the niche in the crypt stays untouched, and {villain} does not forget the heroes.`),failure:q(`Klokken tre lægger {villain} seglet i {npc2}s hånd, {npc1} omfavner en fremmed foran hele egnen og går hjem med en livrente og en løgn, og gæsterne sværger troskab. {villain} styrer {place} gennem en skræmt ung arving, sølvet fra herremandens kasse bliver ved med at forsvinde, og herremandens barn ligger glemt i en tilmuret niche, hvor et lille hvidt lys brænder én nat om året.`,`At three {villain} puts the seal in {npc2}’s hand, {npc1} embraces a stranger before the whole county and goes home with a pension and a lie, and the guests swear fealty. {villain} runs {place} through a frightened young heir, the silver keeps vanishing from the lord’s coffers, and the lord’s child lies forgotten in a walled-up niche where a small white candle burns one night a year.`)}},At={opening:{kind:`opening`,at:`town`,present:[`npc1`],title:q(`Træhesten`,`The Wooden Horse`),summary:q([`Ved solnedgang tager {npc1}, en gammel tjener, der passede herremandens eneste barn indtil natten med branden for tyve år siden, imod heltene i et lille hus i udkanten af {town} med en træhest i hænderne og en indbydelse til morgendagens fest på bordet.`,`I morgen klokken tre skal {npc2}, den unge fremmede, der kom med barnets medaljon for en måned siden, have herremandens segl af {villain}, hofmesteren, i storsalen på {place}, og {npc1} skal træde frem og omfavne arvingen; {npc1} beder heltene finde ud af, om {npc2} virkelig er barnet.`,`Byen har to spor: {npc2} bor på kroen Den Røde Hane til midnat, og {place} ligger en halv time oppe ad bakkevejen, hvor {villain} våger i storsalen hele natten.`],[`At sunset {npc1}, an old servant who looked after the lord’s only child until the night of the fire twenty years ago, receives the heroes in a small house at the edge of {town}, a wooden horse in hand and an invitation to tomorrow’s feast on the table.`,`Tomorrow at three {npc2}, the young stranger who came with the child’s medallion a month ago, is to receive the lord’s seal from {villain}, the chamberlain, in the great hall of {place}, and {npc1} must step forward and embrace the heir; {npc1} asks the heroes to find out whether {npc2} truly is the child.`,`The town holds two leads: {npc2} lodges at the Red Cockerel inn until midnight, and {place} lies half an hour up the hill road, where {villain} keeps watch in the great hall all night.`]),readAloud:q([`Huset er lavt og koldt, og på bordet står en lampe ved siden af et brev med et rødt segl.`,`En gammel tjener i en stoppet sort frakke drejer en lille, gråmalet træhest mellem fingrene; hestens ene øre er brækket af, og tjeneren ser ikke op, da heltene kommer ind.`,`Gennem vinduet ses {place} på bakken over byen, og for første gang i tyve år brænder der lys i hvert eneste vindue.`],[`The house is low and cold, and on the table a lamp stands beside a letter with a red seal.`,`An old servant in a darned black coat turns a small grey-painted wooden horse between thin fingers; one of its ears is broken off, and the servant does not look up as you come in.`,`Through the window {place} can be seen on the hill above the town, and for the first time in twenty years every window is lit.`]),details:[q(`Natten med branden for tyve år siden sendte {villain}, dengang en ung forvalter i huset, {npc1} op for at vække fruen og lovede selv at bære barnet ud. Bagefter svor {villain}, at vuggen var tom og vinduet åbent, og herremanden troede, at bortførere havde taget barnet; men vinduet i barnekammeret havde været malet fast i årevis. {npc1} sagde det dengang og blev jaget bort for at have forladt barnet, og fruen døde af sorg den næste vinter.`,`On the night of the fire twenty years ago {villain}, then a young steward of the household, sent {npc1} to wake the lady and promised to carry the child out personally. Afterwards {villain} swore that the cradle was empty and the window open, and the lord believed kidnappers had taken the child; but the nursery window had been painted shut for years. {npc1} said so at the time and was dismissed for leaving the child, and the lady died of grief the next winter.`),q(`Ved herremandens begravelse i foråret bar {npc1} lys for kisten ned i krypten under kapellet og så i kryptens ældste væg en lille tilmuret niche med brandnattens dato ridset ind i mørtlen og foran den stumpen af et lille hvidt lys, sådan et, man tænder for et dødt barn. {npc1} husker også den smalle trappe fra barnekammeret ned til kapellet, som barnet blev båret ad hver morgen til bøn; efter branden blev den fyldt med murbrokker og glemt.`,`At the lord’s burial this spring {npc1} carried a candle before the coffin down into the crypt beneath the chapel. In the oldest wall of the crypt {npc1} saw a small walled-up niche, with the date of the fire scratched into the mortar and before it the stub of a small white candle, the kind lit for a dead child. {npc1} also remembers the narrow stair from the nursery down to the chapel, by which the child was carried to prayers every morning; after the fire it was filled with rubble and forgotten.`),q(`{npc1} skar to træheste til barnet; den ene havde barnet med i sengen natten med branden, den anden har {npc1} gemt. Da {npc1} viste {npc2} hesten på torvet, "huskede" {npc2} den straks, men {villain} havde hørt {npc1} fortælle om hestene ved begravelsen. Indbydelsen gælder "{npc1} og husstand", så heltene kan komme med til festen. Fra huset er der et kvarter til kroen, og en samtale dér tager en halv time; til {place} er der en halv time ad bakkevejen til porten, der er lukket og bevogtet om natten, eller tyve minutter ad den gamle sti gennem frugthaven, der ender ved den brændte vestfløj.`,`{npc1} carved two wooden horses for the child; the child had one in bed on the night of the fire, and {npc1} kept the other. When {npc1} showed {npc2} the horse in the square, {npc2} "remembered" it at once, but {villain} had heard {npc1} talk about the horses at the burial. The invitation reads "{npc1} and household", so the heroes can come to the feast. From the house it is a quarter of an hour to the inn, and a conversation there takes half an hour. {place} is half an hour by the hill road to the gate, which is shut and guarded at night, or twenty minutes by the old path through the orchard, which ends at the burnt west wing.`)],checks:[X(`Wisdom (Insight)`,`easy`,q(`{npc1} skjuler noget: Presset tilstår {npc1} at have taget imod {villain}s pung, en livrente for resten af livet, hvis {npc1} omfavner {npc2} ved festen. Pungen ligger uåbnet under gulvbrædderne, og med beviser i hånden vil {npc1} kaste den på højbordet i stedet.`,`{npc1} is hiding something: pressed, {npc1} admits to having accepted {villain}’s purse, a pension for life if {npc1} embraces {npc2} at the feast. The purse lies unopened under the floorboards, and with proof in hand {npc1} will throw it on the high table instead.`),q(`Heltene ser kun en gammel tjeners sorg. Om pungen hører de først ved festen, når {villain} minder {npc1} om den foran alle gæsterne.`,`The heroes see only an old servant’s grief. They hear of the purse only at the feast, when {villain} reminds {npc1} of it before all the guests.`)),X(`Intelligence (History)`,`medium`,q(`Heltene husker de gamle efterlysninger, der hang i hver kro i tyve år: Medaljonen hang i en fin sølvkæde med en lås formet som et agern. Et hittebarn, der har gemt medaljonen i tyve år, ville næppe have mistet kæden og beholdt medaljonen.`,`The heroes remember the old reward notices that hung in every inn for twenty years: the medallion was worn on a fine silver chain with a clasp shaped like an acorn. A foundling who kept the medallion for twenty years would hardly have lost the chain and kept the medallion.`),q(`Heltene kender kun historien om bortførerne. Hvad kæden betyder, forstår de først, når de ser resten af den i graven.`,`The heroes know only the story of the kidnappers. They do not understand what the chain means until they see the rest of it in the grave.`))],fight:!1,alternatives:[q(`Tag {npc1} med til {place} i nat: Den gamle tjener kender stien gennem frugthaven og viser vej til barnekammeret, men går langsomt, så hver vej tager et kvarter mere.`,`Take {npc1} along to {place} tonight: the old servant knows the path through the orchard and shows the way to the nursery, but walks slowly, so every walk takes a quarter of an hour longer.`),q(`Gå direkte til {place}: Heltene sparer tiden på kroen, men ved ikke, hvad {npc2} tror, og ved midnat bliver {npc2} låst inde i østtårnet.`,`Go straight to {place}: the heroes save the time at the inn, but do not know what {npc2} believes, and at midnight {npc2} is locked away in the east tower.`)],dmNotes:q(`Lad {npc1} lægge træhesten i en helts hånd. Den gamle tjener håber, at det er barnet, og frygter det på samme tid; eventyret virker bedst, når spillerne også håber. Træhesten bliver vigtig igen, når heltene finder dens tvilling.`,`Let {npc1} put the wooden horse in a hero’s hand. The old servant hopes it is the child and fears it at the same time; the adventure works best when the players hope too. The wooden horse matters again when the heroes find its twin.`)},middle:[{kind:`social`,at:`town`,present:[`npc2`,`npc3`],title:q(`Kroen Den Røde Hane`,`The Red Cockerel`),summary:q([`{npc2} har boet på kroen Den Røde Hane i en måned og sidder oppe i aften i værelset over krostuen og øver en tale til i morgen.`,`{npc3}, kroejeren, fik sølv for at sige, at {npc2} kom alene og uanmeldt, men kroens bog siger noget andet, og i foret i {npc2}s kiste ligger {villain}s breve.`,`Indtil midnat kan heltene tale med {npc2} her; ved midnat henter en lukket vogn fra {place} den unge fremmede, og kisten bliver stående.`],[`{npc2} has lodged at the Red Cockerel for a month and sits up tonight in the room above the taproom, rehearsing a speech for tomorrow.`,`{npc3}, the innkeeper, took silver to say that {npc2} arrived alone and unannounced, but the inn’s ledger says otherwise, and in the lining of {npc2}’s trunk lie {villain}’s letters.`,`Until midnight the heroes can talk to {npc2} here; at midnight a closed carriage from {place} fetches the young stranger, and the trunk stays behind.`]),readAloud:q([`Krostuen er fuld af gæster, der er kommet til festen, og alle taler om barnet, der kom hjem.`,`Ovenpå brænder et lys i vinduet, og en klar, øvet stemme siger de samme ord igen og igen som en skuespiller før en premiere.`,`Bag disken tørrer kroejeren det samme krus af igen og igen og kaster hele tiden et blik op ad trappen.`],[`The taproom is full of guests who have come for the feast, and everyone is talking about the child who came home.`,`Upstairs a candle burns in the window, and a clear, trained voice speaks the same words over and over like a player before opening night.`,`Behind the counter the innkeeper wipes the same mug again and again and keeps glancing up the stairs.`]),details:[q(`{npc3} fik sølv af {villain} for at sige, at {npc2} kom alene og uanmeldt, men i kroens bog står det, som det var: Værelset blev betalt en måned forud af {villain} dagen før, {npc2} kom med postvognen, og {villain} kom ind ad bagdøren den første aften og gik ved daggry, en uge før {villain} "genkendte" medaljonen på torvet. {npc3} fortæller også, at {villain} hvert år på brandnatten sidder alene i krostuen til midnat, køber et lille hvidt lys, sådan et, man tænder for et dødt barn, og går op til kapellet på {place} med det.`,`{npc3} took silver from {villain} to say that {npc2} arrived alone and unannounced, but the inn’s ledger tells it as it was. The room was paid a month ahead by {villain} the day before {npc2} came on the post coach, and {villain} came in by the back door on the first evening and left at dawn, a week before {villain} "recognised" the medallion in the square. {npc3} also says that every year on the night of the fire {villain} sits alone in the taproom until midnight, buys a small white candle, the kind lit for a dead child, and walks up to the chapel at {place} with it.`),q(`{npc2} er et hittebarn og en tidligere omrejsende skuespiller, hurtig og charmerende, og kan alle husets historier udenad, næsten for godt: {npc2} fortæller dem med {villain}s ord. Medaljonen hænger i et sort silkebånd, og i øskenen sidder to bøjede led af en fin, gammel kæde, sorte af sod; {npc2} siger, at kæden blev tabt for længe siden. {villain} har hvisket til {npc2}, at hittebarnet måske virkelig er det forsvundne barn, og {npc2} vil så gerne tro det; i foret i kisten under sengen ligger {villain}s lektiebreve, gemt som sikkerhed.`,`{npc2} is a foundling and a former strolling player, quick and charming, and knows every story of the household by heart, almost too well: {npc2} tells them in {villain}’s words. The medallion hangs on a black silk ribbon, and in its loop sit two bent links of a fine old chain, black with soot; {npc2} says the chain was lost long ago. {villain} has whispered to {npc2} that the foundling may truly be the lost child, and {npc2} longs to believe it; in the lining of the trunk under the bed lie {villain}’s lesson letters, kept as insurance.`),q(`Efter 2 timer (første tik) sidder to af {villain}s {foe} i krostuen og holder øje med døren og trappen. Ved midnat (andet tik) holder en lukket vogn med {place}s våben foran kroen med {villain}s kusk og nogle {foe}, og {npc2} kører med op til gæstekammeret i østtårnet; vagterne fra krostuen kører med, kisten bliver stående, og {npc3} har nøglen til værelset. Vagterne slås ikke i en fuld krostue: Står heltene i vejen, kører vognen tom tilbage, {villain} ved, at heltene har talt med {npc2}, og {npc2} kører op til {place} med gæsterne ved daggry.`,`After 2 hours (the first tick) two of {villain}’s {foe} sit in the taproom watching the door and the stairs. At midnight (the second tick) a closed carriage bearing the arms of {place} stops at the inn with {villain}’s coachman and some {foe}, and {npc2} is driven up to the guest chamber in the east tower. The watchers from the taproom ride along, the trunk stays behind, and {npc3} has the key to the room. The guards will not fight in a full taproom: if the heroes stand in the way, the carriage goes back empty, {villain} knows that the heroes have spoken with {npc2}, and {npc2} rides up to {place} with the guests at dawn.`)],checks:[X(`Charisma (Persuasion)`,`medium`,q(`{npc2} indrømmer at være et hittebarn, som {villain} har lært op, giver heltene lektiebrevene fra kisten og lover at nægte at tage imod seglet ved festen og fortælle gæsterne sandheden, hvis heltene står ved {npc2}s side i salen. Ved midnat kører {npc2} med vognen, som om intet var hændt, så {villain} intet aner.`,`{npc2} admits to being a foundling whom {villain} has coached, gives the heroes the lesson letters from the trunk and promises to refuse the seal at the feast and tell the guests the truth, if the heroes stand by {npc2} in the hall. At midnight {npc2} rides off in the carriage as if nothing had happened, so that {villain} suspects nothing.`),q(`{npc2} klamrer sig til drømmen og kalder på kroejeren; nu kan kun hårdere beviser end ord nå {npc2}: regnskabsbogen i østtårnet eller det, der ligger i graven. Inden for en time hører {villain} om samtalen og sender straks vagterne ud i vestfløjen. Brevene ligger stadig i kisten.`,`{npc2} clings to the dream and calls for the innkeeper; now only harder proof than words can reach {npc2}: the account book in the east tower or what lies in the grave. Within the hour {villain} hears of the conversation and sends the watch out to the west wing at once. The letters still lie in the trunk.`)),X(`Wisdom (Insight)`,`easy`,q(`Heltene ser, at {npc3} lyver om den første aften. Når heltene minder {npc3} om, at en kroejer ikke lyver i sin bog, slår {npc3} bogen op og fortæller også om {villain}s hvide lys på brandnatten.`,`The heroes see that {npc3} is lying about the first evening. Reminded that an innkeeper does not lie in the ledger, {npc3} opens the book and also tells of {villain}’s white candle on the night of the fire.`),q(`{npc3} holder fast i den betalte historie, og først når heltene kommer tilbage med {npc1}, slår {npc3} bogen op; det koster en halv time.`,`{npc3} sticks to the paid story, and only when the heroes come back with {npc1} does {npc3} open the book; it costs half an hour.`))],fight:!1,alternatives:[q(`Vent, til vognen er kørt, og få {npc3} til at låse værelset op: Kisten med brevene står der stadig, og vagterne fra krostuen er kørt med vognen.`,`Wait until the carriage has gone and have {npc3} unlock the room: the trunk with the letters is still there, and the watchers from the taproom have ridden off with the carriage.`),q(`Følg vognen op ad bakkevejen ved midnat: Den kører ind gennem porten, og heltene ser, hvilket tårn {npc2} bliver ført op i.`,`Follow the carriage up the hill road at midnight: it drives in through the gate, and the heroes see which tower {npc2} is taken up into.`)],dmNotes:q(`{npc2} er ingen skurk, men et menneske, der gerne vil være nogens barn. Spil {npc2} varm og lidt for velformuleret; den, der lytter efter, hører {villain}s sætninger i den unge fremmedes mund. Det, heltene siger her, følger med til festen.`,`{npc2} is no villain, but someone who longs to be somebody’s child. Play {npc2} warm and a little too well spoken; whoever listens closely hears {villain}’s phrases in the young stranger’s mouth. What the heroes say here carries over to the feast.`)},{kind:`exploration`,at:`site`,present:[],title:q(`Barnekammeret i vestfløjen`,`The Nursery in the West Wing`),summary:q([`Vestfløjen på {place} brændte for tyve år siden og blev aldrig bygget op igen, og den gamle sti gennem frugthaven fra {town} ender ved dens sammenstyrtede mur.`,`I barnekammeret er vinduet stadig malet fast under soden, og bag det forkullede klædeskab går den smalle trappe ned til krypten under kapellet, ryddet for murbrokker og med krummer af frisk mørtel på trinene.`,`Efter 2 timer (første tik) holder nogle {foe} vagt her på {villain}s ordre; kommer heltene før, er ruinen tom.`],[`The west wing of {place} burned twenty years ago and was never rebuilt, and the old path through the orchard from {town} ends at its fallen wall.`,`In the nursery the window is still painted shut under the soot, and behind the charred wardrobe the narrow stair goes down to the crypt beneath the chapel, cleared of rubble, with crumbs of fresh mortar on the steps.`,`After 2 hours (the first tick) some {foe} keep watch here on {villain}’s orders; if the heroes come earlier, the ruin is empty.`]),readAloud:q([`Vestfløjen er et skelet af sorte bjælker mod himlen, og vinden fløjter gennem vinduer uden glas.`,`I et hjørneværelse ligger en vugge væltet om på siden med mederne brændt ned til stumper.`,`Bag et forkullet klædeskab gaber en mørk sprække, og op fra den stiger en kold luft, der lugter af sten og kalk.`],[`The west wing is a skeleton of black beams against the sky, and the wind whistles through windows without glass.`,`In a corner room a cradle lies on its side, its rockers burnt down to stumps.`,`Behind a charred wardrobe a dark gap opens, and up from it rises cold air that smells of stone and lime.`]),details:[q(`Vejen: Fra {town} er der tyve minutter ad stien gennem frugthaven til vestfløjens mur. Fra vestfløjen er der ti minutter i skyggerne over gården til østtårnet og fem minutter ned ad trappen bag klædeskabet til krypten. Storsalen ligger mellem vestfløjen og østtårnet med kapellet bag højsædet i den vestlige ende, og fra krypten er der to minutter op gennem kapellet til den lille dør bag højsædet.`,`Distances: from {town} it is twenty minutes by the orchard path to the wall of the west wing. From the west wing it is ten minutes through the shadows across the yard to the east tower, and five minutes down the stair behind the wardrobe to the crypt. The great hall lies between the west wing and the east tower, with the chapel behind the high seat at its west end, and from the crypt it is two minutes up through the chapel to the small door behind the high seat.`),q(`Vinduet i barnekammeret er stadig malet fast under soden, og malingen løber ubrudt hen over hasperne: Ingen bar et barn ud ad den vej. Bag det forkullede klædeskab er den smalle trappe ned til krypten ryddet for murbrokker, og på trinene ligger krummer af frisk mørtel og stænk af kalk; for foden af trappen fører en lav dør uden slå for ind til krypten. Det tager ti minutter at flytte klædeskabet uden larm.`,`The nursery window is still painted shut under the soot, and the paint runs unbroken over the catches: nobody carried a child out that way. Behind the charred wardrobe the narrow stair down to the crypt has been cleared of rubble, and on the steps lie crumbs of fresh mortar and spatters of lime; at the foot of the stair a low, unbolted door opens into the crypt. Shifting the wardrobe quietly takes ten minutes.`),q(`Efter 2 timer (første tik), eller straks hvis {villain} har hørt om heltene på kroen, holder nogle {foe} vagt i vestfløjen med en lygte ved den sammenstyrtede mur. De er hyret til at holde fremmede ude, men ved ikke, hvad der er dernede. Kommer heltene før, er ruinen tom; er de her endnu, når vagterne kommer, må de skjule sig eller kæmpe. Falder halvdelen af vagterne, løber resten op til storsalen, og så står {boss} vagt ved døren bag højsædet resten af natten.`,`After 2 hours (the first tick), or at once if {villain} has heard of the heroes at the inn, some {foe} keep watch in the west wing with a lantern by the fallen wall. They were hired to keep strangers out but do not know what lies below. If the heroes come earlier, the ruin is empty; if they are still here when the watch arrives, they must hide or fight. If half of the watch falls, the rest run to the great hall, and then {boss} stands guard at the door behind the high seat for the rest of the night.`)],checks:[X(`Dexterity (Stealth)`,`medium`,q(`Heltene kommer ind i barnekammeret og ned ad trappen, uden at vagterne ser dem, og kan arbejde i ro.`,`The heroes get into the nursery and down the stair without the watch seeing them, and can work in peace.`),q(`En forkullet bjælke knækker under en støvle, og vagterne kommer med lygten; heltene må kæmpe eller trække sig tilbage ud i frugthaven.`,`A charred beam snaps under a boot, and the watch comes with the lantern; the heroes must fight or fall back into the orchard.`)),X(`Intelligence (Investigation)`,`easy`,q(`Heltene ser, at vinduet blev malet fast længe før branden, og finder mørtelkrummerne på trappen: Nogen er gået ned i krypten med mørtel i sommer.`,`The heroes see that the window was painted shut long before the fire, and find the mortar crumbs on the stair: someone went down into the crypt with mortar this summer.`),q(`Heltene finder først trappen, efter at de har gennemsøgt hele fløjen; det koster en halv time.`,`The heroes find the stair only after searching the whole wing; it costs half an hour.`))],fight:!0,alternatives:[q(`Lok vagterne væk med larm eller lys nede i frugthaven, og flyt klædeskabet, mens de leder.`,`Lure the watch away with noise or a light down in the orchard, and shift the wardrobe while they search.`),q(`Gå ned ad trappen med det samme: Krypten ligger fem minutter under barnekammeret, og om natten er der ingen dernede.`,`Go down the stair at once: the crypt lies five minutes below the nursery, and at night nobody is down there.`)],dmNotes:q(`Ruinen er stedet, hvor løgnen begyndte. Lad spillerne selv opdage vinduet, og lad den væltede vugge stå uden kommentar; de forstår det selv.`,`The ruin is where the lie began. Let the players discover the window themselves, and do not comment on the overturned cradle; they will understand.`)},{kind:`investigation`,at:`site`,present:[`npc2`],title:q(`Stuerne i østtårnet`,`The Rooms in the East Tower`),summary:q([`{villain}s stuer ligger øverst i østtårnet på den anden side af gården fra storsalen; i nat er de mørke og låste, for {villain} våger i storsalen.`,`I skrivepulten ligger godsets regnskabsbog med sommerens poster og i en skuffe et bundt små hvide lys ved siden af en almanak, og krogen til kryptens nøgle er tom.`,`Over for stuerne ligger gæstekammeret, hvor {npc2} bliver låst inde ved midnat.`],[`{villain}’s rooms are at the top of the east tower, across the yard from the great hall; tonight they are dark and locked, for {villain} keeps watch in the great hall.`,`In the writing desk lies the estate’s account book with this summer’s entries, and in a drawer a bundle of small white candles beside an almanac; the hook for the crypt key is empty.`,`Across the landing lies the guest chamber, where {npc2} is locked in at midnight.`]),readAloud:q([`Tårntrappen snor sig op forbi skydeskår til en dør med en ny lås.`,`Indenfor lugter der af blæk, lak og kold lysrøg, og alt står i snorlige rækker, fra pennene på pulten til nøglerne på deres kroge ved døren.`,`På den anden side af reposen sidder en tung nøgle i låsen til endnu en dør, som om nogen skal lukkes inde.`],[`The tower stair winds up past arrow slits to a door with a new lock.`,`Inside it smells of ink, sealing wax and cold candle smoke, and everything stands in perfect rows, from the pens on the desk to the keys on their hooks by the door.`,`Across the landing a heavy key sits in the lock of another door, as if someone is to be shut in.`]),details:[q(`Østtårnet ligger fem minutter over gården fra storsalen og ti minutter fra vestfløjen. Døren for foden af trappen har en ny lås, men vinduet på første repos har en knækket krog, og om natten kommer ingen her; tjenestefolkene er i storsalen og køkkenet. Efter daggry går gæsternes tjenere ud og ind af tårnet, og det bliver svært at komme uset op.`,`The east tower is five minutes across the yard from the great hall and ten minutes from the west wing. The door at the foot of the stair has a new lock, but the window on the first landing has a broken catch, and at night nobody comes here; the servants are in the great hall and the kitchens. After dawn the guests’ servants come and go in the tower, and getting up unseen becomes hard.`),q(`I skrivepulten ligger godsets regnskabsbog, og under "Reparation af møllen" står tre poster fra i sommer med {villain}s hånd: en skuespiller løst fri af sin trup for 30 guldstykker, festtøj syet efter mål sendt med brev og et sort silkebånd. I en skuffe ligger et bundt små hvide lys, sådan nogle, man tænder for et dødt barn, ved siden af en almanak, hvor brandnattens dato er ringet ind i hvert eneste år i tyve år. Husets nøgler hænger på mærkede kroge ved døren, men krogen mærket "Krypten" er tom: Den nøgle bærer {villain} i bæltet.`,`In the writing desk lies the estate’s account book, and under "Repairs to the mill" stand three entries from this summer in {villain}’s hand: a player released from a troupe for 30 gold pieces, feast clothes made to measures sent by letter, and a black silk ribbon. In a drawer lies a bundle of small white candles, the kind lit for a dead child, beside an almanac in which the date of the fire is circled for each of the last twenty years. The household’s keys hang on labelled hooks by the door, but the hook marked "Crypt" is empty: {villain} wears that key on their belt.`),q(`Før midnat står gæstekammeret tomt med nyt festtøj lagt frem på sengen. Fra midnat (andet tik) sidder {npc2} derinde, låst inde udefra "for at hvile sig" og lysvågen, medmindre heltene holdt {npc2} tilbage på kroen; nøglen sidder i låsen. Gennem døren eller ansigt til ansigt kan heltene tale med {npc2} uforstyrret, og det, {npc2} lover her, gælder ved festen præcis som på kroen.`,`Before midnight the guest chamber stands empty, with new feast clothes laid out on the bed. From midnight (the second tick) {npc2} sits in there, locked in from outside "to rest" and wide awake, unless the heroes kept {npc2} back at the inn; the key is in the lock. Through the door or face to face the heroes can talk with {npc2} undisturbed, and what {npc2} promises here holds at the feast exactly as at the inn.`)],checks:[X(`Intelligence (Investigation)`,`medium`,q(`Heltene finder både regnskabsbogens poster og skuffen med lysene og almanakken og ser den tomme krog: Nu ved de, at {villain} købte {npc2}, og at det, {villain} sørger over, ligger i krypten.`,`The heroes find both the account book’s entries and the drawer with the candles and the almanac, and see the empty hook: now they know that {villain} bought {npc2}, and that what {villain} mourns lies in the crypt.`),q(`Heltene finder kun regnskabsbogen; skuffen med lysene finder de først, hvis de leder igen, og det koster en halv time.`,`The heroes find only the account book; they find the drawer with the candles only if they search again, and that costs half an hour.`)),X(`Charisma (Persuasion)`,`easy`,q(`Har {npc2} ikke lovet heltene noget på kroen, gør regnskabsbogen og de hvide lys arbejdet nu: {npc2} forstår, at {villain} købte en skuespiller og sørger over et dødt barn, og lover at nægte at tage imod seglet ved festen og fortælle gæsterne sandheden.`,`If {npc2} promised the heroes nothing at the inn, the account book and the white candles do the work now: {npc2} understands that {villain} bought a player and mourns a dead child, and promises to refuse the seal at the feast and tell the guests the truth.`),q(`{npc2} vil ikke tro det før festen; først når {npc2} ser det, der ligger i graven, brister drømmen.`,`{npc2} will not believe it before the feast; only when {npc2} sees what lies in the grave does the dream break.`))],fight:!1,alternatives:[q(`Tag regnskabsbogen og almanakken med: De er tunge, men ved festen kan gæsterne selv læse posterne og se de ringede datoer.`,`Take the account book and the almanac along: they are heavy, but at the feast the guests can read the entries and see the circled dates for themselves.`),q(`Lås gæstekammeret op, og tal med {npc2} ansigt til ansigt: Så kan {npc2} selv se regnskabsbogen, men bliver {npc2} ikke vundet, peger {npc2} heltene ud for {villain} ved festen.`,`Unlock the guest chamber and talk with {npc2} face to face: {npc2} can then see the account book first-hand, but if {npc2} is not won over, {npc2} points the heroes out to {villain} at the feast.`)],dmNotes:q(`Østtårnet er {villain}s sind: ordentligt, pertentligt og fuld af skyld. Lad de hvide lys ligge midt i alt det ordentlige, så spillerne mærker, at hofmesteren ikke kun er en tyv.`,`The east tower is {villain}’s mind: tidy, fastidious and full of guilt. Let the white candles lie in the middle of all that order, so the players feel that the chamberlain is not only a thief.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`,`npc1`,`npc2`],title:q(`Festen i storsalen`,`The Feast in the Great Hall`),summary:q([`Fra middag er storsalen på {place} fuld af gæster: {villain} sidder ved højbordet med {npc2} ved sin side og herremandens segl på en rød pude, {boss} vogter den lille dør bag højsædet, der fører ind til kapellet, og nogle {foe} i nyt livré holder salens døre.`,`Under kapellet ligger krypten med den tilmurede niche, hvor herremandens barn har ligget i tyve år, to minutter fra højbordet.`,`Heltene skal lægge sandheden frem for gæsterne, før kapelklokken slår tre, og {villain} lægger seglet i {npc2}s hånd.`],[`From noon the great hall of {place} is full of guests: {villain} sits at the high table with {npc2} alongside and the lord’s seal on a red cushion, {boss} guards the small door behind the high seat that leads into the chapel, and some {foe} in new livery hold the doors of the hall.`,`Beneath the chapel lies the crypt with the walled-up niche where the lord’s child has lain for twenty years, two minutes from the high table.`,`Before the chapel bell strikes three and {villain} puts the seal in {npc2}’s hand, the heroes must lay the truth before the guests.`]),readAloud:q([`Hundredvis af lys brænder i storsalen, faner hænger fra bjælkerne, og de lange borde bugner af stegt vildt og vin.`,`Ved højbordet sidder en bleg ung fremmed i nyt tøj med en sølvmedaljon i et sort bånd, og ved siden af sidder en skikkelse i sort med en embedskæde om halsen og den ene hånd ved en rød pude, hvor en gammel seglring glimter.`,`Bag højsædet står en lille jernbeslået dør lukket, og ved det nederste bord sidder en gammel tjener og holder noget skjult i begge hænder.`],[`Hundreds of candles burn in the great hall, banners hang from the beams, and the long tables groan under roast venison and wine.`,`At the high table sits a pale young stranger in new clothes with a silver medallion on a black ribbon, and beside the stranger sits a figure in black with a chain of office and one hand resting by a red cushion where an old seal ring gleams.`,`Behind the high seat a small iron-bound door stands shut, and at the lowest table an old servant sits holding something hidden in both hands.`]),details:[q(`{villain} er i storsalen fra solnedgang til festen: Om natten ser {villain} til forberedelserne med {boss} ved sin side, fra daggry tager {villain} imod gæsterne, og fra middag sidder {villain} ved højbordet. {boss} og nogle {foe}, som {villain} hyrede som husets nye vagt efter herremandens død, holder døren bag højsædet og salens døre. De kæmper for deres løn, ikke for en falsk arving: Tvinger heltene døren eller lægger hånd på {villain}, angriber de, gæsterne trænger sig op ad væggene, og vagterne overgiver sig eller flygter, når {boss} falder. {villain} kæmper ikke, bliver ved højbordet, kalder heltene gale gravrøvere og tilbyder dem selve seglet for at slippe væk, når kampen vender.`,`{villain} is in the great hall from sunset until the feast: at night {villain} sees to the preparations with {boss} at hand, from dawn {villain} receives the guests, and from noon {villain} sits at the high table. {boss} and some {foe}, hired by {villain} as the household’s new guard after the lord’s death, hold the door behind the high seat and the doors of the hall. They fight for their pay, not for a false heir: if the heroes force the door or lay hands on {villain}, they attack, the guests press back against the walls, and the guards surrender or flee when {boss} falls. {villain} does not fight, stays at the high table, calls the heroes mad grave robbers and, when the fight turns, offers them the seal itself in exchange for being let go.`),q(`Den lille dør bag højsædet fører ind i kapellet, og fra kapellets gulv går en trappe ned til krypten bag et jerngitter, hvis nøgle {villain} bærer i bæltet; et brækjern får gitteret op på få minutter, men larmen høres i storsalen. I kryptens ældste væg sidder den tilmurede niche med brandnattens dato og ordet "Tilgiv" ridset ind i mørtlen, og en del af mørtlen er ny fra i sommer. Indenfor ligger et lille bundt i et blåt tæppe, sværtet i kanten, med tvillingen til {npc1}s træhest og resten af den fine sølvkæde med agernlåsen, revet over, så de sidste led passer til dem i øskenen på {npc2}s medaljon. I kryptens anden ende fører en lav dør uden slå for til trappen op til barnekammeret i vestfløjen.`,`The small door behind the high seat opens into the chapel, and from the chapel floor a stair goes down to the crypt behind an iron grille whose key {villain} wears on their belt; a crowbar opens the grille in a few minutes, but the noise carries into the great hall. In the oldest wall of the crypt is the walled-up niche, with the date of the fire and the word "Forgive" scratched into the mortar, and part of the mortar was laid fresh this summer. Inside lies a small bundle in a blue blanket, scorched at the edge, with the twin of {npc1}’s wooden horse and the rest of the fine silver chain with the acorn clasp, torn so that its last links match those in the loop of {npc2}’s medallion. At the far end of the crypt a low, unbolted door leads to the stair up to the nursery in the west wing.`),q(`Kommer heltene ad trappen fra barnekammeret om natten, er krypten mørk og tom: {villain} er i storsalen ovenover med {boss}, og kapellet og den tykke dør bag højsædet gør, at ingen i salen hører dem. Nichen kan åbnes stille på ti minutter, og heltene kan tage træhesten og kæden med eller lade alt ligge, så gæsterne selv kan se det i morgen. Efter klokken tre er seglet i {npc2}s hånd, og beviserne kan kun starte en strid, ikke standse anerkendelsen.`,`If the heroes come down the stair from the nursery at night, the crypt is dark and empty: {villain} is in the great hall above with {boss}, and the chapel and the thick door behind the high seat keep anyone in the hall from hearing them. The niche can be opened quietly in ten minutes, and the heroes can take the wooden horse and the chain along, or leave everything in place for the guests to see for themselves tomorrow. After three the seal is in {npc2}’s hand, and the proof can only start a quarrel, not stop the acknowledgement.`),q(`Uden kamp: Før klokken tre kan heltene lægge træhesten og kæden fra graven ved siden af {npc1}s træhest og {npc2}s medaljon på højbordet, sammen med lektiebrevene og regnskabsbogen, eller kræve, at gæsterne går med ned til nichen; med byfogeden fra {town} og de ældste gæster på heltenes side træder vagterne til side. Kender heltene til {villain}s pung og har de vist {npc1} beviserne, nægter {npc1} at omfavne {npc2} og kaster pungen på bordet; ellers minder {villain} {npc1} om pungen foran alle. Har {npc2} lovet heltene noget på kroen eller i østtårnet, nægter {npc2} at tage imod seglet og fortæller, hvordan {villain} købte en skuespiller fri; ellers brister {npc2} først ved synet af det, der lå i graven.`,`Without a fight: before three the heroes can lay the wooden horse and the chain from the grave beside {npc1}’s wooden horse and {npc2}’s medallion on the high table, together with the lesson letters and the account book, or demand that the guests come down with them to the niche. With the reeve of {town} and the eldest guests on the heroes’ side, the guards step aside. If the heroes know of {villain}’s purse and have shown {npc1} the proof, {npc1} refuses to embrace {npc2} and throws the purse on the table; otherwise {villain} reminds {npc1} of the purse before everyone. If {npc2} made the heroes a promise at the inn or in the east tower, {npc2} refuses the seal and tells how {villain} bought a player out of a troupe; otherwise {npc2} breaks only at the sight of what lay in the grave.`)],checks:[X(`Charisma (Persuasion)`,`medium`,q(`Med beviserne på højbordet vinder heltene salen: Byfogeden fra {town} beder vagterne træde til side, seglet bliver liggende på puden, og gæsterne vil se nichen med egne øjne.`,`With the proof on the high table the heroes win the hall: the reeve of {town} orders the guards to step aside, the seal stays on its cushion, and the guests want to see the niche with their own eyes.`),q(`{villain} kalder beviserne for et gravrøverkneb og beder {boss} kaste heltene ud; nu kan kun {npc1}s eller {npc2}s ord vende salen, ellers må heltene kæmpe sig vej til nichen.`,`{villain} calls the proof a grave robbers’ trick and orders {boss} to throw the heroes out; now only {npc1}’s or {npc2}’s word can turn the hall, or the heroes must fight their way to the niche.`)),X(`Charisma (Intimidation)`,`medium`,q(`Stillet over for den åbne niche eller træhesten fra graven brister {villain}s facade: {villain} indrømmer brandnatten foran alle, kalder vagterne tilbage og beder om at blive ført til byfogeden i stedet for til galgen.`,`At the sight of the open niche or the wooden horse from the grave, {villain}’s mask cracks: {villain} confesses what happened on the night of the fire before everyone, calls off the guards and begs to be taken to the reeve rather than to the gallows.`),q(`{villain} nægter alt og beder {boss} og vagterne rydde salen, og kampen begynder.`,`{villain} denies everything and orders {boss} and the guards to clear the hall, and the fight begins.`))],fight:!0,alternatives:[q(`Før gæsterne til graven: Kræv, at de ældste gæster går med ned i krypten; med gæsterne i hælene tør vagterne ikke løfte et våben, og {villain} må forklare nichen.`,`Take the guests to the grave: demand that the eldest guests come down into the crypt; with the guests at their heels the guards dare not raise a weapon, and {villain} must explain the niche.`),q(`Kom om natten: Gå ned ad trappen fra barnekammeret, tag træhesten og kæden fra nichen, og kom til festen med beviset i hænderne, før {villain} aner noget.`,`Come by night: go down the stair from the nursery, take the wooden horse and the chain from the niche, and come to the feast with the proof in hand before {villain} suspects a thing.`)],dmNotes:q(`Konfrontationen er en retssag, ikke et slag: Gæsterne er dommerne, og {villain} forklarer og forklarer, til beviserne ligger på bordet. Sig, hvor længe der er, til klokken slår tre. Har heltene vundet {npc1} eller {npc2} for sig undervejs, så giv dem deres øjeblik i salen.`,`The confrontation is a trial, not a battle: the guests are the judges, and {villain} explains and explains until the proof lies on the table. Call out how long is left until the bell strikes three. If the heroes have won {npc1} or {npc2} over along the way, give them their moment in the hall.`)}},jt=e({kernel:()=>Ft,scenes:()=>It}),Mt=e=>Array.isArray(e)?e.join(` `):e,Z=(e,t)=>({da:Mt(e),en:Mt(t)}),Nt=(e,t)=>({da:e.join(`
`),en:t.join(`
`)}),Q=(e,t,n,r)=>r?{at:e,observation:t,inference:n,handout:r}:{at:e,observation:t,inference:n},Pt=(e,t,n)=>({when:e,event:t,sign:n}),$=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),Ft={id:`festival-the-lantern-night`,titles:[Z(`Lygtenatten`,`The Lantern Night`),Z(`Tolv tønder lampeolie`,`Twelve Casks of Lamp Oil`),Z(`Lygter på floden`,`Lanterns on the River`)],missions:[`festival`,`investigation`],foes:`people`,roles:{npc1:Z(`en ung skriver i flodkøbmændenes laug, der har opdaget, at laugets festolie er forsvundet`,`a young clerk of the river merchants’ guild who has discovered that the guild’s festival oil has vanished`),npc2:Z(`en lygtemager, der hvert år fylder de fattiges lygter med laugets olie`,`a lantern maker who fills the lanterns of the poor with the guild’s oil every year`),npc3:Z(`en gammel vægter ved laugets pakhuse, som {villain} har givet fri i nat`,`an old watchman at the guild’s warehouses whom {villain} has given the night off`),villain:Z(`en oldermand for flodkøbmændenes laug, som hele {town} letter på hatten for`,`a guild master of the river merchants, whom all of {town} looks up to`)},hook:Z(`{npc1}, en ung skriver fra flodkøbmændenes laug, finder heltene på Storebro, da lygtemarkedet åbner, trykker dem en afskrift af laugets olieregister i hånden og beder dem finde de tolv tønder lampeolie, som {villain} har skrevet ud af bøgerne, før byens lygter går på floden ved midnat.`,`{npc1}, a young clerk of the river merchants’ guild, finds the heroes on the Great Bridge as the lantern market opens, presses a copy of the guild’s oil register into their hands. {npc1} begs them to find the twelve casks of lamp oil that {villain} has signed out of the guild’s stores, before the town’s lanterns go onto the river at midnight.`),people:{npc1:{wants:Z(`Vil have olien fundet og sandheden frem, før rådet tæller laugets pakhuse i morgen tidlig.`,`Wants the oil found and the truth out before the council counts the guild’s warehouses tomorrow morning.`),secret:Z(`Skrev posten uden at spørge, fordi {villain} har lovet {npc1} pladsen som laugets øverste skriver til foråret, og frygter nu at blive kaldt tyven, hvis sagen kommer frem.`,`Wrote the entry without asking questions, because {villain} has promised {npc1} the post of the guild’s head clerk in spring, and now fears being called the thief if it all comes out.`)},npc2:{wants:Z(`Vil se en tændt lygte på floden fra hvert hus i {town} ved midnat, olie eller ej.`,`Wants to see a lit lantern on the river from every house in {town} at midnight, oil or no oil.`),secret:Z(`Køber hver vinter smuglerolie af {boss} og kender {boss} langt bedre, end {npc2} vil indrømme.`,`Buys smuggled oil from {boss} every winter and knows {boss} far better than {npc2} will admit.`)},npc3:{wants:Z(`Vil beholde pladsen ved pakhusene og for en gangs skyld se lygterne fra Storebro.`,`Wants to keep their post at the warehouses, and for once to see the lanterns from the Great Bridge.`),secret:Z(`Fik en lille pung af {boss} for at lukke tønderne ind og se den anden vej, og har stadig en reservenøgle til vandporten, som {villain} ikke kender til.`,`Was given a small purse by {boss} to let the casks in and look the other way, and still has a spare key to the water gate that {villain} knows nothing about.`)}},premise:Z([`Lygtenatten er den store fest i {town}: Ved midnat sætter hvert hus en papirlygte på floden, mens hele byen står på broerne, og hvert år giver flodkøbmændenes laug lampeolie, så selv de fattigste huse har lys i deres lygter.`,`I årevis har {villain}, laugets oldermand, solgt laugets uld fra {place}, laugets pakhuse på havnekajen, og dækket over det med falske poster i bøgerne, og morgenen efter festen vil rådet tælle pakhusene og læse bøgerne, fordi laugets enkekasse er tom.`,`Derfor skrev {villain} tolv tønder lampeolie ud som laugets gave til festen og lod {boss} og nogle lejede {foe} rulle dem ind i uldlageret i det gamle pakhus, lige under regnskabsloftet, hvor bøgerne står.`,`Når lygterne går på floden ved midnat, tænder {boss} olien, brændende lygter uden navne på kajen skal få det til at ligne, at festens lygter satte ild til det gamle tømmer, og {villain}, der går forrest i lygteoptoget og først i den sidste time kommer til pakhuset for selv at lægge bøgerne på tønderne, vil stå i spidsen for spandekæden, når det er for sent.`],[`The Lantern Night is the great festival of {town}: at midnight every house sets a paper lantern on the river while the whole town stands on the bridges, and every year the river merchants’ guild gives lamp oil so that even the poorest houses have light in their lanterns.`,`For years {villain}, the guild’s master, has been selling the guild’s wool from {place}, its warehouses on the harbour quay, and covering it up with false entries in the books; the morning after the festival the council will count the warehouses and read the books, because the guild’s widows’ fund is empty.`,`So {villain} signed twelve casks of lamp oil out of the stores as the guild’s gift to the festival and had {boss} and some hired {foe} roll them into the wool store of the old storehouse, right beneath the counting loft where the books are kept.`,`When the lanterns go onto the river at midnight, {boss} will light the oil, and burning nameless lanterns on the quay will make it look as if the festival’s lanterns set the old timber alight. {villain}, who leads the lantern procession and only comes to the storehouse in the last hour to lay the books on the casks in person, will lead the bucket chain when it is too late.`]),goal:Z(`Find de tolv tønder lampeolie, og stop branden i {place}, før byens lygter går på floden ved midnat, så laugets bøger bliver reddet og kan vise, hvem der stod bag.`,`Find the twelve casks of lamp oil and stop the fire at {place} before the town’s lanterns go onto the river at midnight, so that the guild’s books are saved and can show who was behind it.`),objective:{target:Z(`Laugets regnskabsbøger på regnskabsloftet i {place} og det gamle pakhus, der skal brænde med dem`,`The guild’s books in the counting loft at {place}, and the old storehouse meant to burn with them`),state:Z(`Tyve læderbundne bøger, én for hvert år, står på hylderne på regnskabsloftet, og under loftet står de tolv tønder i uldlageret, fra solnedgang i olievædet halm og med en lunte ud under vandporten. {boss} og nogle {foe} holder kajen og pakhuset; ti minutter efter, at lygteoptoget har nået Storebro (efter 5 timer), er {villain} selv i pakhuset og hejser bøgerne ned på tønderne, og ved midnat tænder {boss} lunten.`,`Twenty leather-bound books, one for each year, stand on the shelves of the counting loft, and below the loft the twelve casks stand in the wool store; from sunset on they sit in oil-soaked straw, with a fuse running out under the water gate. {boss} and some {foe} hold the quay and the storehouse; ten minutes after the lantern procession reaches the Great Bridge (after 5 hours), {villain} is in the storehouse in person, hoisting the books down onto the casks, and at midnight {boss} lights the fuse.`),resolution:Z([`Skær lunten over eller træd den ud, før den når tønderne, få bøgerne ud ad gavltrappen, og bring dem og en tønde med laugets brændemærke til rådet, der står på Storebro, til den sidste lygte er drevet forbi en time efter midnat; {npc1}s olieregister og ordet fra {npc2} eller {npc3} viser, hvem der stod bag.`,`Fænger tønderne alligevel, kan heltene stadig redde de bøger, de kan bære, i de første ti minutter, og en spandekæde fra floden kan holde ilden fra naboerne, men så kan {villain} give lygterne skylden.`],[`Cut the fuse or stamp it out before it reaches the casks, get the books out by the gable stair, and bring them and a cask with the guild’s brand to the council, which stands on the Great Bridge until the last lantern has drifted past an hour after midnight. {npc1}’s oil register and the word of {npc2} or {npc3} show who was behind it.`,`If the casks catch fire anyway, the heroes can still save the books they can carry in the first ten minutes, and a bucket chain from the river can keep the fire from the neighbouring buildings, but then {villain} can blame the lanterns.`])},villain:{want:Z(`At blive ved med at være oldermand, den, hele {town} letter på hatten for, uden at nogen nogensinde tæller laugets uld eller læser laugets bøger.`,`To remain guild master, the one all of {town} looks up to, without anyone ever counting the guild’s wool or reading the guild’s books.`),plan:Z([`Først skrev {villain} tolv tønder lampeolie ud som laugets gave til festen og lod {boss} og nogle lejede {foe} rulle dem ind i uldlageret under regnskabsloftet i det gamle pakhus en nat for en uge siden.`,`I eftermiddag sendte {villain} vægteren hjem, tog nøglerne og satte {boss} og nogle {foe} på kajen som laugets festvagter; ved solnedgang væder de ulden og halmen med olie og lægger en lunte ud under vandporten.`,`Selv går {villain} forrest i lygteoptoget, så hele byen ser det, og når optoget når Storebro efter fem timer, smutter {villain} med laugets båd ned til vandporten og hejser bøgerne ned på tønderne; ved midnat tænder {boss} lunten, og {villain} løber op mod broerne og råber brand, når det er for sent.`],[`First, {villain} signed twelve casks of lamp oil out of the stores as the guild’s gift to the festival and, one night a week ago, had {boss} and some hired {foe} roll them into the wool store beneath the counting loft of the old storehouse.`,`This afternoon {villain} sent the watchman home, took the keys and posted {boss} and some {foe} on the quay as the guild’s festival guards; at sunset they soak the wool and the straw with oil and run a fuse out under the water gate.`,`{villain} walks at the head of the lantern procession for the whole town to see, and when it reaches the Great Bridge after five hours, slips down the river in the guild’s boat to the water gate and hoists the books down onto the casks. At midnight {boss} lights the fuse, and {villain} runs toward the bridges crying fire when it is too late.`]),weakness:Z([`{villain} stoler ikke på nogen med bøgerne og må selv hejse dem ned på tønderne i den sidste time, med laugets båd ved vandporten som eneste vej tilbage til Storebro uden at blive set.`,`{villain} er ingen kriger og frygter skam mere end straf: Står {villain} over for bøgerne, en tønde med laugets brændemærke og et vidne, tilbyder {villain} penge, ikke vold, og beder om at blive ført bort i stilhed.`],[`{villain} trusts no one with the books and must hoist them down onto the casks in person in the last hour, with the guild’s boat at the water gate as the only way back to the Great Bridge unseen.`,`{villain} is no fighter and fears shame more than punishment: faced with the books, a cask with the guild’s brand and a witness, {villain} offers money, not violence, and asks to be led away quietly.`])},stakes:Z(`Brænder {place} ved midnat, bliver bøgerne til aske, ilden kan springe til naboerne langs kajen, og lygterne får skylden: Rådet forbyder Lygtenatten for altid, enkerne får aldrig deres penge, {villain} bliver hyldet for spandekæden, og {npc1} får skylden for den forsvundne olie.`,`If {place} burns at midnight, the books turn to ash, the fire may leap to the neighbouring buildings along the quay, and the lanterns take the blame: the council bans the Lantern Night for ever, the widows never get their money, {villain} is praised for the bucket chain, and {npc1} is blamed for the missing oil.`),clock:{start:Z(`Tidlig aften på Lygtenattens dag, seks timer før midnat. Lygtemarkedet på Storebro er netop åbnet, solen går ned om en time, og laugets festvagter, {boss} og nogle {foe}, har stået på kajen ved {place} siden middag. {villain} er i Ankerhuset, laugets hus på torvet, og gør lygteoptoget klar.`,`Early evening on the day of the Lantern Night, six hours before midnight. The lantern market on the Great Bridge has just opened, the sun sets in an hour, and the guild’s festival guards, {boss} and some {foe}, have been standing on the quay at {place} since noon. {villain} is at Anchor Hall, the guild’s hall on the square, readying the lantern procession.`),ticks:[Pt(Z(`Efter 1 time (ved solnedgang)`,`After 1 hour (at sunset)`),Z(`Lygterne bliver tændt på broerne, og i ly af mørket bryder {boss} og nogle {foe} to af tønderne op i uldlageret, væder ulden og halmen med olie og lægger en tjæret lunte ud under vandporten til deres båd.`,`The lanterns are lit on the bridges, and under cover of darkness {boss} and some {foe} break open two of the casks in the wool store, soak the wool and the straw with oil and run a tarred fuse out under the water gate to their boat.`),Z(`En sødlig, fedtet lugt af lampeolie driver hen over kajen ved {place}, og festvagterne viser nu alle væk fra det gamle pakhus.`,`A sweetish, greasy smell of lamp oil drifts over the quay at {place}, and the festival guards now turn everyone away from the old storehouse.`)),Pt(Z(`Efter 5 timer (når lygteoptoget når Storebro)`,`After 5 hours (when the lantern procession reaches the Great Bridge)`),Z(`Lygteoptoget, der gik fra Ankerhuset efter 4 timer med {villain} og laugets store ankerlygte forrest, når Storebro; {villain} giver ankerlygten videre og smutter ned i laugets båd under broen, og ti minutter senere lægger båden til ved vandporten i {place}. Fra nu af er {villain} selv i det gamle pakhus og hejser bøgerne fra regnskabsloftet ned på tønderne, en halv times arbejde.`,`The lantern procession, which left Anchor Hall after 4 hours with {villain} and the guild’s great anchor lantern at its head, reaches the Great Bridge; {villain} hands the anchor lantern on and slips down into the guild’s boat under the bridge, and ten minutes later the boat lands at the water gate of {place}. From now on {villain} is in the old storehouse in person, hoisting the books from the counting loft down onto the casks, half an hour’s work.`),Z(`Trommer og fløjter på Storebro og laugenes store lygter over den tætte mængde, men oldermanden er væk fra laugets plads, og en enlig båd med en lygte i stævnen glider ned ad floden mod havnen.`,`Drums and pipes sound on the Great Bridge and the guilds’ great lanterns hang above the packed crowd, but the guild master is gone from the guild’s place, and a lone boat with a lantern in its bow glides down the river toward the harbour.`)),Pt(Z(`Efter 6 timer (ved midnat)`,`After 6 hours (at midnight)`),Z(`Klokkerne ringer, hvert hus sætter sin lygte på floden fra broerne, og {boss} tænder lunten; ilden tager tønderne, ulden og bøgerne, nogle {foe} spreder brændende lygter uden navne på kajen og i vandet ved porten, og {villain} løber op mod broerne og råber brand.`,`The bells ring, every house sets its lantern on the river from the bridges, and {boss} lights the fuse; the fire takes the casks, the wool and the books, some {foe} scatter burning nameless lanterns on the quay and in the water by the gate, and {villain} runs toward the bridges crying fire.`),Z(`Klokker fra alle broer, tusind lygter i et gyldent bånd ned ad floden og et rødt skær over pakhusene ved havnen.`,`Bells from every bridge, a thousand lanterns in a golden ribbon down the river, and a red glow over the warehouses at the harbour.`))],deadline:Z(`Efter 6 timer, ved midnat, tænder {boss} lunten: Er heltene ikke i det gamle pakhus da, brænder {place} med bøgerne indeni, og lygterne på floden driver ned mod en brand, de får skylden for.`,`After 6 hours, at midnight, {boss} lights the fuse: unless the heroes are in the old storehouse by then, {place} burns with the books inside, and the lanterns on the river drift down toward a fire they will be blamed for.`)},clues:{who:[Q(`town`,Z(`{npc1}s afskrift af laugets olieregister: For en uge siden blev tolv tønder lampeolie skrevet ud som laugets gave til festen, seks gange laugets sædvanlige gave, med {villain}s segl under posten.`,`{npc1}’s copy of the guild’s oil register: a week ago twelve casks of lamp oil were signed out as the guild’s gift to the festival, six times the guild’s usual gift, with {villain}’s seal beneath the entry.`),Z(`{villain} skrev selv olien ud af laugets bøger, og den kom aldrig frem.`,`{villain} signed the oil out in person, and it never arrived.`),Nt([`Flodkøbmændenes laug. Olieregistret, side 31.`,`Udleveret fra oliepakhuset: 12 tønder lampeolie.`,`Til lygtemagerne, laugets gave til Lygtenatten.`,`Skrevet efter oldermandens ord. Segl: {villain}, oldermand.`],[`The River Merchants’ Guild. Oil register, page 31.`,`Issued from the oil house: 12 casks of lamp oil.`,`To the lantern makers, the guild’s gift for the Lantern Night.`,`Entered on the guild master’s word. Seal: {villain}, guild master.`])),Q(`town`,Z(`{npc2}, lygtemageren, har ikke fået en dråbe af laugets olie i år: {villain} sendte bud om, at olien var forsinket, og {npc2} måtte købe olie dyrt i morges til de fattiges lygter.`,`{npc2}, the lantern maker, has not had a drop of the guild’s oil this year: {villain} sent word that the oil was late, and {npc2} had to pay dearly for oil this morning for the lanterns of the poor.`),Z(`{villain} løj om olien; den blev aldrig sendt.`,`{villain} lied about the oil; it was never sent.`)),Q(`town`,Z(`I oldermandens kammer i Ankerhuset ligger rådets brev: Laugets pakhuse skal tælles og bøgerne læses for rådet morgenen efter festen, fordi enkekassen ikke kan betale, og under brevet ligger {villain}s bøn om udsættelse og rådets afslag.`,`In the guild master’s chamber at Anchor Hall lies the council’s letter: the guild’s warehouses are to be counted and its books read before the council the morning after the festival, because the widows’ fund cannot pay, and beneath it lie {villain}’s plea for a delay and the council’s refusal.`),Z(`{villain} har noget i pakhusene og bøgerne, der ikke tåler at blive talt, og tiden løber ud i nat.`,`{villain} has something in the warehouses and the books that will not bear counting, and time runs out tonight.`),Nt([`Til oldermanden for flodkøbmændenes laug:`,`Da enkekassen ikke kan betale i år, tælles laugets pakhuse ved {place},`,`og laugets bøger læses for rådet morgenen efter Lygtenatten. Udsættelse gives ikke.`,`– {town}s råd`],[`To the master of the River Merchants’ Guild:`,`As the widows’ fund cannot pay this year, the guild’s warehouses at {place} shall be counted,`,`and the guild’s books read before the council the morning after the Lantern Night. No delay will be granted.`,`— the council of {town}`])),Q(`town`,Z(`{npc3}, den gamle vægter, blev i eftermiddag sendt hjem fra pakhusene af {villain} selv med en sølvmønt og besked om, at laugets nye festvagter passer kajen i nat, og {villain} tog vægterens nøgler med.`,`{npc3}, the old watchman, was sent home from the warehouses this afternoon by {villain} in person, with a silver coin and word that the guild’s new festival guards would keep the quay tonight, and {villain} took the watchman’s keys.`),Z(`{villain} ville have vægteren væk fra kajen i nat og lejede vagter på den.`,`{villain} wanted the watchman off the quay tonight and hired guards there instead.`)),Q(`site`,Z(`Gennem en sprække i vandporten ses tønderne mellem uldballerne, hver med laugets brændemærke og årets festmærke: den olie, der blev skrevet ud til lygtemagerne.`,`Through a crack in the water gate the casks can be seen among the wool bales, each with the guild’s brand and this year’s festival mark: the oil that was signed out to the lantern makers.`),Z(`Olien blev aldrig sendt; den står i laugets eget pakhus, hvor kun oldermanden har nøglerne.`,`The oil was never sent: it is in the guild’s own storehouse, where only the guild master holds the keys.`))],where:[Q(`town`,Z(`{npc1} fortæller, at lemmen fra regnskabsloftet ned til uldlageret i det gamle pakhus har været låst nedefra med en ny hængelås i en uge efter {villain}s ordre, og at laugets festvagter i eftermiddag viste skriveren væk fra kajen.`,`{npc1} says that the hatch from the counting loft down to the wool store of the old storehouse has been locked from below with a new padlock for a week, on {villain}’s order, and that the guild’s festival guards turned the clerk away from the quay this afternoon.`),Z(`Det, {villain} gemmer, står i uldlageret i det gamle pakhus, og kajen skal holdes tom i nat.`,`Whatever {villain} is hiding is in the wool store of the old storehouse, and the quay is to be kept empty tonight.`)),Q(`town`,Z(`En nat for en uge siden lukkede {npc3} {boss} og nogle {foe} ind ad vandporten til det gamle pakhus og så dem rulle tolv tønder ind i uldlageret under regnskabsloftet, "efter oldermandens ordre".`,`One night a week ago {npc3} let {boss} and some {foe} in by the water gate of the old storehouse and saw them roll twelve casks into the wool store beneath the counting loft, "on the guild master’s orders".`),Z(`Olien står i uldlageret i det gamle pakhus i {place}, lige under laugets bøger.`,`The oil is in the wool store of the old storehouse at {place}, right beneath the guild’s books.`)),Q(`site`,Z(`Plankerne foran vandporten til det gamle pakhus er skrammede af tønder og mørke af olie, og porten er nyligt smurt i hængslerne.`,`The planks in front of the water gate of the old storehouse are scored by casks and dark with oil, and the gate’s hinges have just been greased.`),Z(`Olien er rullet ind ad vandporten til det gamle pakhus, og porten skal kunne åbnes uden en lyd.`,`The oil was rolled in through the water gate of the old storehouse, and the gate is meant to open without a sound.`)),Q(`town`,Z(`{npc2} solgte i morges tyve lygter uden navne til nogle {foe} fra havnen, der bar dem ned mod kajen ved {place}, og ingen i {town} sætter en lygte uden navn på vandet.`,`This morning {npc2} sold twenty lanterns without names to some {foe} from the harbour, who carried them down toward the quay at {place}, and nobody in {town} sets a nameless lantern on the water.`),Z(`Nogen vil have brændte lygter at vise frem på kajen ved {place} i nat.`,`Someone wants burnt lanterns to show on the quay at {place} tonight.`)),Q(`site`,Z(`I vagternes båd under vandporten ligger en sæk med tyve lygter uden navne, og fra solnedgang løber en tjæret lunte fra båden ind under porten.`,`In the guards’ boat beneath the water gate lies a sack of twenty nameless lanterns, and from sunset a tarred fuse runs from the boat in under the gate.`),Z(`Ilden skal tændes fra båden ved vandporten til det gamle pakhus, og lygterne skal tage skylden.`,`The fire is to be lit from the boat at the water gate of the old storehouse, and the lanterns are to take the blame.`))]},endings:{success:Z(`En time efter midnat, mens de sidste lygter driver forbi, lægger heltene laugets bøger og en tønde med brændemærket frem for rådet på Storebro, og de vidner, der lovede at tale, træder frem ved siden af dem. {villain} bliver ført bort af byvagten i sin oldermandskæde, mens hele broen tier, enkerne får deres penge af {villain}s formue, og {npc1} fører laugets bøger med rådets tak; vandt en af heltene lygtebærerbåndet, sætter helten næste år den første lygte på floden.`,`An hour after midnight, as the last lanterns drift past, the heroes lay the guild’s books and a branded cask before the council on the Great Bridge, and the witnesses who promised to speak step forward beside them. {villain} is led away by the town watch, still wearing the guild master’s chain, while the whole bridge falls silent, the widows are paid out of {villain}’s fortune, and {npc1} keeps the guild’s books with the council’s thanks; if a hero won the lantern-bearer’s ribbon, that hero sets the first lantern on the river next year.`),partial:Z(`Ilden bliver stoppet eller holdt fra naboerne, men beviset slår ikke til: Bøgerne er brændt, eller vidnerne tier, og {villain} står i laugets kæde på Storebro og nægter alt. {villain} kalder olien en fejl i {npc1}s regnskab, bærer fortsat kæden og sørger stille for, at {npc1} mister sin plads, men Lygtenatten bliver holdt igen næste år, og hele havnen ved, hvem der stoppede ilden.`,`The fire is stopped or kept from the neighbouring buildings, but the proof falls short: the books have burned or the witnesses keep silent, and {villain} stands on the Great Bridge in the guild’s chain, denying everything. {villain} calls the oil a mistake in {npc1}’s accounts, keeps the chain and quietly sees to it that {npc1} loses their post, but the Lantern Night is held again next year, and the whole harbour knows who stopped the fire.`),failure:Z(`Ved midnat står {place} i flammer, og ilden springer til to naboer langs kajen, før spandekæden fra broerne når frem med {villain} i spidsen. Bøgerne er aske, brændte lygter uden navne ligger på kajen og i vandet, og rådet forbyder Lygtenatten for altid; {villain} bliver hyldet for sit mod, enkerne får aldrig deres penge, og {npc1} bliver jaget ud af lauget som den, der lod olien forsvinde.`,`At midnight {place} goes up in flames, and the fire leaps to two neighbouring buildings along the quay before the bucket chain from the bridges arrives with {villain} at its head. The books are ash, burnt nameless lanterns lie on the quay and in the water, and the council bans the Lantern Night for ever; {villain} is praised for courage, the widows never get their money, and {npc1} is driven out of the guild as the one who let the oil vanish.`)}},It={opening:{kind:`opening`,at:`town`,present:[`npc1`],title:Z(`Blæk og olie`,`Ink and Oil`),summary:Z([`Tidligt på aftenen på Lygtenatten, mens lygtemarkedet på Storebro summer af musik og stegte æbler, finder {npc1}, en ung skriver fra flodkøbmændenes laug, heltene og trykker dem en afskrift af laugets olieregister i hånden.`,`For en uge siden blev tolv tønder lampeolie skrevet ud som laugets gave til festen med {villain}s segl under, men lygtemagerne har ikke fået en dråbe, og ingen ved, hvor olien er; {npc1} beder heltene finde den og finde ud af hvorfor, før byens lygter går på floden ved midnat.`,`Byen har tre spor: lygtemageren {npc2} i gyden langs floden, Ankerhuset, hvor {villain} gør lygteoptoget klar, og laugets pakhuse ved {place}, hvor {npc1} arbejder.`],[`Early in the evening of the Lantern Night, while the lantern market on the Great Bridge hums with music and smells of roasting apples, {npc1}, a young clerk of the river merchants’ guild, finds the heroes and presses a copy of the guild’s oil register into their hands.`,`A week ago twelve casks of lamp oil were signed out as the guild’s gift to the festival under {villain}’s seal, but the lantern makers have not had a drop, and nobody knows where the oil is. {npc1} asks the heroes to find it, and to find out why, before the town’s lanterns go onto the river at midnight.`,`The town holds three leads: the lantern maker {npc2} in the lane along the river; Anchor Hall, where {villain} is readying the lantern procession; and the guild’s warehouses at {place}, where {npc1} works.`]),readAloud:Z([`Storebro er ét langt marked af lys: boder med papirlygter i alle farver, børn, der maler navne på lygternes sider, og duften af røget ål og varm æblemost.`,`Under broen glider floden sort og stille mod havnen, og på broens rækværk sidder tre spillemænd og spiller den gamle lygtevise, mens folk synger med på omkvædet.`,`En ung skriver med blæk på fingrene og en papirrulle under armen baner sig vej hen mod jer og kigger sig over skulderen, før de første ord kommer.`],[`The Great Bridge is one long market of light: stalls of paper lanterns in every colour, children painting names on the lanterns’ sides, and the smell of smoked eel and hot cider.`,`Beneath the bridge the river slides black and quiet toward the harbour, and three fiddlers sitting on the railing play the old lantern song while people join in the chorus.`,`A young clerk with inky fingers and a roll of paper under one arm pushes toward you and glances over one shoulder before speaking.`]),details:[Z(`Afskriften viser posten: tolv tønder lampeolie, seks gange laugets sædvanlige gave, udleveret fra oliepakhuset for en uge siden "til lygtemagerne". {npc1} skrev posten efter {villain}s ord, og {villain} satte sit segl under. I eftermiddag kom lygtemageren {npc2} op på regnskabsloftet og spurgte, hvor laugets olie blev af; der er ikke kommet en dråbe.`,`The copy shows the entry: twelve casks of lamp oil, six times the guild’s usual gift, issued from the oil house a week ago "to the lantern makers". {npc1} wrote the entry on {villain}’s word, and {villain} set the seal beneath it. This afternoon the lantern maker {npc2} came up to the counting loft to ask where the guild’s oil had got to; not a drop has arrived.`),Z(`Morgenen efter festen tæller rådet laugets pakhuse og læser bøgerne, fordi enkekassen ikke kan betale, og de tyve regnskabsbøger står klar på regnskabsloftet i det gamle pakhus ved {place}. Lemmen fra loftet ned til uldlageret har været låst nedefra med en ny hængelås i en uge efter {villain}s ordre, "til uldkøberne kommer", og i eftermiddag viste laugets festvagter {npc1} væk fra kajen: "Ingen på kajen i nat, oldermandens ordre." {npc1} har stadig nøglen til regnskabsloftet.`,`The morning after the festival the council counts the guild’s warehouses and reads the books, because the widows’ fund cannot pay, and the twenty ledgers stand ready in the counting loft of the old storehouse at {place}. The hatch from the loft down to the wool store has been locked from below with a new padlock for a week, on {villain}’s order, "until the wool buyers come", and this afternoon the guild’s festival guards turned {npc1} away from the quay: "Nobody on the quay tonight, the guild master’s orders." {npc1} still has the key to the counting loft.`),Z(`Festens program: Solen går ned om en time, og lygterne bliver tændt på broerne. Tre timer efter start løbes lygteløbet fra kajen ved {place} op til Storebro, fire timer efter start går lygteoptoget fra Ankerhuset med {villain} forrest, og det når Storebro en time senere. Ved midnat ringer klokkerne, og hvert hus sætter sin lygte på floden, mens rådet står på Storebro, til den sidste lygte er drevet forbi en time senere.`,`The festival programme: the sun sets in an hour, and the lanterns are lit on the bridges. Three hours after the start the lantern race is run from the quay at {place} up to the Great Bridge, four hours after the start the lantern procession leaves Anchor Hall with {villain} at its head, and it reaches the Great Bridge an hour later. At midnight the bells ring and every house sets its lantern on the river, while the council stands on the Great Bridge until the last lantern has drifted past an hour later.`),Z(`Vejene: Hver vej mellem to steder i byen, også fra Storebro ned til kajen ved {place}, tager et kvarter til fods, og fra lygteoptoget går (efter 4 timer) en halv time gennem mængden. En båd fra Storebro ned ad floden til {place} tager ti minutter, tilbage op ad floden tyve. Hvert besøg, en samtale eller en grundig undersøgelse, koster en halv time.`,`Distances: every walk between two places in town, including from the Great Bridge down to the quay at {place}, takes a quarter of an hour, and half an hour through the crowd once the procession sets off (after 4 hours). A boat from the Great Bridge down the river to {place} takes ten minutes, and twenty back upstream. Every visit, whether a conversation or a thorough search, costs half an hour.`)],checks:[$(`Wisdom (Insight)`,`easy`,Z(`{npc1} er bange for mere end olien: Presset indrømmer skriveren at have skrevet posten uden at spørge, fordi {villain} har lovet {npc1} en bedre plads i lauget, og at frygte at blive kaldt tyven; som tegn på god tro giver {npc1} heltene nøglen til regnskabsloftet.`,`{npc1} fears more than the lost oil: pressed, the clerk admits to writing the entry without asking questions, because {villain} has promised {npc1} a better post in the guild, and to fearing being called the thief; as a sign of good faith {npc1} gives the heroes the key to the counting loft.`),Z(`Heltene ser kun en ivrig ung skriver. {npc1} holder både nøglen og frygten for sig selv; heltene må bryde ind på regnskabsloftet, og de hører først om løftet fra {villain}, når {villain} giver {npc1} skylden i pakhuset.`,`The heroes see only an eager young clerk. {npc1} says nothing of the key or the fear; the heroes must break into the counting loft, and they do not hear of {villain}’s promise until {villain} blames {npc1} in the storehouse.`)),$(`Intelligence (Investigation)`,`medium`,Z(`Heltene ser, at tolv tønder er laugets lampeolie til en hel vinter, og at posten, i modsætning til alle andre i registret, ikke nævner vogn, pram eller bærere: Olien har aldrig forladt laugets pakhuse, og den, der gemmer så meget olie ved havnen på Lygtenatten, vil have ild.`,`The heroes see that twelve casks is a whole winter’s lamp oil for the guild, and that unlike every other entry in the register this one names no cart, barge or porters: the oil never left the guild’s warehouses, and whoever hides that much oil by the harbour on the Lantern Night wants a fire.`),Z(`Heltene ser kun et tyveri. Hvad olien skal bruges til, forstår de først, når de lugter den ved vandporten til det gamle pakhus.`,`The heroes see only a theft. They do not understand what the oil is for until they smell it at the water gate of the old storehouse.`))],fight:!1,alternatives:[Z(`Gå direkte til pakhusene: Heltene sparer tiden i byen, men festvagterne viser alle væk fra kajen, og uden byens spor ved heltene hverken, hvem vagterne er, eller hvad olien skal bruges til.`,`Go straight to the warehouses: the heroes save the time in town, but the festival guards turn everyone away from the quay, and without the town’s leads the heroes know neither who the guards are nor what the oil is for.`),Z(`Tag {npc1} med: Skriveren kender hvert bræt i det gamle pakhus og har nøglen til regnskabsloftet, men festvagterne kender skriverens ansigt, og ser de {npc1} på kajen, sender {boss} bud til {villain}, som hvis heltene var blevet fundet på trappen i Ankerhuset.`,`Take {npc1} along: the clerk knows every board of the old storehouse and has the key to the counting loft, but the festival guards know the clerk’s face, and if they see {npc1} on the quay, {boss} sends word to {villain}, just as if the heroes had been caught on the stair at Anchor Hall.`)],dmNotes:Z(`Lad festen være varm og larmende omkring heltene: musik, lys, mad og et barn, der vil vise sin lygte frem. Festens program er eventyrets ur; sig tiden, hver gang heltene flytter sig, og lad mængden blive tættere, jo nærmere midnat kommer.`,`Let the festival be warm and loud around the heroes: music, light, food and a child who wants to show off a lantern. The festival programme is the adventure’s clock; call out the time whenever the heroes move, and let the crowd grow thicker the closer midnight comes.`)},middle:[{kind:`social`,at:`town`,present:[`npc2`],title:Z(`Lygtemagerens værksted`,`The Lantern Maker’s Workshop`),summary:Z([`I lygtemagernes gyde langs floden har {npc2} værksted, og hele gyden er fuld af familier, der køber papirlygter og maler navne og ønsker på dem, som skikken byder.`,`{npc2} fylder de fattiges små lerlamper med olie, der blev købt dyrt i morges, fordi laugets olie aldrig kom, og har i dag solgt tyve lygter uden navne til nogle {foe} fra havnen.`,`Her kan heltene få bekræftet, at olien aldrig kom, få navn på køberne og vinde et vidne, og tre timer efter start løber lygteløbet gennem gyden.`],[`In the lantern makers’ lane along the river, {npc2} keeps a workshop, and the whole lane is full of families buying paper lanterns and painting names and wishes on them, as custom demands.`,`{npc2} is filling the small clay lamps of the poor with oil bought dear this morning, because the guild’s oil never came, and earlier today sold twenty lanterns without names to some {foe} from the harbour.`,`Here the heroes can confirm that the oil never came, put a name to the buyers and win a witness, and three hours after the start the lantern race runs through the lane.`]),readAloud:Z([`Gyden er så smal, at lygterne på snorene mellem husene næsten rører hinanden, og under dem trænges folk om borde med pensler og farvekrukker.`,`Et barn maler et navn på en gul lygte med tungen i mundvigen, mens en bedstemor staver bogstaverne højt.`,`Inde i et lavt værksted fylder en lygtemager med sod på kinden små lerlamper fra en kande, så olien glinser i lyset.`],[`The lane is so narrow that the lanterns on the strings between the houses almost touch, and beneath them people crowd round tables of brushes and paint pots.`,`A child paints a name on a yellow lantern with the tip of their tongue showing, while a grandmother spells the letters aloud.`,`Inside a low workshop a lantern maker with soot on one cheek fills small clay lamps from a jug, the oil glinting in the light.`]),details:[Z(`Skikken er, at hvert hus maler navnene på sine døde og et ønske for året på sin lygte, før den sættes på floden ved midnat. En lygte uden navn bringer ulykke, og ingen i {town} sætter en blank lygte på vandet; lygter uden navne er kun til at brænde.`,`Custom has every house paint the names of its dead and a wish for the year on its lantern before it goes onto the river at midnight. A lantern without a name brings bad luck, and nobody in {town} sets a blank one on the water; nameless lanterns are only good for burning.`),Z(`Hvert år får {npc2} laugets olie til de fattiges lygter, men i år kom der ikke en dråbe: {villain} sendte bud om, at olien var forsinket, og {npc2} købte selv olie dyrt i morges. Samme morgen kom nogle {foe} fra havnen og købte tyve lygter uden navne for den dobbelte pris og bar dem ned mod kajen ved {place}. {npc2} kender deres anfører, {boss}, langt bedre, end {npc2} vil sige.`,`Every year {npc2} gets the guild’s oil for the lanterns of the poor, but this year not a drop came: {villain} sent word that the oil was late, and {npc2} paid dearly for oil this morning. That same morning some {foe} from the harbour bought twenty lanterns without names at double the price and carried them down toward the quay at {place}. {npc2} knows their leader, {boss}, far better than {npc2} lets on.`),Z(`Lygteløbet starter på kajen ved {place} tre timer efter start og går op gennem gyden til Storebro, et kvarters løb. {npc2}s lærling løber med en lygte fra værkstedet, og en helt, der vil løbe med, kan få en løbslygte her.`,`The lantern race begins on the quay at {place} three hours after the start and runs up through the lane to the Great Bridge, a quarter of an hour’s run. {npc2}’s apprentice runs with a lantern from the workshop, and a hero who wants to run can get a race lantern here.`)],checks:[$(`Wisdom (Insight)`,`medium`,Z(`{npc2} kender køberne fra vintrene: {boss} sælger smuglerolie på kajen, og {npc2} køber den. Presset fortæller {npc2}, at {boss} og nogle {foe} i nat står på kajen ved {place} som laugets festvagter, hyret af {villain}.`,`{npc2} knows the buyers from past winters: {boss} sells smuggled oil on the quay, and {npc2} buys it. Pressed, {npc2} admits that {boss} and some {foe} are on the quay at {place} tonight as the guild’s festival guards, hired by {villain}.`),Z(`{npc2} siger ikke mere, end at køberne kom fra havnen. Heltene kender først festvagterne som køberne, når de ser sækken med lygterne uden navne i båden ved vandporten.`,`{npc2} says no more than that the buyers came from the harbour. The heroes do not recognise the festival guards as the buyers until they see the sack of nameless lanterns in the boat at the water gate.`)),$(`Charisma (Persuasion)`,`easy`,Z(`{npc2} lover at sige det hele for rådet på Storebro efter midnat, både at laugets olie aldrig kom, og hvem der købte lygterne uden navne, selv om smuglerolien kommer frem.`,`{npc2} promises to tell the council on the Great Bridge after midnight both that the guild’s oil never came and who bought the nameless lanterns, even if the smuggled oil comes out.`),Z(`{npc2} vil ikke tale for rådet af frygt for smuglerolien; uden lygtemagerens ord kan {villain} påstå, at olien blev leveret.`,`{npc2} will not speak before the council for fear of the smuggled oil; without the lantern maker’s word, {villain} can claim the oil was delivered.`))],fight:!1,alternatives:[Z(`Hjælp {npc2} med lamperne: En time ved bordet med kande og tragt giver lygtemagerens fulde tillid, så {npc2} fortæller alt om {boss} uden at blive presset, men timen er tabt for resten af byen.`,`Help {npc2} with the lamps: an hour at the table with jug and funnel wins the lantern maker’s full trust, so {npc2} tells everything about {boss} without being pressed, but the hour is lost to the rest of the town.`),Z(`Meld en helt til lygteløbet: {npc2} giver helten en løbslygte, og ved starten tre timer efter start står helten midt i mængden lige foran pakhusene ved {place}.`,`Enter a hero in the lantern race: {npc2} gives the hero a race lantern, and at the start, three hours in, the hero stands in the thick of the crowd right in front of the warehouses at {place}.`)],dmNotes:Z(`Gyden er festens hjerte: Lad spillerne male deres egne lygter, hvis de vil, og lad {npc2} være varm og travl. Lygtemagerens tavshed om køberne er skam, ikke ondskab, og den, der hjælper, får hele sandheden.`,`The lane is the heart of the festival: let the players paint their own lanterns if they like, and let {npc2} be warm and busy. The lantern maker’s silence about the buyers is shame, not malice, and whoever helps gets the whole truth.`)},{kind:`investigation`,at:`town`,present:[`villain`,`npc3`],title:Z(`Ankerhuset`,`Anchor Hall`),summary:Z([`Ankerhuset er flodkøbmændenes laugshus på torvet ved Storebro, og i aften er salen fuld af laugsbrødre, der spiser og drikker, mens laugets store ankerlygte bliver gjort klar til lygteoptoget.`,`{villain}, oldermanden, tager imod gæster ved højbordet, ovenpå ligger oldermandens kammer med laugets breve, og i køkkenet sidder {npc3}, den gamle vægter fra pakhusene, og brokker sig over at have fået fri.`,`Her kan heltene se {villain} i øjnene, finde rådets brev og høre vægteren, men kun til optoget går fire timer efter start.`],[`Anchor Hall is the river merchants’ guild hall on the square by the Great Bridge, and tonight it is full of guild members eating and drinking while the guild’s great anchor lantern is readied for the lantern procession.`,`{villain}, the guild master, receives guests at the high table; upstairs lies the guild master’s chamber with the guild’s letters; and in the kitchen sits {npc3}, the old watchman from the warehouses, grumbling about the night off.`,`Here the heroes can look {villain} in the eye, find the council’s letter and question the watchman, but only until the procession leaves four hours after the start.`]),readAloud:Z([`Over døren til det gamle laugshus hænger et anker af sortet jern, og indenfor er salen varm af fakler, stegeos og latter.`,`Midt i salen står en lygte af olieret papir, høj som en mand og formet som et skib, og laugsbrødre i blå kapper retter de sidste spanter.`,`For enden af højbordet løfter en værdig skikkelse med en tung sølvkæde om halsen sit krus mod jer og smiler, som om I var ventet.`],[`Over the door of the old guild hall hangs an anchor of blackened iron, and inside the hall is warm with torches, the smoke of roasting meat and laughter.`,`In the middle of the hall stands a lantern of oiled paper, as tall as a man and shaped like a ship, and guild members in blue cloaks straighten its last ribs.`,`At the end of the high table a dignified figure with a heavy silver chain around their neck raises a mug toward you and smiles, as if you were expected.`]),details:[Z(`{villain} er elskværdig, gavmild og elsket af lauget. Spørger heltene om olien, svarer {villain}, at den blev givet til lygtemagerne, og at {npc1} må have skrevet forkert, og byder heltene en plads ved laugets bord på Storebro ved midnat. Fire timer efter start går {villain} forrest i lygteoptoget med ankerlygten; så står salen tom på nær tjenestefolkene, og gaderne bliver så fulde, at hver vej i byen tager en halv time i stedet for et kvarter.`,`{villain} is gracious, generous and loved by the guild. Asked about the oil, {villain} answers that it was given to the lantern makers and that {npc1} must have written it down wrong, and offers the heroes a place at the guild’s table on the Great Bridge at midnight. Four hours after the start {villain} leads the lantern procession with the anchor lantern; then the hall is empty but for the servants, and the streets grow so full that every walk across town takes half an hour instead of a quarter.`),Z(`I oldermandens kammer ovenpå ligger rådets brev om, at laugets pakhuse skal tælles og bøgerne læses morgenen efter festen, fordi enkekassen ikke kan betale, og under det {villain}s bøn om udsættelse og rådets afslag. På tavlen med laugets nøgler er krogene til vandporten og uldlageret tomme. Når optoget er gået, kan kammeret gennemsøges i ro.`,`In the guild master’s chamber upstairs lies the council’s letter saying that the guild’s warehouses are to be counted and the books read the morning after the festival, because the widows’ fund cannot pay, and beneath it lie {villain}’s plea for a delay and the council’s refusal. On the board where the guild’s keys hang, the hooks for the water gate and the wool store are empty. Once the procession has left, the chamber can be searched in peace.`),Z(`I køkkenet sidder {npc3} med et stykke honningkage. {villain} sendte i eftermiddag vægteren hjem med en sølvmønt, tog nøglerne og sagde, at laugets festvagter passer kajen i nat. En nat for en uge siden lukkede vægteren {boss} og nogle {foe} ind ad vandporten og så dem rulle tolv tønder ind i uldlageret under regnskabsloftet, "efter oldermandens ordre". Når optoget går, bærer {npc3} en af laugets lygter i det og står på Storebro ved midnat.`,`In the kitchen sits {npc3} with a slice of honey cake. This afternoon {villain} sent the watchman home with a silver coin, took the keys and said the guild’s festival guards would keep the quay tonight. One night a week ago the watchman let {boss} and some {foe} in by the water gate and saw them roll twelve casks into the wool store beneath the counting loft, "on the guild master’s orders". When the procession leaves, {npc3} carries one of the guild’s lanterns in it and stands on the Great Bridge at midnight.`)],checks:[$(`Dexterity (Stealth)`,`medium`,Z(`Heltene slipper op i oldermandens kammer uden at blive set og finder rådets brev og de tomme kroge på nøgletavlen.`,`The heroes slip up to the guild master’s chamber unseen and find the council’s letter and the empty hooks on the key board.`),Z(`En tjener finder heltene på trappen; {villain} lader dem vise ud med et smil og sender en dreng ned til kajen. Fra nu af venter {boss} heltene: En vagt står også ved gavltrappen til regnskabsloftet, og ingen slipper ubemærket ind i det gamle pakhus uden en afledning.`,`A servant finds the heroes on the stair; {villain} has them shown out with a smile and sends a boy running to the quay. From now on {boss} expects the heroes: a guard stands at the gable stair to the counting loft as well, and nobody gets into the old storehouse unnoticed without a diversion.`)),$(`Charisma (Persuasion)`,`easy`,Z(`{npc3} giver heltene reservenøglen til vandporten, som {villain} ikke kender til, og lover at sige det hele for rådet på Storebro efter midnat.`,`{npc3} gives the heroes the spare key to the water gate, which {villain} knows nothing about, and promises to tell it all before the council on the Great Bridge after midnight.`),Z(`Vægteren brokker sig over fridagen, men holder på reservenøglen og vil ikke gentage et ord for rådet af frygt for at miste pladsen; heltene må dirke eller bryde låsen på vandporten.`,`The watchman grumbles about the night off but keeps the spare key and will not repeat a word before the council for fear of losing their post; the heroes must pick or break the lock on the water gate.`))],fight:!1,alternatives:[Z(`Skål med {villain}: Oldermanden røber intet, men kigger mod vinduet ud mod havnen, hver gang løbet eller pakhusene bliver nævnt. Spørger heltene lige ud om olien eller om {npc1}, er {villain} advaret, som hvis heltene var blevet fundet på trappen.`,`Drink with {villain}: the guild master gives nothing away but glances at the window toward the harbour whenever the race or the warehouses are mentioned. If the heroes ask straight out about the oil or about {npc1}, {villain} is warned, just as if they had been caught on the stair.`),Z(`Gå med i optoget: Lauget lader enhver bære en lygte. Den, der går tæt ved {villain}, ser oldermanden give ankerlygten videre på Storebro efter fem timer og glide ned til laugets båd under broen, og med en båd selv kan heltene følge efter ned ad floden.`,`Walk in the procession: the guild lets anyone carry a lantern. Whoever walks close to {villain} sees the guild master hand the anchor lantern on at the Great Bridge after five hours and slip down to the guild’s boat under the bridge, and with a boat of their own the heroes can follow down the river.`)],dmNotes:Z(`{villain} skal være svær at mistænke: varm, gavmild og elsket af lauget. Lad spillerne mærke, hvor højt byen sætter oldermanden, så beviserne kommer til at betyde noget, når de lægges frem.`,`{villain} should be hard to suspect: warm, generous and loved by the guild. Let the players feel how highly the town thinks of the guild master, so the proof matters when it is laid out.`)},{kind:`exploration`,at:`site`,present:[],title:Z(`Kajen ved pakhusene`,`The Warehouse Quay`),summary:Z([`{place} er laugets pakhuse yderst på havnekajen, og det største er det gamle pakhus af tjæret tømmer med uldlageret i stueetagen, regnskabsloftet ovenpå, en trappe op ad gavlen og vandporten nede ved floden.`,`Laugets festvagter, {boss} og nogle {foe}, holder kajen tom og viser alle væk fra det gamle pakhus, undtagen når lygteløbet starter her tre timer efter start, og kajen fyldes af løbere og tilskuere.`,`Her kan heltene finde ud af, hvor olien er, og hvordan de kommer ind i pakhuset.`],[`{place} is the guild’s row of warehouses at the far end of the harbour quay, and the largest is the old storehouse of tarred timber, with the wool store on the ground floor, the counting loft above, a stair up the gable and the water gate down at the river.`,`The guild’s festival guards, {boss} and some {foe}, keep the quay empty and turn everyone away from the old storehouse, except when the lantern race begins here three hours after the start and the quay fills with runners and onlookers.`,`Here the heroes can work out where the oil is and how to get into the storehouse.`]),readAloud:Z([`For enden af kajen ligger pakhusene i en mørk række med gavlene mod floden, og det ældste af dem hælder let mod vandet som en gammel mand, der lytter.`,`Mellem pæle med lygter står vagter med laugets blå bånd om armen og ser på alle, der kommer forbi.`,`Fra pakhusets vandside lyder vand, der klukker mod en båd, og brisen fra floden bærer en sødlig, fedtet lugt af lampeolie.`],[`At the end of the quay the warehouses stand in a dark row with their gables to the river, and the oldest leans a little toward the water like an old man listening.`,`Between posts hung with lanterns stand guards with the guild’s blue ribbon round their arms, watching everyone who passes.`,`From the river side of the storehouse comes the slap of water against a boat, and the breeze off the river carries a sweetish, greasy smell of lamp oil.`]),details:[Z(`{boss} og nogle {foe} er hyret af {villain} som laugets festvagter og har stået her siden middag, ved den store dør til det gamle pakhus og i en båd under vandporten. Foran folk trækker de ikke våben, men viser alle væk: Oldermanden har forbudt al færdsel på kajen i nat. Har {npc2} nævnt {boss}, kender heltene straks festvagterne som køberne af lygterne uden navne. Før solnedgang lugter her kun svagt af olie.`,`{boss} and some {foe} were hired by {villain} as the guild’s festival guards and have been here since noon, at the great door of the old storehouse and in a boat beneath the water gate. In public they draw no weapons, but they turn everyone away: the guild master has forbidden all traffic on the quay tonight. If {npc2} named {boss}, the heroes recognise the festival guards at once as the buyers of the nameless lanterns. Before sunset there is only a faint smell of oil here.`),Z(`Vandporten sidder lavt i pakhusets flodside og nås med båd eller ad en smal planke langs pælene. Plankerne foran er skrammede af tønder og mørke af olie, porten er nyligt smurt i hængslerne, og gennem en sprække ses tønderne mellem uldballerne, hver med laugets brændemærke og årets festmærke. I vagternes båd under porten ligger en sæk med tyve lygter uden navne, og fra solnedgang løber en tjæret lunte fra båden ind under porten. Har heltene ikke allerede regnet ud, hvad olien skal bruges til, gør lugten her det klart.`,`The water gate sits low in the river side of the storehouse and is reached by boat or along a narrow plank on the pilings. The planks in front of it are scored by casks and dark with oil, the gate’s hinges have just been greased, and through a crack the casks can be seen among the wool bales, each with the guild’s brand and this year’s festival mark. In the guards’ boat beneath the gate lies a sack of twenty nameless lanterns, and from sunset a tarred fuse runs from the boat in under the gate. If the heroes have not yet worked out what the oil is for, the smell here makes it plain.`),Z(`Vejene ind: Vandporten åbnes lydløst med vægterens reservenøgle; ellers må låsen dirkes eller brydes. Regnskabsloftet nås ad den udvendige trappe på gavlen, og døren deroppe åbnes uden en lyd med {npc1}s nøgle; ellers må den brydes, og larmen hører vagterne. Fra loftet går en lem med et hejsespil ned til uldlageret, men lemmen er låst nedefra med {villain}s nye hængelås. Er {villain} blevet advaret i Ankerhuset, står der også en vagt ved gavltrappen.`,`Ways in: the water gate opens silently with the watchman’s spare key; otherwise the lock must be picked or broken. The counting loft is reached by the outside stair on the gable, and the door up there opens without a sound with {npc1}’s key; otherwise it must be broken, and the guards hear it. From the loft a hatch with a hoist goes down to the wool store, but the hatch is locked from below with {villain}’s new padlock. If {villain} was warned at Anchor Hall, a guard stands at the gable stair as well.`),Z(`Tre timer efter start starter lygteløbet her: Kajen fyldes af løbere med lygter på stænger og hundreder af tilskuere, og i et kvarter kan ingen vagt holde nogen væk fra pakhusene. Løbet går op langs floden gennem lygtemagernes gyde til Storebro, et kvarters løb, og vinderen får lygtebærerbåndet: Efter gammel skik skal hvert hus i {town} hjælpe den, der bærer det, på Lygtenatten.`,`Three hours after the start the lantern race begins here: the quay fills with hundreds of onlookers and runners carrying lanterns on poles, and for a quarter of an hour no guard can keep anyone away from the warehouses. The race runs up along the river through the lantern makers’ lane to the Great Bridge, a quarter of an hour’s run, and the winner takes the lantern-bearer’s ribbon: by old custom every house in {town} must help whoever wears it on the Lantern Night.`)],checks:[$(`Dexterity (Stealth)`,`medium`,Z(`Heltene når gavltrappen eller planken til vandporten uden at blive set og kan gå ind i det gamle pakhus, når de vil, og overraske dem, der er derinde.`,`The heroes reach the gable stair or the plank to the water gate unseen and can enter the old storehouse whenever they choose, taking those inside by surprise.`),Z(`En vagt ser dem og kalder på {boss}, der jager dem væk fra kajen. Fra nu af er {boss} på vagt: Heltene kan ikke overraske nogen i pakhuset, og en vagt står ved gavltrappen.`,`A guard spots them and calls for {boss}, who drives them off the quay. From now on {boss} is on guard: the heroes cannot take anyone in the storehouse by surprise, and a guard stands at the gable stair.`)),$(`Dexterity (Acrobatics)`,`medium`,Z(`En helt, der løber lygteløbet, holder flammen i live gennem den jublende mængde og vinder lygtebærerbåndet. Hvor helten går i nat, følger folk efter og hjælper, og ved det gamle pakhus kan helten få en spandekæde på benene på få minutter.`,`A hero who runs the lantern race keeps the flame alive through the cheering crowd and wins the lantern-bearer’s ribbon. Wherever the hero goes tonight, people follow and help, and at the old storehouse the hero can raise a bucket chain in minutes.`),Z(`Flammen går ud i trængslen, og {npc2}s lærling vinder; helten står på Storebro med ømme fødder, et kvarter fra kajen.`,`The flame goes out in the crush, and {npc2}’s apprentice wins; the hero stands on the Great Bridge with sore feet, a quarter of an hour from the quay.`))],fight:!1,alternatives:[Z(`Kom ad vandvejen: Lej en båd ved Storebro, ti minutter ned ad floden, og læg til ved vandporten fra flodsiden, hvor vagterne på kajen ikke kan se jer; men nogle {foe} sidder i vagternes båd under porten og skal lokkes væk først, fx med larm længere nede ad kajen.`,`Come by water: hire a boat at the Great Bridge, ten minutes downstream, and land at the water gate from the river side, where the guards on the quay cannot see the heroes. But some {foe} sit in the guards’ boat beneath the gate and must be lured away first, say with a noise further down the quay.`),Z(`Brug løbet: Mens starten fylder kajen, kan heltene gå lige hen til vandporten og gavltrappen i mængden og se alt, men efter et kvarter er kajen tom igen, og den, der stadig står ved pakhuset, bliver set.`,`Use the race: while the start of the race fills the quay, the heroes can walk right up to the water gate and the gable stair in the crowd and see everything, but after a quarter of an hour the quay is empty again, and whoever is still standing by the storehouse is seen.`)],dmNotes:Z(`Kajen er stille midt i festen: Musikken kommer fra broerne længere oppe ad floden, og her er kun vagterne, vandet og lugten af olie. Sig tiden: Efter solnedgang lugter kajen af olie, fem timer og ti minutter efter start lægger laugets båd til ved vandporten med {villain}, og ved midnat tænder {boss} lunten.`,`The quay is quiet in the middle of the festival: the music comes from the bridges upstream, and here there are only the guards, the water and the smell of oil. Keep track of the time: after sunset the quay smells of oil, five hours and ten minutes after the start the guild’s boat lands at the water gate with {villain}, and at midnight {boss} lights the fuse.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:Z(`Det gamle pakhus`,`The Old Storehouse`),summary:Z([`Inde i det gamle pakhus i {place} står de tolv tønder lampeolie mellem uldballerne i stueetagen, to af dem brudt op, i olievædet halm, og en lunte løber derfra ud under vandporten til vagternes båd.`,`Ovenpå står laugets tyve regnskabsbøger på hylderne på regnskabsloftet, og en lem med et hejsespil går ned til tønderne; {boss} og nogle {foe} vogter den store dør og båden, og ti minutter efter, at optoget har nået Storebro, kommer {villain} selv og hejser bøgerne ned på tønderne.`,`Heltene skal stoppe ilden, redde bøgerne og få {villain} frem for rådet på Storebro.`],[`Inside the old storehouse at {place} the twelve casks of lamp oil stand among the wool bales on the ground floor, two of them broken open, in oil-soaked straw, and a fuse runs from them out under the water gate to the guards’ boat.`,`Upstairs the guild’s twenty ledgers stand on the shelves of the counting loft, and a hatch with a hoist goes down to the casks. {boss} and some {foe} guard the great door and the boat, and ten minutes after the procession reaches the Great Bridge, {villain} comes in person and hoists the books down onto the casks.`,`The heroes must stop the fire, save the books and bring {villain} before the council on the Great Bridge.`]),readAloud:Z([`Stueetagen er et mørke af uldballer, der lugter af får og tjære, og mellem dem glinser olien vådt på gulvbrædderne.`,`Midt mellem ballerne står en stak tønder med laugets brændemærke, og over dem sidder en lem i loftet med et hejsespil, hvis reb dingler ned over tønderne.`,`Gennem væggene høres festen langt borte, musik og latter fra broerne, og tæt ved klukker vandet mod pælene under vandporten.`],[`The ground floor is a darkness of wool bales smelling of sheep and tar, and between them the oil glistens wet on the floorboards.`,`In among the bales stands a stack of casks with the guild’s brand, and above them is a hatch in the ceiling with a hoist whose rope dangles down over the casks.`,`Through the walls the festival can be heard far off, music and laughter from the bridges, and close by, water slaps against the pilings beneath the water gate.`]),details:[Z(`{boss} og nogle {foe} er hyret af {villain} og holder pakhuset: nogle ved den store dør ud mod kajen, {boss} og resten i båden under vandporten med lunten. De kæmper for deres løn, ikke for at brænde inde, og flygter i båden, når {boss} falder. Har heltene sneget sig ind uset, kan de overraske vagterne; er {boss} advaret, venter vagterne dem.`,`{boss} and some {foe} were hired by {villain} and hold the storehouse: some at the great door onto the quay, {boss} and the rest in the boat beneath the water gate with the fuse. They fight for their pay, not to burn with the storehouse, and flee in the boat once {boss} falls. If the heroes slipped in unseen, they can take the guards by surprise; if {boss} was warned, the guards are waiting.`),Z(`Ad gavltrappen kommer heltene ind på regnskabsloftet mellem hylderne med bøgerne, ikke i uldlageret; lemmen i gulvet er låst nedefra, til {villain} kommer, så tønderne nås ellers kun ad vandporten. Før solnedgang er alle tønderne endnu lukkede, og der er ingen lunte. Kommer heltene, før optoget har nået Storebro (efter 5 timer), er {villain} her ikke endnu: Bøgerne står på hylderne, lemmen er låst, og laugets båd lægger først til ved vandporten ti minutter senere. Derfra går {villain} op ad stigen i uldlageret, låser lemmen op og kommer op på loftet med nøglen og en lygte i hånden; venter heltene i stilhed mellem hylderne, går {villain} lige ind i dem. Er der kamp, når båden lægger til, ror {villain} tilbage til Storebro og benægter alt; så må bøgerne og vidnerne klare resten for rådet. Fra {villain} er her, tager det en halv time at hejse bøgerne ned på tønderne, og derefter venter {villain} ved lemmen på klokkerne.`,`By the gable stair the heroes come into the counting loft among the shelves of books, not into the wool store; the hatch in the floor is locked from below until {villain} comes, so otherwise the casks can only be reached by the water gate. Before sunset all the casks are still closed and there is no fuse. If the heroes come before the procession reaches the Great Bridge (after 5 hours), {villain} is not here yet: the books stand on the shelves, the hatch is locked, and the guild’s boat does not land at the water gate until ten minutes later. From there {villain} climbs the ladder in the wool store, unlocks the hatch and comes up into the loft with the key and a lantern in hand; if the heroes wait quietly among the shelves, {villain} walks straight into them. If there is fighting when the boat lands, {villain} rows back to the Great Bridge and denies everything; then the books and the witnesses must do the rest before the council. Once {villain} is here, hoisting the books down onto the casks takes half an hour, and after that {villain} waits by the hatch for the bells.`),Z(`{villain} holder sig ved lemmen og tilbyder heltene penge, når kampen vender. Har heltene ikke {npc1}s egen forklaring på, hvordan posten blev skrevet, siger {villain}, at {npc1} skrev olien ud og stjal den. Men bøgerne viser, hvor meget uld {villain} har solgt og skrevet om til andet, og tællebrættet på væggen i uldlageret siger tre hundrede baller, hvor der står halvfems; med bøgerne, en tønde med laugets brændemærke og vidnerne er sagen klar for rådet på Storebro.`,`{villain} keeps by the hatch and offers the heroes money when the fight turns. Unless the heroes have {npc1}’s own account of how the entry was written, {villain} says that {npc1} signed the oil out and stole it. But the books show how much wool {villain} has sold and entered as something else, and the tally board on the wall of the wool store says three hundred bales where ninety stand; with the books, a cask with the guild’s brand and the witnesses, the case is clear to the council on the Great Bridge.`),Z(`Fra solnedgang ligger lunten klar: Går kampen imod {boss} før midnat, tænder {boss} den med det samme; ellers tændes den, når klokkerne ringer ved midnat. Før solnedgang er tønderne endnu lukkede, og der er ingen lunte: Går kampen da imod {boss}, flygter {boss} og resten i båden for at advare {villain} i Ankerhuset, og vender de tilbage, tager det dem en halv time at bryde to tønder op, væde halmen og lægge lunten ud igen. Lunten brænder et minut, ti runder, før den når tønderne, og kan skæres over eller trædes ud. Fænger tønderne, står stueetagen i flammer efter ti minutter og loftet efter tyve: Bøgerne kan kun reddes i de første ti minutter, ad gavltrappen; hver helt bærer fem bøger ad gangen, og hver tur tager et minut. En spandekæde fra floden slukker ilden på en halv time; med lygtebærerbåndet har en flok fra løbet fulgt heltene herned, ellers må de hente folk på broerne, et kvarter hver vej, eller en halv time, når optoget er gået. Brænder pakhuset en time, springer ilden til naboerne langs kajen.`,`From sunset the fuse lies ready: if the fight goes against {boss} before midnight, {boss} lights it at once; otherwise it is lit when the bells ring at midnight. Before sunset the casks are still closed and there is no fuse: if the fight goes against {boss} then, {boss} and the rest flee in the boat to warn {villain} at Anchor Hall, and if they come back, it takes them half an hour to break two casks open, soak the straw and lay the fuse again. The fuse burns for one minute, ten rounds, before it reaches the casks, and can be cut or stamped out. If the casks catch fire, the ground floor is ablaze within ten minutes and the loft within twenty: the books can only be saved in the first ten minutes, by the gable stair; each hero carries five books at a time, and each trip takes a minute. A bucket chain from the river puts the fire out in half an hour; if a hero wears the lantern-bearer’s ribbon, a crowd from the race has followed the heroes down here; otherwise they must fetch people from the bridges, a quarter of an hour each way, or half an hour once the procession is out. If the storehouse burns for an hour, the fire leaps to the neighbouring buildings along the quay.`)],checks:[$(`Dexterity (Acrobatics)`,`medium`,Z(`En helt når den brændende lunte, ned ad hejsespillets reb gennem den åbne lem eller rundt ad planken til vandporten, og træder den ud, før den når tønderne; pakhuset står, og bøgerne er i sikkerhed. Hver helt kan forsøge én gang i hver runde, så længe lunten brænder.`,`A hero reaches the burning fuse, down the hoist rope through the open hatch or round along the plank to the water gate, and stamps it out before it reaches the casks; the storehouse stands, and the books are safe. Each hero may try once a round while the fuse burns.`),Z(`Helten glider i olien eller bliver standset og når ikke lunten i denne runde; de andre kan prøve i de næste runder. Har lunten brændt sine ti runder, når den tønderne, og stueetagen fænger: Heltene har ti minutter til at få bøgerne ud ad gavltrappen, og uden en spandekæde er det gamle pakhus tabt.`,`The hero slips in the oil or is stopped and does not reach the fuse this round; the others can try in the rounds that follow. Once the fuse has burned its ten rounds, it reaches the casks and the ground floor catches: the heroes have ten minutes to get the books out by the gable stair, and without a bucket chain the old storehouse is lost.`)),$(`Charisma (Intimidation)`,`medium`,Z(`Med bøgerne, en tønde med brændemærket og et vidnes ord mod sig giver {villain} op, kalder vagterne af og beder om at blive ført til rådet i stilhed, ikke gennem mængden.`,`Faced with the books, a branded cask and a witness’s word, {villain} gives up, calls the guards off and begs to be brought to the council quietly, not through the crowd.`),Z(`{villain} råber til {boss}, at lunten skal tændes med det samme, og løber ned ad gavltrappen mod Storebro for at blive set dér, når ilden bryder ud; heltene må vælge mellem ilden og oldermanden.`,`{villain} shouts to {boss} to light the fuse at once and runs down the gable stair toward the Great Bridge, to be seen there when the fire breaks out; the heroes must choose between the fire and the guild master.`))],fight:!0,alternatives:[Z(`Gem jer på loftet, før {villain} kommer: Med {npc1}s nøgle til gavldøren kan heltene vente mellem hylderne og tage {villain}, der kommer op gennem lemmen med nøglen i hånden, før én eneste bog ligger på tønderne.`,`Hide in the loft before {villain} comes: with {npc1}’s key to the gable door, the heroes can wait among the shelves and take {villain}, coming up through the hatch with the key in hand, before a single book lies on the casks.`),Z(`Tag laugets båd ved vandporten: Uden den har {villain} ingen anden vej tilbage til Storebro end en halv time til fods gennem mængden langs kajen, og en oldermand, der løber fra et pakhus, der stinker af olie, er let at fange og svær at forklare.`,`Take the guild’s boat at the water gate: without it {villain} has no way back to the Great Bridge but half an hour on foot through the crowd along the quay, and a guild master running from a storehouse that reeks of oil is easy to catch and hard to explain.`)],dmNotes:Z(`Lad klokkerne fra broerne ringe gennem væggene, når midnat nærmer sig, og lad lygterne på floden drive forbi vandporten i et langt, gyldent bånd. Ilden er den egentlige fjende: Sig hver runde, hvor langt lunten er nået. {villain} er ingen kriger og regner med båden; tag den, og {villain} begynder at forhandle.`,`Let the bells from the bridges ring through the walls as midnight nears, and let the lanterns on the river drift past the water gate in a long golden ribbon. The fire is the real enemy: say every round how far the fuse has burned. {villain} is no fighter and is counting on the boat; take it, and {villain} starts to bargain.`)}},Lt=[t,ie,ue,ge,Se,De,Ne,ze,Ge,Ze,rt,lt,ht,bt,Et,jt],Rt=Lt.flatMap(e=>e.kernel?[e.kernel]:[]),zt=Object.fromEntries(Lt.flatMap(e=>e.kernel&&e.scenes?[[e.kernel.id,e.scenes]]:[]));export{Rt as MORE_KERNELS,zt as MORE_SCENES};